insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0', 'Lực lượng vũ trang có nhiệm vụ sẵn sàng chiến đấu, chiến đấu, phục vụ chiến đấu, bảo vệ độc lập, chủ quyền, thống nhất toàn vẹn lãnh thổ của Tổ quốc, an ninh quốc gia, trật tự, an toàn xã hội; bảo vệ Nhân dân, Đảng, Nhà nước, chế độ xã hội chủ nghĩa, thành quả cách mạng; cùng toàn dân xây dựng đất nước và thực hiện nghĩa vụ quốc tế.', '{}'::text[], '{}'::text[], array['- Công việc được tổ chức bởi những người làm việc dân sự của các cơ sở chính phủ liên quan đến các vấn đề quốc phòng;', '- Thanh tra hải quan và các thành viên của biên giới hoặc các dịch vụ dân sự khác.']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1693) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('1', 'Lãnh đạo, quản lý là tên gọi chung về nghề nghiệp của những người có chức vụ; có quyền quản lý, chỉ huy, điều hành từ trung ương tới cơ sở.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2', 'Nhà chuyên môn bậc cao tiến hành nghiên cứu, áp dụng các khái niệm và lý thuyết khoa học hoặc nghệ thuật; giảng dạy có hệ thống hoặc tham gia vào bất kỳ hoạt động nào của những công việc trên. Mức độ thành thạo của hầu hết các nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng bốn và năm.', array['Tiến hành phân tích, nghiên cứu và phát triển các khái niệm, lý thuyết và phương pháp hoạt động; tư vấn hoặc áp dụng kiến ​​thức hiện có liên quan đến khoa học vật lý, toán học, kỹ thuật và công nghệ, khoa học đời sống, dịch vụ y tế và sức khỏe, khoa học xã hội và nhân văn; giảng dạy lý thuyết và thực hành của một hoặc nhiều ngành học ở các cấp học khác nhau; giảng dạy và giáo dục những người có khó khăn trong học tập hoặc nhu cầu đặc biệt; cung cấp các dịch vụ kinh doanh, pháp lý và xã hội khác nhau; sáng tạo và biểu diễn các tác phẩm nghệ thuật; hướng dẫn tâm linh; chuẩn bị bài báo và báo cáo khoa học. Nhóm này bao gồm cả việc giám sát người lao động khác.', 'Ghi chú:', 'Do sự phát triển chuyên sâu của nghề nên một số nghề phát triển đến cấp độ kỹ năng thứ năm. Một số nghề chưa có quy chuẩn cụ thể nên chỉ những nghề có quy chuẩn sẽ được đưa vào phần giải thích.']::text[], '{}'::text[], '{}'::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 157) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3', 'Nhà chuyên môn bậc trung liên kết thực hiện các nhiệm vụ kỹ thuật liên quan đến nghiên cứu và ứng dụng các khái niệm khoa học hoặc nghệ thuật và phương pháp hoạt động và các quy định của Chính phủ hoặc doanh nghiệp. Mức độ thành thạo trong hầu hết các nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ ba.', array['Thực hiện các công việc kỹ thuật liên quan đến nghiên cứu và ứng dụng các khái niệm và phương pháp hoạt động trong các lĩnh vực khoa học vật lý bao gồm kỹ thuật và công nghệ, khoa học đời sống bao gồm ngành y học và khoa học xã hội và nhân văn; khởi xướng và thực hiện các dịch vụ kỹ thuật khác nhau liên quan đến thương mại, tài chính và quản trị bao gồm quản lý luật pháp và các quy định của Chính phủ và công tác xã hội; cung cấp hỗ trợ kỹ thuật cho nghệ thuật và giải trí; tham gia các hoạt động thể thao; thực hiện một số nhiệm vụ tôn giáo. Nhóm này bao gồm cả việc giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 771) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4', null, '{}'::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1142) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5', 'Nhân viên dịch vụ và bán hàng cung cấp các dịch vụ cá nhân và bảo vệ liên quan đến du lịch, quản gia, phục vụ ăn uống, chăm sóc cá nhân, bảo vệ chống cháy nổ và các hành vi trái pháp luật; bán hàng hóa trong các cửa hàng bán buôn hoặc bán lẻ và các cơ sở tương tự cũng như tại các quầy hàng và trên thị trường. Hiệu suất thành thạo trong các nghề ở nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Tổ chức và cung cấp dịch vụ du lịch; quản gia; chuẩn bị và phục vụ ăn uống; chăm sóc trẻ em; cung cấp dịch vụ chăm sóc cá nhân và sức khỏe cơ bản ở nhà hoặc ở các cơ sở, chăm sóc tóc, làm đẹp; xem bói; dịch vụ tang lễ; cung cấp dịch vụ bảo vệ cá nhân và tài sản chống lại hỏa hoạn và các hành vi trái pháp luật; thực thi pháp luật và trật tự; tạo dáng mẫu cho quảng cáo, sáng tạo và trưng bày nghệ thuật hàng hóa; bán hàng trong các cơ sở bán buôn hoặc bán lẻ cũng như ở các gian hàng và trong chợ; giới thiệu hàng hóa đến khách hàng tiềm năng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1563) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6', 'Lao động có kỹ năng trong nông nghiệp, lâm nghiệp và thủy sản trồng và thu hoạch vụ mùa hoặc cây trồng hàng năm hoặc lâu năm; thu hoạch trái cây và thực vật hoang dã; gây giống, săn bắt động vật; sản xuất các sản phẩm chăn nuôi; trồng, bảo tồn và khai thác rừng; nuôi trồng và đánh bắt thủy sản để cung cấp thực phẩm và tạo thu nhập cho bản thân và gia đình. Hiệu suất thành thạo của các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Chuẩn bị đất, máy gieo hạt, trồng, phun, bón phân và thu hoạch mùa màng; trồng cây ăn quả và cây khác; trồng rau và các sản phẩm làm vườn; thu hoạch trái cây và thực vật hoang dã; nuôi trồng, chăm sóc và săn bắn động vật chủ yếu để lấy thịt, sữa, lông, da hoặc tơ tằm, mật ong và các sản phẩm khác; nuôi trồng, bảo tồn và khai thác rừng; nuôi trồng và đánh bắt thủy sản và các hình thức thu hoạch thủy sản khác; bảo quản tại kho và sơ chế sản phẩm; bán sản phẩm đến người mua, tổ chức tiếp thị. Nhóm này bao gồm cả giám sát người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 419) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7', 'Lao động thủ công và các nghề có liên quan khác áp dụng kỹ thuật chuyên nghiệp và kiến thức cùng kỹ năng thực tế để xây dựng và bảo dưỡng công trình; định hình kim loại; lắp đặt, bảo dưỡng và sửa chữa máy móc, thiết bị hoặc dụng cụ; tiến hành công việc in ấn; sản xuất và chế biến thực phẩm, dệt may, gỗ, kim loại và các mặt hàng khác bao gồm cả hàng thủ công. Hiệu suất thành thạo của các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8', 'Thợ lắp ráp và vận hành máy móc, thiết bị vận hành và giám sát máy móc, thiết bị phục vụ nông nghiệp, công nghiệp tại chỗ hoặc bằng điều khiển từ xa; điều khiển và vận hành tàu hỏa, xe động cơ, máy móc và thiết bị di động; lắp ráp thành phẩm từ các bộ phận theo thông số và quy trình nghiêm ngặt. Hiệu suất thành thạo trong các nghề của nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9', 'Lao động giản đơn gồm những công việc đơn giản, thường xuyên có thể yêu cầu sử dụng các công cụ cầm tay và sức mạnh thể lực. Hầu hết những nghề trong nhóm này đều đòi hỏi kỹ năng ở cấp độ kỹ năng thứ nhất.', array['Dọn dẹp nhà cửa, bổ sung vật tư và thực hiện bảo trì cơ bản trong căn hộ, nhà ở, nhà bếp, khách sạn, văn phòng, các công trình khác; rửa xe ô tô, cửa sổ; phụ bếp và các việc đơn giản để sửa soạn bữa ăn; phân phát thư tín hay hàng hóa; vận chuyển hành lý và túi xách và xử lý cước phí; phục vụ tại máy bán hàng tự động, đọc và tháo đồng hồ đo nước; thu gom và phân loại rác thải; quét dọn đường phố và các khu vực tương tự; thực hiện các nhiệm vụ canh tác, câu cá, săn bắn hoặc đánh bẫy đơn giản; thực hiện các nhiệm vụ đơn giản trong khai khoáng, xây dựng và chế biến gồm phân loại sản phẩm, đóng gói, tháo dỡ sản phẩm bằng tay và chất đầy giá; cung cấp dịch vụ đường phố đa dạng; xe đạp hoặc hướng dẫn bằng tay để vận chuyển hành khách và hàng hóa; lái xe do động vật kéo hoặc có động cơ. Nhóm này bao gồm cả việc giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1089) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('01', 'Lực lượng quân đội là lực lượng nòng cốt của lực lượng vũ trang trong thực hiện nhiệm vụ quốc phòng.', array['sẵn sàng chiến đấu, chiến đấu bảo vệ Tổ quốc; thực hiện công tác vận động, tuyên truyền chủ trương, đường lối của Đảng, chính sách, pháp luật của Nhà nước; lao động sản xuất, kết hợp quốc phòng với kinh tế - xã hội, tham gia phòng thủ dân sự, cùng toàn dân xây dựng đất nước; thực hiện nghĩa vụ quốc tế.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1698) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('02', 'Công an nhân dân là lực lượng nòng cốt của lực lượng vũ trang nhân dân trong thực hiện nhiệm vụ bảo vệ an ninh quốc gia và bảo đảm trật tự, an toàn xã hội, đấu tranh phòng, chống tội phạm.', '{}'::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1719) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('03', null, '{}'::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1745) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('21', 'Nhà chuyên môn trong lĩnh vực khoa học và kỹ thuật tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động; áp dụng kiến ​​thức khoa học liên quan đến các lĩnh vực như vật lý, thiên văn học, khí tượng học, hóa học, địa vật lý, địa chất, sinh học, sinh thái học, dược học, y học, toán học, thống kê, kiến ​​trúc, kỹ thuật, thiết kế và công nghệ. Mức độ thành thạo trong hầu hết các nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng bốn và năm.', array['Tiến hành nghiên cứu, mở rộng, tư vấn hoặc áp dụng kiến ​​thức khoa học có được thông qua nghiên cứu cấu trúc và tính chất của hiện tượng vật chất, đặc tính hóa học và quá trình của các chất khác nhau, vật liệu và sản phẩm khác nhau, tất cả các hình thức của đời sống con người, động vật và thực vật, các khái niệm và phương pháp toán học và thống kê; tư vấn, thiết kế và chỉ đạo xây dựng các tòa nhà, thị trấn và hệ thống giao thông hoặc các công trình dân dụng và kết cấu công nghiệp, cũng như máy móc và các thiết bị khác; tư vấn và áp dụng các phương pháp khai thác và đảm bảo sử dụng tối ưu; khảo sát đất, biển và lập bản đồ; nghiên cứu và tư vấn về các khía cạnh công nghệ của các vật liệu, sản phẩm và quy trình cụ thể, về hiệu quả của tổ chức sản xuất và công việc; chuẩn bị bài báo và báo cáo khoa học. Nhóm này bao gồm cả việc giám sát người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 162) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('22', 'Các nhà chuyên môn về sức khỏe tiến hành nghiên cứu, cải thiện hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động; áp dụng kiến ​​thức khoa học liên quan đến y học, điều dưỡng, nha khoa, thuốc, thú y, dược phẩm, và tăng cường sức khỏe. Mức độ thành thạo của hầu hết các ngành nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng bốn và năm.', array['Tiến hành nghiên cứu và thu thập kiến ​​thức khoa học thông qua nghiên cứu các rối loạn và bệnh ở người và động vật và cách điều trị chúng; tư vấn hoặc áp dụng các biện pháp phòng ngừa và chữa bệnh, hoặc tăng cường sức khỏe; chuẩn bị bài báo và báo cáo khoa học. Nhóm này bao gồm cả việc giám sát các người lao động khác.', 'Ghi chú:', 'Việc sử dụng danh mục nghề nghiệp áp dụng trong thực tế để mô tả hoặc đo lường lực lượng lao động, cần chú ý là nhà chuyên môn về sức khỏe được phân loại trong danh mục nhiều hơn nhóm nghề 22: Nhà chuyên môn về sức khỏe. Những nghề ngoài nhóm này nhưng vẫn thuộc ngành sức khỏe bao gồm: nhà chuyên môn về cai nghiện, kỹ sư y sinh, nhà tâm lý học lâm sàng và nhà vật lý y tế.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 389) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('23', 'Nhà chuyên môn về giảng dạy lý thuyết và thực hành của một hoặc nhiều ngành học ở các cấp học khác nhau; tiến hành nghiên cứu; cải thiện hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động liên quan đến kỷ luật cụ thể của họ; và chuẩn bị các bài báo và sách học thuật. Mức độ thành thạo trong hầu hết các ngành nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng bốn và năm.', array['Thực hiện các lớp học, khóa học hoặc hướng dẫn ở cấp độ giáo dục cụ thể cho mục đích giáo dục và dạy nghề, bao gồm các bài học riêng; thực hiện chương trình xóa mù chữ cho người lớn; giảng dạy và giáo dục những người có khó khăn trong học tập hoặc nhu cầu đặc biệt; thiết kế và sửa đổi chương trình giảng dạy; kiểm tra và tư vấn về phương pháp giảng dạy và hỗ trợ; tham gia vào các quyết định liên quan đến việc tổ chức giảng dạy và các hoạt động liên quan tại các trường học và đại học; tiến hành nghiên cứu trong các môn học cụ thể để cải thiện hoặc phát triển các khái niệm, lý thuyết hoặc phương pháp hoạt động để ứng dụng trong các lĩnh vực công nghiệp và các lĩnh vực khác; chuẩn bị giấy tờ học thuật và sách. Bao gồm cả giám sát các người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 791) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('24', 'Nhà chuyên môn về kinh doanh và quản lý thực hiện các nhiệm vụ phân tích, khái niệm và thực tế để cung cấp dịch vụ trong các vấn đề tài chính, phát triển nguồn nhân lực, quan hệ công chúng, tiếp thị và bán hàng trong lĩnh vực công nghệ kỹ thuật, y tế, thông tin và truyền thông; và tiến hành đánh giá các cấu trúc tổ chức, phương pháp và hệ thống cũng như phân tích định lượng thông tin ảnh hưởng đến các chương trình đầu tư. Mức độ thành thạo trong hầu hết các ngành nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng bốn và năm.', array['Thu thập, phân tích và giải thích thông tin về khả năng tài chính, cấu trúc chi phí và hiệu quả giao dịch của các tổ chức; thực hiện kiểm toán, lập báo cáo tài chính và kiểm soát hệ thống ngân quỹ cho các tổ chức; xây dựng và xem xét các kế hoạch và chiến lược tài chính, thực hiện các lệnh mua và bán, đàm phán mua bán hàng hóa; xây dựng, triển khai và đánh giá các chương trình tuyển dụng, đào tạo và phát triển nhân viên; nghiên cứu, phát triển và thực hiện các chiến dịch tiếp thị và quan hệ công chúng; nghiên cứu và phát triển các phương pháp và chính sách để cải thiện và thúc đẩy hiệu quả và hoạt động của chính phủ và doanh nghiệp; tiếp thu và cập nhật kiến ​​thức của người sử dụng lao động và các đối thủ cạnh tranh hàng hóa và dịch vụ và các điều kiện thị trường; đánh giá nhu cầu khách hàng, giải thích và chứng minh hàng hóa và dịch vụ cho họ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1134) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('25', 'Nhà chuyên môn trong lĩnh vực Công nghệ thông tin và truyền thông tiến hành nghiên cứu; lập kế hoạch, thiết kế, viết, kiểm tra, cung cấp tư vấn và cải thiện hệ thống công nghệ thông tin, phần cứng, phần mềm và các khái niệm liên quan cho các ứng dụng cụ thể; phát triển tài liệu liên quan bao gồm các nguyên tắc, chính sách và thủ tục; thiết kế, phát triển, kiểm soát, duy trì, hỗ trợ cơ sở dữ liệu và các hệ thống thông tin khác để đảm bảo hiệu suất, tính toàn vẹn và bảo mật dữ liệu tối ưu. Mức độ thành thạo trong hầu hết các nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng bốn và năm.', array['Nghiên cứu sử dụng công nghệ thông tin trong các công việc kinh doanh; xác định các lĩnh vực để cải thiện và nghiên cứu các khía cạnh lý thuyết và phương pháp hoạt động cho việc sử dụng máy tính; đánh giá, lập kế hoạch và thiết kế cấu hình phần cứng hoặc phần mềm cho các ứng dụng cụ thể bao gồm Internet, Intranet và các hệ thống đa phương tiện; thiết kế, viết, kiểm tra và bảo trì các chương trình máy tính; thiết kế và phát triển kiến ​​trúc cơ sở dữ liệu và hệ thống quản lý cơ sở dữ liệu; phát triển và thực hiện các kế hoạch bảo mật và chính sách quản trị dữ liệu và quản trị mạng máy tính và môi trường máy tính liên quan; phân tích, phát triển, giải thích và đánh giá các thông số kỹ thuật và thiết kế hệ thống phức tạp, mô hình dữ liệu và sơ đồ trong việc phát triển, cấu hình và tích hợp các hệ thống máy tính.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 154) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('26', 'Nhà chuyên môn về luật pháp, văn hóa, xã hội tiến hành nghiên cứu; cải thiện hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động; hoặc áp dụng kiến ​​thức liên quan đến pháp luật, lưu trữ và truy xuất thông tin và đồ tạo tác, tâm lý học, phúc lợi xã hội, chính trị, kinh tế, lịch sử, tôn giáo, ngôn ngữ, xã hội học, khoa học xã hội khác, nghệ thuật và giải trí. Mức độ thành thạo của hầu hết các nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng bốn và năm.', array['Tiến hành nghiên cứu về các vấn đề pháp lý; soạn thảo luật và quy định; tư vấn cho khách hàng về các trường hợp pháp lý; bào chữa và tiến hành các vụ án tại tòa án của pháp luật; chủ tọa các thủ tục tố tụng tư pháp tại tòa án của pháp luật; phát triển và duy trì thư viện và bộ sưu tập tài liệu lưu trữ; tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động hoặc áp dụng kiến ​​thức liên quan đến lĩnh vực khoa học xã hội; quan niệm, sáng tạo và biểu diễn trong các tác phẩm văn học nghệ thuật; giải thích và truyền đạt tin tức, ý tưởng, ấn tượng và sự kiện.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 316) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('31', 'Kỹ thuật viên khoa học và kỹ thuật thực hiện các nhiệm vụ kỹ thuật kết nối với phương pháp nghiên cứu và vận hành trong khoa học và kỹ thuật. Họ giám sát và kiểm soát các khía cạnh kỹ thuật và hoạt động của khai thác, sản xuất, xây dựng và các hoạt động kỹ thuật khác; vận hành các thiết bị kỹ thuật bao gồm cả máy bay và tàu. Mức độ thành thạo trong hầu hết các nghề trong nhóm chính này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ ba.', array['Thiết lập, giám sát và vận hành các thiết bị và thiết bị, tiến hành và giám sát các thí nghiệm và kiểm tra hệ thống; thu thập và thử nghiệm mẫu; ghi lại các quan sát và phân tích dữ liệu; chuẩn bị, sửa đổi và giải thích các bản vẽ và sơ đồ kỹ thuật; điều phối, giám sát, kiểm soát và lên lịch hoạt động của các công nhân khác; vận hành và giám sát các tổng đài, hệ thống điều khiển máy tính và máy móc điều khiển quá trình đa chức năng; thực hiện các chức năng kỹ thuật để đảm bảo di chuyển và vận hành an toàn và hiệu quả trong tàu, máy bay và các thiết bị khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 774) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('32', 'Kỹ thuật viên sức khỏe thực hiện các nhiệm vụ kỹ thuật và thực tế để hỗ trợ chẩn đoán và điều trị bệnh, thương tật và suy yếu ở người và động vật; hỗ trợ các chuyên gia y tế, bác sỹ thú y, điều dưỡng và các chuyên gia y tế khác thực hiện các kế hoạch chăm sóc sức khỏe và điều trị. Mức độ thành thạo các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ ba.', array['Thử nghiệm và vận hành thiết bị hình ảnh y tế và điều trị xạ trị; thực hiện các xét nghiệm lâm sàng trên mẫu vật của dịch cơ thể và mô; chuẩn bị thuốc và các hợp chất dược phẩm khác theo hướng dẫn của dược sĩ; thiết kế, lắp đặt, bảo dưỡng và sửa chữa các thiết bị, dụng cụ y tế và nha khoa; cung cấp dịch vụ chăm sóc điều dưỡng, chăm sóc cá nhân và hộ sinh; sử dụng thảo dược và các liệu pháp khác dựa trên lý thuyết, niềm tin và kinh nghiệm bắt nguồn từ các nền văn hóa cụ thể.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1274) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('33', 'Nhân viên về kinh doanh và quản lý chủ yếu thực hiện những nhiệm vụ liên quan đến kiểm toán, tài chính, giao dịch, tính toán toán học, phát triển nguồn nhân lực, công cụ mua bán tài chính, các nhiệm vụ thư ký đặc biệt, thi hành và áp dụng các quy định chính phủ liên quan. Nghề nghiệp này cũng bao gồm những người cung cấp các dịch vụ như miễn thuế, kế hoạch hội thảo, sắp xếp việc làm, mua bán bất động sản hoặc hàng hóa cồng kềnh và quản lý nghề như vận động viên, nghệ sĩ.', array['Ghi và chuyển các đơn hàng mua, bán chứng khoán, cổ phiếu, trái phiếu và các công cụ tài chính khác và trao đổi ngoại tệ trong tương lai hoặc tức thời; trình các đơn tín dụng hoặc cho vay để quản lý với những đề xuất để thông qua hoặc từ chối; thông qua hoặc từ chối các đơn xin trong quyền hạn của mình đảm bảo rằng các tiêu chuẩn tín dụng của thể chế được coi trọng; giữ các hồ sơ hoàn chỉnh của tất cả các giao dịch tài chính theo những quy tắc chung với sự hướng dẫn của kế toán viên; hỗ trợ lên kế hoạch và thực hiện tính toán toán học, thống kê, thống kê bảo hiểm, kiểm toán và các tính toán khác có liên quan; mua và bán các công cụ tài chính.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 216) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('34', 'Nhân viên luật pháp, văn hóa, xã hội thực hiện các nhiệm vụ liên quan đến dịch vụ pháp lý, công tác xã hội, văn hóa, chuẩn bị thực phẩm, thể thao và tôn giáo.', array['Cung cấp các dịch vụ kỹ thuật và thực hành; hỗ trợ các chức năng trong quy trình pháp lý và điều tra, xã hội và cộng đồng; hỗ trợ chương trình và các hoạt động tôn giáo và văn hóa; tham gia sự kiện thể thao; phát triển và cung cấp các môn thể thao huấn luyện, tập thể dục và các chương trình giải trí; kỹ năng sáng tạo và kỹ thuật kết hợp trong một loạt các hoạt động nghệ thuật, văn hóa và ẩm thực; việc tạo ra các món ăn, thực đơn và giám sát việc chuẩn bị các bữa ăn.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 650) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('35', 'Kỹ thuật viên thông tin và truyền thông cung cấp hỗ trợ việc chạy các chương trình máy tính hàng ngày, các hệ thống truyền thông và mạng; thực hiện các công việc kỹ thuật liên quan đến viễn thông, truyền thông đại chúng, các hình ảnh và âm thanh cũng như các dạng khác của tín hiệu viễn thông trên đất liền, trên biển và trên không.', array['Cung cấp hỗ trợ người sử dụng hệ thống thông tin và truyền thông; cài đặt các chương trình và thiết bị mới; thiết lập, vận hành, duy trì mạng và các hệ thống truyền dữ liệu khác; cài đặt, giám sát và hỗ trợ các trang web internet và mạng nội bộ (intranet) hoặc phần cứng và phần mềm trang chủ; sửa đổi các trang web; thực hiện các công việc sao lưu và phục hồi trang chủ; quản lý trang thiết bị để ghi lại âm thanh, biên tập và trộn hình ảnh, âm thanh đã được ghi; quản lý, duy trì việc truyền dẫn qua các hệ thống truyền thông đại chúng và các hệ thống vệ tinh cho các chương trình đài hoặc vô tuyến; giám sát và duy trì các hệ thống truyền thông qua đài, các dịch vụ vệ tinh và các hệ thống đa công trên đất liền, trên biển và trên không; cung cấp các hỗ trợ kỹ thuật liên quan tới việc nghiên cứu và phát triển của hệ thống máy tính, phương tiện viễn thông và thử các nguyên mẫu; thiết kế và chuẩn bị thiết kế mạch theo đặc điểm kỹ thuật được đưa ra; cung cấp giám sát kỹ thuật việc sản xuất, sử dụng, duy tu và sửa chữa cho các hệ thống viễn thông.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 906) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('36', null, '{}'::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1021) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('41', 'Nhân viên tổng hợp và nhân viên làm các công việc bàn giấy ghi lại, tổ chức, lưu trữ và lấy thông tin liên quan tới các vấn đề được hỏi và thực hiện một loạt công việc hành chính và văn phòng theo các thủ tục đã được quy định.', array['Sử dụng máy tính cá nhân, máy chữ, máy xử lý văn bản, tính toán, kế toán và các máy móc văn phòng tương tự để nhập và xử lý ký tự, văn bản và dữ liệu; thực hiện các nhiệm vụ và công việc thư ký; thực hiện một loạt công việc văn phòng nói chung bao gồm: sắp xếp giấy tờ, gửi fax hoặc xử lý các thư từ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1143) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('42', 'Nhân viên dịch vụ khách hàng giao dịch với khách hàng liên quan đến các hoạt động xử lý tiền, sắp xếp chuyến đi, yêu cầu thông tin, đặt lịch hẹn, điều hành tổng đài điện thoại; phỏng vấn để khảo sát hoặc hoàn thành các ứng dụng đủ điều kiện nhận dịch vụ. Hiệu suất thành thạo trong các nghề của nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Thực hiện các hoạt động xử lý tiền trong ngân hàng, bưu điện, các cơ sở cá cược và đánh bạc; xử lý các thỏa thuận du lịch; cung cấp thông tin theo yêu cầu của khách hàng và đặt lịch hẹn; điều hành tổng đài điện thoại; chào và đón khách; phỏng vấn người trả lời khảo sát; phỏng vấn ứng viên dịch vụ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1210) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('43', 'Nhân viên ghi chép số liệu và vật liệu lưu giữ, soạn thảo và tính toán sổ sách, số liệu thống kê, tài chính và các số liệu khác, tính phí các giao dịch bằng tiền mặt liên quan đến các vấn đề tài chính. Một số nghề được liệt kê ở đây có nhiệm vụ là lưu giữ hồ sơ về hàng hóa được sản xuất, mua bán, tồn kho và gửi đi hoặc các vật liệu cần thiết được chỉ định vào ngày sản xuất; lưu giữ hồ sơ của các bộ phận hoạt động và điều phối thời gian vận chuyển hàng hóa và hành khách. Cấp độ kỹ năng trong nhóm nghề này ở cấp độ kỹ năng thứ hai.', array['Hỗ trợ hồ sơ và sổ sách kế toán; tính toán chi phí sản xuất đơn vị; tính lương và trong một số trường hợp chuẩn bị các gói lương và trả lương; tính phí các giao dịch bằng tiền mặt liên quan đến các vấn đề tài chính; thu thập, biên soạn và tính toán số liệu thống kê hoặc số liệu thống kê bảo hiểm; thực hiện các nhiệm vụ văn phòng liên quan đến các giao dịch tài chính của một tổ chức bảo hiểm, ngân hàng hoặc các tổ chức tương tự; ghi lại các hoàng hóa sản xuất, lưu trữ, đặt hàng và gửi đi; ghi lại các vật liệu nhận được, nhập kho hoặc phân phối; tính toán số lượng của vật liệu sản xuất theo yêu cầu ở những thời điểm cụ thể; hỗ trợ chuẩn bị và kiểm tra lịch trình hoạt động sản xuất; giữ hồ sơ của các bộ phận chức năng và phối hợp tính toán thời gian vận chuyển hàng hóa và hành khách.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1387) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('44', 'Nhân viên hỗ trợ văn phòng khác làm các công việc văn phòng trong các báo, tòa án, thư viện hoặc bưu điện; lưu trữ văn thư, tài liệu; chuẩn bị thông tin để xử lý; bảo quản các hồ sơ cá nhân; kiểm tra tài liệu và so sánh với các tài liệu gốc; viết thay cho những người mù chữ.', array['Lưu trữ các thông tin về mua sắm, cho mượn và trả sách thư viện; bảo quản các hồ sơ cá nhân; phân loại và sắp xếp các tài liệu, hồ sơ các loại; phân loại, ghi lại và chuyển thư từ bưu điện cũng như trong các công ty; đánh mã, sửa bản in thử; thực hiện một số công việc văn phòng khác; viết thay những người không đọc và viết được.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1486) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('51', 'Nhân viên dịch vụ cá nhân cung cấp dịch vụ cá nhân liên quan đến du lịch; quản gia; dịch vụ nhà hàng khách sạn; chăm sóc tóc và làm đẹp; huấn luyện và chăm sóc vật nuôi; dịch vụ liên quan đến cá nhân khác.', array['Tổ chức và cung cấp dịch vụ liên quan đến du lịch và thắng cảnh; quản gia; chuẩn bị và phục vụ ăn uống; làm tóc và làm đẹp; hướng dẫn lái xe cơ giới; cung cấp dịch vụ cá nhân khác. Bao gồm cả việc giám sát các nhân viên khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1566) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('52', 'Nhân viên bán hàng bán và giới thiệu hàng hóa trong các cửa hàng bán buôn hoặc bán lẻ, ở các gian hàng hoặc siêu thị, giao đến từng nhà, qua điện thoại hoặc trung tâm khách hàng. Họ có thể ghi lại và chấp nhận thanh toán hàng hóa, dịch vụ đã mua và có thể vận hành các cửa hàng bán lẻ nhỏ. Hiệu suất thành thạo trong các nghề thuộc nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Bán hàng trong các cơ sở bán buôn và bán lẻ, ở trên phố hoặc các gian hàng, giao hàng tận nơi, qua điện thoại hoặc trung tâm khách hàng; giới thiệu hàng hóa đến khách hàng tiềm năng; bán và phục vụ thức ăn dùng ngay tại quầy và trên phố; mua hoặc ký hợp đồng cung cấp thường xuyên các sản phẩm sẽ được bán; sắp xếp, hiển thị hàng hóa và đóng gói hàng hóa; xác định sản phẩm pha trộn, lưu kho và mức giá cho hàng hóa bán; dùng máy tính tiền, máy quét mã vạch, máy tính và các thiết bị khác để ghi lại và chấp nhận thanh toán cho việc mua hàng hóa và dịch vụ. Giám sát các nhân viên khác có thể được sắp xếp ở một số nghề ở đây.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 35) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('53', 'Nhân viên chăm sóc cá nhân cung cấp việc chăm sóc, hỗ trợ và giúp đỡ cho trẻ em, người bệnh, người già và người khuyết tật trong các cơ sở và khu dân cư. Hiệu suất công việc của các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Giúp đỡ đi lại, vệ sinh và các nhu cầu cá nhân khác; giúp trẻ em học các kỹ năng xã hội; hỗ trợ và tham gia các hoạt động nâng cao thể lực, phát triển cảm xúc, trí tuệ, xã hội cho trẻ em; quan sát và báo cáo các quan tâm về sức khỏe hoặc dịch vụ xã hội người lao động.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 277) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('54', 'Nhân viên dịch vụ bảo vệ bảo vệ cá nhân và tài sản khỏi hỏa hoạn và các mối nguy hiểm khác; duy trì và thực thi luật pháp và các quy định. Hiệu suất thành thạo trong các nghề ở nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Phòng cháy chữa cháy, cứu người khỏi các vụ hỏa hoạn, các tai nạn hoặc mắc kẹt trong các tình huống nguy hiểm; tuân thủ luật pháp, thực thi pháp luật và quy định, tuần tra khu vực công cộng; hướng dẫn giao thông và bảo vệ hiện trường trong trường hợp có tai nạn; tuần tra và giám sát tại chỗ để bảo vệ tài sản đối với hành vi trộm cắp và phá hoại; kiểm soát ra vào các cơ sở, giữ gìn trật tự và thực thi các quy định tại sự kiện công cộng, trong phạm vi cơ sở. Nhóm này bao gồm cả giám sát nhân viên khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 384) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('61', 'Lao động có kỹ năng trong nông nghiệp có sản phẩm chủ yếu để bán lập kế hoạch, tổ chức và thực hiện hoạt động nuôi trồng và thu hoạch cây hàng năm và lâu năm; sản xuất sản phẩm động vật và thực vật để bán hoặc phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc bán tại chợ. Hiệu suất thành thạo của các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Chuẩn bị đất, gieo hạt, trồng, phun, bón phân và thu hoạch mùa màng; trồng cây ăn quả và cây khác; trồng rau và các sản phẩm làm vườn; thu hoạch trái cây và thực vật hoang dã; nuôi và chăm sóc động vật chủ yếu để lấy thịt, sữa, lông, da hoặc tơ tằm, mật ong và các sản phẩm khác; bảo quản tại kho và sơ chế sản phẩm; bán sản phẩm đến người mua, tổ chức tiếp thị hoặc bán tại chợ. Nhóm này bao gồm cả giám sát người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 422) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('62', 'Lao động có kỹ năng trong lâm nghiệp, thủy sản và săn bắn có sản phẩm chủ yếu để bán lập kế hoạch, tổ chức và thực hiện các hoạt động canh tác, bảo tồn và khai thác rừng tự nhiên; nuôi và khai thác thủy sản; săn bắt và bẫy thú để bán hoặc phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc thị trường. Hiệu suất thành thạo trong các nghề của nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Thuê hoặc đầu tư vào thiết bị, máy móc và vật tư; lập kế hoạch và thực hiện các hoạt động lâm nghiệp, nuôi trồng thủy sản, đánh bắt và săn bắn; bảo trì trang trại, chuồng nuôi, máy móc và thiết bị khác; cung cấp hoặc tiếp thị sản phẩm; giám sát và đào tạo người lao động khác.', 'Ghi chú:', 'Các nghề được phân loại trong nhóm 61 - Lao động có kỹ năng trong nông nghiệp có sản phẩm chủ yếu để bán hoặc nhóm 62 - Lao động có kỹ năng trong lâm nghiệp, thủy sản và săn bắn có sản phẩm chủ yếu để bán nếu mục đích chính của hoạt động là sản xuất hàng hóa cho thị trường. Còn nếu sản xuất chủ yếu để tiêu dùng riêng hoặc để tiêu thụ bởi các thành viên trong gia đình thì được phân loại trong nhóm 63 - Lao động tự cung tự cấp trong nông nghiệp, lâm nghiệp và thủy sản.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 633) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('63', 'Lao động tự cung tự cấp trong nông nghiệp, lâm nghiệp và thủy sản trồng và thu hoạch vụ mùa hoặc cây và bụi cây, rau và trái cây; thu hoạch trái cây hoang dã, dược liệu và các thực vật khác; săn bắn động vật; bắt cá và các sinh vật thủy sinh khác để có được thực phẩm, nơi ở và trong một số trường hợp thu nhập tối thiểu cho bản thân và gia đình của họ. Hiệu suất thành thạo trong các nghề của nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Chuẩn bị đất; gieo hạt, trồng, chăm sóc và thu hoạch cây mùa vụ; trồng rau, trái cây và các loại cây bụi; thu nhặt trái cây hoang dã, dược liệu và các thực vật khác; chăn nuôi, chăm sóc động vật và gia cầm chủ yếu để lấy thịt, trứng, sữa, lông, da hoặc các sản phẩm khác; săn bắn hay bẫy động vật; đánh bắt cá và các loài thủy sinh khác; lấy nước và kiếm củi; lưu trữ các sản phẩm để sử dụng sau này và sơ chế sản phẩm; bảo dưỡng và duy tu nhà cửa và vật dụng; làm công cụ, quần áo và đồ dùng sử dụng trong hộ gia đình; bán hoặc trao đổi một số sản phẩm tại địa phương.', 'Ghi chú:', 'Các nghề được phân loại trong nhóm 63 - Lao động tự cung tự cấp trong nông nghiệp, lâm nghiệp và thủy sản được sản xuất chủ yếu để tiêu dùng riêng hoặc để tiêu thụ bởi các thành viên khác trong gia đình. Nếu một khoản thặng dư lớn được sản xuất và bán nhiều hàng hóa hơn tiêu thụ, nhưng mục đích chính của sản xuất là để tiêu dùng riêng nên các nghề này vẫn được phân loại trong nhóm 63. Các nghề chỉ nên được phân loại trong nhóm 61 - Lao động có kỹ năng trong nông nghiệp có sản phẩm chủ yếu để bán hoặc nhóm 62 - Lao động có kỹ năng trong lâm nghiệp, thủy sản và săn bắn có sản phẩm chủ yếu để bán nếu mục đích chính của hoạt động là sản xuất hàng hóa cho thị trường.', 'Các nghề cũng được phân loại trong nhóm 63 khi hàng hóa chỉ được sản xuất để tiêu dùng riêng hoặc tiêu dùng bởi các thành viên của hộ gia đình lao động và không có thu nhập bằng tiền mặt hoặc trao đổi.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 740) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('71', 'Lao động xây dựng và lao động có liên quan đến nghề xây dựng bảo trì và sửa chữa các tòa nhà; lắp ghép, sửa chữa nền móng, tường và các công trình xây dựng bằng gạch, đá và các nguyên vật liệu tương tự; tạo dáng khuôn mẫu, hoàn thiện đá cho các tòa nhà và cho các mục đích khác. Hiệu suất thành thạo của các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('72', 'Thợ luyện kim, cơ khí và thợ có liên quan tạo hình kim loại bằng việc đúc, hàn, rèn và phương pháp khác; lắp ráp, bảo trì và sửa chữa các cấu trúc kim loại nặng; tham gia lắp đặt, bảo dưỡng, sửa chữa công cụ và máy móc gồm cả động cơ và phương tiện; sản xuất công cụ và các vật dụng kim loại khác. Hiệu suất thành thạo trong các nghề của nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('73', 'Thợ thủ công và thợ liên quan đến in kết hợp kỹ năng nghệ thuật với thủ công để thiết kế, sản xuất, bảo dưỡng và trang trí các dụng cụ chính xác, nhạc cụ, đồ trang sức, các vật liệu quý khác, đồ gốm, sứ, thủy tinh, các mặt hàng làm từ gỗ, dệt, da và vật liệu liên quan, sản phẩm in ấn như sách, báo và tạp chí. Họ áp dụng kỹ thuật truyền thông cùng với hiện đại để khắc, đúc khuôn, lắp ráp, dệt và trang trí vật dụng khác nhau; định dạng trước khi in ấn; thiết lập và vận hành máy in; ghép nối và hoàn thiện sản phẩm in; chuẩn bị giấy và vận hành máy in. Hiệu suất thành thạo của các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('74', 'Thợ điện và thợ điện tử lắp đặt, lắp ráp, bảo trì hệ thống dây điện, máy móc, các thiết bị điện khác, hệ thống dây cáp tải và cung cấp điện, hệ thống và thiết bị điện tử, viễn thông. Hiệu suất thành thạo của các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('75', null, '{}'::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1745) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('81', 'Thợ vận hành máy móc và thiết bị giám sát và vận hành nhà xưởng, máy móc và thiết bị cố định hoặc di động. Hiệu suất thành thạo trong các nghề của nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('82', 'Thợ lắp ráp lắp ráp các bộ phận hoặc linh kiện đúc sẵn để tạo thành các cụm lắp ráp, sản phẩm và thiết bị theo quy trình đặt ra nghiêm ngặt. Các sản phẩm trên có thể được chuyển từ một công nhân sang các dây chuyền lắp ráp tiếp theo. Mức độ thành thạo trong hầu hết các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Lắp ráp các bộ phận thành nhiều loại sản phẩm và thiết bị khác nhau theo quy trình được đặt ra nghiêm ngặt; xem xét đơn đặt hàng công việc, thông số kỹ thuật, sơ đồ và bản vẽ để xác định vật liệu cần thiết và hướng dẫn lắp ráp; ghi dữ liệu sản xuất và vận hành trên các mẫu quy định; kiểm tra và thử nghiệm các thành phần lắp ráp hoàn chỉnh, lắp đặt dây và mạch điện; từ chối lắp ráp các thành phần bị lỗi.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 818) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('83', 'Lái xe và thợ vận hành thiết bị chuyển động lái xe và điều khiển xe lửa, xe cơ giới; vận hành và giám sát máy móc, thiết bị công, nông nghiệp hoặc thực hiện các nhiệm vụ trên boong tàu và các phương tiện chuyên chở bằng đường thủy khác. Hiệu suất thành thạo trong hầu hết các nghề của nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Lái xe và chăm sóc xe lửa, xe cơ giới; điều khiển, vận hành và giám sát các máy móc, thiết bị công, nông nghiệp chuyển động; thực hiện các nhiệm vụ trên boong tàu và các phương tiện chuyên chở bằng đường thủy khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 889) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('91', 'Người quét dọn và giúp việc thực hiện các công việc khác nhau trong hộ gia đình, khách sạn, văn phòng, bệnh viện và các cơ sở khác cũng như trong máy bay, tàu hỏa, xe khách, xe điện và các phương tiện tương tự để giữ cho nội thất, đồ đạc sạch sẽ; giặt, ủi quần áo bằng tay. Hầu hết các nghề trong nhóm này yêu cầu các kỹ năng ở cấp độ kỹ năng thứ nhất.', array['Quét hoặc hút bụi; rửa, đánh bóng sàn nhà, đồ nội thất và các đồ khác; gấp chăn màn và dọn giường; giúp chuẩn bị bữa ăn và dọn dẹp trong bếp; rửa xe và làm sạch cửa sổ; giặt, ủi quần áo bằng tay.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1092) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('92', 'Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản thực hiện các nhiệm vụ đơn giản và thường xuyên trong sản xuất cây trồng và vật nuôi; trồng trọt, duy trì vườn và công viên; khai thác và bảo tồn rừng; thực hiện các hoạt động khai thác và nuôi trồng thủy sản. Hầu hết các nghề trong nhóm này yêu cầu các kỹ năng ở cấp độ kỹ năng thứ nhất.', array['Đào, cào và xúc bằng dụng cụ cầm tay; bốc xếp và xếp chồng vật tư sản xuất và các vật liệu khác; tưới nước, tỉa thưa, làm cỏ và chăm sóc cây trồng bằng tay hoặc sử dụng dụng cụ cầm tay; trồng, thu hoạch, hái và thu gom sản phẩm bằng tay; cho ăn, uống nước, làm sạch động vật và giữ cho khu nhà của chúng sạch sẽ; giám sát chăn nuôi, báo cáo về tình trạng của chúng; chuẩn bị và vận hành lưới, dây chuyền, các thiết bị câu cá và boong khác; phân loại, bó và đóng gói sản phẩm vào container; thực hiện sửa chữa nhỏ trên đồ đạc, tòa nhà, thiết bị, tàu và hàng rào.', 'Ghi chú:', 'Lao động trong nông nghiệp tự cung tự cấp thực hiện một số nhiệm vụ đơn giản và thường xuyên, thường theo sự chỉ đạo của người khác được phân loại trong nhóm 920 - Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản. Lao động trong một môi trường nông nghiệp có nhiệm vụ chính là lấy nước và kiếm củi được phân loại trong nhóm 9624 - Người thu gom nước và củi.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1192) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('93', 'Lao động trong ngành khai khoáng, xây dựng, công nghiệp chế biến, chế tạo và giao thông vận tải thực hiện các nhiệm vụ thủ công đơn giản và thường xuyên trong khai thác mỏ, khai thác đá, xây dựng dân dụng, xây dựng, sản xuất, vận chuyển, lưu trữ, vận hành các phương tiện và máy móc bằng sức người hay động vật. Hầu hết các nghề trong nhóm này yêu cầu các kỹ năng ở cấp độ kỹ năng thứ nhất.', array['Đào hố và rải vật liệu như cát, đất, sỏi bằng các dụng cụ cầm tay; phân loại, xếp, dỡ, di chuyển và lưu trữ vật liệu, thiết bị, sản phẩm, vật tư, hành lý và hàng hóa bằng tay; làm sạch máy móc, thiết bị, dụng cụ và nơi làm việc; đóng, mở gói vật liệu, sản phẩm và làm đầy thùng chứa và kệ chứa sản phẩm bằng tay; vận hành các phương tiện và máy móc bằng sức người và động vật.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1315) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('94', 'Người phụ giúp chuẩn bị thực phẩm chuẩn bị và nấu các món đơn giản hoặc đặt một ít thực phẩm hoặc đồ uống đã qua chế biến, dọn bàn, phòng bếp và rửa bát. Hầu hết các nghề trong nhóm này đều yêu cầu các kỹ năng ở cấp độ kỹ năng thứ nhất.', array['- Chuẩn bị các loại thực phẩm, đồ uống đơn giản hoặc chế biến sẵn như bánh mỳ kẹp, pizza, khoai tây chiên, salad và cà phê;', '- Rửa, thái, đong và trộn thực phẩm để nấu ăn;', '- Sử dụng các thiết bị nấu nướng như lò nướng, lò vi sóng, nồi chiên…;', '- Vệ sinh phòng bếp, khu vực chuẩn bị và phục vụ đồ ăn;', '- Làm sạch các dụng cụ nấu ăn và dụng cụ dùng chung trong nhà bếp và nhà hàng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1478) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('95', 'Lao động trên đường phố và lao động có liên quan đến bán hàng (không bao gồm thực phẩm) để tiêu dùng ngay; cung cấp nhiều loại dịch vụ trên đường phố và tại các điểm công cộng khác như nhà ga. Hầu hết những nghề thuộc nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ nhất.', array['Mua hay làm đồ dùng để bán; bốc dỡ các mặt hàng để bán và vận chuyển chúng; đảm bảo vật liệu cần thiết để thực hiện dịch vụ; tiếp cận khách hàng trên đường phố để chào bán hàng hóa hoặc dịch vụ; làm sạch và đánh bóng giày; làm sạch và đánh bóng cửa kính ô tô; chạy việc vặt; hỗ trợ tài xế tìm bãi đỗ và đảm bảo xe không bị hư hỏng khi vắng mặt tài xế; phát tờ rơi và báo miễn phí; nhận thanh toán ngay.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1527) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('96', 'Người thu dọn vật thải và lao động giản đơn khác thu gom, xử lý và tái chế rác từ các tòa nhà, sân vườn, đường phố và các nơi công cộng khác. Họ giữ cho đường phố và những nơi công cộng khác sạch sẽ, gọn gàng hoặc thực hiện các công việc vặt của các cơ sở kinh doanh hoặc các hộ gia đình. Hầu hết các nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ nhất.', array['Thu gom, bốc xếp và dỡ rác thải; quét dọn đường phố, công viên và những nơi công cộng khác; bổ củi; thu gom, mang vác củi, nước, bao bì, hành lý và thư từ; đập, phủi bụi ra khỏi thảm và thực hiện các công việc lặt vặt khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1571) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('011', '- Sĩ quan Quân đội nhân dân Việt Nam (sau đây gọi chung là sĩ quan) là cán bộ của Đảng Cộng sản Việt Nam và Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam, hoạt động trong lĩnh vực quân sự, được Nhà nước phong quân hàm cấp Úy, cấp Tá, cấp Tướng.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('012', 'Hạ sĩ quan, binh sĩ lực lượng quân đội là công dân Việt Nam tham gia quân đội được phong, thăng cấp bậc hàm Thượng sĩ, Trung sĩ, Hạ sĩ, Binh nhất, Binh nhì.', '{}'::text[], '{}'::text[], array['- Công việc được tổ chức bởi những người làm việc dân sự của các cơ sở chính phủ liên quan đến các vấn đề quốc phòng;', '- Thanh tra hải quan và các thành viên của biên giới hoặc các dịch vụ dân sự khác.']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1708) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('013', 'Lực lượng khác trong quân đội bao gồm: quân nhân chuyên nghiệp, công nhân viên chức quốc phòng,...
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('021', '- Sĩ quan lực lượng công an gồm có: sĩ quan nghiệp vụ và sĩ quan chuyên môn kỹ thuật.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('022', 'Hạ sĩ quan, chiến sĩ lực lượng công an gồm có: Hạ sĩ quan nghiệp vụ, hạ sĩ quan chuyên môn kỹ thuật, hạ sĩ quan, chiến sĩ nghĩa vụ.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('023', 'Lực lượng khác trong công an như công nhân công an. Công nhân công an là công dân Việt Nam có trình độ chuyên môn kỹ thuật, được tuyển dụng vào làm việc trong Công an nhân dân mà không thuộc diện được phong cấp bậc hàm sĩ quan, hạ sĩ quan, chiến sĩ.', '{}'::text[], '{}'::text[], array['- Thanh tra hải quan và các thành viên của biên giới hoặc các dịch vụ dân sự quân đội khác;', '- Nhân viên an ninh;', '- Nhân viên dịch vụ bảo vệ khác chưa được phân vào đâu như: thám tử tư, nhân viên bảo vệ rừng,…']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1739) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('031', '- Lực lượng cơ yếu là một trong những lực lượng chuyên trách bảo vệ thông tin bí mật nhà nước, hoạt động cơ mật đặc biệt, thuộc lĩnh vực an ninh quốc gia; có chức năng tham mưu cho Đảng, Nhà nước về công tác cơ yếu, thực hiện hoạt động cơ yếu; bảo đảm tuyệt đối bí mật, an toàn, chính xác, kịp thời thông tin phục vụ sự lãnh đạo của Đảng, quản lý của Nhà nước, chỉ đạo, chỉ huy của lực lượng vũ trang nhân dân trong mọi tình huống; chủ động phòng ngừa, tham gia đấu tranh với các hoạt động mã thám gây phương hại đến an ninh quốc gia, lợi ích của Nhà nước, quyền và lợi ích hợp pháp của cơ quan, tổ chức, cá nhân.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('032', 'Lực lượng vũ trang khác bao gồm: dân quân tự vệ.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('211', 'Nhà chuyên môn về khoa học trái đất và vật lý tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động; áp dụng kiến ​​thức khoa học liên quan đến vật lý, thiên văn học, khí tượng học, hóa học, địa chất và địa vật lý.', array['Mở rộng kiến ​​thức khoa học thông qua nghiên cứu và thí nghiệm liên quan đến cơ học, nhiệt động lực học, quang học, điện, từ, điện tử, vật lý hạt nhân, thiên văn học, các ngành hóa học, điều kiện khí quyển và tính chất vật lý của trái đất; tư vấn hoặc áp dụng kiến ​​thức này trong các lĩnh vực như sản xuất, nông nghiệp, y học, điều hướng, thăm dò không gian, khai thác dầu khí, nước và khoáng sản, viễn thông và các dịch vụ khác hoặc kỹ thuật dân dụng; chuẩn bị bài báo và báo cáo khoa học.']::text[], '{}'::text[], '{}'::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 165) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('212', 'Nhà toán học, nhà thống kê tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết, mô hình toán học và thống kê; áp dụng kiến ​​thức này cho một loạt các nhiệm vụ trong các lĩnh vực như kỹ thuật, kinh doanh, xã hội và các ngành khoa học khác.', array['Nghiên cứu, cải tiến, phát triển lý thuyết và kỹ thuật toán học, tính toán và thống kê; tư vấn hoặc áp dụng các nguyên tắc, mô hình và kỹ thuật toán học cho một loạt các nhiệm vụ trong các lĩnh vực kỹ thuật, khoa học tự nhiên, xã hội hoặc đời sống; tiến hành phân tích logic các vấn đề quản lý, đặc biệt là về hiệu quả đầu vào - đầu ra và xây dựng các mô hình toán học của từng vấn đề thường được lập trình và giải bằng máy tính; thiết kế và đưa vào hoạt động các chế độ lương hưu, các loại hệ thống bảo hiểm nhân thọ, y tế, xã hội và các loại bảo hiểm khác; áp dụng toán học, thống kê, lý thuyết xác suất và rủi ro để đánh giá tác động tài chính tiềm năng của các sự kiện trong tương lai; lập kế hoạch, thiết kế bảng hỏi, tổ chức các cuộc điều tra và thu thập thống kê; đánh giá, xử lý, phân tích, giải thích dữ liệu thống kê và chuẩn bị để xuất bản; tư vấn hoặc áp dụng các phương pháp thu thập dữ liệu, các phương pháp và kỹ thuật thống kê khác nhau và xác định độ tin cậy của các kết quả, đặc biệt là trong các lĩnh vực như kinh doanh hoặc y học cũng như trong các lĩnh vực khác của khoa học tự nhiên, xã hội hoặc đời sống; chuẩn bị các bài báo và báo cáo khoa học; giám sát công việc của các trợ lý toán học, nhân viên tính toán và nhân viên thống kê.']::text[], '{}'::text[], '{}'::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 253) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('213', 'Nhà chuyên môn về khoa học sự sống áp dụng kiến thức thu được từ nghiên cứu vào đời sống của con người, động vật, thực vật và sự tương tác của chúng với nhau và môi trường để phát triển kiến thức mới, cải thiện sản xuất nông, lâm nghiệp; giải quyết các vấn đề về sức khỏe và môi trường của con người.', array['Thu thập, phân tích, đánh giá dữ liệu thực nghiệm và thực địa để xác định và phát triển các quy trình và kỹ thuật mới; cung cấp tư vấn và hỗ trợ cho chính phủ, tổ chức, doanh nghiệp về phát triển bền vững tài nguyên thiên nhiên.']::text[], '{}'::text[], '{}'::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 289) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('214', 'Nhà chuyên môn về kỹ thuật (trừ kỹ thuật điện) thiết kế, lập kế hoạch, tổ chức thử nghiệm, xây dựng, lắp đặt, bảo trì các cấu trúc, máy móc, các bộ phận của chúng cũng như các hệ thống và nhà máy sản xuất; lập kế hoạch lịch trình sản xuất và quy trình làm việc để đảm bảo các dự án kỹ thuật được thực hiện một cách an toàn, hiệu quả và tiết kiệm chi phí.', array['Lập kế hoạch, thiết kế hệ thống quy trình hóa học, dự án kỹ thuật dân dụng, thiết bị, hệ thống cơ khí, khai thác, khoan và các dự án kỹ thuật khác; xác định, giải thích các bản vẽ, kế hoạch và các biện pháp thi công; giám sát việc xây dựng các công trình, hệ thống cung cấp, vận chuyển nước và khí đốt; sản xuất, lắp đặt, vận hành, bảo trì các thiết bị, máy móc và nhà xưởng; tổ chức, quản lý lao động, cung cấp vật liệu, nhà máy và thiết bị; ước tính tổng chi phí và chuẩn bị các kế hoạch, dự toán chi tiết làm công cụ kiểm soát ngân sách; giải quyết các vấn đề thiết kế và vận hành trong các lĩnh vực kỹ thuật khác nhau thông qua ứng dụng công nghệ kỹ thuật.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 35) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('215', 'Kỹ sư kỹ thuật điện nghiên cứu, thiết kế, tư vấn, lập kế hoạch, chỉ đạo việc xây dựng, vận hành các hệ thống, linh kiện, động cơ và thiết bị điện, điện tử, viễn thông. Họ tổ chức và thiết lập các hệ thống điều khiển để giám sát hoạt động và an toàn của các hệ thống điện và điện tử.', array['Tiến hành nghiên cứu, tư vấn, chỉ đạo việc bảo trì, sửa chữa các sản phẩm và hệ thống điện, điện tử, viễn thông; tư vấn, thiết kế các trạm điện và hệ thống phát điện, truyền tải và phân phối điện; thiết lập các tiêu chuẩn kiểm soát để giám sát hoạt động và an toàn của các hệ thống và thiết bị điện, điện tử và viễn thông.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 199) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('216', 'Kiến trúc sư, nhà quy hoạch, khảo sát và thiết kế lập kế hoạch và thiết kế cảnh quan, bên ngoài và nội thất bên trong tòa nhà, các sản phẩm để sản xuất, nội dung nghe nhìn và hình ảnh để truyền thông tin. Họ tiến hành công việc khảo sát để định vị chính xác các đối tượng địa lý; thiết kế, chuẩn bị và chỉnh lý bản đồ; xây dựng và thực hiện các kế hoạch, chính sách để kiểm soát việc sử dụng đất.', array['Xác định các mục tiêu và ràng buộc của bản tóm tắt thiết kế bằng cách tham khảo ý kiến ​của khách hàng và các bên liên quan; xây dựng các khái niệm và kế hoạch thiết kế hài hòa giữa các cân nhắc thẩm mỹ với các yêu cầu kỹ thuật, chức năng, sinh thái và sản xuất; chuẩn bị các bản phác thảo, sơ đồ, hình ảnh minh họa, hình ảnh động, kế hoạch, bản đồ, biểu đồ, mẫu và mô hình để truyền đạt các khái niệm thiết kế và thông tin khác; phân tích ảnh, hình ảnh vệ tinh, tài liệu và số liệu khảo sát, bản đồ, hồ sơ, báo cáo và thống kê; thực hiện nghiên cứu và phân tích các yêu cầu về chức năng, không gian, thương mại, văn hóa, an toàn, môi trường và mỹ quan.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 256) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('221', 'Bác sĩ y khoa (bác sĩ) nghiên cứu, chẩn đoán, điều trị và phòng ngừa bệnh tật, bệnh tật, chấn thương và các khiếm khuyết về thể chất và tinh thần khác ở người thông qua việc áp dụng các nguyên tắc và quy trình của y học hiện đại. Họ lên kế hoạch, giám sát và đánh giá việc thực hiện các kế hoạch chăm sóc và điều trị của các nhà cung cấp dịch vụ chăm sóc sức khỏe khác và tiến hành các hoạt động nghiên cứu và giáo dục y tế.', array['Tiến hành kiểm tra thể chất cho bệnh nhân và phỏng vấn họ và gia đình để xác định tình trạng sức khỏe của họ; đặt hàng các xét nghiệm chẩn đoán và phân tích kết quả; kê đơn và quản lý điều trị chữa bệnh và các biện pháp phòng ngừa; thực hiện phẫu thuật và các thủ tục lâm sàng khác; theo dõi bệnh nhân tiến triển và đáp ứng với điều trị; tư vấn về sức khỏe, dinh dưỡng và hành vi lối sống hỗ trợ phòng ngừa hoặc điều trị bệnh và rối loạn; xác định và quản lý các biến chứng trước, trong và sau khi sinh con; lập kế hoạch, quản lý và thực hiện kế hoạch giới thiệu cho bệnh nhân cần các dịch vụ chăm sóc sức khỏe chuyên biệt, dài hạn hoặc khác; trao đổi thông tin y tế với các chuyên gia y tế khác để đảm bảo chăm sóc liên tục và toàn diện; báo cáo sinh, tử và các bệnh đáng chú ý cho cơ quan chính quyền; tiến hành nghiên cứu về các rối loạn và bệnh tật của con người và phương pháp phòng ngừa hoặc chữa bệnh.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 394) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('222', 'Y tá/điều dưỡng (cao cấp) và hộ sinh (cao cấp) cung cấp các dịch vụ điều trị và chăm sóc cho những người bị bệnh về thể chất hoặc tinh thần, khuyết tật hoặc ốm yếu và những người khác cần được chăm sóc do những rủi ro tiềm ẩn đối với sức khỏe bao gồm cả trước, trong và sau khi sinh. Họ chịu trách nhiệm lập kế hoạch, quản lý và đánh giá chăm sóc bệnh nhân, bao gồm cả sự giám sát của các nhân viên y tế khác, làm việc tự chủ hoặc trong các nhóm với bác sĩ y tế và những người khác trong việc áp dụng thực tế các biện pháp phòng ngừa và chữa bệnh.', array['Đánh giá, lập kế hoạch, cung cấp và đánh giá chăm sóc điều dưỡng và hộ sinh cho bệnh nhân theo thông lệ và tiêu chuẩn của điều dưỡng và hộ sinh hiện đại; phối hợp chăm sóc bệnh nhân với sự tư vấn của các chuyên gia y tế khác và các thành viên của các đội y tế; xây dựng và triển khai các kế hoạch chăm sóc, phương pháp điều trị và trị liệu, bao gồm cả quản lý thuốc; theo dõi và giảm đau và khó chịu cho bệnh nhân sử dụng nhiều phương pháp điều trị, bao gồm sử dụng thuốc giảm đau; theo dõi bệnh nhân tình trạng sức khỏe, bao gồm cả tiến triển của thai kỳ và đáp ứng với điều trị chữa bệnh; cung cấp thông tin cho bệnh nhân, gia đình và cộng đồng về một loạt các vấn đề sức khỏe, bao gồm phòng ngừa bệnh tật, điều trị và chăm sóc, mang thai và sinh nở và các chủ đề khác; giám sát và điều phối công việc của các nhân viên y tế khác; tiến hành nghiên cứu về thực hành điều dưỡng và hộ sinh và chuẩn bị các bài báo và báo cáo khoa học.', 'Ghi chú:', 'Phân biệt giữa các điều dưỡng, hộ sinh và các bác sỹ phụ tá trên cơ sở tính chất của công việc.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 468) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('223', 'Nhà chuyên môn về y học cổ truyền và hỗ trợ kiểm tra bệnh nhân, phòng ngừa và điều trị bệnh, chấn thương và các khiếm khuyết về thể chất và tinh thần khác và duy trì sức khỏe nói chung ở người bằng cách áp dụng kiến ​​thức, kỹ năng và thực hành có được thông qua nghiên cứu rộng rãi về lý thuyết, niềm tin và kinh nghiệm, bắt nguồn từ cụ thể các nền văn hóa.', array['- Tiến hành kiểm tra thể chất của bệnh nhân và phỏng vấn họ và gia đình họ để xác định tình trạng sức khỏe của họ;', '- Xây dựng và triển khai các kế hoạch điều trị cho các bệnh về thể chất, tinh thần và tâm lý xã hội bằng các ứng dụng như châm cứu, ayurvedic, vi lượng đồng căn và thảo dược;', '- Đánh giá và ghi nhận bệnh nhân tiến triển qua kế hoạch điều trị;', '- Cung cấp tư vấn về sức khỏe, dinh dưỡng và lối sống cho các cá nhân, gia đình và cộng đồng;', '- Kê đơn và pha chế các loại thuốc truyền thống như chiết xuất thảo dược, thực vật, khoáng chất và động vật, để kích thích khả năng tự chữa bệnh của cơ thể;', '- Trao đổi thông tin về bệnh nhân với các nhân viên chăm sóc sức khỏe khác khi cần thiết để đảm bảo chăm sóc sức khỏe liên tục và toàn diện;', '- Tiến hành nghiên cứu các loại thuốc và phương pháp điều trị truyền thống, bổ sung và phổ biến các phát hiện như thông qua các bài báo và báo cáo khoa học.']::text[], array['- Chuyên gia châm cứu', '- Thực hành viên y học hindu', '- Bác sĩ y học cổ truyền Trung Quốc', '- Nhà chuyên môn vi lượng đồng căn', '- Nhà chuyên môn về thiên nhiên liệu pháp', '- Thực hành viên y học Hồi giáo']::text[], array['- Người trị bệnh xương khớp - 2269', '- Kỹ thuật viên châm cứu - 3230', '- Kỹ thuật viên Hindu - 3230', '- Người trồng và bán thảo dược - 3230', '- Kỹ thuật viên bệnh lý cơ tim - 3230', '- Trị liệu nạo và uốn nắn - 3230', '- Người chữa bệnh làng - 3230', '- Thầy mo - 3230', '- Kỹ thuật viên bấm huyệt trị liệu - 3255', '- Kỹ thuật viên thủy liệu pháp - 3255', '- Kỹ thuật viên trị liệu Shiatsu - 3255', '- Người chữa lành đức tin - 3413', 'Ghi chú:', 'Nhà chuyên môn về y học cổ truyền và hỗ trợ đòi hỏi một sự hiểu biết sâu rộng về những lợi ích và các ứng dụng của y học cổ truyền và hỗ trợ, được phát triển từ những kết quả của nghiên cứu chính thức về những kỹ thuật này cũng như trên cơ thể con người và các yếu tố của y học hiện đại, được phân loại trong mã nghề 2230: Nhà chuyên môn về y học cổ truyền và hỗ trợ. Những nghề nghiệp mà thực hành đòi hỏi sự hiểu biết ít hơn dựa trên thời gian giáo dục và đào tạo chính thức hoặc không chính thức, hoặc thông qua các truyền thống và thực hành của cộng đồng nơi họ sinh sống, được bao gồm trong nhóm 3230. Kỹ thuật viên y học cổ truyền và bổ trợ. Các học viên thực hiện ứng dụng số ít các phương pháp tiếp cận với thuốc thảo dược, liệu pháp tinh thần hoặc kỹ thuật trị liệu thủ công được loại trừ khỏi nhóm 2230.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 527) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('224', 'Bác sỹ phụ tá cung cấp các dịch vụ y tế tư vấn, chẩn đoán, chữa bệnh và phòng ngừa hạn chế về phạm vi và độ phức tạp hơn so với các bác sĩ y khoa thực hiện. Họ làm việc tự chủ, hoặc có sự giám sát hạn chế của các bác sĩ y khoa và áp dụng các quy trình lâm sàng tiên tiến để điều trị và ngăn ngừa bệnh tật, thương tích và các khiếm khuyết về thể chất hoặc tinh thần khác cho cộng đồng.', array['- Tiến hành kiểm tra thể chất cho bệnh nhân và phỏng vấn họ và gia đình họ để xác định tình trạng sức khỏe của họ và ghi lại thông tin y tế của bệnh nhân;', '- Thực hiện các thủ tục y tế và phẫu thuật cơ bản hoặc thường quy hơn, bao gồm kê đơn và quản lý các phương pháp điều trị, thuốc men và các biện pháp phòng ngừa hoặc chữa bệnh khác, đặc biệt đối với các bệnh và rối loạn thông thường;', '- Quản lý hoặc đặt hàng các xét nghiệm chẩn đoán, chẳng hạn như X-quang, điện tâm đồ và xét nghiệm trong phòng thí nghiệm;', '- Thực hiện các thủ tục điều trị như tiêm, chích ngừa, khâu vết thương và chăm sóc vết thương và quản lý nhiễm trùng;', '- Hỗ trợ bác sĩ y khoa với các thủ tục phẫu thuật phức tạp;', '- Theo dõi bệnh nhân tiến triển và đáp ứng điều trị và xác định các dấu hiệu và triệu chứng cần chuyển đến bác sĩ y khoa;', '- Tư vấn cho bệnh nhân và gia đình về chế độ ăn uống, tập thể dục và các thói quen khác giúp phòng ngừa hoặc điều trị bệnh và rối loạn;', '- Xác định và chuyển các trường hợp phức tạp hoặc bất thường đến bác sĩ y tế, bệnh viện hoặc những nơi khác để được chăm sóc chuyên khoa;', '- Báo cáo sinh, tử và các bệnh đáng chú ý cho các cơ quan chính phủ để đáp ứng các yêu cầu báo cáo pháp lý và chuyên nghiệp.']::text[], array['- Bác sỹ phụ tá hồi sức', '- Bác sĩ lâm sàng (trợ y)', '- Trợ lí bác sĩ', '- Nhân viên chăm sóc chính', '- Kỹ thuật viên phẫu thuật']::text[], array['- Bác sĩ đa khoa - 2211', '- Bác sĩ phẫu thuật - 2212', '- Trợ lý y tế - 3256', '- Nhân viên cứu thương - 3258', 'Ghi chú:', 'Nghề nghiệp trong nhóm này thường yêu cầu hoàn thành đào tạo đại học trong các dịch vụ y tế lý thuyết và thực tế. Người làm việc với các dịch vụ giới hạn trong điều trị khẩn cấp và thực hành cấp cứu được phân loại trong nhóm 3258. Nhân viên cấp cứu.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 559) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('225', 'Bác sĩ thú y chẩn đoán, điều trị bệnh và phòng ngừa bệnh tật, thương tích và rối loạn chức năng của động vật. Họ có thể chăm sóc cho nhiều loại động vật hoặc chuyên điều trị một nhóm động vật cụ thể hoặc trong một lĩnh vực chuyên môn cụ thể hoặc cung cấp dịch vụ chuyên nghiệp cho các công ty thương mại sản xuất các sản phẩm sinh học và dược phẩm. Đồng thời, Bác sỹ thú y thực hiện công việc trong phòng thí nghiệm, chẩn đoán xét nghiệm vi trùng, vi rút, sử dụng kỹ thuật sinh học phân tử, nuôi cấy, phân lập xác định nguyên nhân gây bệnh; thử nghiệm bệnh động vật; xây dựng tiêu chuẩn, quy chuẩn chẩn đoán xét nghiệm bệnh động vật trên cạn và dưới nước.', array['- Xác định sự hiện diện và bản chất của các điều kiện bất thường bằng cách kiểm tra thể chất, xét nghiệm trong phòng thí nghiệm và thông qua các kỹ thuật chẩn đoán hình ảnh bao gồm chụp X-quang và siêu âm;', '- Điều trị cho động vật về mặt y tế và phẫu thuật, quản lý và kê đơn thuốc, thuốc giảm đau, thuốc gây mê nói chung và tại chỗ;', '- Thực hiện phẫu thuật, băng vết thương và đặt xương gãy;', '- Cung cấp dịch vụ sản khoa;', '- Tham gia vào các chương trình được thiết kế để ngăn chặn sự xuất hiện và lây lan của bệnh động vật;', '- Theo dõi sức khỏe động vật và tiêm phòng cho động vật theo lịch tiêm phòng;', '- Xét nghiệm các bệnh động vật, bệnh truyền nhiễm, bệnh truyền lây giữa người và động vật theo chức năng, nhiệm vụ, yêu cầu của cơ quan quản lý và người chăn nuôi;', '- Chẩn đoán bệnh động vật mới xuất hiện trên lãnh thổ Việt Nam và đề xuất các biện pháp phòng, chống dịch bệnh;', 'Thực hiện lưu giữ vi sinh vật để chẩn đoán, xác định dịch bệnh động vật theo quy định pháp luật;', '- Thực hiện mổ khám xác động vật để xác định nguyên nhân gây chết (lâm sàng) để định hướng chuẩn đoán xét nghiệm xác định nguyên nhân gây chết (xét nghiệm);', '- Tư vấn cho khách hàng về sức khỏe, dinh dưỡng và cho ăn, vệ sinh, chăn nuôi và chăm sóc động vật;', '- Cung cấp dịch vụ chẩn đoán xét nghiệm và dịch vụ khác.']::text[], array['- Nhà bệnh lý về động vật;', '- Nhà chuẩn đoán xét nghiệm bệnh động vật trong phòng thí nghiệm;', '- Bác sĩ thú y;', '- Nhà chuyên môn về dịch tễ học thú y;', '- Nhà chuyên môn thú y cộng đồng;', '- Nhà chuyên môn về kiểm dịch động vật, sản phẩm động vật trên cạn và thủy sản;', '- Nhà chuyên môn về vệ sinh thú y;', '- Nhà chuyên môn về thuốc thú y;', '- Thực tập sinh thú y;', '- Bác sĩ phẫu thuật thú y.']::text[], '{}'::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Thú y, phòng và chữa bệnh thủy sản.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 584) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('226', 'Nhà chuyên môn về sức khỏe khác cung cấp các dịch vụ y tế liên quan đến răng hàm mặt, dược phẩm, sức khỏe và vệ sinh môi trường, sức khỏe và an toàn nghề nghiệp, vật lý trị liệu, dinh dưỡng, thính giác, lời nói, thị lực và liệu pháp phục hồi chức năng. Nhóm nhỏ này bao gồm tất cả các chuyên gia sức khỏe của con người, ngoại trừ bác sĩ, bác sĩ y học cổ truyền và hỗ trợ, y tá/điều dưỡng cao cấp, nữ hộ sinh cao cấp và các chuyên gia y tế.', array['Đánh giá bệnh nhân hoặc khách hàng để xác định bản chất của rối loạn, bệnh tật hoặc vấn đề; xây dựng và triển khai các kế hoạch điều trị và đánh giá và ghi nhận bệnh nhân tiến triển; chẩn đoán và điều trị các bệnh, chấn thương và dị tật của răng, miệng, hàm và các mô liên quan; lưu trữ, bảo quản, pha chế, thử nghiệm và phân phối các sản phẩm thuốc và tư vấn về việc sử dụng đúng cách và tác dụng phụ của chúng; đánh giá, lập kế hoạch và thực hiện các chương trình để nhận biết, giám sát và kiểm soát các yếu tố môi trường có khả năng ảnh hưởng đến sức khỏe con người, cải thiện hoặc phục hồi các chức năng vận động của con người, tối đa hóa khả năng vận động, giảm các hội chứng đau hoặc tăng cường tác động của thực phẩm và dinh dưỡng đối với sức khỏe con người; chẩn đoán, quản lý và điều trị các rối loạn thể chất ảnh hưởng đến thính giác, giao tiếp hoặc nuốt, hoặc rối loạn mắt và hệ thống thị giác của con người; tư vấn cho khách hàng về việc tiếp tục điều trị và chăm sóc và cung cấp hoặc sắp xếp các dịch vụ phục hồi chức năng; giới thiệu khách hàng đến hoặc trao đổi với các chuyên gia y tế hoặc các chuyên gia liên kết khác nếu được yêu cầu.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 611) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('231', 'Giảng viên cao đẳng, đại học và cao học chuẩn bị và cung cấp các bài giảng và thực hiện các hướng dẫn trong một hoặc nhiều môn học trong một khóa học quy định tại một trường đại học hoặc tổ chức giáo dục đại học khác. Họ tiến hành nghiên cứu, chuẩn bị các bài báo và sách học thuật.', array['Thiết kế và sửa đổi chương trình giảng dạy và chuẩn bị các khóa học theo yêu cầu; chuẩn bị và cung cấp các bài giảng và thực hiện các hướng dẫn, hội thảo và thí nghiệm trong phòng thí nghiệm; kích thích thảo luận và suy nghĩ độc lập giữa các sinh viên; giám sát, khi công việc phù hợp, thực nghiệm và thực tế được thực hiện bởi sinh viên; quản lý, đánh giá và chấm bài thi, bài kiểm tra; chỉ đạo nghiên cứu của sinh viên sau đại học hoặc các thành viên khác của bộ phận; nghiên cứu và phát triển các khái niệm, lý thuyết và phương pháp hoạt động để ứng dụng trong các lĩnh vực công nghiệp và các lĩnh vực khác; chuẩn bị sách học thuật, giấy tờ hoặc bài báo; tham gia các cuộc họp của khoa, các hội nghị và hội thảo.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 794) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('232', 'Giáo viên trung cấp dạy hoặc hướng dẫn các môn học nghề nghiệp trong các cơ sở hoạt động giáo dục nghề nghiệp. Họ chuẩn bị cho học viên việc làm trong các nghề cụ thể hoặc các lĩnh vực nghề nghiệp mà thông thường không yêu cầu giáo dục đại học hoặc cao hơn.', array['- Xây dựng chương trình giảng dạy; lập kế hoạch nội dung khóa học và phương pháp giảng dạy;', '- Trình bày các bài giảng và tiến hành thảo luận để tăng cường kiến ​​thức và năng lực của học viên;', '- Giáo dục phẩm chất đạo đức nghề nghiệp và tác phong công nghiệp cho học viên thông qua quá trình giảng dạy;', '- Đánh giá kết quả học tập, kết quả thi tốt nghiệp của học viên;', '- Hoàn thiện các biểu mẫu, sổ sách quản lý lớp học được bố trí, phân công giảng dạy;', '- Hướng dẫn thực tập, thực tập kết hợp với lao động sản xuất; luyện thi cho học viên tham gia kỳ thi tay nghề các cấp; hướng dẫn học viên tham gia nghiên cứu khoa học;', '- Biên soạn giáo trình, tài liệu giảng dạy; góp ý kiến xây dựng chương trình, nội dung mô-đun, môn học được phân công giảng dạy;', '- Tham gia bồi dưỡng cho giáo viên theo yêu cầu phát triển chuyên môn, nghiệp vụ của bộ môn, khoa, cơ sở giáo dục nghề nghiệp;', '- Ứng dụng các tiến bộ khoa học kỹ thuật hoặc sáng kiến, cải tiến kỹ thuật vào giảng dạy và thực tiễn nghề nghiệp;', '- Tham gia thiết kế, xây dựng phòng học chuyên môn; thiết kế, cải tiến, tự làm đồ dùng, trang thiết bị giáo dục nghề nghiệp;', '- Tham gia sinh hoạt chuyên môn, nghiệp vụ.']::text[], array['- Giáo viên công nghệ ô tô', '- Giáo viên dạy nghề']::text[], array['- Hiệu trưởng trường đại học lớn - 1710', '- Hiệu trưởng trường đại học nhỏ - 1748', '- Hiệu trưởng trường cao đẳng - 1748', '- Giáo viên trung học - 233', '- Giáo viên dạy nghề lái xe tại các trung tâm sát hạch - 3641', 'Ghi chú:', 'Những người dạy các môn học dự định chuẩn bị cho sinh viên đi làm trong một nhóm nghề nghiệp cụ thể nên được phân loại trong nhóm 232. Giáo viên trung cấp, cho dù họ làm việc trong một trường trung học phổ thông hoặc trong một trường dạy nghề hoặc kỹ thuật. Những người dạy ở cấp giáo dục trung học, các môn như toán học không nhằm mục đích chuẩn bị cho học sinh đi làm trong một ngành nghề cụ thể, nên được phân loại trong nhóm 233. Giáo viên trung học, ngay cả khi họ được tuyển dụng trong một nghề hoặc kỹ thuật trường đại học.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 843) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('233', 'Giáo viên trung học dạy một hoặc nhiều môn học ở cấp giáo dục trung học, trừ các môn học nhằm chuẩn bị cho học sinh đi làm trong các lĩnh vực nghề nghiệp cụ thể.', array['- Thiết kế và sửa đổi chương trình giảng dạy và chuẩn bị các khóa học giáo dục theo hướng dẫn của chương trình giảng dạy;', '- Thiết lập và thực thi các quy tắc về hành vi và thủ tục để duy trì trật tự giữa các học sinh;', '- Chuẩn bị và đưa ra các bài học, thảo luận và trình diễn trong một hoặc nhiều môn học;', '- Thiết lập các mục tiêu rõ ràng cho tất cả các bài học, đơn vị, dự án và truyền đạt các mục tiêu đó cho học sinh;', '- Chuẩn bị tài liệu và lớp học cho các hoạt động của lớp;', '- Điều chỉnh phương pháp giảng dạy và tài liệu giảng dạy để đáp ứng nhu cầu và sở thích khác nhau của học sinh;', '- Quan sát và đánh giá hiệu suất và hành vi của học sinh;', '- Chuẩn bị, quản lý và chấm bài kiểm tra, bài tập và kiểm tra để đánh giá sự tiến bộ của học sinh;', '- Chuẩn bị các báo cáo về quá trình học của học sinh và trao đổi với các giáo viên khác và phụ huynh;', '- Tham gia các cuộc họp liên quan đến chính sách giáo dục hoặc tổ chức của trường học;', '- Lập kế hoạch, tổ chức và tham gia các hoạt động của trường như du ngoạn, sự kiện thể thao và buổi hòa nhạc.']::text[], array['- Giáo viên cấp 2', '- Giáo viên cấp 3']::text[], array['- Hiệu trưởng nhà trường - 1748', '- Giáo viên trung cấp - 2320', '- Thanh tra trường học - 2391', '- Gia sư dạy chữ - 3642', '- Giáo viên dạy toán - 2399', '- Cố vấn trường học - 2399', 'Ghi chú:', 'Những người dạy chuẩn bị cho sinh viên đi làm trong một nhóm nghề nghiệp cụ thể nên được phân loại trong nhóm 232. Giáo viên trung cấp. Những người dạy ở cấp giáo dục trung học các môn như toán học không nhằm mục đích chuẩn bị cho học sinh đi làm trong một ngành nghề cụ thể nên được phân loại trong nhóm 233. Giáo viên trung học.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 868) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('234', 'Giáo viên tiểu học và mầm non dạy một loạt các môn học ở cấp tiểu học và tổ chức các hoạt động giáo dục cho trẻ dưới tuổi tiểu học.', array['Chuẩn bị các chương trình học và hướng dẫn trong một loạt các môn học ở cấp giáo dục tiểu học, lập kế hoạch và tổ chức các hoạt động được thiết kế để tạo điều kiện cho trẻ phát triển các kỹ năng ngôn ngữ, thể chất và xã hội; chuẩn bị báo cáo. Nhóm này bao gồm cả việc giám sát người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 929) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('239', 'Nhà chuyên môn giảng dạy khác chưa được phân vào đâu tiến hành nghiên cứu và tư vấn về phương pháp giảng dạy; dạy những người có khó khăn trong học tập hoặc nhu cầu đặc biệt; dạy ngôn ngữ không phải tiếng mẹ đẻ cho việc di cư và các mục đích liên quan; cho tư nhân; dạy nghệ thuật, công nghệ thông tin và các môn học khác ngoài các hệ thống giáo dục tiểu học, trung học cơ sở và chính quy và cung cấp các dịch vụ giảng dạy khác không được phân loại ở nơi khác trong nhóm 23: Nhà chuyên môn về giảng dạy.', array['Tiến hành nghiên cứu và phát triển hoặc tư vấn về phương pháp giảng dạy, các khóa học và công cụ hỗ trợ; dạy trẻ em khuyết tật về thể chất, thanh niên hoặc người lớn hoặc những người gặp khó khăn trong học tập hoặc những người có nhu cầu đặc biệt, dạy ngôn ngữ không phải tiếng mẹ đẻ cho mục đích di cư; giảng dạy sinh viên thực hành, lý thuyết và biểu diễn âm nhạc, kịch, khiêu vũ, hình ảnh và nghệ thuật khác; phát triển, lên lịch và thực hiện các chương trình và khóa đào tạo cho người dùng công nghệ thông tin.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 959) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('241', 'Nhà chuyên môn về tài chính lập kế hoạch, phát triển, tổ chức, điều hành, đầu tư, quản lý và tiến hành phân tích định lượng của hệ thống kế toán tài chính hoặc quỹ cho các cá nhân, cơ sở và các tổ chức công cộng hoặc tư nhân.', array['Lập và tổ chức báo cáo tài chính cho một tổ chức; xem xét tài liệu tài chính của một tổ chức; tư vấn tài chính cho các cá nhân và tổ chức; chuẩn bị các báo cáo phân tích liên quan đến các phân khúc của nền kinh tế và toàn bộ nền kinh tế.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1137) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('242', 'Nhà chuyên môn về quản trị áp dụng các khái niệm và lý thuyết khác nhau liên quan đến việc cải thiện hiệu quả của các tổ chức và các cá nhân trong tổ chức.', array['Đánh giá cơ cấu của các tổ chức và đề xuất các lĩnh vực cải tiến; đảm bảo rằng các hoạt động của một tổ chức phù hợp với các mục tiêu chính sách của tổ chức; tuyển dụng, đào tạo, phát triển và tư vấn nhân sự trong một tổ chức.']::text[], '{}'::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1196) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('243', 'Nhà chuyên môn về bán hàng, tiếp thị và quan hệ công chúng lập kế hoạch, phát triển, điều phối và thực hiện các chương trình phổ biến thông tin để thúc đẩy các tổ chức, hàng hóa và dịch vụ; đại diện cho các công ty bán một loạt các hàng hóa và dịch vụ kỹ thuật, công nghiệp, y tế, dược phẩm và công nghệ thông tin.', array['Vận hành và thực hiện nghiên cứu thị trường, phân tích các phát hiện và lập kế hoạch cho các hoạt động quảng cáo, tiếp thị và quan hệ công chúng; hỗ trợ tăng trưởng và phát triển kinh doanh thông qua việc chuẩn bị và thực hiện các mục tiêu, chính sách và chương trình tiếp thị; lập kế hoạch và tổ chức các chiến dịch công khai; thẩm định và lựa chọn tài liệu được gửi bởi các nhà văn, nhiếp ảnh gia, họa sĩ minh họa và những người khác để tạo ra sự công khai thuận lợi; tiếp thu và cập nhật kiến ​​thức của người sử dụng lao động và các đối thủ cạnh tranh hàng hóa, dịch vụ và các điều kiện thị trường; đánh giá nhu cầu khách hàng, giải thích và chứng minh hàng hóa, dịch vụ cho họ; thăm các doanh nghiệp khách hàng thường xuyên và tiềm năng để thiết lập và hành động về các cơ hội tiếp thị; báo giá, đàm phán giá cả và các điều khoản tín dụng và hoàn thành hợp đồng.']::text[], '{}'::text[], '{}'::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Thương mại điện tử.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1262) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('244', 'Nhà chuyên môn điều tiết của Chính phủ quản lý, thực hiện hoặc áp dụng quy định liên quan đến chính phủ và các quy định liên quan đến biên giới quốc gia, các loại thuế và các phúc lợi xã hội; các trường hợp liên quan đến tội phạm; kiểm tra các ứng dụng cho các giấy phép hoặc ủy quyền liên quan đến du lịch, xuất khẩu và nhập khẩu của hàng hóa, thành lập doanh nghiệp, lắp dựng các tòa nhà và các hoạt động khác theo quy định của chính phủ.', array['Kiểm tra người và xe cộ du lịch và vận chuyển tài liệu và hàng hóa qua biên giới để bảo đảm thực thi pháp luật và quy định của chính phủ; kiểm tra thu nhập chịu thuế để xác định thuế phải nộp của cá nhân và các doanh nghiệp; cách kiểm tra và quyết định các ứng dụng cho phúc lợi xã hội; kiểm tra và quyết định các ứng dụng ủy quyền và giấy phép của chính phủ cần thiết để đi du lịch, xuất khẩu hoặc nhập khẩu hàng hóa, xây dựng tòa nhà, thành lập doanh nghiệp hoặc thực hiện các hoạt động khác theo quy định của chính phủ; kiểm soát ảnh hưởng của giá cả, mức lương hoặc trọng lượng và quy định; thu thập và xác minh bằng chứng; phỏng vấn các nhân chứng; phân tích tài liệu và dữ liệu máy tính. Họ có thể nhận được hướng dẫn từ các quan chức cao cấp của chính phủ hoặc người quản lý. Nhóm này bao gồm cả giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 34) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('251', 'Nhà chuyên môn về phân tích và phát triển phần mềm và ứng dụng tiến hành nghiên cứu; lập kế hoạch, thiết kế, viết, kiểm tra, cung cấp tư vấn và cải thiện hệ thống công nghệ thông tin như phần cứng, phần mềm và các ứng dụng khác để đáp ứng các yêu cầu cụ thể.', array['Nghiên cứu sử dụng công nghệ thông tin trong các chức năng kinh doanh và xác định các lĩnh vực có thể cải tiến để tối đa hóa hiệu quả; tiến hành nghiên cứu về các khía cạnh lý thuyết và phương pháp hoạt động để sử dụng máy tính; đánh giá, lập kế hoạch và thiết kế cấu hình phần cứng hoặc phần mềm cho các ứng dụng cụ thể; thiết kế, viết, kiểm tra và bảo trì các chương trình máy tính cho các yêu cầu cụ thể; đánh giá, lập kế hoạch và thiết kế các hệ thống Internet, Intranet và đa phương tiện.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 157) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('252', 'Nhà chuyên môn về cơ sở dữ liệu và mạng thiết kế, phát triển, kiểm soát, duy trì và hỗ trợ hiệu suất và bảo mật tối ưu của các hệ thống công nghệ thông tin và cơ sở hạ tầng, bao gồm cơ sở dữ liệu, phần cứng và phần mềm, mạng và hệ điều hành.', array['Thiết kế và phát triển kiến ​​trúc cơ sở dữ liệu, cấu trúc dữ liệu, từ điển và quy ước đặt tên cho các dự án hệ thống thông tin; thiết kế, xây dựng, sửa đổi, tích hợp, thực hiện và thử nghiệm hệ thống quản lý cơ sở dữ liệu; xây dựng và triển khai các kế hoạch bảo mật, chính sách quản trị dữ liệu, tài liệu và tiêu chuẩn; duy trì và quản trị mạng máy tính và môi trường máy tính liên quan; phân tích, phát triển, giải thích và đánh giá các thông số kỹ thuật và thiết kế hệ thống phức tạp, mô hình dữ liệu và sơ đồ trong việc phát triển, cấu hình và tích hợp các hệ thống máy tính.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 246) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('261', 'Nhà chuyên môn về luật tiến hành nghiên cứu và tư vấn về các vấn đề pháp lý, các vụ kiện hoặc tiến hành truy tố tại tòa án, chủ tọa các thủ tục tố tụng tư pháp tại tòa án và dự thảo luật và quy định.', array['Cung cấp cho khách hàng tư vấn pháp lý, thực hiện kinh doanh hợp pháp cho khách hàng, thay mặt và tiến hành kiện tụng khi cần thiết hoặc chủ tọa các thủ tục tố tụng tư pháp và tuyên án tại tòa án. Nhóm này bao gồm cả việc giám sát người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 319) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('262', 'Thủ thư, nhà chuyên môn về lưu trữ và giám tuyển phát triển và duy trì các bộ sưu tập tài liệu lưu trữ, thư viện, bảo tàng, phòng trưng bày nghệ thuật và các cơ sở tương tự.', array['thẩm định hoặc phát triển và tổ chức các nội dung của tài liệu lưu trữ và đồ tạo tác về lợi ích lịch sử, văn hóa và nghệ thuật, và đảm bảo an toàn và bảo quản chúng; tổ chức các bộ sưu tập và triển lãm tại bảo tàng, phòng trưng bày nghệ thuật và các cơ sở tương tự; phát triển và duy trì bộ sưu tập có hệ thống các tài liệu được ghi lại và xuất bản và cung cấp cho người dùng trong các thư viện và các tổ chức liên quan; chuẩn bị các bài báo và báo cáo học thuật; đóng góp vào nghiên cứu.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 373) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('263', 'Nhà chuyên môn về xã hội và tôn giáo tiến hành nghiên cứu; cải thiện hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động; áp dụng kiến ​​thức liên quan đến triết học, chính trị, kinh tế, xã hội học, nhân chủng học, lịch sử, tâm lý học và các ngành khoa học xã hội khác; hoặc cung cấp các dịch vụ xã hội để đáp ứng nhu cầu của các cá nhân và gia đình trong một cộng đồng.', array['Xây dựng và áp dụng các giải pháp để trình bày hoặc dự kiến ​​các vấn đề kinh tế, chính trị hoặc xã hội; nghiên cứu và phân tích các sự kiện và hoạt động trong quá khứ và truy tìm nguồn gốc và sự tiến hóa của loài người; nghiên cứu các quá trình tinh thần và hành vi của các cá nhân và các nhóm; cung cấp dịch vụ xã hội; chuẩn bị các bài báo và báo cáo học thuật. Nhóm này bao gồm cả giám sát người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 410) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('264', 'Nhà văn, nhà báo và nhà ngôn ngữ học quan niệm và tạo ra các tác phẩm văn học; giải thích và truyền đạt tin tức và các vấn đề công cộng thông qua các phương tiện truyền thông; dịch hoặc giải thích từ ngôn ngữ này sang ngôn ngữ khác.', array['Viết tác phẩm văn học; thẩm định giá trị của văn học và các tác phẩm nghệ thuật khác; thu thập thông tin về các vấn đề hiện tại và viết về chúng; nghiên cứu, điều tra, giải thích và truyền đạt tin tức và công việc thông qua báo chí, truyền hình, đài phát thanh và các phương tiện truyền thông khác; dịch tài liệu bằng văn bản từ ngôn ngữ này sang ngôn ngữ khác; đồng thời dịch từ ngôn ngữ này sang ngôn ngữ khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 549) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('265', 'Nghệ sĩ sáng tạo và trình diễn truyền đạt ý tưởng, ấn tượng và sự kiện trong một loạt các phương tiện truyền thông để đạt được hiệu ứng cụ thể; diễn giải một tác phẩm như một bản nhạc hay kịch bản để biểu diễn hoặc chỉ đạo buổi biểu diễn; tổ chức buổi thuyết trình về hiệu suất như vậy và các sự kiện truyền thông khác.', array['Hình thành và tạo ra các hình thức nghệ thuật thị giác; quan niệm và viết nhạc gốc; nghĩ ra, chỉ đạo, diễn tập và biểu diễn trong các sản phẩm âm nhạc, khiêu vũ, sân khấu và điện ảnh; đảm nhận trách nhiệm sáng tạo, tài chính và tổ chức trong việc sản xuất các chương trình truyền hình, phim và thuyết trình sân khấu; nghiên cứu kịch bản hoặc sách và chuẩn bị diễn tập diễn giải; lựa chọn và giới thiệu âm nhạc, video và các tài liệu giải trí khác để phát sóng và đưa ra thông báo thương mại và dịch vụ công cộng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 628) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('311', 'Kỹ thuật viên khoa học vật lý và kỹ thuật thực hiện các nhiệm vụ kỹ thuật để hỗ trợ nghiên cứu và ứng dụng thực tế các khái niệm, nguyên tắc và phương pháp hoạt động đặc biệt cho khoa học vật lý bao gồm các lĩnh vực như kỹ thuật, bản vẽ kỹ thuật hoặc hiệu quả kinh tế của quy trình sản xuất.', array['Đảm nhận và thực hiện các công việc kỹ thuật liên quan đến hóa học, vật lý, địa chất, khí tượng, thiên văn học, kỹ thuật hoặc bản vẽ kỹ thuật; thiết lập, vận hành và bảo trì các dụng cụ và thiết bị thí nghiệm; giám sát thí nghiệm, quan sát, tính toán và ghi lại kết quả; chuẩn bị vật liệu để thí nghiệm; tiến hành kiểm tra hệ thống; thu thập và thử nghiệm mẫu; ghi lại các quan sát và phân tích dữ liệu; chuẩn bị, sửa đổi và giải thích các bản vẽ kỹ thuật, sơ đồ nối dây, sơ đồ lắp ráp bảng mạch hoặc bản vẽ bố trí.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 777) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('312', 'Giám sát viên khai thác mỏ, sản xuất và xây dựng phối hợp, giám sát, kiểm soát và sắp xếp các hoạt động của công nhân trong các hoạt động sản xuất, khai thác và xây dựng.', array['Giám sát và điều phối các hoạt động của thương nhân, kỹ thuật viên điều khiển quá trình, vận hành máy, lắp ráp, lao động và công nhân khác; tổ chức và lập kế hoạch công việc hàng ngày; chuẩn bị dự toán, hồ sơ và báo cáo; xác định tình trạng thiếu nhân viên hoặc vật tư; đảm bảo an toàn cho người lao động; hướng dẫn và đào tạo nhân viên mới.', 'Ghi chú:', 'Các công việc được phân loại trong nhóm 312: Giám sát viên khai thác mỏ, sản xuất và xây dựng chủ yếu liên quan đến việc lập kế hoạch, tổ chức, điều phối, kiểm soát và chỉ đạo công việc được thực hiện bởi những người khác. Hầu hết thời gian lao động làm việc trong các công việc này không thực hiện các nhiệm vụ của người họ giám sát, mặc dù họ thường có nhiều kinh nghiệm trong việc thực hiện các nhiệm vụ này. Những người giám sát, ngoài việc kiểm soát chất lượng kỹ thuật của công nhân, nên được phân loại với các công nhân mà họ giám sát. Những người này thường được gọi là quản đốc.', 'Để phân biệt giữa các nhà quản lý được phân loại trong nhóm 1, người quản lý và người giám sát được phân loại trong các nhóm khác, cần lưu ý rằng cả người quản lý và người giám sát có thể lập kế hoạch, tổ chức, điều phối, kiểm soát và chỉ đạo công việc được thực hiện bởi những người khác. Ngoài ra, các nhà quản lý thường có trách nhiệm và đưa ra quyết định về: định hướng chiến lược và hoạt động chung của một đơn vị kinh doanh hoặc tổ chức (ví dụ về các loại, số lượng và chất lượng hàng hóa sẽ được sản xuất); ngân sách (chi bao nhiêu tiền và chi cho mục đích gì); và việc lựa chọn, bổ nhiệm và sa thải nhân viên. Các giám sát viên có thể cung cấp lời khuyên và trợ giúp cho các nhà quản lý về những vấn đề này, đặc biệt là liên quan đến lựa chọn và sa thải nhân viên, nhưng không có thẩm quyền đưa ra quyết định.', 'Cần lưu ý rằng đó không phải là điều kiện cần thiết mà các nhà quản lý phải chịu trách nhiệm cho cả ba định hướng chiến lược và hoạt động, ngân sách và lựa chọn nhân viên và sa thải. Mức độ tự chủ mà họ thực hiện cũng có thể khác nhau. Sự khác biệt quan trọng là các giám sát viên chỉ chịu trách nhiệm giám sát các hoạt động của các công nhân khác, trong khi các nhà quản lý có trách nhiệm chung đối với các hoạt động của một đơn vị tổ chức.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 944) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('313', 'Kỹ thuật viên kiểm soát, vận hành và điều khiển quy trình vận hành và giám sát các tổng đài, hệ thống điều khiển máy tính và máy móc điều khiển quá trình đa chức năng; duy trì các đơn vị xử lý trong sản xuất và phân phối điện, nước thải, xử lý nước thải và nhà máy xử lý chất thải, nhà máy lọc hóa chất, dầu khí và khí tự nhiên, trong chế biến kim loại và các hoạt động đa quy trình khác.', array['Vận hành bảng điều khiển điện tử hoặc máy tính từ phòng điều khiển trung tâm để giám sát và tối ưu hóa các quy trình; kiểm soát quá trình khởi động và tắt máy; vận hành và giám sát các tổng đài và thiết bị liên quan; giám sát và kiểm tra thiết bị và hệ thống để phát hiện sự cố; lấy số đọc từ biểu đồ, mét và đồng hồ đo trong khoảng thời gian thiết lập; xử lý sự cố và thực hiện hành động khắc phục khi cần thiết; duy trì hồ sơ, nhật ký và báo cáo; liên lạc với các nhân viên khác để đánh giá tình trạng vận hành thiết bị; vệ sinh và bảo trì thiết bị; giám sát nhà điều hành nhà máy và máy móc, lắp ráp và công nhân khác.', 'Ghi chú:', 'Trong một số trường hợp, công việc của các kỹ thuật viên kiểm soát quá trình có thể được kết hợp với sự giám sát của nhân viên trong các ngành nghề khác, chẳng hạn như người vận hành nhà máy, máy móc và lắp ráp. Những công việc này nên được phân loại trong nhóm 313: Kỹ thuật viên kiểm soát, vận hành và điều khiển quy trình, trừ khi sự giám sát của các công nhân khác là yếu tố chiếm ưu thế rõ ràng của công việc và các hoạt động kiểm soát quy trình tương đối đơn giản. Ví dụ, bộ điều khiển nhà máy xử lý hóa chất vận hành và giám sát các đơn vị và thiết bị xử lý hóa chất từ ​​phòng điều khiển trung tâm, đồng thời giám sát hoạt động của các nhà máy sản xuất hóa chất và vận hành máy, nên được phân loại trong nhóm 3133: Kiểm soát viên nhà máy xử lý hóa chất. Tuy nhiên, một giám sát viên của lao động lắp ráp, người cũng chịu trách nhiệm khởi động và tắt dây chuyền lắp ráp tự động một phần được phân loại trong nhóm 3122: Giám sát viên sản xuất.', 'Người vận hành nhà máy và máy móc quy trình đơn lẻ, hoặc máy móc không liên quan đến điều khiển tự động nhiều quy trình, không được bao gồm trong nhóm 313: Kỹ thuật viên kiểm soát, vận hành và điều khiển quy trình. Những nghề nghiệp này chủ yếu được phân loại trong nhóm 8: Thợ lắp ráp và vận hành máy móc, thiết bị.', 'Tất cả các thợ vận hành nhà máy khai thác được phân loại trong nhóm 811: Thợ vận hành máy móc, thiết bị xử lý khai khoáng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1003) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('314', 'Kỹ thuật viên khoa học sự sống và kỹ thuật viên hỗ trợ liên quan liên kết thực hiện nhiều nhiệm vụ kỹ thuật để hỗ trợ các chuyên gia khoa học sự sống với công việc nghiên cứu, phát triển, quản lý, bảo tồn và bảo vệ của họ trong các lĩnh vực như sinh học, thực vật học, động vật học, công nghệ sinh học, hóa sinh, nông nghiệp, thủy sản và lâm nghiệp.', array['Tiến hành các thử nghiệm, thí nghiệm, phân tích trong phòng thí nghiệm, nghiên cứu thực địa và khảo sát để thu thập thông tin bằng cách sử dụng các phương pháp khoa học được chấp nhận; lưu giữ hồ sơ; hỗ trợ phân tích dữ liệu và chuẩn bị báo cáo; vận hành và bảo trì thiết bị.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1110) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('315', 'Kỹ thuật viên và kiểm soát viên tàu thủy và phương tiện bay chỉ huy và điều hướng tàu và máy bay; thực hiện các chức năng kỹ thuật để đảm bảo vận hành an toàn và hiệu quả; phát triển hệ thống điều khiển không khí điện, cơ điện và máy vi tính.', array['Điều khiển hoạt động của các thiết bị cơ khí, điện và điện tử trên tàu hoặc trên máy bay, chỉ huy và điều hướng tàu hoặc máy bay, chỉ đạo các chuyển động của tàu hoặc máy bay và phát triển hệ thống điều khiển không khí điện, cơ điện và máy tính.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1192) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('321', 'Kỹ thuật viên y tế và dược thực hiện các nhiệm vụ kỹ thuật để hỗ trợ chẩn đoán và điều trị bệnh, thương tật và ốm yếu.', array['Kiểm tra và vận hành X-quang, siêu âm và các thiết bị hình ảnh y tế khác; quản lý dược phẩm phóng xạ hoặc xạ trị cho bệnh nhân để phát hiện hoặc điều trị bệnh; thực hiện các xét nghiệm lâm sàng trên mẫu vật của dịch cơ thể và mô; chuẩn bị thuốc và các hợp chất dược phẩm khác theo hướng dẫn của dược sĩ; thiết kế, lắp đặt, bảo dưỡng và sửa chữa các thiết bị, dụng cụ y tế và nha khoa.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1277) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('322', null, '{}'::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1374) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('323', 'Kỹ thuật viên y học cổ truyền và bổ trợ ngăn ngừa, chăm sóc và điều trị thể chất và tinh thần, rối loạn và tổn thương của con người bằng cách sử dụng thảo dược và các liệu pháp khác dựa trên lý thuyết, niềm tin và kinh nghiệm có nguồn gốc từ nền văn hóa cụ thể. Họ sử dụng liệu pháp kỹ thuật cổ truyền và dược phẩm, hoạt động độc lập hoặc theo kế hoạch chăm sóc thiết lập bởi nhà chuyên môn về y học cổ truyền và hỗ trợ hoặc nhà chuyên môn về sức khỏe khác.', array['- Kiểm tra bệnh nhân, phỏng vấn họ và gia đình để xác định tình trạng sức khỏe của họ và rối loạn về thể chất hoặc tinh thần hoặc các bệnh khác;', '- Đề xuất và cung cấp việc chăm sóc và điều trị bệnh tật bằng cách sử dụng kỹ thuật và thảo dược cổ truyền chẳng hạn như vật lý trị liệu, lấy máu sử dụng mạch tự nhiên, sử dụng các loại thảo mộc, cây, côn trùng và chất chiết xuất từ động vật;', '- Quản lý các phương pháp điều trị như châm cứu, khoa học ayurvedic, liệu pháp vi lượng đồng căn và thảo dược theo kế hoạch chăm sóc điều trị và các thủ tục được thiết lập bởi nhà chuyên môn về y học cổ truyền hoặc nhà chuyên môn về sức khỏe khác;', '- Cung cấp chăm sóc và điều trị các chấn thương vật lý như bị gãy, trật xương bằng cách sử dụng các phương pháp truyền thống của thao tác vật lý và các liệu pháp thảo dược;', '- Tư vấn cho cá nhân, gia đình và cộng đồng hoặc cơ sở sức khỏe, dinh dưỡng duy trì và cải thiện sức khỏe;', '- Giới thiệu bệnh nhân đến và trao đổi thông tin với nhà cung cấp chăm sóc y tế khác để đảm bảo chăm sóc toàn diện và liên tục.']::text[], array['- Kỹ thuật viên châm cứu', '- Kỹ thuật viên Ayurvedic (tên một phương pháp chữa bệnh của Ấn Độ)', '- Người nắn xương', '- Người trồng và bán thảo dược', '- Kỹ thuật viên chữa theo vi lượng đồng căn', '- Người làm giác hơi', '- Thầy lang', '- Thầy mo']::text[], array['Chuyên gia châm cứu - 2230', 'Nhà chuyên môn Ayurvedic - 2230', '- Nhà chuyên môn về thuốc bắc - 2230', '- Nhà chuyên môn vi lượng đồng căn - 2230', '- Nhà chuyên môn về thiên nhiên liệu pháp - 2230', '- Chuyên gia trị liệu thần kinh cột sống - 2269', '- Chuyên gia nắn xương - 2269', '- Hộ sinh truyền thống - 3222', '- Kỹ thuật viên vật lý trị liệu - 3255', '- Kỹ thuật viên thủy liệu pháp - 3255', '- Người chữa lành đức tin - 3413']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1418) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('324', 'Kỹ thuật viên thú y và phụ tá thực hiện tư vấn, chẩn đoán, phòng ngừa và chữa bệnh thú y với nhiệm vụ hạn chế hơn bác sĩ thú y. Họ điều trị cho động vật tại các cơ sở thú y và hỗ trợ bác sĩ thú y để thực hiện các thủ tục và phẫu thuật.', array['Tư vấn cho cộng đồng và cá nhân về việc điều trị của động vật, các bệnh và chấn thương của chúng;', 'Tiến hành kiểm tra động vật để chẩn đoán hoặc tham khảo ý kiến của bác sỹ thú y nếu cần thiết;', 'Điều trị động vật bị bệnh hay bị thương, đặc biệt là cho các bệnh thường gặp và các rối loạn;', 'Vệ sinh và khử trùng các dụng cụ và vật liệu chuẩn bị được sử dụng trong việc khám và điều trị động vật;', 'Thực hiện các nhiệm vụ kỹ thuật liên quan đến thụ tinh nhân tạo động vật;', 'Khống chế hoặc giữ động vật sẵn sàng cho khám bệnh hoặc điều trị;', 'Hỗ trợ bác sĩ thú y quản lý thuốc gây mê tại chỗ và ôxy trong thời gian điều trị;', 'Đặt động vật trong lồng để hồi phục sau phẫu thuật và giám sát tình trạng của chúng;', 'Chụp X-quang, thu thập mẫu và thực hiện các xét nghiệm khác để hỗ trợ trong chẩn đoán bệnh động vật;', 'Thực hiện các thủ thuật nha khoa động vật thường xuyên và hỗ trợ bác sĩ thú y trong nha khoa thú y.']::text[], array['Kỹ thuật viên thụ tinh nhân tạo', 'Phụ tá thú y', 'Y tá thú y', 'Kỹ thuật viên tiêm chủng thú y']::text[], array['Bác sỹ thú y - 2250', 'Nhân viên chăm sóc động vật - 5164', 'Nhân viên hỗ trợ thú y - 5164.', '(Xem tiếp Công báo số 1147 + 1148)', 'Số 1147 + 1148 Ngày 12 tháng 12 năm 2020', 'MỤC LỤC', 'VĂN BẢN QUY PHẠM PHÁP LUẬT', 'THỦ TƯỚNG CHÍNH PHỦ', 'Quyết định số 34/2020/QĐ-TTg ngày 26 tháng 11 năm 2020', 'ban hành Danh mục nghề nghiệp Việt Nam', '(Tiếp theo Công báo số 1145 + 1146)', 'Phụ lục II', 'NỘI DUNG DANH MỤC NGHỀ NGHIỆP VIỆT NAM', '(Ban hành kèm theo Quyết định số 34/2020/QĐ-TTg', 'ngày 26 tháng 11 năm 2020 của Thủ tướng Chính phủ)', '________________']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1448) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('325', 'Kỹ thuật viên sức khỏe khác thực hiện các nhiệm vụ kỹ thuật và cung cấp các dịch vụ hỗ trợ về nha khoa, quản lý hồ sơ y tế, sức khỏe cộng đồng, điều chỉnh giảm thị giác, vật lý trị liệu, sức khỏe môi trường, điều trị cấp cứu và các hoạt động khác để hỗ trợ và thúc đẩy sức khỏe con người.', array['Cung cấp dịch vụ chăm sóc cơ bản cho công tác phòng chống, điều trị bệnh và các rối loạn răng và miệng; tư vấn cho cộng đồng và cá nhân về vệ sinh, chế độ ăn uống và các biện pháp phòng ngừa khác để giảm bớt rủi ro về sức khỏe; bảo quản các hồ sơ y tế của bệnh nhân để cung cấp dữ liệu cho nghiên cứu, thanh toán, kiểm soát chi phí và cải tiến chăm sóc; hỗ trợ các gia đình để phát triển các kỹ năng cần thiết và các nguồn lực để cải thiện tình trạng sức khỏe của họ; cung cấp tư vấn về vệ sinh và vệ sinh môi trường để hạn chế sự lây lan của các bệnh truyền nhiễm; điều chỉnh ống kính quang học; điều tra việc thực hiện các quy tắc và quy định liên quan đến yếu tố môi trường và lao động có khả năng ảnh hưởng đến sức khỏe con người; xoa bóp các mô mềm của cơ thể; chỉ các bệnh nhân đến phòng khám và chuẩn bị cho họ kiểm tra; tham dự và trả lời các tai nạn,các trường hợp khẩn cấp và yêu cầu trợ giúp y tế.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 35) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('331', 'Nhân viên về toán ứng dụng và tài chính định giá các tài sản và mặt hàng khác nhau; giữ hồ sơ các giao dịch tài chính, phân tích các thông tin ứng dụng cho vay và đưa ra quyết định; mua và bán các công cụ tài chính; thực hiện tính toán toán học và tính toán có liên quan.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('332', 'Nhân viên bán hàng, mua sắm và môi giới đại diện cho công ty, chính phủ và các tổ chức khác để mua, bán hàng hóa, bảo hiểm, vận chuyển và các dịch vụ khác cho cơ sở công nghiệp, thương mại hoặc cơ sở khác hoặc đóng vai trò là đại lý độc lập để tập hợp người mua và người bán hàng hóa và dịch vụ.', array['Thu thập thông tin về hàng hóa và dịch vụ của người chủ và đối thủ cạnh tranh; giám sát và phân tích xu hướng và điều kiện thị trường; thu thập các thông tin về nhu cầu của khách hàng và xác định phù hợp với các sản phẩm và dịch vụ; giải thích và chứng minh các sản phẩm và dịch vụ cho khách hàng; đàm phán giá, hợp đồng, điều khoản, điều kiện và sắp xếp vận chuyển mua hoặc bán hàng hóa hoặc dịch vụ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 320) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('333', 'Nhân viên/đại lý dịch vụ kinh doanh thiết lập quan hệ để bán các dịch vụ kinh doanh như nơi quảng cáo trên các phương tiện thông tin, tiến hành các hoạt động miễn thuế mà cần các giấy tờ cần thiết, liên hệ người tìm việc với việc tìm người, tìm người cho các nhà tuyển dụng, sắp xếp hợp đồng cho những buổi trình diễn của vận động viên, nghệ sĩ, ca sĩ, cũng như việc phát hành sách, sản xuất kịch, thu thanh, biểu diễn, bán đĩa nhạc, lập kế hoạch và tổ chức các cuộc họp và sự kiện tương tự.', array['Thực hiện các thủ tục miễn thuế cho hàng xuất khẩu và nhập khẩu; sắp xếp và phối hợp các dịch vụ hội họp và sự kiện như trang thiết bị cuộc họp, đồ ăn uống, trang trí, trình bày, thiết bị nghe nhìn, máy tính, phòng ốc, phương tiện đi lại và các sự kiện xã hội cho người tham gia; liên hệ giữa người tìm việc và việc tìm người; tìm người cho các vị trí còn thiếu của nhà tuyển dụng; giới thiệu các bất động sản cần bán hay cho thuê đến những người mua hoặc người thuê và giải thích các điều khoản bán hàng hay điều kiện cho thuê; bán đấu giá các loại tài sản, xe hơi, vật dụng, thú nuôi, đồ nghệ thuật, nữ trang và các đồ dùng khác; sắp xếp hợp đồng cho những người biểu diễn và những buổi trình diễn.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 400) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('334', 'Thư ký hành chính và nhân viên chuyên môn khác cung cấp các dịch vụ hỗ trợ tổ chức, truyền thông và tài liệu, sử dụng kiến thức chuyên môn về hoạt động kinh doanh của tổ chức mà họ đang làm việc. Họ chịu trách nhiệm giám sát nhân viên văn phòng trong tổ chức', array['Điều phối, phân công và xem xét công việc của các nhân viên liên quan tới các nhiệm vụ sau: xử lý văn bản; lưu giữ và ghi sổ sách; vận hành điện thoại và tổng đài điện thoại; nhập số liệu; chế bản điện tử và các hoạt động liên quan đến các kỹ năng văn phòng và hành chính nói chung; chuẩn bị và xử lý các văn bản và tài liệu pháp luật như chứng thư, di chúc, bản khai có tuyên thệ và bản tóm tắt hồ sơ vụ kiện; thực hiện và hỗ trợ việc liên lạc, giao tiếp, dẫn chứng bằng tài liệu và các hoạt động điều phối quản lý nội bộ của một tổ chức, trong một số trường hợp sử dụng các kiến thức đặc biệt về hoạt động kinh doanh của tổ chức; lập kế hoạch, xác nhận các cuộc hẹn y khoa và các thông tin liên lạc cho cán bộ y tế và bệnh nhân; biên soạn, ghi lại và xem xét các biểu đồ y tế, sổ sách, báo cáo, tài liệu và thư từ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 477) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('335', 'Nhân viên điều tiết của Chính phủ quản lý, thực hiện hoặc áp dụng quy định liên quan đến chính phủ và các quy định liên quan đến biên giới quốc gia, các loại thuế và các phúc lợi xã hội; các trường hợp liên quan đến tội phạm; kiểm tra các ứng dụng cho các giấy phép hoặc ủy quyền liên quan đến du lịch, xuất khẩu và nhập khẩu của hàng hóa, thành lập doanh nghiệp, lắp dựng các tòa nhà và các hoạt động khác theo quy định của chính phủ.', array['Kiểm tra người và xe du lịch và vận chuyển tài liệu, hàng hoá qua biên giới để bảo đảm thực thi pháp luật và quy định của chính phủ; kiểm tra thu nhập chịu thuế để xác định thuế phải nộp của cá nhân và các doanh nghiệp; kiểm tra và quyết định các ứng dụng cho phúc lợi xã hội; kiểm tra và quyết định các ứng dụng ủy quyền và giấy phép của chính phủ cần thiết để đi du lịch, xuất khẩu hoặc nhập khẩu hàng hóa, xây dựng tòa nhà, thành lập doanh nghiệp hoặc thực hiện các hoạt động khác theo quy định của chính phủ; kiểm soát ảnh hưởng của giá cả, mức lương hoặc trọng lượng và quy định; thu thập và xác minh bằng chứng; phỏng vấn các nhân chứng; phân tích tài liệu và dữ liệu máy tính. Họ có thể nhận được hướng dẫn từ các quan chức cao cấp của chính phủ hoặc người quản lý. Nhóm này bao gồm cả giám sát các nhân viên khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 560) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('341', 'Nhân viên về luật pháp, xã hội và tôn giáo cung cấp dịch vụ kỹ thuật, thực hành và hỗ trợ các chức năng trong quy trình pháp lý và điều tra, chương trình hỗ trợ xã hội và cộng đồng và các hoạt động tôn giáo.', array['Trợ giúp và hỗ trợ pháp lý, công tác xã hội và tôn giáo chuyên nghiệp; thu thập và phân tích các chứng cứ, chuẩn bị các văn bản pháp luật và phục vụ các lệnh của tòa án; quản lý và triển khai thực hiện chương trình hỗ trợ xã hội và dịch vụ cộng đồng; hỗ trợ khách hàng để đối phó các vấn đề cá nhân và xã hội; hướng dẫn và hỗ trợ về đạo đức cho các cá nhân và cộng đồng; cung cấp các hỗ trợ thiết thực khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 653) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('342', 'Nhân viên về thể thao và tập luyện chuẩn bị và tham dự các sự kiện thể thao; đào tạo nam nữ vận động viên thể thao nghiệp dư và chuyên để nâng cao hiệu suất; thúc đẩy sự tham gia và các tiêu chuẩn trong thể thao; tổ chức và trọng tài sự kiện thể thao; cung cấp hướng dẫn, đào tạo và giám sát đối với các hình thức khác nhau của thể dục thể thao và các hoạt động giải trí khác.', array['Tham gia các sự kiện thể thao; tiến hành đào tạo các môn thể thao để phát triển khả năng và kiến thức của các vận động viên và người chơi thể thao; biên soạn quy tắc liên quan đến việc tiến hành các cuộc thi đấu thể thao và kiểm soát sự phát triển của những sự kiện này; lập kế hoạch, tổ chức và tiến hành các buổi thực hành; phát triển và thiết kế các chương trình thể dục; cung cấp các lớp học thể dục nhóm và học cá nhân trong một loạt các hoạt động thể dục; thúc đẩy thể thao và phát triển kỹ năng thể thao; giám sát sự tham gia của những người trẻ tuổi trong thể thao.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 734) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('343', 'Nhân viên về nghệ thuật, văn hóa và ẩm thực kết hợp kỹ năng sáng tạo, kiến thức kỹ thuật và văn hóa trong việc xử lý ảnh tĩnh; thiết kế và trang trí nhà hát, trang trí cửa hàng và các nội thất của ngôi nhà; chuẩn bị các vật dụng trình bày; bảo trì thư viện và các bộ sưu tập thư viện ảnh, hệ thống hồ sơ và hướng dẫn; tạo ra thực đơn, chuẩn bị và trình bày món ăn; cung cấp hỗ trợ cho sân khấu, điện ảnh, sản xuất truyền hình và trong các lĩnh vực khác của nghệ thuật, văn hóa.', array['Hoạt động chụp ảnh tĩnh con người, sự kiện, cảnh, vật liệu, sản phẩm và các đối tượng khác; cách áp dụng kỹ thuật nghệ thuật cho sản phẩm thiết kế, trang trí nội thất và xúc tiến bán hàng; gắn kết và chuẩn bị các đối tượng để hiển thị; thiết kế và sắp xếp nội thất triển lãm, hiển thị các trường hợp và hiển thị các khu vực; thiết kế thực đơn và giám sát việc chuẩn bị món ăn; hỗ trợ giám đốc và người biểu diễn với dàn dựng sân khấu, điện ảnh, truyền hình hoặc sản phẩm thương mại.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 801) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('351', 'Kỹ thuật viên hỗ trợ người sử dụng và vận hành công nghệ thông tin và truyền thông cung cấp hỗ trợ việc vận hành hàng ngày các hệ thống truyền thông, các hệ thống máy tính và mạng, cung cấp hỗ trợ kỹ thuật cho người sử dụng.', array['Vận hành, quản lý các thiết bị ngoại vi, các thiết bị máy tính liên quan và hệ thống giám sát các lỗi của thiết bị khi hoạt động; cài đặt các thiết bị ngoại vi như máy in với các thiết bị khác được chọn để chạy hệ điều hành hoặc giám sát việc cài đặt các thiết bị ngoại vi do các nhân viên vận hành thiết bị ngoại vi thực hiện; trả lời các câu hỏi của người sử dụng liên quan đến việc vận hành phần cứng và phần mềm để giải quyết các vấn đề phát sinh; lắp đặt và thực hiện các sửa chữa nhỏ của phần cứng, phần mềm và các thiết bị ngoại vi theo thiết kế hoặc lắp đặt các chi tiết kỹ thuật; giám sát việc vận hành hàng ngày của hệ thống; cài đặt thiết bị theo mục đích của người sử dụng; thực hiện hoặc đảm bảo việc lắp đặt đúng các dây cáp, hệ điều hành hoặc các phần mềm thích hợp; thiết lập, vận hành, bảo quản mạng và các hệ thống truyền thông dữ liệu khác; cài đặt, giám sát, hỗ trợ việc vận hành thử và tính khả dụng của các trang web Internet và Intranet hoặc các phần cứng và phần mềm trang chủ; sửa các trang web và thực hiện việc phục hồi và sao lưu trang chủ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 909) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('352', 'Kỹ thuật viên viễn thông và phát thanh truyền hình điều khiển chức năng kỹ thuật của thiết bị để ghi và chỉnh sửa hình ảnh, âm thanh và để truyền phát sóng vô tuyến và truyền hình hình ảnh, âm thanh cũng như các loại tín hiệu viễn thông khác trên đất liền, trên biển hoặc trên máy bay; thực hiện các nhiệm vụ kỹ thuật kết nối với nghiên cứu kỹ thuật viễn thông và với việc thiết kế, sản xuất, lắp ráp, xây dựng, vận hành, bảo trì và sửa chữa hệ thống viễn thông.', array['Điều khiển thiết bị để ghi lại âm thanh, chỉnh sửa và trộn các bản ghi hình ảnh và âm thanh; kiểm soát, duy trì hệ thống truyền, phát sóng và hệ thống vệ tinh cho các chương trình phát thanh và truyền hình; kiểm soát và duy trì hệ thống thông tin vô tuyến, dịch vụ vệ tinh và hệ thống ghép kênh trên bộ, trên biển hoặc trên máy bay; cung cấp hỗ trợ kỹ thuật kết nối với nghiên cứu và phát triển thiết bị viễn thông hoặc thử nghiệm các nguyên mẫu; thiết kế và chuẩn bị đồ án của mạch theo các thông số kỹ thuật đã cho; cung cấp giám sát kỹ thuật sản xuất, sử dụng, bảo trì và sửa chữa hệ thống viễn thông.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 984) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('361', 'Giáo viên tiểu học dạy một loạt các môn học ở cấp giáo dục tiểu học. Trình độ của giáo viên tiểu học ở nhóm này đòi hỏi ở trình độ trung cấp hoặc cao đẳng.', array['- Giảng dạy, giáo dục học sinh theo chương trình giáo dục, kế hoạch dạy học;', '- Tham gia phát hiện, bồi dưỡng học sinh năng khiếu, phụ đạo học sinh yếu kém;', '- Vận dụng các sáng kiến kinh nghiệm, kết quả nghiên cứu khoa học sư phạm ứng dụng vào thực tế giảng dạy, giáo dục và làm đồ dùng, thiết bị dạy học cấp tiểu học;', '- Thực hiện đổi mới phương pháp dạy học, đổi mới tổ chức lớp học, tổ chức hoạt động dạy học và đánh giá kết quả học tập theo hướng phát huy tính chủ động, tích cực, hình thành năng lực và phương pháp tự học của học sinh;', '- Làm báo cáo viên hoặc dạy minh họa ở các lớp bồi dưỡng giáo viên tiểu học hoặc dạy thử nghiệm các mô hình, phương pháp mới;', '- Hướng dẫn sinh viên thực tập;', '- Chủ trì các nội dung bồi dưỡng và sinh hoạt chuyên đề ở tổ, khối chuyên môn; viết sáng kiến kinh nghiệm; tham gia đánh giá, xét duyệt sáng kiến kinh nghiệm, đề tài nghiên cứu khoa học sư phạm ứng dụng của đồng nghiệp cấp trường trở lên;', '- Tham gia công tác kiểm tra chuyên môn, nghiệp vụ giáo viên tiểu học từ cấp trường trở lên;', '- Tham gia ban giám khảo hội thi giáo viên dạy giỏi, giáo viên chủ nhiệm giỏi, tổng phụ trách đội giỏi;', '- Tham gia tổ chức, đánh giá các hội thi của học sinh tiểu học từ cấp trường trở lên;', '- Hoàn thành các chương trình bồi dưỡng; tự học, tự bồi dưỡng trau dồi đạo đức, nâng cao năng lực chuyên môn nghiệp vụ; tham gia các hoạt động chuyên môn; tham gia phổ cập giáo dục tiểu học, xóa mù chữ;', '- Phối hợp với Đội Thiếu niên Tiền phong Hồ Chí Minh, gia đình học sinh và các tổ chức, đoàn thể liên quan để tổ chức, hướng dẫn các hoạt động giáo dục, tham gia tư vấn tâm lý học sinh tiểu học;', '- Tổ chức các hoạt động trải nghiệm sáng tạo cho học sinh;', '- Thực hiện các nhiệm vụ khác được phân công.']::text[], array['- Giáo viên tiểu học']::text[], array['- Hiệu trưởng nhà trường - 1748', '- Thanh tra trường học - 2391']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1022) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('362', 'Giáo viên mầm non thúc đẩy sự phát triển xã hội, thể chất và trí tuệ của trẻ em dưới độ tuổi tiểu học thông qua việc cung cấp các hoạt động giáo dục và vui chơi. Trình độ của giáo viên mầm non ở nhóm này đòi hỏi ở trình độ trung cấp hoặc cao đẳng.', array['- Bảo vệ an toàn tuyệt đối sức khỏe, tính mạng của trẻ trong thời gian trẻ ở nhóm (lớp) được phân công phụ trách;', '- Trực tiếp nuôi dưỡng, chăm sóc, giáo dục trẻ và chịu trách nhiệm về chất lượng chăm sóc giáo dục trẻ ở nhóm, lớp được phân công phụ trách; thực hiện công tác nuôi dưỡng, chăm sóc, giáo dục trẻ em theo Chương trình giáo dục mầm non;', '- Làm báo cáo viên hoặc dạy minh họa tại các lớp bồi dưỡng giáo viên mầm non cấp trường trở lên; hướng dẫn đồng nghiệp thực hiện chương trình và các hoạt động nuôi dưỡng, chăm sóc, giáo dục trẻ;', '- Đề xuất các nội dung bồi dưỡng và sinh hoạt chuyên đề ở tổ (khối) chuyên môn;', '- Tham gia ban giám khảo các hội thi, đánh giá sáng kiến kinh nghiệm của cấp trường trở lên;', '- Tham gia đoàn đánh giá ngoài, kiểm tra chuyên môn, nghiệp vụ sư phạm cấp trường trở lên; tham gia hướng dẫn, đánh giá thực tập sư phạm của sinh viên (nếu có);', '- Tham gia các hoạt động chuyên môn, bảo quản và sử dụng thiết bị giáo dục được giao;', '- Phối hợp với gia đình và cộng đồng trong việc nuôi dưỡng, chăm sóc, giáo dục trẻ;', '- Thực hiện các nhiệm vụ khác được phân công.']::text[], array['- Giáo viên mầm non', '- Giáo viên tiền tiểu học']::text[], array['- Giám đốc trung tâm chăm sóc trẻ em - 1748', '- Nhân viên chăm sóc trẻ em - 5311']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1044) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('363', 'Giáo viên dạy các đối tượng bị khuyết tật dạy cho trẻ em khuyết tật về thể chất hoặc tinh thần, người trưởng thành trẻ tuổi hoặc những người có khó khăn trong học tập hoặc các nhu cầu đặc biệt khác. Họ thúc đẩy sự phát triển xã hội, tình cảm, trí tuệ và thể chất của học sinh. Trình độ của giáo viên dạy các đối tượng bị khuyết tật ở nhóm này đòi hỏi ở trình độ trung cấp hoặc cao đẳng.', array['- Đánh giá khả năng và giới hạn của học sinh về các khiếm khuyết về trí tuệ, thể chất, xã hội và cảm xúc, quà tặng trí tuệ đặc biệt hoặc các tình huống đặc biệt khác;', '- Thiết kế hoặc sửa đổi chương trình giảng dạy; chuẩn bị và cung cấp các chương trình, bài học, các hoạt động phù hợp với khả năng và nhu cầu của học sinh;', '- Hướng dẫn trên cơ sở cá nhân hoặc nhóm sử dụng các kỹ thuật hoặc trợ giúp đặc biệt phù hợp với nhu cầu của học sinh;', '- Sử dụng các chiến lược và kỹ thuật giáo dục đặc biệt trong quá trình giảng dạy để cải thiện sự phát triển các kỹ năng cảm giác, nhận thức - vận động, ngôn ngữ, nhận thức và trí nhớ;', '- Thiết lập và thực thi các quy tắc để duy trì trật tự giữa các học sinh;', '- Giảng dạy các môn học thuật, các kỹ năng thực tế và tự lực cho học sinh khiếm thính, thị giác và các khiếm khuyết khác;', '- Kích thích và phát triển sở thích, sự tự tin, khả năng, kỹ năng thủ công và phối hợp của học sinh;', '- Trao đổi với các giáo viên khác để lập kế hoạch và sắp xếp các bài học cho các học sinh có nhu cầu đặc biệt;', '- Chuẩn bị và duy trì dữ liệu và các hồ sơ khác của học sinh và gửi báo cáo;', '- Quản lý các hình thức đánh giá và đánh giá tiến bộ khác nhau của mỗi học sinh;', '- Trao đổi với học sinh, phụ huynh, giáo viên chủ nhiệm và các chuyên gia có liên quan khác về các vấn đề của học sinh. Phát triển các kế hoạch giáo dục cá nhân được thiết kế để thúc đẩy học sinh phát triển.']::text[], array['- Giáo viên giáo dục đặc biệt cho người khuyết tật', '- Giáo viên hỗ trợ học tập', '- Giáo viên khắc phục khiếm khuyết', '- Giáo viên dạy trẻ khiếm thính', '- Giáo viên dạy người khiếm thị']::text[], array['- Giáo viên sơ cấp - 3641', '- Giáo viên tiểu học - 3610']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1062) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('364', null, '{}'::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1085) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('411', 'Nhân viên tổng hợp thực hiện một số nhiệm vụ hành chính và văn phòng theo các thủ tục đã được quy định.', array['Ghi chép, chuẩn bị, sắp xếp, phân loại các thông tin;', 'Sắp xếp, mở và gửi thư;', 'Sao và fax tài liệu;', 'Chuẩn bị các báo cáo công việc hàng ngày;', 'Ghi các vấn đề về thiết bị của nhân viên;', 'Trả lời điện thoại hoặc các yêu cầu qua điện tử hoặc chuyển tiếp cho những người thích hợp;', 'Ghi ghép thông tin vào máy tính, đọc sửa và hiệu đính các bản sao lưu.']::text[], array['- Nhân viên văn phòng']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1146) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('412', 'Thư ký (tổng hợp) sử dụng máy đánh chữ, máy tính cá nhân hoặc các thiết bị xử lý văn bản khác để sao chép thư từ và các tài liệu khác; kiểm tra và định dạng các tài liệu do nhân viên khác chuẩn bị; xử lý thư đến và đi; yêu cầu sàng lọc các cuộc họp hoặc cuộc hẹn và thực hiện các nhiệm vụ hỗ trợ hành chính khác.', array['Kiểm tra, định dạng và đánh máy lại các thư từ, biên bản và báo cáo từ bản đọc chính tả, các tài liệu điện tử hoặc các dự thảo viết tay để phù hợp với các tiêu chuẩn văn phòng, sử dụng máy chữ, máy tính cá nhân hoặc các thiết bị xử lý văn bản khác;', 'Sử dụng các gói phần mềm máy tính khác nhau bao gồm bảng tính để cung cấp hỗ trợ quản trị;', 'Giải quyết các thư đi và thư đến;', 'Quét (scan), ghi lại và phân phối thư từ và tài liệu khác;', 'Xem xét các yêu cầu họp hoặc các buổi gặp mặt và giúp đỡ tổ chức các cuộc họp;', 'Xem xét và ghi lại việc rời đi và các việc được làm của các nhân viên khác;', 'Tổ chức và giám sát hệ thống sắp xếp;', 'Chủ động giải quyết các thư từ hàng ngày.']::text[], array['- Thư ký đánh máy', '- Thư ký xử lý văn bản']::text[], array['Thư ký luật - 3342', 'Thư ký hành chính - 3343', 'Trợ lý điều hành - 3343', 'Thư ký y tế - 3344']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1158) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('413', 'Nhân viên làm công việc bàn giấy nhập và xử lý các văn bản và dữ liệu; chuẩn bị, chỉnh sửa và tạo tài liệu để lưu trữ, xử lý, xuất bản và phát hành.', array['Nhập dữ liệu và mã cần thiết để xử lý thông tin; khôi phục, xác thực và cập nhật dữ liệu lưu trữ và lưu giữ hồ sơ nhập dữ liệu; lưu, sao chép lại thông tin và chỉnh sửa các biên bản và các bản thảo dưới dạng tốc ký sử dụng các phương tiện máy tính, máy ghi tốc ký và các thiết bị ghi âm; sao chép lại lời nói, âm thanh xung quanh và lời bài hát làm phụ đề cho các chương trình truyền hình và phim truyện.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1177) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('421', 'Nhân viên thu ngân, thu tiền và các nghề liên quan thực hiện các hoạt động về tiền bạc trong các cơ sở liên quan đến ngân hàng, dịch vụ bưu chính, đánh bạc, cá cược, cầm cố và thu nợ.', array['Giao dịch với khách hàng của ngân hàng hoặc bưu điện về các hoạt động liên quan đến tiền và dịch vụ bưu chính; nhận và trả tiền cá cược dựa trên các kết quả của các sự kiện thể thao; thực hiện các trò chơi đánh bạc; cho vay tiền đối với các vật phẩm ký gửi hoặc chứng khoán khác; thu nợ và các khoản thanh toán khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1213) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('422', 'Nhân viên thông tin khách hàng cung cấp và tiếp nhận các thông tin bằng điện thoại hoặc các phương tiện điện tử như thư điện tử cùng với việc sắp xếp đi lại, miêu tả sản phẩm và dịch vụ của tổ chức, đăng ký ăn ở cho khách, đón khách, sắp đặt lịch hẹn, kết nối các cuộc gọi, phỏng vấn điều tra và phỏng vấn các ứng cử viên để trả lương phù hợp.', array['Chuẩn bị lịch trình, đặt tua du lịch và khách sạn cho khách; chào và tiếp đón khách; đăng ký chỗ ở cho khách; cung cấp thông tin liên quan đến hàng hóa, dịch vụ và chính sách của tổ chức; sắp đặt lịch hẹn thay cho đơn vị; làm tổng đài điện thoại; phỏng vấn điều tra và ứng viên phù hợp.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1265) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('431', 'Nhân viên làm công việc liên quan đến số liệu thu thập, biên soạn, tính toán sổ sách kế toán, các số liệu thống kê, tài chính và các số liệu khác; tính phí các giao dịch bằng tiền mặt liên quan đến các vấn đề tài chính.', array['Hỗ trợ hồ sơ và sổ sách kế toán; tính chi phí sản xuất đơn vị; tính lương và trong một số trường hợp chuẩn bị các gói lương và trả lương; tính phí các giao dịch bằng tiền mặt liên quan đến các vấn đề tài chính; thu thập, biên soạn và tính toán số liệu thống kê hoặc số liệu thống kê bảo hiểm; thực hiện các nhiệm vụ văn phòng liên quan đến các giao dịch tài chính của một tổ chức bảo hiểm, ngân hàng hoặc các tổ chức tương tự.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1390) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('432', 'Nhân viên ghi chép nguyên vật liệu và vận chuyển lưu giữ hồ sơ về hàng hóa sản xuất, mua bán, tồn kho và gửi đi và của các vật liệu cần thiết vào thời điểm sản xuất cụ thể; lưu giữ hồ sơ về các lĩnh vực hoạt động và điều phối thời gian vận chuyển hàng hóa và hành khách.', array['Ghi chép hàng hóa sản xuất, tồn kho, đặt hàng hoặc gửi đi; ghi chép vật liệu sản xuất nhận được, lưu trữ hoặc phân phối; tính toán số lượng vật liệu sản xuất theo yêu cầu ở những thời điểm cụ thể và hỗ trợ chuẩn bị và kiểm tra lịch trình hoạt động sản xuất; giữ hồ sơ của các bộ phận chức năng và phối hợp tính toán thời gian vận chuyển hàng hóa và hành khách.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1446) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('440', 'Nhân viên hỗ trợ văn phòng khác làm các công việc văn phòng trong các báo, tòa án, thư viện hoặc bưu điện; lưu trữ văn thư, tài liệu; chuẩn bị thông tin để xử lý; bảo quản các hồ sơ cá nhân; kiểm tra tài liệu và so sánh với các tài liệu gốc; viết thay cho những người mù chữ.', array['Lưu trữ các thông tin về mua sắm, cho mượn và trả sách thư viện; bảo quản các hồ sơ cá nhân; phân loại và sắp xếp các tài liệu, hồ sơ các loại; phân loại, ghi lại và chuyển thư từ bưu điện cũng như trong các công ty; đánh mã, sửa bản in thử; thực hiện một số công việc văn phòng khác; viết thay những người không đọc và viết được.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1486) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('511', 'Nhân viên hướng dẫn, tổ chức khách du lịch cung cấp những dịch vụ cá nhân đa dạng liên quan đến du lịch bằng máy bay, tàu hỏa, tàu thủy, xe buýt và xe có động cơ khác; hướng dẫn cho cá nhân và nhóm du lịch, tham quan ngắm cảnh và du ngoạn.', array['Đảm bảo sự thoải mái và an toàn cho khách hàng;', 'Phục vụ ăn uống và nghỉ ngơi;', 'Cung cấp thông tin và trả lời câu hỏi liên quan đến du lịch;', 'Phát hành vé trên phương tiện giao thông công cộng;', 'Đi theo cá nhân hoặc nhóm du lịch, tham quan, khám phá và giới thiệu phong cảnh.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1569) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('512', 'Đầu bếp lên kế hoạch, tổ chức, chuẩn bị và nấu món ăn theo công thức hoặc dưới sự giám sát của bếp trưởng, trong khách sạn, nhà hàng hoặc những nơi ăn uống khác, trên tàu thủy, tàu hỏa chở khách và trong nhà riêng.', array['Lên kế hoạch bữa ăn; chuẩn bị và nấu thực phẩm;', 'Lên kế hoạch, giám sát và điều phối công việc của phụ bếp;', 'Kiểm tra chất lượng món ăn;', 'Cân đo và pha chế nguyên liệu theo công thức hoặc yêu cầu cá nhân;', 'Giám sát nhiệt độ của lò, bếp nướng và những thiết bị khác;', 'Kiểm tra và vệ sinh bếp, thiết bị bếp, khu vực phục vụ… để đảm bảo an toàn và vệ sinh các dụng cụ nấu ăn;', 'Vận hành các thiết bị nấu ăn quy mô lớn như lò nướng, lò rán hoặc lưới nướng.']::text[], '{}'::text[], array['Quản lý quán cà phê - 1745', 'Quản lý nhà hàng - 1745', 'Đầu bếp trưởng - 3434', 'Người chuẩn bị đồ ăn nhanh - 9401']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1630) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('513', 'Bồi bàn và nhân viên pha chế phục vụ thức ăn và đồ uống ở những địa điểm kinh doanh ăn uống, câu lạc bộ, căng tin, trên tàu thủy và trên tàu hỏa.', array['Hỗ trợ giữ tài sản của quán; rửa cốc chén đã sử dụng và làm sạch khu vực quầy; phục vụ đồ uống có cồn và không cồn; bầy bàn với khăn sạch, dao dĩa, bát đĩa và cốc; chuẩn bị thức ăn và đồ uống; tư vấn trong việc lựa chọn rượu vang và phục vụ rượu; lấy đơn đặt bàn cho đồ ăn/uống và chuyển cho bộ phận bếp; đưa hóa đơn và nhận thanh toán.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1645) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('514', 'Thợ làm đầu, nhân viên làm đẹp cắt, làm tóc, cạo và tỉa râu, trị liệu làm đẹp, dùng mỹ phẩm và trang điểm và đưa ra những loại chăm sóc khác nhau cho từng cá nhân để cải thiện vẻ bề ngoài.', array['Xem xét yêu cầu của khách hàng; cắt và làm tóc; cạo và tỉa râu; trị liệu làm đẹp, dùng mỹ phẩm và trang điểm, làm móng, xử lý một số vấn đề nhỏ về chân; dịch vụ tắm và massage đơn giản.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1683) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('515', 'Người giám sát tòa nhà, quản gia phối hợp, sắp xếp và giám sát công việc của những người dọn dẹp và nhân viên trông giữ khác trong các cơ quan thương mại, công nghiệp hay khu dân cư. Họ chịu trách nhiệm về trông coi và chăm sóc trong khách sạn, văn phòng, chung cư, nhà ở hay biệt thự tư nhân.', array['Phân công nhiệm vụ và kiểm tra khu vực tòa nhà về vệ sinh, dọn dẹp và công việc duy tu; cung cấp và đảm bảo những thiết bị đưa ra phù hợp; thẩm tra lý lịch và tuyển nhân viên; tập huấn cả nhân viên mới và có kinh nghiệm; tiến cử, thuyên chuyển hoặc sa thải; thực hiện một số nhiệm vụ vệ sinh, dọn dẹp và duy tu.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1720) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('516', 'Nhân viên dịch vụ cá nhân khác kể lại quá khứ, dự đoán tương lai của cuộc đời con người; cung cấp dịch vụ bầu bạn và dịch vụ cá nhân khác; làm đẹp, huấn luyện và chăm sóc vật nuôi; dịch vụ tang lễ và ướp xác; hướng dẫn lái xe.', array['Viết lá số tử vi; cung cấp dịch vụ bầu bạn và dịch vụ cá nhân khác; cung cấp dịch vụ tang lễ và ướp xác; nuôi dưỡng, chăm sóc, làm đẹp vật nuôi; hướng dẫn lái xe.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1779) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('521', 'Người bán hàng trên đường phố và tại chợ bán hàng ở quầy hàng trong chợ hay trên đường phố, chuẩn bị và bán các loại thực phẩm và đồ uống nóng hoặc lạnh tiêu dùng ngay trên các đường phố và nơi công cộng.', array['Có chỗ bán hợp pháp tại một địa điểm cụ thể ở đường phố, chợ hoặc các không gian mở khác để bán thực phẩm và đồ uống trên đường; mua hoặc ký hợp đồng cung cấp thường xuyên các sản phẩm sẽ được bán; dựng và tháo dỡ quầy hàng và giá đỡ; vận chuyển, lưu trữ, bốc xếp sản phẩm để bán; giới thiệu, trưng bày và bán hàng hóa, thực phẩm và đồ uống, chấp nhận thanh toán; bao bì và đóng gói hàng hóa bán; chuẩn bị thức ăn và đồ uống để bán; xe đẩy, xe tải, khay hay giỏ để mang thức ăn và đồ uống đến nơi mong muốn trên đường phố hoặc đến những nơi công cộng như nhà ga hoặc rạp chiếu phim; giữ sổ sách kế toán và duy trì hàng hóa trong kho.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 38) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('522', 'Nhân viên bán hàng trong cửa hàng bán nhiều loại hàng hóa và dịch vụ trực tiếp cho khách hàng hoặc thay mặt cơ sở bán lẻ hoặc bán buôn. Họ giới thiệu đặc điểm và chất lượng của hàng hóa và dịch vụ, có thể điều hành cửa hàng nhỏ hoặc giám sát hoạt động của nhân viên trợ giúp hoặc thu ngân.', array['Giải thích những thắc mắc của khách hàng, tư vấn về dòng sản phẩm, giá, vận chuyển, bảo hành và hướng dẫn sử dụng; giới thiệu, giải thích và bán hàng hóa, dịch vụ cho khách hàng; chấp nhận thanh toán hàng hóa và dịch vụ bằng các phương thức thanh toán khác nhau, chuẩn bị hóa đơn bán hàng; thực hiện hoặc hỗ trợ việc quản lý kho hàng; sắp xếp và trưng bày hàng hóa để bán, đóng gói bao bì bán hàng; xác định sản phẩm pha trộn, lưu kho và mức giá cho hàng hóa bán; giám sát và điều phối các hoạt động của trợ lý bán hàng, kiểm tra máy móc và các nhân viên khác trong siêu thị hoặc cửa hàng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 78) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('523', 'Nhân viên thu ngân và bán vé sử dụng máy tính tiền, máy quét mã, máy tính và các thiết bị khác để ghi lại và chấp nhận thanh toán cho việc mua hàng hóa, dịch vụ trong cửa hàng, nhà hàng và phòng bán vé.', array['Nhận và xác nhận thanh toán bằng tiền mặt, séc, thẻ tín dụng hoặc thẻ ghi nợ tự động trong cửa hàng, phòng vé hoặc các cơ sở tương tự;', 'Trả tiền lẻ và nhận hóa đơn;', 'Phát hành vé cho khán giả sự kiện văn hóa và thể thao;', 'Đếm và ghi lại số tiền nhận được và cân đối với hồ sơ bán hàng của máy tính tiền;', 'Nhận tiền mặt, kiểm tra biên lai và các giấy tờ khác, chuẩn bị gửi tiền đến ngân hàng;', 'Dùng máy tính tiền để tính toán tiền trả lại hoặc nhận từ khách hàng;', 'Quét mã, cân và tính giá hàng hóa;', 'Gói và cho hàng hóa vào túi.']::text[], array['Nhân viên thu ngân', 'Nhân viên thu ngân tại các trạm dịch vụ', 'Nhân viên thu ngân cửa hàng', 'Nhân viên phát hành vé (sự kiện giải trí và thể thao)']::text[], array['Nhân viên phát hành vé (du lịch) - 4221', 'Giám sát viên thu ngân - 5222', 'Nhân viên trợ giúp bán hàng - 5223', 'Nhân viên phục vụ ở các trạm dịch vụ - 5245']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 139) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('524', 'Nhân viên bán hàng khác trưng bày, trình diễn và bán hàng hóa, thực phẩm và dịch vụ cho khách hàng trong các bối cảnh khác ngoài bán hàng ở chợ, đường phố và cửa hàng. Nhóm này gồm nhân viên bán hàng chưa được phân loại ở nhóm 521 - Người bán hàng trên đường phố và tại chợ, nhóm 522 - Nhân viên bán hàng trong cửa hàng và nhóm 523 - Nhân viên thu ngân và bán vé.', array['Trưng bày và giới thiệu các mặt hàng để bán; tạo dáng chụp ảnh, phim, video, quảng cáo hoặc để sáng tạo nghệ thuật; trả lời câu hỏi, tư vấn cho việc sử dụng hàng hóa và dịch vụ; nhận đơn đặt hàng, sắp xếp thanh toán, giao hàng và thu tiền hàng hóa hoặc cung ứng dịch vụ; bán hàng hóa và dịch vụ, thúc đẩy kinh doanh bằng cách tiếp cận khách hàng tiềm năng, giao hàng đặt qua điện thoại hoặc các phương tiện truyền thông điện tử khác; bán nhiên liệu, dầu mỡ bôi trơn và các sản phẩm ô tô khác tại trạm dịch vụ; cung cấp các dịch vụ như tiếp nhiên liệu, làm sạch, bôi trơn và thực hiện các sửa chữa nhỏ cho xe có động cơ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 160) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('531', 'Nhân viên chăm sóc trẻ em và người phụ tá cho giáo viên cung cấp việc chăm sóc và giám sát trẻ em ở trường học, nhà ở và các cơ sở chăm sóc trẻ khác.', array['Hỗ trợ trẻ em học các kỹ năng xã hội; giới thiệu, hỗ trợ và tham gia vào các hoạt động giúp tăng cường sự phát triển về thể chất, xã hội, cảm xúc và trí tuệ cho trẻ em ở trường; hỗ trợ chuẩn bị tài liệu và thiết bị cho giáo dục và các hoạt động giải trí của trẻ em tại trường học, ngoài giờ học, trong kỳ nghỉ và tại các trung tâm chăm sóc ban ngày.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 280) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('532', 'Nhân viên chăm sóc cá nhân trong các dịch vụ y tế cung cấp dịch vụ chăm sóc cá nhân, hỗ trợ đi lại và các hoạt động sinh hoạt hàng ngày cho bệnh nhân, người già, người khuyết tật và người nghỉ dưỡng trong các cơ sở chăm sóc sức khỏe và dân cư.', array['Hỗ trợ bệnh nhân vận động, chăm sóc cá nhân và nhu cầu giao tiếp; khử trùng dụng cụ, thiết bị phẫu thuật và các dụng cụ, thiết bị khác; quan sát và báo cáo lưu ý với các nhân viên y tế và cơ sở xã hội thích hợp; chuẩn bị cho bệnh nhân khám và điều trị, tham gia lập kế hoạch chăm sóc cá nhân.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 314) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('540', 'Nhân viên dịch vụ bảo vệ bảo vệ cá nhân và tài sản khỏi hỏa hoạn và các mối nguy hiểm khác; duy trì và thực thi luật pháp và các quy định. Hiệu suất thành thạo trong các nghề ở nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Phòng cháy chữa cháy, cứu người khỏi các vụ hỏa hoạn, các tai nạn hoặc mắc kẹt trong các tình huống nguy hiểm; tuân thủ luật pháp, thực thi pháp luật và quy định, tuần tra khu vực công cộng; hướng dẫn giao thông và bảo vệ hiện trường trong trường hợp có tai nạn; tuần tra và giám sát tại chỗ để bảo vệ tài sản đối với hành vi trộm cắp và phá hoại; kiểm soát ra vào các cơ sở, giữ gìn trật tự và thực thi các quy định tại sự kiện công cộng, trong phạm vi cơ sở. Nhóm này bao gồm cả giám sát nhân viên khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 384) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('611', 'Lao động trồng trọt và làm vườn có sản phẩm chủ yếu để bán lập kế hoạch, tổ chức và thực hiện các hoạt động trồng, thu hoạch vụ mùa; trồng cây ăn quả và cây khác; trồng rau, cây dược liệu và cây khác trong vườn; sản xuất các sản phẩm từ vườn và vườn ươm để bán, phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc bán tại chợ.', array['Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng cây trồng, lập kế hoạch và điều phối sản xuất phù hợp; mua hạt giống, củ, phân bón; đầu tư cải tạo đất; chuẩn bị đất, gieo hạt, trồng, canh tác và thu hoạch cây trồng; chăm sóc động vật làm việc và bảo trì trang trại, máy móc thiết bị; sản xuất giống, củ và hạt; bảo quản tại kho và thực hiện chế biến một số sản phẩm; cung cấp và tiếp thị sản phẩm nông nghiệp. Nhóm này bao gồm cả giám sát người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 425) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('612', 'Lao động chăn nuôi lên kế hoạch, tổ chức và thực hiện các hoạt động chăn nuôi để nhân giống, chăn nuôi gia súc, gia cầm, côn trùng và động vật hoang dã để lấy thịt, sữa, mật ong, da, sợi và các sản phẩm khác hoặc để sử dụng làm việc, thể thao, giải trí, bán hoặc giao cho người bán buôn, tổ chức tiếp thị và thị trường.', array['Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng chăn nuôi; lập kế hoạch và phối hợp sản xuất phù hợp; cho ăn và chăm sóc động vật; chuẩn bị động vật hoặc sản phẩm động vật cho thị trường; theo dõi và kiểm tra động vật để phát hiện bệnh tật, thương tích và kiểm tra tình trạng sức khỏe như tỷ lệ tăng cân; thực hiện công việc liên quan đến sinh sản động vật như nuôi dưỡng, thụ tinh nhân tạo và đỡ đẻ cho động vật; thuê hoặc đầu tư, bảo trì và làm sạch các trang trại, máy móc, thiết bị và công trình; bảo quản tại kho và sơ chế sản phẩm; giới thiệu và tiếp thị sản phẩm, sắp xếp việc mua, bán, vận chuyển, sản xuất và cung ứng; theo dõi và đánh giá hồ sơ của các hoạt động và giao dịch; đào tạo và giám sát lao động trong các quy trình chăm sóc động vật, nhiệm vụ bảo trì và bảo đảm sức khỏe và an toàn; thuê hoặc sa thải người lao động và nhà thầu.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 523) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('613', 'Lao động trồng trọt và chăn nuôi hỗn hợp lên kế hoạch, tổ chức và thực hiện các hoạt động canh tác để trồng và thu hoạch cây và các loại mùa vụ khác cũng như nhân giống, nuôi, chăm sóc động vật và sản xuất nhiều loại sản phẩm chăn nuôi để bán hoặc phân phối đến người mua buôn, tổ chức tiếp thị hoặc thị trường.', array['- Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng cây trồng và vật nuôi; lập kế hoạch và điều phối sản xuất cho phù hợp;', '- Mua hạt giống, phân bón và các vật tư khác;', '- Thực hiện các hoạt động như làm đất, gieo hạt, trồng, canh tác và thu hoạch cây trồng;', '- Sản xuất hoặc mua thức ăn gia súc và các nguồn cung cấp thực phẩm khác;', '- Chăn nuôi và chăm sóc động vật;', '- Giết mổ và lột da động vật, chuẩn bị động vật hoặc sản phẩm động vật cho thị trường;', '- Thuê hoặc đầu tư, bảo trì và vệ sinh trang trại, máy móc, thiết bị và công trình;', '- Lưu trữ và sơ chế sản phẩm;', '- Giới thiệu và tiếp thị sản phẩm; sắp xếp việc mua, bán, vận chuyển gia súc, sản xuất và cung ứng; theo dõi và đánh giá hồ sơ về các hoạt động và giao dịch của trang trại;', '- Đào tạo và giám sát người lao động về các quy trình sản xuất, nhiệm vụ bảo trì, các biện pháp phòng ngừa an toàn và sức khỏe; tuyển dụng và sa thải người lao động và các nhà thầu.']::text[], array['- Nông dân canh tác hỗn hợp;', '- Công nhân nông nghiệp có kỹ năng (trang trại hỗn hợp)']::text[], array['- Giám đốc sản xuất nông nghiệp - 1721, 1741', '- Nhà quản lý trồng trọt - 1721, 1741', '- Lao động trồng trọt và chăn nuôi hỗn hợp - 9203', 'Ghi chú:', 'Nông dân và các công nhân nông nghiệp có kỹ năng khác có nhiệm vụ chủ yếu liên quan đến chăn nuôi hoặc trồng trọt nhưng cũng liên quan đến một số hoạt động ngẫu nhiên trong việc trồng trọt hoặc chăm sóc động vật không nên được đưa vào nhóm 6130 - Lao động trồng trọt và chăn nuôi hỗn hợp. Ví dụ, một nông dân nuôi gia súc để bán cho thị trường nhưng cũng dành một ít thời gian để trồng rau trong vườn nên được phân loại trong nhóm 6121 - Lao động chăn nuôi gia súc và vật nuôi lấy sữa. Tương tự, một nông dân trồng lúa mì nuôi một số lượng nhỏ gà và các động vật khác trong trang trại nên được phân loại trong nhóm 6111 - Lao động trồng, thu hoạch rau và cây mùa vụ.', 'Công nhân tại các trang trại hỗn hợp chuyên sản xuất cây trồng hoặc sản xuất động vật cho thị trường nên được phân loại trong nhóm 611 - Lao động trồng trọt và làm vườn có sản phẩm chủ yếu để bán hoặc 612 - Lao động chăn nuôi, nếu phù hợp.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 610) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('621', 'Lao động trong lâm nghiệp và lĩnh vực có liên quan lập kế hoạch, tổ chức và thực hiện các hoạt động canh tác, bảo tồn và khai thác rừng tự nhiên và rừng trồng.', array['- Đánh giá các khu vực để trồng lại rừng; chọn cây giống và trồng cây bằng các công cụ thủ công; thiết lập và chăm sóc khu vực rừng;', '- Xác định vị trí cây bị đốn hạ và ước tính khối lượng gỗ;', '- Sử dụng cưa xích và cưa điện cắt, chặt cây và cưa chúng thành các khúc gỗ;', '- Hình thành các sản phẩm gỗ thô từ các khối gỗ tròn tại nơi chặt hạ; xếp chồng vận chuyển chúng trong các máng hoặc trôi sông;', '- Theo dõi để phát hiện các vụ cháy rừng, tham gia các hoạt động chữa cháy, hoàn thành các báo cáo chữa cháy và bảo trì thiết bị chữa cháy;', '- Kiểm soát cỏ dại phát triển trong rừng tái sinh bằng các công cụ và hóa chất;', '- Vận hành và bảo dưỡng xe ủi đất, máy trượt hoặc xe vận chuyển khác để cày xới đất hoặc cải tạo khu vực trồng;', '- Thu nhặt hạt, cắt tỉa cây, hỗ trợ trong trồng khảo sát và đánh dấu cây cho hoạt động tiếp theo;', '- Đào tạo và giám sát người lao động khác trong các quy trình lâm nghiệp, bao gồm cả lao động lâm nghiệp và người vận hành nhà máy.']::text[], array['- Người đốt than', '- Người khai thác gỗ', '- Lao động có kỹ năng trong lâm nghiệp', '- Người tuần tra lâm nghiệp', '- Người đốn cây']::text[], array['- Chuyên gia lâm sinh - 2132', '- Kỹ thuật viên lâm nghiệp - 3143', '- Thợ vận hành máy đốn cây - 8341', '- Lao động lâm nghiệp - 9205']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 638) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('622', 'Lao động thủy sản, săn bắn và đánh bẫy nhân giống, nuôi và đánh bắt thủy sản, săn bắn và bẫy động vật để bán hoặc phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc thị trường.', array['Nhân giống, nuôi, thu hoạch cá, trai, hàu và các loại thủy sinh khác sống ở nước ngọt hoặc nước mặn; giám sát môi trường để đảm bảo duy trì các điều kiện sống tối ưu cho thủy sản; làm sạch, đông lạnh, hoặc ướp muối cho thủy sản đánh bắt trên biển hoặc ngoài khơi, đóng lô cá và các sản phẩm khác để vận chuyển; thuê hoặc đầu tư bảo dưỡng các trang trại, hồ kè, máy móc, tàu đánh cá và các thiết bị khác; chuẩn bị và sửa chữa lưới, ngư cụ và thiết bị khác; vận hành tàu cá đến, đi và ở tại cảng cá; mồi, thiết lập, vận hành ngư cụ; làm bẫy để bắt động vật có vú, chim hoặc bò sát; cung cấp hoặc tiếp thị sản phẩm; giám sát và đào tạo người lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 661) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('631', 'Lao động trồng trọt tự cung tự cấp trồng và thu hoạch cây và bụi cây, rau và trái cây để có thực phẩm, nơi ở và trong một số trường hợp thu nhập tối thiểu cho bản thân và hộ gia đình.', array['- Chuẩn bị đất, gieo, trồng, chăm sóc và thu hoạch cây trồng;', '- Trồng rau, trái cây, các loại cây khác và cây bụi;', '- Lấy nước và kiếm củi;', '- Lưu trữ cho sử dụng sau này và sơ chế sản phẩm;', '- Xây dựng và bảo trì nhà cửa và đồ vật khác;', '- Chế tạo công cụ, quần áo và các đồ dùng sử dụng trong hộ gia đình;', '- Bán hoặc trao đổi một số sản phẩm tại thị trường địa phương.']::text[], array['- Nông dân trồng trọt', '- Lao động làm vườn tự cung tự cấp', '- Lao động trồng rau tự cung tự cấp']::text[], array['- Lao động nông trại - 9201', '- Người thu gom củi - 9624', '- Người thu gom nước - 9624', 'Ghi chú:', 'Người lao động trong môi trường sinh hoạt có nhiệm vụ chính là lấy nước và kiếm củi được phân loại trong nhóm 9624 - Người thu gom nước và củi. Người làm nông nghiệp tự cung tự cấp thực hiện một số ít các công việc đơn giản và thường xuyên thường dưới sự chỉ đạo của người khác được phân loại trong nhóm 92 - Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 746) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('632', 'Lao động chăn nuôi gia súc tự cung tự cấp nuôi và chăm sóc gia súc để cung cấp thức ăn cho gia đình và trong một số trường hợp thu nhập tối thiểu bằng tiền mặt cho bản thân và hộ gia đình.', array['- Canh tác đồng cỏ hoặc quản lý vùng đất chăn thả; giám sát thức ăn và nguồn cung cấp nước cần thiết để duy trì các điều kiện chăn nuôi;', '- Theo dõi và kiểm tra động vật để phát hiện bệnh tật, thương tích hay tình trạng thể chất;', '- Chải lông và đánh dấu động vật để lấy lông và len;', '- Chăn hoặc dẫn gia súc đến đồng cỏ, khoanh vùng đất chăn thả và nguồn cung cấp nước;', '- Nuôi, chăm sóc, vắt sữa hoặc lấy máu động vật;', '- Chăn nuôi và đỡ đẻ động vật;', '- Giết mổ, lột da động vật và chuẩn bị sản phẩm để tiêu dùng hoặc bán;', '- Thực hiện sơ chế động vật;', '- Xây dựng, bảo trì nhà cửa và các đồ vật khác;', '- Làm công cụ, quần áo và đồ dùng tự sử dụng trong hộ gia đình;', '- Lấy nước và kiếm củi;', '- Mua, trao đổi, bán động vật và một số sản phẩm.']::text[], array['- Nông dân chăn nuôi gia súc tự cung tự cấp']::text[], array['- Lao động trang trại chăn nuôi - 9202', '- Lao động trang trại trồng trọt và chăn nuôi hỗn hợp - 9203', '- Người thu gom nước và củi - 9624']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 766) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('633', 'Lao động trồng trọt và chăn nuôi hỗn hợp tự cung tự cấp trồng và thu hoạch vụ mùa hoặc cây và bụi cây, rau và trái cây; thu nhặt trái cây dại, thảo dược và thực vật khác; săn bắn động vật; đánh bắt cá và các loài thủy sinh để có thực phẩm cho gia đình và trong một số trường hợp thu nhập tối thiểu bằng tiền mặt cho bản thân và hộ gia đình.', array['- Chuẩn bị đất, gieo, trồng, chăm sóc và thu hoạch cây trồng mùa vụ;', '- Trồng rau, trái cây, các loại cây khác và cây bụi;', '- Thu nhặt trái cây dại, thảo dược và các thực vật khác;', '- Chăn nuôi, chăm sóc và nuôi dưỡng động vật và gia cầm chủ yếu để lấy thịt, trứng, sữa, lông, da hoặc các sản phẩm khác;', '- Lấy nước và kiếm củi;', '- Lưu trữ các sản phẩm để sử dụng sau này và thực hiện một số sơ chế sản phẩm;', '- Xây dựng và bảo trì nhà ở và các đồ vật khác;', '- Chế tạo dụng cụ, quần áo và đồ dùng tự sử dụng trong hộ gia đình;', '- Bán hoặc trao đổi một số sản phẩm tại thị trường địa phương.']::text[], array['- Nông dân trồng trọt và chăn nuôi hỗn hợp tự cung tự cấp']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 787) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('634', 'Lao động đánh cá, săn bắn, đánh bẫy và thu hái tự cung tự cấp hái lượm trái cây dại, dược liệu và thực vật khác; săn bắt và bẫy động vật; bắt cá và các loài thủy sinh khác để có thực phẩm cho gia đình và trong một số trường hợp thu nhập tối thiểu bằng tiền mặt cho bản thân và hộ gia đình.', array['- Thu nhặt trái cây dại, rễ cây, dược liệu và thực vật khác;', '- Săn bắn hoặc bẫy động vật chủ yếu để lấy thịt, sữa, lông, da hoặc các sản phẩm khác;', '- Lấy nước và kiếm củi;', '- Đánh bắt cá và các loài thủy sinh khác;', '- Lưu trữ hoặc sơ chế sản phẩm;', '- Xây dựng, bảo trì nhà ở và các đồ vật khác;', '- Chế tạo dụng cụ, quần áo và các đồ dùng cho hộ gia đình sử dụng;', '- Bán hoặc trao đổi một số sản phẩm tại thị trường địa phương.']::text[], array['- Nông dân hái lượm tự cung tự cấp', '- Người thu hoạch tự cung tự cấp', '- Người lặn mò tự cung tự cấp', '- Người đánh cá tự cung tự cấp', '- Người đánh bẫy tự cung tự cấp']::text[], array['- Lao động trồng trọt tự cung tự cấp - 6310', '- Lao động chăn nuôi gia súc tự cung tự cấp - 6320', '- Lao động trang trại chăn nuôi - 9202', '- Người thu gom nước và củi - 9624']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 801) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('711', 'Thợ xây dựng khung nhà và thợ khác có liên quan xây dựng, bảo trì và sửa chữa các toà nhà; xây dựng, sửa chữa nền móng, tường, các công trình bằng gạch, đá và các nguyên vật liệu tương tự; tạo dáng, hoàn thiện đá để xây dựng và các mục đích khác; thực hiện các nhiệm vụ xây dựng và bảo trì khác.', array['Xây dựng, bảo trì, sửa chữa các tòa nhà và các công trình xây dựng khác bằng cách sử dụng các kỹ thuật xây dựng truyền thống hoặc hiện đại; xây dựng, sửa chữa nền móng, tường, các công trình bằng gạch, đá và các vật liệu tương tự; cắt đá khai thác thành phiến hoặc khối; cắt, tạo hình và hoàn thiện đá để xây dựng, trang trí, làm bia kỷ niệm hay các mục đích khác; lắp ghép khung và kết cấu bê tông cốt thép cũng như hoàn thiện và sửa chữa bề mặt xi măng; cắt, tạo hình, lắp ráp và bảo trì các cấu trúc bằng gỗ; thực hiện các công việc xây dựng và bảo trì khác. Nhóm này bao gồm cả việc giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 831) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('712', 'Thợ hoàn thiện công trình và thợ có liên quan thực hiện các công việc như lắp đặt, bảo dưỡng và sửa chữa mái nhà, sàn nhà, tường, hệ thống cách nhiệt, kính cửa sổ hoặc các khung khác cũng như hệ thống ống nước, đường dây điện trong tòa nhà và các công trình khác.', array['Phủ mái nhà bằng một hoặc nhiều loại vật liệu; lắp đặt sàn gỗ và các loại sàn khác; lát sàn và tường bằng gạch hoặc tấm khảm; trát vữa tường và trát thạch cao trần nhà; sử dụng vật liệu cách nhiệt cho tường, sàn và trần nhà; cắt, lắp và đặt kính cho cửa sổ và các khoảng trống tương tự; lắp đặt hệ thống ống nước và đường ống; lắp đặt hệ thống dây điện và thiết bị liên quan. Nhóm này bao gồm cả giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 936) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('713', 'Thợ sơn, người lau dọn tòa nhà và lao động có liên quan chuẩn bị bề mặt, quét sơn và các vật liệu tương tự cho các tòa nhà và các cấu trúc khác như xe cộ, đồ đạc. Họ bao phủ bên trong tường, trần nhà bằng giấy dán tường; làm sạch ống khói và bề mặt bên ngoài của các tòa nhà và các công trình khác.', array['Chuẩn bị bề mặt, quét sơn và các vật liệu tương tự cho tòa nhà và các công trình khác; quét sơn hoặc véc ni cho xe hoặc đồ đạc thường bằng dụng cụ phun tay; phủ bên trong tường và trần nhà bằng giấy dán tường, lụa hoặc các loại vải khác; làm sạch ống khói, bề mặt bên ngoài của tòa nhà và các công trình khác. Nhóm này bao gồm cả việc giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1060) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('721', 'Thợ luyện kim loại, thợ đúc, thợ hàn và thợ có liên quan tạo khuôn, lõi để đúc kim loại, hàn và cắt các bộ phận kim loại; chế tạo và sửa chữa các sản phẩm kim loại tấm; lắp đặt, bảo trì và sửa chữa các cấu trúc kim loại nặng, dụng cụ, cáp treo và thiết bị liên quan.', array['Tạo khuôn, lõi để đúc kim loại; hàn và tạo hình các bộ phận kim loại; sản xuất và sửa chữa các sản phẩm bằng kim loại tấm như thép tấm, đồng, thiếc; lắp đặt, bảo trì và sửa chữa các kết cấu kim loại nặng, dụng cụ, cáp treo và thiết bị liên quan.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1113) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('722', 'Thợ rèn, thợ chế tạo các dụng cụ và thợ có liên quan tiến hành quai búa, rèn thanh, cần, thỏi bằng sắt, thép và kim loại khác để chế tạo, sửa chữa các loại dụng cụ, thiết bị và vật dụng khác; lắp đặt máy công cụ cho người vận hành hoặc lắp đặt và vận hành các máy công cụ khác nhau; đánh bóng và mài bề mặt.', array['Quai búa, rèn thanh, cần, thỏi bằng sắt, thép và kim loại khác để chế tạo, sửa chữa các loại dụng cụ, thiết bị và vật dụng khác; lắp đặt máy công cụ cho người vận hành hoặc lắp đặt và vận hành các máy công cụ khác nhau làm việc với dung sai tốt; đánh bóng và mài các bề mặt kim loại và dụng cụ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1198) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('723', 'Thợ cơ khí và sửa chữa máy móc lắp ráp, lắp đặt, bảo trì, sửa chữa động cơ, xe cộ, máy móc nông nghiệp hoặc công nghiệp và thiết bị cơ khí tương tự.', array['lắp ráp, lắp đặt, bảo trì, sửa chữa động cơ, xe cộ, máy móc nông nghiệp hoặc công nghiệp và các thiết bị cơ khí tương tự.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1278) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('731', 'Thợ thủ công kết hợp kỹ năng nghệ thuật và thủ công để thiết kế, chế tạo, sửa chữa, điều chỉnh, bảo dưỡng và trang trí các dụng cụ chính xác, nhạc cụ, đồ trang sức và các kim loại quý khác, đồ gốm sứ. Họ áp dụng các kỹ thuật truyền thống và hiện đại để khắc, đúc, lắp ráp, đan dệt và trang trí các sản phẩm thủy tinh, gốm sứ, dệt, rơm rạ, đá, gỗ và da.', array['Chế tạo, điều chỉnh, sửa chữa, bảo dưỡng và lắp đặt các dụng cụ âm nhạc và dụng cụ chính xác; chế tạo, điều chỉnh, sửa chữa hoặc đánh giá đồ trang sức, vật phẩm dành cho nghi lễ hoặc tôn giáo, vàng, bạc, kim loại quý hoặc đá quý khác; cắt, giũa, đánh bóng, chế tạo đá quý và đá bán quý bao gồm đá quý và kim cương; thiết kế và khắc trên đồ trang sức và kim loại quý; chuẩn bị đồ gốm, đồ sứ, thiết bị vệ sinh, gạch, ngói và bánh xe để mài mòn bằng tay hoặc bằng máy; thổi, đúc, nén, ép, cắt, mài, đánh bóng thủy tinh hoặc tạo hình thủy tinh nóng chảy theo các khuôn mẫu; trang trí các mặt hàng được làm từ gỗ, kim loại, dệt may, thủy tinh, gốm sứ và các nguyên vật liệu khác; lên kế hoạch, thiết kế và vẽ các chữ cái, hình vẽ, chữ lồng để làm bảng hiệu; áp dụng các kỹ thuật truyền thống để chuẩn bị gỗ, rơm rạ, song mây, sậy, đất sét, đá, vỏ sò, vỏ ốc và các vật liệu khác; chạm khắc, đúc nặn, lắp ráp, dệt hoặc sơn trang trí các vật phẩm khác nhau để sử dụng cá nhân, gia đình hay cho các mục đích trang trí; chuẩn bị nguyên vật liệu để làm các đồ nội thất đan lát, bàn chải, chổi và các loại rổ đan khác nhau; áp dụng kỹ thuật và hoa văn truyền thống để sản xuất các loại vải dệt thoi, dệt kim, thêu, các sản phẩm may mặc và đồ gia dụng khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1389) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('732', 'Thợ liên quan đến in gồm thợ thực hiện ở công đoạn trước khi in (chế bản cho in - prepress), thợ thực hiện ở công đoạn in (press) và thợ ở công đoạn hoàn thiện sau in (gia công ấn phẩm - postpress).', array['Vận hành thiết bị kỹ thuật số như nhập văn bản, nhập ảnh đồ họa, tạo dữ liệu cho quá trình ghi phim (image-setter), dữ liệu cho quá trình chế khuôn (plate-setter), vận hành các thiết bị in tương tự (offset, ống lõm, in cao, in lưới), vận hành thiết bị in kỹ thuật số (in phun và in tĩnh điện), vận hành các máy gia công xuất bản phẩm, vận hành các máy gia công các loại bao bì, vận hành các máy trang trí sản phẩm in đồ họa, máy ảnh và chụp hình khác để phục chế bản sao hoàn tất trên phim, đĩa và thiết bị đầu thu kỹ thuật số khác; vận hành thiết bị máy tính dựa trên điện ảnh để scan, tách và hiệu chỉnh màu, chỉnh sửa và quy trình khác liên quan chuyển bản sao từ phim, làm phim từ đĩa, cuộn và sản phẩm ghi hình kỹ thuật số; vận hành và giám sát máy sắp chữ, photo, in, xén, gấp, kiểm tra thứ tự (trang sách) và đóng quyển vật liệu in; thực hiện vận hành máy hoàn thiện tuần tự và bảo dưỡng máy móc; chuẩn bị giấy nền và vận hành thiết bị in.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1590) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('741', 'Thợ lắp đặt và sửa chữa thiết bị điện lắp đặt, bảo trì hệ thống dây điện, máy móc điện, các thiết bị điện, đường dây và dây cáp cung cấp và truyền tải điện.', array['Lắp đặt, bảo trì và điều chỉnh hệ thống dây điện, máy móc và thiết bị điện; kiểm tra bản thiết kế, sơ đồ nối dây và thông số kỹ thuật để xác định trình tự và phương pháp hoạt động; kiểm tra và thử nghiệm hệ thống điện, thiết bị, dây cáp và máy móc để xác định các mối nguy hiểm, khiếm khuyết và sự cần thiết phải điều chỉnh hoặc sửa chữa; lắp đặt, bảo trì và sửa chữa đường dây truyền tải điện; nối cáp điện.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1646) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('742', 'Thợ lắp đặt và thợ sửa chữa điện tử viễn thông lắp đặt, bảo trì, điều chỉnh và sửa chữa thiết bị điện tử như máy móc thương mại và thiết bị văn phòng, dụng cụ điện tử và hệ thống điều khiển; lắp đặt, sửa chữa và bảo trì thiết bị viễn thông, thiết bị truyền dữ liệu, cáp, ăng ten; sửa chữa, lắp đặt và bảo trì máy tính.', array['Kiểm tra và thử nghiệm máy móc, thiết bị, dụng cụ và hệ thống điều khiển để chẩn đoán lỗi; điều chỉnh, sửa chữa và thay thế các bộ phận, dây điện bị hỏng hay khiếm khuyết; bảo trì máy móc, thiết bị và dụng cụ; lắp đặt dụng cụ điện tử và hệ thống điều khiển; lắp và điều chỉnh thiết bị điện tử; bảo trì, khắc phục sự cố, lắp, điều chỉnh, kiểm tra và sửa chữa máy tính, thiết bị truyền dữ liệu và thiết bị ngoại vi máy tính; cài đặt, bảo trì, sửa chữa và chẩn đoán các sự cố của lò vi sóng, các dụng cụ ghi số liệu và truyền từ xa, hệ thống vệ tinh, hệ thống thông tin vô tuyến và sóng điện từ khác; cung cấp các giải pháp và thông tin kỹ thuật, giám sát hiệu suất của các mạng và thiết bị viễn thông phức tạp; lắp đặt, nối và sửa chữa hệ thống cáp cho máy tính, đài phát thanh, điện thoại và truyền hình; lắp đặt, bảo trì và sửa chữa ăng ten được sử dụng trong thông tin liên lạc.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1701) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('751', 'Thợ chế biến thực phẩm và các thợ khác có liên quan giết mổ động vật, xử lý và chế biến chúng cùng các mặt hàng thực phẩm liên quan để tiêu thụ cho người và động vật; làm các loại bánh mỳ, bánh ngọt và các sản phẩm bột mỳ khác; chế biến và bảo quản trái cây, rau củ và thực phẩm liên quan; nếm và phân loại các thực phẩm và đồ uống; chuẩn bị thuốc lá và làm sản phẩm thuốc lá.', array['Giết mổ động vật; chuẩn bị, chế biến thịt, cá và các thực phẩm liên quan; làm các loại bánh mỳ, bánh ngọt và các sản phẩm bột mỳ khác; chế biến, bảo quản trái cây, rau củ và thực phẩm liên quan; nếm và phân loại các sản phẩm thực phẩm, đồ uống khác nhau; chuẩn bị thuốc lá và làm sản phẩm thuốc lá. Nhóm này bao gổm cả việc giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1746) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('752', 'Thợ xử lý gỗ, thợ sản xuất đồ gỗ và các thợ có liên quan bảo quản, xử lý gỗ, đóng, trang trí, sửa chữa tủ đứng, xe cộ và các sản phẩm bằng gỗ khác; định vị, vận hành và bảo quản thiết bị, máy móc, công cụ gia công gỗ.', array['Vận hành các thiết bị để sấy gỗ và các sản phẩm gỗ khác; xử lý và bảo quản các sản phẩm gỗ bằng hóa chất; thiết lập, vận hành máy chế biến gỗ để cắt, tạo hình và tạo thành các bộ phận; lên kế hoạch, xác minh các sản phẩm được xử lý; khớp các bộ phận với nhau tạo thành các sản phẩm hoàn chỉnh, kiểm tra chất lượng và sự phù hợp của sản phẩm đảm bảo tuân thủ các thông số kỹ thuật; cài đặt và điều chỉnh các loại máy khác nhau để người khác vận hành; thiết lập, lập trình, vận hành và giám sát một số loại máy chế biến gỗ để chế tạo, sửa chữa, hoàn thiện đồ nội thất, đồ đạc và các sản phẩm gỗ khác; đọc và giải thích thông số kỹ thuật hoặc làm theo hướng dẫn bằng lời nói.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1852) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('753', 'Thợ may mặc và các thợ có liên quan may mặc, sửa chữa quần áo; thiết kế, sản xuất hàng dệt may, da, lông thú và các sản phẩm da hoặc lông thú; sửa chữa và trang trí quần áo, găng tay và các sản phẩm dệt may khác; tạo kiểu mẫu cho trang phục; sửa chữa hay thay thế vải bọc đồ nội thất, phụ tùng, dụng cụ chỉnh hình và nội thất ô tô; cắt, cạo, làm sạch, thuộc, đánh bóng và nhuộm da động vật; sửa chữa giày dép và vật dụng từ da khác.', array['May, thay đổi và sửa chữa quần áo; thiết kế và sản xuất trang phục may đo từ vải dệt, da, lông và chất liệu khác; làm mũ và tóc giả; thay đổi kiểu trang phục; tạo mẫu để sản xuất hàng may mặc và các sản phẩm dệt, da hoặc lông thú khác; may kết hợp sửa chữa, cải tiến, trang trí hàng may mặc, găng tay và sản phẩm dệt khác; chế tạo và lắp ráp cánh buồm, mái hiên và bạt; lắp đặt, sửa chữa và thay thế lớp bọc đồ nội thất, phụ tùng, dụng cụ chỉnh hình, ghế ngồi và các nội thất khác của ô tô, toa xe lửa, máy bay, tàu thủy và các phương tiện tương tự; cắt, cạo, làm sạch, thuộc, đánh bóng và nhuộm da động vật, vỏ lông để may quần áo và sản phẩm khác; đóng, sửa chữa, chỉnh hình giày dép theo tiêu chuẩn và các sản phẩm da tự nhiên hoặc tổng hợp.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 19) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('754', 'Thợ thủ công khác và các thợ có liên quan làm việc dưới mặt nước, sử dụng thiết bị thở dưới nước; định vị, lắp ráp và kích nổ chất nổ; kiểm tra và thử nghiệm vật liệu, thành phần và sản phẩm sản xuất; loại bỏ các sinh vật không mong muốn để ngăn chặn thiệt hại cho cây trồng, tòa nhà và kiến trúc khác. Nhóm này gồm các nghề thủ công và liên quan khác chưa được phân vào đâu trong nhóm 7 - Lao động thủ công và các nghề có liên quan khác.', array['Đảm bảo các biện pháp phòng ngừa an toàn; thực hiện các nhiệm vụ dưới nước; chất thuốc nổ vào hố bom; trộn hóa chất theo chỉ dẫn; vận hành và giám sát thiết bị phun thuốc trừ sâu và cỏ dại.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 160) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('811', 'Thợ vận hành máy móc, thiết bị xử lý khai khoáng giám sát và vận hành nhà xưởng, máy móc, thiết bị, dụng cụ cầm tay để khai thác đá và khoáng sản ra khỏi đất, xử lý khoáng sản và đá, khoan giếng, sản xuất và hoàn thiện sản phẩm xi măng, đá.', array['Thiết lập, vận hành và giám sát nhà xưởng, máy móc, thiết bị khai thác khoáng sản như máy khoan, máy móc và thiết bị phụ trợ, máy cắt, máy nghiền, máy bơm và máy móc, thiết bị khác; rửa, tách, chiết và loại bỏ chất thải để thu hồi khoáng sản; vận hành nhà xưởng, máy móc để sản xuất xi măng, bê tông, đá nhân tạo, bê tông đúc sẵn và các sản phẩm đá khác; giám sát hiệu suất của máy móc, phát hiện sự cố và khắc phục; thực hiện bảo dưỡng, sửa chữa và làm sạch nhà xưởng, máy móc, thiết bị; duy trì hồ sơ sản xuất.', 'Ghi chú:', 'Người giám sát khai thác mỏ được phân vào nhóm 3121 - Giám sát viên khai thác mỏ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 266) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('812', 'Thợ vận hành thiết bị xử lý và hoàn thiện kim loại vận hành và giám sát máy móc, thiết bị xử lý và điều khiển quá trình đơn chức năng để kiểm soát việc chuyển đổi, xử lý và hoàn thiện quặng khoáng sản và kim loại.', array['Thiết lập, chế biến và điều chỉnh máy móc xử lý và hoàn thiện kim loại; điều phối và giám sát hoạt động sản xuất và hoàn thiện kim loại; xác minh thiết bị gặp sự cố, giám sát máy móc, tiến hành kiểm tra quá trình vận hành định kỳ và bố trí bảo dưỡng; kiểm tra, thử nghiệm và phân tích sản phẩm mẫu; lưu trữ dữ liệu và viết nhật ký sản xuất.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 385) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('813', 'Thợ vận hành máy móc, thiết bị sản xuất hóa học và sản xuất sản phẩm phim ảnh vận hành và giám sát máy móc xử lý nhiều loại hóa chất và các thành phần khác để sản xuất dược phẩm, dung dịch vệ sinh, thuốc nổ, phim ảnh và các sản phẩm hóa học khác.', array['Vận hành và giám sát máy móc, thiết bị pha trộn, đóng gói, xử lý hóa chất và các sản phẩm hóa học khác để chuyển chúng thành các đặc tính mong muốn giúp cho sản xuất công nghiệp hoặc sản xuất ra các sản phẩm cuối cùng. Nhóm này bao gồm cả việc giám sát các lao động khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 428) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('814', 'Thợ vận hành máy sản xuất sản phẩm giấy, nhựa và cao su vận hành và giám sát máy nhào trộn các hợp chất cao su; sản xuất các thành phần và sản phẩm khác nhau từ cao su tự nhiên và tổng hợp; sản xuất các sản phẩm giấy khác từ giấy, bìa cứng và các chất liệu tương tự.', array['Vận hành và giám sát máy nhào trộn các hợp chất cao su; sản xuất các thành phần và sản phẩm khác nhau từ cao su tự nhiên và tổng hợp; vận hành và giám sát máy sản xuất các sản phẩm khác nhau từ giấy; kiểm tra sản phẩm đầu ra để phát hiện lỗi và đảm bảo thống nhất với thông số kỹ thuật; điều chỉnh cài đặt máy móc cho phù hợp.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 470) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('815', 'Thợ vận hành máy sản xuất nguyên liệu dệt, da lông thú và da thuộc giám sát và vận hành hệ thống máy gia công, xử lý và chế biến vải, sợi, chỉ, da hoặc lông thú; sản xuất, sửa chữa giày dép và hàng may mặc; sản xuất hay sấy khô quần áo, vật dụng bằng lông và da mềm.', array['Vận hành, giám sát các máy dệt và dệt kim xử lý sợi hoặc chỉ thành sản phẩm dệt, không dệt và dệt kim; vận hành và giám sát các máy chuẩn bị sợi, kéo sợi, quay, xoắn và xe sợi từ sợi tự nhiên; vận hành và giám sát máy khâu để sản xuất, sửa chữa, cải tiến hàng dệt may, lông thú, tổng hợp, da hoặc thêu các thiết kế trang trí lên trang phục hay chất liệu khác; vận hành và giám sát máy tẩy trắng, co, nhuộm và xử lý các loại sợi, chỉ hoặc vải khác; sấy khô trang phục, lông, thảm; vận hành và giám sát các máy chế biến da hoặc da gắn lông hay len; vận hành và giám sát các máy sản xuất, sửa chữa giày dép theo tiêu chuẩn, tùy chỉnh hoặc chỉnh hình vật dụng bằng da như va-li, cặp và túi xách.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 522) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('816', 'Thợ vận hành máy sản xuất thực phẩm và các thợ có liên quan thiết lập, vận hành, giám sát máy móc được dùng để giết mổ động vật, cắt thịt từ xác động vật, nướng, đông lạnh, hun nhiệt, nghiền, trộn, chế biến các loại thực phẩm, đồ uống và lá thuốc lá.', array['Vận hành, giám sát máy móc được sử dụng để kiềm chế, gây choáng, giết mổ động vật và để cắt thành thịt và thịt cá theo tiêu chuẩn; thiết lập, vận hành và giám sát máy móc và lò nướng để trộn, nướng và chế biến bánh mỳ và sản phẩm bánh kẹo khác; vận hành máy móc nghiền, trộn, nấu và lên men ngũ cốc, trái cây để sản xuất bia, rượu vang, mạch nha, dấm, men, và sản phẩm liên quan; vận hành thiết bị làm mứt, kẹo cứng, pho mai, bơ thực vật, mỳ ống, kem, xúc xích, sôcôla, tinh bột ngô, chất béo; vận hành thiết bị đông lạnh, sấy khô, nướng, hun khói, tiệt trùng, cô đặc thực phẩm và chất lỏng để chế biến thức ăn; trộn, nghiền, tách thực phẩm và chất lỏng với các thiết bị khuấy, ép, sàng, lọc; chế biến lá thuốc lá bằng máy để làm thuốc lá, xì gà và các sản phẩm thuốc lá khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 678) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('817', 'Thợ vận hành thiết bị chế biến gỗ và sản xuất giấy giám sát, vận hành và điều khiển máy móc để cưa gỗ, cắt gỗ ép, làm gỗ ván, sản xuất bột giấy và giấy hay các quy trình chế biến gỗ, bột giấy và giấy để sử dụng sau này.', array['Kiểm tra củi và gỗ thô để xác định kích thước, tình trạng, chất lượng và các đặc tính khác để quyết định việc cắt gỗ tốt nhất; vận hành thiết bị tự động vận chuyển gỗ qua máy quét laser nhằm xác định các kiểu cắt hiệu quả và có lợi nhất; phân loại, xếp và đặt các phôi gỗ lên băng chuyền và máy tiện từ xe tải để xử lý thành dăm, gỗ ép và bột giấy; vận hành và giám sát thiết bị sàng lọc, tẩy trắng, phân hủy, bể trộn, máy rửa và máy móc xử lý bột giấy khác để tiến hành một hay nhiều bước xử lý xenlulo; vận hành, giám sát máy móc, thiết bị chế biến và hoàn thiện giấy để sấy khô, cán giấy, ép mỏng, phủ, rọc, xén, cuộn hay tiến hành các bước chế biến giấy và hoàn thiện khác; giám sát bảng chỉ dẫn, đồng hồ đo, chỉ báo mức độ và dụng cụ, thiết bị khác để phát hiện sự cố máy móc, thiết bị và đảm bảo các bước quy trình được tiến hành theo chỉ dẫn kỹ thuật; vận hành, giám sát máy ép lõi gỗ dán, máy ép ván ép nóng và máy cắt gỗ ép; vận chuyển sản phẩm gỗ chế biến đến khu phân xưởng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 703) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('818', 'Thợ vận hành máy móc, thiết bị khác có thể gồm thợ vận hành máy móc sản xuất con chip silicon cùng với máy nối dây cáp và dây dẫn.', array['Giám sát lò nung, lò nấu thủy tinh và các máy móc thiết bị khác được sử dụng trong sản xuất thủy tinh, gốm, sứ, gạch, ngói; vận hành máy ủ, làm cứng hoặc trang trí thủy tinh và gốm sứ; bảo dưỡng và vận hành động cơ hơi nước, nồi hơi, tua bin và các thiết bị phụ trợ khác; vận hành và giám sát các máy cân, đóng gói và dán nhãn sản phẩm hoặc đổ đầy thùng chứa sản phẩm.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 746) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('820', 'Thợ lắp ráp lắp ráp các bộ phận hoặc linh kiện đúc sẵn để tạo thành các cụm lắp ráp, sản phẩm và thiết bị theo quy trình đặt ra nghiêm ngặt. Các sản phẩm trên có thể được chuyển từ một công nhân sang các dây chuyền lắp ráp tiếp theo. Mức độ thành thạo trong hầu hết các nghề trong nhóm này đòi hỏi các kỹ năng ở cấp độ kỹ năng thứ hai.', array['Lắp ráp các bộ phận thành nhiều loại sản phẩm và thiết bị khác nhau theo quy trình được đặt ra nghiêm ngặt; xem xét đơn đặt hàng công việc, thông số kỹ thuật, sơ đồ và bản vẽ để xác định vật liệu cần thiết và hướng dẫn lắp ráp; ghi dữ liệu sản xuất và vận hành trên các mẫu quy định; kiểm tra và thử nghiệm các thành phần lắp ráp hoàn chỉnh, lắp đặt dây và mạch điện; từ chối lắp ráp các thành phần bị lỗi.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 818) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('831', 'Lái các phương tiện vận chuyển trên đường ray và các công nhân có liên quan điều khiển hoặc hỗ trợ việc điều khiển các động cơ đầu máy để chuyên chở hành khách và hàng hóa; phụ trách và bảo vệ các chuyến tàu chở hàng đường sắt trên suốt chuyến đi; kiểm soát sự di chuyển của giao thông đường sắt bằng tín hiệu điều hành; bẻ ghi chuyển toa xe lửa sang đường khác và chuẩn bị tàu trong sân ga; chuẩn bị tàu để đẩy xe goòng than trong mỏ và kiểm soát sự chuyển động của chúng.', array['Lái hoặc hỗ trợ lái động cơ đường sắt; vận hành tín hiệu đường sắt, chuyển đổi đầu máy toa xe và chuẩn bị tàu trong sân ga; chuẩn bị tàu để đẩy xe goòng than trong hầm mỏ và kiểm soát chuyển động của chúng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 892) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('832', 'Lái xe con, xe tải và xe máy điều khiển và chăm sóc xe máy, xe ba bánh, xe ô tô con hoặc xe tải để vận chuyển hành khách, nguyên vật liệu hoặc hàng hóa.', array['Điều khiển và chăm sóc xe máy, xe ba bánh, xe ô tô con hoặc xe tải để chuyên chở nguyên vật liệu, hàng hóa hoặc hành khách.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 925) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('833', 'Lái xe tải hạng vừa, hạng nặng, xe buýt và xe điện điều khiển và chăm sóc xe tải hạng vừa, hạng nặng và xe buýt hoặc xe điện trên đường để vận chuyển hàng hóa, chất lỏng, vật liệu nặng, thư hoặc hành khách.', array['Điều khiển và chăm sóc xe tải hạng nặng, hạng vừa, xe buýt hoặc xe điện trên đường phố để vận chuyển hàng hóa, chất lỏng, vật liệu nặng, thư hoặc hành khách.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 969) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('834', 'Thợ vận hành thiết bị chuyển động điều khiển, vận hành, giám sát máy móc, thiết bị cơ giới chuyên dùng để giải phóng mặt bằng, chuẩn bị đất, đào, di chuyển, rải đất, đá và các vật liệu tương tự; nâng hoặc di chuyển các vật nặng.', array['Chuẩn bị và định vị máy móc để vận hành, điều chỉnh tốc độ, độ cao, độ sâu của dụng cụ; điều khiển và vận hành máy móc di động; vận hành phụ tùng để nâng, xoay, nhả cây, khúc gỗ, đất và các vật nặng hoặc vật liệu khác; vận hành và giám sát xe nâng, cần cẩu cố định hoặc di động trong các hoạt động xây dựng, vận chuyển, lưu trữ; bảo dưỡng máy móc và thực hiện sửa chữa nhỏ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1003) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('835', 'Thủy thủ trên tàu và những thợ có liên quan (trừ lao động trên tàu đánh bắt thủy sản) thực hiện các nhiệm vụ trên boong tàu và các nhiệm vụ tương tự trên các phương tiện tàu thuyền khác.', array['Đứng quan sát trên biển và khi ra vào bến tàu, bến cảng hoặc vùng nước hẹp khác; lái tàu theo sự hướng dẫn; xử lý dây thừng, dây kim loại và vận hành các thiết bị neo đậu; bảo dưỡng và trong một vài trường hợp vận hành các thiết bị tàu thuyền, thiết bị chở hàng, thiết bị cứu hộ và chữa cháy; thực hiện các công việc làm sạch, cạo, sơn boong tàu, thân tàu và các nhiệm vụ bảo dưỡng khác theo yêu cầu; sửa soạn, sắp xếp hàng hóa đóng gói lên tàu, trang bị thiết bị xử lý hàng hóa.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1072) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('911', 'Người quét dọn và giúp việc gia đình, khách sạn và văn phòng quét dọn, hút bụi, rửa, đánh bóng, chăm sóc đồ vải gia dụng và mua sắm đồ dùng gia đình; thực hiện các nhiệm vụ khác nhau để giữ sạch sẽ, gọn gàng nội thất, đồ đạc của khách sạn, văn phòng và các cơ sở khác cũng như của máy bay, tàu hỏa, xe buýt và các phương tiện tương tự.', array['Quét hoặc hút bụi, rửa và đánh bóng sàn nhà, đồ nội thất và các đồ khác trong khách sạn, văn phòng và trong các cơ sở khác; dọn giường, cung cấp khăn tắm, xà phòng và các đồ có liên quan; giúp chuẩn bị bữa ăn và rửa bát; làm sạch, khử trùng, khử mùi nhà bếp, phòng tắm và nhà vệ sinh.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1095) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('912', 'Thợ rửa xe cộ, làm sạch cửa sổ, giặt là và những người làm công việc dọn dẹp bằng tay khác lau chùi cửa sổ, tủ trưng bày hoặc các bề mặt khác của tòa nhà, xe cộ; giặt, là hoặc giặt khô vải lanh và các loại vải dệt khác bằng tay.', array['Làm sạch, rửa, đánh bóng xe; rửa cửa sổ, các bề mặt kính bằng nước hoặc các dung dịch khác nhau, làm khô và đánh bóng chúng; giặt là vải lanh, quần áo, vải dệt và các mặt hàng tương tự bằng tay trong tiệm giặt hoặc trong các cơ sở khác; làm sạch quần áo, vải, đồ da và các mặt hàng tương tự bằng tay với các dung dịch hóa chất trong các tiệm giặt hoặc các cơ sở khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1138) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('920', 'Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản thực hiện các nhiệm vụ đơn giản và thường xuyên trong sản xuất cây trồng và vật nuôi; trồng trọt, duy trì vườn và công viên; khai thác và bảo tồn rừng; thực hiện các hoạt động khai thác và nuôi trồng thủy sản. Hầu hết các nghề trong nhóm này yêu cầu các kỹ năng ở cấp độ kỹ năng thứ nhất.', array['Đào, cào và xúc bằng dụng cụ cầm tay; bốc xếp và xếp chồng vật tư sản xuất và các vật liệu khác; tưới nước, tỉa thưa, làm cỏ và chăm sóc cây trồng bằng tay hoặc sử dụng dụng cụ cầm tay; trồng, thu hoạch, hái và thu gom sản phẩm bằng tay; cho ăn, uống nước, làm sạch động vật và giữ cho khu nhà của chúng sạch sẽ; giám sát chăn nuôi, báo cáo về tình trạng của chúng; chuẩn bị và vận hành lưới, dây chuyền, các thiết bị câu cá và boong khác; phân loại, bó và đóng gói sản phẩm vào container; thực hiện sửa chữa nhỏ trên đồ đạc, tòa nhà, thiết bị, tàu và hàng rào.', 'Ghi chú:', 'Lao động trong nông nghiệp tự cung tự cấp thực hiện một số nhiệm vụ đơn giản và thường xuyên, thường theo sự chỉ đạo của người khác được phân loại trong nhóm 920 - Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản. Lao động trong một môi trường nông nghiệp có nhiệm vụ chính là lấy nước và kiếm củi được phân loại trong nhóm 9624 - Người thu gom nước và củi.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1192) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('931', 'Lao động trong ngành khai khoáng và xây dựng tiến hành các nhiệm vụ thủ công, giản đơn và thường xuyên trong lĩnh vực khai thác than, quặng đá và xây dựng.', array['Đào và lấp hố, mương bằng dụng cụ cầm tay; xúc và rải vật liệu, cát, đất và sỏi; phân loại, xếp, dỡ và lưu kho dụng cụ, vật liệu và thiết bị rồi vận chuyển chúng quanh địa điểm làm việc; làm sạch máy móc, thiết bị, dụng cụ, nơi làm việc và loại bỏ phế thải.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1318) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('932', 'Lao động trong công nghiệp thực hiện nhiều nhiệm vụ thủ công, giản đơn và thường xuyên trong sản xuất để hỗ trợ việc vận hành và lắp ráp máy móc.', array['Đóng gói vật liệu và các sản phẩm khác bằng tay; đóng chai, hộp, túi và vật chứa đựng khác bằng tay; dán nhãn sản phẩm và thùng chứa bằng tay; bốc dỡ hàng trên xe; vận chuyển hàng hóa, vật tư và thiết bị đến khu làm việc; vệ sinh máy móc, thiết bị, dụng cụ; phân loại sản phẩm và phụ tùng bằng tay.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1371) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('933', 'Lao động vận chuyển và kho hàng đẩy xe và các phương tiện tương tự, điều khiển xe do gia súc kéo và máy kéo để vận chuyển hành khách hoặc hàng hóa; thực hiện xếp dỡ hàng hóa và hành lý; bày hàng hóa lên giá hoặc lên các kệ hàng.', array['Đẩy xe và các phương tiện tương tự, điều khiển xe do gia súc kéo và máy kéo để vận chuyển hành khách hoặc hàng hóa; thực hiện bốc xếp hàng hóa bằng tay; bày hàng hóa lên giá hoặc lên các kệ hàng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1406) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('940', 'Người phụ giúp chuẩn bị thực phẩm chuẩn bị và nấu các món đơn giản hoặc đặt một ít thực phẩm hoặc đồ uống đã qua chế biến, dọn bàn, phòng bếp và rửa bát. Hầu hết các nghề trong nhóm này đều yêu cầu các kỹ năng ở cấp độ kỹ năng thứ nhất.', array['- Chuẩn bị các loại thực phẩm, đồ uống đơn giản hoặc chế biến sẵn như bánh mỳ kẹp, pizza, khoai tây chiên, salad và cà phê;', '- Rửa, thái, đong và trộn thực phẩm để nấu ăn;', '- Sử dụng các thiết bị nấu nướng như lò nướng, lò vi sóng, nồi chiên…;', '- Vệ sinh phòng bếp, khu vực chuẩn bị và phục vụ đồ ăn;', '- Làm sạch các dụng cụ nấu ăn và dụng cụ dùng chung trong nhà bếp và nhà hàng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1478) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('951', 'Lao động trên đường phố và lao động có liên quan cung cấp nhiều dịch vụ khác nhau trên đường phố và những nơi công cộng với các công việc như đánh giày, rửa cửa kính ô tô, chạy việc vặt, phát tờ rơi, trông giữ tài sản và cung cấp các dịch vụ đường phố tại chỗ khác.', array['- Đảm bảo vật liệu cần thiết để thực hiện dịch vụ;', '- Tiếp cận khách hàng trên đường phố để cung cấp dịch vụ;', '- Làm sạch và đánh bóng giày;', '- Làm sạch và đánh bóng cửa kính ô tô;', '- Chạy việc vặt;', '- Hỗ trợ tài xế tìm bãi đỗ và đảm bảo xe không bị hư hỏng khi vắng mặt tài xế;', '- Phát tờ rơi và báo miễn phí;', '- Nhận thanh toán ngay.']::text[], array['- Người bảo vệ xe', '- Thợ rửa cửa kính ô tô', '- Người làm việc vặt', '- Người phát báo miễn phí', '- Người phát tờ rơi', '- Người đánh giày']::text[], array['- Nhân viên phục vụ ở các trạm dịch vụ - 5245', '- Người giao tờ rơi và báo - 9621']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1530) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('952', 'Người bán hàng rong trên đường phố (trừ đồ ăn) thường bán một số lượng hàng hóa nhất định (không bao gồm đồ ăn tiêu thụ ngay) trên đường phố và tại địa điểm công cộng như nhà ga, rạp hát, rạp chiếu phim.', array['- Mua hay nhận các mặt hàng để bán hoặc làm các mặt hàng đơn giản;', '- Xếp và dỡ giỏ, khay, xe đẩy, xe đạp, xe nâng tay hoặc các phương tiện khác để chuyên chở hàng hóa đến khu phố hay địa điểm công cộng như nhà ga, rạp phim;', '- Bày bán hàng hóa hay chào mời để thu hút khách;', '- Tiếp cận khách hàng tiềm năng trên đường phố hay đến tận nhà để chào bán sản phẩm;', '- Nhận thanh toán ngay.']::text[], array['- Người bán rong', '- Người bán báo', '- Người bán dạo']::text[], array['- Người bán hàng trong chợ - 5211', '- Người bán hàng trên phố - 5211', '- Người bán đồ ăn trên đường phố - 5212', '- Nhân viên bán hàng tận nhà - 5243', '- Người phát báo miễn phí - 9510', 'Ghi chú:', 'Những người bán thực phẩm tươi sống không dùng để tiêu thụ ngay (như trái cây, rau, thịt, sữa) được phân vào nhóm 5211 - Người bán hàng trong quầy hàng và tại chợ. Những người bán hàng rong trên đường và tại chợ với nhiều loại thức ăn chế biến sẵn và các mặt hàng thực phẩm để tiêu dùng ngay được phân vào nhóm 5246 - Nhân viên phục vụ đồ ăn uống. Những người bán thực phẩm và đồ uống trên đường phố và địa điểm công cộng từ xe đẩy, xe tải, khay hoặc giỏ được phân vào nhóm 5212 - Người bán đồ ăn trên đường phố. Những người bán hàng rong trên đường phố và địa điểm công cộng các mặt hàng phi thực phẩm (hoặc các mặt hàng thực phẩm không dễ hỏng được đóng gói sẵn như bánh kẹo) từ xe đẩy, xe tải, khay, giỏ được phân vào nhóm 9520 - Người bán hàng rong trên đường phố (trừ đồ ăn).']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1551) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('961', 'Người thu dọn vật thải thu gom, xử lý và tái chế rác thải từ các tòa nhà, sân vườn, đường phố và các nơi công cộng khác hoặc quét dọn đường phố và các nơi công cộng khác.', array['Thu nhặt, bốc dỡ rác thải; quét dọn đường phố, công viên và các nơi công cộng; phân loại và tái chế rác thải như giấy, thủy tinh, nhựa hoặc nhôm.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1574) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('962', 'Lao động giản đơn khác giao hàng và đưa thư; thực hiện một loạt các nhiệm vụ bảo trì và sửa chữa đơn giản; thu tiền và máy bán hàng tự động; đọc đồng hồ đo; thu gom nước và củi; thu thập và phát hành vé cho bãi đậu xe hoặc các sự kiện.', array['chặt củi, lấy nước và củi; làm sạch và bảo trì các tòa nhà, mặt bằng và cơ sở vật chất; gửi thư, giao hàng và các mặt hàng khác trong hoặc giữa các cơ sở hoặc nơi khác; phát hành và thu vé, vé; tính phí gửi xe; lấp đầy khu vực lưu trữ của máy bán hàng tự động và thu tiền từ các khay đựng; đọc đồng hồ đo điện, ga hoặc nước và ghi lại mức tiêu thụ.']::text[], '{}'::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1616) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0110', '- Sĩ quan Quân đội nhân dân Việt Nam (sau đây gọi chung là sĩ quan) là cán bộ của Đảng Cộng sản Việt Nam và Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam, hoạt động trong lĩnh vực quân sự, được Nhà nước phong quân hàm cấp Úy, cấp Tá, cấp Tướng.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0120', 'Hạ sĩ quan, binh sĩ lực lượng quân đội là công dân Việt Nam tham gia quân đội được phong, thăng cấp bậc hàm Thượng sĩ, Trung sĩ, Hạ sĩ, Binh nhất, Binh nhì.', '{}'::text[], '{}'::text[], array['- Công việc được tổ chức bởi những người làm việc dân sự của các cơ sở chính phủ liên quan đến các vấn đề quốc phòng;', '- Thanh tra hải quan và các thành viên của biên giới hoặc các dịch vụ dân sự khác.']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1708) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0130', 'Lực lượng khác trong quân đội bao gồm: quân nhân chuyên nghiệp, công nhân viên chức quốc phòng,...
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0210', '- Sĩ quan lực lượng công an gồm có: sĩ quan nghiệp vụ và sĩ quan chuyên môn kỹ thuật.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0220', 'Hạ sĩ quan, chiến sĩ lực lượng công an gồm có: Hạ sĩ quan nghiệp vụ, hạ sĩ quan chuyên môn kỹ thuật, hạ sĩ quan, chiến sĩ nghĩa vụ.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0230', 'Lực lượng khác trong công an như công nhân công an. Công nhân công an là công dân Việt Nam có trình độ chuyên môn kỹ thuật, được tuyển dụng vào làm việc trong Công an nhân dân mà không thuộc diện được phong cấp bậc hàm sĩ quan, hạ sĩ quan, chiến sĩ.', '{}'::text[], '{}'::text[], array['- Thanh tra hải quan và các thành viên của biên giới hoặc các dịch vụ dân sự quân đội khác;', '- Nhân viên an ninh;', '- Nhân viên dịch vụ bảo vệ khác chưa được phân vào đâu như: thám tử tư, nhân viên bảo vệ rừng,…']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1739) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0310', '- Lực lượng cơ yếu là một trong những lực lượng chuyên trách bảo vệ thông tin bí mật nhà nước, hoạt động cơ mật đặc biệt, thuộc lĩnh vực an ninh quốc gia; có chức năng tham mưu cho Đảng, Nhà nước về công tác cơ yếu, thực hiện hoạt động cơ yếu; bảo đảm tuyệt đối bí mật, an toàn, chính xác, kịp thời thông tin phục vụ sự lãnh đạo của Đảng, quản lý của Nhà nước, chỉ đạo, chỉ huy của lực lượng vũ trang nhân dân trong mọi tình huống; chủ động phòng ngừa, tham gia đấu tranh với các hoạt động mã thám gây phương hại đến an ninh quốc gia, lợi ích của Nhà nước, quyền và lợi ích hợp pháp của cơ quan, tổ chức, cá nhân.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('0320', 'Lực lượng vũ trang khác bao gồm: dân quân tự vệ.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2111', 'Nhà vật lý học và thiên văn học tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động liên quan đến vật chất, không gian, thời gian, năng lượng, các lĩnh vực và mối liên hệ giữa các hiện tượng vật lý này. Họ áp dụng kiến ​​thức khoa học liên quan đến vật lý và thiên văn học trong các lĩnh vực công nghiệp, y tế, quân sự hoặc các lĩnh vực khác.', array['- Tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết, thiết bị, phần mềm và phương pháp hoạt động liên quan đến vật lý và thiên văn học;', '- Tiến hành các thí nghiệm, kiểm tra và phân tích về cấu trúc và tính chất của vật chất trong các lĩnh vực như cơ học, nhiệt động lực học, điện tử, truyền thông, sản xuất và phân phối điện, khí động học, quang học và laser, viễn thám, y học, siêu âm, từ tính và vật lý hạt nhân;', '- Đánh giá kết quả điều tra, thí nghiệm và đưa ra kết luận, chủ yếu sử dụng các kỹ thuật và mô hình toán học;', '- Áp dụng các nguyên tắc, kỹ thuật và quy trình để phát triển hoặc cải tiến các ứng dụng công nghiệp, y tế, quân sự và các ứng dụng thực tế khác về các nguyên tắc và kỹ thuật của vật lý hoặc thiên văn học;', '- Đảm bảo cung cấp phóng xạ an toàn và hiệu quả (ion hóa và không ion hóa) cho bệnh nhân để đạt được kết quả chẩn đoán hoặc điều trị theo quy định của bác sĩ y khoa;', '- Đảm bảo đo lường và mô tả chính xác các đại lượng vật lý được sử dụng trong các ứng dụng y tế;', '- Thử nghiệm, vận hành và đánh giá thiết bị được sử dụng trong các ứng dụng như chẩn đoán hình ảnh, điều trị y tế và đo liều lượng;', '- Tư vấn với các bác sĩ y khoa và các chuyên gia chăm sóc sức khỏe khác trong việc tối ưu hóa sự cân bằng giữa các tác động có lợi và có hại của bức xạ;', '- Quan sát, phân tích, giải thích các hiện tượng thiên thể và phát triển các phương pháp, mô hình số và kỹ thuật để mở rộng kiến ​​thức về các lĩnh vực như điều hướng, liên lạc vệ tinh, thám hiểm không gian, thiên thể và bức xạ vũ trụ;', '- Xây dựng, thực hiện, duy trì các tiêu chuẩn và quy trình để đo lường các hiện tượng vật lý và sử dụng công nghệ hạt nhân trong các ứng dụng công nghiệp và y tế;', '- Chuẩn bị các bài báo và báo cáo khoa học.']::text[], array['- Nhà thiên văn học', '- Nhà vật lý y tế', '- Nhà vật lý hạt nhân', '- Nhà vật lý học']::text[], array['- Bác sĩ ung bướu - 2212', '- Bác sĩ X quang - 2212', '- Bác sĩ chuyên khoa (y học hạt nhân) - 2212', '- Kỹ thuật viên X quang - 3211', 'Ghi chú:', 'Cần lưu ý rằng các nhà y tế được phân loại trong nhóm 22: Nhà chuyên môn về sức khỏe.']::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 168) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2112', 'Nhà khí tượng học chuẩn bị các dự báo thời tiết ngắn hạn hoặc dài hạn được sử dụng trong hàng không, hàng hải, nông nghiệp, các lĩnh vực khác và cung cấp thông tin cho công chúng. Họ tiến hành các nghiên cứu liên quan đến thành phần, cấu trúc và động lực của khí quyển.', array['- Nghiên cứu hướng và tốc độ chuyển động của không khí, áp suất, nhiệt độ, độ ẩm, sự biến đổi vật lý và hóa học của các chất ô nhiễm và các hiện tượng khác như sự hình thành và lượng mưa của mây, nhiễu điện hoặc bức xạ mặt trời;', '- Nghiên cứu dữ liệu được thu thập từ các trạm khí tượng, ra-đa, hình ảnh vệ tinh và đầu ra mô hình máy tính để vẽ đồ thị và dự báo điều kiện thời tiết;', '- Chuẩn bị và báo cáo các bản đồ thời tiết ngắn hạn hoặc dài hạn, dự báo và cảnh báo liên quan đến các hiện tượng khí quyển như lốc xoáy, bão và các mối nguy hiểm khác đến tính mạng, tài sản đồng thời phổ biến thông tin về điều kiện khí quyển thông qua nhiều phương tiện truyền thông bao gồm đài phát thanh truyền hình, báo in và Internet;', '- Tiến hành các thí nghiệm về phân tán sương mù, tạo mây, tăng cường mưa và các loại chương trình điều chỉnh thời tiết khác;', '- Phát triển và thử nghiệm các mô hình máy tính toán học về thời tiết và khí hậu để sử dụng thử nghiệm hoặc vận hành;', '- Tham gia các nghiên cứu về ảnh hưởng của thời tiết đến môi trường;', '- Phân tích tác động của các dự án công nghiệp và hoạt động của con người đến khí hậu và chất lượng không khí, đồng thời làm việc với các tổ chức khoa học xã hội, kỹ thuật và kinh tế để phát triển các chiến lược giảm thiểu phù hợp;', '- Tham gia vào việc thiết kế và phát triển các thiết bị và quy trình mới để thu thập dữ liệu khí tượng và viễn thám hoặc cho các ứng dụng liên quan;', '- Tiến hành nghiên cứu, cải tiến, phát triển các khái niệm, lý thuyết và phương pháp hoạt động liên quan đến thành phần, cấu trúc và động lực của khí quyển; chuẩn bị các bài báo khoa học và báo cáo về kết quả của nghiên cứu này.']::text[], array['- Nhà khí hậu học', '- Nhà khí tượng thủy văn', '- Nhà khí tượng học', '- Nhà dự báo thời tiết', '- Nghiên cứu viên khí tượng học']::text[], '{}'::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 194) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2113', 'Nhà hóa học tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động; áp dụng kiến ​​thức khoa học liên quan đến hóa học để phát triển kiến thức hoặc sản phẩm mới và để kiểm soát chất lượng và quy trình.', array['- Tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, công cụ, lý thuyết và phương pháp hoạt động liên quan đến hóa học;', '- Tiến hành các thí nghiệm, thử nghiệm và phân tích để điều tra thành phần hóa học, các biến đổi năng lượng và hóa học trong các chất, vật liệu và sản phẩm tự nhiên hoặc tổng hợp khác nhau;', '- Xây dựng các quy trình kiểm soát môi trường, kiểm soát chất lượng và các quy trình khác cho nhà sản xuất hoặc người sử dụng;', '- Tiến hành các chương trình thu thập, phân tích mẫu và dữ liệu để xác định và định lượng các chất độc hại đối với môi trường;', '- Tham gia vào các dự án nghiên cứu và phát triển liên ngành với các kỹ sư hóa học, nhà sinh học, nhà vi sinh vật học, nhà nông học, nhà địa chất học hoặc các chuyên gia khác;', '- Sử dụng vi sinh vật để chuyển đổi các chất thành các hợp chất mới;', '- Xác định các cách tăng cường và kết hợp vật liệu hoặc phát triển các vật liệu mới;', '- Tái tạo và tổng hợp các chất có trong tự nhiên và tạo ra các chất nhân tạo mới;', '- Chuẩn bị các bài báo và báo cáo khoa học.']::text[], array['- Nhà hóa học', '- Trưởng phòng nghiên cứu hóa học']::text[], array['- Nhà hóa sinh - 2131', '- Nhà dược lý học - 2131', '- Dược sĩ - 2262']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Kiểm tra và phân tích hóa chất.', '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 212) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2114', 'Nhà địa chất, địa vật lý tiến hành nghiên cứu, cải tiến hoặc phát triển các khái niệm, lý thuyết và phương pháp hoạt động; áp dụng kiến ​​thức khoa học liên quan đến địa chất, địa vật lý trong các lĩnh vực như thăm dò, khai thác dầu khí, khoáng sản, bảo tồn nước, xây dựng dân dụng, viễn thông và hàng hải; đánh giá và giảm thiểu tác động của các dự án phát triển và xử lý chất thải đối với môi trường.', array['- Tiến hành nghiên cứu, cải tiến, phát triển các khái niệm, lý thuyết và phương pháp hoạt động liên quan đến địa chất và địa vật lý;', '- Nghiên cứu thành phần và cấu trúc của vỏ trái đất, kiểm tra đá, khoáng chất, hóa thạch và các vật liệu khác để xác định các quá trình ảnh hưởng đến sự phát triển của trái đất, theo dõi sự tiến hóa của thời kỳ trước, thiết lập tính chất và niên đại của sự hình thành địa chất và đánh giá các ứng dụng thương mại của chúng;', '- Diễn giải dữ liệu nghiên cứu và chuẩn bị báo cáo địa chất, bản đồ, biểu đồ và sơ đồ;', '- Áp dụng kiến ​​thức địa chất cho các vấn đề gặp phải trong các dự án xây dựng dân dụng như xây dựng đập, cầu, đường hầm, các tòa nhà lớn và các dự án cải tạo đất;', '- Sử dụng các chương trình viễn thám khác nhau để điều tra và đo lường các lực địa chấn, lực hấp dẫn, điện, nhiệt và từ trường ảnh hưởng đến trái đất;', '- Ước tính trọng lượng, kích thước và khối lượng của trái đất cũng như thành phần và cấu trúc bên trong của nó đồng thời nghiên cứu tính chất, hoạt động và khả năng dự đoán của núi lửa, sông băng và động đất;', '- Lập biểu đồ từ trường trái đất và áp dụng dữ liệu này và các dữ liệu được thu thập khác để phát sóng, điều hướng và các mục đích khác;', '- Nghiên cứu, đo lường các đặc tính vật lý của biển và khí quyển và mối liên hệ của chúng chẳng hạn như sự trao đổi nhiệt năng;', '- Định vị và xác định bản chất và mức độ của các mỏ dầu, khí đốt và khoáng sản bằng cách sử dụng các phương pháp đo địa chấn, trọng lực, từ tính, điện hoặc đo bức xạ;', '- Xác định cặn lắng của vật liệu xây dựng, các đặc tính và sự phù hợp của chúng để sử dụng làm cốt liệu bê tông, lấp đường hoặc cho các ứng dụng khác;', '- Nghiên cứu sự chuyển động, phân bố, các đặc tính vật lý của nước ngầm và mặt nước;', '- Tư vấn trong các lĩnh vực như quản lý chất thải, lựa chọn tuyến đường, địa điểm và khôi phục các vị trí bị ô nhiễm.']::text[], array['- Nhà địa chất hải dương học', '- Nhà địa chất', '- Nhà địa vật lý hải dương học', '- Nhà địa vật lý', '- Nhà địa chất học']::text[], '{}'::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 232) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2121', 'Nhà toán học tiến hành nghiên cứu, cải tiến, phát triển các khái niệm, lý thuyết toán học và tính toán, các phương pháp và kỹ thuật vận hành; tư vấn hoặc tham gia vào ứng dụng thực tế trong các lĩnh vực như kỹ thuật, kinh doanh, xã hội và các ngành khoa học khác.', array['- Nghiên cứu, cải tiến và phát triển các lý thuyết và kỹ thuật toán học, tính toán;', '- Tư vấn hoặc áp dụng các nguyên tắc, mô hình và kỹ thuật toán học cho một loạt các nhiệm vụ trong các lĩnh vực kỹ thuật, khoa học tự nhiên, xã hội hoặc đời sống;', '- Tiến hành phân tích logic các vấn đề quản lý, đặc biệt là về hiệu quả đầu vào - đầu ra và xây dựng các mô hình toán học của từng vấn đề được lập trình và giải bằng máy tính;', '- Chuẩn bị các bài báo và báo cáo khoa học;', '- Giám sát công việc của các trợ lý toán học và nhân viên tính toán.']::text[], array['- Chuyên gia tính toán', '- Nhà toán học']::text[], array['- Trợ lý chuyên gia tính toán - 3314', '- Trợ lý toán học - 3314', '- Nhân viên tính toán - 4312']::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 256) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2122', 'Nhà thống kê tiến hành nghiên cứu, cải tiến, phát triển các khái niệm, lý thuyết thống kê, phương pháp và kỹ thuật vận hành; tư vấn hoặc tham gia vào ứng dụng thực tế trong các lĩnh vực như kỹ thuật, kinh doanh, xã hội và các ngành khoa học khác.', array['- Áp dụng toán học, thống kê, lý thuyết xác suất và rủi ro để đánh giá tác động tài chính tiềm năng của các sự kiện trong tương lai;', '- Lập kế hoạch, thiết kế bảng hỏi, tổ chức các cuộc điều tra và các thu thập thống kê khác;', '- Đánh giá, xử lý, phân tích, giải thích dữ liệu thống kê và chuẩn bị chúng để công bố;', '- Tư vấn hoặc áp dụng các phương pháp thu thập dữ liệu khác nhau, phương pháp và kỹ thuật thống kê, xác định độ tin cậy của các kết quả, đặc biệt là trong các lĩnh vực như kinh doanh, y học cũng như trong các lĩnh vực khác của khoa học tự nhiên, xã hội hoặc đời sống;', '- Dự báo thống kê dựa trên các dữ liệu thống kê;', '- Chuẩn bị các bài báo và báo cáo khoa học;', '- Giám sát công việc của các trợ lý thống kê và nhân viên thống kê.']::text[], array['- Nhà thống kê nhân khẩu học', '- Nhà chuyên môn về thu thập, xử lý, phân tích dữ liệu thống kê', '- Nhà thống kê']::text[], array['- Nhà phân tích hệ thống thông tin - 2511', '- Trợ lý thống kê - 3314', '- Nhân viên thống kê - 4312']::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 271) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2131', 'Nhà sinh vật học, thực vật học, động vật học và các chuyên môn liên quan nghiên cứu các sinh vật sống, sự tương tác của chúng với nhau và với môi trường đồng thời áp dụng kiến ​​thức này để giải quyết các vấn đề về sức khỏe và môi trường của con người. Họ làm việc trong các lĩnh vực đa dạng như thực vật học, động vật học, sinh thái học, sinh học biển, di truyền học, miễn dịch học, dược lý học, độc chất học, sinh lý học, vi khuẩn học và vi rút học.', array['- Thực hiện nghiên cứu trong các phòng thí nghiệm và trong thực địa để nâng cao kiến ​​thức khoa học về sinh vật sống, khám phá thông tin mới, kiểm tra các giả thuyết, giải quyết các vấn đề trong các lĩnh vực như môi trường, nông nghiệp, y tế; phát triển các sản phẩm, quy trình mới và kỹ thuật sử dụng dược phẩm, nông nghiệp và môi trường;', '- Thiết kế và tiến hành thí nghiệm và thử nghiệm;', '- Thu thập mẫu vật, dữ liệu của người, động vật, côn trùng và thực vật đồng thời nghiên cứu nguồn gốc, sự phát triển, dạng hóa học và vật lý, cấu trúc, thành phần cũng như các quá trình sống và sinh sản của chúng;', '- Kiểm tra các sinh vật sống bằng nhiều thiết bị, dụng cụ, công nghệ và kỹ thuật chuyên biệt như kính hiển vi điện tử, máy đo từ xa, hệ thống định vị toàn cầu, công nghệ sinh học, hình ảnh vệ tinh, kỹ thuật di truyền, phân tích hình ảnh kỹ thuật số, phản ứng chuỗi polymerase và mô hình máy tính;', '- Xác định, phân loại, ghi chép, giám sát các sinh vật sống và duy trì cơ sở dữ liệu;', '- Viết các bài báo, báo cáo khoa học trình bày chi tiết nghiên cứu và bất kỳ phát hiện mới nào được công bố cho cộng đồng khoa học trên các tạp chí khoa học hoặc tại các hội nghị để xem xét và tranh luận thêm;', '- Thiết kế và thực hiện các đánh giá tác động môi trường để xác định những thay đổi gây ra bởi các yếu tố tự nhiên hoặc con người;', '- Tư vấn cho chính phủ, tổ chức, doanh nghiệp trong các lĩnh vực như bảo tồn, quản lý tài nguyên thiên nhiên, tác động của biến đổi khí hậu và ô nhiễm.']::text[], array['- Nhà nghiên cứu hành vi động vật', '- Nhà vi khuẩn học', '- Nhà hóa sinh', '- Nhà sinh học', '- Nhà nghiên cứu y sinh', '- Nhà chuyên môn về công nghệ sinh học', '- Nhà thực vật học', '- Nhà di truyền học tế bào', '- Nhà sinh vật học biển', '- Nhà vi sinh vật học', '- Nhà sinh học phân tử', '- Nhà di truyền học phân tử', '- Nhà dược lý học', '- Nhà động vật học']::text[], array['- Nhà sinh thái học - 2133', 'Ghi chú', 'Các chuyên gia nghiên cứu y học tham gia nghiên cứu y sinh sử dụng các sinh vật sống và không thực hiện lâm sàng được phân loại trong nhóm 2131: Nhà sinh học, thực vật học, động vật học và các chuyên môn liên quan. Những người thực hiện lâm sàng được phân loại trong nhóm 221: Bác sĩ y khoa.']::text[], null, '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 292) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2132', 'Nhà tư vấn nông, lâm nghiệp và thủy sản nghiên cứu, hỗ trợ, tư vấn về quản lý trang trại, lâm nghiệp và thủy sản bao gồm trồng trọt, bón phân, thu hoạch, thoái hóa đất, phòng chống dịch bệnh, dinh dưỡng, luân canh và tiếp thị. Họ phát triển các kỹ thuật để tăng năng suất đồng thời nghiên cứu và phát triển các kế hoạch, chính sách quản lý đất đai và thủy sản.', array['- Thu thập, phân tích dữ liệu và mẫu liên quan đến sản phẩm, thức ăn, chất lượng đất, nước và các yếu tố khác ảnh hưởng đến sản xuất nông nghiệp, lâm nghiệp hoặc thủy sản;', '- Tư vấn về các kỹ thuật cải tiến sản xuất cây trồng, vật nuôi và cá; lựa chọn các phương án sản xuất thay thế;', '- Tư vấn về dịch bệnh gia súc và cây trồng; kiểm soát sâu bệnh, cỏ dại, cải tạo đất, chương trình chăn nuôi và cho ăn;', '- Nghiên cứu các yếu tố môi trường ảnh hưởng đến sản xuất cây trồng thương mại, tăng trưởng đồng cỏ, chăn nuôi, trữ lượng cá, sự tăng trưởng và phát triển của cây rừng;', '- Nghiên cứu ảnh hưởng của kỹ thuật canh tác, đất, côn trùng, dịch bệnh và thực hành nghề cá đối với năng suất vật nuôi, cây trồng, lâm nghiệp và thủy sản;', '- Nghiên cứu sự di cư, tăng trưởng, kiếm ăn và sinh sản của cá; đưa ra các phương pháp thu thập, thụ tinh và ấp trứng cá;', '- Nghiên cứu các đặc điểm, khả năng sử dụng và năng suất của đất; áp dụng các kết quả để phát triển các phương pháp canh tác nông nghiệp, làm vườn và cải tiến lâm nghiệp;', '- Xây dựng các quy trình và kỹ thuật để giải quyết các vấn đề nông nghiệp và nâng cao hiệu quả sản xuất;', '- Quản lý tài nguyên rừng và thủy sản để tối đa hóa lợi ích lâu dài về thương mại, giải trí và môi trường của chúng;', '- Nghiên cứu việc nhân giống và nuôi trồng cây rừng, phương pháp cải thiện sự tăng trưởng của trữ lượng và ảnh hưởng của việc tỉa thưa đến sản lượng rừng;', '- Điều tra, lập kế hoạch và thực hiện các quy trình quản lý để đối phó với các tác động của hỏa hoạn, lũ lụt, hạn hán, xói mòn đất, sâu bệnh và dịch bệnh;', '- Chuẩn bị các báo cáo khoa học, thực hiện các buổi tư vấn thông tin và các bài giảng nông nghiệp, lâm nghiệp và thủy sản.']::text[], array['- Nhà nông học', '- Nhà cố vấn thủy sản', '- Nhà cố vấn lâm nghiệp', '- Nhà khoa học lâm nghiệp', '- Nhà khoa học làm vườn', '- Nhà lâm sinh', '- Nhà khoa học đất']::text[], '{}'::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Nuôi trồng thủy sản nước mặn, nước lợ, nuôi trồng thủy sản nước ngọt, chăn nuôi gia súc, gia cầm, trồng cây cao su, trồng cây thuốc lá, trồng cây lương thực, thực phẩm, trồng rau, kỹ thuật dâu tằm tơ, trồng cây ăn quả.', '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 322) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2133', 'Nhà chuyên môn về bảo vệ môi trường nghiên cứu và đánh giá tác động đến môi trường hoạt động của con người như ô nhiễm không khí, nước, tiếng ồn, ô nhiễm đất, biến đổi khí hậu, chất thải độc hại, sự cạn kiệt và suy thoái tài nguyên thiên nhiên. Họ phát triển các kế hoạch và giải pháp để bảo vệ, bảo tồn, khôi phục, giảm thiểu và ngăn ngừa thiệt hại thêm cho môi trường.', array['- Tiến hành nghiên cứu, thực hiện các thử nghiệm, thu thập mẫu, thực hiện phân tích tại hiện trường và phòng thí nghiệm để xác định nguồn gốc của các vấn đề môi trường và đề xuất các cách để ngăn chặn, kiểm soát và khắc phục tác động của các vấn đề đó;', '- Đánh giá tác động có thể có của các hoạt động, dự án và phát triển tiềm năng hoặc được đề xuất có thể có đối với môi trường và đưa ra các khuyến nghị liệu các phát triển đó có nên tiến hành hay không;', '- Xây dựng và phối hợp thực hiện các hệ thống quản lý môi trường để cho phép các tổ chức xác định, giám sát và kiểm soát tác động của các hoạt động, sản phẩm và dịch vụ của họ đối với môi trường;', '- Thực hiện đánh giá tác động môi trường của các hoạt động, quy trình, chất thải, tiếng ồn và các chất hiện có;', '- Đánh giá sự tuân thủ của một tổ chức đối với các quy định và hướng dẫn của Chính phủ về môi trường nội bộ, xác định các vi phạm và hành động khắc phục phù hợp;', '- Cung cấp dịch vụ tư vấn và hỗ trợ kỹ thuật cho các tổ chức về cách xử lý tốt nhất các vấn đề môi trường để giảm thiệt hại môi trường và giảm thiểu tổn thất tài chính;', '- Xây dựng kế hoạch bảo tồn.']::text[], array['- Nhà chuyên môn về phân tích ô nhiễm không khí', '- Nhà chuyên môn về phân tích ô nhiễm nước', '- Nhà chuyên môn về phân tích ô nhiễm đất', '- Nhà chuyên môn về phân tích ô nhiễm chất thải rắn', '- Nhà chuyên môn về đánh giá tác động môi trường', '- Nhà chuyên môn về độc học môi trường', '- Nhà chuyên môn về bảo tồn', '- Nhà khoa học bảo tồn', '- Nhà sinh thái học', '- Nhà tư vấn môi trường', '- Nhà khoa học nghiên cứu môi trường', '- Nhà khoa học môi trường', '- Nhà chuyên môn về công viên', '- Nhà phân tích chất lượng nước']::text[], array['- Kỹ sư môi trường - 2143.', '(Xem tiếp Công báo số 1143 + 1144)', 'Số 1143 + 1144 Ngày 12 tháng 12 năm 2020', 'MỤC LỤC', 'VĂN BẢN QUY PHẠM PHÁP LUẬT', 'THỦ TƯỚNG CHÍNH PHỦ', 'Quyết định số 34/2020/QĐ-TTg ngày 26 tháng 11 năm 2020', 'ban hành Danh mục nghề nghiệp Việt Nam', '(Tiếp theo Công báo số 1141 + 1142)', 'Phụ lục II', 'NỘI DUNG DANH MỤC NGHỀ NGHIỆP VIỆT NAM', '(Ban hành kèm theo Quyết định số 34/2020/QĐ-TTg', 'ngày 26 tháng 11 năm 2020 của Thủ tướng Chính phủ)', '________________']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Bảo vệ môi trường biển.', '2020_1141 + 1142_34-2020-QĐ-TTg.doc', 346) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2141', 'Kỹ sư công nghiệp chế biến, chế tạo tiến hành nghiên cứu, thiết kế, tổ chức, giám sát việc xây dựng, vận hành, bảo trì các quy trình sản xuất và lắp đặt công nghiệp. Họ thiết lập các chương trình điều phối các hoạt động sản xuất và đánh giá tính hiệu quả, an toàn.', array['- Nghiên cứu các báo cáo chức năng, sơ đồ tổ chức, thông tin dự án để xác định chức năng, trách nhiệm của người lao động, đơn vị làm việc và xác định các khu vực trùng lặp;', '- Thiết lập các chương trình đo lường công việc và phân tích các mẫu công việc để phát triển các tiêu chuẩn sử dụng lao động;', '- Phân tích việc sử dụng lực lượng lao động, bố trí cơ sở, dữ liệu hoạt động, lịch trình sản xuất và chi phí để xác định hiệu quả tối ưu của công nhân và thiết bị;', '- Xây dựng các thông số kỹ thuật cho sản xuất và xác định vật liệu, thiết bị, đường ống, dòng nguyên liệu, công suất, cách bố trí của nhà máy và hệ thống;', '- Tổ chức, quản lý lao động dự án và cung cấp vật tư, nhà xưởng và thiết bị;', '- Thiết lập các tiêu chuẩn, chính sách để lắp đặt, sửa đổi, kiểm soát chất lượng, thử nghiệm, kiểm tra, bảo trì theo các nguyên tắc kỹ thuật và quy định an toàn;', '- Kiểm tra nhà máy để cải thiện và duy trì hiệu suất;', '- Chỉ đạo việc bảo trì các tòa nhà và thiết bị của nhà máy đồng thời điều phối các yêu cầu cho thiết kế, khảo sát và lịch bảo trì mới;', '- Tư vấn cho quản lý về phương pháp, kỹ thuật và thiết bị sản xuất mới;', '- Liên lạc với các bộ phận mua, lưu trữ và kiểm soát vật liệu để đảm bảo dòng cung ứng ổn định.']::text[], array['- Kỹ sư hiệu quả công nghiệp', '- Kỹ sư công nghiệp', '- Kỹ sư nhà máy công nghiệp', '- Kỹ sư sản xuất']::text[], array['- Giám đốc sản xuất (doanh nghiệp lớn) - 1722', '- Giám đốc sản xuất (doanh nghiệp nhỏ) - 1742']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Công nghệ sản xuất bê tông nhựa nóng, công nghệ chế tạo và bảo dưỡng đầu máy, chế tạo thiết bị cơ khí, công nghệ chế tạo vỏ tàu thủy, công nghệ đúc kim loại, công nghệ sản xuất sản phẩm từ cao su, chế biến lương thực, chế biến thực phẩm, công nghệ sản xuất bột giấy và giấy, chế biến mủ cao su, công nghệ sản xuất ván nhân tạo, chế biến rau quả, sản xuất đường mía, chế biến nông sản thực phẩm, chế biến dầu thực vật, sản xuất phân bón, sản xuất bánh kẹo, chế biến và bảo quản thủy sản, may công nghiệp, may thời trang.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 38) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2142', 'Kỹ sư xây dựng nghiên cứu, tư vấn, thiết kế và chỉ đạo thi công; quản lý, vận hành và bảo trì các công trình kỹ thuật dân dụng; nghiên cứu và tư vấn về các khía cạnh công nghệ của các vật liệu cụ thể.', array['- Tiến hành nghiên cứu và phát triển các lý thuyết, phương pháp mới hoặc cải tiến liên quan đến kỹ thuật dân dụng;', '- Tư vấn và thiết kế các công trình như cầu, đập, bến cảng, đường bộ, sân bay, đường sắt, kênh, đường ống, hệ thống xử lý chất thải và kiểm soát lũ, công nghiệp và các tòa nhà lớn khác;', '- Xác định và chỉ rõ các biện pháp thi công, vật liệu, tiêu chuẩn chất lượng và chỉ đạo công việc xây dựng;', '- Thiết lập hệ thống kiểm soát để đảm bảo hoạt động hiệu quả của các cấu trúc cũng như an toàn và bảo vệ môi trường;', '- Tổ chức, chỉ đạo bảo trì và sửa chữa các kết cấu công trình dân dụng hiện có;', '- Phân tích phản ứng của đất, đá khi chịu áp lực của các kết cấu được đề xuất và thiết kế nền móng kết cấu;', '- Phân tích độ ổn định của kết cấu và kiểm tra tính chất, độ bền của vật liệu được sử dụng trong xây dựng.']::text[], array['- Kỹ sư xây dựng', '- Kỹ sư địa kỹ thuật', '- Kỹ sư kết cấu']::text[], array['- Nhà quản lý dự án xây dựng dân dụng (quy mô lớn) - 1723', '- Nhà quản lý dự án xây dựng dân dụng (quy mô nhỏ) - 1743', '- Nhà địa chất học - 2114', '- Kỹ sư luyện kim - 2146', '- Kỹ sư khai thác - 2146', '- Nhà quy hoạch đô thị và giao thông - 2164']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Kỹ thuật lắp đặt ống công nghệ, cấp nước, thoát nước, lắp đặt đường ống nước, lắp đặt cầu, vận hành máy ủi, xúc, san, xây dựng công trình thủy, thí nghiệm và kiểm tra chất lượng cầu đường bộ, xây dựng và bảo dưỡng công trình giao thông đường sắt, kỹ thuật xây dựng mỏ hầm lò, xây dựng và hoàn thiện công trình thủy lợi.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 60) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2143', 'Kỹ sư môi trường tiến hành nghiên cứu, tư vấn, thiết kế, chỉ đạo thực hiện các giải pháp ngăn chặn, kiểm soát hoặc khắc phục các tác động tiêu cực của hoạt động con người đến môi trường thông qua nhiều ngành kỹ thuật khác nhau. Họ tiến hành đánh giá môi trường của các dự án xây dựng và công trình dân dụng; áp dụng các nguyên tắc kỹ thuật để kiểm soát ô nhiễm, tái chế và xử lý chất thải.', array['- Tiến hành nghiên cứu, đánh giá và báo cáo về tác động môi trường của các hoạt động xây dựng, công trình dân dụng và các hoạt động khác hiện có hoặc được đề xuất;', '- Tiến hành nghiên cứu và phân tích hiện trạng ô nhiễm môi trường gây ra bởi tự nhiên và các hoạt động của con người;', '- Xây dựng, phát triển các quy trình phân tích các chất ô nhiễm hóa học trong các thành phần môi trường;', '- Tiến hành nghiên cứu độc tính và sự chuyển hóa các chất hóa học trong môi trường;', '- Kiểm tra các cơ sở công nghiệp để đánh giá hiệu quả hoạt động và đảm bảo tuân thủ các quy định về môi trường;', '- Thiết kế và giám sát sự phát triển các hệ thống, quy trình và thiết bị để kiểm soát, quản lý, khắc phục chất lượng nước, không khí hoặc đất;', '- Cung cấp hỗ trợ kỹ thuật môi trường trong phân tích mạng, phân tích quy định và lập kế hoạch hoặc xem xét phát triển cơ sở dữ liệu;', '- Cập nhật và duy trì các kế hoạch, giấy phép và quy trình vận hành tiêu chuẩn;', '- Cung cấp kỹ thuật và hỗ trợ kỹ thuật cho các dự án xử lý và kiện tụng môi trường bao gồm thiết kế hệ thống xử lý và xác định khả năng áp dụng quy định;', '- Giám sát tiến độ của các chương trình cải thiện môi trường;', '- Tư vấn cho các tập đoàn, cơ quan chính phủ các thủ tục cần tuân thủ trong việc làm sạch các địa điểm bị ô nhiễm để bảo vệ con người và môi trường;', '- Hợp tác với các nhà khoa học môi trường, nhà quy hoạch, kỹ thuật viên xử lý chất thải nguy hại, kỹ sư từ các ngành khác, các chuyên gia về luật và kinh doanh để giải quyết các vấn đề môi trường.']::text[], array['- Kỹ sư kiểm soát ô nhiễm không khí', '- Nhà chuyên môn về phân tích môi trường', '- Kỹ sư môi trường', '- Nhà chuyên môn về xử lý môi trường', '- Kỹ sư xử lý nước thải', '- Kỹ sư kiểm soát ô nhiễm nước', '- Kỹ sư kiểm soát ô nhiễm đất', '- Kỹ sư phân tích môi trường', '- Kỹ sư xử lý chất thải rắn và khí thải']::text[], array['- Nhà khoa học môi trường - 2133', '- Chuyên gia về bảo vệ bức xạ - 2263']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Xử lý nước thải công nghiệp.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 82) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2144', 'Kỹ sư cơ học, cơ khí tiến hành nghiên cứu, tư vấn, thiết kế và sản xuất trực tiếp máy móc, thiết bị, hệ thống công nghiệp, máy bay, tàu thủy; tư vấn, chỉ đạo vận hành, bảo trì và sửa chữa; nghiên cứu và tư vấn về các khía cạnh cơ học của vật liệu, sản phẩm hoặc quy trình cụ thể.', array['- Tư vấn, thiết kế máy móc, công cụ cho sản xuất, khai thác, xây dựng, nông nghiệp và các mục đích công nghiệp khác;', '- Tư vấn và thiết kế động cơ hơi nước, đốt trong và các động cơ không dùng điện khác dùng để đẩy đầu máy xe lửa, phương tiện giao thông đường bộ, máy bay hoặc để lái máy công nghiệp và máy móc khác;', '- Tư vấn và thiết kế thân tàu, cấu trúc thượng tầng và hệ thống đẩy của tàu; nhà máy cơ khí và thiết bị để giải phóng, kiểm soát và sử dụng năng lượng; hệ thống sưởi ấm, thông gió và làm lạnh, thiết bị lái, máy bơm và các thiết bị cơ khí khác;', '- Tư vấn, thiết kế khung máy bay, gầm xe, các thiết bị khác cho máy bay cũng như hệ thống treo, phanh, thân xe và các bộ phận khác của phương tiện giao thông đường bộ;', '- Tư vấn và thiết kế các bộ phận không dùng điện của thiết bị hoặc sản phẩm như bộ xử lý văn bản, máy tính, dụng cụ chính xác, máy ảnh và máy chiếu;', '- Thiết lập các tiêu chuẩn và quy trình kiểm soát để đảm bảo hoạt động hiệu quả, an toàn cho máy móc, thiết bị, công cụ, động cơ, nhà máy công nghiệp hoặc hệ thống;', '- Đảm bảo thiết bị, vận hành và bảo trì tuân thủ các thông số kỹ thuật thiết kế và tiêu chuẩn an toàn.']::text[], array['- Kỹ sư hàng không', '- Nhà chuyên môn về thiết kế động cơ', '- Kiến trúc sư hàng hải', '- Kỹ sư hàng hải', '- Kỹ sư cơ khí']::text[], array['- Kỹ sư tàu thủy - 3151']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Kỹ thuật tua - bin hơi, nguội chế tạo, nguội lắp ráp cơ khí, kỹ thuật lò hơi, rèn, dập, công nghệ mạ, vận hành sửa chữa trạm bơm điện, công nghệ ô tô, phóng dạng và gia công khuôn dưỡng tàu thủy, lắp ráp hệ thống động lực tàu thủy, hàn, cắt gọt kim loại trên máy CNC, sửa chữa thiết bị luyện kim, vận hành, sửa chữa máy tàu cuốc, sửa chữa máy thi công xây dựng, công nghệ cán kéo kim loại.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 111) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2145', 'Kỹ sư hóa học tiến hành nghiên cứu, phát triển, tư vấn, chỉ đạo các quy trình hóa học quy mô thương mại và sản xuất các chất, vật phẩm khác nhau như dầu thô, dẫn xuất dầu mỏ, thực phẩm, đồ uống, thuốc hoặc vật liệu tổng hợp. Họ chỉ đạo bảo trì, sửa chữa nhà máy và thiết bị hóa chất; nghiên cứu và tư vấn về các khía cạnh hóa học của vật liệu, sản phẩm hoặc quy trình cụ thể.', array['- Tiến hành nghiên cứu, tư vấn và phát triển các quy trình hóa học quy mô thương mại để tinh chế dầu thô, các chất lỏng hoặc khí khác và để sản xuất các chất, vật phẩm như dẫn xuất dầu mỏ, chất nổ, thực phẩm, đồ uống, thuốc hoặc vật liệu tổng hợp;', '- Nghiên cứu quy trình và phương pháp phân tích các hợp chất hóa học trong các thành phần môi trường, vật liệu, sản phẩm sử dụng trong đời sống và hoạt động công nghiệp;', '- Quy định phương pháp sản xuất hóa chất, vật tư, tiêu chuẩn chất lượng và đảm bảo chúng phù hợp với thông số kỹ thuật;', '- Thiết lập các tiêu chuẩn và quy trình kiểm soát để đảm bảo an toàn, hiệu quả hoạt động sản xuất hóa chất và an toàn thiết bị vận hành của công nhân hoặc của những người làm việc gần các phản ứng hóa học đang diễn ra;', '- Thiết kế thiết bị nhà máy hóa chất và đưa ra các quy trình sản xuất hóa chất và sản phẩm;', '- Thực hiện các thử nghiệm trong suốt các giai đoạn sản xuất để xác định mức độ kiểm soát đối với các biến bao gồm nhiệt độ, tỷ trọng, trọng lượng riêng và áp suất;', '- Phát triển các quy trình an toàn được sử dụng;', '- Chuẩn bị dự toán chi phí sản xuất và báo cáo tiến độ sản xuất cho quản lý;', '- Thực hiện các nghiên cứu trong phòng thí nghiệm về các bước trong quá trình sản xuất sản phẩm mới và thử nghiệm các quy trình được đề xuất trong các hoạt động quy mô nhỏ như nhà máy thí điểm.']::text[], array['- Kỹ sư hóa học', '- Nhà chuyên môn về công nghệ nhiên liệu', '- Nhà chuyên môn về công nghệ nhựa', '- Kỹ sư công nghệ lọc hóa dầu', '- Kỹ sư hóa học môi trường', '- Kỹ sư hóa phân tích', '- Kỹ sư hóa học ứng dụng']::text[], '{}'::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Thí nghiệm các sản phẩm hóa dầu, kiểm nghiệm chất lượng lương thực, thực phẩm, kiểm nghiệm đường mía, kiểm nghiệm bột giấy và giấy.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 130) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2146', 'Kỹ sư khai thác mỏ, luyện kim và các nghề liên quan tiến hành nghiên cứu, thiết kế, phát triển, duy trì các phương pháp chiết xuất kim loại từ quặng, khoáng sản, nước, dầu hoặc khí từ trái đất và phát triển hợp kim mới, gốm và các vật liệu khác; nghiên cứu và tư vấn về các khía cạnh khai thác hoặc luyện kim của các vật liệu, sản phẩm hoặc quy trình cụ thể.', array['- Xác định vị trí và lập kế hoạch khai thác than, quặng kim loại, khoáng sản phi kim loại và vật liệu xây dựng như đá, sỏi;', '- Xác định các phương pháp khai thác hiệu quả nhất và các loại máy móc sẽ được sử dụng, lập kế hoạch bố trí và chỉ đạo xây dựng các trục và đường hầm;', '- Xác định vị trí khoan và đưa ra các phương pháp kiểm soát dòng chảy của nước, dầu hoặc khí từ giếng;', '- Lập kế hoạch, chỉ đạo lưu trữ, xử lý ban đầu và vận chuyển nước, dầu hoặc khí;', '- Thiết lập các tiêu chuẩn, quy trình an toàn và các phương tiện sơ cứu đặc biệt là dưới lòng đất;', '- Tiến hành nghiên cứu, phát triển các phương pháp chiết xuất kim loại từ quặng của chúng và tư vấn về việc áp dụng chúng;', '- Nghiên cứu tính chất của kim loại và hợp kim, phát triển hợp kim mới; tư vấn, giám sát các khía cạnh kỹ thuật của sản xuất và gia công kim loại và hợp kim;', '- Duy trì liên lạc kỹ thuật và tư vấn với các chuyên gia có liên quan khác như nhà địa chất và nhà địa vật lý;', '- Kiểm tra kho chứa hoặc mỏ để đánh giá lợi nhuận.']::text[], array['- Kỹ sư luyện kim khai thác', '- Kỹ sư khai thác', '- Kỹ sư khai thác dầu mỏ và khí đốt tự nhiên']::text[], array['- Nhà địa chất - 2114', '- Nhà địa vật lý - 2114']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Luyện gang, luyện thép, công nghệ nhiệt luyện, kỹ thuật khai thác mỏ hầm lò.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 151) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2149', 'Kỹ sư kỹ thuật khác chưa được phân vào đâu bao gồm những người thực hiện nghiên cứu, tư vấn hoặc phát triển các quy trình và giải pháp kỹ thuật liên quan đến an toàn tại nơi làm việc, kỹ thuật y sinh, quang học, vật liệu, sản xuất điện hạt nhân và chất nổ.', array['- Áp dụng kiến ​​thức về kỹ thuật vào thiết kế, phát triển, đánh giá các hệ thống và sản phẩm sinh học, y tế như nội tạng nhân tạo, bộ phận giả và dụng cụ đo đạc;', '- Thiết kế các thiết bị được sử dụng trong các quy trình y tế và hệ thống hình ảnh khác nhau như chụp cộng hưởng từ, các thiết bị để tự động tiêm insulin hoặc kiểm soát các chức năng cơ thể;', '- Thiết kế các thành phần của dụng cụ quang học như thấu kính, kính hiển vi, kính thiên văn, laze, hệ thống đĩa quang và các thiết bị khác sử dụng các đặc tính của ánh sáng;', '- Thiết kế, thử nghiệm và phối hợp phát triển vật liệu nổ để đáp ứng các yêu cầu kỹ thuật mua sắm của quân đội;', '- Thiết kế và giám sát việc xây dựng, vận hành các lò phản ứng hạt nhân, nhà máy điện, các hệ thống tái chế và thu hồi nhiên liệu hạt nhân;', '- Thiết kế và phát triển các thiết bị hạt nhân như lõi lò phản ứng, tấm chắn bức xạ, các cơ chế điều khiển và đo đạc liên quan;', '- Đánh giá thiệt hại và cung cấp các tính toán cho các hoạt động cứu hộ hàng hải;', '- Nghiên cứu và tư vấn về các khía cạnh kỹ thuật của các quy trình sản xuất cụ thể như các quy trình liên quan đến thủy tinh, gốm sứ, dệt may, sản phẩm da, gỗ và in ấn;', '- Xác định các mối nguy tiềm ẩn và giới thiệu các quy trình, thiết bị an toàn.']::text[], array['- Kỹ sư y sinh', '- Kỹ sư xử lý vật liệu nổ', '- Kỹ sư cứu hộ hàng hải', '- Kỹ sư vật liệu', '- Kỹ sư sản xuất điện hạt nhân', '- Kỹ sư quang học', '- Kỹ sư an toàn', '- Kỹ sư nghiên cứu thời gian và chuyển động', '- Nhà chuyên môn về khảo sát số lượng']::text[], array['- Kỹ sư sản xuất và công nghiệp - 2141', '- Kỹ sư môi trường - 2143', '- Nhà khảo sát hiện trường - 2165', 'Ghi chú:', 'Cần lưu ý rằng, dù các kỹ sư y sinh được phân loại trong nhóm này như các chuyên gia kỹ thuật khác, nhưng đây được coi là một phần không thể thiếu của lực lượng lao động y tế bên cạnh những nghề nghiệp được phân loại trong nhóm 22: Nhà chuyên môn về sức khỏe và các nghề khác được phân loại trong một số nhóm khác trong nhóm chính 2: Nhà chuyên môn bậc cao.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 171) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2151', 'Kỹ sư điện tiến hành nghiên cứu, tư vấn, thiết kế, chỉ đạo xây dựng và vận hành hệ thống điện, linh kiện, động cơ và thiết bị; tư vấn và chỉ đạo vận hành bảo trì và sửa chữa; nghiên cứu và tư vấn về các khía cạnh công nghệ của vật liệu, sản phẩm kỹ thuật điện và các quy trình.', array['- Tư vấn, thiết kế các trạm điện, hệ thống phát điện, truyền tải và phân phối điện;', '- Giám sát, kiểm soát hoạt động của hệ thống phát điện, truyền tải và phân phối điện;', '- Tư vấn, thiết kế hệ thống cho động cơ điện, lực kéo điện, thiết bị điện gia dụng và các thiết bị khác;', '- Chỉ định lắp đặt và ứng dụng điện trong công nghiệp, các tòa nhà và các công trình khác;', '- Thiết lập các tiêu chuẩn, quy trình kiểm soát để giám sát hiệu suất và an toàn của các hệ thống, động cơ, thiết bị phát và phân phối điện;', '- Xác định phương pháp sản xuất cho hệ thống điện cũng như bảo trì và sửa chữa các hệ thống điện, động cơ và thiết bị hiện có.']::text[], array['- Kỹ sư điện', '- Kỹ sư sản xuất điện', '- Kỹ sư cơ điện']::text[], array['- Kỹ sư sản xuất điện hạt nhân - 2149', '- Kỹ sư điện tử - 2152', '- Kỹ sư phát thanh truyền hình - 2153', '- Kỹ sư viễn thông - 2153']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Điện công nghiệp, hệ thống điện, đo lường điện, thí nghiệm điện, vận hành nhà máy nhiệt điện, lắp đặt công trình điện, kỹ thuật cơ điện mỏ hầm lò, kỹ thuật lắp đặt điện và điều khiển trong công nghiệp, sửa chữa thiết bị tự động hóa, lắp đặt thiết bị điện, cơ điện nông thôn, tự động hóa công nghiệp, sản xuất động cơ điện.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 202) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2152', 'Kỹ sư điện tử tiến hành nghiên cứu, thiết kế, chỉ đạo hoạt động xây dựng, bảo trì và sửa chữa hệ thống điện tử; nghiên cứu và tư vấn về các khía cạnh công nghệ của vật liệu, sản phẩm hoặc quy trình kỹ thuật điện tử.', array['- Tư vấn và thiết kế các thiết bị hoặc linh kiện điện tử, mạch điện, chất bán dẫn và hệ thống;', '- Quy định phương pháp sản xuất hoặc lắp đặt vật liệu và tiêu chuẩn chất lượng; chỉ đạo công việc sản xuất hoặc lắp đặt các sản phẩm và hệ thống điện tử;', '- Thiết lập các tiêu chuẩn và quy trình kiểm soát để đảm bảo hoạt động hiệu quả và an toàn cho các hệ thống, động cơ và thiết bị điện tử;', '- Tổ chức, chỉ đạo bảo trì và sửa chữa các hệ thống và thiết bị điện tử hiện có;', '- Thiết kế các mạch và linh kiện điện tử để sử dụng trong các lĩnh vực như dẫn đường hàng không vũ trụ, điều khiển động cơ đẩy, âm học hoặc các thiết bị và điều khiển;', '- Nghiên cứu và tư vấn về hệ thống ra-đa, hệ thống đo và điều khiển từ xa, vi sóng và các thiết bị điện tử khác;', '- Thiết kế và phát triển các thuật toán xử lý tín hiệu; thực hiện các thuật toán này thông qua lựa chọn phần cứng và phần mềm thích hợp;', '- Phát triển thiết bị và quy trình để kiểm tra các linh kiện, mạch và hệ thống điện tử.']::text[], array['- Kỹ sư phần cứng máy tính', '- Kỹ sư điện tử', '- Kỹ sư thiết bị']::text[], array['- Kỹ sư viễn thông - 2153']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Điện tử công nghiệp, vận hành, sửa chữa thiết bị lạnh, cơ điện tử, điện tử dân dụng, kỹ thuật thiết bị điện tử y tế, sửa chữa máy tính xách tay.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 221) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2153', 'Kỹ sư viễn thông tiến hành nghiên cứu, tư vấn, thiết kế, chỉ đạo xây dựng, vận hành, bảo trì và sửa chữa các hệ thống và thiết bị viễn thông. Họ nghiên cứu và tư vấn về các khía cạnh công nghệ của vật liệu, sản phẩm hoặc quy trình kỹ thuật viễn thông.', array['- Tư vấn, thiết kế các thiết bị hoặc linh kiện viễn thông, hệ thống, thiết bị và trung tâm phân phối;', '- Quy định phương pháp sản xuất hoặc lắp đặt, vật liệu, tiêu chuẩn chất lượng và an toàn; chỉ đạo công việc sản xuất hoặc lắp đặt các sản phẩm và hệ thống viễn thông;', '- Tổ chức và chỉ đạo bảo trì, sửa chữa các hệ thống, động cơ và thiết bị viễn thông hiện có;', '- Nghiên cứu và tư vấn về thiết bị viễn thông;', '- Lập kế hoạch và thiết kế mạng truyền dẫn dựa trên các phương tiện truyền dẫn hữu tuyến và vô tuyến;', '- Thiết kế và phát triển các thuật toán xử lý tín hiệu và thực hiện các thuật toán này thông qua lựa chọn phần cứng và phần mềm thích hợp;', '- Thiết kế mạng viễn thông và hệ thống phân phối phát thanh và truyền hình, bao gồm cả cáp và không dây.']::text[], array['- Kỹ sư phát thanh truyền hình', '- Kỹ sư viễn thông', '- Kỹ sư công nghệ viễn thông']::text[], array['- Kỹ sư điện tử - 2152']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Bảo dưỡng trạm thu phát sóng vô tuyến, lắp đặt thiết bị đầu cuối viễn thông.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 239) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2161', 'Kiến trúc sư xây dựng thiết kế các tòa nhà thương mại, công nghiệp, viện nghiên cứu, khu dân cư, giải trí và lên kế hoạch giám sát việc xây dựng, bảo trì và khôi phục chúng.', array['- Phát triển các lý thuyết và phương pháp kiến ​​trúc mới hoặc cải tiến;', '- Kiểm tra địa điểm và tư vấn khách hàng, ban quản lý và các bên liên quan khác để xác định loại, kiểu dáng, kích thước của các tòa nhà được đề xuất và các thay đổi đối với các tòa nhà hiện có;', '- Cung cấp thông tin liên quan đến thiết kế, vật liệu và thời gian xây dựng dự kiến;', '- Chuẩn bị tài liệu dự án, bao gồm các bản phác thảo, bản vẽ tỷ lệ và tích hợp các yếu tố cấu trúc, cơ học và thẩm mỹ trong thiết kế cuối cùng;', '- Viết thông số kỹ thuật và tài liệu hợp đồng để các nhà xây dựng sử dụng và thay mặt khách hàng gọi thầu;', '- Thực hiện các liên hệ cần thiết để đảm bảo tính khả thi của các dự án liên quan đến phong cách, chi phí, thời gian và sự tuân thủ các quy định;', '- Xác định và tìm giải pháp tốt nhất cho các vấn đề liên quan đến chức năng và chất lượng môi trường bên trong của các tòa nhà và đưa ra các thiết kế, bản vẽ và kế hoạch cần thiết;', '- Giám sát công việc xây dựng hoặc cải tạo để đảm bảo tuân thủ các thông số kỹ thuật và tiêu chuẩn chất lượng;', '- Duy trì liên lạc kỹ thuật và tư vấn với các chuyên gia khác có liên quan.']::text[], array['- Kiến trúc sư nhà cao tầng', '- Kiến trúc sư nội thất']::text[], array['- Kiến trúc sư cảnh quan - 2162', '- Người trang trí nội thất - 3432', '- Người thiết kế nội thất - 3432']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 259) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2162', 'Kiến trúc sư cảnh quan lên kế hoạch và thiết kế cảnh quan, không gian mở cho các dự án như công viên, trường học, tổ chức, đường giao thông, khu vực bên ngoài cho các khu thương mại, công nghiệp, khu dân cư; lập kế hoạch và giám sát việc xây dựng, bảo trì và khôi phục chúng.', array['- Xây dựng mới hoặc sửa đổi các lý thuyết, phương pháp và đưa ra lời khuyên về chính sách liên quan đến kiến ​​trúc cảnh quan;', '- Kiểm tra địa điểm, tư vấn khách hàng, ban quản lý và các bên liên quan khác để xác định loại, kiểu dáng và kích thước của các tòa nhà, công viên, đường xá và các không gian mở khác được đề xuất;', '- Tổng hợp và phân tích dữ liệu địa điểm và cộng đồng về các đặc điểm địa lý, sinh thái, địa hình, đất, thảm thực vật, thủy văn, đặc điểm hình ảnh và cấu trúc nhân tạo, để xây dựng các khuyến nghị sử dụng và phát triển đất, nghiên cứu khả thi và báo cáo tác động môi trường;', '- Chuẩn bị các báo cáo, kế hoạch chiến lược, sơ đồ địa điểm, bản vẽ công trình, thông số kỹ thuật và dự toán chi phí để phát triển đất, hiển thị vị trí và chi tiết của các đề xuất, bao gồm mô hình mặt bằng, cấu trúc, thảm thực vật và tiếp cận;', '- Viết thông số kỹ thuật và tài liệu hợp đồng để các nhà xây dựng và nhà thầu kỹ thuật dân dụng sử dụng và thay mặt khách hàng gọi thầu;', '- Thực hiện các liên hệ cần thiết để đảm bảo tính khả thi về phong cách, chi phí, thời gian và sự tuân thủ các quy định của các dự án;', '- Xác định và tìm giải pháp tốt nhất cho các vấn đề liên quan đến chức năng và chất lượng của môi trường bên ngoài và đưa ra các thiết kế, bản vẽ và kế hoạch cần thiết;', '- Giám sát công việc xây dựng hoặc cải tạo để đảm bảo tuân thủ các thông số kỹ thuật và tiêu chuẩn chất lượng;', '- Duy trì liên lạc kỹ thuật và tư vấn với các chuyên gia khác có liên quan.']::text[], array['- Kiến trúc sư cảnh quan']::text[], array['- Kiến trúc sư nhà cao tầng - 2161', '- Nhà quy hoạch đô thị - 2164']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 278) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2163', 'Nhà thiết kế sản phẩm và may mặc thiết kế, phát triển các sản phẩm để sản xuất; chuẩn bị các thiết kế và thông số kỹ thuật của sản phẩm cho sản xuất hàng loạt và một lần.', array['- Xác định các mục tiêu và ràng buộc của bản tóm tắt thiết kế bằng cách tham khảo ý kiến ​​với khách hàng và các bên liên quan;', '- Hình thành các khái niệm thiết kế cho quần áo, dệt may, các sản phẩm công nghiệp, thương mại và tiêu dùng và đồ trang sức;', '- Hài hòa giữa các yêu cầu thẩm mỹ với các yêu cầu kỹ thuật, chức năng, sinh thái và sản xuất;', '- Chuẩn bị các bản phác thảo, sơ đồ, minh họa, kế hoạch, mẫu và mô hình để truyền đạt các khái niệm thiết kế;', '- Đàm phán các giải pháp thiết kế với khách hàng, quản lý và nhân viên bán hàng và sản xuất;', '- Lựa chọn, chỉ định và đề xuất các vật liệu chức năng và thẩm mỹ, phương pháp sản xuất và hoàn thiện cho sản xuất;', '- Chi tiết và ghi lại thiết kế đã chọn cho sản xuất;', '- Chuẩn bị và vận hành nguyên mẫu và mẫu;', '- Giám sát việc chuẩn bị các mẫu, chương trình và dụng cụ của quy trình sản xuất.']::text[], array['- Nhà thiết kế trang phục', '- Nhà thiết kế thời trang', '- Nhà thiết kế công nghiệp', '- Nhà thiết kế trang sức']::text[], array['- Nhà thiết kế động cơ - 2144', '- Kiến trúc sư nhà cao tầng - 2161', '- Kiến trúc sư cảnh quan - 2162', '- Người thiết kế nội thất - 3432']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 295) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2164', 'Các nhà quy hoạch đô thị và giao thông xây dựng và thực hiện các kế hoạch và chính sách cho việc sử dụng có kiểm soát đất đô thị và nông thôn và cho các hệ thống giao thông. Họ tiến hành nghiên cứu và cung cấp lời khuyên về các yếu tố kinh tế, môi trường và xã hội ảnh hưởng đến việc sử dụng đất và luồng giao thông.', array['- Bố trí quy hoạch và điều phối phát triển đô thị;', '- Tổng hợp và phân tích dữ liệu về các yếu tố kinh tế, pháp lý, chính trị, văn hóa, nhân khẩu học, xã hội học, vật lý và môi trường ảnh hưởng đến việc sử dụng đất;', '- Trao đổi với các cơ quan chính phủ, cộng đồng và chuyên gia trong các lĩnh vực như kiến ​​trúc, quy hoạch, khoa học xã hội, môi trường và pháp luật;', '- Đưa ra và đề xuất sử dụng và phát triển đất đai, trình bày các kế hoạch, chương trình và thiết kế tường thuật và đồ họa cho các nhóm và cá nhân;', '- Tư vấn cho chính phủ, các công ty và cộng đồng về các vấn đề và đề xuất quy hoạch đô thị và khu vực;', '- Xem xét và đánh giá các báo cáo tác động môi trường;', '- Lập kế hoạch và điều phối phát triển các khu đất cho công viên, trường học, tổ chức, sân bay, đường bộ và các dự án liên quan, và cho các khu thương mại, công nghiệp và dân cư;', '- Lập kế hoạch và tư vấn về định tuyến và kiểm soát giao thông đường bộ và hệ thống giao thông công cộng để đạt hiệu quả và an toàn.']::text[], array['- Nhà quy hoạch đất đai', '- Nhà quy hoạch giao thông', '- Nhà quy hoạch đô thị']::text[], array['- Kiến trúc sư nhà cao tầng - 2161', '- Kiến trúc sư cảnh quan - 2162']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 317) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2165', 'Nhà vẽ bản đồ và khảo sát hiện trường xác định vị trí chính xác, chuẩn bị và sửa đổi bản đồ kỹ thuật số, đồ họa, hình ảnh, biểu đồ hoặc biểu diễn trực quan khác về các đặc điểm tự nhiên được xây dựng và ranh giới của đất, biển, vùng ngầm và các thiên thể; áp dụng các nguyên tắc khoa học và toán học.', array['- Khảo sát, đo lường và mô tả các bề mặt đất, mỏ, bề mặt ngầm, biển, sông và lòng hồ;', '- Lưu ý vị trí chính xác của các tính năng khác nhau và ghi dữ liệu khảo sát ở dạng kỹ thuật số;', '- Lập các biểu đồ và bản đồ sẽ được sử dụng để xác định vùng nước và kênh có thể điều hướng và trong quy hoạch xây dựng các công trình biển;', '- Lập kế hoạch và thực hiện các cuộc khảo sát ảnh trên không;', '- Thiết kế, biên soạn và chỉnh sửa bản đồ và biểu đồ bằng các hình ảnh trên không và các hình ảnh khác, hình ảnh vệ tinh, tài liệu khảo sát và dữ liệu, bản đồ và hồ sơ hiện có, báo cáo và thống kê;', '- Thực hiện nghiên cứu và phát triển hệ thống đo đạc và đo quang điện, hệ thống địa chính và hệ thống thông tin đất đai;', '- Nghiên cứu và tư vấn về các khía cạnh kỹ thuật, thẩm mỹ và kinh tế của sản xuất bản đồ;', '- Duy trì liên lạc kỹ thuật và tư vấn với các chuyên gia khác có liên quan.']::text[], array['- Nhà khảo sát trên không', '- Nhà khảo sát hiện trường', '- Nhà vẽ bản đồ', '- Nhà khảo sát thủy văn', '- Nhà khảo sát đất đai', '- Nhà khảo sát mỏ', '- Nhà chuyên môn đọc hình ảnh']::text[], array['- Nhà chuyên môn về khảo sát số lượng - 2149', '- Kỹ thuật viên khảo sát tòa nhà - 3112', '- Kỹ thuật viên khảo sát hàng hải - 3115']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Đo đạc bản đồ, khoan thăm dò địa chất, trắc địa công trình, khảo sát địa hình.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 335) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2166', 'Nhà thiết kế đồ họa và truyền thông đa phương tiện thiết kế nội dung nghe nhìn để truyền đạt thông tin bằng cách sử dụng hình thức in, phim, điện tử, kỹ thuật số và các phương tiện nghe nhìn và âm thanh khác. Họ tạo ra đồ họa, hiệu ứng đặc biệt, hoạt hình hoặc hình ảnh trực quan khác để sử dụng trong các trò chơi máy tính, phim ảnh, video âm nhạc, phương tiện in ấn và quảng cáo.', array['- Xác định các mục tiêu và ràng buộc của bản tóm tắt thiết kế bằng cách tham khảo ý kiến ​​với khách hàng và các bên liên quan;', '- Thực hiện nghiên cứu và phân tích các yêu cầu truyền thông chức năng;', '- Hình thành các khái niệm thiết kế cho chủ đề cần truyền đạt;', '- Chuẩn bị các bản phác thảo, sơ đồ, hình minh họa và bố cục để truyền đạt các khái niệm thiết kế;', '- Thiết kế đồ họa và hoạt hình phức tạp để đáp ứng các yêu cầu về chức năng, thẩm mỹ và sáng tạo của bản tóm tắt thiết kế;', '- Tạo hình ảnh hai chiều và ba chiều mô tả các đối tượng đang chuyển động hoặc minh họa một quá trình, sử dụng hoạt hình máy tính hoặc chương trình mô hình hóa;', '- Đàm phán giải pháp thiết kế với khách hàng, nhân viên quản lý, bán hàng và sản xuất;', '- Lựa chọn, chỉ định hoặc đề xuất các vật liệu và phương tiện chức năng và thẩm mỹ để xuất bản, giao hàng hoặc hiển thị;', '- Chi tiết và ghi lại thiết kế đã chọn cho sản xuất;', '- Giám sát hoặc thực hiện sản xuất trong phương tiện được chọn.']::text[], array['- Nhà chuyên môn về hoạt hình', '- Họa sỹ vẽ minh họa', '- Nhà thiết kế trò chơi máy tính', '- Nghệ sỹ kỹ thuật số', '- Nhà thiết kế đồ họa', '- Họa sĩ quảng cáo', '- Nhà thiết kế đa phương tiện', '- Nhà thiết kế xuất bản', '- Nhà thiết kế trang web']::text[], array['- Kiến trúc sư nội thất - 2161', '- Nhà phát triển đa phương tiện - 2513', '- Nhà phát triển web - 2513', '- Nghệ sĩ thị giác - 2651', '- Người thiết kế nội thất - 3432']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Thiết kế đồ họa.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 359) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2211', 'Các bác sĩ đa khoa (bao gồm cả bác sĩ gia đình và bác sĩ chăm sóc chính) chẩn đoán, điều trị và phòng ngừa bệnh tật, chấn thương và các khiếm khuyết về thể chất và tinh thần khác và duy trì sức khỏe chung ở người thông qua việc áp dụng các nguyên tắc và quy trình của y học hiện đại gồm cả việc điều trị một số bệnh nhất định và có thể chịu trách nhiệm cung cấp dịch vụ chăm sóc y tế liên tục và toàn diện cho các cá nhân, gia đình và cộng đồng.', array['- Tiến hành kiểm tra thể chất của bệnh nhân và phỏng vấn họ và gia đình họ để xác định tình trạng sức khỏe của họ;', '- Yêu cầu xét nghiệm trong phòng thí nghiệm, chụp X-quang và các thủ tục chẩn đoán khác và phân tích kết quả để xác định bản chất của rối loạn hoặc bệnh tật;', '- Cung cấp chăm sóc y tế liên tục cho bệnh nhân bao gồm kê đơn, điều hành, tư vấn và theo dõi các phương pháp điều trị và các biện pháp phòng ngừa;', '- Thực hiện phẫu thuật và các thủ tục lâm sàng khác;', '- Tư vấn cho các cá nhân, gia đình và cộng đồng về sức khỏe, dinh dưỡng và lối sống hỗ trợ phòng ngừa hoặc điều trị bệnh và rối loạn;', '- Cung cấp sự giới thiệu cho bệnh nhân và gia đình để được chăm sóc chuyên khoa tại bệnh viện, trung tâm phục hồi chức năng hoặc các loại trung tâm chăm sóc sức khỏe khác;', '- Xác định, quản lý, cung cấp và giới thiệu các biến chứng trước, trong và sau khi sinh con;', '- Ghi lại bệnh nhân thông tin y tế và lịch sử y tế và trao đổi thông tin với các bác sĩ chuyên khoa và nhân viên y tế khác theo yêu cầu để tiếp tục chăm sóc y tế;', '- Báo cáo sinh, tử và các bệnh đáng chú ý cho các cơ quan chính phủ để đáp ứng các yêu cầu pháp lý và chuyên nghiệp;', '- Tiến hành nghiên cứu về dịch vụ y tế và sức khỏe con người và phổ biến những phát hiện như thông qua các báo cáo khoa học;', '- Lập kế hoạch và tham gia vào các chương trình được thiết kế để ngăn chặn sự xuất hiện và lây lan của các bệnh thông thường.']::text[], array['- Bác sĩ y khoa tuyến huyện', '- Bác sĩ trị liệu', '- Bác sĩ y khoa gia đình', '- Bác sĩ đa khoa', '- Bác sĩ chăm sóc sức khỏe ban đầu', '- Bác sỹ nội trú']::text[], array['- Bác sĩ tâm thần - 2212', '- Bác sĩ chuyên khoa - 2212', '- Bác sĩ phẫu thuật - 2212', '- Bác sỹ phụ tá (y tế) - 2240', 'Ghi chú:', 'Nghề nghiệp trong nhóm này yêu cầu hoàn thành bằng cấp đại học về giáo dục y tế cơ bản cộng với đào tạo lâm sàng sau đại học hoặc tương đương để có thẩm quyền hoạt động. Thực tập sinh y khoa hoặc những người đã hoàn thành giáo dục đại học của họ trong giáo dục y tế cơ bản và đang thực hiện đào tạo lâm sàng sau đại học về y học nói chung mà không có bất kỳ lĩnh vực chuyên khoa nào được bao gồm ở đây. Mặc dù ở một số quốc gia, “chữa trị đa khoa” và “y tế gia đình”có thể được coi là chuyên khoa, nhưng những nghề này nên thuộc mã này.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 397) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2212', 'Bác sỹ chuyên khoa chẩn đoán, điều trị và phòng ngừa bệnh tật, chấn thương và các khiếm khuyết về thể chất và tinh thần khác ở người, sử dụng các xét nghiệm chuyên môn, chẩn đoán, y tế, phẫu thuật, vật lý và tâm thần áp dụng các nguyên tắc và quy trình của y học hiện đại. Họ chuyên về một số loại bệnh, loại bệnh nhân hoặc phương pháp điều trị và có thể tiến hành giáo dục và nghiên cứu y tế trong các lĩnh vực chuyên môn được lựa chọn của họ.', array['- Tiến hành kiểm tra thể chất của bệnh nhân và phỏng vấn họ và gia đình họ để xác định tình trạng sức khỏe của họ;', '- Xem xét thông tin y tế được cung cấp bởi bác sĩ giới thiệu hoặc nhà cung cấp dịch vụ chăm sóc sức khỏe khác;', '- Yêu cầu các xét nghiệm chẩn đoán chuyên biệt để xác định bản chất của rối loạn hoặc bệnh tật;', '- Kê đơn, quản lý và theo dõi bệnh nhân, đáp ứng với các phương pháp điều trị, thuốc men, gây mê, trị liệu tâm lý, chương trình phục hồi thể chất và các biện pháp phòng ngừa và chữa bệnh khác;', '- Thực hiện phẫu thuật có tính chất chung hoặc chuyên biệt;', '- Quản lý các biến chứng trước, trong và sau khi sinh con;', '- Ghi lại thông tin y tế của bệnh nhân và trao đổi thông tin với các chuyên gia y tế khác để đảm bảo cung cấp dịch vụ chăm sóc toàn diện;', '- Báo cáo sinh, tử và các bệnh đáng chú ý cho các cơ quan chính phủ để đáp ứng các yêu cầu pháp lý và chuyên nghiệp;', '- Cung cấp thông tin cho bệnh nhân và gia đình và cộng đồng về các biện pháp phòng ngừa, điều trị và chăm sóc cho các bệnh cụ thể;', '- Thực hiện khám nghiệm tử thi để xác định nguyên nhân tử vong;', '- Tiến hành nghiên cứu về các rối loạn và bệnh tật cụ thể của con người và các phương pháp phòng ngừa hoặc chữa bệnh và phổ biến các phát hiện như thông qua các báo cáo khoa học;', '- Lập kế hoạch và tham gia vào các chương trình được thiết kế để ngăn chặn sự xuất hiện và lây lan của các bệnh cụ thể.']::text[], array['- Bác sĩ gây mê', '- Bác sĩ tim mạch', '- Bác sĩ chuyên khoa cấp cứu', '- Bác sĩ phụ khoa', '- Bác sĩ sản khoa', '- Bác sĩ nhãn khoa', '- Bác sĩ nhi khoa', '- Chuyên gia bệnh lý học', '- Chuyên gia y tế dự phòng', '- Bác sĩ tâm thần', '- Bác sĩ ung bướu', '- Bác sĩ X-quang', '- Cán bộ y tế thường trú trong đào tạo bác sĩ chuyên khoa', '- Chuyên gia y tế (y tế công cộng)', '- Bác sĩ chuyên khoa (nội khoa)', '- Bác sĩ chuyên khoa (y học hạt nhân)', '- Bác sĩ phẫu thuật']::text[], array['- Nhà nghiên cứu y sinh - 2131', '- Bác sĩ đa khoa - 2211', '- Bác sỹ nội trú - 2211', '- Bác sĩ nha khoa - 2261', '- Bác sĩ phẫu thuật nha khoa - 2261', '- Nhà tâm lý học lâm sàng - 2634', 'Ghi chú:', 'Nghề nghiệp trong nhóm này yêu cầu hoàn thành trình độ đại học giáo dục y tế cơ bản cộng với nghiên cứu sinh đào tạo lâm sàng trong một chuyên môn y tế (trừ trường hợp bác sĩ đa khoa) hoặc tương đương. Bác sĩ y tế thường trú và nội trú đào tạo như học chuyên (trừ bác sĩ đa khoa) đều được bao gồm ở đây. Mặc dù trong “Nha khoa” một số quốc gia có thể được coi là một chuyên khoa, thầy thuốc chuyên khoa miệng nên được xếp vào nhóm 2261. Bác sĩ răng - hàm - mặt.', 'Các chuyên gia nghiên cứu y học tham gia nghiên cứu y sinh sử dụng các sinh vật sống và không thực hiện lâm sàng được phân loại trong nhóm 2131: Nhà sinh vật học, thực vật học, động vật học và các chuyên môn liên quan.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 425) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2221', 'Y tá/điều dưỡng (cao cấp) cung cấp các dịch vụ điều trị, hỗ trợ và chăm sóc cho những người cần chăm sóc điều dưỡng do ảnh hưởng của lão hóa, chấn thương, bệnh tật hoặc suy yếu về thể chất hoặc tinh thần khác, hoặc nguy cơ tiềm ẩn đối với sức khỏe. Họ chịu trách nhiệm lập kế hoạch và quản lý chăm sóc bệnh nhân, bao gồm cả sự giám sát của các nhân viên y tế khác, làm việc tự chủ hoặc trong các nhóm với bác sĩ y tế và những người khác trong việc áp dụng thực tế các biện pháp phòng ngừa và chữa bệnh.', array['- Lập kế hoạch, cung cấp và đánh giá chăm sóc điều dưỡng cho bệnh nhân theo thông lệ và tiêu chuẩn của điều dưỡng hiện đại;', '- Phối hợp chăm sóc bệnh nhân với sự tư vấn của các chuyên gia y tế khác và các thành viên của các đội y tế;', '- Xây dựng và triển khai các kế hoạch chăm sóc cho điều trị sinh học, xã hội và tâm lý của bệnh nhân phối hợp với các chuyên gia y tế khác;', '- Lập kế hoạch và cung cấp dịch vụ chăm sóc cá nhân, phương pháp điều trị và trị liệu bao gồm quản lý thuốc và theo dõi các phản ứng đối với kế hoạch điều trị hoặc chăm sóc;', '- Làm sạch vết thương, băng bó và băng phẫu thuật;', '- Theo dõi cơn đau và sự khó chịu của bệnh nhân và giảm đau bằng nhiều phương pháp điều trị, bao gồm sử dụng thuốc giảm đau;', '- Lập kế hoạch và tham gia các chương trình giáo dục sức khỏe, tăng cường sức khỏe và các hoạt động giáo dục y tá trong môi trường lâm sàng và cộng đồng;', '- Trả lời các câu hỏi của bệnh nhân và gia đình và cung cấp thông tin về phòng ngừa bệnh tật, điều trị và chăm sóc sức khỏe;', '- Giám sát và điều phối công việc của các nhân viên điều dưỡng, y tế và chăm sóc cá nhân khác;', '- Tiến hành nghiên cứu về thực hành và quy trình điều dưỡng và phổ biến các kết quả như thông qua các bài báo và báo cáo khoa học.']::text[], array['- Nhà tư vấn y tá/điều dưỡng lâm sàng', '- Y tá/điều dưỡng tuyến huyện', '- Y tá/điều dưỡng gây mê', '- Người đào tạo y tá/điều dưỡng', '- Thực tập viên y tá/điều dưỡng', '- Y tá/điều dưỡng phụ mổ', '- Y tá/điều dưỡng cao cấp', '- Y tá/điều dưỡng sức khỏe cộng đồng', '- Y tá/điều dưỡng chuyên khoa']::text[], array['- Hộ sinh (cao cấp) - 2222', '- Bác sỹ phụ tá - 2240', '- Giảng viên đại học - 2311', '- Giáo viên trung cấp - 2320', '- Y tá/điều dưỡng(chính) - 3221', '- Hộ sinh (chính) - 3222', '- Trợ lý y tá/điều dưỡng (phòng khám hoặc bệnh viện) - 5321', 'Ghi chú:', 'Sự khác biệt giữa các y tá/điều dưỡng cao cấp và y tá/điều dưỡng chính dựa trên cơ sở tính chất của công việc.', 'Y tá/điều dưỡng kết hợp giáo dục y tá/điều dưỡng hoặc nghiên cứu với thực hành y tá/điều dưỡng lâm sàng được phân loại trong nhóm 2221. Y tá/điều dưỡng (cao cấp). Các nhà nghiên cứu y tá/điều dưỡng tham gia nghiên cứu y sinh sử dụng các sinh vật sống và không thực hiện y tá/điều dưỡng lâm sàng được phân loại trong nhóm 2131: Nhà sinh vật học, thực vật học, động vật học và các chuyên môn liên quan.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 473) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2222', 'Hộ sinh (cao cấp) lập kế hoạch, quản lý, cung cấp và đánh giá các dịch vụ chăm sóc hộ sinh trước, trong và sau khi mang thai và sinh nở. Họ cung cấp dịch vụ chăm sóc chuyển dạ để giảm rủi ro sức khỏe cho phụ nữ và trẻ sơ sinh, làm việc tự chủ hoặc trong các nhóm với các nhà cung cấp dịch vụ chăm sóc sức khỏe khác.', array['- Lập kế hoạch, cung cấp và đánh giá các dịch vụ chăm sóc và hỗ trợ cho phụ nữ và trẻ sơ sinh trước, trong và sau khi mang thai và sinh con theo thông lệ và tiêu chuẩn chăm sóc hộ sinh hiện đại;', '- Cung cấp lời khuyên cho phụ nữ và gia đình và thực hiện giáo dục cộng đồng về sức khỏe, dinh dưỡng, vệ sinh, tập thể dục, kế hoạch sinh và cấp cứu, cho con bú, chăm sóc trẻ sơ sinh, kế hoạch hóa gia đình và tránh thai, lối sống và các chủ đề khác liên quan đến mang thai và sinh nở;', '- Đánh giá tiến triển trong khi mang thai và sinh nở, quản lý các biến chứng và nhận biết các dấu hiệu cảnh báo cần được giới thiệu đến bác sĩ y khoa có kỹ năng chuyên môn về sản khoa;', '- Theo dõi tình trạng sức khỏe của trẻ sơ sinh, các biến chứng và nhận biết các dấu hiệu cảnh báo cần được giới thiệu đến bác sĩ y khoa có kỹ năng chuyên môn về sơ sinh;', '- Theo dõi cơn đau và sự khó chịu của phụ nữ trong quá trình chuyển dạ và sinh nở và giảm đau bằng nhiều phương pháp trị liệu, bao gồm sử dụng thuốc giảm đau;', '- Báo cáo sinh cho cơ quan chính phủ để đáp ứng các yêu cầu pháp lý và chuyên nghiệp;', '- Tiến hành nghiên cứu về thực hành và quy trình hộ sinh và phổ biến các kết quả như thông qua các bài báo và báo cáo khoa học;', '- Lập kế hoạch và tiến hành các hoạt động giáo dục hộ sinh trong môi trường lâm sàng và cộng đồng.']::text[], array['Nữ hộ sinh cao cấp']::text[], array['- Y tá/điều dưỡng cao cấp - 2221', '- Y tá/điều dưỡng chính - 3221', '- Hộ sinh chính - 3222', '- Trợ lý y tá/điều dưỡng (phòng khám hoặc bệnh viện) - 5321', 'Ghi chú:', 'Sự khác biệt giữa các y tá/điều dưỡng cao cấp, hộ sinh cao cấp và y tá/điều dưỡng chính, hộ sinh chính trên cơ sở tính chất của công việc. Hộ sinh kết hợp giáo dục hộ sinh hoặc nghiên cứu với thực hành hộ sinh lâm sàng được phân loại trong nhóm 2222. Hộ sinh (cao cấp).']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 507) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2230', 'Nhà chuyên môn về y học cổ truyền và hỗ trợ kiểm tra bệnh nhân, phòng ngừa và điều trị bệnh, chấn thương và các khiếm khuyết về thể chất và tinh thần khác và duy trì sức khỏe nói chung ở người bằng cách áp dụng kiến ​​thức, kỹ năng và thực hành có được thông qua nghiên cứu rộng rãi về lý thuyết, niềm tin và kinh nghiệm, bắt nguồn từ cụ thể các nền văn hóa.', array['- Tiến hành kiểm tra thể chất của bệnh nhân và phỏng vấn họ và gia đình họ để xác định tình trạng sức khỏe của họ;', '- Xây dựng và triển khai các kế hoạch điều trị cho các bệnh về thể chất, tinh thần và tâm lý xã hội bằng các ứng dụng như châm cứu, ayurvedic, vi lượng đồng căn và thảo dược;', '- Đánh giá và ghi nhận bệnh nhân tiến triển qua kế hoạch điều trị;', '- Cung cấp tư vấn về sức khỏe, dinh dưỡng và lối sống cho các cá nhân, gia đình và cộng đồng;', '- Kê đơn và pha chế các loại thuốc truyền thống như chiết xuất thảo dược, thực vật, khoáng chất và động vật, để kích thích khả năng tự chữa bệnh của cơ thể;', '- Trao đổi thông tin về bệnh nhân với các nhân viên chăm sóc sức khỏe khác khi cần thiết để đảm bảo chăm sóc sức khỏe liên tục và toàn diện;', '- Tiến hành nghiên cứu các loại thuốc và phương pháp điều trị truyền thống, bổ sung và phổ biến các phát hiện như thông qua các bài báo và báo cáo khoa học.']::text[], array['- Chuyên gia châm cứu', '- Thực hành viên y học hindu', '- Bác sĩ y học cổ truyền Trung Quốc', '- Nhà chuyên môn vi lượng đồng căn', '- Nhà chuyên môn về thiên nhiên liệu pháp', '- Thực hành viên y học Hồi giáo']::text[], array['- Người trị bệnh xương khớp - 2269', '- Kỹ thuật viên châm cứu - 3230', '- Kỹ thuật viên Hindu - 3230', '- Người trồng và bán thảo dược - 3230', '- Kỹ thuật viên bệnh lý cơ tim - 3230', '- Trị liệu nạo và uốn nắn - 3230', '- Người chữa bệnh làng - 3230', '- Thầy mo - 3230', '- Kỹ thuật viên bấm huyệt trị liệu - 3255', '- Kỹ thuật viên thủy liệu pháp - 3255', '- Kỹ thuật viên trị liệu Shiatsu - 3255', '- Người chữa lành đức tin - 3413', 'Ghi chú:', 'Nhà chuyên môn về y học cổ truyền và hỗ trợ đòi hỏi một sự hiểu biết sâu rộng về những lợi ích và các ứng dụng của y học cổ truyền và hỗ trợ, được phát triển từ những kết quả của nghiên cứu chính thức về những kỹ thuật này cũng như trên cơ thể con người và các yếu tố của y học hiện đại, được phân loại trong mã nghề 2230: Nhà chuyên môn về y học cổ truyền và hỗ trợ. Những nghề nghiệp mà thực hành đòi hỏi sự hiểu biết ít hơn dựa trên thời gian giáo dục và đào tạo chính thức hoặc không chính thức, hoặc thông qua các truyền thống và thực hành của cộng đồng nơi họ sinh sống, được bao gồm trong nhóm 3230. Kỹ thuật viên y học cổ truyền và bổ trợ. Các học viên thực hiện ứng dụng số ít các phương pháp tiếp cận với thuốc thảo dược, liệu pháp tinh thần hoặc kỹ thuật trị liệu thủ công được loại trừ khỏi nhóm 2230.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 527) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2240', 'Bác sỹ phụ tá cung cấp các dịch vụ y tế tư vấn, chẩn đoán, chữa bệnh và phòng ngừa hạn chế về phạm vi và độ phức tạp hơn so với các bác sĩ y khoa thực hiện. Họ làm việc tự chủ, hoặc có sự giám sát hạn chế của các bác sĩ y khoa và áp dụng các quy trình lâm sàng tiên tiến để điều trị và ngăn ngừa bệnh tật, thương tích và các khiếm khuyết về thể chất hoặc tinh thần khác cho cộng đồng.', array['- Tiến hành kiểm tra thể chất cho bệnh nhân và phỏng vấn họ và gia đình họ để xác định tình trạng sức khỏe của họ và ghi lại thông tin y tế của bệnh nhân;', '- Thực hiện các thủ tục y tế và phẫu thuật cơ bản hoặc thường quy hơn, bao gồm kê đơn và quản lý các phương pháp điều trị, thuốc men và các biện pháp phòng ngừa hoặc chữa bệnh khác, đặc biệt đối với các bệnh và rối loạn thông thường;', '- Quản lý hoặc đặt hàng các xét nghiệm chẩn đoán, chẳng hạn như X-quang, điện tâm đồ và xét nghiệm trong phòng thí nghiệm;', '- Thực hiện các thủ tục điều trị như tiêm, chích ngừa, khâu vết thương và chăm sóc vết thương và quản lý nhiễm trùng;', '- Hỗ trợ bác sĩ y khoa với các thủ tục phẫu thuật phức tạp;', '- Theo dõi bệnh nhân tiến triển và đáp ứng điều trị và xác định các dấu hiệu và triệu chứng cần chuyển đến bác sĩ y khoa;', '- Tư vấn cho bệnh nhân và gia đình về chế độ ăn uống, tập thể dục và các thói quen khác giúp phòng ngừa hoặc điều trị bệnh và rối loạn;', '- Xác định và chuyển các trường hợp phức tạp hoặc bất thường đến bác sĩ y tế, bệnh viện hoặc những nơi khác để được chăm sóc chuyên khoa;', '- Báo cáo sinh, tử và các bệnh đáng chú ý cho các cơ quan chính phủ để đáp ứng các yêu cầu báo cáo pháp lý và chuyên nghiệp.']::text[], array['- Bác sỹ phụ tá hồi sức', '- Bác sĩ lâm sàng (trợ y)', '- Trợ lí bác sĩ', '- Nhân viên chăm sóc chính', '- Kỹ thuật viên phẫu thuật']::text[], array['- Bác sĩ đa khoa - 2211', '- Bác sĩ phẫu thuật - 2212', '- Trợ lý y tế - 3256', '- Nhân viên cứu thương - 3258', 'Ghi chú:', 'Nghề nghiệp trong nhóm này thường yêu cầu hoàn thành đào tạo đại học trong các dịch vụ y tế lý thuyết và thực tế. Người làm việc với các dịch vụ giới hạn trong điều trị khẩn cấp và thực hành cấp cứu được phân loại trong nhóm 3258. Nhân viên cấp cứu.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 559) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2250', 'Bác sĩ thú y chẩn đoán, điều trị bệnh và phòng ngừa bệnh tật, thương tích và rối loạn chức năng của động vật. Họ có thể chăm sóc cho nhiều loại động vật hoặc chuyên điều trị một nhóm động vật cụ thể hoặc trong một lĩnh vực chuyên môn cụ thể hoặc cung cấp dịch vụ chuyên nghiệp cho các công ty thương mại sản xuất các sản phẩm sinh học và dược phẩm. Đồng thời, Bác sỹ thú y thực hiện công việc trong phòng thí nghiệm, chẩn đoán xét nghiệm vi trùng, vi rút, sử dụng kỹ thuật sinh học phân tử, nuôi cấy, phân lập xác định nguyên nhân gây bệnh; thử nghiệm bệnh động vật; xây dựng tiêu chuẩn, quy chuẩn chẩn đoán xét nghiệm bệnh động vật trên cạn và dưới nước.', array['- Xác định sự hiện diện và bản chất của các điều kiện bất thường bằng cách kiểm tra thể chất, xét nghiệm trong phòng thí nghiệm và thông qua các kỹ thuật chẩn đoán hình ảnh bao gồm chụp X-quang và siêu âm;', '- Điều trị cho động vật về mặt y tế và phẫu thuật, quản lý và kê đơn thuốc, thuốc giảm đau, thuốc gây mê nói chung và tại chỗ;', '- Thực hiện phẫu thuật, băng vết thương và đặt xương gãy;', '- Cung cấp dịch vụ sản khoa;', '- Tham gia vào các chương trình được thiết kế để ngăn chặn sự xuất hiện và lây lan của bệnh động vật;', '- Theo dõi sức khỏe động vật và tiêm phòng cho động vật theo lịch tiêm phòng;', '- Xét nghiệm các bệnh động vật, bệnh truyền nhiễm, bệnh truyền lây giữa người và động vật theo chức năng, nhiệm vụ, yêu cầu của cơ quan quản lý và người chăn nuôi;', '- Chẩn đoán bệnh động vật mới xuất hiện trên lãnh thổ Việt Nam và đề xuất các biện pháp phòng, chống dịch bệnh;', 'Thực hiện lưu giữ vi sinh vật để chẩn đoán, xác định dịch bệnh động vật theo quy định pháp luật;', '- Thực hiện mổ khám xác động vật để xác định nguyên nhân gây chết (lâm sàng) để định hướng chuẩn đoán xét nghiệm xác định nguyên nhân gây chết (xét nghiệm);', '- Tư vấn cho khách hàng về sức khỏe, dinh dưỡng và cho ăn, vệ sinh, chăn nuôi và chăm sóc động vật;', '- Cung cấp dịch vụ chẩn đoán xét nghiệm và dịch vụ khác.']::text[], array['- Nhà bệnh lý về động vật;', '- Nhà chuẩn đoán xét nghiệm bệnh động vật trong phòng thí nghiệm;', '- Bác sĩ thú y;', '- Nhà chuyên môn về dịch tễ học thú y;', '- Nhà chuyên môn thú y cộng đồng;', '- Nhà chuyên môn về kiểm dịch động vật, sản phẩm động vật trên cạn và thủy sản;', '- Nhà chuyên môn về vệ sinh thú y;', '- Nhà chuyên môn về thuốc thú y;', '- Thực tập sinh thú y;', '- Bác sĩ phẫu thuật thú y.']::text[], '{}'::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Thú y, phòng và chữa bệnh thủy sản.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 584) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2261', 'Bác sỹ răng hàm mặt chẩn đoán, điều trị và ngăn ngừa các bệnh, chấn thương và bất thường của răng, miệng, hàm và các mô liên quan bằng cách áp dụng các nguyên tắc và quy trình của nha khoa hiện đại. Họ sử dụng một loạt các chẩn đoán chuyên ngành, phẫu thuật và các kỹ thuật khác để thúc đẩy và phục hồi sức khỏe răng miệng.', array['- Chẩn đoán bệnh, chấn thương, bất thường và dị tật của răng và các cấu trúc liên quan trong miệng và hàm bằng một loạt phương pháp như X-quang, xét nghiệm nước bọt và lịch sử bệnh lý;', '- Cung cấp dịch vụ chăm sóc sức khỏe răng miệng phòng ngừa như điều trị nha chu, ứng dụng fluoride và tăng cường sức khỏe răng miệng;', '- Quản lý thuốc gây mê để hạn chế số lượng đau của bệnh nhân trong quá trình điều trị;', '- Kê đơn thuốc để giảm đau liên tục sau khi làm thủ thuật;', '- Cung cấp dịch vụ chăm sóc răng miệng như cấy ghép, phục hình răng, cầu răng phức tạp, chỉnh nha, sửa chữa răng bị hư hỏng và sâu răng;', '- Cung cấp các phương pháp điều trị phẫu thuật như nhổ răng, sinh thiết mô và thực hiện điều trị chỉnh nha;', '- Đo lường và lấy dấu ấn của bệnh nhân hàm và răng để xác định hình dạng và kích thước của phục hình răng;', '- Thiết kế, chế tạo và lắp các dụng cụ phục hình răng như dụng cụ duy trì không gian, cầu răng và răng giả, viết hướng dẫn chế tạo hoặc đơn thuốc cho kỹ thuật viên phục hình răng;', '- Phục hồi chức năng miệng với các bộ phận giả có thể tháo rời và cố định;', '- Hỗ trợ chẩn đoán các bệnh thông thường có các biểu hiện ở miệng như bệnh tiểu đường;', '- Giáo dục bệnh nhân và gia đình về vệ sinh răng miệng, dinh dưỡng và các biện pháp khác để chăm sóc sức khỏe răng miệng;', '- Giám sát vệ sinh nha khoa, trợ lý nha khoa và nhân viên khác.']::text[], array['- Thực hành viên răng hàm mặt', '- Bác sĩ phẫu thuật răng hàm mặt', '- Bác sỹ răng hàm mặt', '- Bác sỹ nội khoa răng hàm mặt', '- Bác sĩ phẫu thuật miệng và hàm', '- Nhà chuyên môn về bệnh lý miệng', '- Bác sỹ thẩm mỹ răng miệng', '- Bác sĩ nha nhi khoa', '- Bác sĩ phục hình răng miệng', '- Bác sĩ chuyên khoa miệng', 'Ghi chú:', 'Nghề nghiệp trong nhóm này thường yêu cầu hoàn thành đào tạo trình độ đại học về răng hàm mặt lý thuyết và thực hành hoặc một lĩnh vực liên quan. Ở một số nước, bác sỹ chữa bệnh về miệng có thể được coi là bác sỹ chuyên khoa, nhưng nghề này nên được phân loại ở đây.']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 614) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2262', 'Dược sĩ lưu trữ, bảo quản hợp chất và phân phối các sản phẩm thuốc; tư vấn về việc sử dụng đúng cách và tác dụng phụ của thuốc theo đơn của bác sĩ và các chuyên gia y tế khác. Họ góp phần nghiên cứu, thử nghiệm, chuẩn bị, kê đơn và theo dõi các liệu pháp y học để tối ưu hóa sức khỏe con người.', array['- Nhận đơn thuốc cho các sản phẩm thuốc từ bác sĩ y khoa và các chuyên gia y tế khác, kiểm tra bệnh nhân lịch sử y học, đảm bảo liều lượng, phương pháp thích hợp và tương thích thuốc trước khi pha chế;', '- Chuẩn bị hoặc giám sát việc chuẩn bị và ghi nhãn thuốc lỏng, thuốc mỡ, bột, thuốc viên và các loại thuốc khác để điền vào đơn thuốc;', '- Cung cấp thông tin và lời khuyên cho người kê đơn và khách hàng về tương tác thuốc, không tương thích và chống chỉ định, tác dụng phụ, liều lượng và lưu trữ thuốc thích hợp;', '- Hợp tác với các chuyên gia chăm sóc sức khỏe khác để lập kế hoạch, theo dõi, xem xét và đánh giá chất lượng và hiệu quả của liệu pháp điều trị thuốc của từng bệnh nhân và hiệu quả của các loại thuốc hoặc liệu pháp cụ thể;', '- Duy trì các hồ sơ theo toa và ghi lại vấn đề ma túy, chất độc và thuốc gây nghiện theo các yêu cầu pháp lý và chuyên nghiệp;', '- Lưu trữ và bảo quản vắc-xin, huyết thanh và các loại thuốc khác bị hư hỏng;', '- Tư vấn cho khách hàng và cung cấp các loại thuốc không kê đơn và các phương tiện chẩn đoán và điều trị cho các tình trạng phổ biến;', '- Giám sát và điều phối công việc của các kỹ thuật viên dược, thực tập dược và trợ lý bán hàng dược;', '- Tiến hành nghiên cứu để phát triển và cải tiến dược phẩm, mỹ phẩm và các sản phẩm hóa học liên quan;', '- Trao đổi với các nhà hóa học, chuyên gia kỹ thuật và các chuyên gia khác về kỹ thuật sản xuất và thành phần;', '- Thử nghiệm và phân tích thuốc để xác định danh tính, độ tinh khiết và sức mạnh của chúng liên quan đến các tiêu chuẩn quy định;', '- Đánh giá nhãn, bao bì và quảng cáo sản phẩm thuốc;', '- Phát triển thông tin và rủi ro của các loại thuốc cụ thể.']::text[], array['- Nhà hóa học pha chế', '- Dược sĩ bệnh viện', '- Dược sĩ sản xuất thuốc', '- Dược sĩ kiểm nghiệm thuốc', '- Dược sĩ lâm sàng']::text[], array['- Nhà dược lý học - 2131', '- Kỹ thuật viên dược phẩm - 3213']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 642) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2263', 'Nhà chuyên môn về vệ sinh môi trường và bệnh nghề nghiệp đánh giá, lập kế hoạch và thực hiện các chương trình để nhận biết, giám sát và kiểm soát các yếu tố môi trường có khả năng ảnh hưởng đến sức khỏe con người, đảm bảo điều kiện làm việc an toàn và lành mạnh và ngăn ngừa bệnh tật hoặc thương tích do các tác nhân hóa học, vật lý, phóng xạ và sinh học hoặc các yếu tố công thái học.', array['- Xây dựng, triển khai và xem xét các chương trình và chính sách để giảm thiểu rủi ro môi trường và nghề nghiệp tiềm ẩn đối với sức khỏe và an toàn;', '- Chuẩn bị và thực hiện các kế hoạch và chiến lược để xử lý chất thải thương mại, công nghiệp, y tế và hộ gia đình một cách an toàn, kinh tế và phù hợp;', '- Thực hiện các chương trình và chiến lược phòng chống các bệnh truyền nhiễm, an toàn thực phẩm, hệ thống xử lý nước thải, chất lượng nước sinh hoạt, các chất độc hại và nguy hiểm;', '- Xác định, báo cáo và ghi lại các mối nguy hiểm, đánh giá và kiểm soát rủi ro trong môi trường và nơi làm việc và tư vấn về việc tuân thủ luật pháp và quy định có liên quan;', '- Xây dựng, triển khai và giám sát các chương trình để giảm thiểu ô nhiễm môi trường và nơi làm việc liên quan đến các mối nguy hóa học, vật lý và sinh học;', '- Tư vấn về các phương pháp để ngăn chặn, loại bỏ, kiểm soát hoặc giảm sự phơi nhiễm của công nhân, học sinh, công chúng và môi trường đối với các nguy cơ phóng xạ và các mối nguy khác;', '- Thúc đẩy các nguyên tắc công thái học tại nơi làm việc như kết hợp đồ nội thất, thiết bị và các hoạt động làm việc với nhu cầu của nhân viên;', '- Cung cấp giáo dục, thông tin, đào tạo và tư vấn cho mọi người ở tất cả các cấp về các khía cạnh của vệ sinh lao động và sức khỏe môi trường;', '- Ghi lại và điều tra các thương tích, hư hỏng thiết bị và báo cáo hiệu suất an toàn;', '- Phối hợp sắp xếp để bồi thường, phục hồi và trở lại làm việc của công nhân bị thương.']::text[], array['- Nhà chuyên môn về y tế môi trường', '- Nhà tư vấn về an toàn và bệnh nghề nghiệp', '- Nhà chuyên môn về vệ sinh nghề nghiệp', '- Chuyên gia về bảo vệ bức xạ']::text[], array['- Nhà chuyên môn về bảo vệ môi trường - 2133', '- Chuyên gia y tế (y tế công cộng) - 2212', '- Y tá/điều dưỡng chuyên khoa (y tế công cộng) - 2221', '- Bác sỹ trị liệu nghề nghiệp - 2269', '- Thanh tra y tế - 3257', '- Thanh tra an toàn và bệnh nghề nghiệp - 3257', '- Nhân viên về an toàn vệ sinh - 3257', '- Thanh tra vệ sinh - 3257', 'Ghi chú:', 'Các chuyên gia đánh giá, lập kế hoạch và thực hiện các chương trình giám sát hoặc kiểm soát tác động của các hoạt động của con người đến môi trường được phân loại trong nhóm 2133. Nhà chuyên môn về bảo vệ môi trường.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 667) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2264', 'Nhà chuyên môn về vật lý trị liệu đánh giá, lập kế hoạch và thực hiện các chương trình phục hồi hoặc cải thiện hoặc các chức năng vận động của con người, tối đa hóa khả năng vận động, giảm các hội chứng đau và điều trị hoặc ngăn ngừa các thách thức về thể chất liên quan đến chấn thương, bệnh tật và các suy yếu khác. Họ áp dụng một loạt các liệu pháp và kỹ thuật vật lý như chuyển động, siêu âm, sưởi ấm, laser và các kỹ thuật khác.', array['- Khám cơ, dây thần kinh, các khả năng về chức năng khớp và các xét nghiệm khác để xác định và đánh giá các vấn đề về thể chất của bệnh nhân;', '- Thiết lập mục tiêu điều trị với bệnh nhân và thiết kế các chương trình điều trị để giảm đau cơ thể, tăng cường cơ bắp, cải thiện chức năng tim mạch và hô hấp, khôi phục khả năng vận động của khớp và cải thiện sự cân bằng và phối hợp;', '- Xây dựng, triển khai và giám sát các chương trình và phương pháp điều trị bằng cách sử dụng các đặc tính trị liệu của tập thể dục, nóng, lạnh, xoa bóp, thao tác, thủy trị liệu, điện trị liệu, tia cực tím, tia hồng ngoại và siêu âm trong điều trị bệnh nhân;', '- Hướng dẫn bệnh nhân và gia đình họ các thủ tục được tiếp tục bên ngoài các cơ sở lâm sàng;', '- Ghi lại thông tin về bệnh nhân, tình trạng sức khỏe và phản ứng của bệnh nhân đối với việc điều trị trong các hệ thống lưu giữ hồ sơ y tế và chia sẻ thông tin với các chuyên gia y tế khác theo yêu cầu để đảm bảo chăm sóc liên tục và toàn diện;', '- Xây dựng và triển khai các chương trình sàng lọc và phòng ngừa các bệnh và rối loạn cơ thể thông thường;', '- Giám sát công việc của các trợ lý vật lý trị liệu và những người khác.']::text[], array['- Nhà chuyên môn về vật lý trị liệu lão khoa', '- Nhà chuyên môn trị liệu thao tác', '- Nhà chuyên môn trị liệu vật lý chỉnh hình', '- Nhà chuyên môn trị liệu vật lý nhi', '- Nhà chuyên môn vật lý trị liệu', '- Bác sĩ vật lý trị liệu']::text[], array['- Nhà chuyên môn nắn chỉnh cột sống - 2269', '- Nhà chuyên môn trị liệu bệnh nghề nghiệp - 2269', '- Nhà chuyên môn trị bệnh xương khớp - 2269', '- Bác sĩ phẫu thuật - 2269', '- Kỹ thuật viên trị liệu bấm huyệt - 3255', '- Kỹ thuật viên thủy liệu pháp - 3255', '- Kỹ thuật viên trị liệu bằng massage - 3255', '- Kỹ thuật viên vật lý trị liệu - 3255', '- Kỹ thuật viên trị liệu Shiatsu - 3255']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 696) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2265', 'Nhà chuyên môn về dinh dưỡng đánh giá, lập kế hoạch và thực hiện các chương trình để tăng cường tác động của thực phẩm và dinh dưỡng đối với sức khỏe con người.', array['- Hướng dẫn các cá nhân, gia đình và cộng đồng về dinh dưỡng, lập kế hoạch ăn kiêng và chuẩn bị thực phẩm để tối đa hóa lợi ích sức khỏe và giảm rủi ro tiềm ẩn cho sức khỏe;', '- Lập kế hoạch chế độ ăn kiêng và thực đơn, giám sát việc chuẩn bị và phục vụ bữa ăn, giám sát lượng thức ăn và chất lượng thực phẩm để cung cấp dịch vụ chăm sóc dinh dưỡng trong các cơ sở cung cấp dịch vụ thực phẩm;', '- Tổng hợp và đánh giá dữ liệu liên quan đến tình trạng sức khỏe và dinh dưỡng của các cá nhân, nhóm và cộng đồng dựa trên các giá trị dinh dưỡng của thực phẩm được phục vụ hoặc tiêu thụ;', '- Lập kế hoạch và thực hiện đánh giá dinh dưỡng, các chương trình can thiệp, giáo dục và đào tạo để cải thiện mức độ dinh dưỡng giữa các cá nhân và cộng đồng;', '- Tư vấn với các chuyên gia y tế và các nhà cung cấp dịch vụ chăm sóc khác để quản lý nhu cầu ăn uống và dinh dưỡng của bệnh nhân;', '- Phát triển và đánh giá thực phẩm và các sản phẩm dinh dưỡng để đáp ứng yêu cầu dinh dưỡng;', '- Tiến hành nghiên cứu về dinh dưỡng và phổ biến các phát hiện tại các hội thảo khoa học và trong các môi trường khác.']::text[], array['- Chuyên gia dinh dưỡng lâm sàng', '- Chuyên gia dinh dưỡng thực phẩm', '- Nhà dinh dưỡng học', '- Chuyên gia dinh dưỡng y tế công cộng', '- Chuyên gia dinh dưỡng thể thao']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 723) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2266', 'Bác sỹ thính học và đặc trị các khuyết tật về ngôn ngữ đánh giá, quản lý và điều trị các rối loạn thể chất ảnh hưởng đến thính giác, lời nói, giao tiếp và nuốt của con người. Họ kê toa các thiết bị khắc phục hoặc các liệu pháp phục hồi chức năng cho mất thính giác, rối loạn ngôn ngữ và các vấn đề về cảm giác và thần kinh liên quan, và cung cấp tư vấn về an toàn thính giác và thực hiện giao tiếp.', array['- Đánh giá hiệu suất nghe, nói và ngôn ngữ ở bệnh nhân để xác định bản chất của rối loạn thính giác và giao tiếp;', '- Quản lý các bài kiểm tra thính giác hoặc lời nói/ngôn ngữ hoặc các kỳ thi khác bằng các dụng cụ và thiết bị chẩn đoán chuyên ngành và diễn giải kết quả xét nghiệm cùng với các dữ liệu chẩn đoán y tế, xã hội và hành vi khác để xác định các liệu trình điều trị thích hợp;', '- Lập kế hoạch, chỉ đạo và tham gia tư vấn, sàng lọc, phục hồi lời nói và các chương trình khác liên quan đến thính giác và giao tiếp;', '- Kê toa máy trợ thính và các thiết bị trợ giúp khác theo nhu cầu của bệnh nhân và hướng dẫn họ sử dụng;', '- Lập kế hoạch và tiến hành các chương trình điều trị để quản lý các rối loạn thể chất ảnh hưởng đến việc nói và nuốt;', '- Tư vấn và hướng dẫn điều trần các cá nhân bị khiếm khuyết ngôn ngữ, gia đình, giáo viên và người sử dụng lao động của họ;', '- Giới thiệu bệnh nhân và gia đình đến các dịch vụ y tế hoặc giáo dục hỗ trợ nếu cần.']::text[], array['- Chuyên gia thính học', '- Chuyên gia trị liệu ngôn ngữ', '- Chuyên gia trị liệu lời nói']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 739) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2267', 'Nhà chuyên môn về thị lực và nhãn khoa cung cấp các dịch vụ chẩn đoán, quản lý và điều trị các rối loạn về mắt và hệ thống thị giác. Họ tư vấn về chăm sóc mắt và kê toa các phương tiện quang học hoặc các liệu pháp khác để điều trị rối loạn thị giác.', array['- Kiểm tra mắt bệnh nhân và thực hiện các xét nghiệm chẩn đoán để đánh giá sức khỏe mắt, xác định bản chất và mức độ của các vấn đề bất thường về thị lực;', '- Kiểm tra chức năng thị giác bằng các dụng cụ và thiết bị chuyên dụng để đo thị lực và tật khúc xạ, chức năng của đường mòn thị giác, trường thị giác, chuyển động mắt, tự do thị lực và áp lực nội nhãn;', '- Phát hiện, chẩn đoán và quản lý bệnh về mắt bao gồm kê đơn thuốc để điều trị;', '- Tư vấn và giới thiệu bệnh nhân đến bác sĩ nhãn khoa hoặc các chuyên gia y tế khác nếu điều trị y tế bổ sung là cần thiết;', '- Phát hiện và chẩn đoán rối loạn chuyển động mắt và khiếm khuyết chức năng hai mắt, lập kế hoạch và quản lý các chương trình điều trị bao gồm tư vấn cho bệnh nhân trong các bài tập mắt để phối hợp chuyển động và tập trung của mắt;', '- Kê toa kính mắt hiệu chỉnh, kính áp tròng và các thiết bị hỗ trợ thị lực khác, kiểm tra các thiết bị quang học về hiệu suất, an toàn;', '- Tư vấn về các vấn đề sức khỏe thị giác như chăm sóc kính áp tròng, chăm sóc thị lực cho người già, quang học, công thái thị giác và an toàn mắt nghề nghiệp và công nghiệp.']::text[], array['- Nhà chuyên môn về khúc xạ và thị lực', '- Bác sỹ đo thị lực', '- Bác sỹ chỉnh thị']::text[], array['- Bác sĩ nhãn khoa - 2212', '- Người bán và chỉnh kính - 3254']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 753) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2269', 'Nhà chuyên môn khác về sức khỏe chưa được phân vào đâu bao gồm các nghề nghiệp như bác sĩ phẫu thuật, trị liệu nghề nghiệp, trị liệu giải trí, nắn khớp xương, nắn xương và các chuyên gia khác cung cấp các dịch vụ y tế chẩn đoán, phòng ngừa, chữa bệnh và phục hồi chức năng.', array['- Phỏng vấn bệnh nhân và tiến hành các xét nghiệm chẩn đoán để xác định tình trạng sức khỏe, giới hạn chức năng và bản chất của rối loạn thể chất hoặc tâm thần, bệnh tật hoặc các vấn đề sức khỏe khác;', '- Xây dựng và triển khai các kế hoạch điều trị cho các chấn thương, bệnh tật và các khiếm khuyết về thể chất và tinh thần khác;', '- Đánh giá và ghi nhận bệnh nhân tiến triển qua kế hoạch điều trị và giới thiệu bệnh nhân và gia đình đến bác sĩ y tế hoặc các nhà cung cấp dịch vụ chăm sóc sức khỏe khác cho các dịch vụ chăm sóc chuyên khoa, phục hồi chức năng hoặc các dịch vụ chăm sóc khác khi cần thiết;', '- Quản lý, chăm sóc và điều trị cho bệnh nhân bao gồm thông qua việc áp dụng các kỹ thuật nắn xương, vật lý trị liệu bằng tay và vật lý trị liệu;', '- Khuyến nghị thích ứng môi trường trong môi trường gia đình, giải trí, làm việc và trường học trên cơ sở cá nhân hoặc nhóm để cho phép các cá nhân bị hạn chế chức năng thực hiện các hoạt động và nghề nghiệp hàng ngày của họ;', '- Lập kế hoạch và thực hiện các chương trình trị liệu trên cơ sở cá nhân và nhóm để cải thiện và duy trì các hoạt động thể chất, nhận thức, cảm xúc và xã hội thông qua việc sử dụng nghệ thuật, khiêu vũ và chuyển động, âm nhạc và các hoạt động giải trí khác;', '- Xác định và kê toa các phương pháp điều trị cho các tình trạng ảnh hưởng đến bàn chân, mắt cá chân và các cấu trúc liên quan của chân do bệnh tật hoặc suy yếu về thể chất khác, và kê toa giày dép điều chỉnh và tư vấn về chăm sóc bàn chân để kiểm soát các bệnh về chân;', '- Thực hiện các thủ tục tiểu phẫu như trên bàn chân và mắt cá chân.']::text[], array['- Nhà chuyên môn trị liệu nghệ thuật', '- Nhà chuyên môn trị bệnh về chân', '- Nhà chuyên môn trị liệu vũ đạo và vận động', '- Nhà chuyên môn trị liệu nghề nghiệp', '- Nhà chuyên môn trị bệnh xương khớp', '- Bác sĩ phẫu thuật', '- Nhà chuyên môn trị liệu giải trí', 'Ghi chú:', 'Mặc dù trong một số khu vực pháp lý trị liệu thần kinh cột sống và nắn xương được coi là có các thuộc tính của các chuyên ngành y tế tuy nhiên vẫn được phân loại ở đây.']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 770) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2311', 'Giảng viên đại học và cao học chuẩn bị và cung cấp các bài giảng và thực hiện các hướng dẫn trong một hoặc nhiều môn học trong một khóa học quy định tại một trường đại học hoặc tổ chức giáo dục đại học khác. Họ tiến hành nghiên cứu, chuẩn bị các bài báo và sách học thuật.', array['- Thiết kế và sửa đổi chương trình giảng dạy và chuẩn bị các khóa học theo yêu cầu;', '- Chuẩn bị và cung cấp các bài giảng và thực hiện các hướng dẫn, hội thảo và thí nghiệm trong phòng thí nghiệm;', '- Kích thích thảo luận và suy nghĩ độc lập giữa các sinh viên;', '- Giám sát công việc thử nghiệm và thực tế được thực hiện bởi sinh viên;', '- Quản lý, đánh giá, chấm bài thi và bài kiểm tra;', '- Chỉ đạo nghiên cứu của sinh viên sau đại học hoặc các thành viên khác của bộ phận;', '- Nghiên cứu và phát triển các khái niệm, lý thuyết và phương pháp hoạt động để ứng dụng trong các lĩnh vực công nghiệp và các lĩnh vực khác;', '- Chuẩn bị sách, bài báo hoặc bài báo học thuật;', '- Tham gia các cuộc họp của khoa, các hội nghị và hội thảo.']::text[], array['- Giảng viên giáo dục cao học', '- Giáo sư', '- Giảng viên đại học']::text[], array['- Hiệu trưởng trường đại học lớn - 1710', '- Hiệu trưởng trường đại học nhỏ - 1748', '- Trưởng khoa (đại học) - 1728', '- Trưởng khoa (đại học) - 173', '- Trưởng khoa giáo dục cao học - 1728', '- Trưởng khoa giáo dục cao học - 173', '- Giáo viên trung cấp - 2320']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 797) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2312', 'Giảng viên cao đẳng chuẩn bị và cung cấp các bài giảng và thực hiện các hướng dẫn trong một hoặc nhiều môn học trong một khóa học quy định tại một trường cao đẳng hoặc tổ chức giáo dục cao đẳng khác. Họ tiến hành nghiên cứu, và chuẩn bị các bài báo và sách học thuật.', array['- Thiết kế và sửa đổi chương trình giảng dạy và chuẩn bị các khóa học theo yêu cầu;', '- Chuẩn bị và cung cấp các bài giảng và thực hiện các hướng dẫn, hội thảo và thí nghiệm trong phòng thí nghiệm;', '- Kích thích thảo luận và suy nghĩ độc lập giữa các sinh viên;', '- Giám sát công việc thử nghiệm và thực tế được thực hiện bởi sinh viên;', '- Quản lý, đánh giá, chấm bài thi và bài kiểm tra;', '- Chỉ đạo nghiên cứu của sinh viên cao đẳng hoặc các thành viên khác của bộ phận;', '- Chuẩn bị sách, bài báo hoặc bài báo học thuật;', '- Tham gia các cuộc họp của khoa, các hội nghị và hội thảo.']::text[], array['- Giảng viên cao đẳng']::text[], array['- Hiệu trưởng trường đại học lớn - 1710', '- Hiệu trưởng trường đại học nhỏ - 1748', '- Hiệu trưởng trường cao đẳng - 1748', '- Trưởng khoa (đại học) - 1728', '- Trưởng khoa (đại học) - 173', '- Trưởng khoa giáo dục cao học - 1728', '- Trưởng khoa giáo dục cao học - 173', '- Giáo viên trung cấp - 2320']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 821) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2320', 'Giáo viên trung cấp dạy hoặc hướng dẫn các môn học nghề nghiệp trong các cơ sở hoạt động giáo dục nghề nghiệp. Họ chuẩn bị cho học viên việc làm trong các nghề cụ thể hoặc các lĩnh vực nghề nghiệp mà thông thường không yêu cầu giáo dục đại học hoặc cao hơn.', array['- Xây dựng chương trình giảng dạy; lập kế hoạch nội dung khóa học và phương pháp giảng dạy;', '- Trình bày các bài giảng và tiến hành thảo luận để tăng cường kiến ​​thức và năng lực của học viên;', '- Giáo dục phẩm chất đạo đức nghề nghiệp và tác phong công nghiệp cho học viên thông qua quá trình giảng dạy;', '- Đánh giá kết quả học tập, kết quả thi tốt nghiệp của học viên;', '- Hoàn thiện các biểu mẫu, sổ sách quản lý lớp học được bố trí, phân công giảng dạy;', '- Hướng dẫn thực tập, thực tập kết hợp với lao động sản xuất; luyện thi cho học viên tham gia kỳ thi tay nghề các cấp; hướng dẫn học viên tham gia nghiên cứu khoa học;', '- Biên soạn giáo trình, tài liệu giảng dạy; góp ý kiến xây dựng chương trình, nội dung mô-đun, môn học được phân công giảng dạy;', '- Tham gia bồi dưỡng cho giáo viên theo yêu cầu phát triển chuyên môn, nghiệp vụ của bộ môn, khoa, cơ sở giáo dục nghề nghiệp;', '- Ứng dụng các tiến bộ khoa học kỹ thuật hoặc sáng kiến, cải tiến kỹ thuật vào giảng dạy và thực tiễn nghề nghiệp;', '- Tham gia thiết kế, xây dựng phòng học chuyên môn; thiết kế, cải tiến, tự làm đồ dùng, trang thiết bị giáo dục nghề nghiệp;', '- Tham gia sinh hoạt chuyên môn, nghiệp vụ.']::text[], array['- Giáo viên công nghệ ô tô', '- Giáo viên dạy nghề']::text[], array['- Hiệu trưởng trường đại học lớn - 1710', '- Hiệu trưởng trường đại học nhỏ - 1748', '- Hiệu trưởng trường cao đẳng - 1748', '- Giáo viên trung học - 233', '- Giáo viên dạy nghề lái xe tại các trung tâm sát hạch - 3641', 'Ghi chú:', 'Những người dạy các môn học dự định chuẩn bị cho sinh viên đi làm trong một nhóm nghề nghiệp cụ thể nên được phân loại trong nhóm 232. Giáo viên trung cấp, cho dù họ làm việc trong một trường trung học phổ thông hoặc trong một trường dạy nghề hoặc kỹ thuật. Những người dạy ở cấp giáo dục trung học, các môn như toán học không nhằm mục đích chuẩn bị cho học sinh đi làm trong một ngành nghề cụ thể, nên được phân loại trong nhóm 233. Giáo viên trung học, ngay cả khi họ được tuyển dụng trong một nghề hoặc kỹ thuật trường đại học.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 843) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2331', 'Giáo viên trung học phổ thông dạy một loạt các môn học ở cấp giáo dục trung học phổ thông.', array['- Tham gia biên tập, biên soạn, phát triển chương trình, tài liệu bồi dưỡng giáo viên, học sinh trung học phổ thông;', '- Tham gia hướng dẫn, đánh giá, xét duyệt sáng kiến kinh nghiệm, đề tài nghiên cứu khoa học sư phạm ứng dụng của đồng nghiệp;', '- Hướng dẫn, đánh giá đề tài nghiên cứu khoa học kỹ thuật của học sinh trung học phổ thông từ cấp tỉnh trở lên;', '- Chủ trì các nội dung bồi dưỡng, sinh hoạt chuyên đề của chương trình hoặc tham gia các đề tài, nghiên cứu khoa học, sáng kiến kinh nghiệm;', '- Tham gia công tác kiểm tra chuyên môn, nghiệp vụ giáo viên trung học phổ thông;', '- Tham gia ban giám khảo hội thi giáo viên trung học phổ thông dạy giỏi hoặc giáo viên trung học phổ thông chủ nhiệm giỏi;', '- Tham gia bồi dưỡng, ra đề, chấm thi học sinh giỏi trung học phổ thông;', '- Tham gia tổ chức, đánh giá các hội thi của học sinh trung học phổ thông;', '- Làm báo cáo viên hoặc dạy minh họa ở các lớp bồi dưỡng giáo viên trung học phổ thông hoặc dạy thử nghiệm các mô hình, phương pháp mới;', '- Dạy học và giáo dục học sinh theo chương trình, kế hoạch giáo dục trung học phổ thông;', '- Tham gia phát hiện, bồi dưỡng học sinh năng khiếu, học sinh giỏi, phụ đạo học sinh yếu kém cấp trung học phổ thông;', '- Vận dụng các sáng kiến kinh nghiệm, kết quả nghiên cứu khoa học sư phạm ứng dụng vào thực tế giảng dạy, giáo dục học sinh và làm đồ dùng, thiết bị dạy học cấp trung học phổ thông;', '- Tham gia tư vấn tâm lý, hướng nghiệp, dạy nghề cho học sinh và cha mẹ học sinh trung học phổ thông;', '- Phối hợp với các giáo viên khác, các đoàn thể, gia đình và các tổ chức xã hội liên quan để tổ chức, hướng dẫn các hoạt động giáo dục học sinh trung học phổ thông;', '- Thực hiện các nhiệm vụ khác được giao.']::text[], array['- Giáo viên chủ nhiệm', '- Giáo viên bộ môn']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 894) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2332', 'Giáo viên trung học cơ sở dạy một loạt các môn học ở cấp giáo dục trung học cơ sở.', array['- Tham gia biên tập, biên soạn, phát triển chương trình, tài liệu bồi dưỡng giáo viên, học sinh trung học cơ sở;', '- Chủ trì các nội dung bồi dưỡng, sinh hoạt chuyên đề của nhà trường, tổ chuyên môn hoặc tham gia các đề tài nghiên cứu khoa học, sáng kiến kinh nghiệm;', '- Tham gia hướng dẫn, đánh giá, xét duyệt sáng kiến kinh nghiệm, đề tài nghiên cứu khoa học sư phạm ứng dụng của đồng nghiệp;', '- Tham gia công tác kiểm tra chuyên môn, nghiệp vụ cho giáo viên;', '- Tham gia tổ chức, đánh giá các hội thi của học sinh;', '- Làm báo cáo viên hoặc dạy minh họa ở các lớp bồi dưỡng giáo viên trung học cơ sở hoặc dạy thử nghiệm các mô hình, phương pháp mới;', '- Hướng dẫn sinh viên thực tập khi được phân công;', '- Tham gia ban giám khảo hội thi giáo viên dạy giỏi, giáo viên chủ nhiệm giỏi, tổng phụ trách đội giỏi cấp trường trở lên.']::text[], array['- Giáo viên chủ nhiệm', '- Giáo viên bộ môn']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 915) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2341', 'Giáo viên tiểu học dạy một loạt các môn học ở cấp giáo dục tiểu học.', array['- Tham gia biên tập, biên soạn, phát triển chương trình, tài liệu bồi dưỡng giáo viên, học sinh tiểu học;', '- Chủ trì các hoạt động bồi dưỡng và sinh hoạt chuyên đề của nhà trường hoặc tham gia đánh giá, xét duyệt sáng kiến kinh nghiệm, đề tài nghiên cứu khoa học sư phạm ứng dụng của đồng nghiệp từ cấp huyện trở lên;', '- Tham gia công tác kiểm tra chuyên môn, nghiệp vụ của giáo viên tiểu học từ cấp huyện trở lên;', '- Tham gia ban giám khảo hội thi giáo viên dạy giỏi hoặc giáo viên chủ nhiệm hoặc tổng phụ trách đội giỏi cấp huyện trở lên;', '- Tham gia tổ chức, đánh giá các hội thi của học sinh tiểu học từ cấp huyện trở lên.']::text[], array['- Giáo viên tiểu học', '- Giáo viên chủ nhiệm']::text[], array['- Hiệu trưởng nhà trường - 1748', '- Thanh tra trường học - 2391']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 932) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2342', 'Giáo viên mầm non thúc đẩy sự phát triển về giao tiếp xã hội, thể chất và trí tuệ của trẻ em dưới độ tuổi tiểu học thông qua việc cung cấp các hoạt động giáo dục và vui chơi.', array['- Tham gia biên tập hoặc biên soạn nội dung tài liệu bồi dưỡng giáo viên mầm non cấp huyện trở lên;', '- Tham gia bồi dưỡng chuyên môn cho giáo viên cấp trường trở lên;', '- Tham gia ban giám khảo các hội thi, đánh giá sáng kiến kinh nghiệm của cấp học mầm non cấp huyện trở lên;', '- Tham gia đoàn đánh giá ngoài, kiểm tra chuyên môn, nghiệp vụ sư phạm từ cấp huyện trở lên.']::text[], array['- Giáo viên mầm non', '- Giáo viên tiền tiểu học']::text[], array['- Giám đốc trung tâm chăm sóc trẻ em - 1748', '- Nhân viên chăm sóc trẻ em - 5311']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 946) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2391', 'Chuyên gia về phương pháp giáo dục tiến hành nghiên cứu và phát triển hoặc tư vấn về phương pháp giảng dạy, các khóa học và trợ giúp. Họ xem xét và kiểm tra giáo viên làm việc, hoạt động của các tổ chức giáo dục, kết quả đạt được và đề nghị thay đổi và cải tiến.', array['- Nghiên cứu các phát triển hiện tại trong chương trình giảng dạy, phương pháp giảng dạy và thực tiễn giáo dục khác và tư vấn về những thay đổi cần thiết và cải tiến có thể;', '- Đánh giá và tư vấn về nội dung các khóa học và phương pháp kiểm tra;', '- Nghiên cứu về nghe nhìn và các phương tiện dạy học khác, tư vấn, lập kế hoạch và tổ chức giới thiệu trong các cơ sở giáo dục;', '- Ghi lại các môn học và các khóa học được phát triển và đánh giá các khóa học mới;', '- Cung cấp dịch vụ phát triển, đào tạo và tư vấn chuyên nghiệp liên tục cho giáo viên;', '- Tổ chức và thực hiện các hội thảo và hội nghị để đào tạo giáo viên về các chương trình và phương pháp mới;', '- Phát triển cấu trúc, nội dung và mục tiêu của các khóa học và chương trình giáo dục mới;', '- Thăm trường định kỳ và trao đổi với nhân viên hành chính và giảng dạy về các câu hỏi liên quan đến chương trình giảng dạy, phương pháp giảng dạy, thiết bị và các vấn đề khác;', '- Tham quan các lớp học để quan sát các kỹ thuật giảng dạy và đánh giá kết quả học tập và kết quả giảng dạy của giáo viên;', '- Chuẩn bị báo cáo và đưa ra khuyến nghị cho các cơ quan giáo dục liên quan đến những thay đổi và cải tiến có thể có trong chương trình giảng dạy, phương pháp giảng dạy và các vấn đề khác.']::text[], array['- Điều phối viên chương trình giảng dạy', '- Nhà phát triển chương trình giảng dạy', '- Chuyên gia phương pháp giáo dục', '- Thanh tra trường học', '- Chuyên gia trợ giảng']::text[], array['- Cố vấn trường học - 2399', '- Nhà tư vấn sinh viên - 2399', '- Nhà tâm lý học giáo dục - 2634']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 962) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2392', 'Giáo viên theo các nhu cầu đặc biệt dạy cho trẻ em khuyết tật về thể chất hoặc tinh thần, người trưởng thành trẻ tuổi hoặc những người có khó khăn trong học tập hoặc các nhu cầu đặc biệt khác. Họ thúc đẩy sự phát triển xã hội, tình cảm, trí tuệ và thể chất của học sinh.', array['- Đánh giá khả năng và giới hạn của học sinh về các khiếm khuyết về trí tuệ, thể chất, xã hội và cảm xúc hoặc các tình huống đặc biệt khác;', '- Thiết kế hoặc sửa đổi chương trình giảng dạy, chuẩn bị và cung cấp các chương trình, bài học và hoạt động phù hợp với khả năng và nhu cầu của học sinh;', '- Hướng dẫn trên cơ sở cá nhân hoặc nhóm sử dụng các kỹ thuật hoặc trợ giúp đặc biệt phù hợp với nhu cầu của học sinh;', '- Sử dụng các chiến lược và kỹ thuật giáo dục đặc biệt trong quá trình giảng dạy để cải thiện sự phát triển các kỹ năng cảm giác và nhận thức, vận động, ngôn ngữ, nhận thức và trí nhớ;', '- Thiết lập và thực thi các quy tắc cho hành vi và chính sách, thủ tục để duy trì trật tự giữa các học sinh;', '- Giảng dạy các môn học thuật, các kỹ năng thực tế và tự lực cho học sinh khiếm thính, thị giác và các khiếm khuyết khác;', '- Kích thích và phát triển học sinh tự tin, sở thích, khả năng, kỹ năng thủ công và phối hợp;', '- Trao đổi với các nhân viên khác để lập kế hoạch và sắp xếp các bài học cho các học sinh có nhu cầu đặc biệt;', '- Chuẩn bị, duy trì dữ liệu của học sinh và các hồ sơ khác và gửi báo cáo;', '- Quản lý các hình thức đánh giá và đánh giá tiến bộ khác nhau của mỗi học sinh;', '- Trao đổi với học sinh, phụ huynh, giáo viên chủ nhiệm và các chuyên gia có liên quan khác các vấn đề của học sinh. Chăm sóc để phát triển các kế hoạch giáo dục cá nhân được thiết kế để thúc đẩy học sinh phát triển.']::text[], array['- Giáo viên giáo dục đặc biệt cho người khuyết tật', '- Giáo viên hỗ trợ học tập', '- Giáo viên khắc phục khiếm khuyết', '- Giáo viên dạy trẻ có năng khiếu', '- Giáo viên dạy trẻ khiếm thính', '- Giáo viên dạy người khiếm thị']::text[], array['- Giáo viên trung cấp - 2320', '- Giáo viên trung học - 233', '- Giáo viên tiểu học - 2341']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 985) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2393', 'Giáo viên ngôn ngữ khác dạy ngôn ngữ không phải tiếng mẹ đẻ cho người lớn và trẻ em đang học ngôn ngữ vì lý do di cư, để đáp ứng các yêu cầu hoặc cơ hội việc làm, để tạo điều kiện tham gia vào các chương trình giáo dục bằng tiếng nước ngoài hoặc để làm giàu cá nhân. Họ làm việc bên ngoài các hệ thống giáo dục tiểu học, trung học và đại học chính thống, hoặc hỗ trợ học sinh và giáo viên trong các hệ thống đó.', array['- Đánh giá mức độ khả năng, mức độ khó khăn về ngôn ngữ của học sinh và thiết lập nhu cầu học tập, mục tiêu học tập của học sinh;', '- Lập kế hoạch, chuẩn bị và cung cấp các bài học và hội thảo cho các nhóm và cá nhân với nội dung và tốc độ tiến triển phù hợp với khả năng và nhu cầu của học sinh;', '- Thiết kế tài liệu giảng dạy và điều chỉnh các tài liệu hiện có;', '- Đánh giá sự tiến bộ của học sinh;', '- Hỗ trợ học sinh trong môi trường lớp học nơi các môn học được dạy bằng ngôn ngữ khác với ngôn ngữ bản địa của học sinh;', '- Cung cấp hỗ trợ cho các giáo viên khác bằng cách thiết kế các chương trình giảng dạy đặc biệt cho học sinh vẫn học ngôn ngữ giảng dạy chính;', '- Phân công công việc, chuẩn bị và chấm điểm bài kiểm tra;', '- Đánh giá, ghi chép và báo cáo về sự tiến bộ của học sinh.']::text[], array['- Giáo viên ngôn ngữ chuyên sâu', '- Giáo viên giáo dục di cư', '- Giáo viên ngôn ngữ thực hành', '- Giáo viên ngôn ngữ thứ hai']::text[], array['- Giảng viên đại học - 2311', '- Giáo viên trung cấp - 2320', '- Giáo viên trung học - 233', '- Giáo viên tiểu học - 2341']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1010) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2394', 'Giáo viên âm nhạc khác dạy học sinh thực hành, lý thuyết và biểu diễn âm nhạc bên ngoài các hệ thống giáo dục tiểu học, trung học cơ sở, cao đẳng, đại học nhưng có thể cung cấp cho nhóm nhỏ tư nhân như một hoạt động ngoại khóa kết hợp với các tổ chức giáo dục chính thống.', array['- Đánh giá khả năng, xác định nhu cầu và mục tiêu học tập của học sinh;', '- Lập kế hoạch, chuẩn bị và cung cấp các chương trình học tập, bài học và hội thảo cho từng học sinh và nhóm;', '- Chuẩn bị và trình bày tài liệu về lý thuyết và giải thích âm nhạc;', '- Hướng dẫn và thể hiện các khía cạnh thực tế của ca hát hoặc chơi một nhạc cụ cụ thể;', '- Dạy học sinh đọc và viết ký hiệu âm nhạc;', '- Giao các bài tập và giảng dạy các bản nhạc liên quan theo khả năng, sở thích và tài năng của học sinh;', '- Đánh giá học sinh và đưa ra lời khuyên, phê bình và khuyến khích;', '- Sửa đổi chương trình giảng dạy, nội dung khóa học, tài liệu khóa học và phương pháp giảng dạy;', '- Chuẩn bị cho học sinh thi, biểu diễn và đánh giá;', '- Sắp xếp các chuyến thăm và các chuyến lưu diễn đến các buổi biểu diễn âm nhạc;', '- Tổ chức và hỗ trợ thử giọng hoặc biểu diễn cho học sinh.']::text[], array['- Giáo viên ghi-ta (tư nhân)', '- Giáo viên piano (tư nhân)', '- Giáo viên thanh nhạc (tư nhân)', '- Giáo viên vĩ cầm (tư nhân)']::text[], array['- Giảng viên đại học - 2311', '- Giáo viên trung cấp - 2320', '- Giáo viên trung học - 233', '- Giáo viên tiểu học - 2341', 'Ghi chú:', 'Giáo viên trung học cơ sở và tiểu học chính quy dạy nhạc được phân loại trong nhóm 233. Giáo viên trung học và 2341. Giáo viên tiểu học tương ứng.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1031) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2395', 'Giáo viên nghệ thuật khác dạy học sinh thực hành, lý thuyết và biểu diễn múa, kịch, hình ảnh và nghệ thuật khác (trừ âm nhạc) ngoài các hệ thống giáo dục tiểu học, trung học và đại học chính thống nhưng có thể cung cấp cho nhóm tư nhân nhỏ như một hoạt động ngoại khóa trong hiệp hội với các tổ chức giáo dục chính thống.', array['- Đánh giá mức độ khả năng và xác định nhu cầu học tập của học sinh;', '- Lập kế hoạch, chuẩn bị và cung cấp các chương trình học tập, bài học và hội thảo cho từng học sinh và nhóm;', '- Chuẩn bị và trình bày tài liệu về lý thuyết của lĩnh vực được nghiên cứu;', '- Hướng dẫn và thể hiện các khía cạnh thực tế của kịch, khiêu vũ, hình ảnh hoặc nghệ thuật khác;', '- Giao các bài tập và công việc phù hợp với khả năng, sở thích và tài năng của học sinh;', '- Đánh giá học sinh và đưa ra lời khuyên, phê bình và khuyến khích;', '- Sửa đổi chương trình giảng dạy, nội dung khóa học, tài liệu khóa học và phương pháp giảng dạy;', '- Chuẩn bị cho học sinh kiểm tra, thực hiện và đánh giá;', '- Sắp xếp các chuyến thăm và tham quan triển lãm và biểu diễn;', '- Tổ chức và hỗ trợ biểu diễn hoặc triển lãm cho học sinh.']::text[], array['- Giáo viên dạy nhảy (tư nhân)', '- Giáo viên kịch (tư nhân)', '- Giáo viên vẽ tranh (tư nhân)', '- Giáo viên điêu khắc (tư nhân)']::text[], array['- Giảng viên đại học - 2311', '- Giáo viên trung cấp - 2320', '- Giáo viên trung học - 233', '- Giáo viên tiểu học - 2341', '- Giáo viên dạy nhạc riêng - 2394', 'Ghi chú:', 'Giáo viên trung học cơ sở và tiểu học thường xuyên dạy các môn nghệ thuật được phân loại trong nhóm 233. Giáo viên trung học và 2341. Giáo viên tiểu học.']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1057) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2396', 'Giáo viên công nghệ thông tin phát triển, lên lịch và thực hiện các chương trình và khóa đào tạo cho người dùng máy tính và công nghệ thông tin khác ngoài các hệ thống giáo dục tiểu học, trung học và đại học chính thống.', array['- Xác định nhu cầu và yêu cầu đào tạo công nghệ thông tin của người dùng và tổ chức, cá nhân;', '- Chuẩn bị và phát triển tài liệu đào tạo hướng dẫn và các công cụ hỗ trợ như sổ tay, giáo cụ trực quan, hướng dẫn trực tuyến, mô hình trình diễn và tài liệu tham khảo đào tạo hỗ trợ;', '- Thiết kế, điều phối, lên lịch và thực hiện các chương trình đào tạo và phát triển có thể được cung cấp dưới hình thức hướng dẫn cá nhân và nhóm, tạo điều kiện cho các cuộc họp hội thảo, trình diễn và hội nghị;', '- Giám sát và thực hiện đánh giá liên tục về chất lượng và hiệu quả đào tạo, xem xét và sửa đổi các mục tiêu, phương pháp và các khóa học đào tạo;', '- Thu thập, điều tra và nghiên cứu các tài liệu cơ bản để có được sự hiểu biết đầy đủ về các vấn đề và hệ thống;', '- Tiếp tục phát triển phiên bản sản phẩm mới, tiến bộ về xu hướng công nghệ thông tin và phần mềm, viết các sản phẩm và tài liệu của người dùng cuối như đào tạo người dùng, hướng dẫn sử dụng, trợ giúp trực tuyến và hướng dẫn vận hành và bảo trì.']::text[], array['- Giảng viên máy tính', '- Giảng viên phần mềm']::text[], array['- Giảng viên đại học - 2311', '- Giáo viên trung cấp - 2320', '- Giáo viên trung học - 233', '- Giáo viên tiểu học - 2341', '- Nhà chuyên môn về phát triển nhân sự - 2424']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1083) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2399', 'Nhà chuyên môn giảng dạy khác chưa được phân vào đâu bao gồm những người cung cấp học phí tư nhân trong các môn học ngoài ngoại ngữ và nghệ thuật và những người cung cấp tư vấn giáo dục cho học sinh.', array['- Đánh giá mức độ khả năng và xác định nhu cầu học tập của học sinh;', '- Lập kế hoạch, chuẩn bị và cung cấp các chương trình học tập, bài học và hội thảo cho từng học sinh và nhóm;', '- Chuẩn bị và trình bày tài liệu về lý thuyết của lĩnh vực được nghiên cứu;', '- Hướng dẫn và thể hiện các khía cạnh thực tế của lĩnh vực chủ đề đang nghiên cứu;', '- Giao các bài tập và công việc phù hợp với mức độ khả năng, sở thích và năng khiếu của học sinh;', '- Đánh giá học sinh và đưa ra lời khuyên, phê bình và khuyến khích;', '- Sửa đổi chương trình giảng dạy, nội dung khóa học, tài liệu khóa học và phương pháp giảng dạy;', '- Chuẩn bị cho học sinh thi và đánh giá;', '- Tư vấn cho học sinh về các vấn đề giáo dục như lựa chọn khóa học và chương trình, lên lịch học, điều chỉnh trường học, trốn học, thói quen học tập và lập kế hoạch nghề nghiệp;', '- Tư vấn cho học sinh để giúp họ hiểu và khắc phục các vấn đề cá nhân, xã hội hoặc hành vi ảnh hưởng đến giáo dục của họ;', '- Chuẩn bị cho học sinh những trải nghiệm giáo dục sau này bằng cách khuyến khích họ khám phá các cơ hội học tập và kiên trì với các nhiệm vụ đầy thách thức.']::text[], array['- Giáo viên toán học (tư nhân)', '- Tư vấn viên của trường', '- Tư vấn sinh viên']::text[], array['- Giảng viên đại học - 2311', '- Giáo viên trung cấp - 2320', '- Giáo viên trung học - 233', '- Giáo viên tiểu học - 2341', '- Giáo viên ngôn ngữ chuyên sâu - 2393', '- Giáo viên giáo dục di cư - 2393', '- Giáo viên âm nhạc (tư nhân) - 2394', '- Giáo viên dạy nhảy (tư nhân) - 2395', '- Giáo viên dạy kịch (tư nhân) - 2395', '- Giáo viên vẽ tranh (tư nhân) - 2395', '- Giáo viên điêu khắc (tư nhân) - 2395', '- Nhà tâm lý học giáo dục - 2634', '- Nhà chuyên môn về tư vấn gia đình - 2635', '- Nhà chuyên môn về xã hội - 2635']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1101) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2411', 'Kế toán và các nhà chuyên môn có liên quan lên kế hoạch, tổ chức và điều hành hệ thống kế toán cho các cá nhân và cơ sở. Một số ngành nghề được phân loại ở đây kiểm tra và phân tích hồ sơ tài chính kế toán của các cá nhân và cơ sở để đảm bảo tính chính xác và tuân thủ các chuẩn mực và quy trình kế toán được thiết lập.', array['- Tư vấn, lập kế hoạch, dự toán ngân sách, kiểm soát tài khoản, các chính sách và hệ thống kế toán khác;', '- Chuẩn bị và xác nhận báo cáo tài chính để trình bày cho ban quản lý, cổ đông và theo luật định hoặc các cơ quan khác;', '- Chuẩn bị khai thuế, tư vấn về các vấn đề thuế và tranh chấp khiếu nại trước cơ quan thuế;', '- Chuẩn bị hoặc báo cáo về dự báo lợi nhuận và ngân sách;', '- Tiến hành điều tra tài chính trong các vấn đề như nghi ngờ gian lận, mất khả năng thanh toán và phá sản;', '- Kiểm toán tài khoản và hồ sơ sổ sách kế toán;', '- Tiến hành điều tra và tư vấn quản lý về các khía cạnh tài chính của năng suất, cổ phần, bán hàng, sản phẩm mới, v.v...;', '- Đưa ra và kiểm soát các hệ thống để xác định đơn giá sản phẩm và dịch vụ.']::text[], array['- Kế toán trưởng', '- Trưởng/phó phòng kế toán', '- Kế toán tổng hợp', '- Kế toán viên', '- Kiểm toán viên', '- Kế toán viên được chứng nhận', '- Kế toán viên giám định', '- Kiểm soát tài chính', '- Nhà chuyên môn ủy thác giải quyết mất khả năng thanh toán', '- Kế toán quản trị', '- Kế toán thuế']::text[], array['- Quản lý tài chính - 1731', '- Trợ lý kế toán - 3313', '- Kế toán sổ sách - 3313']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1140) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2412', 'Nhà tư vấn tài chính và đầu tư phát triển các kế hoạch tài chính cho các cá nhân và tổ chức, đồng thời đầu tư và quản lý quỹ.', array['- Xây dựng và duy trì một cơ sở khách hàng;', '- Phỏng vấn khách hàng để xác định tình trạng và mục tiêu tài chính, chấp nhận rủi ro và các thông tin khác cần thiết để xây dựng kế hoạch tài chính và chiến lược đầu tư;', '- Thiết lập các mục tiêu tài chính, phát triển và thực hiện các chiến lược để đạt được chúng;', '- Sắp xếp để mua, bán cổ phiếu và trái phiếu cho khách hàng;', '- Giám sát hiệu quả đầu tư, xem xét và sửa đổi kế hoạch đầu tư dựa trên nhu cầu và thay đổi của thị trường;', '- Đề xuất và sắp xếp bảo hiểm cho khách hàng.']::text[], array['- Nhà lập kế hoạch bất động sản', '- Nhà lập kế hoạch tài chính', '- Nhà tư vấn đầu tư']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1167) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2413', 'Nhà phân tích tài chính và các nhà chuyên môn có liên quan tiến hành phân tích định lượng thông tin ảnh hưởng đến các chương trình đầu tư của các tổ chức công cộng hoặc tư nhân.', array['- Phân tích thông tin tài chính để đưa ra dự báo về các điều kiện kinh doanh, công nghiệp và kinh tế để sử dụng trong việc đưa ra quyết định đầu tư;', '- Duy trì kiến ​​thức và bám sát các phát triển trong các lĩnh vực công nghệ công nghiệp, kinh doanh, tài chính và lý thuyết kinh tế;', '- Diễn giải dữ liệu ảnh hưởng đến các chương trình đầu tư như giá cả, sản lượng, sự ổn định, xu hướng tương lai trong rủi ro đầu tư và ảnh hưởng kinh tế;', '- Theo dõi sự phát triển kinh tế, công nghiệp và doanh nghiệp thông qua phân tích thông tin thu được từ các ấn phẩm tài chính và dịch vụ, công ty ngân hàng đầu tư, cơ quan chính phủ, ấn phẩm thương mại, nguồn công ty và phỏng vấn cá nhân;', '- Khuyến nghị đầu tư và thời gian đầu tư cho các công ty, nhân viên công ty đầu tư hoặc công chúng đầu tư;', '- Xác định giá mà chứng khoán nên được cung cấp và cung cấp cho công chúng;', '- Chuẩn bị kế hoạch hành động để đầu tư dựa trên các phân tích tài chính;', '- Đánh giá và so sánh chất lượng tương đối của các chứng khoán khác nhau trong một ngành nhất định;', '- Trình bày báo cáo bằng miệng và bằng văn bản về xu hướng kinh tế chung, các tập đoàn cá nhân và toàn bộ ngành công nghiệp.']::text[], array['- Nhà phân tích trái phiếu', '- Nhà phân tích đầu tư', '- Nhà tư vấn chứng khoán']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1180) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2421', 'Nhà phân tích tổ chức và quản lý hỗ trợ các tổ chức để đạt được hiệu quả cao hơn và giải quyết các vấn đề của tổ chức. Họ nghiên cứu cơ cấu tổ chức, phương pháp, hệ thống và thủ tục.', array['- Hỗ trợ và khuyến khích phát triển các mục tiêu, chiến lược và kế hoạch nhằm đạt được sự hài lòng của khách hàng và sử dụng hiệu quả các nguồn lực của các tổ chức;', '- Phân tích và đánh giá các hệ thống và cấu trúc hiện tại;', '- Thảo luận về các hệ thống hiện tại với nhân viên và hệ thống quan sát ở tất cả các cấp của tổ chức;', '- Hướng khách hàng tới tổ chức hiệu quả hơn và phát triển các giải pháp cho các vấn đề của tổ chức;', '- Thực hiện và xem xét các nghiên cứu công việc bằng cách phân tích các phương pháp và thủ tục hiện có và được đề xuất như thủ tục hành chính và văn thư;', '- Ghi lại và phân tích sơ đồ quy trình làm việc, hồ sơ, báo cáo, hướng dẫn sử dụng và mô tả công việc của các tổ chức;', '- Chuẩn bị và đưa ra các đề xuất để sửa đổi các phương pháp và quy trình, thay đổi luồng công việc, xác định lại chức năng công việc và giải quyết các vấn đề của tổ chức;', '- Hỗ trợ thực hiện các khuyến nghị đã được phê duyệt, ban hành các hướng dẫn sửa đổi và hướng dẫn thủ tục, soạn thảo các tài liệu khác;', '- Xem xét các quy trình vận hành và tư vấn các thủ tục và tiêu chuẩn.']::text[], array['- Nhà tư vấn kinh doanh', '- Nhà tư vấn quản lý', '- Nhà phân tích phương pháp và tổ chức']::text[], array['- Nhà phân tích kinh doanh công nghệ thông tin - 2511']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1199) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2422', 'Nhà chuyên môn về quản trị chính sách phát triển và phân tích các chính sách hướng dẫn thiết kế, thực hiện và sửa đổi các hoạt động và chương trình của chính phủ và thương mại.', array['- Liên lạc và tư vấn với các quản trị viên chương trình và các bên quan tâm khác để xác định nhu cầu chính sách;', '- Xem xét các chính sách và pháp luật hiện hành để xác định sự bất thường và các điều khoản lỗi thời;', '- Nghiên cứu các xu hướng xã hội, kinh tế, công nghiệp và kỳ vọng của khách hàng về các chương trình và dịch vụ được cung cấp;', '- Xây dựng, phân tích các lựa chọn chính sách, chuẩn bị các tài liệu tóm tắt, đề xuất thay đổi chính sách và tư vấn về các lựa chọn ưu tiên;', '- Đánh giá tác động, ý nghĩa tài chính, tương tác với các chương trình khác và tính khả thi về chính trị, hành chính của các chính sách;', '- Tiến hành đánh giá mối đe dọa, rủi ro và phát triển các phản ứng;', '- Xem xét các hoạt động và chương trình để đảm bảo sự thống nhất với các chính sách của tổ chức.']::text[], array['- Nhà chuyên môn về tình báo', '- Nhà phân tích chính sách', '- Nhà cố vấn chính trị']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1217) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2423', 'Nhà chuyên môn về nhân sự và nghề nghiệp cung cấp các dịch vụ kinh doanh chuyên nghiệp liên quan đến các chính sách nhân sự như tuyển dụng hoặc phát triển nhân viên, phân tích nghề nghiệp và hướng dẫn nghề nghiệp.', array['- Tư vấn và thực hiện các chức năng nhân sự liên quan đến tuyển dụng người lao động, sắp xếp, đào tạo, thăng chức và các mối quan hệ về bồi thường và quản lý người lao động hoặc các lĩnh vực khác trong chính sách nhân sự;', '- Nghiên cứu và phân tích các công việc được thực hiện trong một cơ sở bằng nhiều cách khác nhau bao gồm các cuộc phỏng vấn với người lao động, giám sát viên và quản lý; viết các mô tả chi tiết về vị trí, công việc hoặc nghề nghiệp từ thông tin thu được;', '- Chuẩn bị thông tin nghề nghiệp hoặc làm việc trên các hệ thống phân loại nghề nghiệp;', '- Tư vấn và phân tích công việc và nghề nghiệp trong các lĩnh vực như quản trị nhân sự, nghiên cứu và lập kế hoạch lực lượng lao động, đào tạo hoặc thông tin nghề nghiệp và hướng nghiệp;', '- Nghiên cứu và tư vấn cho các cá nhân về cơ hội việc làm, lựa chọn nghề nghiệp và giáo dục hoặc đào tạo thêm có thể được mong muốn.']::text[], array['- Nhà tư vấn nghề nghiệp', '- Chuyên gia nhân sự', '- Nhà phân tích công việc', '- Chuyên gia giao dịch', '- Nhà phân tích nghề nghiệp', '- Nhà chuyên môn về tuyển dụng', '- Cố vấn về hướng dẫn nghề nghiệp']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1231) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2424', 'Nhà chuyên môn về đào tạo và phát triển nhân viên lập kế hoạch, xây dựng, thực hiện và đánh giá các chương trình đào tạo và phát triển để đảm bảo cán bộ quản lý và nhân viên có được các kỹ năng và phát triển các năng lực cần thiết của tổ chức để đáp ứng mục tiêu của tổ chức.', array['- Xác định nhu cầu và yêu cầu đào tạo của các cá nhân và tổ chức;', '- Thiết lập mục tiêu phát triển nguồn nhân lực và đánh giá kết quả học tập;', '- Chuẩn bị và phát triển tài liệu đào tạo hướng dẫn và các công cụ hỗ trợ như sổ tay, giáo cụ trực quan, hướng dẫn trực tuyến, mô hình trình diễn và tài liệu tham khảo hỗ trợ đào tạo;', '- Thiết kế, điều phối, lên lịch và thực hiện các chương trình đào tạo và phát triển có thể được cung cấp dưới hình thức hướng dẫn cá nhân và nhóm và tạo điều kiện cho các hội thảo, các cuộc họp và hội nghị;', '- Liên lạc với các nhà cung cấp đào tạo bên ngoài để sắp xếp việc cung cấp các chương trình đào tạo và phát triển cụ thể;', '- Thúc đẩy đào tạo và phát triển nội bộ và bên ngoài; đánh giá các hoạt động quảng cáo này;', '- Giám sát và thực hiện đánh giá thường xuyên về chất lượng và hiệu quả đào tạo bên trong và bên ngoài; xem xét và sửa đổi các mục tiêu, phương pháp và các khóa học đào tạo;', '- Thu thập, điều tra và nghiên cứu các tài liệu cơ bản để hiểu biết về các vấn đề và hệ thống khác nhau.']::text[], array['- Nhà chuyên môn về phát triển nhân sự', '- Nhà chuyên môn về đào tạo', '- Chuyên gia phát triển lực lượng lao động']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1247) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2431', 'Nhà chuyên môn về quảng cáo và tiếp thị phát triển và phối hợp các chiến lược và chiến dịch quảng cáo; xác định và phát triển thị trường, cơ hội thị trường cho hàng hóa, dịch vụ mới và hiện có.', array['- Lập kế hoạch, phát triển và tổ chức các chính sách và chiến dịch quảng cáo để hỗ trợ các mục tiêu bán hàng;', '- Tư vấn cho các nhà quản lý và khách hàng về các chiến lược và chiến dịch tiếp cận thị trường mục tiêu, tạo ra nhận thức của người tiêu dùng và thúc đẩy hiệu quả các thuộc tính của hàng hóa và dịch vụ;', '- Viết bản sao quảng cáo, kịch bản truyền thông và sắp xếp sản xuất phim, truyền hình và truyền thông;', '- Thu thập và phân tích dữ liệu liên quan đến mô hình và sở thích của người tiêu dùng;', '- Diễn giải và dự đoán xu hướng tiêu dùng hiện tại và tương lai;', '- Nghiên cứu nhu cầu tiềm năng và đặc điểm thị trường cho hàng hóa và dịch vụ mới;', '- Hỗ trợ tăng trưởng và phát triển kinh doanh thông qua việc chuẩn bị và thực hiện các mục tiêu, chính sách và chương trình tiếp thị;', '- Vận hành và thực hiện nghiên cứu thị trường để xác định cơ hội thị trường cho hàng hóa, dịch vụ mới và hiện có;', '- Tư vấn về tất cả các yếu tố tiếp thị như kết hợp sản phẩm, giá cả, quảng cáo và khuyến mại, kênh bán hàng và phân phối.']::text[], array['- Chuyên gia quảng cáo', '- Chuyên gia tiếp thị', '- Nhà phân tích nghiên cứu thị trường']::text[], '{}'::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Marketing thương mại.', '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1266) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2432', 'Nhà chuyên môn về quan hệ công chúng lập kế hoạch, phát triển, thực hiện và đánh giá các chiến lược thông tin và truyền thông tạo ra sự hiểu biết và cái nhìn thuận lợi về các doanh nghiệp và các tổ chức khác, hàng hóa và dịch vụ của họ và vai trò của họ trong cộng đồng.', array['- Lập kế hoạch và tổ chức các chiến dịch công khai và chiến lược truyền thông;', '- Tư vấn cho các giám đốc điều hành về ý nghĩa quan hệ công chúng, về chính sách, chương trình, thực tiễn của họ; chuẩn bị và kiểm soát vấn đề tin tức và thông cáo báo chí;', '- Thực hiện và ủy thác nghiên cứu dư luận, phân tích các phát hiện, lập kế hoạch quan hệ công chúng và các chiến dịch quảng bá;', '- Tổ chức các sự kiện đặc biệt, hội thảo, giải trí, thi đấu và các chức năng xã hội để thúc đẩy thiện chí và công khai thuận lợi;', '- Đại diện cho tổ chức và sắp xếp các cuộc phỏng vấn với các phương tiện truyền thông công cộng;', '- Tham dự các chức năng kinh doanh, xã hội và các chức năng khác để thúc đẩy tổ chức;', '- Vận hành, lấy ảnh và tài liệu minh họa khác;', '- Lựa chọn, thẩm định và sửa đổi tài liệu được gửi bởi các nhà văn, nhiếp ảnh gia, họa sĩ minh họa và những người khác để tạo ra sự công khai thuận lợi.']::text[], array['- Nhà chuyên môn về đại diện công chúng', '- Nhà chuyên môn về quan hệ công chúng', '- Nhà chuyên môn về sáng tạo nội dung quan hệ công chúng', '- Nhà chuyên môn về liên hệ báo chí']::text[], '{}'::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1283) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2433', 'Nhà chuyên môn về bán hàng hóa kỹ thuật và y tế (không bao gồm công nghệ thông tin và truyền thông) đại diện cho các công ty bán một loạt các hàng hóa và dịch vụ công nghiệp, y tế và dược phẩm cho các cơ sở công nghiệp, kinh doanh, chuyên nghiệp và các cơ sở khác.', array['- Tổng hợp danh sách các doanh nghiệp khách hàng tiềm năng bằng cách sử dụng các thư mục và các nguồn khác;', '- Tiếp thu và cập nhật kiến ​​thức của người sử dụng lao động và các đối thủ cạnh tranh hàng hóa, dịch vụ và các điều kiện thị trường;', '- Thăm các doanh nghiệp khách hàng thường xuyên và tiềm năng để thiết lập và hành động về các cơ hội bán hàng;', '- Đánh giá nhu cầu và nguồn lực của khách hàng và đề xuất hàng hóa hoặc dịch vụ phù hợp;', '- Cung cấp đầu vào cho thiết kế sản phẩm trong đó hàng hóa hoặc dịch vụ phải được điều chỉnh cho phù hợp với nhu cầu của khách hàng;', '- Phát triển các báo cáo và đề xuất như một phần của bài thuyết trình bán hàng để chứng minh lợi ích từ việc sử dụng hàng hóa hoặc dịch vụ;', '- Ước tính chi phí lắp đặt và bảo trì thiết bị hoặc dịch vụ;', '- Giám sát nhu cầu thay đổi của khách hàng, hoạt động của đối thủ cạnh tranh và báo cáo những phát triển này cho quản lý bán hàng;', '- Trích dẫn, đàm phán giá cả và các điều khoản tín dụng; chuẩn bị và điều hành các hợp đồng mua bán;', '- Sắp xếp giao hàng, lắp đặt thiết bị và cung cấp dịch vụ;', '- Báo cáo cho quản lý bán hàng về doanh số bán hàng và khả năng tiếp thị hàng hóa và dịch vụ;', '- Tư vấn với khách hàng sau khi bán hàng để đảm bảo giải quyết thỏa đáng mọi vấn đề và cung cấp hỗ trợ liên tục.']::text[], array['- Nhà chuyên môn đại diện bán hàng (sản phẩm công nghiệp)', '- Nhà chuyên môn đại diện bán hàng (sản phẩm y tế và dược phẩm)', '- Nhà chuyên môn đại diện bán hàng kỹ thuật']::text[], array['- Nhà chuyên môn đại diện bán hàng về công nghệ thông tin và truyền thông - 2434', '- Nhà chuyên môn đại diện bán hàng (máy tính) - 2434', '- Nhân viên đại diện bán hàng hóa thương mại - 3322']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1299) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2434', 'Nhà chuyên môn về bán hàng hóa trong lĩnh vực công nghệ thông tin và truyền thông bán ở cấp độ bán buôn một loạt phần cứng máy tính, phần mềm, các hàng hóa, dịch vụ công nghệ thông tin và truyền thông khác bao gồm cài đặt và cung cấp thông tin chuyên ngành theo yêu cầu.', array['- Mời chào đặt hàng và bán hàng hóa cho các cơ sở bán lẻ, công nghiệp, bán buôn và các cơ sở khác;', '- Bán thiết bị kỹ thuật, vật tư và dịch vụ liên quan cho các cơ sở hoặc cá nhân kinh doanh;', '- Thảo luận về nhu cầu của khách hàng mới và hiện tại và cung cấp thông tin chuyên biệt về cách thức thiết bị, vật tư và dịch vụ cụ thể đáp ứng các nhu cầu đó;', '- Trích dẫn, đàm phán giá cả và các điều khoản tín dụng; hoàn thành hợp đồng và ghi lại đơn đặt hàng;', '- Cập nhật hồ sơ khách hàng và chuẩn bị báo cáo bán hàng;', '- Sắp xếp giao hàng, lắp đặt thiết bị và cung cấp dịch vụ;', '- Báo cáo phản hồi và yêu cầu của khách hàng với nhà sản xuất.']::text[], array['- Đại diện bán hàng (máy tính)', '- Đại diện bán hàng (công nghệ truyền thông)']::text[], array['- Trợ lý bán hàng tại cửa hàng - 5223.', '(Xem tiếp Công báo số 1145 + 1146)', 'Số 1145 + 1146 Ngày 12 tháng 12 năm 2020', 'MỤC LỤC', 'VĂN BẢN QUY PHẠM PHÁP LUẬT', 'THỦ TƯỚNG CHÍNH PHỦ', 'Quyết định số 34/2020/QĐ-TTg ngày 26 tháng 11 năm 2020', 'ban hành Danh mục nghề nghiệp Việt Nam', '(Tiếp theo Công báo số 1143 + 1144)', 'Phụ lục II', 'NỘI DUNG DANH MỤC NGHỀ NGHIỆP VIỆT NAM', '(Ban hành kèm theo Quyết định số 34/2020/QĐ-TTg', 'ngày 26 tháng 11 năm 2020 của Thủ tướng Chính phủ)']::text[], null, '2020_1143 + 1144_34-2020-QĐ-TTg.doc', 1322) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2441', 'Nhà chuyên môn về hải quan của Chính phủ xây dựng và chỉ đạo thực hiện chiến lược, kế hoạch phát triển Hải quan Việt Nam; ban hành và tổ chức thực hiện văn bản quy phạm pháp luật về hải quan; thực hiện kiểm tra, giám sát hàng hóa, phương tiện vận tải; phòng, chống buôn lậu, vận chuyển trái phép hàng hóa qua biên giới; tổ chức thực hiện pháp luật về thuế đối với hàng hóa xuất khẩu, nhập khẩu; thống kê hàng hóa xuất khẩu, nhập khẩu; kiến nghị chủ trương, biện pháp quản lý nhà nước về hải quan đối với hoạt động xuất khẩu, nhập khẩu, xuất cảnh, nhập cảnh, quá cảnh và chính sách thuế đối với hàng hóa xuất khẩu, nhập khẩu.', array['- Xây dựng, ban hành chiến lược, kế hoạch phát triển hải quan và các văn bản quy phạm pháp luật về hải quan;', '- Hướng dẫn, thực hiện và tuyên truyền pháp luật về hải quan;', '- Nghiên cứu, ứng dụng khoa học và công nghệ, phương pháp quản lý hải quan hiện đại;', '- Thanh tra, kiểm tra, giải quyết khiếu nại, tố cáo và xử lý vi phạm pháp luật về hải quan;', '- Thực hiện kiểm tra, giám sát hàng hóa, phương tiện vận tải; phòng, chống buôn lậu, vận chuyển trái phép hàng hóa qua biên giới; tổ chức thực hiện pháp luật về thuế đối với hàng hóa xuất khẩu, nhập khẩu; thống kê hàng hóa xuất khẩu, nhập khẩu;', '- Kiến nghị chủ trương, biện pháp quản lý nhà nước về hải quan đối với hoạt động xuất khẩu, nhập khẩu, xuất cảnh, nhập cảnh, quá cảnh và chính sách thuế đối với hàng hóa xuất khẩu, nhập khẩu.']::text[], array['- Thanh tra biên giới', '- Thanh tra hải quan', '- Nhà chuyên môn về hải quan']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 37) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2442', 'Nhà chuyên môn về thuế của Chính phủ xây dựng và ban hành các văn bản quy phạm pháp luật liên quan đến thuế; tuyên truyền, phổ biến, hướng dẫn pháp luật về thuế; tổ chức thực hiện quản lý thu thuế và các khoản thu khác thuộc ngân sách nhà nước.', array['- Xây dựng và ban hành theo thẩm quyền hoặc trình cấp có thẩm quyền ban hành văn bản quy phạm pháp luật về quản lý thuế;', '- Tổ chức thực hiện quản lý thu thuế và các khoản thu khác thuộc ngân sách nhà nước theo quy định của pháp luật;', '- Tuyên truyền, phổ biến, hướng dẫn pháp luật về thuế, các thủ tục về thuế tại trụ sở, trang thông tin điện tử của cơ quan quản lý thuế và trên các phương tiện thông tin đại chúng;', '- Hướng dẫn hồ sơ, thủ tục về miễn thuế, giảm thuế, xóa nợ tiền thuế, tiền chậm nộp, tiền phạt; miễn tiền chậm nộp, tiền phạt, không tính tiền chậm nộp; gia hạn nộp thuế; nộp dần tiền thuế nợ; khoanh tiền thuế nợ, không thu thuế; xử lý tiền thuế, tiền chậm nộp, tiền phạt nộp thừa; hoàn thuế theo quy định của pháp luật;', '- Lập và thực hiện dự toán thu ngân sách nhà nước;', '- Tổ chức kiểm tra, thanh tra việc thực hiện pháp luật về thuế và quy định khác của pháp luật có liên quan;', '- Xử lý vi phạm pháp luật và giải quyết khiếu nại, tố cáo liên quan đến việc thực hiện pháp luật về thuế theo thẩm quyền;', '- Xác nhận việc thực hiện nghĩa vụ thuế của người nộp thuế khi có đề nghị theo quy định của pháp luật;', '- Giao biên bản, kết luận, quyết định xử lý về thuế sau kiểm tra thuế, thanh tra thuế cho người nộp thuế và giải thích khi có yêu cầu;', '- Bồi thường thiệt hại cho người nộp thuế theo quy định của pháp luật về trách nhiệm bồi thường của Nhà nước;', '- Giám định để xác định số tiền thuế phải nộp của người nộp thuế theo trưng cầu, yêu cầu của cơ quan nhà nước có thẩm quyền.']::text[], array['Thanh tra thuế', 'Nhà chuyên môn về thuế']::text[], array['Kế toán - 2411', 'Kiểm toán - 2411']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 50) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2443', 'Nhà chuyên môn về trợ cấp xã hội của Chính phủ xây dựng và ban hành các văn bản quy phạm pháp luật liên quan đến trợ cấp xã hội; kiểm tra các ứng dụng và các tài liệu khác có liên quan để xác định loại và số lượng phúc lợi mà cá nhân có đủ điều kiện để nhận được.', array['- Xây dựng và ban hành theo thẩm quyền hoặc trình cấp có thẩm quyền ban hành các văn bản quy phạm pháp luật liên quan đến trợ cấp xã hội; tư vấn cá nhân và các tổ chức về pháp luật, quy tắc và quy định của chính phủ liên quan đến chương trình phúc lợi của chính phủ và giải ngân các khoản thanh toán hoặc giới thiệu các dịch vụ cũng như quyền và nghĩa vụ;', '- Kiểm tra các ứng dụng và các tài liệu khác có liên quan để xác định loại và số lượng phúc lợi mà cá nhân có đủ điều kiện để nhận được;', '- Đánh giá hồ sơ và phỏng vấn phúc lợi cho người nhận để đảm bảo tiếp tục đủ điều kiện lợi ích hay dịch vụ;', '- Thực hiện nhiệm vụ hành chính liên quan để duy trì hồ sơ về những trường hợp được trợ cấp xã hội và chuẩn bị báo cáo về các quyết định đủ điều kiện, quyết định giới thiệu, chấm dứt quyền lợi và lạm dụng hoặc lừa đảo.']::text[], array['- Nhà chuyên môn về hưu trí', '- Nhà chuyên môn về phúc lợi xã hội', '- Nhà chuyên môn về bồi thường an sinh xã hội']::text[], array['- Nhà chuyên môn về công tác tư vấn xã hội - 2635', '- Nhà chuyên môn về xã hội - 2635']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 70) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2444', 'Nhà chuyên môn về cấp phép của Chính phủ xây dựng và ban hành các văn bản quy phạm pháp luật liên quan đến cấp phép; kiểm tra các ứng dụng của các giấy phép để xuất khẩu hoặc nhập khẩu hàng hóa, thành lập doanh nghiệp, xây dựng nhà ở hoặc công trình khác hoặc để có được hộ chiếu; xác định các điều kiện của các ứng dụng cho phát hành các giấy phép hoặc hộ chiếu; xác định điều kiện cụ thể hoặc hạn chế để được gắn liền với giấy phép phát hành.', array['- Xây dựng và ban hành theo thẩm quyền hoặc trình cấp có thẩm quyền ban hành các văn bản quy phạm pháp luật liên quan đến cấp phép; tư vấn cá nhân về pháp luật và các quy định của Chính phủ liên quan đến các loại giấy phép cần thiết và các điều kiện kèm theo giấy phép đó về quyền và nghĩa vụ;', '- Kiểm tra các ứng dụng và tài liệu liên quan để xác định liệu có thể cấp giấy phép và các điều kiện đính kèm;', '- Kiểm tra các ứng dụng và phê duyệt các vấn đề của hộ chiếu;', '- Thực hiện các công việc hành chính liên quan để xử lý các ứng dụng, tài liệu hoạt động, đánh giá và quyết định và để chuẩn bị các thư từ thông báo cho người nộp đơn quyết định cấp phép;', '- Quản lý và ghi kiểm tra cần thiết để cấp giấy phép.']::text[], array['- Nhà chuyên môn về giấy phép xây dựng', '- Nhà chuyên môn về giấy phép kinh doanh', '- Nhà chuyên môn về văn bằng', '- Nhà chuyên môn về hộ chiếu (phát hành)']::text[], array['- Thanh tra xây dựng - 3112', '- Thanh tra phòng cháy - 3112']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 84) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2445', 'Kiểm lâm là lực lượng chuyên trách của Nhà nước có chức năng bảo vệ rừng, giúp Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn và Chủ tịch Ủy ban nhân dân cấp tỉnh thực hiện quản lý nhà nước về bảo vệ rừng, bảo đảm chấp hành pháp luật về bảo vệ và phát triển rừng.', array['- Tham mưu cho người đứng đầu cơ quan giúp Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn quản lý nhà nước về lâm nghiệp: xây dựng văn bản quy phạm pháp luật, chương trình, kế hoạch, phương án, đề án về quản lý, bảo vệ rừng, phòng cháy và chữa cháy rừng, bảo đảm chấp hành pháp luật về lâm nghiệp.', '- Chỉ đạo, hướng dẫn, kiểm tra công tác quản lý, bảo vệ rừng, phòng cháy và chữa cháy rừng, bảo đảm chấp hành pháp luật về lâm nghiệp trên phạm vi toàn quốc;', '- Tổ chức thực hiện các nhiệm vụ về quản lý, bảo vệ rừng, phòng cháy và chữa cháy rừng, bảo đảm chấp hành pháp luật về lâm nghiệp trên phạm vi toàn quốc;', '- Quản lý, chỉ đạo Kiểm lâm vùng thực hiện nhiệm vụ, quyền hạn của Kiểm lâm trung ương về quản lý, bảo vệ rừng, bảo đảm chấp hành pháp luật về lâm nghiệp và tổ chức lực lượng chuyên ngành về phòng cháy và chữa cháy rừng trên phạm vi vùng được giao phụ trách;', '- Thực hiện các nhiệm vụ khác theo quy định của pháp luật và cơ quan nhà nước có thẩm quyền giao;', '- Tham mưu cho người đứng đầu cơ quan chuyên môn giúp Ủy ban nhân dân cấp tỉnh quản lý nhà nước về lâm nghiệp trên phạm vi địa bàn tỉnh xây dựng chương trình, kế hoạch, phương án, đề án về quản lý, bảo vệ rừng, phòng cháy và chữa cháy rừng, bảo đảm chấp hành pháp luật về lâm nghiệp;', '- Tổ chức thực hiện các nhiệm vụ về quản lý, bảo vệ rừng, phòng cháy và chữa cháy rừng, bảo đảm chấp hành pháp luật về lâm nghiệp trên phạm vi địa bàn tỉnh;', '- Thực hiện các nhiệm vụ khác theo quy định của pháp luật và cơ quan nhà nước có thẩm quyền giao.']::text[], '{}'::text[], array['- Nhân viên bảo vệ rừng - 5409']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 100) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2446', 'Nhà Ngoại giao là người cụ thể hóa chủ trương, đường lối, chính sách đối ngoại của quốc gia, vùng lãnh thổ hoặc tổ chức quốc tế mà họ đại diện nhằm đạt được hoặc bảo vệ lợi ích/quyền lợi cao nhất trong quan hệ với các quốc gia, vùng lãnh thổ, tổ chức quốc tế khác thông qua đàm phán, thương lượng hòa bình.
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2449', 'Nhóm này bao gồm các nhà chuyên môn điều tiết của Chính phủ khác chưa được phân vào đâu. Ví dụ, nhóm bao gồm các nhà chuyên môn điều tiết về nông nghiệp, ngư nghiệp, lâm nghiệp, giá cả, lương.', array['- Kiểm tra địa điểm kinh doanh để đảm bảo sử dụng đúng trọng lượng và các biện pháp trong thương mại;', '- Giám sát quy định về giá để đánh giá các chi phí thích hợp cho hàng hóa và dịch vụ bảo vệ lợi ích người tiêu dùng;', '- Giám sát các quy định mức lương đảm bảo mức độ thích hợp phải trả cho công việc thực hiện và đánh giá tuân thủ pháp luật về tiêu chuẩn tuyển dụng;', '- Thực hiện nhiệm vụ liên quan đến điều tra và hành chính để ghi lại các kết quả, vấn đề tuân thủ tài liệu hoặc thực tiễn kinh doanh không phù hợp, chuẩn bị báo cáo và thư từ.']::text[], array['Thanh tra nông nghiệp', 'Thanh tra thủy sản', 'Thanh tra lâm nghiệp', 'Thanh tra giá cả', 'Thanh tra lương', 'Thanh tra đo lường']::text[], array['Thanh tra phòng cháy - 3112', 'Thanh tra y tế - 3257', 'Thanh tra sức khỏe nghề nghiệp và an toàn lao động - 3527', 'Thanh tra môi trường - 3257', 'Thanh tra vệ sinh - 3257.']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 134) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2511', 'Nhà phân tích hệ thống tiến hành nghiên cứu, phân tích và đánh giá các yêu cầu, quy trình hoặc vấn đề về công nghệ thông tin của khách hàng, đồng thời phát triển và thực hiện các đề xuất, khuyến nghị và kế hoạch cải thiện hệ thống thông tin hiện tại hoặc tương lai.', array['- Tư vấn với người dùng để xây dựng các yêu cầu tài liệu và với quản lý để đảm bảo thỏa thuận về các nguyên tắc hệ thống;', '- Xác định và phân tích các quy trình kinh doanh, quy trình và thực hành công việc;', '- Xác định và đánh giá sự thiếu hiệu quả và khuyến nghị thực hành kinh doanh tối ưu và chức năng và hành vi hệ thống;', '- Chịu trách nhiệm triển khai các giải pháp chức năng, chẳng hạn như tạo, áp dụng và thực hiện các kế hoạch kiểm tra hệ thống;', '- Phát triển các đặc tả chức năng để sử dụng bởi các nhà phát triển hệ thống;', '- Mở rộng hoặc sửa đổi hệ thống để cải thiện quy trình làm việc hoặc phục vụ các mục đích mới;', '- Điều phối và liên kết các hệ thống máy tính trong một tổ chức để tăng khả năng tương thích.']::text[], array['- Nhà phân tích kinh doanh (công nghệ thông tin)', '- Nhà khoa học máy tính', '- Nhà Phân tích hệ thống thông tin', 'Nhà Tư vấn hệ thống', '- Nhà thiết kế hệ thống (công nghệ thông tin)']::text[], array['- Quản trị viên hệ thống (máy tính) - 2522', '- Nhà phân tích truyền thông (máy tính) - 2523', '- Nhà phân tích mạng - 2523']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 160) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2512', 'Nhà phát triển phần mềm nghiên cứu, phân tích và đánh giá các yêu cầu cho các ứng dụng và hệ điều hành phần mềm hiện có hoặc mới, đồng thời thiết kế, phát triển, thử nghiệm và duy trì các giải pháp phần mềm để đáp ứng các yêu cầu này.', array['- Nghiên cứu, phân tích và đánh giá các yêu cầu đối với các ứng dụng phần mềm và hệ điều hành;', '- Nghiên cứu, thiết kế và phát triển hệ thống phần mềm máy tính;', '- Tham khảo ý kiến ​​với nhân viên kỹ thuật để đánh giá các giao diện giữa phần cứng và phần mềm;', '- Xây dựng và chỉ đạo các quy trình kiểm tra và xác nhận phần mềm;', '- Sửa phần mềm lỗi, để thích ứng với phần cứng mới hoặc nâng cấp giao diện và cải thiện hiệu suất;', '- Chỉ đạo lập trình phần mềm và phát triển tài liệu;', '- Đánh giá, phát triển, nâng cấp và ghi lại các quy trình bảo trì cho các hệ điều hành, môi trường truyền thông và phần mềm ứng dụng;', '- Tư vấn với khách hàng liên quan đến bảo trì hệ thống phần mềm.']::text[], array['- Lập trình viên phân tích', '- Nhà thiết kế phần mềm', '- Nhà phát triển phần mềm', '- Kỹ sư phần mềm']::text[], array['- Lập trình viên ứng dụng - 2514']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Ứng dụng phần mềm.', '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 180) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2513', 'Nhà phát triển web và truyền thông đa phương tiện kết hợp kiến ​​thức thiết kế và kỹ thuật để nghiên cứu, phân tích, đánh giá, thiết kế, lập trình và sửa đổi các trang web và ứng dụng kết hợp văn bản, đồ họa, hoạt hình, hình ảnh, âm thanh và video và các phương tiện tương tác khác.', array['- Phân tích, thiết kế và phát triển các trang web Internet bằng cách áp dụng kết hợp nghệ thuật và sáng tạo với lập trình phần mềm và ngôn ngữ kịch bản và giao tiếp với môi trường hoạt động;', '- Thiết kế và phát triển hoạt hình kỹ thuật số, hình ảnh, thuyết trình, trò chơi, âm thanh và video clip và ứng dụng Internet bằng phần mềm đa phương tiện, công cụ và tiện ích, đồ họa tương tác và ngôn ngữ lập trình;', '- Liên lạc với các chuyên gia mạng về các vấn đề liên quan đến web như bảo mật và lưu trữ trang web, để kiểm soát và thực thi bảo mật Internet và máy chủ web, phân bổ không gian, truy cập người dùng, liên tục kinh doanh, sao lưu trang web và lập kế hoạch khắc phục thảm họa;', '- Thiết kế, phát triển và tích hợp mã máy tính với các đầu vào chuyên dụng khác như tệp hình ảnh, tệp âm thanh và ngôn ngữ kịch bản, để sản xuất, duy trì và hỗ trợ các trang web;', '- Hỗ trợ phân tích, chỉ định và phát triển các chiến lược Internet, phương pháp dựa trên web và kế hoạch phát triển.']::text[], array['- Lập trình viên hoạt hình', '- Lập trình viên trò chơi máy tính', '- Nhà phát triển Internet', '- Lập trình viên đa phương tiện', '- Nhà kiến trúc trang web', '- Nhà phát triển trang web', '- Youtuber', '- Vlogger']::text[], array['- Nhà thiết kế trang web - 2166', '- Quản trị viên trang web - 3514', '- Kỹ thuật viên trang web - 3514']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 199) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2514', 'Nhà lập trình các ứng dụng viết và duy trì mã lập trình được nêu trong các hướng dẫn kỹ thuật và thông số kỹ thuật cho các ứng dụng phần mềm và hệ điều hành.', array['- Viết và duy trì mã chương trình được nêu trong các hướng dẫn và thông số kỹ thuật theo các tiêu chuẩn được công nhận chất lượng;', '- Sửa đổi, sửa chữa hoặc mở rộng các chương trình hiện có để tăng hiệu quả hoạt động hoặc thích ứng với các yêu cầu mới;', '- Tiến hành chạy thử các chương trình và ứng dụng phần mềm để xác nhận rằng chúng sẽ tạo ra thông tin mong muốn;', '- Biên soạn và viết tài liệu phát triển chương trình;', '- Xác định và truyền đạt các vấn đề kỹ thuật, quy trình và giải pháp.']::text[], array['Lập trình viên ứng dụng']::text[], array['- Nhà phân tích lập trình - 2512', '- Nhà phát triển phần mềm - 2512', '- Lập trình viên đa phương tiện - 2513']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 220) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2519', 'Nhóm này bao gồm các nhà chuyên môn về phát triển phần mềm và nhà phân tích chưa được phân vào đâu trong nhóm 251: Nhà chuyên môn về phân tích và phát triển phần mềm và các ứng dụng. Ví dụ, nhóm này bao gồm những nhà chuyên môn về đảm bảo chất lượng và kiểm thử phần mềm.', array['- Xây dựng và lập tài liệu kế hoạch kiểm thử phần mềm;', '- Cài đặt phần mềm và phần cứng và cấu hình phần mềm hệ điều hành để chuẩn bị thử nghiệm;', '- Xác minh rằng các chương trình hoạt động theo yêu cầu của người dùng và hướng dẫn được thiết lập;', '- Thực hiện, phân tích và ghi lại kết quả của các thử nghiệm ứng dụng phần mềm và thử nghiệm hệ thống thông tin và viễn thông;', '- Xây dựng và triển khai các chính sách, quy trình và kịch bản kiểm tra phần mềm và hệ thống thông tin.']::text[], array['- Nhà phân tích đảm bảo chất lượng (máy tính)', '- Nhà thử nghiệm phần mềm', '- Nhà kiểm tra hệ thống']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 234) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2521', 'Nhà quản trị và thiết kế cơ sở dữ liệu thiết kế, phát triển, kiểm soát, duy trì, hỗ trợ hiệu suất và bảo mật tối ưu của cơ sở dữ liệu.', array['- Thiết kế và phát triển kiến ​​trúc cơ sở dữ liệu, cấu trúc dữ liệu, bảng, từ điển và quy ước đặt tên cho các dự án hệ thống thông tin;', '- Thiết kế, xây dựng, sửa đổi, tích hợp, thực hiện và thử nghiệm các hệ thống quản lý cơ sở dữ liệu;', '- Tiến hành nghiên cứu và cung cấp tư vấn về việc lựa chọn, ứng dụng và triển khai các công cụ quản lý cơ sở dữ liệu;', '- Xây dựng và thực hiện chính sách, tài liệu, tiêu chuẩn và mô hình quản trị dữ liệu;', '- Xây dựng các chính sách và thủ tục để truy cập và sử dụng cơ sở dữ liệu và để sao lưu và phục hồi dữ liệu;', '- Thực hiện thiết lập vận hành và bảo trì phòng ngừa các bản sao lưu, quy trình phục hồi và thực thi các biện pháp kiểm soát bảo mật và toàn vẹn.']::text[], array['- Nhà quản trị dữ liệu', '- Nhà quản trị cơ sở dữ liệu', '- Nhà phân tích cơ sở dữ liệu', '- Kiến trúc sư cơ sở dữ liệu']::text[], array['- Nhà quản trị mạng - 2522', '- Nhà quản trị hệ thống (máy tính) - 2522', '- Quản trị viên trang web - 3514']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Quản trị cơ sở dữ liệu.', '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 249) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2522', 'Nhà quản trị hệ thống phát triển, kiểm soát, duy trì, hỗ trợ hiệu suất và bảo mật tối ưu của hệ thống công nghệ thông tin.', array['- Duy trì và quản trị mạng máy tính và các môi trường máy tính liên quan, bao gồm phần cứng máy tính, phần mềm hệ thống, phần mềm ứng dụng và tất cả các cấu hình;', '- Đề xuất các thay đổi để cải thiện cấu hình hệ thống và mạng; xác định các yêu cầu phần cứng hoặc phần mềm liên quan đến các thay đổi đó;', '- Chẩn đoán các vấn đề về phần cứng và phần mềm;', '- Thực hiện sao lưu dữ liệu và các hoạt động khắc phục thảm họa;', '- Vận hành các bảng điều khiển chính để giám sát hiệu suất của các hệ thống, mạng máy tính và để phối hợp truy cập, sử dụng mạng máy tính.']::text[], array['- Nhà Quản trị mạng', '- Nhà Quản trị hệ thống (máy tính)']::text[], array['- Nhà Quản trị cơ sở dữ liệu - 2521', '- Nhà phân tích mạng - 2523', '- Nhà Quản trị trang web - 3514', '- Quản trị viên trang web - 3514', '- Kỹ thuật viên trang web - 3514']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 268) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2523', 'Nhà chuyên môn về mạng máy tính nghiên cứu, phân tích, thiết kế, thử nghiệm và đề xuất các chiến lược cho kiến ​​trúc và phát triển mạng. Họ thực hiện, quản lý, bảo trì, cấu hình phần cứng và phần mềm mạng; giám sát, khắc phục sự cố và tối ưu hóa hiệu suất.', array['- Phân tích, phát triển, giải thích, đánh giá các thông số kỹ thuật, thiết kế hệ thống phức tạp, mô hình dữ liệu và sơ đồ trong việc phát triển, cấu hình và tích hợp các hệ thống máy tính;', '- Nghiên cứu, phân tích, đánh giá và giám sát cơ sở hạ tầng mạng để đảm bảo rằng các mạng được cấu hình để hoạt động với hiệu suất tối ưu;', '- Đánh giá và đề xuất cải tiến hoạt động mạng, phần cứng, phần mềm, truyền thông và hệ điều hành tích hợp;', '- Cung cấp các kỹ năng chuyên môn trong việc hỗ trợ và khắc phục các sự cố và trường hợp khẩn cấp của mạng;', '- Cài đặt, thiết lập cấu hình, kiểm tra, duy trì,nâng cấp, quản trị các mạng mới và ứng dụng cơ sở dữ liệu phần mềm, máy chủ và máy trạm;', '- Chuẩn bị và duy trì các quy trình và tài liệu cho kiểm kê mạng; ghi lại chẩn đoán và giải quyết các lỗi mạng; cải tiến và sửa đổi các hướng dẫn bảo trì mạng;', '- Giám sát lưu lượng và hoạt động của mạng, dung lượng và mức độ sử dụng để đảm bảo tính toàn vẹn liên tục và hiệu suất mạng tối ưu.']::text[], array['- Nhà phân tích truyền thông (máy tính)', '- Nhà phân tích mạng']::text[], array['- Nhà phân tích hệ thống - 2511', '- Nhà quản trị mạng - 2522']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 285) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2529', 'Nhà chuyên môn về cơ sở dữ liệu và mạng chưa được phân vào đâu bao gồm các nhà chuyên môn về bảo mật công nghệ thông tin và truyền thông.', array['- Phát triển các kế hoạch để bảo vệ các tệp máy tính chống lại sự sửa đổi, phá hủy hoặc tiết lộ vô tình hay trái phép và để đáp ứng nhu cầu xử lý dữ liệu khẩn cấp;', '- Đào tạo người dùng và thúc đẩy nhận thức bảo mật để đảm bảo an ninh hệ thống và cải thiện hiệu quả của máy chủ và mạng;', '- Trao đổi với người dùng để thảo luận về các vấn đề như nhu cầu truy cập dữ liệu máy tính, vi phạm bảo mật và thay đổi chương trình;', '- Theo dõi các báo cáo hiện tại về vi-rút máy tính để xác định thời điểm cập nhật hệ thống chống vi-rút;', '- Sửa đổi các tệp bảo mật máy tính để kết hợp phần mềm mới, sửa lỗi hoặc thay đổi trạng thái truy cập cá nhân;', '- Giám sát việc sử dụng các tệp dữ liệu và điều chỉnh quyền truy cập để bảo vệ thông tin trong các tệp máy tính;', '- Thực hiện đánh giá rủi ro và thực hiện các thử nghiệm của hệ thống xử lý dữ liệu để đảm bảo hoạt động của các hoạt động xử lý dữ liệu và các biện pháp bảo mật;', '- Mã hóa truyền dữ liệu và dựng tường lửa để che giấu thông tin bí mật khi nó được truyền đi và để tránh các chuyển giao kỹ thuật số bị nhiễm độc.']::text[], array['- Nhà khai thác dữ liệu', '- Nhà chuyên môn về điều tra số kỹ thuật số', '- Nhà chuyên môn về bảo mật (công nghệ thông tin và truyền thông)']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 301) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2611', 'Luật sư thực hiện dịch vụ pháp lý theo yêu cầu của cá nhân, cơ quan, tổ chức (sau đây gọi chung là khách hàng). Dịch vụ pháp lý của luật sư bao gồm tham gia tố tụng, tư vấn pháp luật, đại diện ngoài tố tụng cho khách hàng và các dịch vụ pháp lý khác.', array['- Tham gia tố tụng với tư cách là người bào chữa cho người bị tạm giữ, bị can, bị cáo hoặc là người bảo vệ quyền lợi của người bị hại, nguyên đơn dân sự, bị đơn dân sự, người có quyền lợi, nghĩa vụ liên quan trong vụ án hình sự;', '- Tham gia tố tụng với tư cách là người đại diện hoặc là người bảo vệ quyền, lợi ích hợp pháp của nguyên đơn, bị đơn, người có quyền lợi, nghĩa vụ liên quan trong các vụ án về tranh chấp dân sự, hôn nhân và gia đình, kinh doanh, thương mại, lao động, hành chính, việc về yêu cầu dân sự, hôn nhân và gia đình, kinh doanh, thương mại, lao động và các vụ, việc khác theo quy định của pháp luật;', '- Thực hiện tư vấn pháp luật;', '- Đại diện ngoài tố tụng cho khách hàng để thực hiện các công việc có liên quan đến pháp luật;', '- Thực hiện dịch vụ pháp lý khác theo quy định của pháp luật.']::text[], array['- Luật sư bào chữa', '- Luật sư luận tội', '- Luật sư tư vấn']::text[], array['- Công chứng viên - 2619', '- Nhân viên làm thủ tục chuyển sở hữu - 3411', '- Thư ký luật - 3342']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 322) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2612', 'Thẩm phán chủ tọa tố tụng dân sự và hình sự tại tòa án.', array['- Chủ trì các phiên tòa và xét xử;', '- Giải thích và thực thi các quy tắc về thủ tục và đưa ra phán quyết liên quan đến sự chấp nhận của bằng chứng;', '- Xác định các quyền và nghĩa vụ của các bên liên quan và trong các trường hợp xét xử của bồi thẩm đoàn;', '- Hướng dẫn bồi thẩm đoàn về các điểm luật áp dụng cho vụ án;', '- Cân nhắc và xem xét bằng chứng trong các phiên tòa không thuộc bồi thẩm đoàn, quyết định kết tội hoặc vô tội hoặc mức độ trách nhiệm của bị cáo hoặc bị cáo;', '- Tuyên án đối với những người bị kết án trong vụ án hình sự, xác định thiệt hại hoặc biện pháp khắc phục thích hợp khác trong vụ án dân sự và ra lệnh của tòa án;', '- Nghiên cứu các vấn đề pháp lý và viết ý kiến về các vấn đề.']::text[], array['- Chánh tòa', '- Phó Chánh tòa', '- Thẩm phán cao cấp', '- Thẩm phán tối cao', '- Thẩm tra viên']::text[], array['- Thư ký luật - 3342', '- Thư ký thẩm phán - 3411']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 338) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2619', 'Nhà chuyên môn về luật khác chưa được phân vào đâu bao gồm những người thực hiện các chức năng pháp lý khác với các vụ kiện hoặc khởi tố hoặc chủ tọa các thủ tục tố tụng tư pháp.', array['- Đưa ra lời khuyên về các khía cạnh pháp lý của các vấn đề cá nhân, kinh doanh và hành chính khác nhau;', '- Soạn thảo các văn bản và hợp đồng pháp lý;', '- Sắp xếp chuyển nhượng tài sản;', '- Xác định bằng cách hỏi nguyên nhân của bất kỳ cái chết nào rõ ràng không phải do nguyên nhân tự nhiên;', '- Chứng nhận tính xác thực, hợp pháp của hợp đồng, giao dịch dân sự khác bằng văn bản, tính chính xác, hợp pháp, không trái đạo đức xã hội của bản dịch giấy tờ, văn bản từ tiếng Việt sang tiếng nước ngoài hoặc từ tiếng nước ngoài sang tiếng Việt;', '- Tống đạt giấy tờ, hồ sơ, tài liệu; lập vi bằng theo yêu cầu của cá nhân, cơ quan, tổ chức; xác minh điều kiện thi hành án theo yêu cầu của đương sự và người có quyền lợi, nghĩa vụ liên quan; tổ chức thi hành các bản án, quyết định của Tòa án theo yêu cầu của đương sự và các công việc khác theo quy định của pháp luật có liên quan.']::text[], array['- Nhân viên điều tra', '- Nhà luật học (trừ luật sư hoặc thẩm phán)', '- Công chứng viên', '- Thừa phát lại']::text[], array['- Chấp hành viên - 3411']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 357) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2621', 'Nhà chuyên môn về lưu trữ và giám tuyển thu thập, thẩm định, đảm bảo an toàn và bảo quản các nội dung của tài liệu lưu trữ, đồ tạo tác và hồ sơ về lợi ích lịch sử, văn hóa, hành chính, nghệ thuật và của các đối tượng khác. Họ lập kế hoạch, đưa ra và thực hiện các hệ thống để bảo vệ hồ sơ và các tài liệu có giá trị lịch sử.', array['- Đánh giá và lưu giữ hồ sơ cho các mục đích hành chính, lịch sử, pháp lý, bằng chứng và các mục đích khác;', '- Chỉ đạo hoặc thực hiện việc chuẩn bị các chỉ mục, thư mục, bản sao vi phim và các công cụ hỗ trợ tham khảo khác cho tài liệu được thu thập và cung cấp cho người dùng;', '- Nghiên cứu nguồn gốc, phân phối và sử dụng các tài liệu và đối tượng quan tâm về văn hóa và lịch sử;', '- Tổ chức, phát triển và duy trì các bộ sưu tập các mặt hàng có ý nghĩa nghệ thuật, văn hóa, khoa học hoặc lịch sử;', '- Chỉ đạo hoặc thực hiện phân loại, lập danh mục các bộ sưu tập bảo tàng, phòng trưng bày nghệ thuật và tổ chức triển lãm;', '- Nghiên cứu, thẩm định, tổ chức và lưu giữ các tài liệu có ý nghĩa và có giá trị lịch sử như giấy tờ của chính phủ, giấy tờ riêng, ảnh, bản đồ, bản thảo và tài liệu nghe nhìn;', '- Chuẩn bị các bài báo và báo cáo học thuật;', '- Lập kế hoạch và thực hiện quản lý trên máy vi tính các tài liệu lưu trữ và hồ sơ điện tử;', '- Tổ chức triển lãm tại các bảo tàng và phòng trưng bày nghệ thuật, công khai các cuộc triển lãm và sắp xếp các màn hình đặc biệt cho sở thích chung, chuyên ngành hoặc giáo dục;', '- Thẩm định và mua tài liệu lưu trữ để xây dựng và phát triển một bộ sưu tập lưu trữ cho mục đích nghiên cứu.']::text[], array['- Nhà lưu trữ', '- Người quản lý phòng trưng bày nghệ thuật', '- Người phụ trách bảo tàng', '- Quản lý hồ sơ']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 376) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2622', 'Thủ thư và các nhà chuyên môn về thông tin liên quan thu thập, lựa chọn, phát triển, tổ chức và duy trì các bộ sưu tập thư viện và các kho thông tin khác; tổ chức và kiểm soát các dịch vụ thư viện khác và cung cấp thông tin cho người dùng.', array['- Tổ chức, phát triển và duy trì một bộ sưu tập sách, tạp chí định kỳ và các tài liệu được in, nghe nhìn và kỹ thuật số khác;', '- Lựa chọn và đề nghị mua lại sách, các tài liệu được in hoặc nghe và ghi kỹ thuật số khác;', '- Tổ chức, phân loại và lập danh mục tài liệu thư viện;', '- Quản lý việc mượn thư viện và các cơ sở cho mượn liên thư viện và mạng thông tin;', '- Truy xuất tài liệu và cung cấp thông tin cho doanh nghiệp và những người dùng khác dựa trên chính bộ sưu tập hoặc trên hệ thống thư viện và mạng thông tin;', '- Tiến hành nghiên cứu và phân tích hoặc sửa đổi thư viện và dịch vụ thông tin phù hợp với những thay đổi về nhu cầu của người dùng;', '- Đưa ra và thực hiện các đề án và mô hình khái niệm cho việc lưu trữ, tổ chức, phân loại và truy xuất thông tin;', '- Chuẩn bị các bài báo và báo cáo học thuật;', '- Thực hiện tìm kiếm tài liệu tham khảo trực tuyến và qua phương tiện tương tác, thực hiện các khoản vay liên thư viện và thực hiện các chức năng khác để hỗ trợ người dùng truy cập tài liệu thư viện.']::text[], array['- Người lập danh mục sách', '- Người lập mục lục', '- Thủ thư']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 394) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2631', 'Nhà kinh tế học tiến hành nghiên cứu, theo dõi dữ liệu, phân tích thông tin và chuẩn bị các báo cáo và kế hoạch để giải quyết các vấn đề kinh tế và kinh doanh; phát triển các mô hình để phân tích, giải thích và dự báo hành vi và mô hình kinh tế. Họ tư vấn cho doanh nghiệp, các nhóm lợi ích và chính phủ để đưa ra các giải pháp để trình bày hoặc dự kiến ​​các vấn đề kinh tế và kinh doanh.', array['- Dự báo những thay đổi trong môi trường kinh tế để lập ngân sách ngắn hạn, lập kế hoạch dài hạn và đánh giá đầu tư;', '- Xây dựng các khuyến nghị, chính sách và kế hoạch cho nền kinh tế, chiến lược và đầu tư của công ty và thực hiện các nghiên cứu khả thi cho các dự án;', '- Giám sát dữ liệu kinh tế để đánh giá hiệu quả và tư vấn về sự phù hợp của các chính sách tiền tệ và tài chính;', '- Dự báo sản xuất và tiêu thụ các sản phẩm và dịch vụ cụ thể dựa trên hồ sơ sản xuất và tiêu dùng trong quá khứ và các điều kiện kinh tế và đặc thù chung của ngành;', '- Chuẩn bị dự báo thu nhập và chi tiêu, lãi suất và tỷ giá hối đoái;', '- Phân tích các yếu tố xác định sự tham gia của lực lượng lao động, việc làm, tiền lương, thất nghiệp và các kết quả thị trường lao động khác;', '- Áp dụng các công thức toán học và phương pháp thống kê để kiểm tra các lý thuyết kinh tế và đưa ra các giải pháp cho các vấn đề kinh tế;', '- Biên soạn, phân tích và giải thích dữ liệu kinh tế bằng lý thuyết kinh tế và một loạt các phương pháp thống kê và phương pháp khác;', '- Đánh giá kết quả của các quyết định chính trị liên quan đến kinh tế và tài chính công; tư vấn về chính sách kinh tế và các hướng hành động khả thi theo các yếu tố và xu hướng kinh tế trong quá khứ, hiện tại và dự kiến;', '- Chuẩn bị các bài báo và báo cáo học thuật;', '- Kiểm tra các vấn đề liên quan đến hoạt động kinh tế của các công ty tư nhân;', '- Tiến hành nghiên cứu về điều kiện thị trường ở khu vực địa phương, khu vực hoặc quốc gia để thiết lập mức bán và giá cho hàng hóa và dịch vụ, để đánh giá tiềm năng thị trường và xu hướng trong tương lai để phát triển các chiến lược kinh doanh.']::text[], array['- Nhà kinh tế lượng', '- Cố vấn kinh tế', '- Nhà phân tích kinh tế', '- Nhà kinh tế', '- Chuyên gia kinh tế lao động']::text[], array['- Nhà thống kê - 2122']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 413) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2632', 'Nhà xã hội học, nhà nhân chủng học và các nghề có liên quan điều tra và mô tả cấu trúc, nguồn gốc và sự tiến hóa của các xã hội và sự phụ thuộc lẫn nhau giữa các điều kiện môi trường và các hoạt động của con người. Họ cung cấp lời khuyên về ứng dụng thực tế của những phát hiện của họ trong việc xây dựng các chính sách kinh tế và xã hội.', array['- Tiến hành nghiên cứu về nguồn gốc, sự phát triển, cấu trúc, mô hình xã hội, tổ chức và mối liên hệ của xã hội loài người;', '- Truy tìm nguồn gốc và sự tiến hóa của loài người thông qua nghiên cứu thay đổi đặc điểm và các thiết chế văn hóa xã hội;', '- Truy tìm sự phát triển của loài người thông qua các vật chất còn sót lại của quá khứ như nhà ở, đền thờ, công cụ, đồ gốm, tiền xu, vũ khí hoặc điêu khắc;', '- Nghiên cứu các khía cạnh vật lý và khí hậu của các khu vực và tương quan những phát hiện này với các hoạt động kinh tế, xã hội và văn hóa;', '- Phát triển lý thuyết, mô hình và phương pháp để giải thích và mô tả các hiện tượng xã hội;', '- Đánh giá kết quả của các quyết định chính trị liên quan đến chính sách xã hội;', '- Phân tích và đánh giá dữ liệu xã hội;', '- Tư vấn về việc áp dụng thực tế các phát hiện trong việc xây dựng các chính sách kinh tế và xã hội cho các nhóm dân cư và khu vực và cho sự phát triển của thị trường;', '- Chuẩn bị các bài báo và báo cáo học thuật.']::text[], array['- Nhân chủng học', '- Nhà khảo cổ học', '- Nhà tội phạm học', '- Nhà dân tộc học', '- Nhà địa lý học', '- Nhà xã hội học']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 436) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2633', 'Nhà triết học, sử học và khoa học chính trị tiến hành nghiên cứu về bản chất của kinh nghiệm và sự tồn tại của con người, các giai đoạn hoặc các khía cạnh của lịch sử loài người, các cấu trúc chính trị, các phong trào và hành vi. Họ viết tài liệu và báo cáo về những phát hiện để thông báo và hướng dẫn các hành động chính trị và cá nhân.', array['- Nghiên cứu lý luận các nguyên nhân, nguyên tắc và ý nghĩa chung của thế giới, hành động của con người, kinh nghiệm và sự tồn tại; diễn giải và phát triển các khái niệm và lý thuyết triết học;', '- Tư vấn và so sánh nguồn gốc chính là hồ sơ gốc hoặc đương đại về các sự kiện trong quá khứ và các nguồn thứ cấp như phát hiện khảo cổ học hoặc nhân học;', '- Trích xuất tài liệu liên quan, kiểm tra tính xác thực của nó, nghiên cứu và mô tả lịch sử của một thời kỳ, quốc gia hoặc khu vực cụ thể hoặc một khía cạnh cụ thể, ví dụ về kinh tế, xã hội, chính trị hoặc về lịch sử của nó;', '- Tiến hành nghiên cứu trong các lĩnh vực như triết học chính trị, hoặc lý thuyết và thực tiễn trong quá khứ và hiện tại của các hệ thống chính trị, thể chế hoặc hành vi;', '- Quan sát các thể chế chính trị đương đại và thu thập dữ liệu về chúng từ nhiều nguồn khác nhau bao gồm các cuộc phỏng vấn với các quan chức chính phủ, đảng chính trị và những người có liên quan khác;', '- Phát triển lý thuyết, mô hình và phương pháp để giải thích, mô tả bản chất của kinh nghiệm con người, các sự kiện, hành vi lịch sử và chính trị;', '- Trình bày những phát hiện và kết luận để công bố hoặc sử dụng bởi chính phủ, đảng chính trị hoặc các tổ chức khác và những người quan tâm;', '- Chuẩn bị các bài báo và báo cáo học thuật.']::text[], array['- Nhà nghiên cứu phả hệ', '- Nhà sử học', '- Triết gia', '- Nhà khoa học chính trị']::text[], array['- Cố vấn chính trị - 2422']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 455) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2634', 'Nhà tâm lý học nghiên cứu các hiện tượng tinh thần và hành vi của con người với tư cách cá nhân hoặc theo nhóm và áp dụng kiến ​​thức này để thúc đẩy sự điều chỉnh và phát triển cá nhân, xã hội, giáo dục hoặc nghề nghiệp.', array['- Lập kế hoạch và thực hiện các bài kiểm tra để đo lường các đặc điểm tinh thần, thể chất và các đặc điểm khác như trí thông minh, khả năng, năng khiếu, tiềm năng, v.v., diễn giải, đánh giá kết quả và đưa ra lời khuyên;', '- Phân tích ảnh hưởng của di truyền, các yếu tố xã hội, nghề nghiệp và các yếu tố khác đối với suy nghĩ và hành vi cá nhân;', '- Thực hiện tư vấn qua phỏng vấn hoặc trị liệu với các cá nhân, các nhóm và cung cấp các dịch vụ tiếp theo;', '- Duy trì các liên hệ cần thiết chẳng hạn như những người có thành viên gia đình, cơ quan giáo dục hoặc người sử dụng lao động và đề xuất các giải pháp khả thi và xử lý các vấn đề;', '- Nghiên cứu các yếu tố tâm lý trong chẩn đoán, điều trị và phòng ngừa các bệnh tâm thần, rối loạn cảm xúc hoặc nhân cách và trao đổi với các chuyên gia liên quan;', '- Chuẩn bị các bài báo và báo cáo học thuật;', '- Xây dựng các bài kiểm tra thành tích, chẩn đoán và dự đoán để giáo viên sử dụng trong phương pháp lập kế hoạch và nội dung giảng dạy;', '- Thực hiện khảo sát và nghiên cứu về thiết kế công việc, nhóm làm việc, tinh thần, động lực, giám sát và quản lý;', '- Phát triển lý thuyết, mô hình và phương pháp để giải thích và mô tả hành vi của con người.']::text[], array['- Nhà tâm lý học lâm sàng', '- Nhà tâm lý học giáo dục', '- Nhà tâm lý học nghề nghiệp, tổ chức', '- Nhà trị liệu tâm lý', '- Nhà tâm lý học thể thao', '- Nhà tâm lý học đường', '- Nhà tâm lý học thần kinh', '- Nhà tâm lý học pháp y']::text[], array['- Bác sĩ tâm thần - 22128']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 473) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2635', 'Nhà chuyên môn về tư vấn và công tác xã hội cung cấp lời khuyên và hướng dẫn cho các cá nhân, gia đình, nhóm, cộng đồng và tổ chức để đối phó với những khó khăn xã hội và cá nhân. Họ hỗ trợ khách hàng phát triển kỹ năng, tiếp cận các nguồn lực và dịch vụ hỗ trợ cần thiết để đáp ứng các vấn đề phát sinh từ thất nghiệp, nghèo đói, khuyết tật, nghiện ngập, tội phạm và hành vi phạm pháp, hôn nhân và các vấn đề khác.', array['- Phỏng vấn khách hàng cá nhân, trong gia đình theo nhóm, để đánh giá tình hình và vấn đề của họ và xác định các loại dịch vụ cần thiết;', '- Phân tích tình huống của khách hàng và đưa ra các phương pháp thay thế để giải quyết vấn đề;', '- Lập hồ sơ vụ án hoặc báo cáo cho tòa án và các thủ tục tố tụng khác;', '- Cung cấp dịch vụ tư vấn, trị liệu và hòa giải; tạo điều kiện cho các phiên nhóm để hỗ trợ khách hàng phát triển các kỹ năng và hiểu biết cần thiết để giải quyết các vấn đề xã hội và cá nhân của họ;', '- Lập kế hoạch và thực hiện các chương trình hỗ trợ cho khách hàng bao gồm can thiệp khủng hoảng và giới thiệu đến các cơ quan hỗ trợ tài chính, trợ giúp pháp lý, nhà ở, điều trị y tế và các dịch vụ khác;', '- Điều tra các trường hợp lạm dụng hoặc bỏ bê và hành động để bảo vệ trẻ em và những người khác có nguy cơ;', '- Làm việc với những người phạm tội trong và sau tuyên án giúp họ hòa nhập với cộng đồng và thay đổi thái độ, hành vi để giảm bớt sự xúc phạm;', '- Cung cấp lời khuyên cho các giám thị nhà tù, các hội đồng xét duyệt quản chế và tạm tha giúp xác định những điều kiện để một người phạm tội nên bị tống giam, ra tù hoặc trải qua các biện pháp cải huấn thay thế;', '- Đóng vai trò là người ủng hộ cho các nhóm khách hàng trong cộng đồng và vận động hành lang cho các giải pháp cho các vấn đề ảnh hưởng đến họ;', '- Xây dựng các chương trình phòng ngừa và can thiệp để đáp ứng nhu cầu của cộng đồng;', '- Duy trì liên lạc với các cơ quan dịch vụ xã hội, tổ chức giáo dục và nhà cung cấp dịch vụ chăm sóc sức khỏe khác có liên quan với khách hàng để cung cấp thông tin và nhận phản hồi về tình hình và tiến độ chung của khách hàng.']::text[], array['- Nhà chuyên môn về tư vấn cai nghiện', '- Nhà chuyên môn về tư vấn khủng hoảng', '- Nhà chuyên môn về tư vấn trẻ em', '- Cán bộ phúc lợi xã hội cấp huyện', '- Nhà chuyên môn về tư vấn gia đình', '- Nhà chuyên môn về tư vấn hôn nhân', '- Nhà quản chế', '- Nhà chuyên môn về tư vấn chống tấn công tình dục', '- Nhà chuyên môn về xã hội', '- Nhà chuyên môn về phúc lợi phụ nữ']::text[], array['- Nhà tâm lý học - 2634', '- Nhân viên hỗ trợ phúc lợi - 3412']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 496) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2636', 'Nhà chuyên môn về tôn giáo hoạt động như người truyền giữ các truyền thống liên quan đến việc thực hành tôn giáo và tín ngưỡng thiêng liêng. Họ tiến hành các dịch vụ tôn giáo, cử hành hoặc điều hành các nghi thức của một đức tin.', array['- Duy trì truyền thống, tập quán và tín ngưỡng thiêng liêng;', '- Tiến hành các nghi lễ tôn giáo;', '- Thực hiện các nhiệm vụ hành chính và xã hội khác nhau bao gồm tham gia các ủy ban và các cuộc họp của các tổ chức tôn giáo;', '- Cung cấp hướng dẫn tinh thần và đạo đức theo tôn giáo được tuyên xưng;', '- Tuyên truyền các học thuyết tôn giáo ở nước mình hoặc nước ngoài;', '- Chuẩn bị và trình bày các bài giảng tôn giáo;', '- Phát triển và chỉ đạo các khóa học và chương trình giáo dục tôn giáo;', '- Tư vấn cho các cá nhân về các vấn đề liên cá nhân, sức khỏe, tài chính và tôn giáo;', '- Lên lịch và tham gia các sự kiện đặc biệt như trại, hội nghị, hội thảo và các khóa tu.']::text[], array['- Sư trụ trì', '- Giáo sĩ Hồi giáo', '- Trưởng ban tôn giáo', '- Giáo sĩ Đạo Hindu', '- Linh mục', '- Giáo sĩ Do thái']::text[], array['- Người thuyết giáo - 3413', '- Nhà sư - 3413', '- Nữ tu - 3413', 'Ghi chú:', 'Các thành viên của các dòng tu có công việc liên quan đến việc thực hiện các nhiệm vụ của các nghề nghiệp khác ví dụ như giáo viên, y tá hoặc nhân viên hỗ trợ phúc lợi được phân loại theo nhiệm vụ chính.']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 524) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2641', 'Nhà văn và nghề có liên quan lên kế hoạch, nghiên cứu, viết sách, kịch bản, vở kịch, bài luận, bài phát biểu, hướng dẫn sử dụng, thông số kỹ thuật và các bài báo không phải là báo chí khác (trừ tài liệu cho báo, tạp chí và các ấn phẩm định kỳ khác) để xuất bản hoặc trình bày.', array['- Xây dựng, viết và biên tập tiểu thuyết, vở kịch, kịch bản, thơ và các tài liệu khác để xuất bản hoặc trình bày;', '- Tiến hành nghiên cứu để thiết lập nội dung thực tế và để có được thông tin cần thiết khác;', '- Viết kịch bản và diễn biến, chuẩn bị các chương trình cho các sản phẩm sân khấu, phim, đài phát thanh và truyền hình;', '- Phân tích tài liệu như thông số kỹ thuật, ghi chú, bản vẽ và tạo hướng dẫn sử dụng tài liệu và các tài liệu khác để giải thích rõ ràng, chính xác việc cài đặt, vận hành, bảo trì phần mềm, điện tử, cơ khí và các thiết bị khác;', '- Viết tài liệu quảng cáo, sổ tay và các ấn phẩm kỹ thuật tương tự;', '- Chọn tài liệu để xuất bản, kiểm tra văn phong, ngữ pháp và độ chính xác của nội dung, sắp xếp cho bất kỳ sửa đổi cần thiết nào và kiểm tra các bản sao bằng chứng trước khi in.']::text[], array['- Nhà văn', '- Biên tập sách', '- Người viết luận', '- Người lập chỉ mục', '- Nhà văn tương tác truyền thông', '- Người viết tiểu thuyết', '- Nhà viết kịch', '- Nhà thơ', '- Người viết kịch bản', '- Người viết diễn văn', '- Nhà khoa học thông tin kỹ thuật', '- Nhà văn kỹ thuật']::text[], array['- Nhà chuyên môn về quảng cáo - 2431', '- Nhà chuyên môn về quan hệ công chúng - 2432', '- Nhà báo - 2642', '- Biên tập báo - 2642']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 552) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2642', 'Nhà báo, biên tập viên nghiên cứu, điều tra, giải thích, truyền đạt tin tức và công chúng thông qua các tờ báo, truyền hình, đài phát thanh và phương tiện truyền thông khác.', array['- Thu thập tin tức địa phương, quốc gia và quốc tế thông qua các cuộc phỏng vấn, điều tra và quan sát, tham dự các sự kiện công cộng, tìm kiếm hồ sơ, xem xét công việc bằng văn bản, tham dự các buổi biểu diễn phim và sân khấu;', '- Thu thập, báo cáo, bình luận về tin tức và các vấn đề thời sự để xuất bản trên báo, tạp chí hoặc để phát sóng qua đài phát thanh, truyền hình hoặc phương tiện truyền thông webcast;', '- Tiếp nhận, phân tích và xác minh tin tức và bản sao khác cho chính xác;', '- Phỏng vấn các chính trị gia và các nhân vật công cộng khác tại các cuộc họp báo và trong các dịp khác bao gồm các cuộc phỏng vấn cá nhân được ghi lại cho đài phát thanh, truyền hình hoặc phương tiện truyền thông webcast;', '- Nghiên cứu và báo cáo về sự phát triển trong các lĩnh vực chuyên ngành như y học, khoa học và công nghệ;', '- Viết các bài xã luận và bình luận về các chủ đề quan tâm hiện tại để kích thích sự quan tâm của công chúng và bày tỏ quan điểm của một nhà xuất bản hoặc đài truyền hình;', '- Viết các bài phê bình về các tác phẩm văn học, âm nhạc và nghệ thuật khác dựa trên kiến ​​thức, phán đoán và kinh nghiệm cho các tờ báo, truyền hình, đài phát thanh và các phương tiện truyền thông khác;', '- Chọn tài liệu để xuất bản, kiểm tra văn phong, ngữ pháp, độ chính xác, tính hợp pháp của nội dung và sắp xếp cho bất kỳ sửa đổi cần thiết nào;', '- Liên lạc với nhân viên sản xuất trong việc kiểm tra các bản sao bằng chứng cuối cùng ngay trước khi in;', '- Lựa chọn, lắp ráp và chuẩn bị tài liệu công khai về doanh nghiệp hoặc các tổ chức khác để phát hành thông qua báo chí, đài phát thanh, truyền hình và các phương tiện truyền thông khác.']::text[], array['- Trưởng phòng, phó trưởng phòng nghiệp vụ báo chí', '- Nhà báo', '- Biên tập báo chí', '- Phóng viên báo chí', '- Nhà báo thể thao', '- Thư ký tòa soạn', '- Nhà sản xuất tin tức trên tivi/đài phát thanh', '- Phóng viên tin tức trên tivi/đài phát thanh']::text[], array['- Nhà chuyên môn về quan hệ công chúng - 2432', '- Nhà văn - 2641', '- Biên tập sách - 2641', '- Phóng viên ảnh - 3431', '- Người điều khiển máy ảnh - 3521']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 579) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2643', 'Nhà biên dịch, phiên dịch và nhà ngôn ngữ khác dịch hoặc phiên dịch từ ngôn ngữ này sang ngôn ngữ khác và nghiên cứu nguồn gốc, sự phát triển và cấu trúc của ngôn ngữ.', array['- Nghiên cứu mối quan hệ giữa các ngôn ngữ cổ và các nhóm ngôn ngữ hiện đại, truy tìm nguồn gốc và sự phát triển của các từ, ngữ pháp, hình thức ngôn ngữ và trình bày các kết quả;', '- Tư vấn hoặc chuẩn bị các hệ thống phân loại ngôn ngữ, ngữ pháp, từ điển và các tài liệu tương tự;', '- Dịch từ ngôn ngữ này sang ngôn ngữ khác và đảm bảo rằng ý nghĩa chính xác của bản gốc được giữ lại, rằng các tác phẩm hợp pháp, kỹ thuật hoặc khoa học được thể hiện chính xác và các cụm từ và thuật ngữ về tinh thần và phong cách của tác phẩm văn học được truyền đạt tốt;', '- Phát triển các phương pháp sử dụng máy tính và các công cụ khác để cải thiện năng suất và chất lượng dịch thuật;', '- Phiên dịch từ ngôn ngữ nói hoặc ngôn ngữ đã ký sang ngôn ngữ nói hoặc ký khác, đặc biệt tại các hội nghị, cuộc họp và các dịp tương tự và đảm bảo rằng ý nghĩa chính xác, truyền tải được tinh thần của bản gốc;', '- Sửa đổi và sửa chữa tài liệu dịch.']::text[], array['- Thông dịch viên', '- Nhà làm từ điển', '- Nhà triết học', '- Thông dịch viên ngôn ngữ ký hiệu', '- Người làm phụ đề', '- Người phiên dịch', '- Trình dịch - sửa đổi']::text[], array['- Nhà văn - 2641', '- Biên tập sách - 2641', '- Nhà báo - 2642']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 607) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2651', 'Nghệ sĩ hình ảnh tạo ra và thực hiện các tác phẩm nghệ thuật bằng cách điêu khắc, vẽ, tạo phim hoạt hình, khắc hoặc sử dụng các kỹ thuật khác.', array['- Hình thành và phát triển ý tưởng, thiết kế phong cách cho tranh, bản vẽ và điêu khắc;', '- Sắp xếp các đối tượng, mô hình định vị, chọn cảnh quan và các hình thức trực quan khác theo đối tượng được chọn;', '- Lựa chọn phương tiện nghệ thuật, phương pháp và tài liệu;', '- Tạo ra các chiều đại diện hoặc trừu tượng bằng cách định hình, chạm khắc và kết hợp các vật liệu như gỗ, đá, đất sét, kim loại, băng hoặc giấy;', '- Tạo ra các bức vẽ và tranh vẽ đại diện hoặc trừu tượng bằng bút chì, mực, phấn, sơn dầu, màu nước hoặc thông qua việc áp dụng các kỹ thuật khác;', '- Tạo bản vẽ hoặc khắc chúng trên kim loại, gỗ hoặc các vật liệu khác;', '- Tạo phim hoạt hình để mô tả người và sự kiện, thường là tranh biếm họa;', '- Khôi phục các bức tranh bị hư hỏng, bẩn, phai màu và các đối tượng nghệ thuật khác.']::text[], array['- Họa sĩ biếm họa', '- Nghệ nhân gốm', '- Họa sĩ minh họa', '- Nghệ sĩ phục hồi hình ảnh', '- Họa sĩ vẽ chân dung', '- Nhà điêu khắc']::text[], array['- Nhà thiết kế công nghiệp - 2163', '- Thiết kế đồ họa - 2166', '- Giáo viên vẽ tranh (dạy tư nhân) - 2355', '- Thợ làm gốm - 7314', '- Thợ trang trí - 7316']::text[], 'Một số nghề trong nhóm này yêu cầu kỹ năng ở cấp độ kỹ năng thứ năm như: Mộc mỹ nghệ, kỹ thuật sơn mài và khảm trai.', '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 631) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2652', 'Nhạc công, ca sĩ và nhạc sĩ viết, sắp xếp, thực hiện và biểu diễn các tác phẩm âm nhạc.', array['- Tạo ra các cấu trúc du dương, hài hòa và nhịp nhàng để thể hiện ý tưởng và cảm xúc dưới hình thức âm nhạc;', '- Chuyển các ý tưởng và khái niệm thành các dấu hiệu và biểu tượng âm nhạc tiêu chuẩn để tái tạo và biểu diễn;', '- Điều chỉnh hoặc sắp xếp âm nhạc cho các nhóm nhạc cụ hoặc nhạc cụ cụ thể;', '- Tiến hành các nhóm nhạc cụ hoặc thanh nhạc;', '- Chọn âm nhạc cho buổi biểu diễn và giao các phần nhạc cụ cho các nhạc sĩ;', '- Chơi một hoặc nhiều nhạc cụ với tư cách là nghệ sĩ độc tấu hoặc là thành viên của một dàn nhạc hoặc một nhóm nhạc;', '- Hát như một nghệ sĩ độc tấu hoặc là thành viên của một nhóm thanh nhạc hoặc ban nhạc khác;', '- Luyện tập để duy trì hiệu suất cao.']::text[], array['- Trưởng ban nhạc', '- Nhạc sĩ', '- Nhạc công', '- Nhạc trưởng', '- Nhạc sĩ câu lạc bộ đêm', '- Ca sĩ câu lạc bộ đêm', '- Người hòa âm', '- Ca sĩ', '- Nhạc sĩ đường phố', '- Ca sĩ đường phố']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 656) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2653', 'Vũ công và biên đạo múa tạo ra hoặc thực hiện các điệu nhảy.', array['- Hình thành và tạo ra các điệu nhảy, thường truyền tải một câu chuyện, chủ đề, ý tưởng hoặc tâm trạng, bằng một mô hình các bước, chuyển động và cử chỉ;', '- Biểu diễn các điệu nhảy với tư cách là nghệ sĩ độc tấu, với đối tác hoặc là thành viên của một nhóm nhảy trước khán giả trực tiếp hoặc cho phim, truyền hình hoặc phương tiện trực quan khác;', '- Đào tạo, tập thể dục và tham dự các lớp khiêu vũ để duy trì mức độ khả năng và thể lực cần thiết;', '- Chỉ đạo và tham gia các buổi tập để thực hành các bước nhảy và kỹ thuật cần thiết cho buổi biểu diễn;', '- Thử vai cho các vai nhảy hoặc cho thành viên trong các công ty khiêu vũ;', '- Điều phối âm nhạc sản xuất với các giám đốc âm nhạc.']::text[], array['- Biên đạo múa', '- Vũ công ba lê', '- Vũ công câu lạc bộ đêm', '- Vũ công đường phố']::text[], array['- Giáo viên dạy nhảy - 2355']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 678) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2654', 'Đạo diễn, nhà sản xuất phim, sân khấu và các nghề liên quan giám sát và kiểm soát các khía cạnh kỹ thuật và nghệ thuật của phim ảnh, sản xuất truyền hình hoặc đài phát thanh và chương trình sân khấu.', array['- Chọn nhà văn, nghiên cứu kịch bản để xác định diễn giải nghệ thuật và hướng dẫn diễn viên về phương pháp diễn xuất;', '- Chỉ đạo tất cả các khía cạnh của các tác phẩm ấn tượng trên sân khấu, truyền hình, đài phát thanh hoặc trong các hình ảnh chuyển động bao gồm cả sự lựa chọn của các diễn viên và các quyết định cuối cùng liên quan đến trang phục, thiết kế, hiệu ứng âm thanh hoặc ánh sáng;', '- Lập kế hoạch, tổ chức và kiểm soát các giai đoạn khác nhau và lên lịch trình liên quan đến việc sản xuất các bài thuyết trình, hình ảnh chuyển động, chương trình truyền hình và chương trình phát thanh;', '- Tham gia và giám sát tất cả các nhân viên kỹ thuật và xác định việc xử lý, phạm vi và lịch trình sản xuất;', '- Duy trì tài liệu lưu trữ sản xuất và thương lượng tiền bản quyền;', '- Tạo, lập kế hoạch hoặc viết kịch bản để ghi, quay video và chỉnh sửa chương trình;', '- Giám sát việc định vị cảnh quan, đạo cụ, thiết bị chiếu sáng và âm thanh.']::text[], array['- Giám đốc tài liệu', '- Biên tập phim', '- Giám đốc hình ảnh chuyển động', '- Giám đốc chụp ảnh', '- Đạo diễn sân khấu', '- Giám đốc kỹ thuật', '- Giám đốc truyền hình hoặc đài phát thanh kỹ thuật', '- Nhà sản xuất sân khấu']::text[], array['- Nhà sản xuất tin tức trên tivi/đài phát thanh - 2642', '- Kỹ thuật viên phát sóng - 3521', '- Kỹ thuật viên ánh sáng - 3521', '- Kỹ thuật viên âm thanh - 3521', '- Kỹ thuật viên video - 3521', '- Người quản lý sân khấu - 3439']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 694) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2655', 'Diễn viên đóng vai trong phim điện ảnh, truyền hình, chương trình biểu diễn trên sân khấu, sản xuất truyền hình hoặc truyền thanh.', array['- Học lời nhắc và đóng các phần trong các vở kịch trên sân khấu, quảng cáo, truyền hình, đài phát thanh hoặc trong các hình ảnh chuyển động;', '- Đóng các nhân vật được tạo bởi một nhà viết kịch hoặc tác giả và truyền đạt điều này đến khán giả;', '- Kể chuyện hoặc đọc các tác phẩm văn học lớn nổi tiếng để giáo dục hoặc giải trí người nghe;', '- Tham dự các buổi thử giọng và thực hiện các cuộc gọi thử vai;', '- Chuẩn bị cho buổi biểu diễn thông qua các buổi diễn tập dưới sự hướng dẫn của giám đốc sản xuất;', '- Đọc các kịch bản và nghiên cứu để có được sự hiểu biết về các phần, chủ đề và đặc điểm;', '- Các phần diễn xuất và vai diễn được phát triển trong các buổi diễn tập trong các tác phẩm điện ảnh, truyền hình, đài phát thanh và sân khấu.']::text[], array['- Diễn viên', '- Nghệ sĩ kịch câm', '- Người kể chuyện']::text[], array['- Nghệ sĩ đóng thế - 3439', '- Người đóng vai phụ - 3439']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 720) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2656', 'Phát thanh viên trên đài, truyền hình và các phương tiện truyền thông đại chúng khác đọc bản tin, thực hiện các cuộc phỏng vấn và đưa ra các thông báo hoặc giới thiệu khác trên đài phát thanh, truyền hình và tại các nhà hát, các cơ sở hoặc phương tiện truyền thông khác.', array['- Đọc bản tin và đưa ra các thông báo khác trên đài phát thanh hoặc truyền hình;', '- Giới thiệu các nghệ sĩ biểu diễn hoặc người được phỏng vấn và đưa ra các thông báo liên quan trên đài phát thanh, truyền hình hoặc tại các nhà hát, câu lạc bộ đêm và các cơ sở khác;', '- Phỏng vấn những người ở nơi công cộng, đặc biệt là trên đài phát thanh và truyền hình;', '- Nghiên cứu thông tin cơ bản để chuẩn bị cho các chương trình hoặc phỏng vấn;', '- Bình luận về âm nhạc và các vấn đề khác chẳng hạn như dự báo thời tiết hoặc giao thông.']::text[], array['- Người dẫn chương trình', '- Phát thanh viên truyền hình', '- Người kết nối tin tức', '- Phát thanh viên thể thao', '- Người dẫn dắt chương trình truyền hình', '- Phóng viên giao thông', '- Phóng viên thời tiết']::text[], array['- Nhà báo - 2642']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 737) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('2659', 'Nghệ sĩ sáng tạo và trình diễn liên quan khác chưa được phân vào đâu gồm những chú hề, ảo thuật gia, nhào lộn và các nghệ sĩ biểu diễn khác.', array['- Thực hiện những trò hề thú vị và kể những câu chuyện hài hước;', '- Thực hiện các thủ thuật ảo giác và ánh sáng của bàn tay và chiến công của thôi miên;', '- Thực hiện các màn nhào lộn khó khăn và ngoạn mục và các kỳ công thể dục hoặc tung hứng;', '- Đào tạo và biểu diễn với động vật.']::text[], array['- Diễn viên xiếc', '- Nghệ sĩ nhào lộn trên không', '- Chú hề', '- Nhà thôi miên', '- Pháp sư', '- Người điều khiển con rối', '- Diễn viên hài độc lập', '- Nghệ sỹ nói tiếng bụng']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 755) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3111', 'Kỹ thuật viên khoa học hóa học và vật lý thực hiện các nhiệm vụ kỹ thuật để hỗ trợ nghiên cứu hóa học, vật lý, địa chất, địa vật lý, khí tượng, thiên văn học và trong việc phát triển các ứng dụng công nghiệp, y tế, quân sự và các ứng dụng thực tế khác của kết quả nghiên cứu.', array['- Thu thập mẫu, chuẩn bị vật liệu và thiết bị cho các thí nghiệm, thử nghiệm và phân tích;', '- Thực hiện các thử nghiệm trong phòng thí nghiệm thông thường và thực hiện một loạt các chức năng hỗ trợ kỹ thuật để hỗ trợ các nhà khoa học hóa học và vật lý trong nghiên cứu, phát triển, phân tích và thử nghiệm;', '- Kiểm soát chất lượng và số lượng vật tư phòng thí nghiệm bằng cách kiểm tra mẫu và giám sát việc sử dụng và chuẩn bị dự toán chi tiết về số lượng, chi phí vật liệu và nhân công cần thiết cho các dự án, theo các thông số kỹ thuật được đưa ra;', '- Thiết lập, vận hành và bảo trì các thiết bị và dụng cụ phòng thí nghiệm, giám sát thí nghiệm, quan sát, tính toán và ghi lại kết quả;', '- Chuẩn bị nguyên liệu cho thí nghiệm như đông lạnh, cắt mẫu và trộn hóa chất;', '- Thu thập và thử nghiệm các mẫu đất và nước, ghi lại các quan sát và phân tích dữ liệu để hỗ trợ các nhà địa chất hoặc địa vật lý.']::text[], array['- Kỹ thuật viên hóa học', '- Kỹ thuật viên địa chất', '- Kỹ thuật viên khí tượng', '- Kỹ thuật viên vật lý']::text[], array['- Kỹ thuật viên kỹ thuật hóa học - 3116', '- Kỹ thuật viên quy trình hóa học - 3133', '- Kỹ thuật viên khoa học sự sống - 3141']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 780) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3112', 'Kỹ thuật viên kỹ thuật xây dựng thực hiện các nhiệm vụ kỹ thuật trong nghiên cứu kỹ thuật dân dụng và trong thiết kế, xây dựng, vận hành, bảo trì và sửa chữa các tòa nhà và các cấu trúc khác như hệ thống cấp nước và xử lý nước thải, cầu, đường, đập và sân bay.', array['- Thực hiện hoặc hỗ trợ kiểm tra thực địa, thí nghiệm đất và vật liệu xây dựng;', '- Cung cấp hỗ trợ kỹ thuật liên quan đến việc xây dựng các tòa nhà và các cấu trúc khác và với các cuộc khảo sát hoặc chuẩn bị các báo cáo khảo sát;', '- Đảm bảo tuân thủ các thông số kỹ thuật thiết kế, luật pháp và quy định có liên quan; duy trì các tiêu chuẩn mong muốn của vật liệu và công việc;', '- Áp dụng kiến ​​thức kỹ thuật về các nguyên tắc và thực hành xây dựng và kỹ thuật dân dụng để xác định và giải quyết các vấn đề phát sinh;', '- Hỗ trợ chuẩn bị các ước tính chi tiết về số lượng, chi phí vật liệu và nhân công cần thiết cho các dự án theo các thông số kỹ thuật được đưa ra;', '- Tổ chức bảo trì và sửa chữa;', '- Kiểm tra các tòa nhà và công trình trong và sau khi xây dựng để đảm bảo rằng chúng tuân thủ luật xây dựng, phân loại, phân vùng và an toàn cũng như các kế hoạch, thông số kỹ thuật và tiêu chuẩn được phê duyệt, cũng như các quy tắc khác liên quan đến chất lượng và an toàn của các tòa nhà;', '- Kiểm tra nhà máy công nghiệp, khách sạn, rạp chiếu phim, các tòa nhà và công trình khác để phát hiện các nguy cơ hỏa hoạn và tư vấn về cách loại bỏ chúng;', '- Tư vấn lắp đặt thiết bị báo cháy, hệ thống phun nước và sử dụng vật liệu trong xây dựng các tòa nhà và phương tiện giao thông để giảm nguy cơ hỏa hoạn, mức độ thiệt hại và nguy hiểm nếu hỏa hoạn xảy ra.']::text[], array['- Thanh tra xây dựng', '- Khảo sát xây dựng', '- Kỹ thuật viên dân dụng', '- Thư ký công trình', '- Thanh tra phòng cháy', '- Chuyên viên phòng cháy chữa cháy', '- Kỹ thuật viên địa kỹ thuật', '- Kỹ thuật viên khảo sát']::text[], array['- Nhà chuyên môn về khảo sát số lượng - 2149', '- Giám sát hàng hải - 3115', '- Điều tra viên cứu hỏa - 3119']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 798) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3113', 'Kỹ thuật viên kỹ thuật điện thực hiện các nhiệm vụ kỹ thuật để hỗ trợ nghiên cứu kỹ thuật điện và thiết kế, sản xuất, lắp ráp, xây dựng, vận hành, bảo trì và sửa chữa thiết bị điện, cơ sở và hệ thống phân phối.', array['- Cung cấp hỗ trợ kỹ thuật trong nghiên cứu và phát triển các thiết bị và phương tiện điện hoặc thử nghiệm các nguyên mẫu;', '- Thiết kế và chuẩn bị kế hoạch chi tiết lắp đặt điện và mạch điện theo các thông số kỹ thuật đã cho;', '- Chuẩn bị các ước tính chi tiết về số lượng, chi phí vật liệu và nhân công cần thiết cho sản xuất và lắp đặt theo các thông số kỹ thuật được đưa ra;', '- Giám sát các khía cạnh kỹ thuật của sản xuất, lắp đặt, sử dụng, bảo trì, sửa chữa hệ thống điện và thiết bị để đảm bảo hiệu suất thỏa đáng và tuân thủ các thông số kỹ thuật và quy định;', '- Lập kế hoạch phương án lắp đặt, kiểm tra các cài đặt đã hoàn thành về an toàn và kiểm soát hoặc thực hiện vận hành ban đầu các thiết bị hoặc hệ thống điện mới;', '- Lắp ráp, lắp đặt, thử nghiệm, hiệu chỉnh, sửa đổi và sửa chữa các thiết bị điện và lắp đặt để phù hợp với các quy định và yêu cầu an toàn.']::text[], array['- Kỹ thuật viên kỹ thuật điện', '- Kỹ thuật viên kỹ thuật truyền tải điện']::text[], array['- Kỹ thuật viên kỹ thuật điện tử - 3114', '- Nhà điều hành nhà máy sản xuất điện - 3131', '- Cơ điện - 7412']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 823) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3114', 'Kỹ thuật viên kỹ thuật điện tử thực hiện các nhiệm vụ kỹ thuật để hỗ trợ nghiên cứu điện tử và thiết kế, sản xuất, lắp ráp, xây dựng, vận hành, bảo trì và sửa chữa thiết bị điện tử.', array['- Cung cấp hỗ trợ kỹ thuật trong nghiên cứu và phát triển thiết bị điện tử hoặc thử nghiệm các nguyên mẫu;', '- Thiết kế và chuẩn bị đồ án của mạch điện tử theo các thông số kỹ thuật được đưa ra;', '- Chuẩn bị các ước tính chi tiết về số lượng, chi phí vật liệu và nhân công cần thiết cho việc sản xuất và lắp đặt thiết bị điện tử theo các thông số kỹ thuật được đưa ra;', '- Giám sát các khía cạnh kỹ thuật của sản xuất, sử dụng, bảo trì và sửa chữa thiết bị điện tử để đảm bảo hiệu suất thỏa đáng và đảm bảo tuân thủ các thông số kỹ thuật và quy định;', '- Hỗ trợ thiết kế, phát triển, lắp đặt, vận hành và bảo trì các hệ thống điện tử;', '- Lập kế hoạch phương án cài đặt, kiểm tra các cài đặt đã hoàn thành về an toàn và kiểm soát hoặc thực hiện vận hành ban đầu các thiết bị hoặc hệ thống điện tử mới;', '- Tiến hành các thử nghiệm hệ thống điện tử, thu thập, phân tích dữ liệu và lắp ráp mạch để hỗ trợ các kỹ sư điện tử.']::text[], '{}'::text[], array['- Kỹ thuật viên kỹ thuật điện - 3113', '- Kỹ thuật viên kỹ thuật viễn thông - 3522', '- Thợ cơ điện tử - 7421', '- Nhân viên lắp ráp thiết bị điện tử - 8212']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 839) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3115', 'Kỹ thuật viên kỹ thuật cơ khí thực hiện các nhiệm vụ kỹ thuật để hỗ trợ nghiên cứu kỹ thuật cơ khí và thiết kế, sản xuất, lắp ráp, xây dựng, vận hành, bảo trì và sửa chữa máy móc, linh kiện và thiết bị cơ khí.', array['- Cung cấp hỗ trợ kỹ thuật trong nghiên cứu và phát triển máy móc và lắp đặt cơ khí, cơ sở vật chất và linh kiện hoặc các nguyên mẫu thử nghiệm;', '- Thiết kế và chuẩn bị bố trí máy móc và lắp đặt cơ khí, cơ sở vật chất và linh kiện theo các thông số kỹ thuật được đưa ra;', '- Chuẩn bị các ước tính chi tiết về số lượng, chi phí vật liệu và nhân công cần thiết cho sản xuất và lắp đặt theo các thông số kỹ thuật được đưa ra;', '- Giám sát các khía cạnh kỹ thuật của sản xuất, sử dụng, bảo trì, sửa chữa máy móc và lắp đặt cơ khí, cơ sở vật chất và linh kiện để đảm bảo hiệu suất thỏa đáng và tuân thủ các thông số kỹ thuật và quy định;', '- Xây dựng và giám sát việc thực hiện các tiêu chuẩn và quy trình an toàn cho công tác khảo sát biển liên quan đến tàu, vỏ tàu, thiết bị và hàng hóa;', '- Lắp ráp và lắp đặt các bộ phận cơ khí mới, sửa chữa linh kiện, máy công cụ, điều khiển và hệ thống điện thủy lực;', '- Tiến hành các thử nghiệm hệ thống cơ khí, thu thập và phân tích dữ liệu, lắp ráp và lắp đặt các bộ phận cơ khí; hỗ trợ các kỹ sư cơ khí;', '- Đảm bảo rằng các thiết kế kỹ thuật cơ khí và công việc đã hoàn thành nằm trong các thông số kỹ thuật, quy định và điều khoản hợp đồng.']::text[], array['- Kỹ thuật viên kỹ thuật hàng không', '- Kỹ thuật viên kỹ thuật hàng hải', '- Khảo sát biển', '- Dự toán cơ khí', '- Kỹ thuật viên cơ khí']::text[], array['- Thợ cơ khí máy móc công nghiệp - 7233', '- Thợ lắp ráp máy móc cơ khí - 8201']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 854) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3116', 'Kỹ thuật viên kỹ thuật hóa học thực hiện các nhiệm vụ kỹ thuật để hỗ trợ nghiên cứu kỹ thuật hóa học và thiết kế, sản xuất, xây dựng, vận hành, bảo trì và sửa chữa nhà máy hóa chất.', array['- Hỗ trợ nghiên cứu và phát triển các quy trình hóa học công nghiệp, nhà máy và thiết bị hoặc thử nghiệm các nguyên mẫu;', '- Thiết kế và chuẩn bị bố trí các nhà máy hóa chất theo các thông số kỹ thuật được đưa ra;', '- Chuẩn bị các ước tính chi tiết về số lượng, chi phí vật liệu và nhân công cần thiết cho sản xuất và lắp đặt theo các thông số kỹ thuật được đưa ra;', '- Giám sát các khía cạnh kỹ thuật của việc xây dựng, lắp đặt, vận hành, bảo trì và sửa chữa các nhà máy hóa chất để đảm bảo thực hiện thỏa đáng và tuân thủ các thông số kỹ thuật và quy định;', '- Tiến hành các thử nghiệm trong phòng thí nghiệm hóa học và vật lý để hỗ trợ các nhà khoa học và kỹ sư thực hiện các phân tích định tính và định lượng về chất rắn, chất lỏng và vật liệu khí.']::text[], array['- Dự toán kỹ thuật hóa học', '- Kỹ thuật viên kỹ thuật hóa học']::text[], array['- Kỹ thuật viên hóa học - 3111', '- Kỹ thuật viên quy trình hóa học - 3133']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 874) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3117', 'Kỹ thuật viên khai thác mỏ và luyện kim thực hiện các nhiệm vụ kỹ thuật để hỗ trợ nghiên cứu và thí nghiệm liên quan đến luyện kim, cải tiến phương pháp khai thác khoáng sản rắn, dầu khí và trong thiết kế, xây dựng, vận hành, bảo dưỡng và sửa chữa mỏ và lắp đặt mỏ cho các hệ thống vận chuyển và lưu trữ dầu và khí tự nhiên và để khai thác kim loại từ quặng.', array['- Cung cấp hỗ trợ kỹ thuật để hỗ trợ nghiên cứu và phát triển các quy trình để xác định tính chất của kim loại và hợp kim mới;', '- Cung cấp hỗ trợ kỹ thuật trong các khảo sát địa chất, địa hình và trong thiết kế; bố trí các hệ thống khai thác dầu mỏ, khí tự nhiên, khoáng sản và các nhà máy chế biến và tinh chế khoáng sản và kim loại;', '- Chuẩn bị dự toán chi tiết về số lượng, chi phí vật liệu và nhân công cần thiết cho các dự án thăm dò, khai thác, chế biến và vận chuyển khí khoáng, dầu mỏ và khí tự nhiên;', '- Giám sát các khía cạnh kỹ thuật, quy định và an toàn của việc xây dựng, lắp đặt, vận hành, bảo trì và sửa chữa quặng khoáng sản, thăm dò dầu khí, khai thác, vận chuyển, lưu trữ và nhà máy chế biến khoáng sản;', '- Giúp lập kế hoạch và thiết kế các mỏ, trục mỏ, đường hầm và các cơ sở sơ cứu ngầm;', '- Thu thập và chuẩn bị các mẫu đá, khoáng sản và kim loại; thực hiện các thử nghiệm trong phòng thí nghiệm để xác định tính chất; phân tích và báo cáo kết quả thử nghiệm; bảo trì thiết bị thử nghiệm;', '- Sử dụng kính hiển vi, máy chiếu xạ điện từ, máy quang phổ, máy đo mật độ và máy kiểm tra độ căng;', '- Hỗ trợ các nhà khoa học sử dụng các dụng cụ đo điện, âm thanh hoặc hạt nhân trong cả hoạt động sản xuất và phòng thí nghiệm để thu thập dữ liệu các nguồn quặng kim loại, khí hoặc dầu mỏ tiềm năng.']::text[], array['- Kỹ thuật viên luyện kim', 'Thanh tra mỏ', '- Kỹ thuật viên khai thác mỏ']::text[], array['- Kỹ thuật viên địa chất - 3111', '- Thợ mỏ - 8111', '- Thợ vận hành nhà máy khai thác - 8111', '- Thợ khai thác mỏ đá - 8111']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 888) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3118', 'Kỹ thuật viên phác thảo kỹ thuật chuẩn bị các bản vẽ kỹ thuật, bản đồ và hình minh họa từ bản phác thảo và dữ liệu khác, và sao chép các bản vẽ và tranh vẽ cuối cùng lên các bản in.', array['- Chuẩn bị và sửa đổi các bản vẽ từ các bản phác thảo và thông số kỹ thuật được chuẩn bị bởi các kỹ sư và nhà thiết kế để sản xuất, lắp đặt máy móc thiết bị hoặc để xây dựng, sửa đổi, bảo trì và sửa chữa các tòa nhà, đập, cầu, đường, kiến ​​trúc khác và dự án xây dựng dân dụng;', '- Vận hành thiết kế hỗ trợ máy tính và thiết bị thoát nước để sửa đổi và tạo các bản trình bày cứng và kỹ thuật số của bản vẽ;', '- Bảng số hóa vận hành hoặc thiết bị tương tự để chuyển biểu diễn bản sao cứng của bản vẽ, bản đồ và các đường cong khác sang dạng kỹ thuật số;', '- Chuẩn bị và sửa đổi các minh họa cho các công trình tham khảo, tài liệu quảng cáo và hướng dẫn kỹ thuật liên quan đến lắp ráp, lắp đặt, vận hành, bảo trì, sửa chữa máy móc, các thiết bị và hàng hóa khác;', '- Sao chép các bản vẽ và tranh vẽ lên các tấm đá hoặc kim loại để in;', '- Chuẩn bị sơ đồ nối dây, sơ đồ lắp ráp bảng mạch và bản vẽ bố trí được sử dụng để sản xuất, lắp đặt và sửa chữa thiết bị điện trong các nhà máy, nhà máy điện và các tòa nhà;', '- Tạo sơ đồ làm việc chi tiết của máy móc và thiết bị cơ khí bao gồm kích thước, phương pháp buộc và thông tin kỹ thuật khác;', '- Sắp xếp các bản vẽ hoàn thành sẽ được sao chép để sử dụng làm bản vẽ làm việc.']::text[], array['- Chuyên viên thiết kế', '- Chuyên viên đồ họa kỹ thuật']::text[], array['- Nhà bản đồ học - 2165', '- Nhà khảo sát hiện trường - 2165']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 908) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3119', 'Kỹ thuật viên khoa học vật lý và kỹ thuật chưa được phân vào đâu bao gồm những người hỗ trợ các nhà khoa học và kỹ sư tham gia xây dựng các quy trình hoặc tiến hành nghiên cứu về an toàn, y sinh, môi trường, công nghiệp và kỹ thuật sản xuất.', array['- Thu thập dữ liệu và cung cấp hỗ trợ kỹ thuật về sử dụng nhân sự, vật liệu và thiết bị hiệu quả, an toàn và kinh tế; phương pháp làm việc và trình tự các hoạt động và giám sát việc thực hiện của họ; và bố trí hiệu quả của nhà máy hoặc cơ sở;', '- Hỗ trợ xác định các mối nguy hiểm tiềm ẩn và giới thiệu các quy trình, thiết bị an toàn;', '- Sửa đổi và thử nghiệm các thiết bị được sử dụng trong phòng ngừa, kiểm soát, khắc phục ô nhiễm môi trường, khắc phục hiện trường và cải tạo đất;', '- Hỗ trợ phát triển các thiết bị xử lý ô nhiễm môi trường dưới sự chỉ đạo của kỹ sư;', '- Hỗ trợ các kỹ sư thử nghiệm và thiết kế thiết bị robot.']::text[], array['- Kỹ thuật viên kỹ thuật (sản xuất)', '- Điều tra viên cứu hỏa', '- Kỹ thuật viên khoa học pháp y', '- Kỹ thuật viên khảo sát số lượng', '- Kỹ thuật viên robot', '- Kỹ thuật viên nghiên cứu thời gian và chuyển động']::text[], array['- Kỹ sư sản xuất - 2141', '- Nhà chuyên môn về khảo sát số lượng - 2149', '- Kỹ thuật viên kỹ thuật hàng không - 3115']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 925) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3121', 'Giám sát viên khai thác mỏ giám sát các hoạt động khai thác và khai thác đá; trực tiếp giám sát và điều phối các hoạt động của các thợ mỏ làm việc trong các mỏ và mỏ khai thác dưới mặt đất và trên mặt đất.', array['- Giám sát và điều phối các hoạt động của công nhân khai thác khoáng sản, các trầm tích tự nhiên khác từ trái đất và vận hành vận tải ngầm hoặc thiết bị nặng trong các mỏ và mỏ đá trên mặt nước;', '- Thiết lập các phương pháp để đáp ứng lịch trình làm việc và đề xuất các biện pháp cho các nhà quản lý khai thác để cải thiện năng suất;', '- Làm việc với nhân viên quản lý và kỹ thuật, các bộ phận và nhà thầu khác để giải quyết các vấn đề vận hành và điều phối các hoạt động;', '- Cung cấp các báo cáo và thông tin khác cho các nhà quản lý về tất cả các khía cạnh của hoạt động khai thác hoặc khai thác đá;', '- Xác định nhân sự và nhu cầu vật chất cho mỏ hoặc mỏ đá.']::text[], array['- Phó mỏ', '- Giám sát viên khai thác mỏ', '- Người quản lí khai thác mỏ', '- Người giám sát mỏ quặng']::text[], array['- Quản lý mỏ - 1722', '- Thanh tra mỏ - 3117', '- Thợ mỏ - 8111', '- Thợ khai thác mỏ đá - 8111']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 951) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3122', 'Giám sát viên sản xuất phối hợp và giám sát các hoạt động của kỹ thuật viên điều khiển quá trình, vận hành máy, lắp ráp và lao động sản xuất khác.', array['- Điều phối và giám sát các hoạt động của kỹ thuật viên điều khiển quá trình, người vận hành máy, lắp ráp và lao động sản xuất khác;', '- Tổ chức và lập kế hoạch công việc hàng ngày liên quan đến kế hoạch, kinh tế, nhân viên và môi trường;', '- Chuẩn bị dự toán, hồ sơ và báo cáo;', '- Xác định sự thiếu hụt nhân viên hoặc các thành phần;', '- Đảm bảo an toàn cho người lao động;', '- Hướng dẫn và đào tạo nhân viên mới.']::text[], array['- Điều phối viên khu vực (sản xuất)', '- Giám sát hội', '- Giám sát viên hoàn thiện', '- Giám sát sản xuất']::text[], array['- Quản lý sản xuất - 1722']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 969) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3123', 'Giám sát viên xây dựng phối hợp, giám sát và sắp xếp các hoạt động của công nhân tham gia xây dựng và sửa chữa các tòa nhà và công trình.', array['- Đọc thông số kỹ thuật để xác định các yêu cầu xây dựng và quy trình lập kế hoạch;', '- Tổ chức và điều phối nguồn lực vật chất và nhân lực cần thiết để hoàn thành công việc;', '- Kiểm tra tiến độ công việc;', '- Kiểm tra thiết bị và công trường để đảm bảo đáp ứng các yêu cầu về sức khỏe và an toàn;', '- Giám sát các công trường xây dựng và điều phối công việc với các dự án xây dựng khác;', '- Giám sát các hoạt động xây dựng của công nhân, người lao động và công nhân xây dựng khác.']::text[], array['- Giám sát thi công xây dựng', '- Quản lý trang web (xây dựng)']::text[], array['- Quản lý dự án xây dựng (thuộc Tập đoàn, Tổng công ty, trường đại học lớn và tương đương) - 1723', '- Quản lý dự án xây dựng (nhỏ) - 1743', '- Người thầu dự án xây dựng (thuộc Tập đoàn, Tổng công ty, trường đại học lớn và tương đương) - 1723', '- Người thầu dự án xây dựng (nhỏ) - 1743', '- Thư ký công trình - 3112']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 985) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3131', 'Người vận hành trạm hoặc nhà máy phát điện vận hành, giám sát và bảo trì các tổng đài và thiết bị liên quan trong các trung tâm điều khiển điện điều khiển việc sản xuất và phân phối điện hoặc năng lượng khác trong các mạng truyền dẫn. Các thiết bị hoạt động bao gồm lò phản ứng, tua bin, máy phát điện và các thiết bị phụ trợ khác trong các trạm phát điện.', array['- Vận hành, giám sát và kiểm tra các loại nhà máy điện tạo năng lượng;', '- Vận hành và điều khiển các hệ thống và thiết bị sản xuất điện bao gồm nồi hơi, tua bin, máy phát điện, bình ngưng và lò phản ứng trong các nhà máy thủy điện, nhiệt, than, dầu, khí tự nhiên và hạt nhân để sản xuất và phân phối điện;', '- Kiểm soát khởi động và tắt thiết bị của nhà máy điện, kiểm soát hoạt động chuyển mạch, điều chỉnh mực nước và liên lạc với người vận hành hệ thống để điều chỉnh và điều phối tải truyền, tần số và điện áp đường dây;', '- Lấy số đọc từ biểu đồ, mét và đồng hồ đo theo các khoảng thời gian đã thiết lập, xử lý sự cố và thực hiện hành động khắc phục khi cần thiết;', '- Hoàn thành và duy trì hồ sơ trạm, nhật ký, báo cáo và liên lạc với nhân viên nhà máy khác để đánh giá tình trạng vận hành thiết bị;', '- Làm sạch và bảo trì các thiết bị như máy phát điện, nồi hơi, tua bin, máy bơm và máy nén để tránh hỏng hóc hoặc hư hỏng thiết bị.']::text[], array['- Người điều hành kiểm soát phân phối', '- Người điều hành nhà máy điện', '- Người điều hành trạm phát điện', '- Người điều hành nhà máy thủy điện', '- Người điều hành nhà máy điện hạt nhân', '- Người vận hành hệ thống điện', '- Người điều hành nhà máy điện mặt trời']::text[], array['- Thợ vận hành động cơ hơi nước và nồi hơi - 8182']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1010) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3132', 'Người vận hành lò đốt rác và nhà máy xử lý nước giám sát và vận hành các hệ thống điều khiển bằng máy tính và các thiết bị liên quan trong các nhà máy xử lý chất thải rắn và lỏng để điều chỉnh việc xử lý và xử lý nước thải, chất thải và trong các nhà máy lọc và xử lý nước để điều chỉnh và phân phối nước.', array['- Vận hành và giám sát các hệ thống điều khiển vi tính, máy móc và thiết bị liên quan trong xử lý nước thải và nhà máy xử lý chất thải lỏng để điều tiết dòng chảy, xử lý nước thải và chất thải và trong các nhà máy lọc và xử lý nước để điều chỉnh và phân phối nước cho con người và sau đó thải vào hệ thống nước tự nhiên;', '- Kiểm soát hoạt động của lò đốt nhiều lò sưởi và các thiết bị liên quan để đốt bùn và chất thải rắn trong các nhà máy xử lý chất thải;', '- Kiểm tra thiết bị và giám sát các điều kiện vận hành, đồng hồ đo, bộ lọc, clo và máy đo trong phòng điều khiển trung tâm để xác định các yêu cầu tải, để xác minh rằng dòng chảy, áp suất và nhiệt độ nằm trong đặc điểm kỹ thuật và để phát hiện sự cố;', '- Giám sát và điều chỉnh các thiết bị phụ trợ như khí thải, máy lọc và thiết bị thu hồi nhiệt của lò đốt;', '- Thu thập và thử nghiệm các mẫu nước và nước thải cho hàm lượng hóa chất và vi khuẩn, sử dụng thiết bị thử nghiệm và tiêu chuẩn phân tích màu;', '- Phân tích kết quả thử nghiệm để điều chỉnh các thiết bị và hệ thống của nhà máy để khử trùng và khử mùi nước và các chất lỏng khác;', '- Thực hiện kiểm tra an ninh và an toàn trong nhà máy và trên mặt đất;', '- Hoàn thành và duy trì nhật ký và báo cáo của nhà máy.']::text[], array['- Người vận hành lò đốt rác', '- Người điều hành xử lý chất thải lỏng', '- Người điều hành trạm bơm', '- Người vận hành nhà máy xử lý nước thải', '- Người vận hành xử lý nước thải']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1029) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3133', 'Kiểm soát viên nhà máy xử lý hóa chất vận hành và giám sát các nhà máy hóa chất và máy móc điều khiển quá trình đa chức năng có liên quan; điều chỉnh và bảo trì các đơn vị xử lý và thiết bị chưng cất, lọc, tách, nhiệt hoặc tinh chế hóa chất.', array['- Vận hành bảng điều khiển điện tử hoặc máy tính từ phòng điều khiển trung tâm để giám sát và tối ưu hóa các quy trình vật lý và hóa học cho một số đơn vị xử lý;', '- Điều chỉnh thiết bị, van, máy bơm, điều khiển và thiết bị xử lý;', '- Kiểm soát việc chuẩn bị, đo lường, cung cấp nguyên liệu thô và các tác nhân chế biến như chất xúc tác và phương tiện lọc vào nhà máy;', '- Kiểm soát quá trình khởi động và tắt máy; xử lý sự cố và giám sát bên ngoài thiết bị xử lý;', '- Xác minh thiết bị cho các sự cố, thực hiện các thử nghiệm vận hành thường xuyên và sắp xếp để bảo trì;', '- Phân tích các sản phẩm mẫu, thực hiện các thử nghiệm, ghi dữ liệu và nhật ký sản xuất.']::text[], array['- Người vận hành thiết bị lọc và tách hóa chất', '- Người vận hành cấy ghép hóa học', '- Kỹ thuật viên quy trình hóa học', '- Kỹ thuật viên vận hành hóa chất và lò phản ứng']::text[], array['- Người vận hành nhà máy lọc dầu và khí đốt tự nhiên - 3134', '- Thợ vận hành máy và thiết bị sản xuất hóa học - 8131']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1046) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3134', 'Người vận hành nhà máy lọc dầu và khí tự nhiên vận hành và điều khiển nhà máy lọc dầu hoạt động, theo dõi, điều chỉnh và duy trì thiết bị lọc, chưng cất dầu khí, sản phẩm chứa dầu, phụ phẩm dầu mỏ hoặc khí thiên nhiên.', array['- Điều khiển bảng điện tử hoặc máy tính từ phòng điều khiển trung tâm để giám sát và tối ưu hóa quá trình vật lý và hóa học cho một số đơn vị chế biến;', '- Điều chỉnh thiết bị, van, máy bơm, điều khiển và thiết bị xử lý;', '- Kiểm soát quá trình khởi động và đóng cửa, xử lý sự cố và giám sát thiết bị xử lý bên ngoài;', '- Xác minh thiết bị trục trặc, ống rò rỉ và gãy, sắp xếp để bảo trì;', '- Phân tích các sản phẩm mẫu, thực hiện kiểm tra, ghi chép số liệu và viết bản ghi sản xuất.']::text[], array['- Người điều hành máy trộn (dầu mỏ và lọc khí thiên nhiên)', '- Người điều hành nhà máy gas', '- Người điều hành nhà máy sản xuất chế phẩm từ dầu mỏ chứa Paraffin', '- Người điều hành xử lý lọc dầu', '- Kỹ thuật viên xưởng lọc dầu', '- Người điều khiển máy móc (dầu mỏ và lọc khí thiên nhiên)']::text[], array['- Kiểm soát viên nhà máy xử lý hóa chất - 3133', '- Thợ vận hành máy và thiết bị sản xuất hóa chất - 8131']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1063) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3135', 'Kiểm soát viên quy trình sản xuất kim loại vận hành và giám sát máy móc và thiết bị điều khiển quá trình đa chức năng để điều khiển quá trình xử lý lò luyện kim, nhà máy cán kim loại, nhà máy ép kim loại, xử lý nhiệt kim loại.', array['- Điều phối và giám sát hoạt động của một khía cạnh cụ thể của sản xuất gia công kim loại thông qua bảng điều khiển, thiết bị đầu cuối máy tính hoặc các hệ thống điều khiển khác thường là từ phòng điều khiển trung tâm;', '- Vận hành máy móc điều khiển quá trình trung tâm đa chức năng để nghiền, tách, lọc, nấu chảy, rang, xử lý, tinh chế hoặc xử lý kim loại khác;', '- Quan sát các bản in máy tính, màn hình và máy đo video để xác minh các điều kiện xử lý được chỉ định và để thực hiện các điều chỉnh cần thiết;', '- Điều phối và giám sát đội sản xuất như người vận hành máy móc và quy trình, trợ lý và người trợ giúp;', '- Khởi động và tắt hệ thống sản xuất trong trường hợp khẩn cấp hoặc theo yêu cầu của lịch trình;', '- Cung cấp và tổ chức đào tạo cho các thành viên của đội sản xuất;', '- Duy trì nhật ký thay đổi của sản xuất và dữ liệu khác và chuẩn bị sản xuất và các báo cáo khác.']::text[], array['- Người vận hành lò cao', '- Người điều khiển trung tâm', '- Người vận hành điều khiển máy cán']::text[], array['- Thợ rót khuôn - 8121', '- Thợ cuộn thép - 8121', '- Thợ vận hành máy hoàn thiện kim loại - 8122']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1081) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3139', 'Kỹ thuật viên kiểm soát quy trình khác chưa được phân vào đâu bao gồm những người vận hành nhiều thiết bị điều khiển quy trình trong sản xuất dây chuyền lắp ráp, sản xuất giấy và bột giấy.', '{}'::text[], array['- Người vận hành dây chuyền lắp ráp tự động', '- Người điều khiển robot công nghiệp', '- Nhà điều hành bảng điều khiển (bột giấy và giấy)', '- Nhà điều hành nhà máy bột giấy', '- Người điều khiển máy nghiền', '- Kỹ thuật viên nghiền', 'Ghi chú:', 'Những người vận hành máy móc khai thác mỏ được phân loại trong nhóm 811: Thợ vận hành máy móc, thiết bị xử lý khai khoáng.']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1099) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3141', 'Kỹ thuật viên khoa học sự sống (không kể y tế) cung cấp hỗ trợ kỹ thuật cho các chuyên gia khoa học sự sống thực hiện nghiên cứu, phân tích và thử nghiệm các sinh vật sống; phát triển, ứng dụng các sản phẩm và quy trình do nghiên cứu trong các lĩnh vực như quản lý tài nguyên thiên nhiên, bảo vệ môi trường, sinh học thực vật và động vật, vi sinh, sinh học tế bào và phân tử.', array['- Hỗ trợ thiết kế, thiết lập và tiến hành thí nghiệm;', '- Thiết lập, hiệu chuẩn, vận hành, bảo trì các dụng cụ và thiết bị thí nghiệm;', '- Thu thập và chuẩn bị mẫu thí nghiệm, dung dịch hóa chất, slide và nuôi cấy để sử dụng trong các thí nghiệm;', '- Thực hiện kiểm tra thường xuyên và xét nghiệm;', '- Giám sát các thí nghiệm để đảm bảo tuân thủ các quy trình kiểm soát chất lượng phòng thí nghiệm, hướng dẫn an toàn và sức khỏe;', '- Thực hiện các quan sát thử nghiệm; phân tích, tính toán, ghi lại và báo cáo kết quả thử nghiệm bằng các phương pháp khoa học thích hợp;', '- Bảo quản và phân loại mẫu thí nghiệm;', '- Ghi nhật ký chi tiết của công việc được thực hiện;', '- Sử dụng máy tính để phát triển mô hình và phân tích dữ liệu;', '- Sử dụng các thiết bị phức tạp và công suất cao để thực hiện công việc;', '- Tham gia nghiên cứu, phát triển và sản xuất các sản phẩm và quy trình;', '- Đặt hàng và dự trữ vật tư phòng thí nghiệm;', '- Duy trì cơ sở dữ liệu liên quan.']::text[], array['- Kỹ thuật viên vi khuẩn', '- Kỹ thuật viên hóa sinh', '- Kỹ thuật viên Herbarium', '- Kỹ thuật viên dược lý', '- Kỹ thuật viên huyết thanh học', '- Kỹ thuật nuôi cấy mô', '- Kỹ thuật viên động vật học']::text[], array['- Kỹ thuật viên khoa học pháp y - 3119', '- Kỹ thuật viên phòng thí nghiệm y tế - 3212', '- Kỹ thuật viên phòng thí nghiệm bệnh lý - 3212', '- Kỹ thuật viên dược phẩm - 3213']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1113) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3142', 'Kỹ thuật viên nông nghiệp thực hiện các thử nghiệm và thí nghiệm cung cấp hỗ trợ kỹ thuật và khoa học cho các nhà khoa học nông nghiệp, nông dân và quản lý trang trại.', array['- Chuẩn bị vật liệu và thiết bị cho các thí nghiệm, thử nghiệm và phân tích;', '- Thu thập và chuẩn bị mẫu vật như đất, tế bào thực vật hoặc động vật, mô hoặc các bộ phận của cơ quan động vật để làm thí nghiệm, xét nghiệm và phân tích;', '- Hỗ trợ và thực hiện các thí nghiệm, kiểm tra và phân tích áp dụng các phương pháp và kỹ thuật như kính hiển vi, mô học, sắc ký, điện di và quang phổ;', '- Xác định vi sinh vật gây bệnh và côn trùng, ký sinh trùng, nấm, cỏ dại gây hại cho cây trồng và vật nuôi; hỗ trợ đưa ra các phương pháp kiểm soát;', '- Phân tích sản phẩm để thiết lập và duy trì các tiêu chuẩn chất lượng;', '- Thực hiện hoặc giám sát các chương trình hoạt động như trại giống cá, nhà kính và các chương trình sản xuất chăn nuôi;', '- Phân tích mẫu hạt giống để đánh giá chất lượng, độ tinh khiết và nảy mầm;', '- Thu thập dữ liệu, ước tính số lượng, chi phí vật liệu và nhân công cần thiết cho các dự án;', '- Tổ chức bảo trì và sửa chữa thiết bị nghiên cứu.']::text[], array['- Kỹ thuật viên về sữa', '- Kỹ thuật viên trồng trọt', '- Kiểm tra viên đàn vật nuôi', '- Kỹ thuật viên làm vườn', '- Kỹ thuật viên gia cầm']::text[], array['- Nhân viên thụ tinh nhân tạo - 3240', '- Kỹ thuật viên thú y - 3240']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1142) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3143', 'Kỹ thuật viên lâm nghiệp thực hiện các chức năng kỹ thuật và giám sát để hỗ trợ nghiên cứu lâm nghiệp, quản lý rừng, khai thác, bảo tồn tài nguyên và bảo vệ môi trường.', array['- Tiến hành kiểm kê rừng, khảo sát và đo đạc thực địa theo các quy trình khoa học và hoạt động được chấp nhận;', '- Hỗ trợ và thực hiện các chức năng kỹ thuật trong việc chuẩn bị kế hoạch quản lý và khai thác rừng bằng kỹ thuật lập bản đồ và hệ thống thông tin trên máy vi tính;', '- Hỗ trợ lập kế hoạch và giám sát xây dựng các tuyến đường tiếp cận và đường rừng;', '- Giám sát và thực hiện các chức năng kỹ thuật trong các hoạt động lâm sinh liên quan đến việc chuẩn bị mặt bằng, trồng và chăm sóc cây trồng;', '- Phối hợp các hoạt động như nhân rộng gỗ, ngăn chặn cháy rừng, kiểm soát dịch bệnh hoặc côn trùng và tỉa thưa các lâm phần;', '- Giám sát và thực hiện các chức năng kỹ thuật trong hoạt động khai thác rừng;', '- Đảm bảo tuân thủ các quy định và chính sách liên quan đến bảo vệ môi trường, sử dụng tài nguyên, an toàn cháy nổ và phòng ngừa tai nạn;', '- Giám sát các hoạt động của vườn ươm cây rừng;', '- Cung cấp hỗ trợ kỹ thuật cho các chương trình nghiên cứu lâm nghiệp trong các lĩnh vực như cải tạo cây, vận hành vườn giống, khảo sát côn trùng và bệnh hoặc nghiên cứu kỹ thuật lâm nghiệp;', '- Chuẩn bị kế hoạch canh tác và chặt phá rừng.']::text[], array['- Kỹ thuật viên lâm nghiệp', '- Kỹ thuật viên lâm sinh']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1163) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3144', 'Kỹ thuật viên nuôi trồng thủy sản nuôi dưỡng, chăm sóc cho thủy sản cũng như các động vật dưới nước khác. Nắm bắt mọi tình huống, theo dõi thông số môi trường nước thường xuyên để giúp môi trường sống của các loài động vật dưới nước được đảm bảo.', array['- Cung cấp hỗ trợ kỹ thuật cho nuôi trồng, chăm sóc thủy sản;', '- Bảo vệ nguồn lợi thủy sản, chẩn đoán bệnh học thủy sản;', '- Quản lý các hoạt động liên quan đến đánh bắt;', '- Theo dõi quá trình sinh trưởng và phát triển từng cá thể động vật dưới nước nhờ đó mà giúp phát hiện những cá thể bị mắc bệnh để chữa trị kịp thời;', '- Quản lý môi trường ao nuôi, công trình nuôi thủy sản, dinh dưỡng và thức ăn trong nuôi trồng thủy sản;', '- Thực hiện các biện pháp kỹ thuật sản xuất giống.']::text[], array['- Kỹ thuật viên nuôi trồng thủy sản nước ngọt', '- Kỹ thuật viên nuôi trồng thủy sản nước mặn, nước lợ', '- Kỹ thuật viên sản xuất giống thủy sản']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1179) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3151', 'Kỹ thuật viên máy của tàu thủy điều khiển và tham gia vận hành, bảo dưỡng và sửa chữa các thiết bị và máy móc cơ khí, điện và điện tử trên tàu hoặc thực hiện các chức năng hỗ trợ liên quan trên bờ.', array['- Kiểm soát và tham gia vận hành, bảo dưỡng và sửa chữa các thiết bị và máy móc cơ khí, điện và điện tử trên tàu;', '- Đặt hàng nhiên liệu và duy trì hoạt động các phòng động cơ khác;', '- Thực hiện giám sát kỹ thuật đối với việc lắp đặt, bảo trì và sửa chữa tàu, máy móc và thiết bị của tàu để đảm bảo tuân thủ các thông số kỹ thuật và quy định;', '- Kiểm tra và tiến hành bảo dưỡng và sửa chữa khẩn cấp cho động cơ, máy móc và thiết bị phụ trợ;', '- Giám sát phòng động cơ và ghi nhận hiệu suất của động cơ, máy móc và thiết bị phụ trợ.']::text[], array['- Kỹ sư tàu thủy']::text[], array['- Kỹ sư hàng hải - 2144']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1195) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3152', 'Hoa tiêu và nhân viên văn phòng trên tàu chỉ huy và điều hướng các tàu và các phương tiện tương tự tàu và thực hiện các chức năng liên quan trên bờ.', array['- Chỉ huy và điều hướng tàu hoặc các phương tiện tương tự tàu trên biển hoặc trên đường thủy nội địa;', '- Kiểm soát, tham gia các hoạt động trên boong và cầu nối;', '- Điều hướng các tàu vào, ra khỏi cảng, qua các kênh, eo biển và các vùng nước khác, nơi cần có kiến ​​thức đặc biệt;', '- Đảm bảo bốc dỡ hàng hóa an toàn, tuân thủ các quy định và quy trình an toàn của cả đoàn và hành khách;', '- Thực hiện giám sát kỹ thuật bảo trì và sửa chữa tàu để đảm bảo tuân thủ các thông số kỹ thuật và quy định;', '- Áp dụng kiến ​​thức về các nguyên tắc và thực tiễn liên quan đến hoạt động và điều hướng tàu để xác định và giải quyết các vấn đề phát sinh trong quá trình làm việc của họ;', '- Đặt hàng cửa hàng tàu, tuyển nhân viên theo yêu cầu và duy trì hồ sơ hoạt động;', '- Truyền, nhận thông tin thường xuyên và khẩn cấp với các trạm bờ và các tàu khác.']::text[], array['- Hoa tiêu (tàu)', '- Thuyền trưởng tàu', '- Thuyền trưởng (thuyền buồm)']::text[], array['- Đội trưởng khai thác cá trong nội địa - 6222', '- Đội trưởng tàu đánh cá bằng lưới - 6223', '- Thủy thủ - 8350']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1207) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3153', 'Phi công phương tiện bay và kỹ thuật viên hỗ trợ liên quan kiểm soát hoạt động của các thiết bị cơ khí, điện và điện tử để điều hướng máy bay vận chuyển hành khách, thư, hàng hóa; thực hiện các nhiệm vụ trước chuyến bay và trên chuyến bay liên quan.', array['- Bay và điều hướng máy bay theo quy trình điều khiển và vận hành đã được thiết lập;', '- Chuẩn bị và trình kế hoạch bay; kiểm tra kế hoạch bay tiêu chuẩn;', '- Kiểm soát hoạt động của các thiết bị cơ khí, điện, điện tử và đảm bảo tất cả các thiết bị và điều khiển hoạt động tốt;', '- Áp dụng kiến ​​thức về các nguyên tắc và thực hành bay để xác định và giải quyết các vấn đề phát sinh trong quá trình làm việc của họ;', '- Kiểm tra hồ sơ bảo trì và tiến hành kiểm tra để đảm bảo máy bay hoạt động tốt, việc bảo trì đã được thực hiện và tất cả các thiết bị đều hoạt động;', '- Ký các chứng chỉ cần thiết và lưu giữ hồ sơ chính thức của chuyến bay;', '- Có được các chỉ dẫn và thông quan trước các chuyến bay; duy trì liên lạc với giao thông hàng không hoặc kiểm soát không lưu trong suốt chuyến bay.']::text[], array['- Người phun thuốc trên không', '- Kỹ sư máy bay', '- Người hướng dẫn bay', '- Điều hướng (chuyến bay)', '- Phi công (máy bay)']::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1226) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3154', 'Kiểm soát viên không lưu chỉ đạo di chuyển của máy bay trong không phận và trên mặt đất, sử dụng hệ thống vô tuyến, radar và ánh sáng cung cấp thông tin liên quan đến hoạt động của máy bay.', array['- Chỉ đạo, điều khiển máy bay tiếp cận và rời sân bay và chuyển động của chúng trên mặt đất;', '- Chỉ đạo và điều khiển máy bay hoạt động trong các lĩnh vực không phận được chỉ định;', '- Kiểm tra và phê duyệt kế hoạch bay;', '- Thông báo cho phi hành đoàn chuyến bay và nhân viên điều hành về điều kiện thời tiết, phương tiện hoạt động, kế hoạch bay và giao thông hàng không;', '- Áp dụng kiến ​​thức về các nguyên tắc và thực hành kiểm soát không lưu để xác định và giải quyết các vấn đề phát sinh trong quá trình làm việc của họ;', '- Khởi xướng và tổ chức các dịch vụ và thủ tục khẩn cấp, tìm kiếm cứu nạn;', '- Chỉ đạo các hoạt động của tất cả các máy bay và phương tiện phục vụ trên hoặc gần đường băng sân bay;', '- Duy trì liên lạc vô tuyến và điện thoại với các tháp điều khiển liền kề, các đơn vị điều khiển đầu cuối và các trung tâm điều khiển khác; điều phối sự di chuyển của máy bay vào các khu vực liền kề.']::text[], '{}'::text[], '{}'::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1242) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3155', 'Kỹ thuật viên điện tử an toàn không lưu thực hiện các nhiệm vụ kỹ thuật liên quan đến thiết kế, lắp đặt, quản lý, vận hành, bảo trì và sửa chữa điều khiển không lưu và hệ thống định vị không khí.', array['- Thực hiện các nhiệm vụ kỹ thuật liên quan đến việc phát triển các hệ thống, thiết bị điều hướng không khí điện tử, máy tính và các nguyên mẫu thử nghiệm;', '- Cung cấp trợ giúp kỹ thuật trong thiết kế và bố trí mạch giao diện cụ thể của hệ thống theo dõi phát hiện máy bay;', '- Chuẩn bị dự toán chi phí và thông số kỹ thuật và huấn luyện cho thiết bị an toàn và kiểm soát không lưu;', '- Cung cấp hoặc hỗ trợ giám sát kỹ thuật xây dựng, lắp đặt và vận hành thiết bị dẫn đường trên mặt đất; bảo trì và sửa chữa để đảm bảo đáp ứng các tiêu chuẩn và thông số kỹ thuật;', '- Áp dụng kiến ​​thức, kỹ năng của các nguyên tắc và thực hành kỹ thuật an toàn không lưu để xác định và giải quyết các vấn đề phát sinh trong quá trình làm việc của họ;', '- Phát triển, sửa đổi và gỡ lỗi phần mềm hệ thống;', '- Sửa đổi các hệ thống và thiết bị điều hướng không khí trên mặt đất hiện có để thích ứng với các quy trình kiểm soát không lưu mới nhằm cải thiện khả năng, độ tin cậy và tính toàn vẹn hoặc để tạo điều kiện cho các thủ tục kiểm soát không lưu và chỉ định không phận;', '- Kiểm soát, giám sát và chứng nhận thiết bị điều hướng liên lạc và giám sát không lưu; hiệu chỉnh hệ thống điều hướng trên không để đảm bảo độ chính xác và an toàn tối đa cho các hoạt động bay, cất cánh và hạ cánh;', '- Cung cấp đào tạo kỹ thuật và giám sát các công nhân khác.']::text[], array['- Kỹ sư an toàn giao thông hàng không', '- Kỹ thuật viên an toàn giao thông hàng không']::text[], array['- Kỹ sư hàng không - 2144', '- Kỹ sư điện tử - 2152', '- Thợ cơ khí máy bay - 7232', '- Thợ bảo trì máy bay (hệ thống điện tử hàng không) - 7421', '- Kỹ thuật viên điện tử hàng không - 7421']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1253) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3211', 'Kỹ thuật viên hình ảnh và thiết bị y tế kiểm tra và vận hành X-quang, siêu âm và các thiết bị hình ảnh y tế khác để tạo ra hình ảnh cấu trúc cơ thể để chẩn đoán và điều trị chấn thương, bệnh tật và các khiếm khuyết khác. Họ có thể điều trị bức xạ cho bệnh nhân dưới sự giám sát của bác sĩ X-quang hoặc chuyên gia y tế khác.', array['- Vận hành hoặc giám sát hoạt động của thiết bị X-quang, siêu âm và hình ảnh từ tính để tạo ra hình ảnh của cơ thể cho mục đích chẩn đoán;', '- Giải thích các quy trình, quan sát và định vị bệnh nhân; sử dụng các thiết bị bảo vệ để đảm bảo an toàn và thoải mái trong quá trình khám, quét hoặc điều trị;', '- Định vị hình ảnh hoặc thiết bị xử lý, giám sát hiển thị video, điều chỉnh các cài đặt và điều khiển theo thông số kỹ thuật;', '- Xem xét và đánh giá các tia X, băng video hoặc thông tin do máy tính phát triển để xác định xem hình ảnh có thỏa đáng cho mục đích chẩn đoán hay không và ghi lại kết quả của các thủ tục;', '- Theo dõi tình trạng và phản ứng bệnh nhân, báo cáo các dấu hiệu bất thường cho bác sĩ;', '- Đo và ghi lại liều lượng phóng xạ hoặc dược phẩm phóng xạ nhận và sử dụng cho bệnh nhân theo đơn thuốc do bác sĩ y khoa ban hành;', '- Quản lý, phát hiện và lập bản đồ dược phẩm phóng xạ hoặc phóng xạ ở cơ thể bệnh nhân; sử dụng đồng vị phóng xạ, máy ảnh hoặc thiết bị khác để chẩn đoán và điều trị bệnh;', '- Ghi lại và xử lý các chất phóng xạ và lưu trữ dược phẩm phóng xạ theo các quy trình an toàn bức xạ.']::text[], array['- Kỹ thuật viên chẩn đoán X-quang y tế', '- Kỹ thuật viên hình ảnh cộng hưởng từ', '- Kỹ thuật viên chụp nhũ ảnh', '- Kỹ thuật viên trị liệu bức xạ y tế', '- Kỹ thuật viên y học hạt nhân', '- Kỹ thuật viên X-quang', '- Kỹ thuật viên siêu âm']::text[], array['- Nhà vật lý y tế - 2111', '- Bác sĩ X-quang - 2212', '- Chuyên gia bảo vệ bức xạ - 2263', '- Trợ lý hình ảnh y tế - 5329']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1280) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3212', 'Kỹ thuật viên phòng thí nghiệm y tế thực hiện các xét nghiệm lâm sàng trên mẫu vật của dịch cơ thể và mô để có được thông tin về sức khỏe của bệnh nhân hoặc nguyên nhân tử vong.', array['- Tiến hành phân tích hóa học các chất dịch cơ thể bao gồm máu, nước tiểu và dịch tủy sống để xác định sự hiện diện của các thành phần bình thường và bất thường;', '- Vận hành, hiệu chuẩn và bảo trì các thiết bị được sử dụng trong phân tích định lượng và định tính như máy đo quang phổ, nhiệt lượng kế, quang kế ngọn lửa và máy phân tích do máy tính điều khiển;', '- Nhập dữ liệu từ phân tích các xét nghiệm trong phòng thí nghiệm và kết quả lâm sàng vào các hệ thống lưu giữ hồ sơ và báo cáo kết quả cho các bác sĩ y khoa và các chuyên gia y tế khác;', '- Phân tích các mẫu vật liệu sinh học về hàm lượng hóa học hoặc phản ứng;', '- Thiết lập, làm sạch và bảo trì thiết bị phòng thí nghiệm;', '- Phân tích kết quả phòng thí nghiệm để kiểm tra tính chính xác của kết quả;', '- Thiết lập và giám sát các chương trình để đảm bảo tính chính xác của kết quả phòng thí nghiệm; phát triển, chuẩn hóa, đánh giá và sửa đổi các quy trình, kỹ thuật và xét nghiệm được sử dụng trong phân tích mẫu vật;', '- Lấy mẫu bệnh phẩm, nuôi cấy, phân lập và xác định vi sinh vật để phân tích;', '- Kiểm tra các tế bào nhuộm màu bằng thuốc nhuộm để xác định vị trí bất thường;', '- Tiêm trứng đã thụ tinh, nước dùng hoặc môi trường vi khuẩn khác với sinh vật.']::text[], array['- Kỹ thuật viên ngân hàng máu', '- Kỹ thuật viên tế bào học', '- Kỹ thuật viên phòng thí nghiệm y tế', '- Kỹ thuật viên bệnh lý']::text[], array['- Bác sĩ chuyên khoa - 2212', '- Kỹ thuật viên khoa học pháp y - 3119', '- Kỹ thuật viên thú y - 3240', '- Kỹ thuật viên lấy máu - 5329']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1304) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3213', 'Kỹ thuật viên và trợ lý dược thực hiện một loạt các nhiệm vụ liên quan đến pha chế các sản phẩm thuốc theo hướng dẫn của dược sĩ hoặc chuyên gia y tế khác.', array['- Chuẩn bị thuốc và các hợp chất dược phẩm khác theo hướng dẫn của dược sĩ hoặc chuyên gia y tế khác;', '- Phân phối thuốc cho khách hàng và hướng dẫn bằng văn bản và bằng miệng về việc sử dụng chúng theo quy định của bác sĩ y tế, bác sĩ thú y hoặc các chuyên gia y tế khác;', '- Nhận đơn thuốc hoặc yêu cầu cung cấp thêm từ các chuyên gia y tế và xác minh rằng thông tin là đầy đủ và chính xác theo tiêu chuẩn lưu trữ hồ sơ y tế;', '- Duy trì các điều kiện bảo quản thích hợp cho thuốc;', '- Điền và dán nhãn hộp đựng các loại thuốc theo quy định;', '- Hỗ trợ khách hàng bằng cách trả lời các câu hỏi, định vị vật phẩm hoặc giới thiệu họ đến dược sĩ để biết thông tin về thuốc;', '- Định giá và nộp đơn thuốc đã được điền; thiết lập và duy trì hồ sơ bệnh nhân bao gồm danh sách các loại thuốc được sử dụng bởi từng bệnh nhân;', '- Đặt hàng, dán nhãn, đếm số lượng thuốc, hóa chất và vật tư; nhập dữ liệu hàng tồn kho vào các hệ thống lưu giữ hồ sơ;', '- Làm sạch và chuẩn bị thiết bị, thùng chứa được sử dụng để phân phối thuốc và hợp chất dược phẩm.']::text[], array['- Kỹ thuật viên pha chế', '- Trợ lý dược', '- Kỹ thuật viên dược phẩm', '- Dược sĩ bán lẻ thuốc']::text[], array['- Dược sĩ - 2262', '- Kỹ thuật viên dược lý - 3141', '- Phụ tá dược - 5329']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1327) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3214', 'Kỹ thuật viên lắp răng giả và chỉnh hình thiết kế, lắp, chế tạo và sửa chữa các thiết bị, dụng cụ y tế và nha khoa theo toa thuốc hoặc hướng dẫn của chuyên gia y tế. Họ có thể chế tạo một loạt các dụng cụ hỗ trợ để khắc phục các vấn đề về cơ thể hoặc nha khoa chẳng hạn như niềng cổ, nẹp chỉnh hình, chân tay giả, máy trợ thính, hỗ trợ vòm, răng giả, chụp răng và cầu răng.', array['- Kiểm tra, phỏng vấn và đo lường bệnh nhân để xác định nhu cầu thiết bị của họ và để xác định các yếu tố có thể ảnh hưởng đến sự phù hợp của thiết bị;', '- Trao đổi với các bác sĩ y khoa và nha khoa để xây dựng các thông số kỹ thuật và đơn thuốc cho các thiết bị và công cụ;', '- Diễn giải các đơn thuốc hoặc thông số kỹ thuật để xác định loại sản phẩm hoặc thiết bị sẽ được chế tạo, các vật liệu và công cụ sẽ được yêu cầu;', '- Tạo hoặc nhận phôi hoặc dấu ấn của bệnh nhân, tay chân, miệng hoặc răng để sử dụng làm mô hình chế tạo;', '- Thiết kế và chế tạo các thiết bị chỉnh hình và chân tay giả bằng các vật liệu như vật liệu nhiệt dẻo và nhiệt rắn, hợp kim, kim loại và da, dụng cụ cầm tay và điện;', '- Lắp thiết bị và dụng cụ cho bệnh nhân, kiểm tra và đánh giá chúng, thực hiện các điều chỉnh cho phù hợp, đúng chức năng và thoải mái;', '- Sửa chữa, sửa đổi và bảo trì các thiết bị hỗ trợ và phục hình y tế, nha khoa theo thông số kỹ thuật;', '- Uốn, tạo hình và định hình vải hoặc vật liệu sao cho phù hợp với các đường viền quy định cần thiết để chế tạo các thành phần kết cấu;', '- Chế tạo răng giả toàn phần và một phần; xây dựng các tấm bảo vệ miệng, mão răng, móc kim loại, khảm, cầu răng và các dụng cụ hỗ trợ khác;', '- Hướng dẫn bệnh nhân sử dụng và chăm sóc các thiết bị giả hoặc dụng cụ chỉnh hình.']::text[], array['- Kỹ thuật viên lắp răng giả', '- Kỹ thuật viên nha khoa', '- Nha sĩ', '- Nhà sản xuất dụng cụ chỉnh hình', '- Kỹ thuật viên chỉnh hình', '- Kỹ thuật viên lắp chân tay giả', '- Bác sĩ thẩm mỹ']::text[], array['- Trợ lý nha khoa - 5329', '- Thợ sản xuất dụng cụ phẫu thuật - 7311', 'Ghi chú:', 'Nghề nghiệp trong mã này thường đòi hỏi một số kiến ​​thức y tế, nha khoa và giải phẫu, kỹ thuật thông qua đào tạo chính thức. Kỹ thuật viên xây dựng và sửa chữa các dụng cụ y tế và phẫu thuật chính xác không thuộc mã này.']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1348) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3221', 'Y tá/điều dưỡng, kỹ thuật viên chăm sóc bệnh nhân cung cấp điều dưỡng cơ bản và chăm sóc cá nhân cho những người cần sự chăm sóc đó do ảnh hưởng của lão hóa, bệnh tật, chấn thương hay suy yếu về thể chất hoặc tinh thần. Họ thường làm việc dưới sự giám sát của các chuyên gia y tế và các y tá/điều dưỡng bậc cao; hỗ trợ thực hiện các kế hoạch chăm sóc sức khỏe và điều trị được thiết lập bởi các chuyên gia y tế và các y tá/điều dưỡng bậc cao.', array['- Cung cấp điều dưỡng và chăm sóc cá nhân; điều trị và tư vấn sức khỏe cho bệnh nhân theo kế hoạch chăm sóc được thiết lập bởi các chuyên gia y tế;', '- Quản lý thuốc và các phương pháp điều trị cho bệnh nhân; theo dõi bệnh nhân về tình trạng và phản ứng với điều trị; giới thiệu bệnh nhân và gia đình họ đến một chuyên gia y tế để được chăm sóc chuyên khoa khi cần thiết;', '- Làm sạch vết thương và dán băng phẫu thuật;', '- Cập nhật thông tin về bệnh nhân, tình trạng và phương pháp điều trị nhận được trong các hệ thống lưu giữ hồ sơ;', '- Hỗ trợ lập kế hoạch và quản lý chăm sóc từng bệnh nhân;', '- Hỗ trợ điều trị sơ cứu trong trường hợp khẩn cấp.']::text[], array['- Trợ lý y tá/điều dưỡng', '- Y tá/Điều dưỡng', '- Y tá/điều dưỡng chính quy', '- Y tá/điều dưỡng thực hành']::text[], array['- Nhà tư vấn y tá/điều dưỡng lâm sàng - 2221', '- Y tá/điều dưỡng cao cấp - 2221', '- Y tá/điều dưỡng chuyên khoa - 2221', '- Nữ hộ sinh cao cấp - 2222', '- Nữ hộ sinh chính - 3222', '- Trợ lý y tá/điều dưỡng (phòng khám hoặc bệnh viện) - 5321', '- Trợ lý y tá/điều dưỡng (tại nhà) - 5322', 'Ghi chú:', 'Sự khác biệt giữa y tá/điều dưỡng cao cấp với y tá/điều dưỡng chính nên được xác định trên cơ sở bản chất của công việc có liên quan đến nhiệm vụ cụ thể. Trình độ chuyên môn của các cá nhân hoặc chiếm ưu thế trong nước không phải là yếu tố chính tạo nên sự khác biệt này, vì sự sắp xếp đào tạo cho y tá/điều dưỡng rất khác nhau giữa các quốc gia và thay đổi theo thời gian trong các quốc gia.']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1375) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3222', 'Hộ sinh cung cấp tư vấn và chăm sóc sức khỏe cơ bản trước, trong và sau khi mang thai và sinh nở. Họ thực hiện các kế hoạch chăm sóc và điều trị được thiết lập bởi các chuyên gia y tế và các hộ sinh bậc cao.', array['- Tư vấn cho phụ nữ, gia đình và cộng đồng về sức khỏe, dinh dưỡng, vệ sinh, tập thể dục, kế hoạch sinh nở và trường hợp cấp cứu; cho con bú, chăm sóc trẻ sơ sinh, kế hoạch hóa gia đình và tránh thai; lối sống và các chủ đề khác liên quan đến mang thai và sinh nở;', '- Đánh giá tiến triển trong khi mang thai và sinh nở; nhận ra các dấu hiệu và triệu chứng cần được giới thiệu đến một chuyên gia y tế;', '- Cung cấp dịch vụ chăm sóc sinh nở thường chỉ trong trường hợp không có các biến chứng tiềm ẩn đã được xác định; hỗ trợ bác sĩ y khoa hoặc chuyên gia hộ sinh chăm sóc sinh nở;', '- Chăm sóc và hỗ trợ cho phụ nữ sau khi sinh con và trẻ sơ sinh; theo dõi tình trạng sức khỏe của họ, xác định các dấu hiệu và triệu chứng cần được giới thiệu đến một chuyên gia y tế.']::text[], array['- Nữ hộ sinh chính', '- Bà đỡ truyền thống']::text[], array['- Nhà tư vấn y tá/điều dưỡng lâm sàng - 2221', '- Y tá/điều dưỡng cao cấp - 2221', '- Y tá/điều dưỡng chuyên khoa - 2221', '- Nữ hộ sinh cao cấp - 2222', '- Hộ lý sinh sản - 5321', 'Ghi chú:', 'Nhóm này bao gồm các nghề nghiệp đòi hỏi kiến thức và kỹ năng về chăm sóc hộ sinh thường xuyên và cấp cứu có được thông qua đào tạo chính thức hoặc không chính thức. Các tiêu chí để đưa các cá nhân vào nhóm này phải dựa trên tính chất công việc được thực hiện liên quan đến các nhiệm vụ được chỉ định chứ không phải bằng cấp do các cá nhân nắm giữ hoặc chiếm ưu thế trong nước. Nữ hộ sinh truyền thống và bà đỡ, những người cung cấp dịch vụ chăm sóc và tư vấn mang thai và sinh nở cơ bản chủ yếu dựa trên kinh nghiệm và kiến thức có được thông qua các truyền thống và thực hành của cộng đồng nơi họ bắt nguồn, được phân loại ở đây.', 'Hộ lý sinh sản, người hỗ trợ tinh thần, chăm sóc và tư vấn chung cho phụ nữ và gia đình trong khi mang thai và chuyển dạ, được phân loại trong nhóm 532. Nhân viên chăm sóc về dịch vụ sức khỏe.']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1399) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3230', 'Kỹ thuật viên y học cổ truyền và bổ trợ ngăn ngừa, chăm sóc và điều trị thể chất và tinh thần, rối loạn và tổn thương của con người bằng cách sử dụng thảo dược và các liệu pháp khác dựa trên lý thuyết, niềm tin và kinh nghiệm có nguồn gốc từ nền văn hóa cụ thể. Họ sử dụng liệu pháp kỹ thuật cổ truyền và dược phẩm, hoạt động độc lập hoặc theo kế hoạch chăm sóc thiết lập bởi nhà chuyên môn về y học cổ truyền và hỗ trợ hoặc nhà chuyên môn về sức khỏe khác.', array['- Kiểm tra bệnh nhân, phỏng vấn họ và gia đình để xác định tình trạng sức khỏe của họ và rối loạn về thể chất hoặc tinh thần hoặc các bệnh khác;', '- Đề xuất và cung cấp việc chăm sóc và điều trị bệnh tật bằng cách sử dụng kỹ thuật và thảo dược cổ truyền chẳng hạn như vật lý trị liệu, lấy máu sử dụng mạch tự nhiên, sử dụng các loại thảo mộc, cây, côn trùng và chất chiết xuất từ động vật;', '- Quản lý các phương pháp điều trị như châm cứu, khoa học ayurvedic, liệu pháp vi lượng đồng căn và thảo dược theo kế hoạch chăm sóc điều trị và các thủ tục được thiết lập bởi nhà chuyên môn về y học cổ truyền hoặc nhà chuyên môn về sức khỏe khác;', '- Cung cấp chăm sóc và điều trị các chấn thương vật lý như bị gãy, trật xương bằng cách sử dụng các phương pháp truyền thống của thao tác vật lý và các liệu pháp thảo dược;', '- Tư vấn cho cá nhân, gia đình và cộng đồng hoặc cơ sở sức khỏe, dinh dưỡng duy trì và cải thiện sức khỏe;', '- Giới thiệu bệnh nhân đến và trao đổi thông tin với nhà cung cấp chăm sóc y tế khác để đảm bảo chăm sóc toàn diện và liên tục.']::text[], array['- Kỹ thuật viên châm cứu', '- Kỹ thuật viên Ayurvedic (tên một phương pháp chữa bệnh của Ấn Độ)', '- Người nắn xương', '- Người trồng và bán thảo dược', '- Kỹ thuật viên chữa theo vi lượng đồng căn', '- Người làm giác hơi', '- Thầy lang', '- Thầy mo']::text[], array['Chuyên gia châm cứu - 2230', 'Nhà chuyên môn Ayurvedic - 2230', '- Nhà chuyên môn về thuốc bắc - 2230', '- Nhà chuyên môn vi lượng đồng căn - 2230', '- Nhà chuyên môn về thiên nhiên liệu pháp - 2230', '- Chuyên gia trị liệu thần kinh cột sống - 2269', '- Chuyên gia nắn xương - 2269', '- Hộ sinh truyền thống - 3222', '- Kỹ thuật viên vật lý trị liệu - 3255', '- Kỹ thuật viên thủy liệu pháp - 3255', '- Người chữa lành đức tin - 3413']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1418) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3240', 'Kỹ thuật viên thú y và phụ tá thực hiện tư vấn, chẩn đoán, phòng ngừa và chữa bệnh thú y với nhiệm vụ hạn chế hơn bác sĩ thú y. Họ điều trị cho động vật tại các cơ sở thú y và hỗ trợ bác sĩ thú y để thực hiện các thủ tục và phẫu thuật.', array['Tư vấn cho cộng đồng và cá nhân về việc điều trị của động vật, các bệnh và chấn thương của chúng;', 'Tiến hành kiểm tra động vật để chẩn đoán hoặc tham khảo ý kiến của bác sỹ thú y nếu cần thiết;', 'Điều trị động vật bị bệnh hay bị thương, đặc biệt là cho các bệnh thường gặp và các rối loạn;', 'Vệ sinh và khử trùng các dụng cụ và vật liệu chuẩn bị được sử dụng trong việc khám và điều trị động vật;', 'Thực hiện các nhiệm vụ kỹ thuật liên quan đến thụ tinh nhân tạo động vật;', 'Khống chế hoặc giữ động vật sẵn sàng cho khám bệnh hoặc điều trị;', 'Hỗ trợ bác sĩ thú y quản lý thuốc gây mê tại chỗ và ôxy trong thời gian điều trị;', 'Đặt động vật trong lồng để hồi phục sau phẫu thuật và giám sát tình trạng của chúng;', 'Chụp X-quang, thu thập mẫu và thực hiện các xét nghiệm khác để hỗ trợ trong chẩn đoán bệnh động vật;', 'Thực hiện các thủ thuật nha khoa động vật thường xuyên và hỗ trợ bác sĩ thú y trong nha khoa thú y.']::text[], array['Kỹ thuật viên thụ tinh nhân tạo', 'Phụ tá thú y', 'Y tá thú y', 'Kỹ thuật viên tiêm chủng thú y']::text[], array['Bác sỹ thú y - 2250', 'Nhân viên chăm sóc động vật - 5164', 'Nhân viên hỗ trợ thú y - 5164.', '(Xem tiếp Công báo số 1147 + 1148)', 'Số 1147 + 1148 Ngày 12 tháng 12 năm 2020', 'MỤC LỤC', 'VĂN BẢN QUY PHẠM PHÁP LUẬT', 'THỦ TƯỚNG CHÍNH PHỦ', 'Quyết định số 34/2020/QĐ-TTg ngày 26 tháng 11 năm 2020', 'ban hành Danh mục nghề nghiệp Việt Nam', '(Tiếp theo Công báo số 1145 + 1146)', 'Phụ lục II', 'NỘI DUNG DANH MỤC NGHỀ NGHIỆP VIỆT NAM', '(Ban hành kèm theo Quyết định số 34/2020/QĐ-TTg', 'ngày 26 tháng 11 năm 2020 của Thủ tướng Chính phủ)', '________________']::text[], null, '2020_1145 + 1146_34-2020-QĐ-TTg.doc', 1448) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3251', 'Phụ tá nha khoa và trị liệu cung cấp dịch vụ chăm sóc răng cơ bản cho việc phòng chống, điều trị bệnh và các rối loạn răng, miệng theo kế hoạch chăm sóc và thủ tục thiết lập bởi một nha sĩ hay chuyên gia sức khỏe răng miệng.', array['- Tư vấn cho cộng đồng và cá nhân về vệ sinh răng miệng, ăn kiêng và các biện pháp phòng ngừa khác để giảm rủi ro tiềm ẩn đến sức khỏe răng miệng;', '- Tiến hành kiểm tra bằng mắt thường miệng, răng của bệnh nhân và các cấu trúc liên quan để đánh giá tình trạng sức khỏe răng miệng;', '- Xác định các trường hợp bệnh nhân có sức khỏe răng miệng kém hoặc bệnh răng miệng đòi hỏi phải giới thiệu đến một nha sĩ hoặc chuyên gia sức khỏe khác;', '- Hỗ trợ nha sĩ trong các thủ thuật nha khoa;', '- Cung cấp các điều trị flour, làm sạch và loại bỏ cao răng, chuẩn bị hàn răng, cách đặt trám, gây mê cục bộ và thực hiện những nhiệm vụ nha khoa lâm sàng cơ bản hoặc hàng ngày;', '- Chuẩn bị, làm sạch và khử trùng dụng cụ nha khoa, thiết bị và vật liệu được sử dụng ở khám và điều trị bệnh nhân;', '- Giúp bệnh nhân chuẩn bị khám hoặc điều trị, trong đó có giải thích quy trình và định vị chính xác;', '- Tham gia lấy dấu miệng và chụp răng để hỗ trợ chẩn đoán và lắp răng giả.']::text[], array['- Phụ tá nha khoa', '- Phụ tá vệ sinh răng', '- Kỹ thuật viên trị liệu răng']::text[], array['- Nha sĩ - 2261', '- Kỹ thuật viên chỉnh hình răng - 3214', '- Kỹ thuật viên lắp chân tay giả - 3214', '- Kỹ thuật viên nha khoa - 3214', '- Trợ lý nha khoa - 5329']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 38) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3252', 'Nhân viên ghi chép sổ sách y tế và thông tin về sức khỏe triển khai, duy trì và thực hiện các hồ sơ y tế được xử lý, lưu trữ và truy xuất hệ thống cơ sở y tế và các cài đặt chăm sóc sức khỏe khác để đáp ứng nhu cầu luật pháp, chuyên môn, đạo đức và hành chính.', array['- Lập kế hoạch, triển khai, duy trì và xử lý một loạt các danh mục hồ sơ sức khỏe; lưu trữ và truy xuất hệ thống thu thập, phân loại và phân tích thông tin;', '- Sao chép, biên dịch và xử lý các hồ sơ y tế của bệnh nhân, hồ sơ nhập, xuất và các báo cáo y tế khác vào hệ thống lưu giữ thông tin để cung cấp dữ liệu cho việc giám sát bệnh nhân và giám sát dịch tễ học, nghiên cứu, thanh toán, kiểm soát chi phí và cải tiến chăm sóc;', '- Xem xét hồ sơ đảm bảo đầy đủ, chính xác và phù hợp với quy định;', '- Đọc mô tả thông số từ hồ sơ y tế và các tài liệu sức khỏe khác chuyển vào mã tương thích với hệ thống danh mục chuẩn;', '- Quản lý bản ghi y tế an toàn để đảm bảo tính bảo mật và phát hành thông tin cho người được ủy quyền và các cơ quan theo quy định;', '- Giám sát hành chính người lao động liên quan đến duy trì các hồ sơ y tế.']::text[], array['Lập trình viên lâm sàng', 'Nhân viên về đăng ký bệnh', 'Nhân viên thông tin sức khỏe', 'Nhân viên phân tích hồ sơ y tế', 'Nhân viên hồ sơ y tế', 'Kỹ thuật viên hồ sơ y tế', 'Giám sát viên hồ sơ y tế']::text[], array['- Thư ký y tế - 3344', '- Nhân viên nhập dữ liệu - 4132', '- Nhân viên văn thư - 4405']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 59) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3253', 'Nhân viên y tế cộng đồng cung cấp giáo dục sức khỏe, giới thiệu, theo dõi và quản lý sức khỏe cá nhân; chăm sóc sức khỏe phòng ngừa cơ bản và dịch vụ thăm khám tại nhà đối với trường hợp cụ thể. Họ cung cấp việc hỗ trợ và giúp đỡ cho các cá nhân và gia đình trong vấn đề hướng đến các hệ thống y tế và dịch vụ xã hội.', array['- Cung cấp thông tin cho gia đình và cộng đồng về một loạt các vấn đề sức khỏe bao gồm dinh dưỡng, vệ sinh, trẻ sơ sinh, chăm sóc trẻ em, chích ngừa, kế hoạch hóa gia đình, yếu tố nguy cơ và phòng chống bệnh truyền nhiễm thường gặp, phòng ngừa ngộ độc, hỗ trợ ban đầu điều trị bệnh đơn giản và phổ biến, nghiện ma túy, bạo lực và các chủ đề khác;', '- Thăm gia đình để cung cấp thông tin về sức khỏe, xã hội và các dịch vụ khác; hỗ trợ họ trong việc đạt được các dịch vụ này;', '- Thăm gia đình thường không tiếp cận các cơ sở y tế để giám sát một cách thường xuyên các điều kiện nhất định ví dụ những tiến bộ trong thai sản, tăng trưởng, phát triển trẻ em và vệ sinh môi trường;', '- Phân phối đến hộ gia đình vật tư y tế đối với công tác phòng chống và điều trị các bệnh truyền nhiễm như bệnh sốt rét, viêm phổi và bệnh tiêu chảy; hướng dẫn các thành viên gia đình và cộng đồng trong việc sử dụng các sản phẩm này;', '- Tiến hành các nỗ lực tiếp cận với các nhóm người không thường tiếp cận các cơ sở y tế với các thông tin và vật tư y tế cơ bản cho phòng ngừa và quản lý điều kiện y tế hiện tại mà họ có nguy cơ cao, chẳng hạn như HIV/AIDS và các bệnh truyền nhiễm khác;', '- Thu thập dữ liệu từ các hộ gia đình và cộng đồng những người không thường tiếp cận các cơ sở y tế cho các mục đích giám sát bệnh nhân, giới thiệu và báo cáo đáp ứng các quy định của y tế.']::text[], array['- Trợ giúp y tế cộng đồng', '- Người sáng lập y tế cộng đồng', '- Nhân viên y tế cộng đồng', '- Nhân viên y tế làng xã']::text[], array['- Bà đỡ truyền thống - 3222', '- Người chữa bệnh trong làng - 3230', '- Phụ tá chăm sóc tại nhà - 5322']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 80) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3254', 'Kỹ thuật viên nhãn khoa thiết kế phù hợp và phân chia các ống kính quang học dựa trên toa thuốc từ bác sĩ nhãn khoa hoặc y sĩ nhãn khoa cho điều chỉnh giảm thị lực. Họ có dịch vụ sửa chữa kính, tròng, tầm nhìn thị lực thấp và các thiết bị quang học khác.', array['- Kiểm tra và lấy số đo trên khuôn mặt và mắt của khách hàng để lắp kính và các dụng cụ quang học;', '- Cung cấp tư vấn cho khách hàng lựa chọn và bảo trì kính và gọng, kính áp tròng và các thiết bị quang học khác đảm bảo hiệu quả, an toàn, thoải mái;', '- Giải thích mô tả quang học, chuẩn bị đơn đặt hàng làm việc cho phòng thí nghiệm quang học cho mài và gắn kính vào gọng, chuẩn bị kính áp tròng và yêu cầu công việc khác;', '- Xác nhận hoàn thành thiết bị quang học và các thiết bị khác phù hợp với khách hàng.']::text[], array['- Kỹ thuật viên kính áp tròng', '- Kỹ thuật viên dụng cụ quang học']::text[], array['Bác sĩ nhãn khoa - 2212', 'Nhà chuyên môn về thị lực - 2267', 'Nhà chuyên môn về nhãn khoa - 2267']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 98) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3255', 'Kỹ thuật viên vật lý trị liệu và phụ tá cung cấp phương pháp điều trị vật lý trị liệu đối với các bệnh nhân gặp vấn đề về chức năng di chuyển do thương tật hay suy nhược. Phương pháp điều trị thường được cung cấp theo kế hoạch phục hồi được thiết lập bởi bác sỹ vật lý trị liệu hoặc chuyên gia y tế khác.', array['- Quản lý, hướng dẫn sử dụng liệu pháp như điều trị bằng massage hoặc điều trị bằng áp lực điểm;', '- Quản lý phương thức trị liệu điện từ, siêu âm và các liệu pháp vật lý khác sử dụng các kỹ thuật và thiết bị chuyên môn;', '- Hướng dẫn, thúc đẩy, bảo vệ và giúp đỡ bệnh nhân như thực hành các bài tập vật lý, kỹ thuật thư giãn và vận động chức năng;', '- Bàn bạc với bác sỹ vật lý trị liệu hoặc nhà cung cấp chăm sóc y tế khác để đánh giá các thông tin bệnh nhân từ đó lập kế hoạch phù hợp;', '- Giám sát và ghi lại sự tiến bộ của bệnh nhân trong quá trình điều trị bao gồm cả đo chuyển động và các dấu hiệu sinh tồn;', '- Chỉnh dụng cụ chỉnh hình, các thiết bị hỗ trợ vật lý khác như nạng bệnh nhân và hướng dẫn bệnh nhân trong việc sử dụng các thiết bị này.']::text[], array['- Kỹ thuật viên trị liệu bấm huyệt', '- Kỹ thuật viên điều trị xung điện', '- Kỹ thuật viên thủy liệu pháp', '- Kỹ thuật viên trị liệu bằng mát xa', '- Kỹ thuật viên phục hồi chức năng', '- Kỹ thuật viên vật lý trị liệu', '- Kỹ thuật viên trị liệu Shiatsu']::text[], array['- Bác sĩ vật lý trị liệu - 2264', '- Bác sỹ về cột sống - 2269', '- Nhà trị liệu về cơ năng - 2269', '- Nhà chuyên môn trị bệnh về chân - 2269']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 112) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3256', 'Nhân viên trợ giúp y tế thực hiện các nhiệm vụ cơ bản lâm sàng và hành chính để hỗ trợ chăm sóc bệnh nhân dưới sự giám sát trực tiếp của y, bác sĩ hoặc chuyên gia y tế khác.', array['- Phỏng vấn bệnh nhân và gia đình của họ để có được thông tin về tình trạng sức khỏe của họ và lịch sử y tế;', '- Hỗ trợ các y, bác sĩ và các chuyên gia y tế khác để kiểm tra và điều trị bệnh nhân bao gồm cả đo và ghi lại các dấu hiệu quan trọng, quản lý thuốc và thực hiện các thủ tục lâm sàng hàng ngày như tiêm và tháo chỉ khâu;', '- Chuẩn bị cho bệnh nhân kiểm tra và điều trị bao gồm giải thích thủ tục và hiển thị chúng cho phòng xét nghiệm;', '- Chuẩn bị và xử lý dụng cụ y tế và nguồn cung cấp bao gồm cả thiết bị khử trùng và xử lý các nguồn cung cấp bị ô nhiễm theo đúng quy trình an toàn;', '- Lấy máu, mô hoặc mẫu vật khác và chuẩn bị chúng cho phòng xét nghiệm;', '- Cung cấp thông tin cho bệnh nhân và gia đình về chăm sóc sức khỏe bao gồm các loại thuốc theo quy định của bác sĩ hoặc chuyên viên y tế khác;', '- Cung cấp thông tin thuốc theo toa cho các hiệu thuốc;', '- Bảo đảm vệ sinh cho phòng chờ của bệnh nhân và phòng xét nghiệm;', '- Ghi thông tin về lịch sử y tế bệnh nhân, kết quả chẩn đoán, xét nghiệm và các thông tin khác trong hệ thống;', '- Lên lịch hẹn với bệnh nhân, chuẩn bị tài liệu cần thiết cho bảo hiểm thanh toán.']::text[], array['- Phụ tá lâm sàng', '- Phụ tá y tế', '- Trợ lý nhãn khoa']::text[], array['- Bác sĩ lâm sàng (trợ y) - 2240', '- Kỹ thuật viên lắp chân tay giả - 3214', '- Phụ tá nha khoa - 3251', '- Kỹ thuật viên vật lý trị liệu - 3255', '- Thư ký y tế - 3344', '- Trợ giúp hình ảnh y khoa - 5329']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 134) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3257', 'Thanh tra viên và cộng tác viên môi trường và sức khỏe nghề nghiệp điều tra việc thực hiện các quy tắc và quy định liên quan đến yếu tố môi trường có thể ảnh hưởng đến sức khỏe con người, an toàn tại nơi làm việc và an toàn của các quá trình sản xuất hàng hóa và dịch vụ. Họ có thể thực hiện và đánh giá các chương trình để phục hồi hoặc cải thiện các điều kiện vệ sinh dưới sự giám sát của một chuyên gia y tế.', array['- Tham mưu đại diện người sử dụng lao động và người lao động về việc thực hiện các quy định, quy tắc của pháp luật và tổ chức liên quan đến an toàn lao động và môi trường lao động;', '- Kiểm tra nơi làm việc để đảm bảo rằng môi trường, máy móc và thiết bị làm việc phù hợp với quy tắc, quy định của chính phủ và các tiêu chuẩn liên quan đến vệ sinh môi trường, sức khỏe, an toàn lao động và môi trường;', '- Đưa ra lời khuyên về các vấn đề vệ sinh môi trường và kỹ thuật;', '- Kiểm tra nơi làm việc bằng cách phỏng vấn, quan sát và các phương tiện khác; thu thập thông tin về thực tiễn công việc và tai nạn để xác định phù hợp với các quy tắc và quy định an toàn;', '- Kiểm tra khu vực sản xuất, chế biến, vận chuyển, xử lý, bảo quản và tiêu thụ sản phẩm để đảm bảo phù hợp với các tiêu chuẩn của chính phủ và các quy định khác;', '- Tư vấn doanh nghiệp và công chúng nói chung về việc thực hiện các quy định của chính phủ và các quy tắc liên quan đến vệ sinh, vệ sinh môi trường, độ tinh khiết và phân loại các sản phẩm chủ yếu, thực phẩm, thuốc, mỹ phẩm và hàng hóa tương tự;', '- Kiểm tra các cơ sở để đảm bảo phù hợp với quy định của chính phủ và các quy tắc liên quan đến việc xả thải các chất ô nhiễm và xử lý chất thải nguy hiểm;', '- Khởi xướng các hành động để duy trì hoặc cải thiện vệ sinh và ngăn ngừa ô nhiễm của nước, không khí, thức ăn hoặc đất;', '- Đẩy mạnh phòng ngừa và khắc phục các biện pháp như kiểm soát các sinh vật mang bệnh, các chất độc hại trong không khí, xử lý thực phẩm bẩn, xử lý chất thải ô nhiễm và làm sạch những nơi công cộng;', '- Ước tính số lượng, chi phí vật liệu và lao động cần thiết cho sức khỏe, an toàn và vệ sinh môi trường các dự án khắc phục;']::text[], array['Thanh tra an toàn thực phẩm và vệ sinh môi trường', 'Thanh tra y tế', 'Thanh tra sức khỏe nghề nghiệp và an toàn lao động', 'Thanh tra môi trường', 'Thanh tra an toàn sản phẩm', 'Thanh tra vệ sinh']::text[], array['Nhà chuyên môn về y tế môi trường - 2263', 'Nhà tư vấn về sức khỏe nghề nghiệp và an toàn lao động - 2263', 'Nhà chuyên môn về vệ sinh nghề nghiệp - 2263', 'Chuyên gia về bảo vệ bức xạ - 2263']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 158) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3258', 'Nhân viên cấp cứu cung cấp chăm sóc y tế khẩn cấp cho bệnh nhân đang bị thương, bị bệnh, tàn tật hoặc suy sụp về thể chất và tinh thần trước và trong quá trình vận chuyển đến cơ sở y tế.', array['- Đánh giá tình trạng sức khỏe của người liên quan đến các tai nạn, thiên tai và các tình huống khẩn cấp; xác định nhu cầu trợ giúp y tế ngay lập tức và chuyên ngành;', '- Thực hiện các thủ tục y tế, quản lý các loại thuốc và các liệu pháp khác theo phương thức cho điều trị y tế khẩn cấp bao gồm cả hồi sức, phục hồi nhịp tim cho bệnh nhân và vận hành thiết bị hỗ trợ sự sống;', '- Giám sát các thay đổi về tình trạng sức khỏe của bệnh nhân trong quá trình vận chuyển đến và từ cơ sở y tế; phục hồi chức năng và chăm sóc sức khỏe khác;', '- Cung cấp thông tin và đào tạo cho các nhóm cộng đồng và người lao động cần thiết dịch vụ cấp cứu ban đầu cho việc chăm sóc bệnh tật hoặc thương tích;', '- Tham dự và tuần tra cuộc tụ họp công cộng quy mô lớn và các sự kiện khác nơi có thể xảy ra trường hợp cấp cứu y tế;', '- Ghi thông tin về điều kiện và phương pháp điều trị bệnh nhân được cung cấp trong hồ sơ y tế.']::text[], array['- Nhân viên cứu thương', '- Kỹ thuật viên cấp cứu']::text[], array['- Thực tập sinh y khoa - 2240', '- Lái xe cứu thương - 8322']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 183) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3259', 'Nhóm này bao gồm các nghề chưa được phân loại trong nhóm 32: Kỹ thuật viên sức khỏe. Ví dụ, nhóm liên quan đến nghề nghiệp như nhân viên tư vấn HIV, nhân viên tư vấn kế hoạch hóa gia đình và chuyên môn sức khỏe khác.', array['- Phỏng vấn và kiểm tra các bệnh nhân để có được thông tin về tình trạng sức khỏe của họ, tính chất và mức độ thương tật, bệnh tật hoặc các điều kiện sức khỏe về thể chất hoặc tâm thần khác;', '- Cung cấp thông tin và tư vấn cho bệnh nhân và gia đình về một số điều kiện sức khỏe, phòng ngừa và lựa chọn điều trị, tuân thủ điều trị, và hành vi cá nhân có thể ảnh hưởng đến kết quả sức khỏe;', '- Quản lý điều trị và chăm sóc cho bệnh nhân;', '- Thực hiện một số thủ tục lâm sàng cơ bản như quản lý xét nghiệm kháng thể HIV hoặc đặt vòng tránh thai;', '- Phân phát và tư vấn về chế độ ăn uống bổ sung, các thuốc kháng vi rút và phòng ngừa, sản phẩm chăm sóc sức khỏe khác.', '- Theo dõi sự tiến bộ của bệnh nhân thông qua kế hoạch điều trị; xác định các dấu hiệu và triệu chứng cần giới thiệu đến một bác sĩ y khoa hoặc chuyên gia y tế khác;', '- Ghi lại thông tin về tình trạng sức khỏe và đáp ứng với điều trị trong các hệ thống lưu giữ hồ sơ y tế của bệnh nhân;', '- Chia sẻ thông tin với các nhà cung cấp dịch vụ chăm sóc sức khỏe khác khi cần thiết để đảm bảo liên tục và chăm sóc toàn diện.']::text[], array['- Kỹ thuật viên gây mê', '- Tư vấn kế hoạch hóa gia đình', '- Tư vấn HIV', '- Kỹ thuật viên trị liệu hô hấp', 'Ghi chú:', 'Nghề nghiệp trong nhóm này thường yêu cầu đào tạo chính thức về cung cấp dịch vụ y tế.']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 198) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3311', 'Nhân viên môi giới, buôn bán chứng khoán và tài chính mua và bán chứng khoán, cổ phiếu, trái phiếu và các công cụ tài chính khác, thực hiện giao dịch ngoại hối tại chỗ hoặc trên thị trường tương lai, thay mặt công ty hoặc khách hàng trên cơ sở ủy nhiệm và đề xuất các giao dịch với khách hàng hoặc nhà quản lý cao cấp.', array['Nhận các thông tin về tình hình tài chính của khách hàng và công ty thực hiện đầu tư;', 'Phân tích xu hướng thị trường chứng khoán, trái phiếu, cổ phiếu và các công cụ tài chính khác bao gồm ngoại hối;', 'Thông tin cho khách hàng tiềm năng về điều kiện và triển vọng thị trường;', 'Tư vấn và tham gia đàm phán về các điều khoản và tổ chức cho vay cổ phiếu và trái phiếu trên thị trường để tăng vốn cho khách hàng;', 'Ghi và chuyển các đơn hàng mua, bán chứng khoán, cổ phiếu, trái phiếu, các công cụ tài chính khác và trao đổi ngoại hối trong tương lai hoặc tức thời.']::text[], array['- Nhân viên môi giới ngoại hối', '- Đại lý ngoại hối', '- Nhân viên môi giới chứng khoán', '- Nhân viên môi giới cổ phiếu']::text[], array['- Nhà phân tích trái phiếu - 2413', '- Nhân viên môi giới hàng hóa - 3324', '- Nhân viên phân phối hàng hóa tương lai - 3324', '- Nhân viên chứng khoán - 4312']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 222) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3312', 'Nhân viên phụ trách các khoản tín dụng và khoản vay phân tích, đánh giá thông tin, đơn xin vay vốn và quyết định thông qua hoặc từ chối khách hàng hoặc đề xuất để thông qua hoặc từ chối quản lý.', array['Phỏng vấn ứng viên để cho vay cá nhân, thế chấp, cho sinh viên và doanh nghiệp vay;', 'Nghiên cứu và đánh giá tình trạng tài chính của các ứng viên, điều khoản tham chiếu, uy tín và khả năng hoàn trả vốn vay;', 'Trình các đơn xin vay vốn với đề xuất thông qua hoặc từ chối; thông qua hoặc từ chối các đơn xin trong quyền hạn của mình đảm bảo các tiêu chuẩn của thể chế được coi trọng;', 'Giữ hồ sơ về việc hoàn trả, chuẩn bị thư đòi nợ thông thường đối với những khoản nợ quá hạn và thực hiện các nhiệm vụ pháp lý;', 'Hoàn tất hồ sơ vay vốn.']::text[], array['- Nhân viên cho vay', '- Nhân viên thế chấp']::text[], array['- Giám đốc chi nhánh tổ chức tài chính - 1731']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 240) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3313', 'Kế toán viên giữ các hồ sơ về giao dịch tài chính của hoạt động kinh doanh và xác nhận tính chính xác của tài liệu, hồ sơ liên quan đến giao dịch.', array['Lưu giữ các hồ sơ về giao dịch tài chính của hoạt động kinh doanh theo những quy tắc chung với sự chỉ dẫn của kế toán;', 'Xác nhận tính chính xác của tài liệu, hồ sơ liên quan đến thu chi và các giao dịch tài chính khác;', 'Chuẩn bị báo cáo tài chính cho từng giai đoạn cụ thể;', 'Áp dụng kiến thức về quy tắc chung và thực hành để xác định và giải quyết các vấn đề nảy sinh trong công việc;', 'Thực hiện những nhiệm vụ có liên quan.']::text[], array['- Trợ lý kế toán', '- Kế toán viên']::text[], array['- Kế toán - 2411', '- Trợ lý chuyên gia tính toán - 3314', '- Nhân viên kế toán - 4311']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 253) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3314', 'Nhân viên về thống kê và toán học ứng dụng có liên quan hỗ trợ lập kế hoạch thu thập, xử lý, giới thiệu các dữ liệu thống kê, toán học, thống kê bảo hiểm và thực hiện những hoạt động này, thường làm việc dưới sự hướng dẫn của các nhà thống kê, nhà toán học và nhà thống kê bảo hiểm.', array['Hỗ trợ trong kế hoạch và thực hiện các tính toán thống kê, toán học, thống kê bảo hiểm, kế toán và các tính toán liên quan;', 'Chuẩn bị các dự toán chi tiết về số lượng, chi phí nguyên vật liệu và nhân công theo yêu cầu cho các cuộc tổng điều tra thống kê và các hoạt động điều tra, khảo sát;', 'Thực hiện các công việc kỹ thuật liên quan đến thiết lập, duy trì và sử dụng các sổ sách và cỡ mẫu cho tổng điều tra và các hoạt động điều tra;', 'Thực hiện những công việc kỹ thuật liên quan tới thu thập số liệu, quản lý chất lượng các hoạt động của tổng điều tra và khảo sát;', 'Sử dụng các phần mềm tiêu chuẩn để thực hiện việc tính toán toán học, thống kê, thống kê bảo hiểm và các tính toán khác liên quan;', 'Chuẩn bị các tính toán toán học, thống kê, thống kê bảo hiểm và các kết quả khác cho việc trình bày bằng các dạng đồ thị hoặc bảng biểu;', 'Áp dụng kiến thức về thống kê, toán học, thống kê bảo hiểm, tính toán và các nguyên tắc liên quan và thực tế để xác định và giải quyết các vấn đề phát sinh trong công việc của họ;', 'Giám sát công việc của các nhân viên thống kê khác.']::text[], array['- Trợ lý chuyên gia tính toán', '- Trợ lý toán học', '- Trợ lý thống kê']::text[], array['- Chuyên gia tính toán - 2121', '- Nhà toán học - 2121', '- Nhà thống kê - 2122', '- Trợ lý kế toán - 3313', '- Nhân viên thống kê - 4312']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 268) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3315', 'Nhân viên định giá và đánh giá mức độ thiệt hại định giá tài sản và các hàng hóa khác, đánh giá thiệt hại được bảo hiểm đền bù.', array['Xác định chất lượng và giá trị của nguyên liệu thô, bất động sản, thiết bị công nghiệp, những ảnh hưởng cá nhân hoặc hộ gia đình, công trình nghệ thuật, đá quý và các tài sản khác;', 'Đánh giá quy mô thiệt hại, trách nhiệm của công ty bảo hiểm và người ký nhận trách nhiệm thanh toán các hợp đồng bảo hiểm đối với các thiệt hại do bảo hiểm chi trả;', 'Nhận các hồ sơ kinh doanh và giá trị của tài sản hoặc hàng hóa tương tự;', 'Kiểm tra hàng hóa và tài sản để đánh giá điều kiện, kích thước và cấu trúc;', 'Chuẩn bị báo cáo về giá trị, phác thảo những yếu tố đánh giá và phương pháp sử dụng.']::text[], array['- Thẩm định viên', '- Nhân viên đánh giá khiếu nại', '- Thanh tra yêu cầu bồi thường', '- Nhân viên giám định bảo hiểm', '- Nhân viên giám định bất động sản', '- Nhân viên định giá']::text[], array['- Nhân viên đấu giá - 3339']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 289) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3316', 'Thủ quỹ là người kiểm soát toàn bộ hoạt động thu chi phát sinh trong doanh nghiệp như kiểm tra phiếu Thu, phiếu Chi, ký xác nhận, giao các liên, tạm ứng… Thủ quỹ quản lý, lưu trữ toàn bộ giấy tờ liên quan khác trong quá trình này.', array['- Quản lý toàn bộ tiền mặt trong két sắt; quản lý chìa khóa két sắt an toàn; quản lý bảo trì, bảo dưỡng và các vấn đề có liên quan tới két sắt;', '- Phân loại và kiểm tra chất lượng tiền mặt, phát hiện tiền giả và báo cáo để giải quyết vấn đề về tiền giả;', '- Thực hiện việc thanh toán tiền mặt hàng ngày theo quy trình thanh toán của doanh nghiệp;', '- Thực hiện kiểm tra lần cuối về tính hợp pháp và hợp lý của chứng từ trước khi xuất, nhập tiền khỏi quỹ;', '- Thực hiện kiểm kê đối chiếu quỹ hàng ngày với kế toán tổng hợp;', '- Lưu trữ chứng từ thu chi tiền;', '- Làm việc với kế toán tổng hợp về số dư tồn quỹ nhằm phục vụ các mục tiêu kinh doanh hay đảm bảo việc chi trả lương, bảo hiểm, phúc lợi khác cho nhân viên;', '- Thực hiện các báo cáo định kỳ cho doanh nghiệp về quỹ tiền của doanh nghiệp và trình lên cấp trên;', '- Thực hiện các công việc khác do kế toán trưởng và giám đốc giao.']::text[], array['- Thủ quỹ']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 306) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3321', 'Nhân viên đại diện bảo hiểm tư vấn về bảo hiểm nhân thọ, tai nạn, ô tô, vốn, hỏa hoạn, tàu thủy và các loại bảo hiểm đến khách hàng mới và khách hàng đã có.', array['- Có được thông tin về tình trạng hiện tại của khách hàng để xác định loại bảo hiểm và điều kiện thích hợp;', '- Thương lượng với khách hàng để xác định loại và mức độ rủi ro mà bảo hiểm đòi hỏi;', '- Giải thích chi tiết bảo hiểm, điều kiện, rủi ro và thuận lợi khi khách hàng tham gia bảo hiểm;', '- Giúp khách hàng xác định loại và mức độ chi trả, tính phương thức thanh toán;', '- Thương lượng và đặt hợp đồng tái bảo hiểm;', '- Tư vấn, thương lượng và ký hợp đồng bảo hiểm cho các loại dự án lớn hoặc đặc biệt.']::text[], array['- Nhân viên đại lý bảo hiểm', '- Nhân viên môi giới bảo hiểm', '- Nhân viên bảo lãnh bảo hiểm']::text[], array['- Nhà quản lý đại lý bảo hiểm - 1747', '- Nhân viên môi giới chứng khoán - 3311', '- Nhân viên giám định bảo hiểm - 3315', '- Nhân viên bảo hiểm - 4312']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 323) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3322', 'Nhân viên đại diện bán hàng hóa thương mại bán nhiều loại hàng hóa và dịch vụ để kinh doanh và cung cấp thông tin chi tiết của sản phẩm khi có yêu cầu.', array['- Mời chào đặt hàng và bán hàng hóa cho các cơ sở bán lẻ, công nghiệp, bán buôn và các cơ sở khác;', '- Bán thiết bị, vật tư và dịch vụ liên quan cho các cơ sở kinh doanh hoặc cá nhân;', '- Cập nhật kiến thức về điều kiện thị trường, hàng hóa và dịch vụ của chủ và đối thủ cạnh tranh;', '- Cung cấp cho khách hàng tiềm năng thông tin về các đặc tính, chức năng của sản phẩm, thiết bị đển bán và thể hiện công dụng hoặc chất lượng của nó;', '- Báo giá, ghi lại đơn đặt hàng và sắp xếp giao hàng;', '- Báo cáo phản ứng và yêu cầu của khách hàng với nhà cung cấp và nhà sản xuất;', '- Theo dõi khách hàng để đảm bảo sự hài lòng với sản phẩm đã mua.']::text[], array['- Nhân viên tư vấn dịch vụ sau bán hàng;', '- Nhân viên chào hàng mua hàng hóa thương mại']::text[], array['- Nhà quản lý kinh doanh - 1744', '- Nhà chuyên môn đại diện bán hàng y tế - 2433', '- Nhà chuyên môn đại diện bán hàng kỹ thuật - 2433', '- Nhà chuyên môn về bán hàng hóa trong lĩnh vực công nghệ thông tin và truyền thông - 2434', '- Nhân viên trợ giúp bán hàng - 5223', '- Nhân viên đại diện bán hàng giao tận nhà - 5243']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 341) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3323', 'Nhân viên/đại lý mua hàng thay mặt cơ sở công nghiệp, thương mại, chính phủ và tổ chức khác mua hàng hóa và dịch vụ cho việc sử dụng hoặc bán lại.', array['Xác định hoặc thương lượng điều khoản, quyết định hợp đồng cung cấp hoặc hợp đồng hoa hồng cho việc mua thiết bị, nguyên liệu thô, sản phẩm, dịch vụ và hàng hóa để bán lại;', 'Thu thập thông tin về yêu cầu đặc điểm chất lượng và số lượng được mua, chi phí, ngày vận chuyển và điều kiện hợp đồng khác;', 'Mua thiết bị, nguyên liệu và dịch vụ thương mại nói chung hoặc chuyên biệt cho sử dụng hoặc chế biến của cơ sở;', 'Mời thầu, tư vấn với người cung cấp và báo giá;', 'Mua máy móc cho bán lại bởi cơ sở bán lẻ hoặc bán buôn;', 'Nghiên cứu báo cáo thị trường, xuất bản định kỳ của thương mại và buôn bán, thăm quan hội chợ, phòng trưng bày, nhà máy và sự kiện thiết kế sản phẩm;', 'Lựa chọn hàng hóa hoặc sản phẩm phù hợp nhất với yêu cầu của cơ sở;', 'Phỏng vấn người cung cấp và thương lượng về giá cả, chiết khấu, phương thức thanh toán và thỏa thuận vận chuyển;', 'Giám sát việc phân phối hàng hóa đến cửa hàng tiêu thụ sản phẩm và duy trì lượng lưu kho thích hợp;', 'Thiết lập lịch phân phối, giám sát các bước và liên hệ khách hàng và nhà cung cấp để giải quyết vấn đề.']::text[], array['- Nhân viên mua hàng', '- Nhân viên tìm nguồn hàng', '- Nhân viên đại lý mua', '- Nhân viên cung cấp']::text[], array['- Nhân viên môi giới hàng hóa - 3324']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 361) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3324', 'Nhân viên môi giới thương mại mua và bán hàng hóa, dịch vụ vận chuyển thường khối lượng lớn, thay mặt công ty riêng của họ hoặc cho khách hàng trên cơ sở hợp đồng.', array['Lập hợp đồng giữa người mua và người bán hàng hóa;', 'Bàn với người mua và người bán yêu cầu về khách hàng và đưa ra tư vấn phù hợp;', 'Mua và bán không gian hàng hóa trên tàu;', 'Thương lượng mua và bán hàng hóa và hàng hóa tương lai;', 'Tìm không gian cho hàng hóa lưu kho và đàm phán phí xếp dỡ, vận chuyển và lưu trữ;', 'Giám sát và phân tích xu hướng thị trường và các yếu tố khác ảnh hưởng đến cung và cầu hàng hóa và dịch vụ vận chuyển.']::text[], array['Nhân viên môi giới hàng hóa', 'Nhân viên phân phối hàng hóa tương lai', 'Nhân viên môi giới vận chuyển']::text[], array['Nhân viên môi giới tài chính - 3311', 'Giao dịch viên tài chính - 3311', 'Nhân viên môi giới chứng khoán - 3311', 'Giao dịch viên chứng khoán - 3311', 'Giao dịch viên bảo hiểm - 3321']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 381) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3331', 'Nhân viên làm thủ tục thông quan và vận tải hàng hóa thực hiện các quy trình miễn thuế và đảm bảo bảo hiểm, các giấy phép xuất/nhập khẩu và các thủ tục khác hợp lệ.', array['- Tiến hành các thủ tục miễn thuế cho hàng xuất và nhập khẩu;', '- Đảm bảo đúng thủ tục bảo hiểm;', '- Đảm bảo các giấy phép xuất, nhập khẩu và các thủ tục khác hợp lệ;', '- Ký và phát hành vận đơn;', '- Kiểm tra tài liệu xuất/nhập khẩu để xác định loại hàng, phân loại hàng hóa thành các loại phí và thuế quan khác nhau, sử dụng hệ thống mã số thuế.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 403) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3332', 'Nhân viên tổ chức hội thảo và sự kiện tổ chức và kết hợp các dịch vụ cho các cuộc hội thảo, sự kiện, các buổi họp mặt và buổi tiệc.', array['Xúc tiến các cuộc hội thảo, hội nghị và triển lãm thương mại cho khách hàng tiềm năng;', 'Trả lời các thắc mắc liên quan đến các dịch vụ được cung cấp và chi phí cho việc thuê phòng và thiết bị, ăn uống và các dịch vụ có liên quan;', 'Gặp gỡ khách hàng để thảo luận về nhu cầu của họ, đưa ra những lựa chọn trọn gói để đáp ứng những nhu cầu đó;', 'Sắp xếp và kết hợp các dịch vụ như cơ sở vật chất của hội nghị, ăn uống, trang trí, trưng bày, các thiết bị nghe nhìn, máy tính, phòng ốc, phương tiện đi lại và các sự kiện xã hội cho người tham gia; sắp xếp hậu cần cho người dẫn chương trình;', 'Tổ chức đăng ký cho người tham gia;', 'Đàm phán về loại hình và chi phí dịch vụ trong phạm vi ngân sách cấp;', 'Giám sát công việc của các nhà thầu và báo cáo những thay đổi trong công việc.']::text[], array['- Nhân viên tổ chức sự kiện và hội nghị', '- Nhân viên lên kế hoạch hội nghị', '- Nhân viên tổ chức tiệc cưới']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 411) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3333', 'Nhân viên giới thiệu việc làm và nhà thầu kết nối người tìm việc với các công việc cần người, tìm người cho các nhà tuyển dụng và hợp đồng lao động với những dự án cụ thể theo yêu cầu của doanh nghiệp và các tổ chức khác bao gồm chính phủ, các thể chế và tìm việc cho người tìm việc theo ủy nhiệm.', array['- Kết nối người tìm việc với các công việc cần người;', '- Tìm người cho các vị trí còn trống theo ủy quyền của nhà tuyển dụng hoặc người làm việc;', '- Bàn bạc với các doanh nghiệp/tổ chức những kỹ năng cần thiết và những đặc điểm của người được tuyển dụng hay hợp đồng;', '- Tìm người có những kỹ năng phù hợp; thực hiện các thủ tục cần thiết theo những quy định và yêu cầu quốc gia và quốc tế;', '- Bảo đảm hợp đồng tuyển dụng phù hợp với các yêu cầu pháp lý và ký kết hợp đồng;', '- Tư vấn kế hoạch đào tạo.']::text[], array['- Đại lý việc làm', '- Nhân viên giới thiệu việc làm', '- Nhà thầu lao động']::text[], array['- Nhà tư vấn nghề nghiệp - 2423', '- Nhà phân tích nghề nghiệp - 2423', '- Nhân viên đại lý văn học - 3339', '- Nhân viên đại lý biểu diễn âm nhạc - 3339', '- Nhân viên đại lý thể thao - 3339', '- Nhân viên đại lý sân khấu - 3339']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 425) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3334', 'Nhân viên môi giới bất động sản và quản lý tài sản/bất động sản sắp xếp các cuộc mua bán, cho thuê tài sản thực tế, thương lượng thay mặt khách hàng và trên cơ sở ủy quyền.', array['Nhận thông tin về các tài sản được bán hoặc cho thuê, hoàn cảnh của chủ tài sản và nhu cầu của người mua hay thuê tiềm năng;', 'Giới thiệu tài sản được bán và cho thuê đến người mua và thuê tiềm năng; giải thích các điều khoản kinh doanh hoặc các điều kiện cho thuê;', 'Sắp xếp các thỏa thuận và chuyển nhượng quyền sở hữu tài sản;', 'Thu tiền cho thuê và tiền khế ước thay mặt chủ tài sản; kiểm tra tài sản trước, trong thời gian và sau khi thuê;', 'Bảo đảm có sẵn nhân công để thực hiện việc bảo quản tài sản.']::text[], array['- Đại lý bất động sản', '- Nhân viên quản lý tài sản', '- Nhân viên môi giới', '- Nhân viên bán hàng (bất động sản)']::text[], array['- Nhân viên thế chấp - 4312']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 445) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3339', 'Nhân viên đại lý dịch vụ kinh doanh khác chưa được phân vào đâu có thể bao gồm những người thiết lập quan hệ kinh doanh, bán dịch vụ kinh doanh như không gian quảng cáo trên các phương tiện, sắp xếp hợp đồng trình diễn cho vận động viên, nghệ sĩ, ca sĩ cũng như việc phát hành sách, sản xuất kịch, thu thanh, trình diễn hay bán đĩa nhạc. Nhóm này cũng bao gồm những người bán các loại hàng hóa, vật dụng và tài sản bằng hình thức đấu giá.', array['Nhận thông tin về dịch vụ để bán và nhu cầu của khách hàng tiềm năng;', 'Thay mặt người mua và người bán đàm phán các hợp đồng và giải thích các điều khoản mua, bán cho khách hàng;', 'Ký kết thỏa thuận hợp tác thay mặt cho người mua hoặc bán và đảm bảo hợp đồng được thực hiện theo đúng cam kết;', 'Đảm bảo dịch vụ kinh doanh được mua sẵn có với người mua theo hình thức và thời gian thỏa thuận;', 'Bán đấu giá các loại tài sản, xe hơi, đồ dùng, vật nuôi, đồ nghệ thuật, nữ trang và các vật dụng khác.', 'Tổ chức nhóm du lịch cho kinh doanh hoặc tham quan; đặt vé nơi ở và những chuyến du lịch lớn.']::text[], array['- Nhân viên kinh doanh quảng cáo', '- Nhân viên đấu giá', '- Nhân viên đại lý văn học', '- Nhân viên đại lý biểu diễn âm nhạc', '- Nhân viên đại lý thể thao', '- Nhân viên đại lý sân khấu', '- Nhân viên tổ chức tua du lịch.']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 460) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3341', 'Giám sát viên văn phòng giám sát và điều phối các hoạt động của người làm việc trong nhóm 4: Nhân viên trợ lý văn phòng.', array['- Điều phối, phân công và xem xét các công việc của nhân viên liên quan đến các nhiệm vụ sau: xử lý văn bản; lưu giữ và ghi sổ sách; vận hành điện thoại và tổng đài điện thoại; nhập số liệu và các hoạt động liên quan đến các kỹ năng văn phòng và hành chính nói chung;', '- Lập kế hoạch các thủ tục công việc và các hoạt động điều phối với các phòng, ban khác;', '- Giải quyết các vấn đề liên quan tới công việc và chuẩn bị thủ tục trình và báo cáo khác;', '- Đào tạo và hướng dẫn người làm các nhiệm vụ cần thực hiện, các quy trình về an toàn và các chính sách của công ty; sắp xếp bố trí các khóa đào tạo;', '- Đánh giá việc thực hiện công việc của nhân công có đúng theo các quy định, hướng dẫn và khuyến nghị các hoạt động nhân sự thích hợp;', '- Tuyển dụng, phỏng vấn và lựa chọn người làm công.']::text[], array['- Giám sát viên văn phòng', '- Giám sát viên nhập dữ liệu', '- Giám sát viên văn thư', '- Giám sát viên nhân sự']::text[], array['- Giám sát viên hồ sơ y tế - 3252']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 480) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3342', 'Thư ký luật hỗ trợ lãnh đạo đơn vị và các thành viên khác trong việc thực hiện và hỗ trợ việc liên lạc, dẫn chứng tài liệu và các hoạt động điều phối quản lý nội bộ, trong các văn phòng luật, các phòng, ban pháp luật của các công ty lớn và của chính phủ.', array['Chuẩn bị và xử lý các tài liệu và hồ sơ pháp luật như là các chứng thư, di chúc, bản khai có tuyên thệ và bản tóm tắt hồ sơ vụ kiện;', 'Xem xét, đọc, sửa bản in thử và thư từ liên lạc để bảo đảm phù hợp với các thủ tục pháp luật quy định;', 'Gửi mail, fax hoặc sắp xếp chuyển các thư từ luật pháp đến khách hàng, các nhân chứng và các nhân viên tòa án;', 'Tổ chức và bảo quản tài liệu, hồ sơ vụ kiện và các thư viện luật;', 'Xem xét yêu cầu về hội họp, lên kế hoạch và tổ chức họp;', 'Hỗ trợ trong việc chuẩn bị ngân sách, giám sát chi phí, dự thảo hợp đồng và mua sắm theo yêu cầu;', 'Hỗ trợ lãnh đạo các đơn vị và các cán bộ khác trả lời các câu hỏi về bản chất hành chính và tổ chức;', 'Giám sát các nhân viên văn phòng khác.']::text[], array['- Quản lý hành nghề pháp lý', '- Thư ký pháp lý']::text[], array['- Trợ giúp pháp lý - 3411']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 496) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3343', 'Thư ký hành chính và điều hành thực hiện và hỗ trợ việc liên lạc, dẫn chứng tài liệu và các hoạt động điều phối quản lý nội bộ của một đơn vị tổ chức để hỗ trợ lãnh đạo của đơn vị và các nhân viên khác.', array['Dự thảo thư từ và biên bản hành chính;', 'Thu xếp, đề xuất và giám sát thời hạn cuối cùng và thực hiện theo kế hoạch đó;', 'Xem xét các yêu cầu cuộc họp, lập kế hoạch và tổ chức cuộc họp; bố trí sắp xếp các cuộc hẹn cho lãnh đạo và nhân viên khác;', 'Hỗ trợ việc chuẩn bị ngân sách, giám sát chi phí, dự thảo hợp đồng và mua sắm theo yêu cầu;', 'Hỗ trợ lãnh đạo đơn vị và các nhân viên khác trả lời các câu hỏi về bản chất hành chính và tổ chức;', 'Hỗ trợ lãnh đạo đơn vị hoặc các nhân viên khác tổ chức và tiếp đón khách đến thăm;', 'Giữ liên lạc với nhân viên khác về các vấn đề liên quan tới hoạt động của tổ chức;', 'Viết và trả lời thư kinh doanh hoặc kỹ thuật và các thư từ tương tự khác;', 'Chuẩn bị các báo cáo nguyên văn của các biên bản lưu trong hội đồng lập pháp, tòa án luật hoặc các nơi khác bằng tốc ký hoặc các loại khác;', 'Giám sát công việc của các nhân viên văn phòng khác.']::text[], array['- Thư ký hành chính', '- Báo cáo viên tòa án', '- Thư ký điều hành', '- Trợ giúp nhân sự']::text[], array['- Thư ký y tế - 3344', '- Thư ký (tổng hợp) - 4120']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 512) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3344', 'Thư ký y tế sử dụng các kiến thức chuyên ngành của thuật ngữ và thủ tục y khoa hỗ trợ lãnh đạo đơn vị và các nhân viên khác trong việc thực hiện và hỗ trợ các hoạt động liên lạc, dẫn chứng tài liệu, các hoạt động điều phối quản lý quốc tế, trong văn phòng bác sỹ, bệnh viện, phòng khám y khoa và các cơ sở y tế khác.', array['Lập kế hoạch, xác nhận các cuộc hẹn y khoa, chuyển các thông báo, tin nhắn cho các nhân viên y tế và các bệnh nhân;', 'Biên soạn, ghi nhận, xem xét đánh giá các biểu đồ y tế, các báo cáo, tài liệu và thư từ y khoa;', 'Phỏng vấn bệnh nhân để hoàn thiện mẫu biểu, tài liệu và các bệnh án;', 'Hoàn thiện các biểu mẫu bảo hiểm và các mẫu đơn yêu cầu khác;', 'Bảo quản hồ sơ bệnh lý, các hồ sơ khác và thư viện kỹ thuật;', 'Chuẩn bị các báo cáo tài chính, các thủ tục thanh toán và hóa đơn khác;', 'Hỗ trợ chuẩn bị ngân sách, chuẩn bị báo cáo tài chính và các thủ tục thanh toán; dự thảo hợp đồng và thực hiện các yêu cầu mua sắm;', 'Giám sát các nhân viên văn phòng khác.']::text[], array['Thư ký nha khoa', 'Thư ký trông nom buồng bệnh nhân', 'Thư ký hóa đơn bảo hiểm y tế', 'Thư ký phòng thí nghiệm y tế', 'Trợ lý hành chính y tế', 'Quản lý thực tập sinh y tế', 'Thư ký y tế', 'Nhân viên viết hồ sơ y tế', 'Thư ký bệnh lý học', 'Thư ký chăm sóc bệnh nhân']::text[], array['Kỹ thuật viên hồ sơ y tế - 3252', 'Phụ tá y tế - 3256', 'Thư ký (tổng hợp) - 4120', 'Nhân viên lễ tân y tế - 4226']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 533) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3351', 'Nhân viên hải quan của Chính phủ kiểm tra người và xe qua biên giới quốc gia quản lý và thực thi các quy định pháp luật liên quan.', array['- Thực hiện kiểm tra, giám sát hải quan; giám sát việc mở, đóng, chuyển tải, xếp dỡ hàng hóa tại địa điểm làm thủ tục hải quan và địa điểm kiểm tra hàng hóa xuất khẩu, nhập khẩu; trong trường hợp phát hiện có dấu hiệu vi phạm pháp luật về hải quan thì yêu cầu chủ hàng hóa, chủ phương tiện vận tải, người chỉ huy, người điều khiển phương tiện vận tải hoặc người được ủy quyền thực hiện các yêu cầu để kiểm tra, khám xét hàng hóa, phương tiện vận tải theo quy định của pháp luật;', '- Lấy mẫu hàng hóa với sự có mặt của người khai hải quan để cơ quan hải quan phân tích hoặc trưng cầu giám định phục vụ kiểm tra hải quan;', '- Yêu cầu người khai hải quan cung cấp thông tin, chứng từ liên quan đến hàng hóa để xác định đúng mã số, xuất xứ, trị giá hải quan của hàng hóa;', '- Yêu cầu người chỉ huy, người điều khiển phương tiện vận tải đi đúng tuyến đường, đúng thời gian, dừng đúng nơi quy định;', '- Hướng dẫn người khai hải quan, tổ chức, cá nhân có liên quan khi có yêu cầu.']::text[], array['- Thanh tra biên giới', '- Thanh tra hải quan', '- Nhân viên hải quan', '- Nhân viên kiểm tra hộ chiếu']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 563) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3352', 'Nhân viên thuế của Chính phủ kiểm tra thuế, hóa đơn bán hàng và các tài liệu khác để xác định tiền thuế, miễn thuế và các loại phí, lệ phí được trả bởi cá nhân hoặc các doanh nghiệp.', array['- Thu thuế và các khoản thu khác thuộc ngân sách nhà nước theo quy định của pháp luật;', '- Giải thích, cung cấp thông tin liên quan đến việc xác định nghĩa vụ thuế cho người nộp thuế, mức thuế phải nộp và các thủ tục về thuế;', '- Bảo mật thông tin của người nộp thuế, trừ các thông tin cung cấp cho cơ quan có thẩm quyền hoặc thông tin được công bố công khai theo quy định của pháp luật;', '- Hướng dẫn hồ sơ, thủ tục về miễn thuế, giảm thuế, xóa nợ tiền thuế, tiền chậm nộp, tiền phạt; miễn tiền chậm nộp, tiền phạt, không tính tiền chậm nộp; gia hạn nộp thuế; nộp dần tiền thuế nợ; khoanh tiền thuế nợ, không thu thuế; xử lý tiền thuế, tiền chậm nộp, tiền phạt nộp thừa; hoàn thuế theo quy định của pháp luật;', '- Giải quyết khiếu nại, tố cáo liên quan đến việc thực hiện pháp luật về thuế theo thẩm quyền;', '- Giao biên bản, kết luận, quyết định xử lý về thuế sau kiểm tra thuế, thanh tra thuế cho người nộp thuế và giải thích khi có yêu cầu.']::text[], array['- Thanh tra thuế', 'Nhân viên thuế']::text[], array['Kế toán - 2411', 'Kiểm toán - 2411']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 576) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3353', 'Nhân viên trợ cấp xã hội của Chính phủ kiểm tra ứng dụng các chương trình của Chính phủ, tài chính hoặc dịch vụ để xác định đủ điều kiện và số tiền của các lợi ích hay dịch vụ thích hợp.', array['- Tư vấn cá nhân và các tổ chức về pháp luật, quy tắc và quy định của chính phủ liên quan đến chương trình phúc lợi của chính phủ; giải ngân các khoản thanh toán hoặc giới thiệu các dịch vụ cũng như quyền và nghĩa vụ;', '- Kiểm tra các ứng dụng và các tài liệu khác có liên quan để xác định loại và số lượng phúc lợi mà cá nhân có đủ điều kiện để nhận được;', '- Đánh giá tài liệu và phỏng vấn người nhận phúc lợi để đảm bảo tiếp tục đủ điều kiện lợi ích hay dịch vụ;', '- Thực hiện nhiệm vụ hành chính liên quan để duy trì hồ sơ khách hàng và chuẩn bị báo cáo về các quyết định đủ điều kiện, quyết định giới thiệu, chấm dứt quyền lợi và lạm dụng hoặc gian lận.']::text[], array['- Nhân viên về hưu trí', '- Nhân viên về phúc lợi xã hội', '- Nhân viên bồi thường an sinh xã hội']::text[], array['- Nhà chuyên môn về tư vấn và công tác xã hội - 2635', '- Nhà chuyên môn về xã hội - 2635']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 591) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3354', 'Nhân viên cấp phép của Chính phủ kiểm tra các ứng dụng của các giấy phép để xuất khẩu hoặc nhập khẩu hàng hóa, thành lập doanh nghiệp, xây dựng nhà ở, công trình khác hoặc để có được hộ chiếu; xác định các điều kiện của các ứng dụng cho phát hành các giấy phép hoặc hộ chiếu; xác định điều kiện cụ thể hoặc hạn chế để được gắn liền với giấy phép phát hành.', array['- Tư vấn cá nhân về pháp luật và các quy định của chính phủ liên quan đến các loại giấy phép cần thiết và các điều kiện kèm theo giấy phép đó về quyền và nghĩa vụ;', '- Kiểm tra các ứng dụng, tài liệu liên quan và xác định liệu có thể cấp giấy phép và các điều kiện đính kèm;', '- Kiểm tra các ứng dụng và phê duyệt các vấn đề của hộ chiếu;', '- Thực hiện các công việc hành chính liên quan để xử lý các ứng dụng, tài liệu hoạt động, đánh giá và quyết định và để chuẩn bị các thư từ để thông báo cho người nộp đơn quyết định cấp phép;', '- Quản lý và ghi kiểm tra cần thiết để cấp giấy phép.']::text[], array['Nhân viên về giấy phép xây dựng', 'Nhân viên về giấy phép kinh doanh', 'Nhân viên về văn bằng', 'Nhân viên hộ chiếu (phát hành)']::text[], array['Thanh tra xây dựng - 3112', 'Thanh tra phòng cháy - 3112']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 605) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3355', 'Kiểm lâm là lực lượng chuyên trách của Nhà nước có chức năng bảo vệ rừng, giúp Chủ tịch Ủy ban nhân dân cấp huyện thực hiện quản lý nhà nước về bảo vệ rừng, bảo đảm chấp hành pháp luật về bảo vệ và phát triển rừng.', array['- Tham mưu cho người đứng đầu Kiểm lâm cấp tỉnh và Ủy ban nhân dân cấp huyện;', '- Tổ chức thực hiện các nhiệm vụ về quản lý, bảo vệ rừng, phòng cháy và chữa cháy rừng, bảo đảm chấp hành pháp luật về lâm nghiệp trên phạm vi địa bàn được giao quản lý;', '- Quản lý, chỉ đạo hoạt động của Trạm Kiểm lâm và Kiểm lâm làm việc tại địa bàn thực hiện các nhiệm vụ tham mưu, giúp Chủ tịch Ủy ban nhân dân cấp xã tổ chức thực hiện văn bản quy phạm pháp luật, chương trình, kế hoạch, phương án về quản lý, bảo vệ rừng, phòng cháy và chữa cháy rừng, bảo đảm chấp hành pháp luật về lâm nghiệp;', '- Thực hiện các nhiệm vụ khác theo quy định của pháp luật và cơ quan nhà nước có thẩm quyền giao.']::text[], '{}'::text[], array['- Nhân viên bảo vệ rừng - 5409.']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 621) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3359', 'Nhân viên điều tiết của chính phủ khác chưa được phân vào đâu bao gồm các nhân viên điều tiết về nông nghiệp, ngư nghiệp, lâm nghiệp, giá cả, lương…', array['- Kiểm tra địa điểm kinh doanh để đảm bảo sử dụng đúng trọng lượng và các biện pháp trong thương mại;', '- Giám sát quy định về giá để đánh giá các chi phí thích hợp cho hàng hóa và dịch vụ bảo vệ lợi ích người tiêu dùng;', '- Giám sát các quy định mức lương đảm bảo mức độ thích hợp để trả cho công việc thực hiện và đánh giá tuân thủ pháp luật về tiêu chuẩn tuyển dụng;', '- Thực hiện nhiệm vụ liên quan đến điều tra và hành chính để ghi lại các kết quả, vấn đề tuân thủ tài liệu hoặc thực tiễn kinh doanh không phù hợp, chuẩn bị báo cáo và thư từ.']::text[], array['Thanh tra nông nghiệp', 'Thanh tra thủy sản', 'Thanh tra lâm nghiệp', 'Thanh tra giá cả', 'Thanh tra lương', 'Thanh tra đo lường']::text[], array['Thanh tra phòng cháy - 3112', 'Thanh tra y tế - 3257', 'Thanh tra sức khỏe nghề nghiệp và an toàn lao động - 3527', 'Thanh tra môi trường - 3257', 'Thanh tra vệ sinh - 3257']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 630) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3411', 'Nhân viên về luật pháp thực hiện chức năng hỗ trợ tại tòa án hoặc trong văn phòng luật, cung cấp các dịch vụ liên quan đến các vấn đề pháp lý như hợp đồng bảo hiểm, chuyển giao tài sản, việc cấp các khoản vay và các giao dịch tài chính hoặc tiến hành điều tra cho khách hàng.', array['- Tài liệu về thủ tục tố tụng tòa án và bản án;', '- Phục vụ báo cáo của các bồi thường, hầu tòa, bảo đảm, trát lệnh và các lệnh tòa;', '- Việc duy trì trật tự tại tòa án và phòng cách ly;', '- Chuẩn bị các văn bản pháp luật bao gồm cả thử nghiệm tóm tắt, biện hộ, kháng cáo, bản di chúc và các hợp đồng; chuẩn bị giấy tờ tổng kết pháp lý các vị trí hoặc thiết lập các điều kiện của các khoản vay hoặc bảo hiểm;', '- Điều tra các sự kiện, tổng hợp các bằng chứng và nghiên cứu quy chế có liên quan, quyết định và các văn bản quy phạm pháp luật để áp dụng cho từng trường hợp;', '- Tư vấn cho khách hàng về các vấn đề pháp lý;', '- Kiểm tra các tài liệu như thế chấp, quyền của chủ nợ, hợp đồng và bản đồ để kiểm tra mô tả pháp lý của tài sản và quyền sở hữu;', '- Chuẩn bị tài liệu liên quan đến chuyển giao bất động sản, chứng khoán hoặc các vấn đề đòi hỏi phải có đăng ký chính thức;', '- Có thể điều tra các trường hợp liên quan đến hành vi trộm cắp hàng hóa, tiền, thông tin từ cơ sở kinh doanh và các hành vi trái pháp luật khác của khách hàng hoặc nhân viên;', '- Điều tra cơ sở hoặc hoàn cảnh và hành vi của người đại diện cho khách hàng.']::text[], array['Chấp hành viên', 'Thư ký thẩm phán', 'Thư ký soạn thảo giấy tờ chuyển nhượng', 'Thư ký tòa án', '- Trợ lý pháp lý', '- Người giúp việc cho luật sư', '- Thám tử tư', '- Người rà soát quyền sở hữu']::text[], array['Luật sư - 2611', 'Công chứng viên - 2619', 'Thư ký luật - 3342']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 656) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3412', 'Nhân viên về công tác xã hội quản lý và thực hiện chương trình hỗ trợ xã hội và các dịch vụ cộng đồng; hỗ trợ khách hàng để đối phó với những vấn đề cá nhân và xã hội.', array['- Thu thập thông tin liên quan đến nhu cầu của khách hàng và đánh giá các kỹ năng có liên quan, điểm mạnh và điểm yếu;', '- Giúp người khuyết tật hay người già để có được dịch vụ cải thiện khả năng của mình đối với xã hội;', '- Hỗ trợ khách hàng để xác định lựa chọn và xây dựng kế hoạch hành động bằng việc cung cấp các hỗ trợ cần thiết;', '- Hỗ trợ khách hàng xác định và truy cập vào nguồn lực cộng đồng bao gồm trợ giúp pháp lý, y tế, tài chính, nhà ở, việc làm, giao thông vận tải, giúp di chuyển, chăm sóc ban ngày và giới thiệu các dịch vụ khác;', '- Tư vấn khách hàng sống trong nhóm nhà tạm, giám sát hoạt động của họ và kế hoạch hỗ trợ;', '- Tham gia lựa chọn và đăng ký của các khách hàng đối với chương trình phù hợp;', '- Cung cấp sự can thiệp khủng hoảng và các dịch vụ trú ẩn khẩn cấp;', '- Thực hiện các cuộc hội thảo kỹ năng sống, chương trình điều trị nghiện ma túy, chương trình quản lý hành vi, các chương trình dịch vụ thanh thiếu niên và các chương trình cộng đồng và xã hội dưới sự giám sát của công tác xã hội hoặc chuyên gia chăm sóc sức khỏe;', '- Hỗ trợ việc đánh giá hiệu quả của các biện pháp can thiệp và các chương trình giám sát; báo cáo về sự tiến bộ của khách hàng;', '- Duy trì liên lạc với các cơ quan dịch vụ xã hội, trường học và chăm sóc sức khỏe khác liên quan đến khách hàng để cung cấp thông tin và nhận được phản hồi về tình hình và tiến độ tổng thể của khách hàng.']::text[], array['Nhân viên phát triển cộng đồng', 'Nhân viên dịch vụ cộng đồng', 'Nhân viên can thiệp khủng hoảng', 'Nhân viên về dịch vụ cho người khuyết tật', 'Nhân viên dịch vụ gia đình', 'Nhân viên hướng dẫn kỹ năng sống', 'Nhân viên hỗ trợ sức khỏe thể lực', 'Nhân viên hỗ trợ phúc lợi', 'Nhân viên giám sát mái ấm cho phụ nữ', 'Nhân viên về dịch vụ thanh niên']::text[], array['Nhà chuyên môn về tư vấn hôn nhân - 2635', 'Nhà quản chế - 2635', 'Nhà chuyên môn về xã hội - 2635']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 682) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3413', 'Nhân viên về tôn giáo cung cấp hỗ trợ cho người đứng đầu tôn giáo hay một cộng đồng tôn giáo thực hiện công tác tôn giáo, thuyết giảng và tuyên truyền những lời dạy của một tôn giáo cụ thể và cố gắng để cải thiện phúc lợi thông qua sức mạnh của đức tin và tinh thần.', array['- Thực hiện công tác tôn giáo;', '- Thuyết giảng và tuyên truyền những lời dạy của một niềm tin tôn giáo cụ thể;', '- Hỗ trợ tại các dịch vụ công cộng thờ phụng và nghi lễ tôn giáo;', '- Cung cấp giáo dục tôn giáo, hướng dẫn tâm linh và hỗ trợ giáo dục đạo đức cho các cá nhân và cộng đồng;', '- Quản lý và tham gia vào các chương trình để cung cấp thực phẩm, quần áo và nơi ở cho những người có nhu cầu;', '- Tư vấn cho cộng đồng và cá nhân về hành vi đúng đắn và để duy trì niềm tin hay cải thiện được;', '- Chữa bệnh bằng đức tin.']::text[], array['- Người chữa lành đức tin', '- Người thuyết giáo', '- Nhà sư', '- Nữ tu']::text[], array['- Sư trụ trì - 2636', '- Giáo sĩ Hồi giáo - 2636', '- Trưởng ban tôn giáo - 2636', '- Linh mục - 2636', '- Giáo sĩ do thái - 2636', '- Người trồng và bán thảo dược - 3230', '- Thầy lang - 3230', '- Thầy mo - 3230']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 710) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3421', 'Vận động viên và người chơi thể thao tham gia vào sự kiện thi đấu thể thao. Họ luyện tập và thi đấu cá nhân hoặc đồng đội theo cách họ chọn.', array['- Tham gia các sự kiện thi đấu thể thao;', '- Tham gia vào các khóa huấn luyện và thực hành thường xuyên và thực hiện đào tạo riêng để duy trì các tiêu chuẩn yêu cầu của tập thể dục và kỹ năng;', '- Thực hiện các hoạt động quảng cáo thể thao và phỏng vấn truyền thông;', '- Duy trì mức độ cao về chuyên môn trong một môn thể thao cụ thể;', '- Tham khảo ý kiến của huấn luyện viên để ra những quyết định chiến lược;', '- Đánh giá các đối thủ cạnh tranh và các điều kiện thi đấu;', '- Cạnh tranh trong thể thao sự kiện;', '- Tuân thủ các quy tắc và quy định liên quan đến một môn thể thao cụ thể.']::text[], array['Vận động viên điền kinh', 'Vận động viên đua xe đạp', 'Vận động viên quyền anh', 'Vận động viên cờ tướng', 'Cầu thủ đá bóng', 'Vận động viên chơi golf', 'Vận động viên chơi khúc quân cầu', 'Vận động viên đua xe', 'Vận động viên quần vợt']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 737) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3422', 'Huấn luyện viên, nhân viên hướng dẫn thể thao và làm việc trong lĩnh vực thể thao làm việc với vận động viên thể thao chuyên nghiệp hoặc người đam mê thể thao để nâng cao hiệu suất và khuyến khích sự phát triển trong thể thao; tổ chức và trọng tài trong các sự kiện theo quy định của thể thao.', array['- Xác định những điểm mạnh và điểm yếu của vận động viên hoặc đội thể thao;', '- Lập kế hoạch và triển khai thực hiện đào tạo và các buổi thực hành;', '- Triển khai kế hoạch, lịch trình thi đấu và chương trình phối hợp;', '- Thúc đẩy và chuẩn bị các vận động viên hoặc đội cho các sự kiện thi đấu hoặc các trò chơi;', '- Xây dựng chiến lược cạnh tranh, phát triển kế hoạch và chỉ đạo các vận động viên và cầu thủ trong thi đấu hoặc các sự kiện thể thao;', '- Phân tích các vận động viên hoặc đội trong khi thi đấu và chỉnh sửa các chương trình đào tạo;', '- Giám sát và phân tích hiệu suất kỹ thuật và xác định cải thiện trong tương lai như thế nào;', '- Cử hành tại các sự kiện thể thao hoặc cuộc thi thể thao để duy trì tiêu chuẩn thi đấu và để đảm bảo luật và quy định được giám sát;', '- Ghi lại thời gian đã qua và số điểm trong các sự kiện hay các cuộc thi;', '- Đánh giá đối thủ cạnh tranh, trao điểm, áp đặt hình phạt đối với những vi phạm và xác định kết quả;', '- Biên soạn điểm và hồ sơ thể thao khác.']::text[], array['- Trọng tài', '- Huấn luyện viên trượt tuyết', '- Huấn luyện viên thể thao', '- Cán bộ thể thao', '- Huấn luyện viên bơi lội']::text[], array['Hướng dẫn viên thể dục - 3423', 'Hướng dẫn viên đua ngựa - 3423']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 758) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3423', 'Người hướng dẫn tập luyện và giải trí, người chỉ đạo chương trình hướng dẫn các nhóm và cá nhân trong thể dục, vui chơi giải trí hoặc các hoạt động mạo hiểm ngoài trời.', array['- Lập kế hoạch và thực hiện các hoạt động giải trí và thể dục;', '- Giám sát vui chơi giải trí, hoạt động thể dục thể thao để đảm bảo an toàn và cung cấp ứng cứu hoặc hỗ trợ cấp cứu khi có yêu cầu;', '- Đánh giá và giám sát khả năng của khách hàng và đề xuất các hoạt động;', '- Làm mẫu và giảng dạy các chuyển động cơ thể, các khái niệm và kỹ năng sử dụng trong thói quen thể dục và các hoạt động vui chơi giải trí;', '- Hướng dẫn sử dụng thiết bị;', '- Giải thích và thực thi các quy trình an toàn, nội quy và quy định.']::text[], array['- Hướng dẫn viên thể dục nhịp điệu', '- Hướng dẫn viên thể dục thẩm mỹ', '- Hướng dẫn viên đua ngựa', '- Hướng dẫn viên các hoạt động mạo hiểm ngoài trời', '- Hướng dẫn viên cá nhân', '- Hướng dẫn viên chèo thuyền', '- Hướng dẫn viên lặn']::text[], array['Huấn luyện viên trượt tuyết - 3422', 'Huấn luyện viên bơi lội - 3422']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 781) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3431', 'Nhiếp ảnh gia chụp ảnh tĩnh con người, sự kiện, cảnh, vật liệu, sản phẩm và các đối tượng khác.', array['- Chụp ảnh cho quảng cáo hoặc các mục đích thương mại, công nghiệp và khoa học khác; để minh họa cho câu chuyện và bài viết trên các tờ báo, tạp chí và các ấn phẩm khác;', '- Chụp ảnh chân dung của người và nhóm người;', '- Nghiên cứu yêu cầu của một nhiệm vụ cụ thể và quyết định loại máy ảnh, phim, ánh sáng và nền phụ kiện được sử dụng;', '- Xác định bố cục hình ảnh, điều chỉnh kỹ thuật đối với thiết bị và máy ảnh;', '- Sử dụng máy quét để chuyển hình ảnh nhiếp ảnh đến máy vi tính;', '- Sử dụng máy tính để thao tác hình ảnh nhiếp ảnh;', '- Tương thích với hình ảnh nhiếp ảnh hiện có để tạo ra hình ảnh số hóa mới được đưa vào sản phẩm đa phương tiện;', '- Sử dụng bút vẽ mỹ thuật, máy tính hoặc các kỹ thuật khác để tạo ra các hiệu ứng hình ảnh mong muốn.']::text[], array['Nhiếp ảnh gia trên không', 'Nhiếp ảnh gia thương mại', 'Nhiếp ảnh gia công nghiệp', 'Nhiếp ảnh gia', 'Phóng viên ảnh', 'Nhiếp ảnh gia chụp chân dung', 'Nhiếp ảnh gia khoa học']::text[], array['Kỹ thuật viên vận hành máy quay phim - 3521', 'Kỹ thuật viên vận hành máy quay video - 3521', 'Thợ sửa chữa thiết bị chụp ảnh - 7311', 'Thợ quét và xử lý ảnh - 7321', 'Thợ quang khắc - 7321', 'Thợ cơ điện tử - 7421']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 804) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3432', 'Nhà thiết kế và trang trí nội thất lên kế hoạch và thiết kế nội thất nhà thương mại, công nghiệp, công cộng, bán lẻ và nhà ở để tạo ra một môi trường phù hợp với mục đích, có tính đến các yếu tố nâng cao môi trường sống, làm việc và xúc tiến bán hàng. Họ phối hợp và tham gia trong vấn đề xây dựng và trang trí.', array['- Xác định các mục tiêu và hạn chế của bản tóm tắt thiết kế để tư vấn với khách hàng và các bên liên quan;', '- Nghiên cứu và phân tích không gian, chức năng, hiệu quả, an toàn và yêu cầu thẩm mỹ;', '- Xây dựng nội dung thiết kế cho nội thất của tòa nhà;', '- Chuẩn bị phác thảo, sơ đồ, hình minh họa và kế hoạch để trình bày ý tưởng thiết kế;', '- Thương lượng các giải pháp thiết kế với khách hàng, quản lý, nhà cung cấp và nhân viên xây dựng;', '- Lựa chọn, xác định và đề xuất các vật liệu chức năng và thẩm mỹ, đồ gỗ và các sản phẩm cho nội thất;', '- Quy định chi tiết và lập hồ sơ được lựa chọn thiết kế cho xây dựng;', '- Phối hợp xây dựng và trang trí nội thất;', '- Thiết kế và vẽ tranh phong cảnh;', '- Thiết kế và trang trí cho cửa sổ và các khu vực khác để quảng bá sản phẩm và dịch vụ.']::text[], array['- Người trang trí trưng bày', '- Người trang trí nội thất', '- Người chỉ đạo mỹ thuật', '- Người bài trí bán hàng', '- Người bày hàng tủ kính']::text[], array['- Kiến trúc sư nội thất - 2161']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 830) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3433', 'Kỹ thuật viên thư viện, viện bảo tàng và triển lãm chuẩn bị các tác phẩm nghệ thuật, mẫu vật và cổ vật cho các bộ sưu tập; sắp xếp và xây dựng phòng trưng bày triển lãm; hỗ trợ nhân viên thư viện để tổ chức và vận hành hệ thống xử lý ghi nhận tài liệu và các tập tin.', array['- Lắp đặt và chuẩn bị các đối tượng để trưng bày;', '- Thiết kế và sắp xếp nội thất triển lãm, quầy hàng, khu vực trưng bày;', '- Hỗ trợ trong việc thiết lập thiết bị chiếu sáng và hiển thị;', '- Tiếp nhận, vận chuyển, đóng gói và mở hàng trưng bày;', '- Đặt hàng vật liệu thư viện mới, duy trì bản ghi thư viện và các hệ thống lưu thông;', '- Biên mục in và ghi lại nguyên liệu;', '- Nhập dữ liệu vào cơ sở dữ liệu và chỉnh sửa bản ghi máy tính;', '- Sử dụng thiết bị nghe nhìn và máy sao chụp;', '- Tìm kiếm và xác nhận các thư mục dữ liệu.']::text[], array['Kỹ thuật viên bảo tàng', 'Kỹ thuật viên thư viện', 'Kỹ thuật viên phòng trưng bày']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 851) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3434', 'Đầu bếp trưởng thiết kế thực đơn, tạo ra các món ăn và giám sát việc lập kế hoạch, tổ chức, chuẩn bị và nấu các bữa ăn trong khách sạn, nhà hàng, trên tàu thủy, tàu hỏa chở khách, gia đình riêng và các nơi ăn uống khác.', array['- Lập kế hoạch và phát triển các công thức nấu ăn và thực đơn; ước lượng thực phẩm, chi phí lao động và đặt hàng cung cấp thực phẩm;', '- Giám sát chất lượng món ăn ở mọi giai đoạn chuẩn bị và trình bày;', '- Thảo luận về các vấn đề chuẩn bị thực phẩm với các nhà quản lý, chuyên môn dinh dưỡng, nhà bếp và nhân viên bồi bàn;', '- Giám sát và điều phối các hoạt động của đầu bếp và nhân viên khác tham gia vào chuẩn bị thức ăn;', '- Kiểm tra vật tư, thiết bị và công việc khu vực để đảm bảo sự phù hợp với tiêu chuẩn của cơ sở;', '- Xác định cách thức thực phẩm trình bày và tạo ra các trang trí thực phẩm;', '- Hướng dẫn đầu bếp và nhân viên khác trong việc chuẩn bị, nấu ăn, trang trí và trình bày của thực phẩm;', '- Tham gia tuyển dụng của các nhân viên nhà bếp và giám sát hiệu suất của họ;', '- Chuẩn bị gia vị, nấu các món ăn đặc sản và phức tạp;', '- Giải thích và thực hiện các quy định an toàn vệ sinh và thực phẩm.']::text[], array['- Đầu bếp chính', '- Đầu bếp trưởng', '- Bếp trưởng bếp bánh', '- Người chế nước xốt']::text[], array['Đầu bếp - 5120', '- Người chuẩn bị đồ ăn nhanh - 9401']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 867) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3439', 'Nhân viên về nghệ thuật và văn hóa khác bao gồm những người hỗ trợ giám đốc hay các diễn viên dàn dựng sân khấu, điện ảnh, truyền hình hoặc sản xuất thương mại.', '{}'::text[], array['Nhân viên về nghệ thuật cơ thể', '- Nhân viên quản lý tầng (phát thanh)', '- Kỹ thuật viên ánh sáng', '- Các điều phối viên của chương trình (phát sóng)', '- Người nhắc vở', '- Người phụ trách đồ dùng sân khấu', '- Kỹ thuật viên kỹ thuật đặc biệt', '- Người quản lý sân khấu', '- Kỹ thuật viên sân khấu', '- Nghệ sỹ đóng thế', '- Điều phối viên đóng thế', '- Nghệ sỹ xăm', '- Kỹ thuật viên sân khấu', '- Người làm về phục trang sân khấu', '- Người đóng vai phụ']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 888) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3511', 'Kỹ thuật viên vận hành công nghệ thông tin (CNTT) và truyền thông hỗ trợ việc xử lý, vận hành, quản lý thông tin, hệ thống kỹ thuật truyền thông hàng ngày bao gồm các mạng LAN và WAN, các phần cứng, phần mềm và các thiết bị máy tính liên quan nhằm đảm bảo việc vận hành tốt nhất và xác định các vấn đề phát sinh.', array['Vận hành, giám sát các thiết bị ngoại vi và các thiết bị máy tính liên quan; nhập lệnh, sử dụng thiết bị đầu cuối máy tính và kích hoạt bảng điều khiển máy tính, các thiết bị ngoại vi để tích hợp và vận hành thiết bị;', 'Giám sát hệ thống tìm lỗi của thiết bị hoặc lỗi vận hành;', 'Thông báo cho giám sát viên hoặc kỹ thuật viên bảo dưỡng các trục trặc của thiết bị;', 'Giải quyết các thông báo lỗi chương trình bằng cách tìm và sửa các vấn đề, thông báo lỗi cho các kỹ thuật viên khác hoặc kết thúc chương trình;', 'Đọc các hướng dẫn thiết lập để xác định những thiết bị được sử dụng, yêu cầu sử dụng, các tài liệu như các đĩa và sách hướng dẫn và thiết lập các quản lý;', 'Sửa chữa, khôi phục, phân loại và sắp xếp các chương trình đầu ra theo yêu cầu và gửi dữ liệu đến những người sử dụng cụ thể;', 'Cài đặt các thiết bị ngoại vi như máy in với các vật liệu được chọn để chạy vận hành hoặc giám sát việc cài đặt các thiết bị ngoại vi do người vận hành thiết bị ngoại vi thực hiện.']::text[], array['- Kỹ thuật viên điều hành máy tính', '- Kỹ thuật viên điều hành thiết bị ngoại vi của máy tính', '- Kỹ thuật viên điều hành máy in tốc độ cao']::text[], array['- Kỹ thuật viên mạng máy tính - 3513']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 912) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3512', 'Kỹ thuật viên hỗ trợ người sử dụng công nghệ thông tin và truyền thông cung cấp không trực tiếp các hỗ trợ kỹ thuật cho người sử dụng thông qua điện thoại, email hoặc các phương tiện điện tử khác bao gồm chuẩn đoán, giải quyết các vấn đề và trục trặc với phần mềm, phần cứng, thiết bị ngoại vi máy tính, mạng và cơ sở dữ liệu; cung cấp hướng dẫn và hỗ trợ trong việc triển khai, cài đặt và duy trì hệ thống.', array['Trả lời các câu hỏi của người sử dụng về việc vận hành phần mềm, phần cứng để giải quyết các vấn đề phát sinh;', 'Nhập các lệnh và quan sát chức năng của hệ thống để xác định những vận hành đúng và tìm các lỗi;', 'Cài đặt và thực hiện sửa chữa các lỗi nhỏ của phần cứng, phần mềm, thiết bị ngoại vi theo thiết kế hoặc các đặc điểm kỹ thuật cài đặt;', 'Giám sát vận hành hàng ngày của các hệ thống máy tính và truyền thông;', 'Cài đặt thiết bị theo mục đích sử dụng, thực hiện và đảm bảo việc cài đặt chính xác, phù hợp các dây cáp, các hệ điều hành hoặc các phần mềm thích hợp;', 'Duy trì việc ghi nhận các giao dịch truyền thông dữ liệu hàng ngày, các vấn đề, cách giải quyết hoặc các hoạt động cài đặt;', 'Báo cáo các vấn đề kỹ thuật mà người dùng gặp phải;', 'Tư vấn cho người sử dụng các hướng dẫn sử dụng kỹ thuật, các tài liệu khác để nghiên cứu và các giải pháp thực hiện.']::text[], array['- Trợ lý truyền thông', '- Trợ lý cơ sở dữ liệu máy tính', '- Kỹ thuật viên trợ giúp máy tính bàn', '- Trợ lý lập trình máy tính', '- Trợ lý phân tích hệ thống máy tính']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 928) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3513', 'Kỹ thuật viên hệ thống và mạng máy tính thiết lập, vận hành, duy trì mạng và các hệ thống truyền dữ liệu khác.', array['Vận hành, bảo trì và xử lý sự cố các hệ thống mạng;', 'Vận hành và bảo trì các hệ thống truyền thông dữ liệu khác ngoài mạng;', 'Hỗ trợ người sử dụng giải quyết các vấn đề về mạng và truyền dữ liệu;', 'Xác định các khu vực cần nâng cấp thiết bị và phần mềm;', 'Cài đặt phần cứng máy tính, phần mềm mạng, phần mềm hệ điều hành và các phần mềm ứng dụng;', 'Thực hiện các hoạt động từ khởi động đến đóng chương trình cũng như việc sao lưu và phục hồi sự cố.']::text[], array['- Kỹ thuật viên mạng máy tính', '- Kỹ thuật viên hỗ trợ mạng']::text[], array['- Nhà quản trị mạng - 2522', '- Nhà phân tích mạng - 2523', '- Kỹ thuật viên điều hành máy tính - 3511', '- Kỹ thuật viên trang web - 3514']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 945) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3514', 'Kỹ thuật viên trang web duy trì, giám sát và hỗ trợ việc thực hiện tốt nhất các chức năng của các trang web trên internet, intranet, phần cứng và phần mềm các trang chủ.', array['Cài đặt, giám sát và hỗ trợ tính tin cậy và tiện lợi của các trang web trên internet, intranet, phần cứng và phần mềm các trang chủ;', 'Phát triển và duy trì các tài liệu, chính sách; hướng dẫn, ghi nhận các hoạt động vận hành và các bản ghi hệ thống;', 'Phát triển, điều phối, thực hiện và giám sát các cách thức bảo mật;', 'Phân tích và đưa ra các khuyến nghị để nâng cao hoạt động của hệ thống, bao gồm việc nâng cấp và yêu cầu các hệ thống mới;', 'Giữ liên lạc và cung cấp hướng dẫn cho khách hàng và người sử dụng;', 'Sửa đổi các trang web;', 'Thực hiện việc sao lưu và phục hồi trang chủ.']::text[], array['- Kỹ thuật viên tạo trang web', '- Kỹ thuật viên quản trị trang web', '- Kỹ thuật viên trang web']::text[], array['- Nhà thiết kế trò chơi máy tính - 2166', '- Nhà thiết kế trang web - 2166', '- Nhà phân tích hệ thống (máy tính) - 2511', '- Nhà thiết kế phần mềm máy tính - 2512', '- Nhà phát triển trang web - 2513', '- Nhà quản trị hệ thống máy tính - 2522', '- Nhà quản trị mạng - 2522']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 962) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3521', 'Kỹ thuật viên truyền hình và nghe - nhìn kiểm soát chức năng kỹ thuật của thiết bị để ghi và chỉnh sửa hình ảnh, âm thanh, để truyền phát sóng hình ảnh và truyền hình cũng như các loại tín hiệu viễn thông khác trên đất liền, trên biển hoặc trên máy bay.', array['- Điều khiển thiết bị ghi lại âm thanh;', '- Điều khiển thiết bị chỉnh sửa và trộn các bản ghi hình ảnh, âm thanh để đảm bảo chất lượng thỏa đáng và tạo hiệu ứng hình ảnh, âm thanh đặc biệt;', '- Áp dụng kiến ​​thức về các nguyên tắc và thực hành ghi, chỉnh sửa hình ảnh, âm thanh để xác định và giải quyết vấn đề;', '- Kiểm soát các hệ thống truyền phát, phát sóng và hệ thống vệ tinh cho các chương trình phát thanh và truyền hình;', '- Điều khiển hệ thống thông tin vô tuyến, dịch vụ vệ tinh và hệ thống ghép kênh trên mặt đất, trên biển hoặc trên máy bay;', '- Áp dụng kiến ​​thức về các nguyên tắc và thực hành về phát thanh truyền hình, thiết bị đầu cuối viễn thông và hệ thống truyền dẫn để xác định và giải quyết các vấn đề;', '- Sửa chữa khẩn cấp cho thiết bị.']::text[], array['- Kỹ thuật viên điều hành thiết bị nghe nhìn', '- Kỹ thuật viên điều hành thiết bị phát sóng', '- Kỹ thuật viên phát sóng', '- Kỹ thuật viên vận hành máy ảnh (hình ảnh chuyển động)', '- Kỹ thuật viên vận hành máy ảnh (video)', '- Trợ lý sản xuất (truyền thông)']::text[], array['- Nhiếp ảnh gia - 3431']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 987) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3522', 'Kỹ thuật viên kỹ thuật viễn thông thực hiện các nhiệm vụ kỹ thuật gắn với nghiên cứu kỹ thuật viễn thông cũng như với thiết kế, sản xuất, lắp ráp, xây dựng, vận hành, bảo trì và sửa chữa hệ thống viễn thông.', array['- Cung cấp hỗ trợ kỹ thuật gắn với nghiên cứu và phát triển thiết bị viễn thông hoặc thử nghiệm các nguyên mẫu;', '- Nghiên cứu tài liệu kỹ thuật như bản thiết kế và bản phác thảo để quyết định phương pháp làm việc sẽ được thông qua;', '- Chuẩn bị các ước tính chi tiết về số lượng và chi phí vật liệu, nhân công cần thiết cho việc sản xuất và lắp đặt thiết bị viễn thông theo các thông số kỹ thuật được đưa ra;', '- Cung cấp giám sát kỹ thuật cho việc sản xuất, sử dụng, bảo trì và sửa chữa hệ thống viễn thông để đảm bảo thực hiện thỏa đáng và tuân thủ các thông số kỹ thuật và quy định;', '- Áp dụng kiến ​​thức kỹ thuật về các nguyên tắc và thực hành kỹ thuật viễn thông để xác định và giải quyết các vấn đề phát sinh trong quá trình làm việc của họ.']::text[], array['- Kỹ thuật viên kỹ thuật viễn thông']::text[], array['- Kỹ thuật viên kỹ thuật điện tử - 3114', '- Thợ cài đặt phần cứng máy tính - 7422', '- Thợ sửa chữa thiết bị viễn thông - 7422', '- Thợ lắp đặt điện thoại - 7422']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1006) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3610', 'Giáo viên tiểu học dạy một loạt các môn học ở cấp giáo dục tiểu học. Trình độ của giáo viên tiểu học ở nhóm này đòi hỏi ở trình độ trung cấp hoặc cao đẳng.', array['- Giảng dạy, giáo dục học sinh theo chương trình giáo dục, kế hoạch dạy học;', '- Tham gia phát hiện, bồi dưỡng học sinh năng khiếu, phụ đạo học sinh yếu kém;', '- Vận dụng các sáng kiến kinh nghiệm, kết quả nghiên cứu khoa học sư phạm ứng dụng vào thực tế giảng dạy, giáo dục và làm đồ dùng, thiết bị dạy học cấp tiểu học;', '- Thực hiện đổi mới phương pháp dạy học, đổi mới tổ chức lớp học, tổ chức hoạt động dạy học và đánh giá kết quả học tập theo hướng phát huy tính chủ động, tích cực, hình thành năng lực và phương pháp tự học của học sinh;', '- Làm báo cáo viên hoặc dạy minh họa ở các lớp bồi dưỡng giáo viên tiểu học hoặc dạy thử nghiệm các mô hình, phương pháp mới;', '- Hướng dẫn sinh viên thực tập;', '- Chủ trì các nội dung bồi dưỡng và sinh hoạt chuyên đề ở tổ, khối chuyên môn; viết sáng kiến kinh nghiệm; tham gia đánh giá, xét duyệt sáng kiến kinh nghiệm, đề tài nghiên cứu khoa học sư phạm ứng dụng của đồng nghiệp cấp trường trở lên;', '- Tham gia công tác kiểm tra chuyên môn, nghiệp vụ giáo viên tiểu học từ cấp trường trở lên;', '- Tham gia ban giám khảo hội thi giáo viên dạy giỏi, giáo viên chủ nhiệm giỏi, tổng phụ trách đội giỏi;', '- Tham gia tổ chức, đánh giá các hội thi của học sinh tiểu học từ cấp trường trở lên;', '- Hoàn thành các chương trình bồi dưỡng; tự học, tự bồi dưỡng trau dồi đạo đức, nâng cao năng lực chuyên môn nghiệp vụ; tham gia các hoạt động chuyên môn; tham gia phổ cập giáo dục tiểu học, xóa mù chữ;', '- Phối hợp với Đội Thiếu niên Tiền phong Hồ Chí Minh, gia đình học sinh và các tổ chức, đoàn thể liên quan để tổ chức, hướng dẫn các hoạt động giáo dục, tham gia tư vấn tâm lý học sinh tiểu học;', '- Tổ chức các hoạt động trải nghiệm sáng tạo cho học sinh;', '- Thực hiện các nhiệm vụ khác được phân công.']::text[], array['- Giáo viên tiểu học']::text[], array['- Hiệu trưởng nhà trường - 1748', '- Thanh tra trường học - 2391']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1022) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3620', 'Giáo viên mầm non thúc đẩy sự phát triển xã hội, thể chất và trí tuệ của trẻ em dưới độ tuổi tiểu học thông qua việc cung cấp các hoạt động giáo dục và vui chơi. Trình độ của giáo viên mầm non ở nhóm này đòi hỏi ở trình độ trung cấp hoặc cao đẳng.', array['- Bảo vệ an toàn tuyệt đối sức khỏe, tính mạng của trẻ trong thời gian trẻ ở nhóm (lớp) được phân công phụ trách;', '- Trực tiếp nuôi dưỡng, chăm sóc, giáo dục trẻ và chịu trách nhiệm về chất lượng chăm sóc giáo dục trẻ ở nhóm, lớp được phân công phụ trách; thực hiện công tác nuôi dưỡng, chăm sóc, giáo dục trẻ em theo Chương trình giáo dục mầm non;', '- Làm báo cáo viên hoặc dạy minh họa tại các lớp bồi dưỡng giáo viên mầm non cấp trường trở lên; hướng dẫn đồng nghiệp thực hiện chương trình và các hoạt động nuôi dưỡng, chăm sóc, giáo dục trẻ;', '- Đề xuất các nội dung bồi dưỡng và sinh hoạt chuyên đề ở tổ (khối) chuyên môn;', '- Tham gia ban giám khảo các hội thi, đánh giá sáng kiến kinh nghiệm của cấp trường trở lên;', '- Tham gia đoàn đánh giá ngoài, kiểm tra chuyên môn, nghiệp vụ sư phạm cấp trường trở lên; tham gia hướng dẫn, đánh giá thực tập sư phạm của sinh viên (nếu có);', '- Tham gia các hoạt động chuyên môn, bảo quản và sử dụng thiết bị giáo dục được giao;', '- Phối hợp với gia đình và cộng đồng trong việc nuôi dưỡng, chăm sóc, giáo dục trẻ;', '- Thực hiện các nhiệm vụ khác được phân công.']::text[], array['- Giáo viên mầm non', '- Giáo viên tiền tiểu học']::text[], array['- Giám đốc trung tâm chăm sóc trẻ em - 1748', '- Nhân viên chăm sóc trẻ em - 5311']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1044) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3630', 'Giáo viên dạy các đối tượng bị khuyết tật dạy cho trẻ em khuyết tật về thể chất hoặc tinh thần, người trưởng thành trẻ tuổi hoặc những người có khó khăn trong học tập hoặc các nhu cầu đặc biệt khác. Họ thúc đẩy sự phát triển xã hội, tình cảm, trí tuệ và thể chất của học sinh. Trình độ của giáo viên dạy các đối tượng bị khuyết tật ở nhóm này đòi hỏi ở trình độ trung cấp hoặc cao đẳng.', array['- Đánh giá khả năng và giới hạn của học sinh về các khiếm khuyết về trí tuệ, thể chất, xã hội và cảm xúc, quà tặng trí tuệ đặc biệt hoặc các tình huống đặc biệt khác;', '- Thiết kế hoặc sửa đổi chương trình giảng dạy; chuẩn bị và cung cấp các chương trình, bài học, các hoạt động phù hợp với khả năng và nhu cầu của học sinh;', '- Hướng dẫn trên cơ sở cá nhân hoặc nhóm sử dụng các kỹ thuật hoặc trợ giúp đặc biệt phù hợp với nhu cầu của học sinh;', '- Sử dụng các chiến lược và kỹ thuật giáo dục đặc biệt trong quá trình giảng dạy để cải thiện sự phát triển các kỹ năng cảm giác, nhận thức - vận động, ngôn ngữ, nhận thức và trí nhớ;', '- Thiết lập và thực thi các quy tắc để duy trì trật tự giữa các học sinh;', '- Giảng dạy các môn học thuật, các kỹ năng thực tế và tự lực cho học sinh khiếm thính, thị giác và các khiếm khuyết khác;', '- Kích thích và phát triển sở thích, sự tự tin, khả năng, kỹ năng thủ công và phối hợp của học sinh;', '- Trao đổi với các giáo viên khác để lập kế hoạch và sắp xếp các bài học cho các học sinh có nhu cầu đặc biệt;', '- Chuẩn bị và duy trì dữ liệu và các hồ sơ khác của học sinh và gửi báo cáo;', '- Quản lý các hình thức đánh giá và đánh giá tiến bộ khác nhau của mỗi học sinh;', '- Trao đổi với học sinh, phụ huynh, giáo viên chủ nhiệm và các chuyên gia có liên quan khác về các vấn đề của học sinh. Phát triển các kế hoạch giáo dục cá nhân được thiết kế để thúc đẩy học sinh phát triển.']::text[], array['- Giáo viên giáo dục đặc biệt cho người khuyết tật', '- Giáo viên hỗ trợ học tập', '- Giáo viên khắc phục khiếm khuyết', '- Giáo viên dạy trẻ khiếm thính', '- Giáo viên dạy người khiếm thị']::text[], array['- Giáo viên sơ cấp - 3641', '- Giáo viên tiểu học - 3610']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1062) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3641', 'Giáo viên sơ cấp dạy hoặc hướng dẫn các môn học nghề nghiệp trong các cơ sở hoạt động giáo dục nghề nghiệp. Họ chuẩn bị cho học viên việc làm trong các ngành nghề cụ thể hoặc các lĩnh vực nghề nghiệp mà thông thường không yêu cầu giáo dục đại học hoặc cao hơn.', array['- Soạn giáo án, lập đề cương bài giảng, chuẩn bị tài liệu, trang thiết bị phục vụ cho việc giảng dạy mô-đun được phân công giảng dạy;', '- Giảng dạy mô-đun được phân công theo kế hoạch và quy định của chương trình;', '- Đánh giá kết quả học tập của học viên gồm: soạn đề kiểm tra, coi kiểm tra, đánh giá kiểm tra định kỳ;', '- Coi thi, kiểm tra, đánh giá kết thúc mô-đun;', '- Hoàn thiện các biểu mẫu, sổ sách quản lý lớp học được bố trí, phân công giảng dạy theo quy định;', '- Biên soạn giáo trình, tài liệu giảng dạy; góp ý kiến xây dựng chương trình, nội dung mô-đun được phân công giảng dạy;', '- Tham gia thiết kế, xây dựng phòng học chuyên môn; thiết kế, cải tiến, tự làm đồ dùng, trang thiết bị giáo dục nghề nghiệp;', '- Tổ chức các hoạt động giáo dục và rèn luyện học viên;', '- Dự giờ, trao đổi kinh nghiệm giảng dạy; thực tập tại doanh nghiệp hoặc cơ quan chuyên môn, tham gia các hoạt động chuyên môn, nghiệp vụ;', '- Tham gia bồi dưỡng cho nhà giáo theo yêu cầu phát triển chuyên môn, nghiệp vụ;', '- Tham gia công tác quản lý đào tạo, quản lý học viên;', '- Thực hiện các nhiệm vụ khác được giao.']::text[], array['- Giáo viên công nghệ ô tô', '- Giáo viên thẩm mỹ', '- Giáo viên dạy nghề']::text[], array['- Hiệu trưởng - 1748', '- Giáo viên trung học - 233']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1086) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('3642', 'Giáo viên đào tạo khác bao gồm những người cung cấp học phí tư nhân trong các môn học ngoài các môn học nghề nghiệp ở nhóm 3651: Giáo viên sơ cấp và những người cung cấp tư vấn giáo dục cho học viên.', array['- Đánh giá mức độ khả năng của học viên và xác định nhu cầu học tập;', '- Lập kế hoạch, chuẩn bị và cung cấp các chương trình học tập, bài học và hội thảo cho từng học viên và nhóm;', '- Chuẩn bị và trình bày tài liệu về lý thuyết của lĩnh vực được nghiên cứu;', '- Hướng dẫn và thể hiện các khía cạnh thực tế của lĩnh vực, chủ đề đang nghiên cứu;', '- Giao các bài tập và công việc phù hợp với mức độ khả năng, sở thích và năng khiếu của học viên;', '- Đánh giá học viên và đưa ra lời khuyên, phê bình và khuyến khích;', '- Chuẩn bị cho học viên thi và đánh giá;', '- Tư vấn cho học viên về các vấn đề giáo dục như lựa chọn khóa học và chương trình, lên lịch học, điều chỉnh trường học, trốn học, thói quen học tập và lập kế hoạch nghề nghiệp;', '- Tư vấn cho học viên để giúp họ hiểu và khắc phục các vấn đề cá nhân, xã hội hoặc hành vi ảnh hưởng đến giáo dục của họ;', '- Chuẩn bị cho học viên những trải nghiệm giáo dục sau này bằng cách khuyến khích họ khám phá các cơ hội học tập và kiên trì với các nhiệm vụ đầy thách thức.']::text[], array['- Gia sư dạy chữ (tư nhân)', '- Giáo viên toán học (tư nhân)', '- Tư vấn viên của trường', '- Tư vấn sinh viên']::text[], array['- Giảng viên đại học - 2311', '- Giáo viên trung cấp - 2320', '- Giáo viên trung học - 233', '- Giáo viên tiểu học - 2341', '- Giáo viên ngôn ngữ chuyên sâu - 2393', '- Giáo viên giáo dục di cư - 2393', '- Giáo viên âm nhạc (tư nhân) - 2394', '- Giáo viên dạy nhảy (tư nhân) - 2395', '- Giáo viên kịch (tư nhân) - 2395', '- Giáo viên vẽ tranh (tư nhân) - 2395', '- Giáo viên điêu khắc (tư nhân) - 2395', '- Nhà tâm lý học giáo dục - 2634', '- Nhà chuyên môn về tư vấn gia đình - 2635', '- Nhà chuyên môn về xã hội - 2635', '- Giáo viên sơ cấp - 3641']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1108) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4110', 'Nhân viên tổng hợp thực hiện một số nhiệm vụ hành chính và văn phòng theo các thủ tục đã được quy định.', array['Ghi chép, chuẩn bị, sắp xếp, phân loại các thông tin;', 'Sắp xếp, mở và gửi thư;', 'Sao và fax tài liệu;', 'Chuẩn bị các báo cáo công việc hàng ngày;', 'Ghi các vấn đề về thiết bị của nhân viên;', 'Trả lời điện thoại hoặc các yêu cầu qua điện tử hoặc chuyển tiếp cho những người thích hợp;', 'Ghi ghép thông tin vào máy tính, đọc sửa và hiệu đính các bản sao lưu.']::text[], array['- Nhân viên văn phòng']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1146) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4120', 'Thư ký (tổng hợp) sử dụng máy đánh chữ, máy tính cá nhân hoặc các thiết bị xử lý văn bản khác để sao chép thư từ và các tài liệu khác; kiểm tra và định dạng các tài liệu do nhân viên khác chuẩn bị; xử lý thư đến và đi; yêu cầu sàng lọc các cuộc họp hoặc cuộc hẹn và thực hiện các nhiệm vụ hỗ trợ hành chính khác.', array['Kiểm tra, định dạng và đánh máy lại các thư từ, biên bản và báo cáo từ bản đọc chính tả, các tài liệu điện tử hoặc các dự thảo viết tay để phù hợp với các tiêu chuẩn văn phòng, sử dụng máy chữ, máy tính cá nhân hoặc các thiết bị xử lý văn bản khác;', 'Sử dụng các gói phần mềm máy tính khác nhau bao gồm bảng tính để cung cấp hỗ trợ quản trị;', 'Giải quyết các thư đi và thư đến;', 'Quét (scan), ghi lại và phân phối thư từ và tài liệu khác;', 'Xem xét các yêu cầu họp hoặc các buổi gặp mặt và giúp đỡ tổ chức các cuộc họp;', 'Xem xét và ghi lại việc rời đi và các việc được làm của các nhân viên khác;', 'Tổ chức và giám sát hệ thống sắp xếp;', 'Chủ động giải quyết các thư từ hàng ngày.']::text[], array['- Thư ký đánh máy', '- Thư ký xử lý văn bản']::text[], array['Thư ký luật - 3342', 'Thư ký hành chính - 3343', 'Trợ lý điều hành - 3343', 'Thư ký y tế - 3344']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1158) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4131', 'Nhân viên đánh máy sử dụng máy chữ, máy tính cá nhân và các máy xử lý văn bản khác thực hiện các công việc hiệu đính và in ấn; ghi lại các vấn đề dạng nói và viết dưới hình thức tốc ký.', array['Đánh máy các tài liệu viết từ các bản thảo thô, hiệu đính các bản thảo, ghi âm hoặc tốc ký sử dụng máy tính, máy xử lý văn bản hoặc máy chữ;', 'Kiểm tra các lỗi văn bản đã soạn thảo như chính tả, ngữ pháp, dấu câu, hình thức;', 'Thu thập và sắp xếp các tài liệu theo từng loại như hướng dẫn;', 'Sắp xếp và lưu trữ các văn bản thực hiện vào ổ cứng máy tính hoặc đĩa; duy trì hệ thống lọc để lưu trữ, khôi phục và cập nhật văn bản;', 'Viết hoặc ghi lại các vấn đề dưới dạng tốc ký;', 'Sao chép lại lời nói, âm thanh xung quanh và lời bài hát làm phụ đề cho các chương trình truyền hình và phim truyện;', 'Chuyển các thông tin lưu được sang dạng tốc ký và thu vào các thiết bị ghi âm.']::text[], array['- Nhân viên đánh máy tốc ký', '- Nhân viên viết tốc ký', '- Nhân viên đánh máy chữ', '- Nhân viên xử lý văn bản']::text[], array['- Báo cáo viên tòa án - 3343', '- Nhân viên viết hồ sơ y tế - 3344']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1180) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4132', 'Nhân viên nhập dữ liệu nhập các dữ liệu thống kê, tài chính và dữ liệu số khác vào thiết bị điện tử, cơ sở dữ liệu vi tính, bảng tính hoặc kho lưu trữ dữ liệu khác bằng bàn phím, chuột, máy quét quang, phần mềm nhận dạng giọng nói hoặc các công cụ nhập dữ liệu khác. Họ nhập dữ liệu vào các thiết bị để thực hiện các phép tính toán học.', array['Nhận và đăng ký hóa đơn, biểu mẫu, hồ sơ và các tài liệu khác để thu thập dữ liệu;', 'Nhập dữ liệu dạng số và dạng khác từ các nguồn tài liệu vào các thiết bị lưu trữ và xử lý số liệu tương thích với máy tính;', 'Xác minh tính chính xác, đầy đủ của dữ liệu và sửa dữ liệu đã nhập, nếu cần thiết;', 'Sử dụng các máy tính toán và lưu giữ sổ sách;', 'Nhập và xuất dữ liệu giữa các hệ thống cơ sở dữ liệu và phần mềm khác nhau.']::text[], array['- Nhân viên nhập dữ liệu', '- Nhân viên điều hành nhập liệu', '- Nhân viên nhập thanh toán']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1198) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4211', 'Nhân viên giao dịch ngân hàng và các nghề liên quan giao dịch trực tiếp với khách hàng của ngân hàng hoặc bưu điện liên quan đến các việc như nhận, đổi tiền và trả tiền hoặc cung cấp các dịch vụ thư tín.', array['Xử lý tiền gửi và tiền rút séc, chuyển khoản, hối phiếu, thẻ tín dụng, thư chuyển tiền, chi phiếu ngân hàng của khách hàng và những giao dịch ngân hàng có liên quan khác;', 'Ghi nợ vào tài khoản khách hàng;', 'Trả hối phiếu và chuyển nhượng tiền thay mặt khách hàng;', 'Nhận thư, bán tem thư và thực hiện các công việc tại quầy bưu điện như trả hối phiếu, chuyển tiền và các công việc liên quan;', 'Đổi tiền từ ngoại tệ này sang ngoại tệ khác theo yêu cầu của khách hàng;', 'Ghi lại các giao dịch và giải quyết bằng quyết toán tiền mặt.']::text[], array['- Giao dịch viên ngân hàng', '- Nhân viên đổi tiền', '- Nhân viên bưu điện']::text[], array['- Nhân viên thu ngân - 5230']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1216) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4212', 'Nhân viên chia bài trong sòng bạc và các nghề liên quan đến cờ bạc khác quyết định tỷ lệ cược, nhận và trả tiền cá cược theo kết quả của các sự kiện thể thao và các sự kiện khác; tổ chức các cuộc chơi may rủi trong các tổ chức cá cược.', array['Xác định rủi ro để quyết định tỷ lệ cá cược và phòng ngừa hoặc từ chối đặt cược;', 'Chuẩn bị và đưa ra danh sách các tỷ lệ cược gần đúng;', 'Chia bài, gieo xúc xắc hoặc quay bánh xe rulet;', 'Diễn giải và giải thích quy luật chơi của cơ sở đánh bạc;', 'Thông báo số thắng cược, trả cho người thắng cuộc và thu tiền từ người thua cuộc.']::text[], array['- Nhân viên chia bài trong sòng bạc', '- Nhân viên cá cược']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1231) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4213', 'Chủ hiệu cầm đồ và cho vay tiền trên cơ sở những đồ vật ký gửi làm vật thế chấp hoặc tài sản hay các chứng khoán khác.', array['Định giá các đồ vật đem làm thế chấp, tính toán lãi suất và cho vay;', 'Hoàn trả các đồ vật khi nợ được trả hoặc trong trường hợp không trả được nợ thì bán các đồ vật thế chấp;', 'Cho vay các khoản nợ cá nhân với mục đích thu lợi trong tương lai hoặc những cam kết khác;', 'Thu nợ khi đồ thế chấp liên quan đến việc thu lợi trong tương lai hoặc những cam kết khác;', 'Giữ lại các hóa đơn về đồ vật nhận được và tiền được thu và nhận.']::text[], array['- Người cho vay tiền', '- Chủ hiệu cầm đồ']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1242) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4214', 'Người thu nợ và các công viên liên quan thu tiền trả quá hạn, các khoản séc khó đòi và thu tiền từ thiện.', array['Truy tìm và xác định vị trí của con nợ; liên hệ với bạn bè, hàng xóm, người thân hoặc người tuyển dụng của con nợ để thu thập thông tin;', 'Gọi điện, đến thăm hoặc viết thư cho khách hàng để thu tiền hoặc sắp xếp các khoản trả chậm;', 'Chuẩn bị báo cáo gồm các khoản thu và giữ các hồ sơ liên quan đến công việc;', 'Kiến nghị các hành động pháp lý hoặc ngưng thực hiện dịch vụ khi việc chi trả không thực hiện được;', 'Yêu cầu và thu tiền từ thiện.']::text[], array['- Người thu nợ', '- Người thu tiền qua hóa đơn và tài khoản', '- Người thu tiền từ thiện']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1253) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4221', 'Nhân viên và tư vấn viên du lịch cung cấp thông tin về các điểm đến du lịch; sắp xếp lịch trình du lịch, đặt chỗ du lịch và nơi ở; đăng ký hành khách khi nhận phòng và khởi hành.', array['Thu thập các thông tin về chi phí và sự thuận tiện của các loại phương tiện giao thông và chỗ ở khác nhau; tìm hiểu các yêu cầu của khách hàng và tư vấn cho họ về việc sắp xếp chuyến đi;', 'Cung cấp thông tin về các điểm tham quan địa phương và khu vực, tham quan du lịch, nhà hàng, nghệ thuật và giải trí; cung cấp bản đồ và tài liệu quảng cáo;', 'Chuẩn bị lịch trình;', 'Đặt chỗ ở và các dịch vụ cần thiết;', 'Phân phát vé, thẻ lên máy bay và chứng từ;', 'Giúp đỡ khách hàng trong việc nhận các giấy tờ du lịch cần thiết như visa;', 'Chuẩn bị hóa đơn và nhận thanh toán;', 'Xác minh thủ tục du lịch; đăng ký hành khách và hành lý khi nhận phòng và khởi hành.']::text[], array['- Đại lý vé máy bay', '- Tiếp viên', '- Nhân viên bán vé (du lịch)', '- Nhân viên thông tin du lịch', '- Nhân viên đại lý du lịch', '- Nhân viên tư vấn du lịch', '- Nhân viên văn phòng du lịch']::text[], array['Quản lý đại lý du lịch - 1747', 'Nhân viên tổ chức sự kiện và hội nghị - 3332', 'Nhân viên tổ chức tua du lịch - 3339', 'Nhân viên hộ tống tua du lịch - 5113', 'Hướng dẫn viên du lịch - 5113', 'Nhân viên phát hành vé (sự kiện giải trí và thể thao) - 5230']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1268) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4222', 'Nhân viên trung tâm thông tin liên lạc liên hệ với khách hàng thông qua điện thoại hoặc các phương tiện thông tin điện tử như thư điện tử; nhân viên sẽ đưa ra những lời khuyên và thông tin cho khách hàng; trả lời các câu hỏi về hàng hóa, dịch vụ hay chính sách, các giao dịch tài chính của tổ chức. Khách hàng hoặc những hoạt động của tổ chức mà thông tin được cung cấp có thể điều khiển từ xa.', array['Nhận các cuộc gọi đến hay các thông điệp từ khách hàng, trả lời các yêu cầu, điện thoại đối với dịch vụ hay phân loại những lời than phiền của khách hàng;', 'Xác định các yêu cầu và nhập các sự kiện vào hệ thống máy tính;', 'Phân bổ công việc đến các đơn vị khác có liên quan;', 'Lập hóa đơn hoặc thanh toán tiền hàng nếu cần thiết;', 'Gửi thư, bảng thông tin và các tài liệu khác cho khách hàng;', 'Tư vấn cho khách hàng các sản phẩm và dịch vụ tăng thêm.']::text[], array['- Nhân viên trung tâm thông tin liên lạc khách hàng']::text[], array['- Nhân viên điều hành điện thoại - 4223', '- Phỏng vấn viên nghiên cứu thị trường - 4227', '- Nhân viên bán hàng qua trung tâm điện thoại - 5244', '- Nhân viên bán hàng qua trung tâm liên lạc khách hàng - 5244', '- Nhân viên tiếp thị qua điện thoại - 5244', 'Ghi chú:', 'Chỉ những nhân viên trả lời yêu cầu thông tin hoặc xử lý các giao dịch đơn giản mới được phân loại ở nhóm 4222. Nhân viên trung tâm thông tin liên lạc. Những người cung cấp dịch vụ chuyên ngành như tư vấn du lịch được phân loại trong nhóm chuyên ngành có liên quan cho dù họ có ở trung tâm liên hệ khách hàng hay không.']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1294) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4223', 'Nhân viên vận hành tổng đài điện thoại vận hành tổng đài điện thoại và bảng điều khiển thông tin điện thoại để kết nối điện thoại, nhận các yêu cầu của người gọi và báo cáo về các vấn đề dịch vụ; ghi và tiếp âm các tin nhắn tới nhân viên hay khách hàng.', array['Vận hành tổng đài và bảng điều khiểu để kết nối, chờ máy, chuyển máy và ngắt các cuộc điện thoại;', 'Kết nối các cuộc gọi ra ngoài;', 'Giải quyết các yêu cầu qua điện thoại, ghi lại các tin nhắn;', 'Gửi tin nhắn tới các nhân viên khác và khách hàng;', 'Kiểm tra các vấn đề hệ thống vận hành và các dịch vụ sửa chữa thông tin.']::text[], array['- Nhân viên điều hành dịch vụ trả lời', '- Nhân viên điều hành điện thoại']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1313) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4224', 'Nhân viên lễ tân khách sạn có nhiệm vụ ghi lại khách hàng, đăng ký phòng, đưa chìa khóa, cung cấp thông tin liên quan đến dịch vụ khách sạn, đặt trước phòng, ghi lại các phòng ở còn trống, tính tiền phòng cho khách đi và nhận tiền thanh toán.', array['Kiểm kê các phòng trống để ở, đặt trước và bố trí phòng;', 'Đăng ký khách đến, bố trí phòng, xác minh tài khoản của khách và đưa chìa khóa phòng;', 'Cung cấp các thông tin liên quan đến dịch vụ khách sạn và dịch vụ sẵn có trong cộng đồng;', 'Cung cấp thông tin về phòng trống và đặt phòng trước;', 'Trả lời các yêu cầu của khách về dịch vụ bảo dưỡng và trông phòng cũng như các lời phàn nàn của khách;', 'Liên hệ với các dịch vụ bảo dưỡng và trông phòng khi khách gặp sự cố;', 'Tính toán và kiểm tra chi phí của khách hàng bằng hệ thống máy tính hoặc thủ công;', 'Nhận và chuyển các tin nhắn trực tiếp hoặc sử dụng điện thoại hay tổng đài điện thoại;', 'Kiểm tra chi phí của khách đi và nhận thanh toán.']::text[], array['- Nhân viên lễ tân tại sảnh khách sạn', '- Tiếp tân']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1324) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4225', 'Nhân viên hướng dẫn trả lời các thư từ cá nhân, thư tay, thư điện tử và các yêu cầu qua điện thoại, các lời phàn nàn về hàng hóa, dịch vụ và chính sách của tổ chức, cung cấp các thông tin và chỉ dẫn khách hàng tới tổ chức khác. Vị trí của nhân viên hướng dẫn có liên hệ trực tiếp với khách hàng hoặc với dây chuyền sản xuất hàng hóa và dịch vụ.', array['Trả lời các câu hỏi về hàng hóa, dịch vụ và chính sách, cung cấp thông tin về phòng trống, địa điểm, giá cả và các vấn đề có liên quan;', 'Trả lời các câu hỏi về các vấn đề và tư vấn, cung cấp thông tin và trợ giúp;', 'Ghi lại những thông tin về những yêu cầu và những lời than phiền;', 'Chuyển các yêu cầu phức tạp tới đội ngũ lãnh đạo hoặc các chuyên gia tư vấn;', 'Phát các mẫu liên quan, sách và giấy tờ cung cấp thông tin cho các bên quan tâm.']::text[], array['- Nhân viên hỏi đáp', '- Nhân viên cung cấp thông tin']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1339) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4226', 'Lễ tân nhận và đón khách hoặc bệnh nhân; trả lời các thắc mắc và yêu cầu bao gồm cả sắp đặt các cuộc hẹn.', array['Nhận và đón khách hoặc bệnh nhân;', 'Sắp đặt lịch hẹn cho khách hoặc bệnh nhân;', 'Trả lời các yêu cầu qua điện thoại về thông tin hoặc lịch hẹn;', 'Chỉ dẫn khách hàng hoặc bệnh nhân tới những địa chỉ hoặc người phù hợp;', 'Cung cấp sách hay mẫu thông tin.']::text[], array['- Nhân viên lễ tân y tế']::text[], array['- Thư ký y tế - 3344', '- Nhân viên lễ tân khách sạn - 4224']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1350) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4227', 'Phỏng vấn viên điều tra và nghiên cứu thị trường phỏng vấn và ghi lại câu trả lời của người được điều tra đối với các câu hỏi điều tra và nghiên cứu thị trường về các chủ đề khác nhau.', array['Liên lạc với các cá nhân qua điện thoại hoặc trực tiếp và giải thích mục đích của cuộc phỏng vấn;', 'Đặt câu hỏi theo phiếu bảng hỏi và điều tra;', 'Ghi lại câu trả lời trên giấy và nhập trực tiếp vào cơ sở dữ liệu máy tính thông qua các hệ thống phỏng vấn có sự hỗ trợ của máy tính;', 'Kiểm tra và giải quyết các lỗi không nhất quán trong các câu trả lời;', 'Cung cấp phản hồi cho các nhà tài trợ khảo sát liên quan đến các vấn đề trong việc lấy dữ liệu hợp lệ.']::text[], array['- Phỏng vấn viên nghiên cứu thị trường', '- Phỏng vấn viên dư luận', '- Điều tra viên']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1363) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4229', 'Nhận và xử lý thông tin từ khách hàng cần thiết để quyết định phù hợp với các dịch vụ.', array['Phỏng vấn bệnh nhân để nhận và xử lý thông tin theo yêu cầu và cung cấp các dịch vụ của bệnh viện;', 'Phỏng vấn các ứng viên để được hỗ trợ công cộng để thu thập thông tin phù hợp cho ứng dụng của họ;', 'Xác nhận độ chính xác của thông tin được cung cấp;', 'Đề xuất các thủ tục để cung cấp, sửa đổi, từ chối hay hủy bỏ hỗ trợ;', 'Cung cấp thông tin và trả lời các câu hỏi liên quan đến các lợi ích và thủ tục bồi thường;', 'Chuyển bệnh nhân hoặc các ứng viên đến các tổ chức khác nếu họ không phù hợp với các dịch vụ.']::text[], array['- Phỏng vấn viên có khả năng', '- Nhân viên làm thủ tục nhập viện']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1375) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4311', 'Nhân viên kế toán tính toán, phân loại và ghi chép số liệu để hoàn tất hồ sơ tài chính. Họ thực hiện các công việc kết hợp của tính toán, vào sổ và kiểm tra để có được số liệu tài chính dùng cho việc duy trì hồ sơ thanh toán.', array['Kiểm tra số liệu, tài liệu để nhập đúng, tính toán chính xác và mã số phù hợp;', 'Sử dụng phần mềm tính toán để ghi chép, lưu giữ và phân tích thông tin;', 'Phân loại, ghi chép, tóm tắt số liệu và dữ liệu tài chính để biên soạn, lưu giữ sổ sách tài chính, sử dụng các biên bản, sổ cái hay máy tính;', 'Tính toán, chuẩn bị và phát hành hối phiếu, hóa đơn, bản kê tài khoản và các bản kê tài chính khác theo quy trình có sẵn;', 'Soạn thảo báo cáo và các bảng biểu thống kê, tài chính và kiểm toán gắn liền với các vấn đề như nhận tiền mặt, chi tiêu, tài khoản trả và nhận, lợi nhuận và thua lỗ.']::text[], array['- Nhân viên kế toán', '- Nhân viên ghi chép sổ sách', '- Nhân viên tính toán chi phí']::text[], array['- Trợ lý kế toán - 3313', '- Kế toán viên - 3313']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1393) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4312', 'Nhân viên thống kê, tài chính và bảo hiểm thu thập, biên soạn, tính toán dữ liệu thống kê và thống kê bảo hiểm liên quan đến các giao dịch của tổ chức bảo hiểm, ngân hàng và các tổ chức tài chính khác.', array['Thực hiện đăng ký hay hủy bỏ bảo hiểm, giao dịch bồi thường, những thay đổi điều khoản hợp đồng hay chi trả bảo hiểm;', 'Thu thập và biên soạn số liệu thống kê và thống kê bảo hiểm dựa trên các nguồn thông tin thường xuyên hoặc đặc biệt;', 'Tính toán tổng số, trung bình, phần trăm và các chỉ số khác; trình bày theo dạng bảng biểu theo yêu cầu;', 'Chuẩn bị các tài liệu tài chính và tính toán lãi suất hoặc phí môi giới và lệ phí chứng từ chi trả;', 'Duy trì chứng từ trái phiếu, cổ phiếu và chứng khoán khác được mua và bán thay mặt khách hàng và nhà tuyển dụng.']::text[], array['- Nhân viên tính toán', '- Nhân viên môi giới', '- Nhân viên tài chính', '- Nhân viên bảo hiểm', '- Nhân viên thế chấp', '- Nhân viên chứng khoán', '- Nhân viên thống kê']::text[], array['- Nhân viên môi giới cổ phiếu - 3311', '- Trợ lý kế toán - 3313', '- Trợ lý thống kê - 3314', '- Nhân viên môi giới hàng hóa - 3324', '- Nhân viên kế toán - 4311', '- Nhân viên ghi chép sổ sách - 4311']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1408) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4313', 'Nhân viên kế toán tiền lương xác thực và xử lý thông tin về bảng lương, tính toán những khoản chi trả và lợi ích của nhân viên trong một đơn vị, công ty hay tổ chức khác.', array['Duy trì hồ sơ làm việc của nhân viên, nghỉ phép và làm thêm giờ để tính các khoản trợ cấp lương và lợi ích, sử dụng các hệ thống thủ công hoặc máy tính;', 'Chuẩn bị và xác thực báo cáo thu nhập của nhân viên; xác định tổng lương, lương thuần và những khoản khấu trừ như thuế, phí công đoàn, bảo hiểm và các kế hoạch trợ cấp;', 'Chuẩn bị trả lương và lợi ích cho nhân viên bằng tiền mặt hay chuyển qua tài khoản;', 'Xem xét bảng chấm công, biểu đồ công việc, tính toán tiền lương và các thông tin khác để phát hiện và đối chiếu sự khác biệt về bảng lương;', 'Xác minh việc làm, giờ làm và điều chỉnh chi trả; ghi thông tin vào hồ sơ.']::text[], array['- Nhân viên tiền lương']::text[], array['Trợ lý kế toán - 3313', 'Kế toán viên - 3313', 'Nhân viên kế toán - 4311', 'Nhân viên ghi chép sổ sách - 4311']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1431) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4321', 'Nhân viên ghi chép tồn kho duy trì hồ sơ của hàng hóa sản xuất và các nguyên vật liệu sản xuất nhận được, cân đo, phân phối, gửi hoặc lưu kho.', array['Sắp xếp, kiểm soát việc nhận, gửi hàng hóa và giữ các hóa đơn liên quan;', 'Duy trì hồ sơ tồn kho, xác thực các vấn đề về hàng hóa, tính toán nhu cầu và trưng thu hàng mới;', 'Nhận, lưu giữ, phân phối dụng cụ, phụ tùng hoặc các thiết bị khác và duy trì sổ sách liên quan;', 'Xem xét hàng hóa nhận được, phân phối, sản xuất hay ký gửi và duy trì hồ sơ liên quan;', 'Tổng hợp hàng tồn kho của đồ nội thất và các mặt hàng khác nhận được để lưu trữ.']::text[], array['- Nhân viên điều phối kho', '- Nhân viên ghi chép hàng hóa', '- Nhân viên kho', '- Nhân viên phòng bảo quản', '- Nhân viên cân đong']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1449) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4322', 'Nhân viên sản xuất tính toán số lượng vật liệu cần thiết tại các ngày quy định cho sản xuất, xây dựng và cho các chương trình sản xuất tương tự; chuẩn bị và kiểm tra các kế hoạch hoạt động sản xuất.', array['Tính toán số lượng và loại vật liệu theo yêu cầu của sản xuất;', 'Chuẩn bị các kế hoạch yêu cầu sản xuất bảo đảm các vật liệu sẵn có khi cần và lưu giữ hồ sơ liên quan;', 'Chuẩn bị và hỗ trợ chuẩn bị kế hoạch sản xuất trên cơ sở đơn đặt hàng của khách hàng và khả năng sản xuất;', 'Xác thực hàng tồn kho, sắp xếp các hàng hóa vận chuyển và điều tra sự trì hoãn;', 'Ghi chép và điều phối công việc và vật liệu giữa các đơn vị.']::text[], array['- Nhân viên kế hoạch (nguyên liệu)', '- Nhân viên sản xuất']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1463) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4323', 'Nhân viên vận chuyển lưu giữ hồ sơ của các bộ phận hoạt động và phối hợp tính toán thời gian vận chuyển hàng hóa và hành khách đường sắt, đường bộ và đường hàng không, chuẩn bị các báo cáo quản lý.', array['Lưu giữ sổ sách của các bộ phận hoạt động và phối hợp tính toán thời gian vận chuyển hành khách và hàng hóa;', 'Chỉ dẫn lộ trình đường sắt trong phạm vi một khu vực, một vùng của hệ thống đường sắt và giữ các hồ sơ liên quan;', 'Chỉ đạo, kiểm soát và giữ hồ sơ mua bán hàng hóa ở đường sắt;', 'Phối hợp và lưu giữ hồ sơ về các hoạt động liên quan đến vận chuyển đường bộ như phân phối và hành trình của phương tiện và người lái; bốc dỡ hàng hóa và lưu giữ hàng hóa quá cảnh;', 'Phối hợp và lưu giữ hồ sơ hoạt động liên quan đến vận chuyển hành khách và hàng hóa bằng đường hàng không như danh sách khách hàng và kê khai hàng hóa;', 'Chuẩn bị báo cáo quản lý.']::text[], array['- Nhân viên kiểm soát (dịch vụ vận chuyển)', '- Nhân viên điều vận (dịch vụ vận chuyển)']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1474) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4401', 'Nhân viên thư viện cho mượn và nhận lại các tài liệu thư viện; sắp xếp và đưa sách lên kệ; cung cấp các thông tin chung về thư viện cho người sử dụng.', array['Cho mượn và nhận các sách thư viện và các tài liệu khác;', 'Sắp xếp sách và các hồ sơ tài liệu của thư viện lên kệ;', 'Thực hiện các công việc văn phòng như sắp xếp thủ công hoặc bằng máy, đánh máy chữ và các công việc không thường xuyên;', 'Giữ tiền đặt báo dài hạn;', 'Hỗ trợ người dùng thư viện truy cập các tài liệu thư viện cơ bản và cho mượn liên thư viện;', 'Lưu giữ các hồ sơ ghi chép của thư viện liên quan tới việc mua sắm, cho mượn, nhận lại sách và các xuất bản phẩm khác.']::text[], array['- Nhân viên thư viện', '- Nhân viên hồ sơ thư viện']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1489) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4402', 'Nhân viên phân loại và vận chuyển thư thực hiện việc phân loại, lưu trữ, vận chuyển và các công việc khác liên quan đến các dịch vụ thư tín từ các bưu điện hoặc các tổ chức có liên quan cũng như trong nội bộ một tổ chức.', array['Thực hiện các công việc xử lý thư trong các bưu điện công cộng hoặc các cơ sở chuyển phát thuộc sở hữu tư nhân;', 'Phân loại và vận chuyển thư đến các hộ gia đình và các doanh nghiệp;', 'Cung cấp hồ sơ xác nhận giao hàng khi khách hàng yêu cầu;', 'Phân loại và lưu giữ các hồ sơ đơn giản về thư đi và thư đến và chuyển các thư đi cho các tổ chức khác nhau;', 'Thực hiện các công việc liên quan khác.']::text[], array['- Nhân viên đưa thư', '- Nhân viên bưu chính']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1501) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4403', 'Nhân viên đánh mã, đọc và sửa bản in thử chuyển đổi các thông tin sang mã số; xác minh và hiệu chỉnh các bản in thử và thực hiện một số công việc văn phòng khác.', array['Chuyển đổi các thông tin sang mã số và phân loại thông tin bằng mã số nhằm mục đích xử lý dữ liệu;', 'So sánh bản in thử với các tài liệu liên quan để in với bản gốc, sửa lỗi và đánh dấu theo các quy định về xuất bản;', 'Phân loại các khuôn và đánh dấu chúng bằng các số để nhận dạng;', 'Phân loại các tài liệu cho việc sắp xếp hoặc đối chiếu các trang;', 'Ghi địa chỉ trên giấy báo và trên phong bì bằng tay.']::text[], array['- Nhân viên mã hóa', '- Nhân viên hiệu đính']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1512) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4404', 'Người ghi chép thuê và người làm các công việc có liên quan viết thư và hoàn thiện các mẫu đơn thay mặt cho những người không có khả năng đọc và viết.', array['Đọc thư và các vật phẩm được viết ra khác cho những người không có khả năng đọc và viết; thực hiện việc giải thích và cung cấp thông tin cần thiết;', 'Viết thư và hoàn thiện các mẫu đơn thay mặt cho người khác;', 'Tư vấn, giải thích cho cá nhân và giúp đỡ hoàn thiện các mẫu đơn chính thức do nhà nước quy định;', 'Thực hiện các công việc có liên quan khác.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1523) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4405', 'Nhân viên văn thư và phô tô làm công việc sắp xếp các thư từ, các danh thiếp, hóa đơn, biên lai và các chứng từ khác theo bảng chữ cái hoặc theo số thứ tự hoặc theo hệ thống sắp xếp được sử dụng. Họ đặt tài liệu vào tủ hồ sơ và chuyển đi khi được yêu cầu và thực hiện việc phô tô, scan hoặc fax tài liệu.', array['Phân loại hoặc sắp xếp có hệ thống các tài liệu theo hướng dẫn như theo nội dung, mục đích, tiêu chí sử dụng, thứ tự thời gian, bảng chữ cái hoặc theo số;', 'Sắp xếp tài liệu vào ngăn kéo, ngăn tủ và hộp đựng tài liệu;', 'Đặt tài liệu vào tủ hồ sơ và chuyển đi khi được yêu cầu;', 'Lưu giữ hồ sơ của các tài liệu được sắp xếp và chuyển đi;', 'Phô tô, scan hoặc fax tài liệu.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1530) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4406', 'Nhân viên tổ chức nhân sự duy trì và cập nhật hồ sơ nhân sự như thông tin về thuyên chuyển và thăng chức; thực hiện việc đánh giá hiệu suất, tính dồn số nghỉ phép của nhân viên, lương, bằng cấp và đào tạo.', array['Cập nhật thông tin về quá trình công việc, tiền lương, thực hiện đánh giá hiệu suất, bằng cấp và đào tạo, nghỉ phép và tích lũy;', 'Lập hồ sơ cho người lao động mới làm việc và kiểm tra các hồ sơ cho đầy đủ;', 'Xử lý đơn xin việc và thông báo kết quả cho các ứng viên;', 'Nhận và trả lời các câu hỏi, các yêu cầu thông tin về quyền và các điều kiện của công việc;', 'Gửi đơn xin việc và thông báo về cơ hội việc làm và các kỳ thi tuyển;', 'Duy trì và cập nhật hệ thống ghi sổ và đăng ký thủ công hoặc bằng máy tính; biên soạn và chuẩn bị các báo cáo và tài liệu liên quan đến hoạt động nhân sự;', 'Lưu trữ và truy xuất hồ sơ và tài liệu nhân sự theo yêu cầu.']::text[], array['- Trợ lý nguồn nhân lực', '- Nhân viên nguồn nhân lực']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1538) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('4409', 'Nhân viên hỗ trợ văn phòng khác chưa được phân vào đâu ví dụ nhóm bao gồm nhân viên thư tín và nhân viên xuất bản.', array['Nhận đơn đặt hàng của khách hàng để phân loại quản cáo; viết và chỉnh sửa bản sao; tính toán chi phí quảng cáo và đăng quảng cáo cho khách hàng;', 'Viết các thư từ trong kinh doanh và hành chính Nhà nước như trả lời các yêu cầu cung cấp thông tin và hỗ trợ, bồi thường thiệt hại, yêu cầu về tín dụng và thanh toán và khiếu nại về dịch vụ;', 'Hỗ trợ việc chuẩn bị các tạp chí xuất bản định kỳ, quảng cáo, danh mục, thư mục và các xuất bản phẩm khác;', 'Đọc báo, tạp chí, thông cáo báo chí và các ấn phẩm khác để định vị và gửi các bài báo quan tâm đến nhân viên và khách hàng.']::text[], array['Nhân viên quảng cáo', 'Nhân viên trao đổi thư từ', 'Biên dịch viên từ điển', 'Nhân viên xuất bản']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1551) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5111', 'Tiếp viên trên tàu hoặc máy bay đảm bảo sự thoải mái và an toàn cho hành khách, phục vụ ăn uống và dịch vụ cá nhân có sẵn trên máy bay và tàu thủy. Có thể lập kế hoạch và phối hợp vệ sinh và các hoạt động xã hội trên tàu.', array['Đón khách lên máy bay hoặc tàu thủy, soát vé hoặc thẻ lên tàu, hướng dẫn khách đến chỗ ngồi;', 'Thông báo, giải thích, hướng dẫn an toàn và khẩn cấp như sử dụng mặt nạ oxy, đai ghế và áo phao;', 'Phục vụ đồ ăn uống đã được đóng gói chuẩn bị sẵn;', 'Bán hàng miễn thuế và hàng khác;', 'Chăm sóc nhu cầu chung và sự thoải mái cho khách, trả lời yêu cầu, giữ khoang sạch sẽ;', 'Hướng dẫn, giúp đỡ và theo khách trong những trường hợp khẩn cấp như thoát ra khỏi máy bay bằng thang cứu hộ;', 'Đảm bảo dụng cụ cấp cứu và thiết bị y tế khác hoạt động tốt;', 'Thực hiện sơ cứu cho khách bị nạn;', 'Chú ý chỉ dẫn trước khi bay liên quan đến thời tiết, độ cao, quãng đường, trường hợp khẩn cấp, phối hợp tổ bay, độ dài chuyến bay, bữa ăn phục vụ và số lượng khách;', 'Chuẩn bị cho khách cất cánh và hạ cánh;', 'Xác định nhu cầu hỗ trợ đặc biệt của hành khách như trẻ nhỏ, người già hoặc người khuyết tật.']::text[], array['- Tiếp viên', 'Tiếp viên hàng không', 'Tiếp viên trên tàu']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1577) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5112', 'Nhân viên phụ tàu xe kiểm soát, bán vé, đảm bảo an toàn và tiện nghi cho khách trên tàu, xe buýt, tàu điện ngầm và phương tiện giao thông công cộng khác.', array['Bán vé và kiểm tra tính hợp lệ của vé phát hành;', 'Chú ý đến toa xe có giường nằm và hành khách trên toa khách;', 'Cung cấp sự hỗ trợ đặc biệt về việc lên tàu, chỗ ngồi và hành lý đối với người già, người ốm và người khuyết tật;', 'Đóng và mở cửa cho khách;', 'Kiểm tra vận hành của thiết bị an toàn trong thời gian đi;', 'Ra hiệu cho lái xe dừng hoặc đi tiếp;', 'Đón khách lên phương tiện giao thông, thông báo quãng đường và các điểm dừng;', 'Đảm bảo tuân thủ quy tắc an toàn;', 'Trả lời yêu cầu của khách, giải thích, cung cấp thông tin về điểm dừng và nối chuyến;', 'Đưa ra những hành động thích hợp trong trường hợp ứng phó khẩn cấp hoặc tai nạn;']::text[], array['Nhân viên phụ xe buýt;', 'Nhân viên phụ cáp treo;', 'Nhân viên kiểm tra vé (giao thông công cộng);', 'Nhân viên phụ tàu hỏa;', 'Nhân viên phụ tàu điện ngầm.']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1595) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5113', 'Nhân viên hướng dẫn du lịch đi theo khách cá nhân hoặc nhóm du lịch trong chuyến đi; tham quan du lịch, du ngoạn các địa điểm yêu thích như di tích lịch sử, danh lam thắng cảnh, khu công nghiệp và công viên giải trí. Họ giới thiệu những điểm nổi bật và cung cấp thông tin cần thiết về những nơi du khách đến.', array['Đi theo và hướng dẫn du khách trong những chuyến du lịch dã ngoại;', 'Đi theo du khách đến những địa điểm như bảo tàng, triển lãm, công viên giải trí, nhà máy và những cơ sở công nghiệp;', 'Mô tả, cung cấp thông tin và giải đáp các câu hỏi về những điểm hấp dẫn và những vật trưng bày;', 'Tổ chức các hoạt động giáo dục cho học sinh;', 'Kiểm tra các hoạt động của du khách để đảm bảo tuân thủ những quy tắc du lịch và an toàn ở các điểm tham quan;', 'Đón khách, đăng ký khách và thành viên của đoàn du lịch, phát thẻ hoặc thiết bị an toàn;', 'Phát ấn phẩm quảng cáo, trình bày các bài thuyết trình nghe nhìn, giải thích thủ tục và hoạt động tại các trang web du lịch;', 'Cung cấp thiết bị sơ cứu và hướng dẫn thoát hiểm;', 'Giải quyết vấn đề phát sinh trong chuyến đi, dịch vụ hoặc chỗ ở.']::text[], array['Hướng dẫn triển lãm nghệ thuật', 'Nhân viên hộ tống tua du lịch', 'Hướng dẫn viên du lịch']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1614) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5120', 'Đầu bếp lên kế hoạch, tổ chức, chuẩn bị và nấu món ăn theo công thức hoặc dưới sự giám sát của bếp trưởng, trong khách sạn, nhà hàng hoặc những nơi ăn uống khác, trên tàu thủy, tàu hỏa chở khách và trong nhà riêng.', array['Lên kế hoạch bữa ăn; chuẩn bị và nấu thực phẩm;', 'Lên kế hoạch, giám sát và điều phối công việc của phụ bếp;', 'Kiểm tra chất lượng món ăn;', 'Cân đo và pha chế nguyên liệu theo công thức hoặc yêu cầu cá nhân;', 'Giám sát nhiệt độ của lò, bếp nướng và những thiết bị khác;', 'Kiểm tra và vệ sinh bếp, thiết bị bếp, khu vực phục vụ… để đảm bảo an toàn và vệ sinh các dụng cụ nấu ăn;', 'Vận hành các thiết bị nấu ăn quy mô lớn như lò nướng, lò rán hoặc lưới nướng.']::text[], '{}'::text[], array['Quản lý quán cà phê - 1745', 'Quản lý nhà hàng - 1745', 'Đầu bếp trưởng - 3434', 'Người chuẩn bị đồ ăn nhanh - 9401']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1630) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5131', 'Bồi bàn phục vụ thức ăn và đồ uống tại bàn ở những nơi ăn uống, câu lạc bộ, quán và căng tin, trên tàu thủy hoặc tàu hỏa chở khách.', array['Bầy bàn ăn với khăn sạch, dao dĩa, bát đĩa và cốc chén;', 'Đón khách và giới thiệu với họ về thực đơn và đồ uống;', 'Tư vấn chọn món ăn và đồ uống;', 'Lấy danh sách đặt món và chuyển cho bộ phận bếp hoặc nhân viên quầy;', 'Phục vụ đồ ăn uống cho khách hàng tại bàn;', 'Lau sạch bàn và đưa bát đĩa vào bếp;', 'Đưa hóa đơn thanh toán, nhận thanh toán, sử dụng máy bán hàng và máy tính tiền.']::text[], '{}'::text[], array['Quản lý quán cà phê - 1745', 'Quản lý nhà hàng - 1745', 'Nhân viên pha chế- 5132', 'Ghi chú:', 'Chủ quán cà phê, nhà hàng hoặc quán bar nhỏ mà việc quản lý và giám sát nhân viên chỉ là phần nhỏ thì phụ thuộc vào nhiệm vụ chủ yếu để xếp vào nhóm 5120 - Đầu bếp, 5131 - Bồi bàn hoặc 5132 - Nhân viên pha chế.']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1648) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5132', 'Nhân viên pha chế chuẩn bị, pha và phục vụ đồ uống có cồn và đồ uống không cồn trực tiếp cho khách hàng ở quầy bar hoặc quầy tính tiền hoặc thông qua người bồi bàn.', array['Lấy thực đơn đặt từ nhân viên phục vụ hoặc lấy trực tiếp từ khách quen;', 'Chuẩn bị và phục vụ đồ uống có cồn hoặc không cồn ở quán bar;', 'Rửa cốc chén đã uống, làm sạch và bảo quản khu vực quầy, khu vực pha chè và cà phê, thiết bị như máy pha cà phê;', 'Lấy hóa đơn cho bộ phận bán hàng, sử dụng máy đếm tiền và nhận tiền thanh toán;', 'Đưa két vào khu vực cung cấp;', 'Hỗ trợ việc giữ tài sản của quầy; sắp xếp chai và cốc;', 'Kiểm tra xác nhận của khách hàng đối với những yêu cầu khác nhau về rượu;', 'Thực hiện quy trình giới hạn sử dụng rượu như thuyết phục khách hàng ngừng uống rượu, từ chối phục vụ thêm hoặc đặt xe;', 'Pha trộn nguyên liệu để làm coctai và những đồ uống khác;', 'Phục vụ đồ ăn nhẹ hoặc những đồ ăn khác cho khách ở quầy.']::text[], '{}'::text[], array['Quản lý quán cà phê - 1745', 'Quản lý nhà hàng - 1745', 'Bồi bàn - 5131', 'Ghi chú:', 'Chủ quán cà phê, nhà hàng hoặc quán bar nhỏ mà việc quản lý và giám sát nhân viên chỉ là phần nhỏ thì phụ thuộc vào nhiệm vụ chủ yếu để xếp vào nhóm 5120 - Đầu bếp, 5131 - Bồi bàn hoặc 5132 - Nhân viên pha chế.']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1664) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5141', 'Thợ làm đầu cắt, tạo kiểu, nhuộm, duỗi, làm tóc xoăn, cạo hoặc tỉa râu và xử lý vấn đề da đầu.', array['Cắt, gội, nhuộm và uốn tóc;', 'Cạo hoặc tỉa râu;', 'Xử lý vấn đề da đầu;', 'Chỉnh tóc giả theo yêu cầu của khách hàng;', 'Tư vấn về chăm sóc tóc, sản phẩm làm đẹp và kiểu tóc;', 'Tạo kiểu tóc thành tóc uốn lọn dài, tết và nối tóc;', 'Sắp xếp lịch hẹn và thanh toán;', 'Vệ sinh khu làm việc và làm sạch dụng cụ.']::text[], array['Thợ cắt tóc nam', 'Chuyên gia chăm sóc tóc', 'Thợ cắt tóc nữ', 'Nhà tạo mẫu tóc']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1686) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5142', 'Nhân viên làm đẹp và nhân viên có liên quan đưa ra các trị liệu làm đẹp về da mặt hoặc cơ thể, dùng mỹ phẩm và trang điểm, đưa ra nhiều loại trị liệu khác nhau để cải thiện vẻ bề ngoài.', array['Làm sạch và dùng kem dưỡng da và các sản phẩm liên quan đến mặt và các phần khác của cơ thể;', 'Massage mặt và cơ thể;', 'Trang điểm cho khách hàng, diễn viên hoặc người biểu diễn khác;', 'Làm sạch, đánh bóng, sơn móng tay và xử lý vấn đề về chân như chai chân, sẹo hoặc móng chân biến dạng;', 'Dịch vụ tắm và massage;', 'Tẩy lông theo phương pháp dân gian hoặc hiện đại;', 'Tư vấn cho khách hàng về ăn kiêng và luyện tập để giảm cân;', 'Sắp xếp lịch hẹn và thanh toán.']::text[], array['Nhân viên tắm và massage', 'Nhân viên làm đẹp', 'Chuyên gia trang điểm', 'Thợ sửa móng', 'Thợ chăm sóc móng', 'Tư vấn giảm cân']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1702) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5151', 'Người giám sát việc dọn dẹp và vệ sinh văn phòng, khách sạn và các cơ quan khác tổ chức, giám sát và thực hiện các nhiệm vụ giữ sạch sẽ và ngăn nắp khu vực bên trong và đồ đạc trong khách sạn, cơ quan cũng như trên máy bay, tàu, xe buýt và các phương tiện tương tự.', array['Thuê, đào tạo, sa thải, tổ chức và giám sát người giúp việc, người dọn dẹp và nhân viên dọn phòng khác;', 'Mua hoặc kiểm soát việc mua bán thiết bị vệ sinh;', 'Kiểm tra việc lưu giữ và phân phát thiết bị;', 'Giám sát phúc lợi và hướng dẫn thực hiện cho nhân viên vệ sinh;', 'Quét dọn hoặc hút bụi, giặt giũ, lau sàn, đồ nội thất và các đồ dùng khác;', 'Dọn giường, lau nhà tắm, cung cấp khăn tắm, xà bông và các vật dụng liên quan khác;', 'Lau dọn nhà bếp và trợ giúp các công việc bếp núc bao gồm cả rửa bát đĩa;', 'Bầy biện thêm những đồ dùng như cốc uống nước và đồ để ghi chép.']::text[], array['- Dọn dẹp phòng (khách sạn)', '- Quản gia (dọn dẹp phòng)']::text[], array['- Quản lý khách sạn - 1745', '- Người dọn giường và chuẩn bị đồ ăn sáng - 5152', '- Quản gia - 5152', '- Người chăm sóc tòa nhà - 5153', '- Người dọn dẹp gia đình - 9111']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1723) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5152', 'Người quản lý công việc gia đình tổ chức, giám sát và thực hiện các chức năng trông giữ trong các hộ tư nhân và các cơ sở lưu trú nhỏ có hoặc không có sự hỗ trợ của nhân viên trợ giúp.', array['Giám sát các nhân viên được thuê làm việc tại hộ gia đình;', 'Mua hoặc kiểm tra việc mua thiết bị cho hộ gia đình;', 'Kiểm tra việc lưu giữ và phân phát thiết bị;', 'Trợ giúp trong các trường hợp bị thương nhẹ hoặc đau ốm ví dụ như đo nhiệt độ, đưa thuốc và băng bó;', 'Quét dọn hoặc hút bụi, giặt giũ, lau sàn, đồ nội thất và các đồ dùng khác;', 'Dọn giường, lau nhà tắm, cung cấp khăn tắm, xà bông và các vật dụng liên quan khác;', 'Trông coi vật nuôi và cây cảnh trong nhà, tiếp khách, trả lời điện thoại, đưa tin và mua các hàng hóa lặt vặt;', 'Chuẩn bị và nấu thức ăn, dọn bàn và phục vụ đồ ăn, uống;', 'Làm sạch nhà bếp và giúp việc bếp núc bao gồm cả rửa bát.']::text[], array['- Người dọn giường và chuẩn bị đồ ăn sáng', '- Quản gia']::text[], array['- Quản lý khách sạn - 1745', '- Người giúp việc gia đình - 9111', 'Ghi chú:', 'Người quản lý của các cơ sở lưu trú nhỏ, nhà nghỉ nhỏ và việc quản lý và giám sát nhân viên không phải là thành phần quan trọng của công việc, được phân loại trong nhóm 5152 - Người quản lý công việc gia đình.']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1743) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5153', 'Người chăm sóc, bảo vệ tòa nhà chăm sóc các tòa nhà chung cư, khách sạn, văn phòng, nhà thờ hoặc các tòa nhà khác và bảo trì chúng trong điều kiện sạch sẽ và trật tự. Họ có thể giám sát nhân viên và các nhà thầu khác tùy thuộc vào quy mô và tính chất của tòa nhà liên quan.', array['Giám sát việc dọn dẹp, trông giữ, bảo quản tòa nhà của các nhân viên khác và nhà thầu;', 'Tham gia vào việc dọn dẹp, sửa chữa đơn giản và bảo dưỡng bên trong khu nhà;', 'Coi giữ lò sưởi và bình nước nóng để đảm bảo việc cung cấp nhiệt và nước nóng;', 'Điều chỉnh hành vi của người thuê và khách trong các vấn đề như giảm tiếng ồn hoặc lạm dụng tài sản;', 'Cung cấp dịch vụ nhỏ cho người thuê vắng mặt như nhận giao hàng thay mặt họ hoặc cung cấp thông tin được yêu cầu cho người gọi;', 'Thông báo cho người quản lý hoặc chủ tòa nhà về các yêu cầu sửa chữa chính;', 'Tuần tra tòa nhà để đảm bảo an ninh được duy trì;', 'Điền vào mẫu đăng ký và cung cấp cho người thuê các bản sao của các quy tắc.']::text[], array['Người giữ nhà', 'Nhân viên bảo vệ (tòa nhà)', 'Người gác cổng', 'Người trông nom nhà thờ']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1763) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5161', 'Nhà chiêm tinh, nhà tướng số và những người có liên quan đến tâm linh khác nhắc lại quá khứ và dự đoán tương lai của cuộc đời con người qua tử vi, xem đặc điểm lòng bàn tay, rút thẻ hoặc các kỹ thuật khác.', array['Viết lá số tử vi cho các cá nhân khi mới sinh ra hoặc khi đã lớn lên để kể lại quá khứ và dự báo các sự kiện và điều kiện sống của họ trong tương lai;', 'Xem đặc điểm lòng bàn tay của khách hàng, rút thẻ, vị trí của lá trầu hoặc bã cà phê trong cốc, hình dạng và mẫu xương động vật chết…', 'Dự báo sự kiện tương lai dựa vào những hiểu biết;', 'Xem ngày giờ tốt cho các sự kiện như lễ nhậm chức, kết hôn, những chuyến đi, những lễ kỷ niệm và tôn giáo khác;', 'Đưa ra những cảnh báo và lời khuyên về các hoạt động;', 'Đưa ra những lời khuyên để tránh những điềm xấu có thể xảy ra.']::text[], array['Nhà chiêm tinh', 'Nhà tướng số', 'Nhà số học', 'Người xem tướng tay']::text[], array['Thầy lang - 3230', 'Người chữa lành đức tin - 3413']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1782) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5162', 'Người bồi phòng và những người được thuê để làm bầu bạn cung cấp sự đồng hành và đáp ứng các nhu cầu khác nhau của khách hàng.', array['Cung cấp người làm bầu bạn đến khách hàng như đi cùng người đó đến những điểm khác nhau, đọc sách, tham gia vào nhiều hoạt động như thể thao;', 'Hỗ trợ khách hàng giải trí tại nhà;', 'Giữ giường tủ và đồ dùng cá nhân gọn gàng.']::text[], array['- Người đồng hành', '- Người giúp việc cá nhân', '- Người bồi phòng']::text[], array['Quản gia - 5152', 'Bạn nhảy - 5169', 'Người hộ tống -5169']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1799) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5163', 'Người làm nghề phục vụ tang lễ và ướp xác lo hậu sự và thực hiện các công việc trong quá trình ướp xác.', array['Sắp xếp và tiến hành tang lễ, hỏa táng và chôn cất;', 'Ướp xác hoặc làm chậm quá trình phân rã;', 'Đảm bảo sức khỏe và vệ sinh môi trường cũng như tuân thủ các yêu cầu pháp lý liên quan đến việc ướp xác;', 'Đóng vết mổ trên các bộ phận khác nhau của cơ thể và định hình hoặc cấu trúc lại những phần bị biến dạng hoặc bị thương trên cơ thể con người nếu cần thiết;', 'Thay đồ cho người chết và đưa vào quan tài;', 'Lấy tư liệu để chuẩn bị cáo phó, hỗ trợ việc lựa chọn quan tài hoặc quách, xác định địa điểm và thời gian chôn cất hoặc hỏa táng.']::text[], '{}'::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1813) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5164', 'Nhân viên chăm sóc và làm đẹp động vật nuôi dưỡng, chăm sóc, huấn luyện và làm đẹp động vật; trợ giúp bác sỹ thú y, kỹ thuật viên thú y và kỹ thuật viên trong cửa hàng thú y, trại huấn luyện động vật, chăn nuôi gia súc, vườn thú, phòng thí nghiệm, cửa hàng bán lẻ vật nuôi, trường đua, trường huấn luyện chó, cơ sở làm đẹp vật nuôi và tương tự.', array['Tắm và cho động vật ăn;', 'Dắt hoặc mang động vật đến phòng chữa trị và trông coi chúng trong quá trình chữa trị;', 'Vệ sinh và khử trùng dụng cụ phẫu thuật thú y;', 'Ghi nhãn thuốc, hóa chất và các chế phẩm dược phẩm; bổ sung kho;', 'Khử trùng chai, lọ và các thiết bị khác;', 'Vệ sinh, tổ chức và khử trùng khu động vật như chỗ quây, chuồng, lồng, bãi, thiết bị như yên ngựa và dây cương;', 'Thu thập và ghi lại các thông tin động vật như trọng lượng, kích thước, tình trạng thể lực, phương pháp điều trị và thức ăn nhận được;', 'Huấn luyện vật nuôi để phát triển và duy trì cho các cuộc thi, giải trí, an ninh, cưỡi và các hoạt động khác;', 'Làm đẹp vật nuôi như tắm, chải, cắt tỉa lông, cắt móng, làm sạch tai.']::text[], array['Nhân viên trông coi động vật', 'Nhân viên huấn luyện chó', 'Nhân viên huấn luyện ngựa', 'Trợ lý thú y', 'Nhân viên giữ vườn thú']::text[], '{}'::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1822) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5165', 'Giáo viên hướng dẫn lái xe dạy cách lái xe có động cơ', array['Hướng dẫn học viên lái xe trong điều kiện thực tế, giải thích và chứng minh các hoạt động của hệ thống phanh, ly hợp, lựa chọn bánh, hộp số tự động, tín hiệu và đèn;', 'Hướng dẫn các quy tắc giao thông;', 'Hướng dẫn bảo đảm an toàn;', 'Tư vấn cho học viên khi họ chuẩn bị trải qua kỳ kiểm tra lái xe;', 'Tư vấn và giảng dạy kỹ thuật lái xe tiên tiến cần thiết cho tình huống khẩn cấp;', 'Minh họa và giải thích các hoạt động xử lý và cơ khí của xe có động cơ và lái xe kỹ thuật, sử dụng biểu đồ và hỗ trợ nghe nhìn.']::text[], '{}'::text[], array['Người hướng dẫn bay - 3153']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1840) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5169', 'Nhân viên dịch vụ cá nhân khác chưa được phân vào đâu bao gồm những người cung cấp dịch vụ như bạn nhảy, người hộ tống, nhân viên hoặc chủ câu lạc bộ đêm.', array['Đi cùng khách đến nhà hàng và các chuyến đi chơi;', 'Bạn nhảy;', 'Chào đón khách đến câu lạc bộ đêm và bảo đảm họ được giải trí tốt.']::text[], array['Chủ câu lạc bộ', 'Nhân viên câu lạc bộ', 'Bạn nhảy', 'Người hộ tống']::text[], array['Người đồng hành - 5162', '(Xem tiếp Công báo số 1149 + 1150)', 'Số 1149 + 1150 Ngày 12 tháng 12 năm 2020', 'MỤC LỤC', 'VĂN BẢN QUY PHẠM PHÁP LUẬT', 'THỦ TƯỚNG CHÍNH PHỦ', 'Quyết định số 34/2020/QĐ-TTg ngày 26 tháng 11 năm 2020', 'ban hành Danh mục nghề nghiệp Việt Nam', '(Tiếp theo Công báo số 1147 + 1148)', 'Phụ lục II', 'NỘI DUNG DANH MỤC NGHỀ NGHIỆP VIỆT NAM', '(Ban hành kèm theo Quyết định số 34/2020/QĐ-TTg', 'ngày 26 tháng 11 năm 2020 của Thủ tướng Chính phủ)', '________________']::text[], null, '2020_1147 + 1148_34-2020-QĐ-TTg.doc', 1851) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5211', 'Người bán hàng trong quầy hàng và tại chợ bán hàng hóa khác nhau ở các quầy hàng trong chợ xây kiên cố hoặc chợ ngoài trời, các quầy hàng trên đường phố hoặc các không gian mở.', array['Xin phép thiết lập gian hàng tại một địa điểm cụ thể trên đường phố, chợ hoặc các không gian mở khác;', 'Xác định hỗn hợp sản phẩm, tồn kho và mức giá bán của hàng hóa được bán ra;', 'Mua hoặc ký hợp đồng cung cấp hàng hóa thường xuyên từ nhà bán buôn hoặc trực tiếp từ nhà sản xuất;', 'Dựng và tháo dỡ quầy hàng; vận chuyển, lưu trữ, bốc xếp hàng hóa để bán;', 'Giới thiệu, bán hàng và chấp nhận thanh toán;', 'Sắp xếp và hiển thị hàng hóa bán, đóng gói bao bì hàng hóa bán;', 'Giữ sổ sách kế toán và duy trì hàng hóa trong kho.']::text[], array['Người bán hàng ở các kiốt', 'Người bán hàng trong chợ', 'Người bán hàng rong trong chợ', 'Người trợ giúp bán hàng trên phố']::text[], array['Người bán đồ ăn trên đường phố - 5212', 'Chủ cửa hiệu - 5221', 'Người trợ giúp bán hàng cho cửa hàng - 5223', 'Nhân viên phục vụ đồ ăn uống - 5246', 'Người bán hàng rong trên phố (trừ đồ ăn) - 9520']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 41) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5212', 'Người bán đồ ăn trên đường phố chuẩn bị và bán đồ ăn uống nóng hoặc lạnh ăn ngay trên phố hoặc những nơi công cộng như nhà ga, rạp chiếu phim hoặc nhà hát.', array['Được cho phép hoặc có giấy phép ở những nơi yêu cầu, để bán đồ ăn uống trên phố hoặc ở những nơi công cộng;', 'Lấy thực phẩm và đồ uống để bán;', 'Chuẩn bị trước hoặc tại chỗ thực phẩm và đồ uống để bán;', 'Xếp và dỡ; đẩy, đạp xe hoặc mang xe ba gác, xe tải, khay hay giỏ để chuyển đồ ăn uống đến vị trí mong muốn trên đường phố hoặc nơi công cộng như nhà ga, rạp chiếu phim hoặc nhà hát.', 'Trưng bày, bán và tính tiền đồ ăn uống.']::text[], array['Người bán hàng rong (đồ ăn uống)', 'Người bán đồ ăn trên đường phố']::text[], array['Đầu bếp - 5120', 'Nhân viên phục vụ đồ ăn uống - 5246', 'Người chuẩn bị đồ ăn nhanh - 9401', 'Người bán hàng rong trên đường phố (trừ đồ ăn) - 9520']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 62) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5221', 'Chủ cửa hiệu điều hành các cửa hàng bán lẻ nhỏ độc lập hoặc với sự hỗ trợ từ một số ít người khác.', array['Quyết định sản phẩm pha trộn, lưu kho và mức giá bán;', 'Mua và sắp xếp hàng hóa bán từ nhà bán buôn và các nhà cung cấp khác;', 'Ghi lại ngân quỹ và hàng tồn kho cũng như các giao dịch tài chính;', 'Quyết định giá bán và giới thiệu hàng bán;', 'Bán hàng cho khách và tư vấn;', 'Kiểm tra hàng trả lại và ra quyết định phù hợp;', 'Kiểm kê hàng hóa trong kho.']::text[], array['Người bán tạp hóa', 'Người bán báo', 'Chủ cửa hiệu']::text[], array['Quản lý cửa hàng - 1744', 'Người bán hàng trong chợ - 5211', 'Ghi chú:', 'Chỉ những người điều hành các cửa hàng nhỏ mà việc quản lý và giám sát nhân viên không phải là một thành phần quan trọng của công việc được phân loại vào nhóm 5221 - Chủ cửa hiệu. Người điều hành cửa hàng nơi nhiệm vụ quản lý và giám sát nhân viên là yếu tố quan trọng và thường xuyên của công việc được phân loại vào nhóm 1744. Nhân viên kiểm soát và điều phối các hoạt động của trợ lý bán hàng cửa hàng, nhân viên kiểm tra và nhân viên khác, nhưng không chịu trách nhiệm xác định sản phẩm hỗn hợp, thiết lập tổng thể của giá cả, ngân sách, lựa chọn và tuyển dụng nhân viên được phân loại vào nhóm 5222 - Nhân viên giám sát cửa hàng.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 81) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5222', 'Nhân viên giám sát cửa hàng giám sát và điều phối các hoạt động của nhân viên trợ giúp bán hàng, nhân viên kiểm tra và các nhân viên khác trong cửa hàng bán buôn hoặc bán lẻ như trong siêu thị và cửa hàng bách hóa.', array['Lên kế hoạch và chuẩn bị các lịch trình làm việc và phân công nhân viên với nhiệm vụ cụ thể;', 'Hướng dẫn nhân viên quy trình bán hàng bao gồm cả việc làm thế nào để xử lý các trường hợp khó hoặc phức tạp;', 'Đảm bảo khách hàng nhận được dịch vụ nhanh chóng;', 'Tham gia, cung cấp tư vấn cho các quản lý khi phỏng vấn, tuyển dụng, đào tạo, đánh giá, đề bạt và sa thải nhân viên, giải quyết các khiếu nại của nhân viên;', 'Kiểm tra về hàng hóa trả lại và ra quyết định phù hợp;', 'Tham gia kiểm kê hàng hóa và đặt hàng mới;', 'Đảm bảo hàng hóa và dịch vụ đúng giá và được niêm yết;', 'Đảm bảo quy trình an toàn được thực hiện.']::text[], array['Giám sát viên thu ngân', 'Giám sát viên siêu thị']::text[], array['Quản lý cửa hàng - 1744', 'Người bán hàng trên phố - 5211', 'Chủ cửa hiệu - 5221']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 100) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5223', 'Nhân viên trợ giúp bán hàng bán nhiều loại hàng hóa và dịch vụ trực tiếp cho khách hàng hoặc thay mặt cơ sở bán buôn và bán lẻ, giải thích đặc điểm và chất lượng của hàng hóa và dịch vụ đó.', array['Xác định yêu cầu của khách hàng và tư vấn về dòng sản phẩm, giá, vận chuyển, bảo hành, hướng dẫn sử dụng;', 'Giới thiệu và giải thích với khách hàng về hàng hóa và dịch vụ;', 'Bán hàng hóa và dịch vụ, nhận tiền qua các phương thức thanh toán khác nhau, chuẩn bị hóa đơn bán và sử dụng máy tính tiền;', 'Hỗ trợ quản lý kho như sản phẩm tồn kho, tham gia kiểm kê;', 'Sắp xếp và trưng bày các sản phẩm để bán và đóng gói hàng hóa bán ra.']::text[], array['Nhân viên bán hàng (cơ sở bán lẻ)', 'Nhân viên bán hàng (cơ sở bán buôn)', 'Nhân viên trợ giúp bán hàng']::text[], array['Quản lý cửa hàng - 1744', 'Người bán hàng ở các kiot - 5211', 'Người bán hàng trong chợ - 5211', 'Người bán hàng trên phố - 5211', 'Người bán đồ ăn trên đường phố - 5212', 'Chủ cửa hiệu - 5221', 'Nhân viên thu ngân - 5230', 'Nhân viên phục vụ đồ ăn uống - 5246']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 118) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5230', 'Nhân viên thu ngân và bán vé sử dụng máy tính tiền, máy quét mã, máy tính và các thiết bị khác để ghi lại và chấp nhận thanh toán cho việc mua hàng hóa, dịch vụ trong cửa hàng, nhà hàng và phòng bán vé.', array['Nhận và xác nhận thanh toán bằng tiền mặt, séc, thẻ tín dụng hoặc thẻ ghi nợ tự động trong cửa hàng, phòng vé hoặc các cơ sở tương tự;', 'Trả tiền lẻ và nhận hóa đơn;', 'Phát hành vé cho khán giả sự kiện văn hóa và thể thao;', 'Đếm và ghi lại số tiền nhận được và cân đối với hồ sơ bán hàng của máy tính tiền;', 'Nhận tiền mặt, kiểm tra biên lai và các giấy tờ khác, chuẩn bị gửi tiền đến ngân hàng;', 'Dùng máy tính tiền để tính toán tiền trả lại hoặc nhận từ khách hàng;', 'Quét mã, cân và tính giá hàng hóa;', 'Gói và cho hàng hóa vào túi.']::text[], array['Nhân viên thu ngân', 'Nhân viên thu ngân tại các trạm dịch vụ', 'Nhân viên thu ngân cửa hàng', 'Nhân viên phát hành vé (sự kiện giải trí và thể thao)']::text[], array['Nhân viên phát hành vé (du lịch) - 4221', 'Giám sát viên thu ngân - 5222', 'Nhân viên trợ giúp bán hàng - 5223', 'Nhân viên phục vụ ở các trạm dịch vụ - 5245']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 139) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5241', 'Nhân viên làm mẫu mặc và trình diễn quần áo, phụ kiện; đưa ra hình ảnh, phim, video, quảng cáo, chụp ảnh tĩnh hoặc cho sáng tạo nghệ thuật.', array['Mặc mẫu kiểu dáng mới hoặc hiện tại theo yêu cầu của khách hàng;', 'Làm mẫu để giới thiệu đặc điểm, ưu điểm, kiểu dáng của trang phục, phụ kiện thời trang và hàng hóa khác.', 'Ngồi làm mẫu vẽ cho các tác phẩm điêu khắc, hội họa và các loại hình nghệ thuật thị giác khác;', 'Tạo dáng chụp ảnh tĩnh cho các tạp chí và các phương tiện quảng cáo;', 'Tạo dáng cho quảng cáo truyền hình, video, điện ảnh và các sản phẩm khác.']::text[], array['Người mẫu quảng cáo', 'Người mẫu nghệ thuật', 'Người mẫu thời trang']::text[], array['Diễn viên - 2655']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 163) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5242', 'Nhân viên thuyết minh giới thiệu hàng hóa ở các cơ sở thương mại, triển lãm và nhà riêng.', array['Trưng bày và giới thiệu sản phẩm bán để cho khách hàng biết được về đặc điểm của chúng, cơ chế hoạt động cũng như tạo sự quan tâm mua hàng;', 'Trả lời câu hỏi và tư vấn hướng dẫn sử dụng;', 'Bán hàng hoặc hướng dẫn khách hàng đến nhân viên bán hàng;', 'Nhận đơn đặt hàng, sắp xếp thanh toán, giao hàng và thu tiền hàng hóa;', 'Cung cấp hàng mẫu, phân phối danh mục và tài liệu quảng cáo.']::text[], array['Nhân viên thuyết minh', 'Nhân viên bán hàng']::text[], array['Người bán hàng trong chợ - 5211', 'Người bán hàng trên phố - 5211', 'Nhân viên bán hàng tận nhà - 5243']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 177) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5243', 'Nhân viên bán hàng tận nhà mô tả, giới thiệu và bán hàng hóa, dịch vụ; thu hút kinh doanh cho các cơ sở qua việc tiếp cận hoặc thăm hỏi khách hàng tiềm năng bằng cách đến tận nhà.', array['Cung cấp chi tiết về hàng hóa hoặc dịch vụ khác nhau bằng cách đến thăm khách hàng và khách hàng tiềm năng tại nhà riêng;', 'Giới thiệu hoặc mô tả hàng hóa và dịch vụ được cung cấp;', 'Ghi lại đơn đặt hàng, giao dịch và địa điểm nhận hàng với người cung cấp;', 'Chuẩn bị hóa đơn, hợp đồng mua bán và nhận thanh toán;', 'Chuyển thư, thông tin và các tài liệu khác cho khách hàng;', 'Tổng hợp danh sách khách hàng tiềm năng và giới thiệu họ về kinh doanh mới;', 'Qua lại giữa điểm bán hàng và khách hàng; vận chuyển mẫu hoặc hàng hóa để bán.']::text[], array['Nhân viên bán hàng tận nhà', 'Nhân viên đại diện bán hàng giao tận nhà', 'Nhân viên bán hàng trong các sự kiện tại nhà']::text[], array['Nhân viên đại diện bán hàng hóa thương mại - 3322', 'Người bán hàng rong trên phố - 9520']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 192) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5244', 'Nhân viên bán hàng qua trung tâm liên lạc liên lạc với khách hàng hiện tại và tiềm năng qua điện thoại hoặc phương tiện truyền thông điện tử khác để giới thiệu hàng hóa và dịch vụ. Họ có thể làm việc từ một trung tâm liên lạc hoặc từ cơ sở không tập trung.', array['Xúc tiến bán hàng hóa và dịch vụ bằng điện thoại hoặc thư điện tử theo kịch bản và danh sách các địa chỉ liên hệ;', 'Tạo sự quan tâm đến hàng hóa và dịch vụ, tìm kiếm doanh số hoặc thỏa thuận để gặp đại diện bán hàng;', 'Sắp xếp và gửi hàng hóa, dịch vụ, thông tin, tài liệu quảng cáo cho khách hàng;', 'Sắp xếp các cuộc hẹn cho đại diện bán hàng;', 'Ghi lại lưu ý cho các hoạt động tiếp theo và cập nhật cơ sở dữ liệu thị trường để phản ánh thay đổi tình trạng của mỗi khách hàng;', 'Báo cáo hoạt động của các đối thủ cạnh tranh và các vấn đề phát sinh bằng việc liên hệ với quản lý;', 'Duy trì thống kê các cuộc gọi thực hiện và cuộc gọi thành công;', 'Nộp báo cáo định kỳ về các hoạt động và kết quả tiếp thị từ xa.']::text[], array['Nhân viên bán hàng qua trung tâm điện thoại', 'Nhân viên bán hàng qua trung tâm liên lạc khách hàng', 'Nhân viên bán hàng qua Intenet', 'Nhân viên tiếp thị qua điện thoại', 'Nhân viên bán hàng qua điện thoại']::text[], array['Nhân viên trung tâm thông tin liên lạc - 4222']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 209) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5245', 'Nhân viên phục vụ ở các trạm dịch vụ bán nhiên liệu, dầu mỡ bôi trơn và các sản phẩm khác của ô tô và cung cấp dịch vụ như tiếp nhiên liệu, làm sạch, bôi trơn và thực hiện sửa chữa nhỏ của xe có động cơ.', array['Đổ nhiên liệu vào thùng và bình theo yêu cầu của khách hàng;', 'Kiểm tra, bơm lốp xe, thay dầu và các nhiên liệu khác;', 'Rửa kính chắn gió xe và cửa sổ;', 'Thực hiện việc sửa chữa nhỏ cho các loại xe như thay lốp xe, bóng đèn và lưỡi gạt nước kính chắn gió;', 'Duy trì và sử dụng máy rửa xe tự động;', 'Thu các khoản thanh toán từ khách hàng;', 'Làm sạch máy bơm xăng, đường vào của xe, cửa hàng và các thiết bị khác;', 'Kiểm soát kho, chuẩn bị báo cáo về nhiên liệu, dầu, thiết bị và các sản phẩm được bán ra.']::text[], array['Nhân viên phục vụ trên tàu thủy', 'Nhân viên phục vụ ở các trạm dịch vụ']::text[], array['Nhân viên trợ giúp bán hàng ở cửa hàng - 5223', 'Nhân viên thu ngân ở các trạm dịch vụ - 5230', 'Nhân viên phục vụ đồ ăn uống - 5246', 'Ghi chú:', 'Nhân viên thanh toán hoặc bán hàng hóa trong các cửa hàng tại các trạm dịch vụ nhưng không cung cấp dịch vụ như hỗ trợ nhiên liệu, dầu nhờn, làm sạch và bảo trì được loại trừ khỏi nhóm này.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 228) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5246', 'Nhân viên phục vụ đồ ăn uống phục vụ khách hàng tại quầy thực phẩm và chuẩn bị món ăn, đồ uống đơn giản trong nhà hàng, quán cà phê, khách sạn, quầy ăn nhanh, nhà ăn, bệnh viện và các cơ sở khác.', array['Phục vụ đồ ăn cho khách hàng tại quầy;', 'Tìm sản phẩm mong muốn cho khách hàng, giúp họ lựa chọn và đặt hàng;', 'Làm sạch, gọt vỏ, cắt tỉa thực phẩm bằng tay hoặc bằng máy;', 'Chuẩn bị đồ ăn đơn giản và hâm nóng bữa ăn;', 'Chia và gói thức ăn hoặc đặt lên đĩa phục vụ trực tiếp cho khách hàng;', 'Đóng túi thức ăn mang đi;', 'Bảo quản lạnh và ghi lại số lượng đã sử dụng;', 'Nhận thanh toán thực phẩm được mua.']::text[], array['Nhân viên quán ăn tự phục vụ', 'Nhân viên phục vụ salad']::text[], array['Đầu bếp - 5120', 'Bồi bàn - 5131', 'Nhân viên pha chế - 5132', 'Người bán hàng ở các kiot - 5211', 'Người bán hàng ở chợ - 5211', 'Người bán hàng trên phố - 5211', 'Người chuẩn bị đồ ăn nhanh - 9401', 'Ghi chú:', 'Người bán hàng trên đường phố và ở chợ bán các sản phẩm thực phẩm tươi sống không dành cho tiêu dùng ngay lập tức (như trái cây, rau, thịt và các sản phẩm từ sữa) được phân loại trong nhóm 5211 - Người bán hàng trong quầy hàng và tại chợ. Người bán hàng tại các quầy hàng trên đường phố và ở chợ với nhiều loại thực phẩm chế biến sẵn để tiêu thụ ngay lập tức được phân loại trong nhóm 5246 - Nhân viên phục vụ đồ ăn uống. Người bán thức ăn và đồ uống để tiêu thụ ngay lập tức trên đường phố và nơi công cộng từ xe đẩy, xe tải, khay hoặc giỏ được phân loại trong nhóm 5212 - Người bán đồ ăn trên đường phố. Người bán trên đường phố và nơi công cộng của các mặt hàng phi thực phẩm (hoặc các mặt hàng thực phẩm không dễ hỏng đóng gói sẵn như bánh kẹo) từ xe đẩy, xe tải, khay hoặc giỏ được phân loại trong nhóm 9520 -Người bán hàng rong trên đường phố (trừ đồ ăn). Người chuẩn bị các mặt hàng thực phẩm đơn giản để tiêu thụ ngay lập tức chẳng hạn như bánh hamburger nhưng hạn chế tiếp xúc trực tiếp với khách hàng được phân loại trong nhóm 9401 - Người chuẩn bị đồ ăn nhanh.', 'Những người bán thực phẩm để tiêu thụ ngay lập tức đòi hỏi phải có kỹ năng phục vụ, chuẩn bị cơ bản và xử lý vệ sinh thực phẩm. Nhân viên phục vụ đồ ăn uống thường phục vụ nhiều loại sản phẩm và bữa ăn phức tạp hơn so với người bán thức ăn đường phố và thường không vận chuyển đồ ăn hoặc bán đồ ăn từ các thiết bị như xe tay, xe đạp hoặc giỏ.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 248) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5249', 'Bao gồm những nhân viên bán hàng chưa được phân vào đâu ở nhóm 52 - Nhân viên bán hàng.', '{}'::text[], array['Nhân viên bán hàng cho thuê']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 273) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5311', 'Nhân viên chăm sóc trẻ em cung cấp dịch vụ chăm sóc và giám sát cho trẻ em ở nhà và ở trường, sau giờ học, ngày nghỉ và ở trung tâm chăm sóc ban ngày.', array['Hỗ trợ trẻ em tắm rửa, mặc quần áo và cho ăn;', 'Đưa trẻ đến trường và từ trường về hoặc ra ngoài giải trí;', 'Chơi với trẻ, thư giãn với trẻ bằng cách đọc sách hoặc kể chuyện;', 'Hỗ trợ trong việc chuẩn bị tài liệu hoặc thiết bị cho hoạt động giáo dục hoặc giải trí;', 'Quản lý các hành vi của trẻ và hướng dẫn chúng phát triển xã hội;', 'Kỷ luật và đưa ra các biện pháp để kiểm soát hành vi của trẻ như tự giặt quần áo, nhặt đồ chơi và sách;', 'Quan sát và theo dõi các hoạt động vui chơi của trẻ;', 'Lưu giữ hồ sơ về từng trẻ bao gồm những quan sát và thông tin hàng ngày về các hoạt động, bữa ăn được phục vụ và thuốc được quản lý.']::text[], array['Người giữ trẻ', 'Nhân viên chăm sóc trẻ em', 'Nhân viên chăm sóc gia đình hàng ngày', 'Nhân viên chăm sóc ngoài giờ học']::text[], array['Giáo viên mầm non - 2342']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 283) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5312', 'Người phụ tá cho giáo viên không thực hiện nhiệm vụ giảng dạy mà hỗ trợ giáo viên, chăm sóc và giám sát học sinh ở trường học.', array['Giới thiệu, giám sát và tham gia hoạt động giúp tăng cường sự phát triển thể chất, xã hội, cảm xúc và trí tuệ cho học sinh ở trường;', 'Chuẩn bị khu vực trong và ngoài lớp cho việc học và hoạt động giải trí;', 'Hỗ trợ học sinh gặp khó khăn về trí tuệ, thể chất, hành vi và việc học tập;', 'Hỗ trợ cá nhân học sinh học các kỹ năng xã hội;', 'Hỡ trợ chuẩn bị tài liệu giảng dạy, in chụp tài liệu;', 'Sử dụng thiết bị nghe nhìn, máy tính và thiết bị giảng dạy khác;', 'Phát và thu tài liệu bài học.']::text[], array['Phụ tá ở trường mầm non', 'Giáo viên trợ giảng']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 301) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5321', 'Nhân viên hỗ trợ về chăm sóc sức khỏe cung cấp dịch vụ chăm sóc và hỗ trợ trực tiếp cá nhân với các hoạt động sinh hoạt hàng ngày cho bệnh nhân và người dân trong các cơ sở chăm sóc sức khỏe như bệnh viện, phòng khám, cơ sở chăm sóc điều dưỡng nội trú. Họ thực hiện kế hoạch và chăm sóc dưới sự giám sát trực tiếp của điều dưỡng hoặc chuyên gia y tế hoặc kỹ thuật viên sức khỏe khác.', array['Cung cấp việc chăm sóc, hỗ trợ và điều trị cho bệnh nhân và người dân theo kế hoạch điều trị được thiết lập bởi các chuyên gia y tế, điều dưỡng khác;', 'Hỗ trợ bệnh nhân có nhu cầu chăm sóc cá nhân và điều trị như vệ sinh cá nhân, cho ăn, mặc quần áo, vận động về thể chất, tập thể dục, giao tiếp, uống thuốc và thay băng;', 'Di chuyển vị trí, nâng và vận chuyển bệnh nhân bằng xe lăn hoặc giường di chuyển;', 'Giữ vệ sinh môi trường như làm sạch phòng bệnh nhân, thay ga gối;', 'Massage và thực hiện các biện pháp giảm đau không dùng thuốc khác như trong khi mang thai hoặc chuyển dạ;', 'Quan sát tình trạng, phản ứng và hành vi của bệnh nhân; báo cáo thay đổi cho chuyên gia y tế chuyên trách.']::text[], array['Hộ lý sinh sản (phòng khám hoặc bệnh viện)', 'Trợ lý y tá/điều dưỡng (phòng khám hoặc bệnh viện)', 'Phụ tá chăm sóc bệnh nhân', 'Hỗ trợ bệnh nhân tâm thần']::text[], array['Y tá/điều dưỡng cao cấp - 2221', 'Y tá/điều dưỡng chính - 3221', 'Nhân viên cứu thương - 3258', 'Trợ lý y tá/điều dưỡng (tại nhà) - 5322', 'Ghi chú:', 'Nhân viên chăm sóc cá nhân cho người dân của các cơ sở có giám sát y tế hoặc điều dưỡng lâu dài (như bệnh viện, trung tâm phục hồi chức năng, cơ sở điều dưỡng nội trú và nhà dưỡng lão) và do đó làm việc dưới sự giám sát trực tiếp của y tá, bác sĩ y khoa hoặc các chuyên gia y tế được phân loại trong nhóm 5321 - Nhân viên hỗ trợ về chăm sóc sức khỏe. Nhân viên chăm sóc cá nhân cho người dân của các cơ sở độc lập, thường không có giám sát y tế hoặc điều dưỡng lâu dài nên được phân loại trong nhóm 5322 - Nhân viên chăm sóc cá nhân tại nhà. Nói chung, các nhân viên được phân loại trong nhóm 532 - Nhân viên chăm sóc cá nhân trong các dịch vụ y tế không thực hiện các nhiệm vụ đòi hỏi kiến ​​thức hoặc đào tạo y tế sâu rộng mà thường thực hiện các nhiệm vụ đơn giản như quản lý thuốc, làm sạch và băng vết thương.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 317) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5322', 'Nhân viên chăm sóc cá nhân tại nhà cung cấp dịch vụ chăm sóc và hỗ trợ tại nhà với các hoạt động sinh hoạt hàng ngày cho những người cần được chăm sóc do ảnh hưởng của tuổi tác, bệnh tật, chấn thương hoặc các lý do về thể lực và tinh thần khác tại nhà riêng hoặc khu dân cư độc lập khác.', array['Hỗ trợ khách hàng có nhu cầu chăm sóc và điều trị cá nhân như vệ sinh cá nhân, cho ăn, mặc quần áo, hoạt động về thể chất và tập thể dục, giao tiếp, uống thuốc, thay băng, thường theo kế hoạch chăm sóc được thiết lập bởi chuyên gia y tế;', 'Duy trì hồ sơ chăm sóc khách hàng, thay đổi tình trạng và phản ứng điều trị; báo cáo vấn đề lưu ý hoặc giới thiệu đến một cơ sở dịch vụ sức khỏe hoặc xã hội chuyên nghiệp;', 'Cố định hoặc nâng khách hàng để vận chuyển trên xe lăn hoặc xe có động cơ;', 'Cung cấp cho khách hàng và gia đình hỗ trợ tinh thần, thông tin và tư vấn về dinh dưỡng, vệ sinh, tập thể dục, chăm sóc trẻ sơ sinh hoặc thích ứng cho người khuyết tật hoặc người bệnh;', 'Duy trì các tiêu chuẩn vệ sinh môi trường cho khách hàng như thay ga gối, giặt quần áo, rửa bát đĩa và làm sạch khu nhà ở;', 'Cung cấp hỗ trợ tâm lý cho khách hàng thông qua các cuộc trò chuyện;', 'Lập kế hoạch, mua, chuẩn bị hoặc phục vụ bữa ăn để đáp ứng nhu cầu dinh dưỡng và chế độ ăn kiêng theo quy định;', 'Cung cấp hỗ trợ cho cha mẹ và chăm sóc trẻ sơ sinh trong giai đoạn sau sinh;', 'Lên lịch và đi cùng khách hàng đến các cuộc hẹn với bác sĩ và các chuyên gia y tế khác hoặc thực hiện các công việc nhỏ khác.']::text[], array['Hộ lý sinh tại nhà', 'Nhân viên chăm sóc tại nhà', 'Trợ lý y tá/điều dưỡng tại nhà', 'Nhân viên cung cấp dịch vụ chăm sóc cá nhân']::text[], array['Y tá/điều dưỡng cao cấp - 2221', 'Nhà chuyên môn về xã hội - 2635', 'Y tá/điều dưỡng chính - 3221', 'Nhân viên về công tác xã hội - 3412', 'Hộ lý sinh sản (phòng khám hoặc bệnh viện) - 5321', 'Ghi chú:', 'Nhân viên chăm sóc cá nhân cho người dân của các cơ sở y tế và chăm sóc sức khỏe có giám sát y tế hoặc điều dưỡng lâu dài (như trong bệnh viện và nhà dưỡng lão) và làm việc dưới sự giám sát trực tiếp của các chuyên gia y tế hoặc các kỹ thuật viên sức khỏe được phân loại trong nhóm 5321 - Nhân viên hỗ trợ về chăm sóc sức khỏe. Nhân viên chăm sóc cá nhân trong môi trường dân cư độc lập (bao gồm cả cộng đồng hưu trí với sự giám sát y tế hoặc điều dưỡng tại chỗ) không được phân loại trong nhóm 5322 - Nhân viên chăm sóc cá nhân tại nhà. Hộ lý sinh tại nhà, những người cung cấp dịch vụ hỗ trợ, chăm sóc, tư vấn chung cho phụ nữ và gia đình trong khi mang thai và chuyển dạ để giảm rủi ro sức khỏe nhưng không chăm sóc sinh nở được phân loại ở đây. Nhân viên chăm sóc và giám sát trẻ em tại nhà dân và trung tâm chăm sóc được phân loại trong nhóm 5311 - Nhân viên chăm sóc trẻ em.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 338) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5329', 'Nhân viên chăm sóc cá nhân trong các dịch vụ y tế chưa được phân vào đâu bao gồm các nghề hỗ trợ nha khoa, hỗ trợ khử trùng, hỗ trợ chuẩn đoán hình ảnh y tế và hỗ trợ dược phẩm.', array['Làm sạch và khử trùng dụng cụ phẫu thuật, nha khoa, dược phẩm, chai, lọ và các thiết bị khác;', 'Ghi nhãn thuốc, hóa chất và các chế phẩm dược phẩm khác; bổ sung hàng dự trữ vào kho;', 'Nâng, di chuyển bệnh nhân và vận chuyển họ trên xe lăn hoặc giường di chuyển;', 'Chuẩn bị cho bệnh nhân khám và điều trị;', 'Xếp khay dụng cụ, chuẩn bị hồ sơ và hỗ trợ nha sĩ hoặc bác sĩ chụp X-quang trong khi làm thủ tục;', 'Lấy chuẩn đoán X-quang.']::text[], array['Trợ lý nha khoa', 'Trợ lý sơ cứu', 'Tạp vụ bệnh viện', 'Trợ lý hình ảnh y tế', 'Phụ tá dược', 'Người lấy máu', 'Trợ lý khử trùng']::text[], array['Trợ lý dược - 3213', 'Kỹ thuật viên nha khoa - 3214', 'Phụ tá nha khoa - 3251']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 363) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5401', 'Nhân viên an ninh bảo vệ trật tự, tuần tra khu vực, thực hiện luật pháp và các quy định, bắt giữ người phạm tội bị nghi ngờ.', array['Tuần tra một khu vực cụ thể để duy trì trật tự công cộng, ứng phó với trường hợp khẩn cấp, bảo vệ con người và tài sản, thực thi pháp luật và quy định;', 'Xác định, truy bắt nghi phạm và thủ phạm có hành vi phạm tội;', 'Hướng dẫn giao thông và bảo vệ hiện trường trong trường hợp có tai nạn;', 'Hỗ trợ khẩn cấp cho các nạn nhân của vụ tai nạn, tội phạm và thiên tai.']::text[], array['An ninh dân phòng.']::text[], array['Cảnh sát trưởng - 0210', 'Chánh thanh tra cảnh sát - 0210']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 387) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('5409', 'Nhân viên dịch vụ bảo vệ khác chưa được phân vào đâu có thể bao gồm nhân viên cứu hộ, nhân viên dẫn đường và kiểm soát viên động vật…', array['Tuần tra bãi biển và bể bơi để bảo vệ khỏi tai nạn và đuối nước;', 'Giám sát lưu lượng giao thông để xác định khoảng cách an toàn mà người đi bộ có thể qua đường;', 'Trả lời khiếu nại liên quan đến các vật nuôi, thú nuôi và động vật hoang dã; phát hành các cảnh báo, trích dẫn cho chủ sở hữu và động vật bị mất, động vật hoang dã và nguy hiểm;', 'Tuần tra một khu vực được chỉ định về quy định đỗ xe;', 'Điều tiết giao thông.']::text[], array['Thám tử tư', 'Nhân viên kiểm soát động vật', 'Nhân viên tuần tra bãi biển', 'Nhân viên dẫn đường', 'Nhân viên bảo vệ rừng', 'Nhân viên cứu hộ', 'Nhân viên điều tiết giao thông']::text[], array['Nhân viên gác cửa - 5401', 'Bảo vệ bảo tàng - 5401', 'Tuần tra an ninh - 5401']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 399) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6111', 'Lao động trồng, thu hoạch rau và cây mùa vụ lập kế hoạch, tổ chức và thực hiện các hoạt động canh tác để trồng và thu hoạch các loại cây khác nhau như lúa và ngũ cốc khác, củ cải đường, mía, lạc, thuốc lá, cây lau và cây mùa vụ khác, khoai tây, cải bắp và các loại rau khác để bán hoặc phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc bán tại chợ.', array['- Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng cây trồng, lập kế hoạch và điều phối sản xuất phù hợp;', '- Chuẩn bị đất bằng tay hoặc bằng máy, rải phân bón và phân chuồng;', '- Lựa chọn và gieo hạt giống, cây giống và trồng;', '- Chăm sóc cây trồng bằng cách canh tác đất, cấy ghép, cắt tỉa, thiết lập và vận hành thiết bị tưới tiêu;', '- Kiểm soát cỏ dại, sâu bệnh bằng cách sử dụng thuốc diệt cỏ và thuốc trừ sâu;', '- Thu hoạch mùa màng và phá bỏ cây trồng bị bệnh hoặc thừa;', '- Kiểm tra, làm sạch, phân loại, đóng gói và bảo quản tại kho; phân phối cây trồng để bán và cung cấp ra thị trường.', '- Chăm sóc động vật làm việc và bảo trì trang trại, nhà xưởng, thiết bị và hệ thống cung cấp nước;', '- Bảo quản tại kho và thực hiện chế biến một số sản phẩm;', '- Giới thiệu và tiếp thị sản phẩm; sắp xếp việc mua, bán và vận chuyển sản phẩm; cung cấp, theo dõi và đánh giá các hoạt động và giao dịch của trang trại;', '- Đào tạo và giám sát người lao động trong sản xuất mùa vụ, đảm bảo các biện pháp phòng ngừa an toàn và sức khỏe; thuê và sa thải người lao động và các nhà thầu.']::text[], array['- Nông dân trồng ngũ cốc', '- Nông dân trồng bông', '- Nông dân trồng khoai tây', '- Nông dân trồng lúa', '- Công nhân trang trại có kỹ năng (lĩnh vực cây trồng)', '- Công nhân trồng mía đường']::text[], array['- Giám đốc sản xuất nông nghiệp - 1721, 1741', '- Lao động trồng trọt - 9201', 'Ghi chú:', 'Người trồng rau sử dụng các kỹ thuật canh tác thâm canh được phân loại trong nhóm 6113 - Lao động làm vườn, trong nhà kính, vườn ươm.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 428) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6112', 'Lao động trồng, thu hoạch sản phẩm cây bụi và cây thân gỗ lên kế hoạch, tổ chức và thực hiện các hoạt động canh tác để trồng và thu hoạch trái cây, hạt cây, chè, cà phê, ca cao, cao su, nhựa cây… để bán hoặc phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc bán tại chợ.', array['- Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng cây trồng, lập kế hoạch và điều phối sản xuất phù hợp;', '- Chuẩn bị đất bằng tay hoặc bằng máy; rải phân bón và phân chuồng;', '- Lựa chọn hạt giống, gieo hạt và trồng cây;', '- Duy trì các loại cây trồng bằng cách canh tác đất, cấy, cắt tỉa hoặc tỉa thưa cây gỗ và cây bụi; thiết lập và vận hành thiết bị tưới tiêu;', '- Kiểm soát cỏ dại, sâu bệnh bằng cách sử dụng thuốc diệt cỏ và thuốc trừ sâu;', '- Chăm sóc cây, thu hoạch nhựa cây và sản phẩm;', '- Kiểm tra, làm sạch, phân loại, đóng gói, bảo quản tại kho và vận chuyển để bán hoặc cung cấp cho thị trường.', '- Chăm sóc động vật làm việc, bảo trì trang trại, thiết bị, nhà xưởng và hệ thống cấp nước;', '- Bảo quản tại kho và thực hiện một số sơ chế;', '- Giới thiệu và tiếp thị sản phẩm; lên kế hoạch mua, bán và vận chuyển sản phẩm; theo dõi và đánh giá về các hoạt động và giao dịch của trang trại;', '- Đào tạo và giám sát người lao động trong việc trồng cây, đảm bảo nhiệm vụ bảo trì và các biện pháp đảm bảo an toàn và sức khỏe; tuyển dụng, sa thải người lao động và các nhà thầu.']::text[], array['- Nông dân trồng cây ăn quả', '- Nông dân trồng cây cao su', '- Nông dân trồng chè', '- Nông dân trồng nho']::text[], array['- Nhà quản lý trồng trọt - 1721, 1741', '- Người hái hoa quả - 9201']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 454) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6113', 'Lao động làm vườn, trồng vườn và vườn ươm lên kế hoạch, tổ chức và thực hiện các hoạt động để trồng và chăm sóc cây, cây bụi, hoa và cây cảnh khác trong công viên và khu vực nhà riêng; sản xuất cây non, củ, hạt giống hoặc trồng rau và hoa bằng các kỹ thuật canh tác thâm canh để bán hoặc phân phối thường xuyên cho người mua buôn, tổ chức tiếp thị và tại chợ.', array['- Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng rau, các sản phẩm ươm để trồng; lập kế hoạch và điều phối sản xuất cho phù hợp;', '- Cải tạo đất, san lấp mặt bằng, lắp đặt và vận hành hệ thống tưới tiêu;', '- Trồng cây, cây leo, cỏ và cây trong vườn;', '- Cắt tỉa cây, cây bụi, cây leo; lắp đặt hệ thống giá đỡ và bảo vệ, cán, cắt, viền thảm cỏ;', '- Xây dựng các tính năng và tiện nghi trong vườn như đường dẫn hoặc khu vực lát đá, tường, hồ, hệ thống nước, nhà kho và hàng rào;', '- Kiểm tra cây và cây giống, tìm và xử lý cỏ dại, sâu bệnh, sử dụng mùn và phân bón;', '- Sản xuất cây giống, củ và hạt; trồng cây từ hạt hoặc giâm cành;', '- Thu hoạch cây trồng, kiểm tra, làm sạch, phân loại, đóng gói, bảo quản tại kho các sản phẩm để bán hoặc phân phối đến thị trường;', '- Bảo trì các tòa nhà, nhà kính, các cấu trúc, thiết bị và hệ thống cấp nước;', '- Bảo quản tại kho và sơ chế sản phẩm;', '- Giới thiệu và tiếp thị sản phẩm; sắp xếp việc mua, bán và vận chuyển sản phẩm; theo dõi và đánh giá hồ sơ về các hoạt động và giao dịch;', '- Đào tạo và giám sát người lao động trong các nhiệm vụ sản xuất, bảo trì, đảm bảo sức khỏe và an toàn; tuyển dụng và sa thải người lao động và các nhà thầu.']::text[], array['- Người làm vườn', '- Người chăm sóc cảnh quan', '- Người trồng nấm']::text[], array['- Nhà khoa học làm vườn - 2132', '- Lao động làm vườn - 9204', '- Lao động trồng vườn - 9204', 'Ghi chú:', 'Những người trồng cây bụi và cây ăn quả trong vườn được phân loại trong nhóm 6112 - Lao động trồng, thu hoạch sản phẩm cây bụi và cây thân gỗ trừ khi điều này được thực hiện kết hợp với làm vườn nói chung hoặc trồng trọt làm vườn. Người trồng rau trên các cánh đồng không sử dụng kỹ thuật canh tác thâm canh được phân loại trong nhóm 6111 - Lao động trồng, thu hoạch rau và cây mùa vụ.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 476) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6114', 'Lao động trồng trọt hỗn hợp lập kế hoạch, tổ chức và thực hiện các hoạt động canh tác để trồng và thu hoạch cây trồng, rau, cây bụi, các sản phẩm làm vườn, trồng vườn và vườn ươm để bán hoặc giao cho người mua buôn, tổ chức tiếp thị và tại chợ.', array['- Giám sát hoạt động và tình hình thị trường; xác định loại và số lượng cây trồng; lập kế hoạch và điều phối sản xuất phù hợp;', '- Chuẩn bị đất bằng tay hoặc bằng máy; rải phân bón và phân chuồng;', '- Lựa chọn hạt giống, gieo hạt và trồng cây con;', '- Duy trì các loại cây trồng bằng cách canh tác đất, cấy, cắt tỉa hoặc tỉa thưa cây gỗ và cây bụi, thiết lập và vận hành thiết bị tưới tiêu;', '- Trồng hoa và rau chuyên canh;', '- Sản xuất cây giống, củ và hạt;', '- Thu hoạch, kiểm tra, làm sạch, phân loại, đóng gói, bảo quản tại kho và vận chuyển để bán hoặc cung cấp cho thị trường.', '- Chăm sóc động vật làm việc; bảo trì trang trại, thiết bị và hệ thống cấp nước;', '- Bảo quản tại kho và thực hiện một số sơ chế;', '- Giới thiệu và tiếp thị sản phẩm, sắp xếp việc mua, bán và vận chuyển sản phẩm; theo dõi, đánh giá hồ sơ về các hoạt động và giao dịch;', '- Đào tạo và giám sát người lao động trong các nhiệm vụ sản xuất, bảo trì và các biện pháp bảo đảm an toàn và sức khỏe; tuyển dụng và sa thải người lao động và các nhà thầu.']::text[], array['- Nông dân mùa vụ hỗn hợp', '- Lao động trang trại có kỹ năng (mùa vụ hỗn hợp)']::text[], array['- Giám đốc sản xuất nông nghiệp - 1721, 1741', '- Nhà quản lý cây trồng - 1721, 1741', '- Lao động trồng trọt - 9201', '- Người hái hoa quả - 9201']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 501) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6121', 'Lao động chăn nuôi gia súc và vật nuôi lấy sữa lên kế hoạch, tổ chức và thực hiện các hoạt động chăn nuôi để nhân giống và chăn nuôi gia súc (không bao gồm gia cầm) như trâu, bò, cừu, lợn, dê, ngựa, lạc đà để lấy thịt, sữa, da, len hoặc để làm việc, thể thao hay giải trí, để bán cho người mua bán buôn, tổ chức tiếp thị hoặc thị trường.', array['- Giám sát hoạt động và tình hình thị trường; xác định loại và số lượng chăn nuôi; lập kế hoạch và điều phối sản xuất phù hợp;', '- Canh tác đồng cỏ; theo dõi và cung cấp thức ăn, nguồn nước để duy trì mức độ dinh dưỡng thích hợp và các điều kiện chăn nuôi;', '- Theo dõi và kiểm tra động vật để phát hiện bệnh tật, thương tích; kiểm tra tình trạng sức khỏe như tỷ lệ tăng cân;', '- Chải chuốt, đánh dấu, cắt, tỉa, thiến động vật và cạo lông để lấy lông hoặc len;', '- Chăn gia súc ở các đồng cỏ hoặc chuồng, nhà kho, xe hoặc các khu vực khác;', '- Vắt sữa động vật bằng tay hoặc máy;', '- Trộn thức ăn, phụ gia và thuốc theo quy định và cho động vật ăn;', '- Thực hiện các nhiệm vụ liên quan đến sinh sản vật nuôi như cho ăn, thụ tinh nhân tạo và đỡ đẻ cho động vật;', '- Bảo trì và vệ sinh trang trại, máy móc, thiết bị và công trình;', '- Giết mổ, lột da động vật và cung cấp cho thị trường;', '- Bảo quản tại kho và thực hiện một số chế biến sản phẩm động vật và sữa;', '- Giới thiệu và tiếp thị sản phẩm; sắp xếp việc mua, bán, vận chuyển, sản xuất và cung ứng gia súc; theo dõi, đánh giá hồ sơ về các hoạt động và giao dịch của trang trại;', '- Đào tạo và giám sát người lao động trong các quy trình chăm sóc động vật, bảo đảm nhiệm vụ bảo trì và các biện pháp phòng ngừa an toàn và sức khỏe; tuyển dụng, sa thải người lao động và các nhà thầu.']::text[], array['- Công nhân chăn nuôi có kỹ năng (gia súc)', '- Nông dân chăn nuôi gia súc', '- Nông dân chăn nuôi bò sữa', '- Người lai giống chó', '- Người lai giống ngựa', '- Người cắt cỏ', '- Nông dân nuôi dê', '- Nông dân chăn cừu', '- Nông dân chăn ngựa', '- Nông dân nuôi hươu sao']::text[], array['- Giám đốc sản xuất nông nghiệp - 1721, 1741', '- Nhà quản lý trang trại - 1721, 1741', 'Ghi chú:', 'Những người sản xuất và lưu trữ cỏ khô và thức ăn gia súc khác để tiêu thụ cho gia súc mà họ nuôi được phân loại trong nhóm 6121 - Lao động chăn nuôi gia súc và vật nuôi lấy sữa.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 526) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6122', 'Lao động chăn nuôi gia cầm lên kế hoạch, tổ chức và thực hiện các hoạt động chăn nuôi như nuôi gà, gà tây, ngỗng, vịt và các gia cầm khác để sản xuất thịt, trứng để bán hoặc giao cho người mua buôn, tổ chức tiếp thị hoặc tại chợ.', array['- Giám sát hoạt động thị trường, lập kế hoạch và điều phối sản xuất cho phù hợp; duy trì và đánh giá hồ sơ các hoạt động nông nghiệp;', '- Trồng hoặc mua thức ăn và các nguồn cung cấp khác cần thiết để duy trì mức dinh dưỡng và điều kiện thích hợp cho gia cầm;', '- Theo dõi và kiểm tra gia cầm để phát hiện bệnh tật, thương tích và kiểm tra tình trạng thể chất như tốc độ tăng trọng và loại bỏ gia cầm yếu, bị bệnh hoặc chết khỏi đàn;', '- Trộn thức ăn và các chất phụ gia thức ăn chăn nuôi, đưa vào các hộp đựng thức ăn và dụng cụ chứa nước;', '- Tiêm phòng cho gia cầm qua nước uống, tiêm hoặc hút bụi không khí;', '- Thu thập, bảo quản trứng và đóng gói để bán hoặc cung cấp cho thị trường;', '- Xác định giới tính của gà con và tạo điều kiện thuận lợi cho sinh sản, thụ tinh nhân tạo và ấp trứng;', '- Thuê hoặc đầu tư, bảo trì và làm sạch trang trại, máy móc, thiết bị và công trình;', '- Giết mổ và làm sạch gia cầm để bán hoặc cung cấp cho thị trường;', '- Bảo quản tại kho và sơ chế sản phẩm;', '- Sắp xếp việc mua, bán, vận chuyển và cung cấp hàng;', '- Đào tạo và giám sát người lao động ở trại nuôi gia cầm về quy trình sản xuất, nhiệm vụ bảo trì, các biện pháp phòng ngừa an toàn và sức khỏe; tuyển dụng và sa thải người lao động và các nhà thầu.']::text[], array['- Người chăn nuôi gia cầm', '- Nông dân chăn nuôi gia cầm', '- Nhà thầu chăn nuôi gia cầm']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 558) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6123', 'Lao động nuôi ong và nuôi tằm lên kế hoạch, tổ chức và thực hiện các hoạt động nhân giống, nuôi và chăm sóc các côn trùng như ong, tằm và các loài khác để sản xuất mật ong, sáp ong, tơ tằm và các sản phẩm khác để bán hoặc giao cho người mua buôn, tổ chức tiếp thị hoặc tại chợ.', array['- Giám sát hoạt động và tình hình của thị trường, xác định loại và số lượng sản phẩm côn trùng để sản xuất, lập kế hoạch và điều phối sản xuất phù hợp;', '- Mua côn trùng; trồng hoặc mua thức ăn và các vật tư khác;', '- Chăn nuôi và chăm sóc các loài côn trùng và thu các sản phẩm của chúng;', '- Thuê hoặc đầu tư, bảo trì và vệ sinh trang trại, máy móc, thiết bị và công trình;', '- Bảo quản tại kho và sơ chế các sản phẩm;', '- Sắp xếp việc mua, bán, vận chuyển, sản xuất và cung cấp; theo dõi và đánh giá hồ sơ của các hoạt động chăn nuôi;', '- Đào tạo và giám sát người lao động về quy trình sản xuất, nhiệm vụ bảo trì, các biện pháp phòng ngừa an toàn và sức khỏe; tuyển dụng và sa thải người lao động và các nhà thầu.']::text[], '{}'::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 577) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6129', 'Lao động chăn nuôi chưa được phân vào đâu bao gồm những người tham gia chăn nuôi, nuôi và chăm sóc động vật có vú hoang dã, thú săn, các loài chim khác (trừ gia cầm), ốc, rắn và loài bò sát khác cũng như các loại côn trùng và động vật khác được sử dụng để thử nghiệm trong phòng thí nghiệm, để bán hoặc giao hàng thường xuyên đến người mua buôn, tổ chức tiếp thị, vườn thú, rạp xiếc hoặc các thị trường.', array['- Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng sản phẩm để sản xuất, lập kế hoạch và điều phối sản xuất phù hợp;', '- Nuôi, cho ăn và chăm sóc động vật;', '- Theo dõi và kiểm tra động vật để phát hiện bệnh tật, chấn thương, kiểm tra tình trạng sức khỏe như tỷ lệ tăng cân;', '- Thực hiện các nhiệm vụ liên quan đến sinh sản động vật như cho ăn, thụ tinh nhân tạo và đỡ đẻ cho động vật;', '- Thuê hoặc đầu tư, bảo trì và làm sạch trang trại, máy móc, thiết bị và công trình;', '- Giết mổ và lột da động vật để bán hoặc cung cấp cho thị trường;', '- Lưu trữ và sơ chế sản phẩm;', '- Quảng bá và tiếp thị sản phẩm; sắp xếp việc mua, bán, vận chuyển, sản xuất và cung ứng; theo dõi và đánh giá hồ sơ về các hoạt động và giao dịch;', '- Đào tạo và giám sát người lao động về quy trình chăm sóc động vật, nhiệm vụ bảo trì, các biện pháp phòng ngừa an toàn và sức khỏe; tuyển dụng và sa thải người lao động và các nhà thầu.']::text[], array['- Nông dân nuôi cá sấu', '- Nông dân nuôi động vật lấy lông (động vật hoang dã)', '- Người nuôi chim cảnh', '- Nông dân nuôi đà điểu', '- Nông dân nuôi ốc sên']::text[], array['- Nhân viên trông coi động vật - 5164', '- Nhân viên giữ vườn thú - 5164', '- Nhân viên kiểm soát động vật - 5409', '- Người chăn nuôi gia cầm - 6122']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 587) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6130', 'Lao động trồng trọt và chăn nuôi hỗn hợp lên kế hoạch, tổ chức và thực hiện các hoạt động canh tác để trồng và thu hoạch cây và các loại mùa vụ khác cũng như nhân giống, nuôi, chăm sóc động vật và sản xuất nhiều loại sản phẩm chăn nuôi để bán hoặc phân phối đến người mua buôn, tổ chức tiếp thị hoặc thị trường.', array['- Giám sát hoạt động và tình hình thị trường, xác định loại và số lượng cây trồng và vật nuôi; lập kế hoạch và điều phối sản xuất cho phù hợp;', '- Mua hạt giống, phân bón và các vật tư khác;', '- Thực hiện các hoạt động như làm đất, gieo hạt, trồng, canh tác và thu hoạch cây trồng;', '- Sản xuất hoặc mua thức ăn gia súc và các nguồn cung cấp thực phẩm khác;', '- Chăn nuôi và chăm sóc động vật;', '- Giết mổ và lột da động vật, chuẩn bị động vật hoặc sản phẩm động vật cho thị trường;', '- Thuê hoặc đầu tư, bảo trì và vệ sinh trang trại, máy móc, thiết bị và công trình;', '- Lưu trữ và sơ chế sản phẩm;', '- Giới thiệu và tiếp thị sản phẩm; sắp xếp việc mua, bán, vận chuyển gia súc, sản xuất và cung ứng; theo dõi và đánh giá hồ sơ về các hoạt động và giao dịch của trang trại;', '- Đào tạo và giám sát người lao động về các quy trình sản xuất, nhiệm vụ bảo trì, các biện pháp phòng ngừa an toàn và sức khỏe; tuyển dụng và sa thải người lao động và các nhà thầu.']::text[], array['- Nông dân canh tác hỗn hợp;', '- Công nhân nông nghiệp có kỹ năng (trang trại hỗn hợp)']::text[], array['- Giám đốc sản xuất nông nghiệp - 1721, 1741', '- Nhà quản lý trồng trọt - 1721, 1741', '- Lao động trồng trọt và chăn nuôi hỗn hợp - 9203', 'Ghi chú:', 'Nông dân và các công nhân nông nghiệp có kỹ năng khác có nhiệm vụ chủ yếu liên quan đến chăn nuôi hoặc trồng trọt nhưng cũng liên quan đến một số hoạt động ngẫu nhiên trong việc trồng trọt hoặc chăm sóc động vật không nên được đưa vào nhóm 6130 - Lao động trồng trọt và chăn nuôi hỗn hợp. Ví dụ, một nông dân nuôi gia súc để bán cho thị trường nhưng cũng dành một ít thời gian để trồng rau trong vườn nên được phân loại trong nhóm 6121 - Lao động chăn nuôi gia súc và vật nuôi lấy sữa. Tương tự, một nông dân trồng lúa mì nuôi một số lượng nhỏ gà và các động vật khác trong trang trại nên được phân loại trong nhóm 6111 - Lao động trồng, thu hoạch rau và cây mùa vụ.', 'Công nhân tại các trang trại hỗn hợp chuyên sản xuất cây trồng hoặc sản xuất động vật cho thị trường nên được phân loại trong nhóm 611 - Lao động trồng trọt và làm vườn có sản phẩm chủ yếu để bán hoặc 612 - Lao động chăn nuôi, nếu phù hợp.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 610) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6210', 'Lao động trong lâm nghiệp và lĩnh vực có liên quan lập kế hoạch, tổ chức và thực hiện các hoạt động canh tác, bảo tồn và khai thác rừng tự nhiên và rừng trồng.', array['- Đánh giá các khu vực để trồng lại rừng; chọn cây giống và trồng cây bằng các công cụ thủ công; thiết lập và chăm sóc khu vực rừng;', '- Xác định vị trí cây bị đốn hạ và ước tính khối lượng gỗ;', '- Sử dụng cưa xích và cưa điện cắt, chặt cây và cưa chúng thành các khúc gỗ;', '- Hình thành các sản phẩm gỗ thô từ các khối gỗ tròn tại nơi chặt hạ; xếp chồng vận chuyển chúng trong các máng hoặc trôi sông;', '- Theo dõi để phát hiện các vụ cháy rừng, tham gia các hoạt động chữa cháy, hoàn thành các báo cáo chữa cháy và bảo trì thiết bị chữa cháy;', '- Kiểm soát cỏ dại phát triển trong rừng tái sinh bằng các công cụ và hóa chất;', '- Vận hành và bảo dưỡng xe ủi đất, máy trượt hoặc xe vận chuyển khác để cày xới đất hoặc cải tạo khu vực trồng;', '- Thu nhặt hạt, cắt tỉa cây, hỗ trợ trong trồng khảo sát và đánh dấu cây cho hoạt động tiếp theo;', '- Đào tạo và giám sát người lao động khác trong các quy trình lâm nghiệp, bao gồm cả lao động lâm nghiệp và người vận hành nhà máy.']::text[], array['- Người đốt than', '- Người khai thác gỗ', '- Lao động có kỹ năng trong lâm nghiệp', '- Người tuần tra lâm nghiệp', '- Người đốn cây']::text[], array['- Chuyên gia lâm sinh - 2132', '- Kỹ thuật viên lâm nghiệp - 3143', '- Thợ vận hành máy đốn cây - 8341', '- Lao động lâm nghiệp - 9205']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 638) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6221', 'Lao động nuôi trồng thủy sản nuôi và thu hoạch cá, trai, hàu và các loại thủy sinh khác để bán hoặc phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc thị trường.', array['- Chăm sóc và nuôi cá, trai, hàu và các loại thuỷ sinh khác sống ở nước mặn và nước ngọt;', '- Thu thập và ghi tốc độ tăng trưởng, sản xuất và dữ liệu về môi trường;', '- Thực hiện và giám sát các kiểm tra để xác định bệnh hoặc ký sinh trùng;', '- Giám sát môi trường để đảm bảo duy trì các điều kiện sống tối ưu cho thủy sản;', '- Chỉ đạo và giám sát việc đánh bắt và sinh sản của cá, ấp trứng và chăm sóc, áp dụng các kiến thức về quản lý và kỹ thuật nuôi cá;', '- Làm sạch, đông lạnh hoặc ướp muối thủy sản đánh bắt; đóng lô cá và các sản phẩm khác để vận chuyển;', '- Bảo dưỡng trang trại, lồng cá, máy móc thiết bị, tàu thuyền và các thiết bị khác;', '- Cung cấp hoặc tiếp thị sản phẩm;', '- Thuê hoặc đầu tư vào các công trình, thiết bị và máy móc; mua thức ăn và các vật tư khác;', '- Giám sát và đào tạo người lao động về nuôi trồng thủy sản và trại cá.']::text[], array['- Người trồng tảo', '- Nông dân nuôi cá', '- Nông dân nuôi hàu', '- Người nuôi trai ngọc', '- Nông dân nuôi hải sản', '- Công nhân có kỹ năng trong trang trại thủy sản']::text[], array['- Nhà quản lý sản xuất nuôi trồng thủy sản - 1710, 1721, 1741', '- Lao động nuôi trồng thủy sản - 9206']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 664) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6222', 'Lao động khai thác thủy sản trong nội địa, một mình hoặc là thành viên của đội tàu đánh bắt cá hoặc các sinh vật dưới nước khác trong vùng biển nội địa hoặc ven biển để bán hoặc phân phối thường xuyên đến người mua buôn, tổ chức tiếp thị hoặc tại thị trường.', array['- Chuẩn bị và sửa chữa lưới, thiết bị và ngư cụ khác;', '- Lựa chọn khu vực để câu cá, tính toán các vị trí điều hướng bằng cách sử dụng la bàn, bản đồ và các công cụ hỗ trợ khác;', '- Điều hành các tàu đánh cá đến, đi từ cảng cá;', '- Cài đặt, vận hành và sử dụng ngư cụ bằng tay hoặc sử dụng thiết bị cẩu;', '- Đánh bắt các sinh vật thủy sinh từ ven biển và nội địa;', '- Bảo dưỡng động cơ, ngư cụ và các thiết bị trên tàu;', '- Lưu giữ hồ sơ về các giao dịch, hoạt động đánh bắt, thời tiết, điều kiện biển và ước tính chi phí và ngân sách;', '- Phân loại bảo quản bằng muối và nước đá;', '- Lấy các mẻ cá từ thiết bị câu cá, cân đo chúng để đảm bảo phù hợp với kích thước quy định và trả lại những sản phẩm khai thác không mong muốn hoặc bất hợp pháp vào nước;', '- Chỉ đạo hoạt động đánh bắt và giám sát các thành viên đội đánh bắt.']::text[], array['- Đội trưởng ngư nghiệp ven biển', '- Ngư dân vùng nước ven biển', '- Ngư dân vùng nước nội địa']::text[], array['- Nhà quản lý hoạt động thủy sản - 1710, 1721, 1741', '- Lao động khai thác thủy sản trong vùng biển Việt Nam - 6223', '- Thợ mò hàu - 7541', '- Lao động khai thác thủy sản - 9206']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 687) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6223', 'Lao động khai thác thủy sản trong vùng biển Việt Nam là chỉ huy hoặc thành viên của tàu cá, đánh cá ngoài khơi để bán hoặc giao cho người mua buôn, tổ chức tiếp thị hay thị trường.', array['- Chuẩn bị và sửa chữa lưới, ngư cụ và các thiết bị;', '- Chỉ huy và điều hành tàu cá đến, đi tại cảng cá;', '- Xác định khu vực đánh bắt cá, tính toán các vị trí điều hướng bằng cách sử dụng la bàn, bản đồ, bảng biểu và các công cụ hỗ trợ khác;', '- Điều khiển tàu, vận hành thiết bị dẫn đường và thiết bị điện tử hỗ trợ đánh cá;', '- Chỉ đạo hoạt động đánh bắt và giám sát các hoạt động của đoàn;', '- Ghi lại tiến trình và hoạt động đánh bắt cũng như thời tiết và tình hình biển vào nhật ký của tàu;', '- Đánh mồi, cài đặt và kéo ngư cụ;', '- Làm sạch, đông lạnh hoặc ướp muối để bán trong nước hoặc ngoài nước;', '- Lựa chọn và đào tạo thủy thủ tàu.']::text[], array['- Người khai thác thủy sản trong vùng biển Việt Nam', '- Đội trưởng tàu khai thác thủy sản']::text[], array['- Nhà quản lý hoạt động thủy sản - 1710, 1721, 1741', '- Chỉ huy tàu khai thác trong nội địa - 6222', '- Ngư dân (khai thác trong nội địa) - 6222', '- Lao động thủy sản - 9206']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 709) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6224', 'Lao động săn bắn, đánh bẫy giết động vật có vú, chim hoặc bò sát chủ yếu lấy thịt, da, lông và các sản phẩm khác để bán hoặc phân phối thường xuyên đến người bán buôn, tổ chức tiếp thị hoặc thị trường.', array['- Đặt bẫy để bắt động vật có vú, chim hoặc bò sát;', '- Giết bằng bẫy hoặc bắt tự do các động vật có vú, chim hoặc bò sát với vũ khí hoặc các công cụ khác;', '- Lấy da và các phần khác của động vật có vú, chim hoặc bò sát để có các sản phẩm muốn bán hoặc giao hàng;', '- Cung cấp hoặc bán động vật sống có vú, chim hoặc bò sát bị bẫy;', '- Sửa chữa và bảo trì thiết bị.']::text[], array['- Thợ bẫy lông', '- Thợ săn hải cẩu']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 729) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6310', 'Lao động trồng trọt tự cung tự cấp trồng và thu hoạch cây và bụi cây, rau và trái cây để có thực phẩm, nơi ở và trong một số trường hợp thu nhập tối thiểu cho bản thân và hộ gia đình.', array['- Chuẩn bị đất, gieo, trồng, chăm sóc và thu hoạch cây trồng;', '- Trồng rau, trái cây, các loại cây khác và cây bụi;', '- Lấy nước và kiếm củi;', '- Lưu trữ cho sử dụng sau này và sơ chế sản phẩm;', '- Xây dựng và bảo trì nhà cửa và đồ vật khác;', '- Chế tạo công cụ, quần áo và các đồ dùng sử dụng trong hộ gia đình;', '- Bán hoặc trao đổi một số sản phẩm tại thị trường địa phương.']::text[], array['- Nông dân trồng trọt', '- Lao động làm vườn tự cung tự cấp', '- Lao động trồng rau tự cung tự cấp']::text[], array['- Lao động nông trại - 9201', '- Người thu gom củi - 9624', '- Người thu gom nước - 9624', 'Ghi chú:', 'Người lao động trong môi trường sinh hoạt có nhiệm vụ chính là lấy nước và kiếm củi được phân loại trong nhóm 9624 - Người thu gom nước và củi. Người làm nông nghiệp tự cung tự cấp thực hiện một số ít các công việc đơn giản và thường xuyên thường dưới sự chỉ đạo của người khác được phân loại trong nhóm 92 - Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 746) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6320', 'Lao động chăn nuôi gia súc tự cung tự cấp nuôi và chăm sóc gia súc để cung cấp thức ăn cho gia đình và trong một số trường hợp thu nhập tối thiểu bằng tiền mặt cho bản thân và hộ gia đình.', array['- Canh tác đồng cỏ hoặc quản lý vùng đất chăn thả; giám sát thức ăn và nguồn cung cấp nước cần thiết để duy trì các điều kiện chăn nuôi;', '- Theo dõi và kiểm tra động vật để phát hiện bệnh tật, thương tích hay tình trạng thể chất;', '- Chải lông và đánh dấu động vật để lấy lông và len;', '- Chăn hoặc dẫn gia súc đến đồng cỏ, khoanh vùng đất chăn thả và nguồn cung cấp nước;', '- Nuôi, chăm sóc, vắt sữa hoặc lấy máu động vật;', '- Chăn nuôi và đỡ đẻ động vật;', '- Giết mổ, lột da động vật và chuẩn bị sản phẩm để tiêu dùng hoặc bán;', '- Thực hiện sơ chế động vật;', '- Xây dựng, bảo trì nhà cửa và các đồ vật khác;', '- Làm công cụ, quần áo và đồ dùng tự sử dụng trong hộ gia đình;', '- Lấy nước và kiếm củi;', '- Mua, trao đổi, bán động vật và một số sản phẩm.']::text[], array['- Nông dân chăn nuôi gia súc tự cung tự cấp']::text[], array['- Lao động trang trại chăn nuôi - 9202', '- Lao động trang trại trồng trọt và chăn nuôi hỗn hợp - 9203', '- Người thu gom nước và củi - 9624']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 766) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6330', 'Lao động trồng trọt và chăn nuôi hỗn hợp tự cung tự cấp trồng và thu hoạch vụ mùa hoặc cây và bụi cây, rau và trái cây; thu nhặt trái cây dại, thảo dược và thực vật khác; săn bắn động vật; đánh bắt cá và các loài thủy sinh để có thực phẩm cho gia đình và trong một số trường hợp thu nhập tối thiểu bằng tiền mặt cho bản thân và hộ gia đình.', array['- Chuẩn bị đất, gieo, trồng, chăm sóc và thu hoạch cây trồng mùa vụ;', '- Trồng rau, trái cây, các loại cây khác và cây bụi;', '- Thu nhặt trái cây dại, thảo dược và các thực vật khác;', '- Chăn nuôi, chăm sóc và nuôi dưỡng động vật và gia cầm chủ yếu để lấy thịt, trứng, sữa, lông, da hoặc các sản phẩm khác;', '- Lấy nước và kiếm củi;', '- Lưu trữ các sản phẩm để sử dụng sau này và thực hiện một số sơ chế sản phẩm;', '- Xây dựng và bảo trì nhà ở và các đồ vật khác;', '- Chế tạo dụng cụ, quần áo và đồ dùng tự sử dụng trong hộ gia đình;', '- Bán hoặc trao đổi một số sản phẩm tại thị trường địa phương.']::text[], array['- Nông dân trồng trọt và chăn nuôi hỗn hợp tự cung tự cấp']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 787) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('6340', 'Lao động đánh cá, săn bắn, đánh bẫy và thu hái tự cung tự cấp hái lượm trái cây dại, dược liệu và thực vật khác; săn bắt và bẫy động vật; bắt cá và các loài thủy sinh khác để có thực phẩm cho gia đình và trong một số trường hợp thu nhập tối thiểu bằng tiền mặt cho bản thân và hộ gia đình.', array['- Thu nhặt trái cây dại, rễ cây, dược liệu và thực vật khác;', '- Săn bắn hoặc bẫy động vật chủ yếu để lấy thịt, sữa, lông, da hoặc các sản phẩm khác;', '- Lấy nước và kiếm củi;', '- Đánh bắt cá và các loài thủy sinh khác;', '- Lưu trữ hoặc sơ chế sản phẩm;', '- Xây dựng, bảo trì nhà ở và các đồ vật khác;', '- Chế tạo dụng cụ, quần áo và các đồ dùng cho hộ gia đình sử dụng;', '- Bán hoặc trao đổi một số sản phẩm tại thị trường địa phương.']::text[], array['- Nông dân hái lượm tự cung tự cấp', '- Người thu hoạch tự cung tự cấp', '- Người lặn mò tự cung tự cấp', '- Người đánh cá tự cung tự cấp', '- Người đánh bẫy tự cung tự cấp']::text[], array['- Lao động trồng trọt tự cung tự cấp - 6310', '- Lao động chăn nuôi gia súc tự cung tự cấp - 6320', '- Lao động trang trại chăn nuôi - 9202', '- Người thu gom nước và củi - 9624']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 801) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7111', 'Thợ xây nhà xây, bảo trì và sửa chữa các ngôi nhà và các tòa nhà nhỏ tương tự bằng cách sử dụng các kỹ thuật và vật liệu truyền thống hoặc hiện đại.', array['Chuẩn bị mặt bằng để xây dựng tòa nhà hoặc các công trình xây dựng khác;', 'Xây dựng các cấu trúc để hỗ trợ mái nhà; xây dựng và phủ tường bằng các vật liệu thích hợp;', 'Cố định xà vào mái nhà và che bằng các nguyên liệu lợp mái;', 'San nền cho bằng phẳng và tiện lợi khi dùng;', 'Bảo dưỡng và sửa chữa các công trình xây dựng hiện có;', 'Sắp xếp các công việc chuyên môn như lát gạch, sơn tường, hệ thống ống nước và hệ thống dây điện được thực hiện bởi các nhà thầu phụ;', 'Điều phối và giám sát các hoạt động của các nhà thầu phụ và người lao động khác.']::text[], array['- Thợ xây nhà']::text[], array['- Giám đốc dự án xây dựng - 1723, 1743', '- Giám sát thi công xây dựng - 3123']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 834) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7112', 'Thợ nề và các thợ có liên quan xếp gạch, đá cắt sẵn và các loại khối xây dựng khác trong vữa để xây dựng và sửa chữa tường, vách ngăn, vòm và các cấu trúc khác.', array['- Xếp đá, gạch và các khối xây dựng tương tự để xây dựng và sửa chữa tường, vách ngăn, lò sưởi và các cấu trúc khác như ống khói, lò nướng, lò nung vôi, gạch… trụ cầu, móng cầu và các trụ chống, trụ đá;', 'Lát vỉa hè, lề đường, lối đi bộ;', 'Xếp gạch hoặc vật liệu khác để xây dựng sân, tường bao của vườn và các công trình trang trí khác.']::text[], array['- Thợ xây khối nhà', '- Thợ nề', '- Thợ xây ống khói', '- Thợ lát gạch chịu lửa']::text[], array['- Thợ xây nhà bằng đá - 7113']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 849) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7113', 'Thợ xây nhà bằng đá, thợ cắt đá, thợ tách đá và thợ khắc đá cắt và tạo hình các khối, tấm đá cứng và mềm để xây dựng và bảo trì các công trình xây dựng bằng đá; chạm khắc các kiểu dáng và hình vẽ trên đá.', array['- Lái máy ủi vào trong các mỏ đá khai thác để phá nó thành các khối hoặc tấm;', '- Lựa chọn và phân loại các tấm và khối đá granit, đá hoa cẩm thạch và các loại đá khác;', '- Cắt, tạo dáng và hoàn thiện các khối đá xây dựng bằng tay hoặc bằng các dụng cụ điện cầm tay đối với các tòa nhà, các công trình liên quan đến đài kỷ niệm bằng đá granit hoặc đá hoa cẩm thạch;', '- Tạo hoa văn và đánh dấu hình dạng trên đá để cưa, khoan, đẽo gọt, mài và cắt đá;', '- Cắt và chạm khắc các ký tự, hình vẽ hoặc thiết kế trên các khối đá được sử dụng cho các di tích hoặc đài tưởng niệm;', '- Sắp xếp, bố trí đá trong việc xây dựng các di tích và đài tưởng niệm;', '- Phục hồi, tu sửa và thay thế các công trình xây bằng đá của các tòa nhà cổ, nhà thờ và các di tích;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ cắt đá granit, hoa cương', '- Thợ cắt đá', '- Thợ khắc đá', '- Thợ đánh bóng đá (thủ công)']::text[], array['- Thợ lát sàn và tường - 7122', '- Thợ vận hành máy cắt hoặc chế biến đá - 8112']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 862) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7114', 'Thợ đổ bê tông và các thợ có liên quan dựng lên các khung và kết cấu bê tông cốt thép; tạo dáng cho các khuôn bê tông, gia cố bề mặt bê tông; chát xi măng trên tường hoặc bên ngoài giếng nước; hoàn thiện và sửa chữa các bề mặt xi măng.', array['- Xây dựng và sửa chữa sàn bê tông cốt thép, tường, bể chứa, hầm dưới đất để chứa đồ và các kết cấu bê tông khác;', '- Tạo các ván cốt pha hoặc lắp ráp các khuôn mẫu đúc sẵn để đúc bê tông;', '- Trát xi măng lên tường hoặc bên ngoài của giếng;', '- Hoàn thiện và làm phẳng bề mặt của các kết cấu bê tông;', '- Đắp xi măng, cát và các tấm đá hoa vào sàn nhà để bề mặt nhẵn và bền;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác']::text[], array['- Thợ hoàn thiện xi măng', '- Thợ đổ bê tông', '- Thợ nung đất']::text[], array['- Thợ vận hành máy hoàn thiện bê tông - 8114', '- Thợ vận hành máy san mặt đường - 8342']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 882) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7115', 'Thợ mộc và thợ làm đồ gỗ cắt, tạo hình, lắp ráp, chế tạo, bảo trì và sửa chữa các loại công trình và đồ đạc bằng gỗ.', array['- Chế tạo, thay đổi và sửa chữa kết cấu và các đồ gỗ khác tại bàn làm việc hoặc trên công trường xây dựng;', '- Xây dựng và lắp đặt các cấu trúc bằng gỗ nặng trên các khu đất đang xây dựng nhà ở;', '- Lắp ráp, thay đổi đồ đạc bên trong và bên ngoài của các tòa nhà như tường, cửa, khung cửa sổ và cửa ra vào, các bảng điều khiển;', '- Chế tạo, sửa chữa và lắp các thiết bị cảnh quan cho các buổi biểu diễn sân khấu, sản xuất phim điện ảnh hoặc các chương trình truyền hình;', '- Xây dựng, lắp đặt, thay đổi, sửa chữa đồ đạc và thiết bị bằng gỗ trong toa tàu, máy bay, tàu thủy, thuyền và các phương tiện khác;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ mộc', '- Thợ lắp cửa', '- Thợ mộc hoàn thiện', '- Thợ làm khung', '- Thợ làm đồ gỗ', '- Thợ đóng tàu bằng gỗ']::text[], array['- Thợ đóng tủ - 7522', '- Thợ đóng bánh xe lăn - 7522']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 899) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7119', 'Thợ xây dựng khung nhà và thợ khác có liên quan chưa được phân vào đâu ví dụ như thợ gác chuông, thợ giàn giáo và thợ phá dỡ.', array['- Leo trèo và thực hiện các công việc xây dựng và bảo trì các công trình cao như tháp, ống khói;', '- Dựng giàn giáo tạm thời bằng gỗ hoặc kim loại trên công trường;', '- Phá hủy các tòa nhà và các công trình xây dựng khác;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ phá dỡ nhà', '- Thợ lắp ráp nhà làm sẵn', '- Thợ giàn giáo', '- Thợ phá dỡ chuyên nghiệp', '- Thợ chữa tháp chuông, ống khói (chuyên leo lên các tháp chuông, ống khói cao... để sửa chữa, quét vôi)']::text[], array['- Lao động xây dựng - 9313', '- Lao động phá dỡ - 9313']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 919) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7121', 'Thợ lợp và sửa chữa mái nhà của tất cả các loại tòa nhà, sử dụng một hoặc nhiều loại vật liệu.', array['- Nghiên cứu các bản vẽ, thông số kỹ thuật và địa điểm xây dựng để xác định vật liệu cần thiết;', '- Bao phủ khung mái bằng đá phiến và gạch đúc sẵn để che mái nhà dốc;', '- Đặt tấm chắn chống thấm nước và cố định vật liệu kim loại hoặc tổng hợp để xây dựng khung tòa nhà;', '- Định cỡ và cắt vật liệu lợp để phù hợp với các cạnh, góc và các chỗ nhô lên như ống khói;', '- Sử dụng các vật liệu tự nhiên như tấm lợp để lợp mái;', '- Tạo ra các cấu trúc tạm thời như giàn giáo và thang.']::text[], array['- Thợ lợp mái nhựa', '- Thợ lợp mái kim loại', '- Thợ sửa mái nhà', '- Thợ lợp ngói', '- Thợ lợp mái bằng đá phiến', '- Thợ lợp rạ, tranh', 'Ghi chú:', 'Thợ lắp đặt mái nhà bằng kim loại được phân vào nhóm 7121 - Thợ lợp mái. Thợ sản xuất các sản phẩm kim loại tấm để lắp đặt bởi thợ lợp mái được phân loại trong nhóm 7213 - Thợ luyện kim loại.']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 939) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7122', 'Thợ lát sàn và thợ lát đá lắp đặt, bảo trì và sửa chữa sàn, phủ sàn, tường và các bề mặt khác bằng đá lát, gạch hoặc tấm khảm để trang trí hoặc các mục đích khác.', array['- Chuẩn bị bề mặt sàn nhà để lát với nhiều loại vật liệu;', '- Lắp đặt đá, gạch hoặc các vật liệu khác và đặt chúng trên sàn theo thiết kế và các thông số kỹ thuật khác;', '- Chuẩn bị bề mặt tường để lát với đá hoặc các vật liệu khác để trang trí hay theo các mục đích khác như cách âm;', '- Đặt đá lát và các tấm khảm lên tường, sàn nhà và các bề mặt khác;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ lát thảm', '- Thợ lát đá cẩm thạch', '- Thợ lát sàn gỗ', '- Thợ lát ngói.']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 957) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7123', 'Thợ thạch cao lắp đặt, bảo trì và sửa chữa tấm thạch cao trong các tòa nhà; sử dụng các lớp phủ trang trí và bảo vệ của thạch cao, xi măng và vật liệu tương tự cho nội thất và ngoại thất của các công trình.', array['- Trát một hay nhiều lớp thạch cao lên tường và trần của toà nhà để tạo ra bề mặt hoàn thiện;', '- Đo lường, đánh dấu và lắp đặt các tấm thạch cao trang trí; đúc và cắt các thạch cao trang trí;', '- Đo lường, đánh dấu và cắt tấm thạch cao; định vị và bảo vệ chúng vào tường, trần và ván sàn;', '- Che các mối nối và lỗ đinh bằng thạch cao ướt và các hợp chất hàn kín; làm mịn chúng bằng bàn chải ướt và giấy nhám;', '- Sử dụng các lớp phủ bảo vệ và trang trí bằng xi măng, thạch cao và các vật liệu tương tự cho các bề mặt xây dựng bên ngoài;', '- Chế tạo và lắp đặt đồ trang trí bằng thạch cao sợi;', '- Sử dụng và hoàn thiện vật liệu cách âm, cách nhiệt và chống cháy liên kết với thạch cao, xi măng và các vật liệu tương tự;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ thạch cao tường khô', '- Thợ thạch cao sợi', '- Thợ thạch cao trang trí', '- Thợ thạch cao', '- Thợ thạch cao rắn', '- Thợ thạch cao vữa']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 971) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7124', 'Thợ lắp đặt vật liệu cách âm, cách nhiệt lắp đặt và sửa chữa các vật liệu cách âm, cách nhiệt cho tòa nhà, nồi hơi, đường ống, thiết bị làm lạnh và máy điều hòa không khí.', array['- Cắt vật liệu cách âm, cách nhiệt theo kích thước và hình dáng;', '- Đặt các tấm và thanh cách nhiệt hoặc cách âm lên tường, dưới sàn nhà và trên trần nhà của các tòa nhà;', '- Thổi và hàn các vật liệu cách âm, cách nhiệt vào các lỗ hổng giữa hai bức tường, sàn và trần của các tòa nhà bằng máy chạy bằng điện;', '- Nghiên cứu các bản vẽ, thông số kỹ thuật và vị trí công trình xây dựng để xác định loại, chất lượng và số lượng của các vật liệu cách âm, cách nhiệt cần thiết;', '- Đặt các vật liệu cách âm, cách nhiệt cho các bề mặt tiếp xúc của thiết bị như nồi hơi, ống dẫn và bể chứa;', '- Cách nhiệt cho thiết bị làm lạnh và máy điều hòa không khí;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ cách âm', '- Thợ nồi hơi và ống cách nhiệt', '- Thợ lắp đặt cách nhiệt', '- Thợ cách nhiệt', '- Thợ cách nhiệt cho thiết bị làm lạnh và máy điều hòa không khí']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 990) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7125', 'Thợ lắp kính đo, cắt, hoàn thiện, lắp và lắp đặt kính phẳng và gương.', array['- Lựa chọn loại kính được sử dụng, cắt theo đúng kích thước, hình dạng và lắp chúng vào cửa sổ, cửa ra vào, buồng tắm và vách ngăn của các tòa nhà;', '- Lắp đặt kính và gương trong giếng trời, hộp trưng bày, tường và trần bên trong nhà;', '- Lắp đặt hoặc thay thế kính chắn gió của xe và tàu thuyền;', '- Tạo các kính trang trí như tường kính, cầu thang, lan can và cửa sổ kính màu;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ lắp kính tự động', '- Thợ lắp kính', '- Thợ lắp kính mái nhà', '- Thợ lắp kính ô tô']::text[], array['- Thợ cắt thủy tinh - 7315', '- Thợ hoàn thiện thủy tinh - 7315']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1007) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7126', 'Thợ ống nước lắp đặt, sửa chữa và bảo trì hệ thống đường ống, cống, máng xối, ống dẫn và các phụ kiện liên quan cho hệ thống nước, khí ga, hệ thống thoát nước, hệ thống sưởi, làm mát, thông gió, các thiết bị thủy lực và khí nén.', array['- Kiểm tra bản vẽ và thông số kỹ thuật để xác định bố trí hệ thống ống nước, thông gió và vật liệu cần thiết;', '- Đo lường, cắt, bắt ren, uốn, nối, lắp ráp, lắp đặt, bảo trì và sửa chữa đường ống, phụ kiện của hệ thống thoát nước, hệ thống sưởi ấm, thông gió, cấp nước và hệ thống thoát nước;', '- Lắp đặt các thiết bị ga, máy rửa bát, bình nước nóng, bồn rửa và bồn vệ sinh bằng dụng cụ cầm tay và điện;', '- Đặt ống bằng đất sét, bê tông hoặc gang trong rãnh, mương để tạo thành cống, ống dẫn nước, đường ống nước hoặc cho các mục đích khác;', '- Xem xét, kiểm tra và thử nghiệm các hệ thống và đường ống đã được lắp đặt, sử dụng đồng hồ đo áp suất, theo dõi và kiểm tra thủy tĩnh hoặc dùng các phương pháp khác;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ thoát nước', '- Thợ lắp bình gas', '- Thợ lắp ống xả', '- Thợ sửa đường ống nước', '- Thợ đường ống', '- Thợ lắp ống thông gió']::text[], array['- Thợ cơ khí thiết bị điều hòa không khí và làm lạnh - 7127', 'Ghi chú:', 'Thợ lắp đặt cống, máng xối và ống dẫn bằng kim loại được phân vào nhóm 7126 - Thợ ống nước. Thợ sản xuất các sản phẩm kim loại tấm cho thợ ống nước lắp đặt đường ống được phân vào nhóm 7213 - Thợ luyện kim loại.']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1024) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7127', 'Thợ cơ khí thiết bị điều hòa không khí và làm lạnh lắp đặt, bảo dưỡng và sửa chữa hệ thống và thiết bị điều hòa không khí và làm lạnh.', array['- Đọc bản thiết kế, bản vẽ và các thông số kỹ thuật;', '- Lắp đặt và sửa chữa các thành phần như máy nén, động cơ, bình ngưng, thiết bị bay hơi, công tắc và đồng hồ đo cho hệ thống điều hòa không khí và làm lạnh;', '- Kết nối hệ thống ống dẫn và các thiết bị bằng cách bắt bu-lông, đinh tán hoặc hàn lại;', '- Kiểm tra hệ thống, chẩn đoán lỗi và thực hiện các công việc bảo dưỡng định kỳ;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ cơ khí thiết bị điều hòa không khí', '- Thợ cơ điện lạnh']::text[], array['- Thợ sửa đường ống nước - 7126', '- Thợ lắp ống xả - 7126']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1045) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7131', 'Thợ sơn và thợ liên quan khác chuẩn bị bề mặt của các tòa nhà và công trình khác để sơn, quét các lớp sơn trang trí hay bảo vệ hoặc bằng các vật liệu tương tự; phủ lên tường và trần của tòa nhà bằng giấy dán tường hoặc các lớp hoàn thiện khác.', array['- Làm sạch và chuẩn bị tường hoặc các bề mặt khác của tòa nhà để sơn hoặc dán tường;', '- Lựa chọn và chuẩn bị sơn theo màu sắc yêu cầu bằng việc trộn lẫn hỗn hợp chất màu và chất phụ gia;', '- Quét hoặc phun sơn, véc ni và các vật liệu tương tự lên bề mặt, đồ đạc và phụ kiện trang trí của tòa nhà;', '- Đo và dán giấy dán tường hoặc các loại vải khác trên tường và trần nhà;', '- Quét sơn, véc ni và chất nhuộm màu lên bề mặt bằng bàn chải, con lăn và các bình xịt;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ sơn công trình', '- Thợ dán giấy dán tường']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1063) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7132', 'Thợ phun sơn và thợ đánh véc ni điều khiển các thiết bị phun sơn và đánh véc ni để tạo lớp phủ bảo vệ các mặt hàng sản xuất hoặc các vật kiến trúc.', array['- Chuẩn bị bề mặt cần phủ; sử dụng các phương pháp để loại bỏ dầu mỡ, bụi bẩn và rỉ sắt;', '- Sơn ô tô, xe buýt, xe tải và các phương tiện khác, phủ véc ni và các lớp sơn bảo vệ khác;', '- Phủ sơn hoặc đánh véc ni bằng thiết bị phun tay để bảo vệ kim loại, gỗ và các sản phẩm được sản xuất;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ sơn hàng công nghiệp chế tạo', '- Thợ đánh véc ni', '- Thợ sơn xe']::text[], array['- Thợ sơn công trình - 7131', '- Thợ sơn trang trí - 7316', '- Thợ vẽ biển quảng cáo - 7316', '- Thợ xử lý gỗ - 7521', '- Thợ vận hành máy mạ kim loại - 8122']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1076) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7133', 'Người lau dọn tòa nhà làm sạch bề mặt bên ngoài các tòa nhà và các công trình khác; loại bỏ bồ hóng từ các ống khói.', array['- Lau rửa bề mặt đá, gạch, kim loại hoặc các vật liệu tương tự bằng hóa chất, vòi tia nước hoặc cát được đặt dưới áp suất lớn;', '- Loại bỏ bồ hóng khỏi ống khói và ống nối;', '- Loại bỏ amiăng, nấm mốc và các bề mặt bị cháy từ các tòa nhà;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ lau chùi bên ngoài tòa nhà', '- Thợ quét dọn ống khói', '- Thợ phun cát (bên ngoài tòa nhà)']::text[], array['- Người lau hình vẽ trên tường - 9129', '- Người phun nước - 9129']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1094) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7211', 'Thợ tạo khuôn và lõi kim loại thực hiện tạo khuôn, lõi để đúc kim loại', array['- Làm khuôn bằng tay hoặc sử dụng máy phụ trợ trên băng ghế để đúc kim loại nhỏ, trên sàn đúc hoặc trong hố để đúc lớn;', '- Làm lõi để sử dụng trong khuôn kim loại;', '- Làm sạch và làm mịn khuôn, hộp lõi và sửa chữa các khiếm khuyết bề mặt;', '- Di chuyển và định vị các phần công việc như phần khuôn, hoa văn và bảng dưới cùng; sử dụng cần cẩu hoặc báo hiệu cho người khác để di chuyển các phần công việc;', '- Định vị các mẫu bên trong các phần khuôn và các phần kẹp với nhau;', '- Cắt vòi, lỗ chạy và lỗ phun vào khuôn;', '- Nâng các phần khuôn trên từ các phần thấp hơn và loại bỏ các mẫu đúc.']::text[], array['- Thợ làm lõi', '- Thợ tạo khuôn đúc kim loại']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1116) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7212', 'Thợ hàn và thợ cắt kim loại bằng nhiệt hàn và cắt các bộ phận kim loại bằng ngọn lửa khí, hồ quang điện và các nguồn nhiệt khác để nấu chảy và cắt hoặc để nung chảy và kết dính kim loại.', array['- Hàn các bộ phận kim loại bằng ngọn lửa khí, hồ quang điện, hỗn hợp nhiệt nhôm hay các phương pháp khác;', '- Vận hành máy hàn điện trở;', '- Sử dụng ống thổi để chế tạo và sửa chữa lớp lót chì, đường ống, sàn nhà và các đồ bằng chì khác;', '- Hàn các bộ phận kim loại với nhau;', '- Cắt các miếng kim loại bằng ngọn lửa khí hoặc hồ quang điện;', '- Nối các bộ phận kim loại bằng cách hàn tay;', '- Giám sát quá trình lắp ráp, nung, hàn để tránh bị quá nhiệt, cong vênh, co ngót, biến dạng hoặc giãn mở của vật liệu.', '- Kiểm tra sản phẩm để tìm sai sót và đo các sản phẩm với thước thẳng hoặc mẫu có sẵn để đảm bảo thống nhất với thông số kỹ thuật.']::text[], array['- Thợ làm đồ đồng thau', '- Thợ cắt kim loại bằng ngọn lửa khí', '- Thợ hàn']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1129) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7213', 'Thợ luyện kim loại chế tạo, lắp đặt và sửa chữa các thiết bị và các bộ phận của sản phẩm làm từ kim loại tấm như thép tấm, đồng, thiếc, đồng thau, nhôm, kẽm hoặc sắt mạ kẽm.', array['- Đánh dấu kim loại tấm để cắt và tạo hình;', '- Chế tạo, sửa chữa đồ dùng gia đình, các vật phẩm khác bằng thiếc, đồng và hợp kim nhẹ hoặc đồ và phụ kiện trang trí;', '- Chế tạo và sửa chữa nồi hơi, bể chứa, thùng và các thùng chứa tương tự;', '- Lắp đặt và sửa chữa các bộ phận kim loại tấm của phương tiện và máy bay;', '- Chuyển đổi bản thiết kế thành bản vẽ để được theo dõi trong quá trình xây dựng và lắp ráp các sản phẩm kim loại tấm;', '- Xác định các yêu cầu của dự án bao gồm phạm vi, trình tự lắp ráp, phương pháp và vật liệu cần thiết theo bản thiết kế, bản vẽ và hướng dẫn bằng văn bản hoặc bằng lời nói;', '- Kiểm tra chất lượng sản phẩm và lắp đặt để đảm bảo sự phù hợp với thông số kỹ thuật.']::text[], array['- Thợ rèn nồi hơi', '- Thợ đúc đồ đồng', '- Thợ gò', '- Thợ thiếc', 'Ghi chú:', 'Thợ lắp đặt tấm lợp kim loại được xếp vào mã 7121 - Thợ lợp mái. Thợ lắp đặt cống, máng xối và ống dẫn kim loại được xếp vào mã 7126 - Thợ ống nước. Thợ sản xuất các sản phẩm kim loại tấm để lắp đặt bởi thợ lợp mái và thợ ống nước được xếp vào mã 7213 - Thợ luyện kim loại.']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1144) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7214', 'Thợ chuẩn bị và lắp ráp các cấu kiện kim loại chuẩn bị, lắp ráp và tháo dỡ các cấu kiện kim loại của tòa nhà và các công trình khác.', array['- Đánh dấu khung kim loại khi khoan cắt và tạo dáng chúng để sử dụng trong tòa nhà, tàu thuyền và các công trình khác;', '- Khoan, cắt và tạo hình kết cấu thép trong phân xưởng;', '- Dựng khung thép cho tòa nhà, cầu và các công trình xây dựng khác;', '- Lắp ghép dàn khung và các bộ phận kim loại khác của các kết cấu tàu thuyền;', '- Định hình và lắp ráp các tấm thép kim loại của tàu thuyền đang thi công hoặc sửa chữa;', '- Ghép các cấu trúc kim loại bằng tay, máy hoặc đinh tán khí nén;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác']::text[], array['- Thợ lắp ráp kim loại kết cấu', '- Thợ chuẩn bị kim loại kết cấu', '- Thợ đóng đinh tán']::text[], array['- Thợ vận hành máy sản xuất đinh tán - 7223']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1161) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7215', 'Thợ lắp ráp và thợ nối cáp lắp ráp các thiết bị để di chuyển; định vị thiết bị và các thành phần cấu trúc; lắp đặt, bảo trì cáp, dây kim loại trên các công trường xây dựng, tòa nhà và các công trình khác.', array['- Ước lượng kích cỡ, kiểu dáng và trọng lượng của các vật thể sẽ được di chuyển và quyết định loại thiết bị để di chuyển chúng;', '- Lắp đặt và sửa chữa dây cáp, dây kim loại, ròng rọc và các hệ thống dây và ròng rọc khác;', '- Nối, sửa chữa, lắp ráp các phụ tùng cho dây cáp, ròng rọc và dây kim loại;', '- Lắp ráp và sửa chữa cần trục cho khoan nước, giếng dầu và khí đốt;', '- Nâng và gắn cảnh quan, thiết bị ánh sáng và các thiết bị khác trong rạp hát và trên phim trường;', '- Lắp đặt và bảo trì các tháp truyền thông, cáp treo trên không trung, đường sắt leo núi, thang kéo trượt tuyết và các cơ sở hạ tầng tương tự;', '- Thực hiện các công việc có liên quan;', '- Giám sát các lao động khác.']::text[], array['- Thợ nối cáp', '- Thợ lắp ráp', '- Thợ lắp ráp tàu thuyền', '- Thợ lắp đặt sân khấu', '- Thợ bảo dưỡng tòa tháp']::text[], array['- Thợ vận hành máy nối dây cáp - 8189', '- Thợ vận hành thiết bị cần cẩu, cần trục và liên quan - 8343']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1178) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7221', 'Thợ rèn, thợ quai búa và thợ rèn ép nén kim loại búa và rèn dập thanh, cần, thỏi và tấm bằng sắt, thép và kim loại khác; kéo sợi thép để chế tạo, sửa chữa các loại công cụ, vật dụng kim loại, thiết bị, công cụ sản xuất nông nghiệp và các dụng cụ liên quan.', array['- Nung kim loại trong lò rèn; sản xuất, sửa chữa các vật dụng bằng cách kéo, uốn, cắt, rèn kim loại trên đe, đục lỗ, cắt, hàn, làm cứng hoặc ủ;', '- Định hình kim loại nung nóng thành vật rèn trên búa điện được trang bị khuôn mở;', '- Vận hành búa máy lò rèn để rèn các vật dụng kim loại;', '- Vận hành máy ép điện được trang bị khuôn dập để rèn các vật dụng kim loại;', '- Rút sợi kim loại;', '- Xem đơn đặt hàng công việc hoặc bản thiết kế để xác định dung sai và trình tự hoạt động được chỉ định để thiết lập máy;', '- Đo lường và kiểm tra các bộ phận của máy để đảm bảo sự phù hợp với thông số kỹ thuật của sản phẩm.']::text[], array['- Thợ rèn', '- Thợ búa máy', '- Thợ rèn dập', '- Thợ quai búa']::text[], array['- Thợ vận hành máy đúc khuôn - 7223', '- Thợ vận hành máy công cụ - 7223']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1201) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7222', 'Thợ chế tạo dụng cụ và thợ có liên quan chế tạo, sửa chữa các dụng cụ chuyên dụng, súng thể thao, khóa, khuôn, mô hình, linh kiện máy móc và các vật dụng kim loại khác sử dụng dụng cụ cầm tay hoặc máy để gia công kim loại cho dung sai tốt.', array['- Đọc và giải thích các bản vẽ và thông số kỹ thuật của các dụng cụ, khuôn, nguyên mẫu hoặc mô hình;', '- Chuẩn bị khuôn mẫu và bản phác thảo, xác định quy trình sản xuất.', '- Tính toán kích thước, hình dạng và dung sai của sản phẩm dựa trên thông số kỹ thuật;', '- Định vị, bảo đảm và đo lường kim loại hoặc vật đúc để gia công.', '- Thiết lập, vận hành và bảo trì các máy công cụ thông thường và máy điều khiển số để cắt, tiện, phay, nghiền, khoan, mài hoặc định hình phôi theo kích thước quy định và hoàn thiện;', '- Lắp ráp các bộ phận để chế tạo và sửa chữa đồ gá lắp, đồ đạc và đồng hồ đo;', '- Sửa chữa và cải tiến súng thể thao và các loại vũ khí nhỏ khác;', '- Chế tạo, lắp ráp, sửa chữa và cài đặt khóa và các bộ phận khóa;', '- Chế tạo và sửa chữa các mẫu kim loại để chuẩn bị khuôn đúc;', '- Vẽ các đường và điểm tham chiếu về trữ lượng kim loại để hướng dẫn các lao động khác cắt, phay, nghiền, mài hoặc tạo hình kim loại;', '- Kiểm tra kích thước, sự sắp xếp và độ hở của các thành phẩm đảm bảo phù hợp với thông số kỹ thuật; sử dụng dụng cụ đo chính xác và kiểm tra thành phẩm để vận hành chuẩn xác.']::text[], array['- Thợ tạo khuôn', '- Thợ chế tạo súng', '- Thợ sản xuất khuôn', '- Thợ khóa', '- Thợ tạo mô hình', '- Thợ làm dụng cụ']::text[], array['- Thợ vận hành máy sản xuất dụng cụ - 7223']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1219) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7223', 'Thợ lắp ráp và vận hành máy công cụ kim loại thiết lập và vận hành các công cụ máy khác nhau làm việc với dung sai tốt.', array['- Thiết lập một hay nhiều loại máy công cụ để sản xuất các sản phẩm kim loại theo nhiều tiêu chuẩn;', '- Vận hành và giám sát máy gia công kim loại như máy tiện, phay, bào, khoan, khoan đào, mài gồm cả máy gia công kim loại điều khiển bằng số đa năng;', '- Thực hiện nhiệm vụ tương tự khi gia công nhựa hay vật liệu thay thế kim loại khác;', '- Quan sát các hoạt động của máy để phát hiện các lỗi hoặc trục trặc từ đó điều chỉnh máy khi cần thiết;', '- Kiểm tra các phần công việc để tìm lỗi và đo các phần công việc để xác định độ chính xác về hoạt động của máy, sử dụng các quy tắc, mẫu hoặc các dụng cụ đo khác;', '- Thay đổi phụ tùng máy móc bị mòn như dụng cụ cắt và chổi lông; sử dụng dụng cụ cầm tay.']::text[], array['- Thợ vận hành máy khoan đào', '- Thợ vận hành máy đúc khuôn', '- Thợ vận hành máy công cụ', '- Thợ lắp đặt máy công cụ', '- Thợ vận hành, lắp đặt máy công cụ', '- Thợ quay kim loại', '- Thợ vận hành máy sản xuất đinh tán', '- Thợ vận hành máy sản xuất dụng cụ']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1242) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7224', 'Thợ đánh bóng, thợ mài kim loại và dụng cụ kim loại đánh bóng, mài bề mặt kim loại và các dụng cụ.', array['- Vận hành máy đánh bóng cố định hay di động;', '- Mài dao và dụng cụ cắt bằng máy mài hoặc máy mài vận hành cơ học;', '- Sửa chữa, điều chỉnh và mài lưỡi cưa và răng kim loại trong máy dệt;', '- Chỉnh bánh răng mài theo thông số kỹ thuật;', '- Giám sát hoạt động của máy để quyết định việc điều chỉnh có cần thiết không và dừng hoạt động của máy khi có sự cố;', '- Kiểm tra và đo các phần công việc để đảm bảo các bề mặt và kích thước đáp ứng các thông số kỹ thuật;', '- Chọn và lắp bánh răng mài vào máy theo thông số kỹ thuật; sử dụng dụng cụ cầm tay và áp dụng kiến thức về vật liệu mài mòn và quy trình mài.']::text[], array['- Thợ mài dao', '- Thợ hoàn thiện kim loại', '- Thợ đánh bóng kim loại', '- Thợ mài dụng cụ']::text[], array['- Thợ vận hành máy hoàn thiện kim loại - 8122', '- Thợ vận hành máy đánh bóng kim loại - 8122']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1260) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7231', 'Thợ cơ khí và sửa chữa xe có động cơ lắp ráp, bảo dưỡng, sửa chữa động cơ và thiết bị cơ khí và các thiết bị liên quan của xe khách, xe tải, xe máy và xe cơ giới khác.', array['- Phát hiện và chẩn đoán lỗi trong động cơ và các bộ phận;', '- Lắp ráp, kiểm tra, thử nghiệm và bảo dưỡng động cơ xe cơ giới;', '- Thay thế các bộ phận động cơ hoặc động cơ hoàn chỉnh;', '- Lắp ráp, kiểm tra, điều chỉnh, tháo dỡ và thay thế các bộ phận bị hỏng của xe cơ giới;', '- Lắp ráp hoặc điều chỉnh động cơ và phanh; điều chỉnh tay lái hoặc các bộ phận khác của xe cơ giới;', '- Thực hiện dịch vụ bảo dưỡng định kỳ như thay dầu, bôi trơn, điều chỉnh động cơ để xe chạy êm hơn và tuân thủ quy chuẩn ô nhiễm;', '- Lắp ráp lại động cơ và các bộ phận của xe sau khi sửa chữa.']::text[], array['- Thợ máy phục vụ hệ thống phanh ô tô', '- Thợ tra dầu diesel (giao thông đường bộ)', '- Thợ lắp động cơ (xe cơ giới)', '- Thợ sửa xe', '- Thợ sửa xe gắn máy', '- Thợ sửa xe môtô', '- Thợ cơ khí xe kéo cơ giới', '- Thợ máy bảo quản hệ thống động cơ và nhiên liệu của xe cơ giới', '- Thợ cơ khí xe cơ giới', '- Thợ máy dịch vụ cơ điện tử xe cơ giới', '- Thợ sửa chữa xe cơ giới', '- Thợ máy bảo dưỡng xe cơ giới', '- Thợ cơ khí động cơ nhỏ']::text[], array['- Thợ sửa xe đạp - 7234', '- Thợ điện ô tô - 7412', '- Thợ cơ điện - 7412', '- Thợ lắp ráp động cơ xe cơ giới - 8201']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1281) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7232', 'Thợ cơ khí và sửa chữa động cơ máy bay sửa chữa, đại tu động cơ và lắp ráp máy bay như khung máy bay, hệ thống thủy lực, khí nén.', array['- Lắp ráp, kiểm tra, thử nghiệm và bảo dưỡng động cơ máy bay;', '- Thay thế một phần động cơ hay động cơ hoàn chỉnh;', '- Kiểm tra máy bay và các bộ phận của máy bay bao gồm cả bộ phận tiếp đất, hệ thống thủy lực, thiết bị khử nhiễu để phát hiện sự hao mòn, vết nứt, vỡ, rò rỉ hoặc các vấn đề khác;', '- Bảo trì, sửa chữa, đại tu, điều chỉnh và thử nghiệm kết cấu máy bay, cơ khí và hệ thống thủy lực máy bay;', '- Đọc và giải thích hướng dẫn sử dụng, bản tin dịch vụ và các thông số kỹ thuật khác để xác định tính khả thi và phương pháp sửa chữa hoặc thay thế các bộ phận hư hỏng, trục trặc;', '- Bảo trì, sửa chữa và tái dựng kết cấu máy bay, bộ phận chức năng và các bộ phận như cánh và thân máy bay, hệ thống truyền động, hệ thống thủy lực, hệ thống khí oxi, nhiên liệu, điện, gioăng và phớt;', '- Kiểm tra công việc đã hoàn thành để xác nhận việc bảo trì đảm bảo tiêu chuẩn và máy bay sẵn sàng hoạt động;', '- Duy trì nhật ký sửa chữa, ghi lại tất cả các kỳ bảo dưỡng máy bay theo hướng phòng ngừa hay khắc phục;', '- Lắp đặt và thử nghiệm các linh kiện điện, điện tử trên máy bay;', '- Kết nối các bộ phận với các tổ hợp như hệ thống vô tuyến, dụng cụ, nam châm, bộ biến tần và hệ thống tiếp nhiên liệu trên máy bay.']::text[], array['- Thợ máy trên máy bay', '- Thợ lắp ráp động cơ máy bay', '- Thợ bảo trì máy bay (khung máy bay)', '- Thợ bảo trì máy bay (động cơ)', '- Giám sát viên bảo trì máy bay', '- Thợ sửa chữa máy bay', '- Thợ phục chế máy bay', '- Kỹ thuật viên dịch vụ máy bay', '- Thợ cơ khí máy bay và nhà máy điện', '- Thợ cơ khí khung máy bay', '- Kỹ thuật viên bảo trì hàng không', '- Thợ cơ khí trực thăng', '- Thợ cơ khí phản lực', '- Thợ cơ chế hệ thống thủy lực (máy bay)', '- Thợ cơ khí điện (máy bay)', '- Thợ cơ khí thành phần động cơ tên lửa']::text[], array['- Kỹ sư hàng không - 2144', '- Thợ bảo trì máy bay (hệ thống điện tử hàng không) - 7421', '- Kỹ thuật viên điện tử hàng không - 7421', '- Thợ lắp ráp động cơ máy bay - 8201']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1310) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7233', 'Thợ cơ khí và sửa chữa máy móc nông nghiệp và công nghiệp lắp đặt, kiểm tra, bảo trì và sửa chữa động cơ, máy móc nông nghiệp, công nghiệp và thiết bị cơ khí trừ xe cơ giới, máy bay và động cơ điện.', array['- Lắp đặt, kiểm tra, bảo dưỡng và sửa chữa động cơ, máy móc và thiết bị cơ khí;', '- Tra dầu, bôi trơn động cơ và máy móc cố định;', '- Kiểm tra và thử nghiệm máy móc, thiết bị cơ khí mới cho phù hợp với tiêu chuẩn và thông số kỹ thuật;', '- Tháo rời máy móc, thiết bị để gỡ bỏ các bộ phận và tiến hành sửa chữa;', '- Kiểm tra các bộ phận bị hỏng như vỡ và mòn quá mức;', '- Vận hành máy móc và thiết bị mới được sửa chữa để kiểm tra sự phù hợp của sửa chữa;', '- Lưu lại công đoạn sửa chữa và bảo dưỡng đã thực hiện.']::text[], array['- Thợ cơ khí máy móc xây dựng', '- Thợ sửa chữa máy móc xây dựng', '- Thợ sửa chữa máy móc nông nghiệp', '- Thợ lắp đặt máy móc khai thác mỏ', '- Thợ sửa chữa máy móc khai thác mỏ', '- Thợ lắp ráp động cơ cố định', '- Thợ sửa chữa động cơ cố định', '- Thợ lắp ráp động cơ tàu hỏa', '- Thợ sửa chữa động cơ tàu hỏa']::text[], array['- Thợ cơ khí thiết bị điều hòa không khí - 7127', '- Thợ cơ điện - 7412', '- Thợ lắp ráp máy cơ khí - 8201']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1345) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7234', 'Thợ sửa chữa xe đạp và thợ có liên quan lắp đặt, bảo dưỡng và sửa chữa các thiết bị cơ khí và liên quan của xe đạp, xe kéo, xe nôi, xe lăn và các phương tiện thô sơ khác.', array['- Kiểm tra, bảo dưỡng và sửa chữa xe đạp và các phương tiện giao thông thô sơ khác;', '- Lau chùi, bôi trơn vòng bi và các bộ phận chuyển động khác;', '- Thay thế và sửa chữa các bộ phận và phụ kiện như phanh, bánh răng, xích, bánh xe và ghi-đông;', '- Thay lốp và điều chỉnh áp suất không khí;', '- Phun sơn khung xe;', '- Lắp ráp xe đạp, xe lăn mới và các thiết bi thô sơ tương tự.']::text[], array['- Thợ sửa chữa xe đạp', '- Thợ sửa chữa xe đẩy trẻ con', '- Thợ sửa chữa xe lăn']::text[], array['- Thợ sửa xe gắn máy - 7231', '- Thợ cơ khí xe kéo cơ giới - 7231']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1369) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7311', 'Thợ sản xuất và sửa chữa dụng cụ chính xác chế tạo, điều chỉnh, sửa chữa, bảo dưỡng, lắp đặt đồng hồ và đồng hồ cơ, các thiết bị, dụng cụ chính xác, khí tượng, quang học và các thiết bị, dụng cụ chính xác khác và để chúng hoạt động chính xác.', array['- Sửa chữa, làm sạch và điều chỉnh cơ chế của các dụng cụ đo thời gian như đồng hồ treo tường và đồng hồ để bàn;', '- Điều chỉnh các máy đo thời gian, sử dụng compa, máy ghi tốc độ thời gian và kẹp nhíp;', '- Làm sạch, rửa và làm khô các bộ phận của đồng hồ; sử dụng các dung dịch hoặc máy làm sạch đồng hồ;', '- Kiểm tra độ chính xác và hiệu suất của đồng hồ, sử dụng dụng cụ đo và các dụng cụ điện tử khác;', '- Kiểm tra độ chính xác của đồng hồ đo, sử dụng chỉ báo hoặc dụng cụ ghi để xác định vị trí các bộ phận bị lỗi và điều chỉnh phù hợp với tiêu chuẩn;', '- Hiệu chuẩn dụng cụ hoặc cân, sử dụng dụng cụ cầm tay, máy tính hoặc thiết bị điện tử;', '- Xem xét, kiểm tra các bộ phận cấu thành, kết nối và cơ chế truyền động để phát hiện lỗi;', '- Lắp ráp các dụng cụ và các thiết bị như dụng cụ đo khí áp, van điều khiển, con quay hồi chuyển, ẩm kế, tốc độ kế, máy đo tốc độ gốc và máy điều chỉnh nhiệt;', '- Điều chỉnh và sửa chữa các cột ăng-ten, cột buồm, đèn giải phóng mặt bằng, bảng điều khiển, cáp điều khiển, hệ thống dây điện, các thiết bị điện tử và cơ khí khác;', '- Sửa chữa và lắp các dụng cụ quang học như kính hiển vi, kính thiên văn, máy kinh vĩ và kính lục phân;', '- Kiểm tra các đơn vị lắp đặt có phù hợp với các thông số kỹ thuật; đảm bảo hiệu suất và độ nhạy theo quy định bằng các thử nghiệm tiêu chuẩn.']::text[], array['- Thợ sản xuất dụng cụ khí tượng', '- Thợ sửa chữa thiết bị chụp ảnh', '- Thợ sản xuất dụng cụ phẫu thuật', '- Thợ sửa đồng hồ']::text[], array['- Nhà sản xuất dụng cụ chỉnh hình - 3214', '- Thợ khóa - 7222', '- Thợ vận hành máy công cụ - 7223', '- Thợ lắp ráp đồng hồ - 8202']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1392) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7312', 'Thợ sản xuất và điều chỉnh nhạc cụ chế tạo, lắp ráp, sửa chữa, điều chỉnh, khôi phục nhạc cụ; điều chỉnh để chúng đạt đến cao độ cần thiết bằng tay hoặc dụng cụ điện. Họ thường chuyên về một loại nhạc cụ như nhạc cụ có dây, nhạc cụ bằng đồng, đàn piano hoặc nhạc cụ gõ.', array['- Chế tạo và lắp ráp nhạc cụ và các bộ phận nhạc cụ bằng gỗ, ebonit, kim loại, da và các vật liệu khác;', '- Sửa chữa hoặc thay thế các bộ phận và linh kiện của nhạc cụ như dây đàn, cầu, nỉ và phím, sử dụng dụng cụ cầm tay và điện;', '- Chơi và kiểm tra các nhạc cụ để đánh giá chất lượng âm thanh và để xác định các lỗi của chúng;', '- Điều chỉnh độ căng của dây để đạt được âm sắc hoặc cao độ của nhạc cụ có dây;', '- Điều chỉnh môi, lưỡi gà hoặc lỗ của ống nhạc bằng việc sử dụng dụng cụ cầm tay để điều chỉnh luồng không khí và độ to của âm thanh;', '- Điều chỉnh và sửa chữa các bộ phận ống nhạc của đàn ống bằng việc điều chỉnh cao độ của đàn ống nhạc và điều chỉnh độ cao thấp của các ống nhạc khác với sự liên quan tới độ cao thấp của các ống nhạc đã được điều chỉnh;', '- Làm mặt trống mới cho các nhạc cụ gõ như trống;', '- Lên dây đàn ăc-cooc bằng cách nghe so sánh độ cao thấp của lưỡi gà với các lưỡi gà chính và các lưỡi gà giữa để đạt được độ cao thấp chuẩn;', '- Sắp cho thẳng hàng các miếng đệm lót và các khóa của dây đàn trên các nhạc khí có lưỡi gà hoặc các nhạc khí hơi;', '- Điều chỉnh các nhạc cụ gõ theo cao độ yêu cầu bằng việc kéo căng hoặc nới lỏng các dây giữ các miếng da cố định ở trên đỉnh hoặc ở cả hai đầu của nhạc cụ;', '- Lắp ráp và đặt các ống nhạc mới hoặc đàn piano trong các tòa nhà.']::text[], array['- Thợ sửa kèn đồng', '- Thợ chỉnh đàn piano', '- Thợ sản xuất nhạc cụ có dây', '- Thợ sản xuất nhạc cụ bằng gỗ']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1416) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7313', 'Thợ kim hoàn thiết kế, chế tác, điều chỉnh, sửa chữa hoặc thẩm định đồ trang sức, vật phẩm nghi lễ hoặc tôn giáo, vàng, bạc, kim loại quý hoặc đá quý khác. Họ cắt, giũa, đánh bóng và tạo hình đá quý và đá bán quý bao gồm đá, ngọc, kim cương; khắc, trổ, chạm các mẫu vẽ trên đồ kim hoàn và các kim loại quý khác. Họ cắt và đánh bóng kim cương cho mục đích công nghiệp.', array['- Đúc đồ trang sức và các vật phẩm kim loại màu khác bằng tay;', '- Tạo ra các mẫu đồ kim hoàn mới và thay đổi các mẫu hiện có, sử dụng máy tính khi cần thiết;', '- Thiết kế, cắt các mẫu trong khuôn hoặc bằng các vật liệu khác được sử dụng như các mẫu trong việc chế tác các sản phẩm kim loại và đồ kim hoàn;', '- Thay đổi giá treo đồ trang sức hiện có để định vị lại đồ trang sức hoặc để điều chỉnh giá treo;', '- Sửa chữa, phục hồi lại hình dáng các đồ kim hoàn cũ hoặc đồ kim loại quý theo thiết kế hoặc theo hướng dẫn;', '- Chế tác các đồ kim hoàn như nhẫn, dây chuyền, vòng đeo, trâm cài từ các vật liệu như vàng, bạc, bạch kim, đá quý hoặc đá bán quý;', '- Kiểm tra bề mặt đá quý và cấu trúc bên trong bằng việc sử dụng kính phân cực, máy đo khúc xạ, kính hiển vi và các thiết bị quang học khác để phân biệt giữa các loại đá, để xác định các mẫu vật hiếm hoặc để phát hiện ra các vết rạn nứt, các khiếm khuyết hoặc các nét riêng biệt ảnh hưởng đến giá trị của đá quý;', '- Cắt và đánh bóng đá, ngọc và tạo chúng thành các đồ kim hoàn;', '- Khắc, trổ, chạm hoặc dập nổi chữ, các mẫu vẽ hoặc các đường nét trang trí lên đồ trang sức và đồ kim loại quý;', '- Mài, khoan và hoàn thiện các vòng bi ngọc để sử dụng trong các dụng cụ chính xác như la bàn hay đồng hồ bấm giờ;', '- Kiểm tra các sản phẩm lắp ráp và thành phẩm để bảo đảm sự phù hợp với thông số kỹ thuật bằng việc sử dụng kính lúp hay các dụng cụ đo chính xác.']::text[], array['- Thợ tráng men (trang sức)', '- Thợ làm đá quý', '- Thợ vàng', '- Thợ làm đồ trang sức', '- Thợ bạc']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1435) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7314', 'Thợ gốm và thợ có liên quan chuẩn bị đồ gốm, sứ, thiết bị vệ sinh, gạch, ngói và mài bằng tay hoặc bằng máy.', array['- Chế tạo đồ gốm, sứ;', '- Chế tạo khuôn bằng đất sét hoặc thạch cao;', '- Đọc bản vẽ kỹ thuật để biết được yêu cầu của khách hàng;', '- Tạo các vật phẩm trên bánh xe thợ gốm bằng cách ấn ngón tay cái vào chính giữa đất sét quay để tạo thành chỗ lõm và ấn vào bên trong và bên ngoài khối đất sét mới nổi bằng tay và các ngón tay, dần dần nâng và tạo hình đất sét thành các hình dạng và kích thước mong muốn;', '- Điều chỉnh tốc độ của bánh quay đất sét theo cảm giác khi các mảnh đất sét đó to ra và thành trở nên mỏng hơn;', '- Vận hành thiết bị làm đồ gốm như bát, chén, đĩa;', '- Điều chỉnh và kiểm soát pha trộn, ép, cắt và cho đất sét trong hoặc trên các khuôn theo quy định;', '- Làm phẳng bề mặt của các mẫu đã hoàn thiện bằng việc sử dụng chất tẩy cao su và các miếng bọt biển ướt;', '- Tạo các bánh xe mài mòn bằng việc đúc và ép hỗn hợp mài mòn bằng tay hoặc bằng máy;', '- Kiểm tra sản phẩm đã được hoàn thiện để tìm lỗi và xác minh sự chính xác của hình dạng và kích cỡ của các đồ vật bằng việc sử dụng thước kẹp và các khuôn mẫu;', '- Chuẩn bị các khâu cho việc bán hàng và triển lãm; duy trì mối quan hệ với các mạng lưới bán lẻ, xưởng gốm, hệ thống mỹ thuật và tài nguyên tạo thuận lợi cho việc bán hàng hoặc triển lãm.']::text[], array['- Thợ chế tạo bánh xe mài', '- Thợ đúc khuôn gạch ngói', '- Thợ làm gốm', '- Thợ đúc đồ gốm, sứ', '- Thợ làm khuôn đồ gốm, sứ']::text[], array['- Nghệ nhân gốm - 2651', '- Thợ vận hành lò nung (gạch ngói) - 8181', '- Thợ vận hành lò nung (gốm và sứ) - 8181']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1455) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7315', 'Thợ sản xuất, thợ cắt, thợ mài và thợ hoàn thiện đồ thủy tinh thổi, đúc, ép, cắt, mài và đánh bóng thủy tinh; nấu chảy thủy tinh theo các khuôn mẫu để tạo ra hình dạng khác nhau.', array['- Nung thủy tinh đến giai đoạn dẻo bằng cách sử dụng ngọn lửa khí hoặc lò nung; quay thủy tinh để làm nóng đồng đều;', '- Thổi và uốn ống thủy tinh thành các hình dạng cụ thể để tạo thành các bộ dụng cụ có tính khoa học như bình thót cổ dùng trong phòng thí nghiệm, bình cổ cong, ống hút;', '- Mài và đánh bóng các đồ vật hoặc các bộ phận thủy tinh để sửa chữa các khiếm khuyết hoặc để chuẩn bị bề mặt để hoàn thiện; làm mịn, đánh bóng các cạnh thô bằng việc sử dụng máy mài hoặc bánh xe đánh bóng;', '- Kiểm tra kho thủy tinh và thành phẩm để đánh dấu và loại bỏ các mặt hàng có khiếm khuyết như các vết đốm, bẩn, sẹo, thủng, sứt mẻ, trầy xước hoặc các mẫu hay các sản phẩm hoàn thiện không được chấp nhận;', '- Đọc đơn đặt hàng để xác định kích thước, vị trí cắt và số lượng để cắt;', '- Quan sát đồng hồ đo, dữ liệu in từ máy tính, màn hình video để kiểm tra việc xử lý được chỉ định và thực hiện các điều chỉnh khi cần;', '- Định vị các mẫu hoặc hình vẽ trên thủy tinh; đo kích thước và đánh dấu các đường cắt bằng việc sử dụng dụng cụ cắt thủy tinh; cắt thủy tinh theo các đường nét được đánh dấu hoặc theo khuôn mẫu;', '- Thiết lập, vận hành và điều chỉnh các thiết bị cắt kính đã được thiết lập trong máy tính hoặc người máy;', '- Kiểm tra, cân và đo sản phẩm để xác minh sự phù hợp với thông số kỹ thuật bằng việc sử dụng các dụng cụ như dụng cụ đo micromet, thước kẹp, kính lúp và các thước đo khác;', '- Điều chỉnh nhiệt độ lò theo từng loại thủy tinh được xử lý;', '- Chuyển mẫu cho các bộ phận kính màu riêng lẻ từ bản vẽ đầy đủ sang giấy mẫu sử dụng bút trâm để vẽ can lại bản vẽ;', '- Phun dung dịch bạc lên thủy tinh để tạo thành bề mặt gương bằng việc sử dụng súng phun;', '- Cắt và mài thủy tinh quang học và thủy tinh khác theo kích thước và trọng lượng quy định để đúc vào phôi ống kính và được sử dụng làm tinh thể đồng hồ.']::text[], array['- Thợ thổi thủy tinh', '- Thợ cắt thủy tinh', '- Thợ hoàn thiện thủy tinh', '- Thợ mài thủy tinh']::text[], array['- Thợ vận hành lò sản xuất thủy tinh - 8181']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1479) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7316', 'Thợ vẽ biển quảng cáo, thợ trang trí, thợ khắc và thợ khắc axit trang trí các sản phẩm được làm từ gỗ, kim loại, vải dệt, thủy tinh, gốm sứ và các nguyên vật liệu khác. Họ lên kế hoạch, bố trí và vẽ các chữ cái, hình vẽ, chữ viết lồng nhau và thiết kế để làm bảng hiệu; chạm khắc và khắc axit các mẫu trang trí, hoa văn trên thủy tinh và các đồ khác.', array['- Vẽ trang trí lên các đồ vật như đồ gốm, thủy tinh, hộp đựng thuốc lá điếu, chụp đèn, chao đèn;', '- Chuyển các thiết kế trang trí từ giấy sang các vật phẩm;', '- Kết hợp và phát triển các yếu tố thị giác như đường kẻ, không gian, khối, mầu sắc và phối cảnh để tạo ra hiệu ứng mong muốn như minh họa các ý tưởng, cảm xúc hoặc tâm trạng;', '- Bố trí và vẽ các chữ cái, hình, chữ lồng nhau và thiết kế để làm bảng hiệu;', '- Phác thảo hoặc tìm các thiết kế viết chữ, hoa văn lên các tác phẩm để chuẩn bị các mẫu và giấy nến;', '- Thiết kế các mẫu hoặc chữ để vẽ lên bảng hiệu, đồ thủy tinh, đồ gốm hoặc tấm kẽm;', '- Sử dụng phần mềm và thiết bị định tuyến để tạo ra hình ảnh ba chiều cho ứng dụng lên các biển hiệu lớn cũng như các hình được khắc và dát;', '- Thiết kế và sản xuất các chữ cắt phẳng thông thường hoặc các chữ được phủ bóng bằng vinyl hoặc các chữ được cắt sẵn để ghép;', '- Viết, vẽ hoặc in các dấu hiệu được sử dụng để hiển thị hoặc cho các mục đích khác;', '- Cắt các chữ cái và ký hiệu để hiển thị từ bảng hoặc bìa cứng bằng tay hoặc bằng máy hoặc lưỡi cưa chạy bằng điện;', '- Kiểm tra các bản phác thảo, sơ đồ, mẫu, bản thiết kế hoặc hình ảnh để quyết định việc thiết kế như khắc, cắt hoặc khắc, trổ, chạm lên các mẫu vật;', '- Đo và tính toán kích thước của chữ, thiết kế hoặc các mẫu sẽ được khắc;', '- Khắc và in các mẫu, các thiết kế, nhãn hiệu, hình hoặc chữ lên bề mặt phẳng hoặc cong của các đồ kim loại, thủy tinh, nhựa hoặc gốm;', '- Khắc axit các mẫu trang trí lên các sản phẩm thủy tinh.']::text[], array['- Thợ trang trí', '- Thợ tráng men thủy tinh', '- Thợ khắc thủy tinh', '- Thợ khắc axit', '- Thợ vẽ biển quảng cáo']::text[], array['- Thợ sơn công trình - 7131', '- Thợ sơn hàng công nghiệp chế tạo - 7132', '- Thợ sơn xe - 7132', '- Thợ vận hành máy sơn gốm - 8181', '- Thợ vận hành máy sơn thủy tinh - 8181']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1502) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7317', 'Thợ thủ công sản xuất đồ gỗ, rổ rá và các nguyên liệu có liên quan áp dụng các kỹ thuật truyền thống để chuẩn bị gỗ, rơm, mây, song, sậy, đất sét, vỏ sò và các nguyên vật liệu khác; khắc, đúc, lắp ráp, dệt hoặc sơn và trang trí các vật phẩm khác nhau sử dụng cho cá nhân, gia đình hoặc cho mục đích trang trí. Thợ đan rổ rá, làm bàn chải và các thợ có liên quan lựa chọn và chuẩn bị nguyên vật liệu như ni lông, sợi, lông, dây để làm đồ nội thất đan lát, bàn chải, chổi.', array['- Chuẩn bị gỗ, rơm, mây, sậy, vỏ sò hoặc các nguyên vật liệu tương tự;', '- Khắc, chạm, trổ các kiểu mẫu hoa và nghệ thuật trên bề mặt gỗ để trang trí;', '- Vẽ các kiểu mẫu trang trí lên thủy tinh và gốm sứ;', '- Chạm khắc, lắp ráp, dệt, sơn và trang trí các đồ vật khác nhau cho cá nhân hoặc hộ gia đình như bát đĩa, thớt, khay, lọ, bình, giỏ, mũ rơm, thảm rơm và các đồ vật tương tự;', '- Chạm khắc, lắp ráp, dệt, vẽ các vật phẩm trang trí khác nhau như tượng và tác phẩm điêu khắc, quân cờ, đồ trang sức và các đồ vật tương tự;', '- Chế tạo các đồ nội thất đan lát từ các loại vỏ và cây mây mềm, sậy, cói, cành liễu và các nguyên vật liệu tương tự;', '- Làm các loại rổ khác nhau bằng việc bện, kết các cây liễu, cây mây, sậy, cói và các nguyên vật liệu tương tự;', '- Đan các thanh tạo thành các cạnh xung quanh và đáy dưới để làm khung;', '- Lựa chọn và chuẩn bị các vật liệu làm bàn chải như lông, ni lông, sợi, dây và đặt chúng vào đế bàn chải;', '- Lựa chọn và chuẩn bị các vật liệu làm chổi.']::text[], array['- Thợ đan giỏ', '- Thợ làm bàn chải', '- Thợ dệt thủ công', '- Thợ làm đồ nội thất đan lát', '- Thợ thủ công mỹ nghệ']::text[], array['- Thợ vận hành máy (sản phẩm gỗ) - 7523']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1531) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7318', 'Thợ thủ công dệt vải, da và các nguyên liệu có liên quan áp dụng kỹ thuật và hoa văn truyền thống để sản xuất vải dệt, đan, thêu và các sản phẩm may mặc khác cho gia đình cùng với giày dép, túi xách, thắt lưng và các phụ kiện truyền thống khác.', array['- Kéo sợi và nhuộm bằng thuốc nhuộm tự nhiên;', '- Sản xuất ren, dệt, đan hoặc thêu các sản phẩm may mặc và sản phẩm khác để sử dụng trong gia đình;', '- Chuẩn bị và nhuộm da bằng thuốc nhuộm tự nhiên để làm giày dép, túi xách, thắt lưng và các phụ kiện truyền thống khác;', '- Kéo sợi và cuộn sợi bằng tay;', '- Dệt sợi bằng tay;', '- Dệt vải trơn hoặc hình, tấm thảm, ren hoặc các loại vải khác trên khung dệt tay;', '- Làm thảm bằng kỹ thuật thắt nút;', '- Đan hàng may mặc và các mặt hàng khác bằng tay hoặc trên máy vận hành bằng tay;', '- Đan lưới bằng tay;', '- Phân loại sợi dệt tự nhiên;', '- Giặt sợi len;', '- Làm sạch và làm xơ sợi dệt;', '- Kết hợp các sợi thành búi, các mảnh thành vòng.']::text[], array['- Thợ làm thảm thủ công', '- Thợ dệt thảm', '- Thợ dệt vải', '- Thợ đan', '- Thợ làm đồ da thủ công', '- Thợ dệt thoi', '- Thợ dệt sợi', '- Thợ kéo sợi', '- Thợ cuộn sợi', '- Thợ dệt thủ công', '- Thợ xe chỉ và sợi']::text[], array['- Thợ vận hành máy chải sợi - 8151', '- Thợ vận hành máy đan - 8152', '- Thợ vận hành máy dệt - 8152']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1552) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7319', 'Thợ thủ công khác chưa được phân vào đâu bao gồm các thợ thủ công truyền thống làm kim loại quý và đá.', '{}'::text[], array['- Thợ làm nến (thủ công)', '- Thợ sản xuất đồ chơi kim loại', '- Thợ làm đồ đá thủ công']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1584) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7321', 'Thợ thực hiện công đoạn trước in gồm nhập và xử lý chữ văn bản phù hợp với kỹ thuật in, nhập và xử lý ảnh đồ họa phù hợp với kỹ thuật in, tạo ra dữ liệu phù hợp với kỹ thuật in để ghi phim, ghi bản, tạo khuôn in và dùng dữ liệu này trong in kỹ thuật số (digital printing).', array['- Nhập và xử lý chữ trên máy tính;', '- Nhập và xử lý ảnh trên máy tính, máy quét ảnh, máy ảnh;', '- Thiết kế, dàn trang và bình bản cho quá trình ghi phim, ghi bản, in kỹ thuật số;', '- Thiết lập và vận hành các thiết bị ghi phim, máy phơi phim, máy hiện bản và các máy phụ trợ khác trong các kỹ thuật in tương tự;', '- Thiết lập và vận hành các thiết bị ghi bản, máy hiện bản và các thiết bị phụ trợ khác trong các kỹ thuật in tương tự;']::text[], array['- Thợ sắp chữ - dàn trang', '- Thợ quét và xử lý ảnh', '- Thợ chế bản gồm bình bản, ghi bản, hiện bản cho công nghệ in offset', '- Thợ khắc hóa học cho khuôn in ống đồng', '- Thợ vận hành máy khắc cho khuôn in ống đồng', '- Thợ chế khuôn in cao (in flexo)', '- Thợ chế khuôn in lưới']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1593) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7322', 'Thợ in vận hành các loại máy in của công nghệ in offset, in lõm, in cao, in lưới và in kỹ thuật số.', array['- Vận hành các bộ phận chức năng của thiết bị in gồm vận hành hệ thống cấp vật liệu, vận hành hệ thống in, vận hành hệ thống thu nhận sản phẩm in, các hệ thống phụ trợ khác như hệ thống hơi, hệ thống điện, hệ thống làm mát,...', '- Kiểm soát các vật liệu cho quá trình in gồm: Vật liệu nền (giấy, màng mỏng,...), mực phù hợp với các kỹ thuật in ở trên, và các vật liệu phụ phù hợp với các kỹ thuật in ở trên;', '- Thiết lập các thông số công nghệ cho quá trình in phù hợp với các kỹ thuật in ở trên để tạo ra sản phẩm in đạt tiêu chuẩn chất lượng;', '- Bảo trì và bảo dưỡng các bộ phận chức năng của thiết bị cho các kỹ thuật in ở trên.']::text[], array['- Thợ vận hành máy in offset dạng tờ rời (sheetfed offset)', '- Thợ vận hành máy in offset dạng cuộn (web offset)', '- Thợ vận hành máy in lõm (in ống đồng)', '- Thợ vận hành máy in cao (in flexo)', '- Thợ vận hành máy in lưới', '- Thợ vận hành máy in kỹ thuật số', '- Thợ pha màu mực']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1609) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7323', 'Thợ hoàn thiện sản phẩm in thực hiện thủ công hoặc vận hành các thiết bị hoàn thiện xuất bản phẩm, bao bì.', array['- Thợ thủ công thực hiện một vài công đoạn trong quá trình hoàn thiện xuất bản phẩm, bao bì;', '- Vận hành các bộ phận chức năng của thiết bị hoàn thiện và trang trí xuất bản phẩm, bao bì gồm vận hành hệ thống cấp vật liệu, vận hành công đoạn hoàn thiện chính, vận hành hệ thống thu nhận sản phẩm, các hệ thống phụ trợ khác như hệ thống hơi, hệ thống điện,...', '- Kiểm soát các vật liệu cho quá trình in gồm: Vật liệu nền (giấy, màng mỏng,...), các loại keo dán phù hợp, các loại vật tư trang trí khác,...', '- Thiết lập các quá trình hoàn thiện và trang trí phù hợp với đặc điểm sản phẩm để tạo ra sản phẩm in đạt tiêu chuẩn chất lượng;', '- Bảo trì và bảo dưỡng các bộ phận chức năng của các thiết bị trong hệ thống hoàn thiện xuất bản phẩm và bao bì.']::text[], array['- Thợ đóng sách', '- Thợ vận hành máy vào bìa', '- Thợ vận hành máy cắt giấy', '- Thợ vận hành máy ép nhũ', '- Thợ vận hành máy gấp', '- Thợ vận hành máy đóng sách liên hoàn', '- Thợ vận hành máy hoàn thiện', '- Thợ vận hành máy đóng sách bằng ghim, máy khâu sách', '- Thợ vận hành máy đóng gói nhỏ']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1624) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7411', 'Thợ lắp điện cho tòa nhà và thợ điện có liên quan lắp đặt, bảo trì và sửa chữa hệ thống dây điện, thiết bị và phụ tùng liên quan.', array['- Lắp đặt, bảo trì và sửa chữa hệ thống dây điện và thiết bị liên quan trong các tòa nhà như trường học, bệnh viện, trung tâm thương mại, nhà ở và các công trình khác;', '- Kiểm tra bản thiết kế, sơ đồ nối dây, thông số kỹ thuật để xác định trình tự và phương pháp hoạt động;', '- Lập kế hoạch bố trí và lắp đặt hệ thống dây điện, thiết bị và phụ tùng điện dựa trên thông số kỹ thuật và các tiêu chuẩn liên quan;', '- Kiểm tra hệ thống điện, thiết bị và linh kiện để xác định mối nguy hiểm, lỗi và sự cần thiết phải điều chỉnh hoặc sửa chữa;', '- Lựa chọn, cắt và kết nối dây điện và dây cáp với thiết bị đầu cuối và đầu nối;', '- Đo lường và bố trí các điểm tham chiếu lắp đặt;', '- Định vị và lắp đặt tổng đài điện;', '- Kiểm tra tính liên tục của mạch điện.']::text[], array['- Thợ sửa chữa điện cho tòa nhà', '- Thợ điện']::text[], array['- Thợ lắp máy phát điện - 7412', '- Thợ cơ điện - 7412', '- Thợ lắp đặt đường dây điện - 7413']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1649) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7412', 'Thợ lắp ráp và thợ cơ khí điện điều chỉnh, lắp đặt và sửa chữa máy móc, thiết bị điện tại các tòa nhà, nhà máy, xe cơ giới, nhà xưởng hay địa điểm khác.', array['- Lắp đặt, điều chỉnh và sửa chữa hệ thống máy móc và động cơ điện, máy phát điện, thiết bị chuyển mạch, bộ điều khiển hay bộ phận điện của thang máy và thiết bị liên quan;', '- Lắp đặt, điều chỉnh và sửa chữa các bộ phận điện trong thiết bị gia dụng, máy công nghiệp và các thiết bị khác;', '- Kiểm tra và thử nghiệm các sản phẩm điện được sản xuất;', '- Cài đặt, thử nghiệm, kết nối, vận hành, bảo trì và sửa chữa thiết bị điện, hệ thống dây điện và điều khiển;', '- Thiết kế, lắp đặt, bảo trì và sửa chữa thang máy chở khách bằng thủy lực và thang vận chuyển hàng, thang cuốn, thang băng chuyền và các thiết bị thang máy khác;', '- Kết nối hệ thống điện với nguồn điện;', '- Thay thế và sửa chữa các bộ phận bị hỏng.']::text[], array['- Thợ xây phần ứng điện', '- Thợ điện ô tô', '- Thợ lắp máy phát điện', '- Thợ cơ điện', '- Thợ điện thang máy']::text[], array['- Thợ cơ điện tử - 7421', '- Thợ lắp ráp thiết bị điện - 8202']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1667) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7413', 'Thợ lắp đặt và sửa chữa đường dây điện lắp đặt, sửa chữa, truyền tải điện, cung cấp cáp và thiết bị liên quan.', array['- Lắp đặt, sửa chữa đường dây điện trên cao và ngầm;', '- Tạo mối nối dây cáp trên cao và ngầm;', '- Tuân thủ các quy trình an toàn như kiểm tra thiết bị thường xuyên và dựng rào chắn xung quanh khu vực làm việc;', '- Mở công tắc hoặc gắn các thiết bị nối đất để loại bỏ mối nguy hiểm từ các đường dây bị rơi hoặc để tạo điều kiện sửa chữa;', '- Trèo cột điện hoặc dùng thùng gắn xe tải để tiếp cận thiết bị;', '- Xác định các thiết bị phân đoạn bị lỗi, bộ ngắt mạch, cầu chì, bộ điều chỉnh điện áp, máy biến áp, công tắc, rơle hoặc hệ thống dây điện bằng cách sử dụng sơ đồ nối dây và dụng cụ kiểm tra điện.']::text[], array['- Thợ nối cáp điện', '- Thợ đường dây điện']::text[], array['- Thợ cáp dữ liệu và viễn thông - 7422', '- Thợ đường dây viễn thông - 7422']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1686) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7421', 'Thợ cơ khí và thợ dịch vụ điện tử bảo trì, điều chỉnh và sửa chữa thiết bị điện tử như máy móc điện tử và thiết bị văn phòng, thiết bị điện tử và hệ thống điều khiển.', array['- Kiểm tra và thử nghiệm máy móc, dụng cụ, linh kiện, hệ thống điều khiển và các thiết bị điện tử khác để chẩn đoán các lỗi;', '- Điều chỉnh, sửa chữa và thay thế các bộ phận và hệ thống dây điện bị mòn và hỏng; bảo dưỡng máy móc, thiết bị và các dụng cụ;', '- Lắp ráp lại, kiểm tra, vận hành và điều chỉnh các thiết bị;', '- Lắp đặt các thiết bị điện tử và hệ thống điều khiển;', '- Phối hợp làm việc với các kỹ sư, kỹ thuật viên và nhân viên bảo trì khác;', '- Diễn giải dữ liệu thử nghiệm để chẩn đoán sự cố và các vấn đề về hiệu năng hệ thống;', '- Lắp đặt, điều chỉnh, sửa chữa hoặc thay thế các linh kiện điện và điện tử bằng dụng cụ cầm tay hoặc dụng cụ điện;', '- Kết nối các bộ phận với các tổ hợp như hệ thống vô tuyến, dụng cụ, nam châm, bộ biến tần và hệ thống tiếp nhiên liệu trên máy bay;', '- Lưu giữ hồ sơ của công việc bảo trì và sửa chữa.']::text[], array['- Thợ bảo trì máy bay (hệ thống điện tử hàng không)', '- Thợ cơ khí máy rút tiền tự động', '- Kỹ thuật viên điện tử hàng không', '- Thợ dịch vụ thiết bị điện tử', '- Thợ cơ điện tử', '- Thợ máy photo']::text[], array['- Kỹ thuật viên điện tử an toàn không lưu - 3155']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1704) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7422', 'Thợ lắp đặt và dịch vụ kỹ thuật thông tin và truyền thông lắp đặt, sửa chữa và bảo trì các thiết bị viễn thông, thiết bị truyền dữ liệu, cáp, ăng ten và ống dẫn; sửa chữa, lắp đặt và bảo dưỡng máy tính.', array['- Bảo dưỡng, khắc phục sự cố, kiểm tra và sửa chữa máy tính, thiết bị truyền dữ liệu và các thiết bị ngoại vi máy tính;', '- Lắp và điều chỉnh phần cứng của máy tính;', '- Lắp đặt, bảo dưỡng, sửa chữa và chẩn đoán sự cố của lò vi sóng, hệ thống đo từ xa, hệ thống vệ tinh, hệ thống thông tin vô tuyến và sóng điện từ khác;', '- Cung cấp tư vấn và thông tin kỹ thuật đồng thời giám sát hiệu suất của các mạng và thiết bị viễn thông phức tạp;', '- Cài đặt và sửa chữa hệ thống cáp cho máy tính, điện thoại và phát thanh truyền hình;', '- Nối cáp viễn thông với dữ liệu và bọc kín;', '- Lắp đặt, bảo dưỡng và sửa chữa ăng ten được sử dụng trong thông tin liên lạc.']::text[], array['- Thợ dịch vụ công nghệ truyền thông', '- Thợ lắp đặt thiết bị máy tính', '- Thợ cài đặt phần cứng máy tính', '- Thợ cáp dữ liệu và viễn thông', '- Thợ sửa chữa thiết bị viễn thông', '- Thợ đường dây viễn thông', '- Thợ lắp đặt điện thoại']::text[], array['- Kỹ thuật viên kỹ thuật viễn thông - 3522']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1725) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7511', 'Thợ giết, mổ, chuẩn bị thịt, cá và thực phẩm khác có liên quan giết mổ động vật, làm sạch, cắt, loại bỏ xương và chuẩn bị các thực phẩm liên quan; bảo quản thịt, cá và thực phẩm khác bằng cách sấy khô, ướp muối hay hun khói.', array['- Giết mổ động vật;', '- Lột da và chặt thịt động vật;', '- Loại bỏ xương, thái và tẩm ướp thịt, cá để bán hay chế biến sau này;', '- Chuẩn bị nguyên liệu, làm xúc xích và các sản phẩm tương tự bằng máy băm, trộn và tạo khuôn;', '- Hấp thịt, cá và thực phẩm khác;', '- Sử dụng máy hun khói hay lò nướng để hun thịt, cá và đồ ăn khác;', '- Nấu hoặc chuẩn bị thịt, cá và các thực phẩm liên quan theo cách khác để bán;', '- Bán thịt, cá cho khách hàng gồm cả việc gói, cân, dán nhãn sản phẩm và nhận thanh toán.']::text[], array['- Người bán thịt', '- Người lọc cá', '- Người bán cá', '- Người giết mổ']::text[], array['- Chủ cửa hiệu - 5221', '- Thợ vận hành máy chế biến cá - 8160', '- Thợ vận hành máy chế biến thịt - 8160']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1749) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7512', 'Thợ nướng bánh, thợ làm bánh ngọt và bánh kẹo làm nhiều loại bánh mỳ, bánh ngọt và các sản phẩm bột khác cùng với socola và đồ ngọt tự làm.', array['- Làm bánh mỳ, bánh ngọt, bánh quy, bánh nướng và các sản phẩm từ bột khác;', '- Làm bánh kẹo thủ công từ hỗn hợp đường, socola và nguyên liệu khác sử dụng công cụ cầm tay và một số máy móc thiết bị;', '- Cho nguyên liệu cân đong sẵn vào máy để trộn hoặc nấu;', '- Kiểm tra chất lượng nguyên liệu thô để đảm bảo các tiêu chuẩn và thông số chất lượng đều được đáp ứng;', '- Sử dụng men, kem hay các loại phụ liệu khác để nướng bánh, dùng thìa hoặc chổi lông;', '- Kiểm tra vệ sinh dụng cụ và cơ sở sản xuất để đảm bảo tuân thủ các quy định về sức khỏe và an toàn thực phẩm;', '- Theo dõi nhiệt độ lò nướng và sản phẩm để xác định thời gian nướng bánh;', '- Điều phối việc tạo hình, nướng, dỡ, khử mùi và làm nguội các lô bánh mì, bánh cuộn, bánh ngọt và sản phẩm bánh kẹo khác.']::text[], array['- Thợ làm bánh mỳ', '- Thợ làm socola', '- Thợ làm bánh kẹo', '- Thợ làm bánh ngọt']::text[], array['- Đầu bếp - 5120', '- Thợ vận hành máy nướng bánh - 8160', '- Thợ vận hành máy sản xuất bánh mỳ - 8160', '- Thợ vận hành máy sản xuất socola - 8160']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1769) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7513', 'Thợ sản xuất sản phẩm từ sữa chế biến bơ và các loại phô mai, kem hoặc các sản phẩm từ sữa khác.', array['- Tiệt trùng hoặc thanh trùng sữa để đạt hàm lượng chất béo quy chuẩn;', '- Tách kem từ sữa và trộn kem vào bơ;', '- Đổ các chất và các thành phần khác đã được cân đong vào sữa;', '- Vắt sữa, đung nóng sữa cho đến khi đạt độ đông mong muốn, xả sữa đông và đặt phô mai vào khuôn để ép thành hình;', '- Phô mai được cấy nấm mốc tạo thành phô mai xanh;', '- Giám sát chất lượng sản phẩm trước khi đóng gói bằng cách kiểm tra, lấy mẫu và điều chỉnh các điều kiện xử lý khi cần thiết;', '- Ghi lại số lượng thành phần được sử dụng, kết quả kiểm tra và chu kỳ thời gian.']::text[], array['- Thợ làm bơ', '- Thợ làm phô mai']::text[], array['- Thợ vận hành máy sản xuất sản phẩm từ sữa - 8160', '- Thợ vận hành máy chế biến sữa - 8160']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1790) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7514', 'Thợ bảo quản rau, hoa quả tươi và các thứ có liên quan xử lý hay bảo quản trái cây, hạt và thực phẩm liên quan theo nhiều cách khác nhau bao gồm nấu, sấy khô, ướp muối hoặc chiết xuất nước trái cây hay tinh dầu.', array['- Chiết xuất nước ép từ trái cây;', '- Chiết xuất tinh dầu từ hạt hay trái cây chứa dầu;', '- Nấu, ướp muối hay sấy khô trái cây, rau củ và thực phẩm liên quan;', '- Trộn và bổ sung nguyên liệu như chất làm đông mứt, đường, gia vị và giấm để hỗ trợ bảo quản, tăng cường kết cấu, vẻ ngoài và hương vị;', '- Chuyển thực phẩm bảo quản vào bình, chai hay hộp đựng vô trùng khác.']::text[], array['- Thợ sản xuất tương ớt', '- Thợ bảo quản trái cây', '- Thợ làm mứt', '- Thợ chiết xuất dầu', '- Thợ hái rau và quả', '- Thợ bảo quản rau']::text[], array['- Thợ vận hành máy đóng hộp - 8183']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1806) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7515', 'Thợ nếm và phân loại đồ uống, thực phẩm kiểm tra, thử và phân loại nông sản, thực phẩm và đồ uống.', array['- Kiểm tra, thử nghiệm, nếm và ngửi các sản phẩm nông nghiệp, thực phẩm, đồ uống tại các giai đoạn chế biến khác nhau;', '- Xác định chất lượng, khả năng chấp nhận thị hiếu của người tiêu dùng và giá trị tương đương của sản phẩm rồi phân loại chúng vào nhóm tương ứng;', '- Loại bỏ các sản phẩm kém chất lượng;', '- Ghi và nhập hạng phân loại hoặc số hiệu nhận dạng trên nhãn hiệu hay báo cáo kinh doanh;', '- Cân và đong sản phẩm.']::text[], array['- Thợ phân loại thực phẩm', '- Thợ nếm thực phẩm', '- Thợ nếm rượu', '- Thợ nếm trà', '- Thợ nếm rượu vang']::text[], '{}'::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1823) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7516', 'Thợ sản xuất và chuẩn bị thuốc lá pha chế lá thuốc lá và tạo sản phẩm thuốc lá.', array['- Phân hạng lá cây thuốc lá được bào chế theo chủng loại, chất lượng và vùng miền trồng loại cây đó;', '- Trộn lá thuốc lá theo công thức để có được sự pha trộn của hương vị riêng biệt;', '- Bảo quản thùng hút chân không làm ẩm thuốc lá để chế biến sau này;', '- Loại bỏ gân giữa và cuống khỏi lá thuốc và nghiền vụn thuốc lá;', '- Làm xì gà, điếu thuốc lá và các sản phẩm thuốc lá khác bằng thủ công hay máy móc đơn giản.']::text[], array['- Thợ sản xuất thuốc lá', '- Thợ sản xuất xì gà', '- Thợ phân hạng thuốc lá']::text[], array['- Thợ vận hành máy sản xuất thuốc lá - 8160', '- Thợ vận hành máy sản xuất xì gà - 8160']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1837) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7521', 'Thợ xử lý gỗ hong khô, bảo quản và xử lý gỗ thủ công hoặc sử dụng các thiết bị xử lý gỗ như lò sấy hay bể chứa.', array['- Vận hành, bảo dưỡng lò nung, xử lý bể chứa và các thiết bị khác để sấy gỗ, chuẩn bị, gia công gỗ và các sản phẩm gỗ khác; ngâm tẩm các sản phẩm gỗ bằng chất bảo quản;', '- Giám sát hoạt động của thiết bị, đồng hồ đo, đèn bảng để phát hiện sai lệch so với tiêu chuẩn và đảm bảo các quy trình đang hoạt động theo thông số kỹ thuật;', '- Vận hành van để đưa dung dịch xử lý vào bình xử lý; duy trì nhiệt độ, áp suất chân không, thủy lực quy định và mức dung dịch trong mỗi giai đoạn của chu trình xử lý;', '- Kích hoạt bơm chân không và áp suất thủy lực loại bỏ không khí, hơi nước; đưa dung dịch xử lý vào lỗ hổng của gỗ để đẩy nhanh quá trình xử lý;', '- Hỗ trợ bảo dưỡng thiết bị và máy móc chế biến theo yêu cầu;', '- Làm sạch, bôi trơn và điều chỉnh thiết bị;', '- Vận chuyển vật liệu, sản phẩm đến và đi từ khu làm việc bằng tay hoặc dùng xe đẩy, xe kéo hay cầu nâng;', '- Hoàn thiện và duy trì báo cáo sản phẩm.']::text[], array['- Thợ vận hành lò nung khô', '- Thợ vận hành lò sấy gỗ', '- Thợ vận hành bể xử lý gỗ', '- Thợ bảo quản lò sấy gỗ ván', '- Thợ ép gỗ', '- Thợ xử lý gỗ']::text[], array['- Thợ vận hành máy chế biến gỗ - 8172']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1855) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7522', 'Thợ sản xuất đồ gỗ và các thợ có liên quan đóng, trang trí, sửa chữa đồ gỗ, xe đẩy và các phương tiện, bánh xe, phụ tùng, khuôn mẫu, mô hình và các sản phẩm gỗ khác sử dụng máy chế biến gỗ, máy công cụ và dụng cụ cầm tay chuyên dụng.', array['- Vận hành các máy gia công gỗ như cưa điện, máy nối, máy nghiền và sử dụng các dụng cụ cầm tay để cắt, tạo hình và tạo thành các bộ phận và linh kiện;', '- Nghiên cứu kế hoạch, xác minh kích thước của vật dụng sản xuất; kiểm tra chất lượng, sự phù hợp các mẫu để đảm bảo tuân thủ thông số kỹ thuật;', '- Ghép các bộ phận với nhau để tạo thành sản phẩm hoàn chỉnh sử dụng keo, kẹp; gia cố các khớp bằng đinh, ốc vít;', '- Đóng, tái tạo và sửa chữa các vật dụng bằng gỗ như tủ, đồ nội thất, xe cộ, mô hình, dụng cụ thể thao và thiết bị hay sản phẩm khác;', '- Trang trí đồ nội thất và đồ đạc bằng chạm khắc hoặc khảm trai;', '- Hoàn thiện bề mặt của đồ gỗ hoặc đồ nội thất.']::text[], array['- Thợ đóng tủ', '- Thợ đóng xe đẩy', '- Thợ đóng tủ nội thất', '- Thợ đóng bánh xe lăn', '- Thợ tạo khuôn gỗ']::text[], array['- Thợ mộc - 7115', '- Thợ lắp ráp sản phẩm gỗ - 8209']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1875) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7523', 'Thợ lắp đặt và vận hành máy công cụ chế biến gỗ vận hành và giám sát các máy chế biến gỗ tự động hoặc bán tự động như cưa chính xác, tạo hình, bào, máy khoan, tiện và máy khắc gỗ để chế tạo hoặc sửa chữa các bộ phận bằng gỗ cho đồ nội thất, đồ đạc và các sản phẩm bằng gỗ khác.', array['- Thiết lập, lập trình, vận hành và giám sát các loại máy chế biến gỗ để cưa, tạo hình, khoan, bào, ép, tiện, đánh giấy ráp hay chạm khắc để chế tạo hoặc sửa chữa các bộ phận bằng gỗ cho đồ nội thất, đồ đạc và sản phẩm từ gỗ khác;', '- Vận hành máy chế biến gỗ chuyên dụng để chế tạo sản phẩm từ gỗ như mắc áo, cán chổi lau nhà, kẹp quần áo và sản phẩm khác;', '- Chọn dao, cưa, lưỡi dao, mũi dao phay, dây curoa theo chi tiết gia công, chức năng của máy và thông số kỹ thuật của sản phẩm;', '- Lắp đặt và điều chỉnh lưỡi cắt, đầu cắt, mũi khoan và dây curoa bào gỗ, dùng dụng cụ cầm tay;', '- Thiết lập và điều chỉnh các loại máy chế biến gỗ để người khác vận hành;', '- Đọc và giải thích thông số kỹ thuật hoặc làm theo chỉ dẫn bằng lời nói.']::text[], array['- Thợ vận hành máy khắc gỗ', '- Thợ vận hành máy sản xuất đồ gỗ', '- Thợ cưa gỗ', '- Thợ vận hành máy làm sản phẩm gỗ', '- Thợ vận hành máy tiện gỗ', '- Thợ thiết lập máy chế biến gỗ', '- Thợ vận hành máy khai thác gỗ', '- Thợ lắp đặt máy chế biến gỗ']::text[], array['- Thợ lắp ráp gỗ và các sản phẩm liên quan - 8209.', '(Xem tiếp Công báo số 1151 + 1152)', 'VĂN BẢN QUY PHẠM PHÁP LUẬT', 'THỦ TƯỚNG CHÍNH PHỦ', 'Quyết định số 34/2020/QĐ-TTg ngày 26 tháng 11 năm 2020', 'ban hành Danh mục nghề nghiệp Việt Nam', '(Tiếp theo Công báo số 1149 + 1150)', 'Phụ lục II', 'NỘI DUNG DANH MỤC NGHỀ NGHIỆP VIỆT NAM', '(Ban hành kèm theo Quyết định số 34/2020/QĐ-TTg', 'ngày 26 tháng 11 năm 2020 của Thủ tướng Chính phủ)', '________________']::text[], null, '2020_1149 + 1150_34-2020-QĐ-TTg.doc', 1893) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7531', 'Thợ may, thợ làm da thú và thợ làm mũ may và sửa chữa quần áo. Họ sản xuất quần áo may đo như bộ véc, áo khoác, váy từ vải dệt, da, lông thú và chất liệu khác hoặc làm mũ, tóc giả theo hướng dẫn của khách hàng và nhà sản xuất quần áo.', array['- May áo khoác ngoài, bộ véc, váy, áo sơ mi, áo bu-dông, đồ lót, áo lót, mũ, tóc giả và trang phục tương tự theo yêu cầu của khách hàng;', '- Chọn vải dệt, da hay lông thú phù hợp với kích thước, màu sắc, kiểu dáng và chất lượng vải; định dạng chúng theo mẫu thiết kế của hàng may mặc;', '- Thay đổi kiểu dáng quần áo như bóp ống quần hay lên gấu áo, thêm hoặc bớt miếng độn;', '- Chọn và sửa đổi các mẫu theo thông số kỹ thuật phù hợp cho khách hàng và các nhà sản xuất quần áo;', '- May, thay đổi và sửa chữa quần áo, váy, áo khoác và các sản phẩm may đo khác theo yêu cầu của khách hàng;', '- Sản xuất và bảo quản trang phục sử dụng trong các tác phẩm sân khấu, truyền hình và phim ảnh;', '- Gấp, xoắn và sấy khô chất liệu như satin hoặc lụa, may ruy băng hoặc vải thành hình hoa giả và nơ quanh vương miện và vành để tạo hình và trang trí mũ;', '- Khâu và gắn chặt các vật liệu và lọn tóc vào với nhau để làm tóc giả;', '- Pha trộn các sắc thái của tóc để tạo vẻ tự nhiên cho tóc giả; xếp các mẫu tóc theo các vị trí quy định và khâu các đoạn tóc vào nhau để thành các kiểu tóc;', '- Thiết kế, thay đổi, tái tạo và sửa chữa quần áo và các sản phẩm khác bằng lông thú;', '- Cải tạo lông thú hoặc da từ áo khoác cũ, đính lớp vải vào bên trong áo khoác lông và cắt quần áo lông thú.']::text[], array['- Thợ may quần áo nữ', '- Thợ phân loại lông', '- Thợ làm da thú', '- Thợ làm mũ', '- Thợ làm nón', '- Thợ may']::text[], array['- Thợ dệt thủ công - 7318', '- Thợ vận hành máy may - 8153']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 22) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7532', 'Thợ tạo mẫu và cắt quần áo và các thợ có liên quan tạo ra các mẫu để sản xuất hàng may mặc, sản phẩm dệt, da hoặc lông thú khác. Họ đánh dấu, cắt, tạo hình vải, da và chất liệu khác theo bản thiết kế hay thông số trong sản xuất hàng may mặc, mũ vành, mũ lưỡi trai, găng tay và sản phẩm khác.', array['- Thiết kế mẫu theo kích thước sử dụng biểu đồ, dụng cụ phác thảo, máy tính hoặc thiết bị phân loại;', '- Tạo ra các bản thiết kế hoặc các mẫu cho một trang phục cụ thể với sự trợ giúp của máy tính;', '- Tính kích cỡ của các mẫu, xem xét đến độ co dãn của chất liệu;', '- Vẽ chi tiết về các phần được phác thảo để chỉ ra chỗ nối cũng như vị trí nếp gấp, túi, khuy trên quần áo, khâu trang trí trên các bộ phận giày hoặc khoen lỗ trên các sản phẩm vải sử dụng máy tính hay dụng cụ phác thảo;', '- Định vị mẫu hay đo vật liệu để xác định các điểm cắt cụ thể hoặc đánh dấu vải phù hợp để cắt được tối đa sản phẩm;', '- Đặt mẫu chính lên trên vải và cắt mẫu;', '- Các mẫu thử nghiệm bằng cách may và chỉnh mẫu may;', '- Đặt các mẫu lên trên các lớp vải và cắt vải theo các mẫu sử dụng kéo điện hay kéo thủ công, máy cắt hoặc các thiết bị cắt được điều khiển bằng số của máy tính;', '- Cắt vải hay lông thú để may quần áo và các sản phẩm từ lông;', '- Cắt vật liệu thừa hay cắt chỉ ra khỏi thành phẩm như cắt các đầu lỏng của thành phẩm;', '- Định vị da lên khoang cắt của máy, tối đa hóa việc sử dụng theo lượng da, lỗ hổng da và độ căng của da;', '- Thực hiện các nhiệm vụ tạo mẫu, đánh dấu và cắt trong sản xuất các sản phẩm khác như hàng vải bạt.']::text[], array['- Thợ tạo mẫu lông thú', '- Thợ cắt may', '- Thợ tạo mẫu quần áo', '- Thợ cắt găng tay']::text[], array['- Thợ vận hành máy dệt mẫu - 8159']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 46) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7533', 'Thợ khâu vá, thợ thêu và các thợ có liên quan phối hợp may, sửa chữa, cải tiến và trang trí hàng may mặc, găng tay, các sản phẩm khác của dệt, lông thú, da và vật liệu khác; chế tạo và gia công lều, buồm, mái hiên và bạt. Họ làm việc chủ yếu bằng tay và dùng kim, chỉ nhưng có thể thực hiện một số công việc bằng máy khâu.', array['- Sửa chữa phần bị lỗi hay hư hỏng của tấm vải hay trang phục bằng tay, sử dụng chỉ và kim khâu;', '- Tháo các mũi khâu từ trang phục được thay đổi, sử dụng dây kéo hoặc lưỡi dao nhọn;', '- Chọn chỉ và màu chỉ phù hợp với vải;', '- Vá lỗ hổng, khâu vết rách và đường may bị rách hoặc khuyết điểm trong các vật phẩm, sử dụng kim và chỉ;', '- Kéo các nút thắt sang các mặt sau của quần áo, sử dụng móc;', '- Cắt tỉa các đầu bằng kéo để làm cho các phần được vá trông đồng nhất với mẫu vải;', '- Khâu các thiết kế trang trí bằng tay trên các mẫu đã được đóng dấu hoặc in trên vải, sử dụng kim và chỉ màu;', '- Thêu họa tiết trang trí trên vải bằng tay hoặc máy, sử dụng kim và chỉ màu;', '- Làm mềm da hoặc chất liệu giày bằng nước để chuẩn bị may giày;', '- Khâu hay đính trang trí cho các vật phẩm như mũ vành, mũ lưỡi trai hay mũ thời trang;', '- Khâu thủ công vải bọc ô để dựng khung, may lượt vải bọc vành ô dọc sườn ô, khâu các góc từ đỉnh vành ô và may nút thắt ngoài vải bọc để giữ ô khi gấp;', '- Gia công và lắp ráp vải dày hay vải bạt và vật liệu tương tự thành buồm, mái hiên, bạt và lều.']::text[], array['- Thợ thêu', '- Thợ khâu vá quần áo', '- Thợ may ô']::text[], array['- Thợ dệt thủ công - 7318', '- Thợ may - 7531', '- Thợ vận hành máy may - 8153']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 68) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7534', 'Thợ làm nghề bọc đồ đạc và các thợ có liên quan thực hiện lắp đặt, thay thế và sửa chữa lớp bọc đồ nội thất, đồ đạc, dụng cụ chỉnh hình, ghế ngồi, khung xe và các nội thất khác của ô tô, toa xe, máy bay, tàu thủy và vật dụng khác tương tự bằng vải, da, rexin hay vật liệu bọc khác. Họ cũng sản xuất và sửa gối, chăn ga và đệm.', array['- Thảo luận với khách hàng về chủng loại, màu sắc, kích thước vải bọc và cung cấp giá thành cho việc bọc đồ nội thất hay vật dụng khác;', '- Tạo các mẫu bọc từ bản phác thảo, sự mô tả của khách hàng hay bản vẽ kỹ thuật;', '- Bố trí, đo lường và cắt vật liệu bọc theo các mẫu, bản phác thảo hay chỉ dẫn thiết kế;', '- Lắp đặt, bố trí và bảo quản lò xo, lót đệm và bọc vật liệu vào khung nội thất;', '- Khâu vật liệu bọc cho đệm bằng tay và nối các phần của vật liệu che phủ;', '- Khâu đường xứt chỉ hay chỗ rách của vật liệu hoặc tạo đường chần, dùng kim và chỉ;', '- Dán hoặc khâu đồ trang trí, móc, viền, cúc, các phụ kiện khác để phủ hay khung trên các vật dùng được bọc;', '- Bố trí, cắt, chế tạo và láp đặt lớp bọc ngoài máy bay, xe cơ giới, tàu hỏa, thuyền và tàu thủy;', '- Sửa chữa tấm phủ da thô của chân tay giả;', '- Cải tạo đồ nội thất cổ bằng nhiều loại dụng cụ như đục, búa từ và kim dài;', '- Phối hợp với nhà thiết kế nội thất để trang trí phòng và phối hợp trang trí nội thất bằng vải;', '- Làm chăn ga, gối và đệm.']::text[], array['- Thợ bọc nội thất', '- Thợ sản xuất đệm', '- Thợ bọc ghế chỉnh hình', '- Thợ bọc xe']::text[], array['- Thợ vận hành máy may - 8153']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 91) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7535', 'Thợ thuộc da sống, thợ nhuộm và thợ chuyên lột da, lông thú cắt, cạo, làm sạch, thuộc và nhuộm da, lông thú để sản xuất da, lông thú thành phẩm để may quần áo và các sản phẩm khác.', array['- Sắp xếp và phân loại lông, da sống và da bì theo màu sắc, độ bóng, kích cỡ và nguồn gốc;', '- Cạo phần thịt, mỡ hay mô bảo vệ từ da hay lông để làm sạch hay làm mềm chúng;', '- Loại bỏ lông từ da bì hay da sống ngâm trong nước vôi;', '- Gia công da sống bằng cách ướp muối;', '- Loại bỏ lông dài, thô từ vỏ lông và tỉa lớp lông đến độ dài đều nhau;', '- Nhuộm da để tăng độ bóng đẹp hoặc để khôi phục lại vẻ ngoài tự nhiên của da;', '- Chuẩn bị vỏ cây và rượu myrobalan để xử lý da;', '- Xử lý da sống và da bì bằng liệu pháp thuộc da để chuyển chúng thành da thật;', '- Nhuộm lông thú để tăng màu lông tự nhiên;', '- Xóa nếp nhăn của da;', '- Bôi thuốc nhuộm lên da;', '- Kéo dài và làm mượt lông;', '- Làm sạch da bằng cách bôi dung dịch hóa học hoặc dầu đều lên bề mặt bằng bàn chải tay và để nó khô trong không khí.']::text[], array['- Thợ lột da, lông thú', '- Thợ phân loại da', '- Thợ thuộc da']::text[], array['- Thợ vận hành máy thuộc da - 8155']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 113) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7536', 'Thợ đóng giày và các thợ có liên quan đóng, hiệu chỉnh và sửa chữa giày dép sản xuất đại trà, theo đơn đặt hàng; chỉnh hình các sản phẩm da tự nhiên hoặc tổng hợp như va-li, túi xách, thắt lưng (trừ quần áo, mũ và găng tay da); tham gia sản xuất giày và hàng hóa liên quan. Họ trang trí, gia cố, hoàn thiện giày, va li, túi xách và thắt lưng.', array['- Sản xuất và sửa chữa giày dép theo tiêu chuẩn nhằm đáp ứng yêu cầu cá nhân;', '- Sản xuất và sửa chữa giày dép chỉnh hình hay trị liệu theo chỉ dẫn của bác sĩ hoặc hiệu chỉnh giày dép hiện có cho những ai gặp vấn đề về chân và có nhu cầu đặc biệt;', '- Sửa chữa thắt lưng, hành lý, ví và các sản phẩm tương tự;', '- Tạo khuôn thạch cao từ chân hay bàn chân bị biến dạng để chuẩn bị bản thiết kế;', '- Sửa chữa miếng độn, miếng lót và nâng gót giày từ khuôn chân khách hàng;', '- Nghiên cứu bản vẽ và chỉ dẫn kỹ thuật khác để đóng giày dép theo nhu cầu khách hàng;', '- Nghiên cứu các đơn đặt hàng để thu nhận thông tin về khối lượng công việc, thông số kỹ thuật và các loại vật liệu sẽ được sử dụng;', '- Kiểm tra kết cấu, màu sắc và độ bền của da để đảm bảo nó đáp ứng mục đích nhất định;', '- Cắt, tạo hình và đệm lót các bộ phận của vật dụng bằng da;', '- Khâu viền hoặc vá để sửa chữa các vật phẩm như ví, thắt lưng, giày và hành lý;', '- Loại bỏ và kiểm tra giày, cấu tạo và thiết kế giày để xác minh sự phù hợp với thông số kỹ thuật như luồn các mũi khâu vào các rãnh;', '- Gắn phụ kiện hay vật trang trí để trang trí và bảo vệ sản phẩm;', '- Chế tạo và sửa chữa các vật phẩm như yên ngựa, dây cương cho động vật, hành lý, túi xách, cặp, ba lô da, thắt lưng và phụ kiện khác.']::text[], array['- Thợ chữa giày', '- Thợ đóng giày chỉnh hình', '- Thợ đóng yên ngựa', '- Thợ đóng giày']::text[], array['- Thợ làm da thú - 7531', '- Thợ làm mũ - 7531', '- Thợ vận hành máy đóng giày - 8156']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 135) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7541', 'Thợ lặn làm việc dưới mặt nước, có hoặc không có sự trợ giúp của thiết bị thở dưới nước để kiểm tra, lắp đặt, sửa chữa và tháo gỡ thiết bị và kết cấu; tiến hành thử nghiệm hoặc thí nghiệm chất nổ giàn khoan, cấu trúc ảnh hay sinh vật biển; thu thập các dạng sinh vật biển khác nhau để bán hoặc nghiên cứu; tìm kiếm và phục hồi các vật phẩm và người mất tích.', array['- Thực hiện các biện pháp phòng ngừa an toàn như theo dõi chiều dài, độ sâu lặn và đăng ký với chính quyền trước khi cuộc thám hiểm lặn bắt đầu;', '- Kiểm tra và bảo dưỡng thiết bị lặn như mũ bảo hiểm, mặt nạ, bình dưỡng khí, bộ đồ lặn, dây lưng và đồng hồ đo;', '- Xuống nước với sự trợ giúp của thợ lặn, sử dụng thiết bị lặn hoặc bộ đồ lặn;', '- Làm việc dưới nước để đặt, sửa chữa cầu, trụ và móng tường;', '- Kiểm tra các hư hỏng đang nghi ngờ và tiến hành sửa chữa nhỏ cho thân tàu, vỏ tàu và thiết bị dưới nước;', '- Báo cáo về tình trạng tàu bị đắm;', '- Loại bỏ vật cản dưới nước;', '- Khoan lỗ để nổ mìn dưới nước;', '- Thực hiện các nhiệm vụ dưới nước khác nhau liên quan đến công việc cứu hộ hay phục hồi người đuối nước;', '- Thu thập động vật có vỏ, bọt biển và sinh vật biển khác;', '- Liên lạc với các thợ trên bờ trong khi lặn dưới nước, dùng đường dây tín hiệu hay điện thoại;', '- Nhận thông tin về nhiệm vụ lặn và điều kiện môi trường.']::text[], array['- Thợ mò hàu', '- Thợ lặn cứu hộ', '- Thợ mò bọt biển', '- Công nhân dưới nước']::text[], array['- Người lặn mò tự cung tự cấp - 6340']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 163) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7542', 'Thợ giật mìn phá đá định vị, lắp ráp, kích nổ chất nổ tại các khu vực khai thác và bãi thử chất nổ.', array['- Đảm bảo các quy trình và quy định về an toàn và vận chuyển chất nổ tại nơi làm việc được tuân thủ;', '- Lên kế hoạch và đưa ra chỉ dẫn về cách bố trí, độ sâu và đường kính hố bom;', '- Kiểm tra chiều sâu và độ sạch của hố bom;', '- Xác định quy mô và loại chất nổ sẽ được sử dụng;', '- Nạp chất nổ vào hố;', '- Lắp ráp hay chỉ dẫn công nhân khác lắp ráp, sạc mồi bằng cách dùng kíp nổ, hộp thuốc nổ và gắn dây điện, cầu chì, dây kích nổ vào mồi;', '- Nối dây ngòi, cầu chì và dây kích nổ thành kết cấu nổ; kiểm tra các mạch điện và khắc phục sự cố rồi nối kết cấu nổ và máy nổ;', '- Lấp đầy hố bom bằng bụi đá, cát và vật liệu khác;', '- Đảm bảo chất nổ được kích hoạt; báo cáo về các hành vi sai trái;', '- Tuyên bố các khu vực nổ an toàn trước và sau khi phát nổ chất nổ;', '- Lập và duy trì hồ sơ về việc sử dụng chất nổ theo quy định của pháp luật.']::text[], array['- Thợ nổ mìn', '- Thợ nạp thuốc súng', '- Thợ nạp đạn', '- Thợ giật mìn']::text[], array['- Giám sát viên khai thác mỏ - 3121', '- Thợ vận hành máy khoan (khai thác mỏ) - 8111', '- Thợ khoan (giếng dầu khí) - 8113', '- Lao động khai thác mỏ - 9311', '- Lao động khai thác đá - 9311']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 185) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7543', 'Thợ phân loại và kiểm tra sản phẩm (trừ thực phẩm và đồ uống) kiểm tra, thử nghiệm, phân loại, lấy mẫu và cân nguyên liệu, thành phần sản xuất và hàng hóa không thể ăn được sản xuất hay bán nhằm đảm bảo tuân thủ các tiêu chuẩn chất lượng, xác định mức độ hỏng, hao mòn và sai lệch so với thông số kỹ thuật để phân loại chúng theo chất lượng.', array['- Kiểm tra và thử nghiệm sản phẩm, phụ tùng, vật liệu đảm bảo đồng nhất với thông số kỹ thuật và tiêu chuẩn;', '- Phân hạng và phân loại sợi dệt tự nhiên để kéo sợi và cuộn dây;', '- Loại bỏ sản phẩm, vật liệu và thiết bị không đáp ứng thông số kỹ thuật;', '- Phân tích và giải thích bản thiết kế, dữ liệu, bản hướng dẫn và tài liệu khác để xác định các thông số kỹ thuật, quy trình kiểm tra và thử nghiệm;', '- Thông báo giám sát viên và nhân viên khác về các vấn đề sản phẩm; hỗ trợ xác minh và xử lý vấn đề;', '- Ghi lại dữ liệu kiểm tra như trọng lượng, nhiệt độ, cấp độ hoặc độ ẩm và đếm số lượng được kiểm tra hoặc phân loại;', '- Đánh dấu sản phẩm với các chi tiết như cấp độ, trạng thái chấp nhận hay loại bỏ;', '- Đo kích thước của sản phẩm bằng các dụng cụ như thước kẻ, thước cặp, đồng hồ đo hoặc micromet;', '- Phân tích dữ liệu thử nghiệm và tiến hành tính toán khi cần thiết để xác định kết quả thử nghiệm.']::text[], array['- Thợ phân loại sản phẩm', '- Thợ kiểm tra chất lượng', '- Thợ phân loại len']::text[], array['- Thanh tra an toàn sản phẩm - 3257', '- Thợ phân loại thực phẩm - 7515', '- Thợ phân loại lông - 7531', '- Thợ phân loại da - 7535']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 210) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7544', 'Thợ hun khói và thợ kiểm soát thực vật, động vật có hại khác dùng hóa chất để loại bỏ côn trùng, ký sinh, cỏ dại và sinh vật gây hại khác nhằm ngăn chặn thiệt hại cho cây trồng, tòa nhà và kiến trúc khác cùng môi trường xung quanh để ngăn ngừa mối nguy cho sức khỏe.', array['- Vận hành và giám sát thiết bị phun sâu bệnh và cỏ dại;', '- Trộn hóa chất theo chỉ dẫn;', '- Bao phủ các khu vực đến độ sâu quy định bằng thuốc trừ sâu; vận dụng kiến thức về điều kiện thời tiết, kích cỡ giọt, tỷ lệ độ cao trên khoảng cách và vật cản;', '- Phun hoặc xả hóa chất hay khí độc, đặt bẫy để tiêu diệt sâu bệnh, vật hại mùa màng như chuột, mối và gián;', '- Nâng, đẩy, lắc đầu phun, vòi phun và ống để phun trực tiếp lên các khu vực được chỉ định;', '- Đổ đầy bình phun bằng nước và hóa chất;', '- Vệ sinh và bảo dưỡng máy móc để đảm bảo hiệu suất vận hành;']::text[], array['- Thợ hun khói', '- Thợ kiểm soát sâu bệnh', '- Thợ kiểm soát cỏ dại']::text[], array['- Người phun thuốc trên không - 3153']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 231) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('7549', 'Thợ thủ công và các thợ khác chưa được phân vào đâu bao gồm những người đúc khuôn, cắt, mài và đánh bóng kính lúp quang học và các thợ cắm hoa trưng bày.', array['- Gia nhiệt, đúc khuôn và dập kính quang học để làm lăng kính lúp.', '- Mài và đánh bóng lăng kính lúp;']::text[], array['- Thợ cắm hoa', '- Thợ hoàn thiện thấu kính quang học', '- Thợ đúc khuôn thấu kính quang học']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 247) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8111', 'Thợ khai thác mỏ và đá vận hành máy móc thiết bị, dụng cụ cầm tay để khai thác đá, quặng khoáng sản và các mỏ khác bao gồm cả khai thác muối mỏ và muối biển.', array['- Định vị, vận hành và giám sát hiệu suất của nhiều loại thiết bị khai thác ngầm và trên bề mặt bao gồm máy khai khoáng, khoan cắt và vận chuyển liên hoàn;', '- Thiết lập và vận hành thiết bị khoan trong các mỏ ngầm và trên bề mặt mỏ;', '- Vận hành máy móc và sử dụng các dụng cụ cầm tay hoặc điện để khai thác đá, quặng, than và các mỏ khác;', '- Chuẩn bị, sửa chữa và lắp đặt phụ tùng tại các công trình ngầm;', '- Vận hành máy móc để mở hầm, bộ điều khiển, lỗ thông hơi, cầu nâng mới;', '- Thực hiện bảo dưỡng, sửa chữa nhỏ, bôi trơn và làm sạch máy móc, dụng cụ;', '- Hoàn thiện hồ sơ chi tiết quá trình vận hành hoàn chỉnh trong suốt ca trực;', '- Thu thập mẫu khoáng chất cho phân tích tại phòng thí nghiệm;', '- Khai thác muối mỏ, đập vụn muối và sàng muối;', '- Khai thác muối từ nước biển, nước mặn ở hồ hoặc nước mặn tự nhiên khác; nghiền, tẩy rửa và tinh chế muối phục vụ cho sản xuất.']::text[], array['- Thợ vận hành máy đào bùn', '- Thợ vận hành máy khai thác mỏ liên hoàn', '- Thợ vận hành máy xúc (khai thác)', '- Thợ vận hành máy khoan (khai thác)', '- Thợ mỏ', '- Thợ vận hành nhà máy khai thác', '- Thợ khai thác mỏ đá', '- Thợ vận hành máy sàng có mái che (khai khoáng)', '- Lao động làm muối']::text[], array['- Giám sát viên khai thác mỏ - 3121', '- Thợ nổ mìn - 7542', '- Thợ giật mìn - 7542', '- Thợ khoan (giếng dầu khí) - 8113', '- Lao động khai thác mỏ - 9311', '- Lao động khai thác đá - 9311']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 271) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8112', 'Thợ vận hành thiết bị chế biến khoáng sản và đá giám sát và vận hành máy móc, thiết bị xử lý đá, khoáng sản để thu các sản phẩm tinh chế sử dụng ngay lập tức hoặc chế biến thêm.', array['- Thiết lập và vận hành máy móc, thiết bị xay, nghiền, cắt, cưa đá, khoáng sản theo các thông số kỹ thuật;', '- Định vị khối và phiến đá lên máy để cưa, cắt và công đoạn sau này;', '- Giám sát và duy trì lưu lượng đá, khoáng chất chưa qua chế biến từ dây chuyền vào máy;', '- Vận hành thiết bị rửa, phân tách, khử, kết tủa, lọc, chiết; kết nối thiết bị để loại tạp chất và thu hồi khoáng chất;', '- Hòa trộn khoáng quặng với dung môi để tiếp tục xử lý sâu;', '- Phân tách chất cô đặc kim loại và khoáng chất từ quặng và phù sa bằng cách cô đặc, tách đãi, phân tách trọng lượng, lọc hoặc tách từ và tĩnh điện;', '- Quan sát thước đo, khoảng cách, bảng điều khiển, van và hệ thống điều chỉnh để đảm bảo thiết bị hoạt động an toàn và hiệu quả; phát hiện sự cố và hỗ trợ bảo trì và sửa chữa máy móc, thiết bị;', '- Kiểm tra các vật liệu được xử lý một cách trực quan hoặc bằng tay để đảm bảo tuân thủ các tiêu chuẩn và thông số kỹ thuật đã được thiết lập; thu thập các mẫu để thử nghiệm trong phòng thí nghiệm;', '- Ghi thông tin về quy trình xử lý hoàn chỉnh trong ca trực chẳng hạn như số lượng, loại và kích thước vật liệu được sản xuất;', '- Phân loại, sắp xếp và vận chuyển các khoáng sản và đá đã qua xử lý để đóng gói, tiếp tục chế biến hay vận chuyển.']::text[], array['- Thợ làm sạch than đá', '- Thợ vận hành máy nghiền (chế biến khoáng sản hay đá)', '- Thợ tách đãi (chế biến khoáng sản)', '- Thợ đãi vàng', '- Thợ vận hành máy cắt hoặc chế biến đá', '- Thợ vận hành máy nghiền khoáng sản']::text[], array['- Thợ cắt đá (thủ công hay thiết bị điện cầm tay) - 7113', '- Thợ khắc đá - 7113', '- Thợ đánh bóng đá (thủ công hay thiết bị điện cầm tay) - 7113', '- Thợ tách đá (thủ công hay thiết bị điện cầm tay) - 7113', '- Thợ vận hành máy (sản xuất bê tông) - 8114', '- Thợ vận hành máy đánh bóng đá - 8114']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 301) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8113', 'Thợ khoan, đào giếng và các thợ có liên quan lắp ráp và vận hành máy móc, thiết bị liên quan để đào giếng, trích xuất mẫu đá, chất lỏng và khí hoặc cho nhiều mục đích khác.', array['- Tháo dỡ, di chuyển và lắp ráp giàn khoan và thiết bị phụ trợ;', '- Lắp ráp và tháo dỡ đường ống, vỏ, đầu khoan và thay thế các thiết bị chức năng;', '- Kiểm soát vận hành để hạ thấp và nâng cao ống khoan, vỏ trong và ngoài giếng, điều chỉnh áp lực trong giếng và kiểm soát tốc độ của các công cụ;', '- Chuẩn bị khoan và kiểm tra hoạt động của máy bơm để đảm bảo lưu thông đầy đủ chất lỏng trong ống khoan và giếng khoan;', '- Giám sát đồng hồ đo và các chỉ số khác; quan sát thiết bị để phát hiện sự cố và tình trạng giếng bất thường và xác định nhu cầu thay đổi máy khoan hoặc thiết bị;', '- Bảo trì, điều chỉnh, sửa chữa và làm sạch giàn khoan, cẩu và máy móc khác;', '- Duy trì hồ sơ của hoạt động khoan và phục vụ;', '- Vận hành máy móc và công cụ để hút bụi;', '- Đóng và niêm phong giếng không còn được sử dụng;', '- Giám sát và đào tạo người lao động khác.']::text[], array['- Thợ khoan lỗ', '- Thợ vận hành thiết bị khoan', '- Thợ cần cẩu', '- Thợ điều hành cần cẩu', '- Thợ khoan phát triển', '- Thợ khoan định hướng', '- Thợ khoan giếng dầu khí', '- Thợ điều hành nhà máy khoan', '- Thợ vận hành giàn khoan', '- Thợ vận hành lưỡi đẩy', '- Thợ điều khiển việc khoan trên giàn khoan dầu', '- Thợ đẩy vòng quanh.']::text[], array['- Thợ nổ mìn - 7542', '- Thợ mỏ - 8111', '- Thợ khai thác mỏ đá - 8111']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 328) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8114', 'Thợ vận hành máy sản xuất xi măng, đá và khoáng khác giám sát và vận hành máy sản xuất và hoàn thiện bê tông đúc sẵn, bitum, các sản phẩm đá và làm đá đúc cho mục đích xây dựng.', array['- Vận hành máy ép đùn, đúc, trộn, bơm, đầm, nghiền và cắt để sản xuất và hoàn thiện bê tông đúc sẵn và các sản phẩm đá;', '- Vận hành nhà máy để sản xuất xi măng, vôi và clanhke bao gồm các thành phần bốc xếp và vận hành các thiết bị cung cấp liên tục như máy bơm và băng tải;', '- Vận hành nhà máy và máy móc để cân và trộn cát, sỏi, xi măng, nước và các thành phần khác để làm bê tông;', '- Vận hành máy móc đổ đầy khuôn bằng hỗn hợp bê tông và đá nhân tạo, loại bỏ vật đúc khỏi khuôn và bề mặt hoàn thiện của sản phẩm đúc sẵn;', '- Cắt, mài, khoan, phun cát và đánh bóng các sản phẩm bê tông, khối đá, tấm và các sản phẩm theo thông số kỹ thuật;', '- Kiểm tra kế hoạch sản xuất và thông số kỹ thuật để xác định và lựa chọn vật liệu, thành phần, quy trình, cài đặt và điều chỉnh cho máy ép đùn, đúc, trộn và nén;', '- Giám sát nhà máy và máy móc trong quá trình vận hành bằng cách quan sát các dụng cụ như đồng hồ đo nhiệt độ và áp suất, điều chỉnh các điều khiển và báo cáo sự cố khi cần thiết;', '- Thu thập và kiểm tra các mẫu hỗn hợp và thành phẩm cho phù hợp với thông số kỹ thuật và điều chỉnh cài đặt máy cho phù hợp;', '- Kiểm tra và duy trì hồ sơ sản xuất bao gồm thông tin về số lượng, kích thước, loại vật liệu và hàng hóa được sản xuất;', '- Sắp xếp và hỗ trợ bảo trì và sửa chữa nhà máy và máy móc.']::text[], array['- Thợ vận hành máy đúc sản phẩm bê tông;', '- Thợ vận hành máy đúc đá;', '- Thợ vận hành máy hoàn thiện bê tông;', '- Thợ vận hành máy sản xuất bê tông;', '- Thợ vận hành máy đánh bóng kim cương công nghiệp;', '- Thợ vận hành máy đánh bóng đá.']::text[], array['- Thợ đánh bóng đá (bằng tay hoặc dụng cụ cầm tay) - 7113', '- Thợ vận hành máy chế biến đá - 8112', '- Thợ ép đất sét ép - 8181', '- Thợ vận hành lò nung (gạch, gốm) - 8181', 'Ghi chú:', 'Ví dụ về các sản phẩm được sản xuất trong nhóm này bao gồm: Bê tông hỗn hợp để sử dụng trong các dự án xây dựng và xây dựng dân dụng, cột cờ, gạch bê tông, cột hàng rào, phần ống đúc và ống mương, tà vẹt đường sắt, ốp tường và tấm vách ngăn các thành phần xây dựng, ống dẫn cáp, ống dẫn khói và bụi, bánh xe mài mòn và đồ gỗ ngoài trời.']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 358) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8121', 'Thợ vận hành thiết bị xử lý kim loại giám sát, vận hành, điều chỉnh, bảo trì máy móc, thiết bị xử lý đơn chức năng để xử lý và chuyển đổi quặng khoáng sản; tinh chế, làm cứng, cuộn và đùn kim loại.', array['- Thiết lập, chuẩn bị và điều chỉnh máy chế biến quặng khoáng sản và kim loại để thực hiện một bước trong hoạt động tổng thể của chế biến quặng khoáng sản hoặc kim loại;', '- Vận hành máy móc đơn chức năng để mài, tách, lọc, trộn, xử lý, đúc khuôn, cuộn, tinh chế hay các quy trình xử lý kim loại và quặng khoáng sản khác;', '- Giám sát thiết bị, máy đo, màn hình video và sản phẩm để đảm bảo vận hành máy móc chính xác và xác minh điều kiện xử lý được chỉ định;', '- Điều chỉnh thiết bị, van, máy bơm, điều khiển và thiết bị xử lý;', '- Kiểm soát việc chuẩn bị, đo lường, nạp nguyên liệu thô và các tác nhân chế biến trong nhà máy;', '- Kiểm soát quá trình khởi động và tắt máy; xử lý sự cố và giám sát thiết bị xử lý ngoại vi;', '- Xác nhận thiết bị gặp sự cố, thực hiện các thử nghiệm vận hành định kỳ và sắp xếp để bảo dưỡng;', '- Phân tích các sản phẩm mẫu, thực hiện các thử nghiệm, ghi dữ liệu và ghi nhật ký sản xuất.']::text[], array['- Thợ rót khuôn', '- Thợ điều hành nhà máy ép đùn kim loại', '- Thợ vận hành xử lý nhiệt kim loại', '- Thợ cuộn thép']::text[], array['- Người vận hành lò cao - 3135', '- Người điều khiển trung tâm - 3135', '- Người vận hành điều khiển máy cán - 3135', '- Thợ vận hành máy mạ kim loại - 8122']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 388) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8122', 'Thợ vận hành máy hoàn thiện, tráng, mạ kim loại giám sát, vận hành thiết bị hoàn thiện, tấm và lớp phủ các vật phẩm hoặc bộ phận kim loại để cải thiện khả năng chống ăn mòn và mài mòn cho mục đích trang trí hoặc để truyền điện, từ tính.', array['- Vận hành và giám sát thiết bị giúp làm sạch các vật phẩm kim loại để chuẩn bị cho quá trình mạ điện, mạ kẽm, tráng men hoặc các xử lý tương tự;', '- Vận hành và giám sát thiết bị mạ điện;', '- Vận hành và giám sát thiết bị nhúng nóng dùng để tráng các sản phẩm sắt, thép;', '- Vận hành và giám sát máy tự động mạ dây bằng kim loại màu;', '- Vận hành và giám sát máy phun kim loại nóng chảy hay tạp chất khác lên sản phẩm kim loại để tạo lớp phủ bảo vệ hay trang trí hoặc để tạo dựng các bề mặt bị ăn mòn hoặc hư hỏng;', '- Vận hành và giám sát thiết bị để tạo ra lớp phủ chống gỉ cho các sản phẩm kim loại bằng hóa chất và làm nóng;', '- Kiểm tra độ dày thích hợp của mạ bằng micromet, thước kẹp hoặc các thiết bị khác; ghi dữ liệu và nhật ký sản xuất;', '- Chuẩn bị và trộn các dung dịch kim loại hóa theo công thức hoặc hướng dẫn kỹ thuật.']::text[], array['- Thợ vận hành máy phủ kim loại', '- Thợ vận hành máy hoàn thiện kim loại', '- Thợ vận hành máy mạ kim loại', '- Thợ vận hành máy đánh bóng kim loại']::text[], array['- Kiểm soát viên quy trình sản xuất kim loại - 3135', '- Thợ sơn xe - 7132']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 409) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8131', 'Thợ vận hành máy và thiết bị sản xuất hóa chất vận hành và giám sát các thiết bị và máy để pha trộn, xử lý và đóng gói một loạt các sản phẩm hóa học.', array['- Thiết lập, khởi động, điều khiển, điều chỉnh và tắt máy móc, thiết bị;', '- Giám sát các quy trình phản ứng và chuyển giao sản phẩm phù hợp với quy trình an toàn;', '- Kiểm tra, theo dõi các dụng cụ đo, máy đo và các thiết bị điện tử trên một hoặc nhiều đơn vị hóa học hoặc công thức như máy trộn, máy sấy khô, máy đóng gói, máy tạo hạt và máy phủ;', '- Tạo mẫu và thực hiện các xét nghiệm hóa học và vật lý thông thường của sản phẩm; ghi lại dữ liệu sản xuất;', '- Lau dọn và thực hiện các việc sửa chữa nhỏ cho các thiết bị và máy móc.']::text[], array['- Thợ vận hành máy sản xuất nến', '- Thợ vận hành máy sản xuất thuốc nổ', '- Thợ vận hành máy sản xuất dược phẩm và dung dịch vệ sinh']::text[], array['- Kiểm soát viên nhà máy xử lý hóa chất - 3133', '- Người vận hành nhà máy lọc dầu và khí tự nhiên - 3134']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 431) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8132', 'Thợ vận hành máy sản xuất sản phẩm phim ảnh vận hành và giám sát thiết bị tạo ảnh trên phim và giấy, xử lý phơi sáng phim ảnh và tạo ảnh in.', array['- Vận hành và giám sát các thiết bị tạo ảnh trên phim và giấy;', '- Vận hành, giám sát và thử nghiệm thiết bị xử lý và in ảnh; duy trì các tiêu chuẩn hoạt động;', '- Chuẩn bị phơi sáng phim cho quá trình xử lý khác nhau trong phòng tối và buồng tối;', '- Kiểm tra hình ảnh, phim, bản in và điều chỉnh cài đặt trên thiết bị in để tạo ra màu sắc, độ sáng, độ tương phản, số lượng, kích thước và loại ảnh in cần thiết;', '- Điều chỉnh cài đặt và vận hành tự động các thiết bị rửa ảnh;', '- Vận hành thiết bị để chuyển từ phim sang băng video hoặc các phương tiện điện tử khác;', '- Thực hiện các nhiệm vụ liên quan đến xử lý ảnh;', '- Vận hành các thiết bị tự động (trong các cơ sở bán lẻ) để rửa các bản ảnh in, slide, âm bản màu.']::text[], array['- Thợ phát triển màu sắc (phim)', '- Kỹ thuật viên phòng tối', '- Thợ vận hành máy chụp ảnh', '- Thợ vận hành máy mở rộng', '- Thợ phóng ảnh', '- Thợ vận hành máy quay phim', '- Thợ in phim chụp ảnh', '- Thợ xử lý ảnh', '- Thợ in ảnh']::text[], array['- Nhiếp ảnh gia - 3431', '- Thợ quét và xử lý ảnh - 7321']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 446) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8141', 'Thợ vận hành máy sản xuất sản phẩm cao su vận hành và giám sát máy nhào trộn các hợp chất cao su; sản xuất các thành phần và sản phẩm khác nhau từ cao su tự nhiên và tổng hợp như giày dép đúc, nội thất, vật liệu cách điện, phụ kiện công nghiệp hay lốp xe.', array['- Vận hành và giám sát máy nhào, trộn các hợp chất cao su và cao su để tiếp tục xử lý;', '- Vận hành và giám sát máy sản xuất tấm cao su hay cao su hóa vải sợi theo quy trình cán;', '- Vận hành và giám sát máy ép đùn cao su tổng hợp hay định dạng cao su lưu hóa bằng khuôn đúc;', '- Vận hành và giám sát các máy dựng lốp xe trên khuôn, lưu hóa lốp xe và đúc hoặc tái tạo lốp đã qua sử dụng;', '- Kiểm tra đầu ra để phát hiện lỗi và đảm bảo thống nhất với thông số kỹ thuật;', '- Định vị lỗi và sửa chữa lốp xe bị mòn và bị hỏng bằng cách lưu hóa hoặc các cách xử lý khác.']::text[], array['- Công nhân cao su', '- Thợ vận hành máy ép đùn cao su', '- Thợ vận hành máy phay cao su', '- Thợ đúc khuôn cao su', '- Thợ vận hành máy sản xuất cao su', '- Thợ sản xuất lốp xe', '- Thợ sửa lốp', '- Thợ lưu hóa']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 473) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8142', 'Thợ vận hành máy sản xuất sản phẩm nhựa giám sát và vận hành máy nhào trộn các hợp chất để thu được chất liệu nhựa và tạo ra các thành phần, vật phẩm nhựa khác.', array['- Vận hành và giám sát máy nhào trộn các hợp chất để thu được chất liệu nhựa;', '- Vận hành và giám sát máy tạo hình vật liệu nhựa bằng đúc khuôn, ép, thổi, cắt và các phương pháp khác;', '- Vận hành và giám sát các máy ép nhựa và vật liệu tẩm nhựa hay sản xuất sợi thủy tinh;', '- Bọc nhựa dây nối, dây dẫn, dây cáp và sợi quang học không tráng phủ bằng nhựa;', '- Kiểm tra đầu ra để phát hiện lỗi và đảm bảo thống nhất với thông số kỹ thuật;', '- Tái chế phế thải nhựa;', '- Chế tạo mắt nhân tạo và đĩa kính áp tròng; chế tạo, sửa chữa khung kính và các bộ phận bằng nhựa của các thiết bị chỉnh hình.']::text[], array['- Thợ vận hành máy ép nhiều lớp (nhựa)', '- Thợ kéo sợi quang', '- Thợ đóng thuyền nhựa', '- Thợ vận hành máy thổi chai nhựa', '- Thợ vận hành máy làm cáp nhựa', '- Thợ vận hành máy ép đùn nhựa', '- Thợ đúc khuôn nhựa', '- Thợ vận hành máy sản xuất nhựa']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 491) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8143', 'Thợ vận hành máy sản xuất sản phẩm từ giấy và thùng cac-tông giám sát và vận hành máy sản xuất hộp, phong bì, túi và các hàng hóa khác từ giấy, bìa giấy, bìa cứng và các vật liệu tương tự.', array['- Vận hành và giám sát các máy dán keo giấy vào bìa cứng; cắt nó theo chiều dài cần thiết hoặc cắt và gấp các tông hoặc bìa để tạo thành các ô trống;', '- Vận hành và giám sát các máy ép tạo thành cốc uống hoặc các vật chứa khác từ giấy, bìa hoặc bìa cứng;', '- Vận hành và giám sát các máy cắt, gấp, dán giấy để làm phong bì, túi giấy hoặc tạo thành túi từ vật liệu tương tự khác.']::text[], array['- Thợ vận hành máy (sản xuất bìa cứng)', '- Thợ vận hành máy (sản xuất bao và túi giấy)', '- Thợ vận hành máy (sản xuất hộp giấy)', '- Thợ vận hành máy sản xuất giấy', '- Thợ phay giấy']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 510) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8151', 'Thợ vận hành máy xe sợi, kéo sợi và cuộn sợi giám sát và vận hành máy chuẩn bị sợi, kéo sợi, quay, bện và xe sợi từ sợi tự nhiên. Họ bện hai hay nhiều sợi để thành một bó sợi bền, mượt, đồng đều và nặng hơn; xử lý sợi để tạo độ cứng và chống thấm nước.', array['- Vận hành và giám sát máy cào vải thành bông sợi;', '- Vận hành và giám sát máy làm sạch và biến sợi len thừa thành len lông tơ;', '- Vận hành và giám sát máy kết hợp sợi dệt thành bó thống nhất;', '- Vận hành và giám sát các máy làm sạch, xáo trộn các sợi dệt và chải chúng thành sợi cho lần rút đầu tiên, kết hợp các sợi thành bó hoặc cuộn sợi thành vòng ruy băng;', '- Vận hành khung (máy) rút sợi quy mô lớn, kết hợp các sợi rút thành một bó tương đồng về khối lượng và độ dày như sợi gốc;', '- Vận hành và giám sát máy kéo chỉ và sợi từ sợi thô, cuộn nhiều sợi lên trên suốt chỉ, xoắn nhiều sợi hoặc chỉ thành bó để tăng cường độ bền, độ mượt và độ đồng đều của sợi hoặc chỉ từ bao kiện này đến bao kiện khác;', '- Vận hành và giám sát khung kéo sợi rút ra và xoắn thành sợi hoặc chỉ;', '- Vận hành và giám sát máy kéo các sợi từ máy rút sợi xoắn được bện lỏng;', '- Chuẩn bị hỗn hợp để làm cứng và hoàn thiện vải, sợi bằng cách trộn các thành phần như tinh bột, mỡ động vật, nhựa, xà phòng với nước và đun sôi trong thời gian quy định trong hơi nước;', '- Xử lý hàng dệt bằng hóa chất để làm cho chúng chống nước;', '- Làm sạch con lăn và xi-lanh để loại bỏ len thừa;', '- Vận hành và tái tạo bề mặt kim loại hệ thống con lăn của máy kéo sợi, chải và vắt bằng vỏ cao su hoặc da mới.']::text[], array['- Thợ vận hành máy chải sợi', '- Thợ vận hành máy chuẩn bị sợi', '- Thợ vận hành máy kéo chỉ và sợi', '- Thợ vận hành máy xoắn chỉ và sợi', '- Thợ vận hành máy cuộn chỉ và sợi']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 525) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8152', 'Thợ vận hành máy dệt kim, máy đan thiết lập, vận hành và giám sát máy dệt và đan, xử lý sợi hay chỉ thành sản phẩm dệt, không dệt và dệt kim như vải, ren, thảm, vải công nghiệp, hàng dệt kim và đan hay vỏ chăn và vải thêu.', array['- Thiết lập và vận hành pin của máy dệt kim tự động, liên kết để đan trang phục với các mẫu và thiết kế cụ thể;', '- Luồn sợi, chỉ khâu và vải qua hệ thống thanh dẫn sợi, kim và con lăn của máy dệt, đan và các máy gia công khác;', '- Bảo trì máy dệt tự động đồng thời dệt sợi cọc, làm đầy sợi và vật liệu sợi để sản xuất thảm và thảm trải sàn với thiết kế màu sắc đa dạng;', '- Vận hành và giám sát máy dệt mà sợi hoặc xoắn được giao nhau và thắt nút đều đặn để tạo thành lưới;', '- Vận hành và giám sát máy đa kim tự động công suất lớn để thêu vật liệu hoặc may theo độ dài các lớp vật liệu để làm hàng hóa sợi, vỏ chăn hay ga đệm;', '- Bảo trì máy dệt kim tròn với điều khiển mẫu tự động đan ống liền mạch;', '- Vận hành và giám sát máy đan hàng dệt kim với định dạng bàn chân và cẳng chân;', '- Vận hành và giám sát máy đan gót và ngón chân của tất;', '- Vận hành và giám sát các máy móc có đường may hở ở mũi tất;', '- Vận hành và giám sát máy móc để đan ren, cắt tỉa theo mẫu hay thiết kế định sẵn;', '- Kiểm tra máy dệt để xác định nguyên nhân sự cố ngừng hoạt động như làm đầy sợi dọc, đứt dây hay lỗi cơ học;', '- Sửa chữa hay thay thế kim bị mòn hoặc bị hỏng và các phụ tùng khác;', '- Làm sạch, tra dầu, bôi trơn máy móc, sử dụng ống khí, dung dịch tẩy rửa, giẻ lau, can dầu hay súng mỡ.']::text[], array['- Thợ vận hành máy dệt thảm', '- Thợ vận hành máy đan', '- Thợ vận hành máy sản xuất lưới', '- Thợ vận hành máy dệt']::text[], array['- Thợ dệt thảm - 7318', '- Thợ dệt vải - 7318', '- Thợ đan - 7318']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 546) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8153', 'Thợ vận hành máy may giám sát và vận hành máy may để sản xuất, sửa chữa, làm mờ và đổi mới hàng dệt may, lông thú, tổng hợp hoặc da; thêu các thiết kế trang trí trên hàng may mặc hoặc các vật liệu khác. Họ vận hành máy làm khuy áo và cắt khuyết áo, thùa khuyết, khâu nút và sửa dây đeo cho hàng may mặc.', array['- Vận hành hoặc chăm sóc máy may để thực hiện các hoạt động may như tham gia, gia cố, may hoặc trang trí hàng may mặc hoặc các bộ phận may mặc;', '- Đính các nút, móc, khóa kéo, ốc vít hoặc các phụ kiện khác vào vải, sử dụng phễu nạp hoặc kẹp giữ;', '- Chăm sóc máy may bán tự động với nhiều đầu may được điều khiển bởi các chuỗi hoa văn thêu các thiết kế khác nhau trên hàng may mặc;', '- Vận hành các máy như máy cắt kim đơn hoặc đôi, máy cắt ép để tự động tham gia, gia cố, trang trí vật liệu hoặc vật phẩm;', '- Vận hành máy may lông thú để nối các dải lông thú với kích thước và hình dạng cần thiết và nối các tấm vải vào các phần may hoặc vỏ;', '- Vận hành máy khâu để khâu các bộ phận da với nhau cho quần áo, túi xách, găng tay hoặc các mặt hàng tương tự;', '- Giám sát các hoạt động của máy để phát hiện các vấn đề như khâu bị lỗi, đứt chỉ hoặc trục trặc của máy;', '- Thực hiện các nhiệm vụ bảo trì thiết bị như thay kim.']::text[], array['- Thợ vận hành máy thêu', '- Thợ vận hành máy may']::text[], array['- Thợ dệt thủ công - 7318', '- Thợ làm da thú - 7531', '- Thợ may - 7531', '- Thợ thêu - 7533', '- Thợ khâu - 7533']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 571) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8154', 'Thợ vận hành máy tẩy trắng, máy nhuộm và làm sạch sợi vận hành và giám sát máy tẩy trắng, co, nhuộm và xử lý các loại sợi, chỉ hoặc vải.', array['- Khởi động và điều khiển máy móc thiết bị tẩy trắng, nhuộm hoặc xử lý và hoàn thiện vải, sợi, chỉ hay hàng dệt khác;', '- Bảo trì máy co vải dệt thoi hay dệt kim theo kích cỡ định sẵn hoặc gia cố vải dệt bằng cách đan các sợi vào nhau;', '- Bảo trì các loại máy tự động chải và đánh bóng lông thú;', '- Vận hành và giám sát máy xử lý tơ tằm để làm lụa tơ tằm;', '- Vận hành và giám sát các máy tẩm hàng dệt bằng hóa chất để làm chúng không thấm nước;', '- Nhuộm các sản phẩm để thay đổi hay khôi phục màu sắc của chúng;', '- Vận hành và giám sát máy duỗi hoặc hoàn thiện vải;', '- Giám sát và điều chỉnh các thiết bị khử trùng và loại bỏ vật lạ ra khỏi lông thú;', '- Vận hành máy chải, sấy khô và đánh bóng lông thú; làm sạch, tiệt trùng và làm mềm lông và vỏ chăn;', '- Nhập các hướng dẫn xử lý để lập trình thiết bị điện tử;', '- Quan sát màn hình hiển thị, hệ điều hành, thiết bị và quy trình nhập vải hay xử lý lối ra để xác định thiết bị vận hành chính xác;', '- Làm sạch bộ lọc máy và thiết bị bôi trơn.']::text[], array['- Thợ vận hành máy tẩy trắng sợi', '- Thợ vận hành máy nhuộm vải']::text[], array['- Thợ in vải - 7322', '- Thợ vận hành máy giặt - 8157', '- Thợ giặt bằng tay - 9121', '- Thợ ủi bằng bàn là cầm tay - 9121']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 591) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8155', 'Thợ vận hành máy chuẩn bị da, lông thú giám sát và vận hành các loại máy khác nhau gia công da hay chế biến vỏ lông, vỏ len. Họ cắt tỉa, cạo, làm sạch, thuộc, nhuộm da sống động vật, vỏ lông hay da bì để sản xuất tấm da và lông hoàn thiện.', array['- Vận hành và giám sát máy móc loại bỏ thịt và mỡ từ da sống hay vỏ lông để vệ sinh và làm mềm trước khi chế biến;', '- Vận hành và giám sát máy móc loại bỏ lông thô dài từ vỏ lông, tỉa san bằng lông rồi nhuộm, kéo căng và làm mềm các lớp lông;', '- Vận hành và giám sát máy móc loại bỏ lông biểu bì, tế bào sắc tố và muối khỏi bề mặt của da;', '- Vận hành và giám sát máy móc cạo bớt da sống hay da bì đến kích thước đồng đều;', '- Vận hành và giám sát máy đánh bóng, đánh ráp da sống hay da bì đến mức hoàn thiện nhất định;', '- Vận hành và giám sát máy phân tách len thừa từ da hay thịt và lông từ da sống;', '- Vận hành và giám sát máy móc mà qua đó da sống được phân chia các lớp để tạo thành hai hay nhiều mảnh hoặc tạo đồ dày đồng đều;', '- Vận hành và giám sát máy móc xử lý da sống và da bì theo các giải pháp để chuyển chúng thành da;', '- Xử lý bề mặt da bằng dầu và vận hành máy đánh bóng để tạo độ bóng láng cho da;', '- Vận hành và giám sát máy móc, thiết bị nhuộm và làm sạch vết bẩn cho da;', '- Bảo dưỡng và sửa chữa khoang máy và máy móc khác.']::text[], array['- Thợ vận hành máy khử mùi da thú', '- Thợ vận hành máy nhuộm da', '- Thợ vận hành máy thuộc da']::text[], array['- Thợ lột da, lông thú - 7535', '- Thợ thuộc da - 7535']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 614) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8156', 'Thợ vận hành máy đóng giày, dép và các thợ có liên quan giám sát và vận hành các máy sản xuất, sửa chữa giày, dép đại trà hoặc chuyên dụng, túi xách và các phụ kiện khác chủ yếu làm bằng da.', array['- Vận hành và giám sát máy móc đánh dấu các mẫu và cắt các bộ phận giày;', '- Vận hành và giám sát máy may, viền, đánh bóng, gắn họa tiết và tiến hành công đoạn hoàn thiện giày;', '- Vận hành và giám sát máy sản xuất vali, túi xách, thắt lưng, các phụ kiện khác cùng với vật dụng khác như yên ngựa, vòng cổ, dây cương;']::text[], array['- Thợ vận hành máy đóng giày dép']::text[], array['- Thợ làm đồ da thủ công - 7318', '- Thợ chữa giày - 7536']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 635) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8157', 'Thợ vận hành máy giặt là vận hành máy giặt, giặt khô, là, ủi và các loại máy xử lý vải trong các cơ sở giặt là và giặt khô.', array['- Phân loại sản phẩm để giặt theo mầu sắc, chất liệu vải và xử lý làm sạch theo yêu cầu;', '- Để các đồ đã được phân loại vào các thùng chứa và lên trên các băng tải để di chuyển chúng đến khu vực sửa chữa và làm sạch;', '- Kiểm tra và loại bỏ vết bẩn khỏi quần áo, thay các nút áo và thực hiện các sửa chữa nhỏ;', '- Dỡ và xếp máy giặt, máy sấy khô và máy vắt;', '- Thêm chất tẩy rửa và các chất hồ để hồ vải;', '- Làm mềm quần áo và đưa chúng vào máy giặt và máy là;', '- Tắt và bật máy để gỡ rối, làm cho phẳng và lấy các sản phẩm;', '- Đặt các đồ lên giá và treo chúng lên khi trả hàng và nhận hàng;', '- Đóng gói đồ và chuẩn bị hàng để gửi đi.']::text[], array['- Thợ vận hành máy giặt khô', '- Thợ vận hành máy giặt', '- Thợ vận hành máy ủi là']::text[], array['- Thợ giặt bằng tay - 9121', '- Thợ ủi bằng bàn là cầm tay - 9121']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 646) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8159', 'Thợ vận hành máy sản xuất nguyên liệu dệt, da lông thú và da thuộc chưa được phân vào đâu gồm các công việc liên quan vận hành và giám sát máy móc làm lều, làm mũ, đệm hay các vật phẩm như kẹp tóc và các đồ trang trí khác.', array['- Vận hành và giám sát máy móc định dạng và tạo mũ từ vải dệt, lông thú hoặc da;', '- Vận hành và giám sát máy móc sản xuất các vật phẩm như kẹp tóc hay các vật trang trí khác;', '- Vận hành và giám sát các máy gấp vải theo chiều dài đo sẵn;', '- Vận hành và giám sát máy luồn chỉ, dây bện hay sợi thành quả cầu để vận chuyển hay xử lý tiếp;', '- Vận hành và giám sát máy để đo kích thước của các miếng da;']::text[], array['- Thợ vận hành máy làm kẹp tóc', '- Thợ vận hành máy làm mũ', '- Thợ vận hành máy làm lều', '- Thợ vận hành máy dệt mẫu']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 665) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8160', 'Thợ vận hành máy sản xuất thực phẩm và các thợ có liên quan thiết lập, vận hành và giám sát máy móc dùng để giết mổ động vật và cắt thịt từ xác động vật; nướng, đông lạnh, hun nhiệt, nghiền, trộn, pha và chế biến thực phẩm, đồ uống và lá thuốc lá.', array['- Vận hành, giám sát máy móc được sử dụng để kiềm chế, gây choáng, giết mổ động vật và để cắt thành thịt và thịt cá theo tiêu chuẩn;', '- Thiết lập, vận hành, giám sát máy móc và lò nướng để trộn, nướng, chế biến các sản phẩm bánh kẹo và bột mỳ;', '- Vận hành máy nghiền, trộn, nấu và lên men ngũ cốc, hoa quả để sản xuất bia, rượu, mạch nha, dấm, men và sản phẩm liên quan;', '- Vận hành thiết bị làm mứt, kẹo cứng, phô mai, bơ thực vật, nước đá, mỳ ống chế biến sẵn, kem, xúc xích, sôcôla, tinh bột ngô, chất béo thực phẩm;', '- Vận hành thiết bị để làm nguội, hun nóng, sấy khô, nướng, hun khói, tiệt trùng, đông lạnh, làm bay hơi, cô đặc thực phẩm và chất lỏng được sử dụng trong chế biến thực phẩm;', '- Trộn, nghiền, phân tách thực phẩm và chất lỏng với thiết bị khuấy, ép, sàng, lọc;', '- Chế biến lá thuốc lá bằng máy để làm thuốc lá, xì gà, thuốc lào và các sản phẩm thuốc lá khác.']::text[], array['- Thợ vận hành máy sản xuất đồ nướng', '- Thợ vận hành máy sản xuất bánh mỳ', '- Thợ vận hành máy sản xuất sôcôla', '- Thợ vận hành máy sản xuất thuốc lá', '- Thợ vận hành máy sản xuất xì gà', '- Thợ vận hành máy sản xuất sản phẩm từ sữa', '- Thợ vận hành máy chế biến cá', '- Thợ vận hành máy chế biến thịt', '- Thợ vận hành máy chế biến sữa']::text[], array['- Thợ vận hành máy đóng chai - 8183']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 681) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8171', 'Thợ vận hành máy nghiền bột giấy và làm giấy giám sát và vận hành thiết bị xử lý gỗ, bột giấy và các vật liệu xenlulo khác trong quá trình sản xuất bột giấy để làm bao bì và giấy hoàn chỉnh.', array['- Vận hành và giám sát thiết bị sàng lọc và tẩy trắng, máy phân hủy, bể trộn, máy rửa và máy móc xử lý bột giấy khác để thực hiện một hoặc nhiều bước xử lý xenlulo;', '- Vận hành, giám sát máy móc, thiết bị chế biến và hoàn thiện giấy để sấy khô, cán mỏng, phủ, rọc, xén, cuộn hay thực hiện các bước quy trình làm giấy và hoàn thiện khác;', '- Kiểm soát khởi động và tắt máy móc, thiết bị; quan sát các chỉ số của bảng điều khiển thiết bị, máy móc, đồng hồ đo và các thiết bị khác để phát hiện sự cố máy móc, thiết bị và đảm bảo các bước của quy trình được thực hiện theo thông số kỹ thuật;', '- Liên lạc với các nhà điều hành quy trình để điều chỉnh quy trình, khởi động hoặc tắt máy móc, thiết bị theo yêu cầu;', '- Phân tích chỉ số dụng cụ và mẫu kiểm nghiệm sản xuất rồi tiến hành điều chỉnh quy trình và thiết bị sản xuất theo yêu cầu;', '- Gắn kết, định vị và luồn con lăn giấy bằng máy trục;', '- Kiểm tra giấy bằng trực quan để phát hiện nếp nhăn, lỗ thủng, chỗ đổi màu, vệt hoặc các khuyết tật khác và tiến hành khắc phục;', '- Hoàn thiện và duy trì báo cáo sản xuất.']::text[], array['- Thợ vận hành máy cán ép (bột giấy và giấy)', '- Thợ vận hành máy nghiền bột giấy và giấy', '- Thợ vận hành máy làm sạch lại', '- Thợ vận hành máy cắt (bột giấy và giấy)']::text[], array['- Nhà điều hành nhà máy bột giấy - 3139', '- Người điều khiển máy nghiền - 3139', '- Kỹ thuật viên nghiền - 3139']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 706) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8172', 'Thợ vận hành máy chế biến gỗ giám sát, vận hành và kiểm soát thiết bị của nhà máy gỗ để xẻ gỗ thành gỗ thô, cắt gỗ, tạo ván ép và ván dăm rồi gia công gỗ cho giai đoạn sử dụng sau này.', array['- Kiểm tra gỗ thô để xác định kích thước, tình trạng, chất lượng và các đặc điểm khác để quyết định việc cắt gỗ tốt nhất; vận hành thiết bị tự động để truyền các phôi gỗ qua máy quét laser xác định các mẫu cắt có năng suất và lợi nhuận cao nhất;', '- Vận hành và giám sát nhật ký hệ thống cấp liệu và băng chuyền;', '- Vận hành và giám sát các đầu, lưỡi cưa và cưa nhiều lưỡi để cưa gỗ, tách vỏ và loại bỏ các cạnh thô từ gỗ thành gỗ xẻ có kích cỡ khác nhau;', '- Vận hành và giám sát máy đặt lõi gỗ dán, máy ép ván ép nóng và máy cắt gỗ ép;', '- Làm sạch và bôi trơn thiết bị cưa.']::text[], array['- Thợ vận hành máy cưa vòng', '- Thợ vận hành máy cắt gỗ', '- Thợ vận hành máy ép gỗ dán', '- Thợ vận hành máy cưa', '- Thợ vận hành máy cắt xén', '- Thợ vận hành máy tiện gỗ ép', '- Thợ cưa trong nhà máy chế biến gỗ']::text[], array['- Thợ vận hành bể xử lý gỗ - 7521', '- Thợ bảo quản lò sấy gỗ ván - 7521', '- Thợ vận hành máy sản xuất đồ gỗ - 7523']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 726) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8181', 'Thợ vận hành thiết bị sản xuất thủy tinh và gốm vận hành và giám sát các lò nung, lò nấu và các máy móc, thiết bị khác được sử dụng trong sản xuất thủy tinh, gốm, sứ, gạch, ngói; vận hành máy ủ, làm cứng hoặc trang trí thủy tinh và gốm sứ.', array['- Vận hành và giám sát các lò luyện thủy tinh để chế tạo thủy tinh bằng cách nấu chảy và nung chảy các thành phần trộn sẵn;', '- Vận hành thiết bị phun nóng hoặc lạnh để bọc tráng thủy tinh bằng chất làm cứng bề mặt;', '- Vận hành và bảo dưỡng các máy ép hoặc thổi thủy tinh nóng chảy vào các khuôn để tạo thành hình dáng hoặc định hình các vật chứa đựng như chai, lọ, bình vại và ly uống nước;', '- Thao tác ấn tay để đúc thủy tinh thành hình dạng cần thiết;', '- Vận hành lò nung để xử lý thủy tinh nóng chảy thành các tấm kính phẳng;', '- Vận hành và giám sát thiết bị sản xuất thủy tinh nổi;', '- Vận hành và bảo dưỡng máy hoàn thiện để mài, khoan, đánh bóng bằng cát, làm cho xiên góc, trang trí, rửa hoặc đánh bóng thủy tinh và các sản phẩm thủy tinh;', '- Thiết lập và vận hành máy ép để đúc các sản phẩm gốm từ đất sét ẩm;', '- Vận hành máy trộn đất sét với nước để nhào thành một trạng thái mềm dẻo thích hợp hoặc dạng bán lỏng để sản xuất các sản phẩm gốm;', '- Vận hành và giám sát các lò nung gốm, sứ, gạch và ngói;', '- Vận hành và giám sát máy tráng men hoặc mài mòn;', '- Vận hành và giám sát các máy ép đùn thủy tinh nóng chảy để tạo thành sợi thủy tinh;', '- Quan sát các sản phẩm đã hoàn thiện để phát hiện các chỗ nứt, rạn, vỡ, màu sắc và các khiếm khuyết khác.']::text[], array['- Thợ vận hành lò gạch', '- Thợ vận hành máy sơn gốm', '- Thợ vận hành máy trộn đất sét', '- Thợ ép đất sét ép', '- Thợ vận hành lò sản xuất thủy tinh', '- Thợ vận hành máy thổi thủy tinh', '- Thợ vận hành máy trộn thủy tinh', '- Thợ vận hành lò sản xuất thủy tinh', '- Thợ vận hành lò gốm', '- Thợ vận hành lò gạch ngói']::text[], array['- Thợ đúc khuôn gạch ngói - 7314', '- Thợ thổi thủy tinh - 7315', '- Thợ cắt thủy tinh - 7315']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 749) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8182', 'Thợ vận hành động cơ hơi nước và nồi hơi duy trì và vận hành các loại động cơ hơi nước, nồi hơi, tua bin và thiết bị phụ trợ để cung cấp năng lượng và các dịch vụ tiện ích khác cho các tòa nhà thương mại, công nghiệp, khu làm việc, trên tàu hoặc tàu tự hành.', array['- Vận hành, làm sạch, bôi trơn và giám sát động cơ hơi nước, nồi hơi và thiết bị phụ trợ như máy bơm, máy nén, thiết bị điều hòa không khí để cung cấp và duy trì hơi nước và năng lượng cho các tòa nhà, tàu biển hay dụng cụ khí nén;', '- Phân tích và ghi lại các thiết bị đọc, xử lý sự cố, thực hiện các sửa chữa nhỏ để ngăn ngừa lỗi thiết bị hoặc hệ thống;', '- Theo dõi và kiểm tra hiệu suất thiết bị để vận hành hiệu quả và đảm bảo nước lò hơi, hóa chất và nhiên liệu được duy trì ở mức yêu cầu;', '- Đốt lò than bằng thủ công hay bằng nồi hơi được nạp ga hoặc dầu, sử dụng nguồn cấp khí tự động hoặc bơm dầu;', '- Kiểm tra chất lượng nước nồi hơi hoặc sắp xếp để thử nghiệm; điều chỉnh và thực hiện các hành động khắc phục cần thiết như thêm hóa chất để ngăn chặn sự ăn mòn và cặn lắng có hại;', '- Giám sát các chỉ số động cơ, máy móc và thiết bị của tàu; ghi lại các biến số và báo cáo bất thường với nhân viên kỹ thuật đang trực trên tàu;', '- Vận hành và bảo trì các bơm và van chất lỏng không tải.']::text[], array['- Thợ bảo quản nồi hơi', '- Thợ vận hành đầu máy tàu thủy', '- Thợ vận hành máy móc cố định', '- Thợ vận hành động cơ hơi nước', '- Thợ đốt lò']::text[], array['- Kỹ sư tàu thủy - 3151', '- Thợ lắp ráp động cơ cố định - 7233']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 780) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8183', 'Thợ vận hành thiết bị đóng gói, đóng chai và dán nhãn vận hành và giám sát máy cân, đóng gói và dán nhãn sản phẩm hoặc đổ đầy thùng chứa bằng sản phẩm.', array['- Vận hành và giám sát máy cân, bọc, đóng gói và đóng kiện các sản phẩm;', '- Vận hành và giám sát máy làm đầy và đóng kín ống tuýp, chai, lon, hộp, túi và các vật chứa khác bằng các sản phẩm như thực phẩm, đồ uống, sơn, dầu, nước hoa;', '- Vận hành và giám sát máy sản xuất nhãn mác, dán nhãn sản phẩm, bao gói và các thùng hàng khác bằng cách dán hoặc phương pháp khác;']::text[], array['- Thợ làm đầy chai', '- Thợ vận hành máy đóng hộp', '- Thợ vận hành máy dán nhãn', '- Thợ vận hành máy đóng kiện', '- Thợ vận hành máy đóng gói']::text[], array['- Thợ đóng gói bằng tay - 9321']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 799) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8189', 'Thợ vận hành máy móc, thiết bị khác chưa được phân vào đâu có thể nhóm này gồm các nghề vận hành máy móc liên quan sản xuất con chip silicon, nối dây cáp và dây tải điện.', '{}'::text[], array['- Thợ vận hành máy nối dây cáp và dây tải điện', '- Thợ vận hành máy sản xuất con chip silicon']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 813) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8201', 'Thợ lắp ráp máy cơ khí lắp ráp theo các quy trình được đặt ra nghiêm ngặt các bộ phận cấu thành của máy móc cơ khí như động cơ, xe cơ giới, tua bin và máy bay.', array['- Lắp ráp và lắp đặt các bộ phận hoặc linh kiện đúc sẵn để tạo thành các cụm lắp ráp, máy móc cơ khí, động cơ và xe cơ giới đã hoàn thành;', '- Xem xét đơn đặt hàng công việc, thông số kỹ thuật, sơ đồ và bản vẽ để xác định vật liệu cần thiết và hướng dẫn lắp ráp;', '- Ghi dữ liệu sản xuất và vận hành trên các mẫu được chỉ định;', '- Kiểm tra và thử nghiệm các thành phần lắp ráp đã hoàn thành;', '- Từ chối lắp ráp các thành phần bị lỗi.']::text[], array['- Thợ lắp ráp máy bay', '- Thợ lắp ráp băng ghế dự bị (xe tải)', '- Thợ lắp ráp động cơ', '- Thợ cài đặt hộp số', '- Thợ lắp ráp tuabin', '- Thợ lắp ráp xe']::text[], array['- Thợ sửa chữa xe cơ giới - 7231', '- Thợ lắp ráp thiết bị cơ điện - 8202', '- Thợ lắp ráp xe đạp - 8209']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 821) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8202', 'Thợ lắp ráp thiết bị điện và điện tử lắp ráp hoặc sửa đổi theo quy trình đặt ra nghiêm ngặt các thành phần của thiết bị điện, cơ điện và điện tử.', array['- Lắp ráp các bộ phận cấu thành và hệ thống điện, điện tử; định vị, sắp xếp và gắn các bộ phận chính, bộ phận phụ hoặc khung bằng dụng cụ cầm tay hoặc điện, thiết bị hàn và hàn vi mô;', '- Xem xét các đơn đặt hàng công việc, thông số kỹ thuật, sơ đồ và bản vẽ để xác định vật liệu cần thiết và hướng dẫn lắp ráp;', '- Ghi dữ liệu sản xuất và vận hành trên các mẫu được chỉ định;', '- Vận hành máy cuộn dây và cuộn dây gió được sử dụng trong các thiết bị, linh kiện điện như thanh ghi, máy biến thế, dây phần ứng, động cơ điện và máy phát điện;', '- Kiểm tra và thử nghiệm các thành phần lắp ráp đã hoàn thành, lắp đặt dây và mạch điện; từ chối các thành phần lắp ráp bị lỗi.']::text[], array['- Thợ lắp ráp phần cứng', '- Thợ lắp ráp thiết bị điện', '- Thợ lắp ráp thiết bị cơ điện', '- Thợ lắp ráp thiết bị điện tử', '- Thợ khắc bằng axit (bảng mạch in)', '- Thợ lắp ráp điện thoại', '- Thợ lắp ráp ti vi', '- Thợ lắp ráp đồng hồ']::text[], array['- Thợ sản xuất dụng cụ chính xác - 7311', '- Thợ cơ khí và dịch vụ điện tử - 7421']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 840) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8209', 'Thợ lắp ráp chưa được phân vào đâu lắp ráp theo quy trình đặt ra nghiêm ngặt các sản phẩm khác nhau không bao gồm các thành phần điện tử, điện hoặc cơ khí.', array['- Lắp ráp các bộ phận cấu thành; định vị, sắp xếp và gắn các bộ phận chính, bộ phận phụ hoặc khung bằng dụng cụ cầm tay hoặc điện, thiết bị hàn và hàn vi mô;', '- Xem xét các đơn đặt hàng công việc, thông số kỹ thuật, sơ đồ và bản vẽ để xác định vật liệu cần thiết và hướng dẫn lắp ráp;', '- Ghi dữ liệu sản xuất và vận hành trên các mẫu được chỉ định;', '- Kiểm tra và thử nghiệm các thành phần lắp ráp hoàn chỉnh;', '- Từ chối các sản phẩm bị lỗi.']::text[], array['- Thợ lắp ráp đạn dược', '- Thợ lắp ráp xe đạp', '- Thợ làm hộp', '- Thợ lắp ráp cửa', '- Thợ lắp ráp gọng kính mắt', '- Thợ hoàn thiện đồ nội thất (gỗ)', '- Thợ lắp ráp trang sức', '- Thợ lắp ráp dao', '- Thợ lắp ráp sản phẩm da', '- Thợ hoàn thiện hành lý', '- Thợ lắp ráp sản phẩm kim loại (trừ cơ khí)', '- Thợ lắp ráp sản phẩm bìa', '- Thợ lắp ráp bút và bút chì', '- Thợ lắp ráp sản phẩm nhựa', '- Thợ lắp ráp đồ chơi bằng nhựa', '- Thợ lắp ráp sản phẩm cao su', '- Thợ lắp rèm che nắng', '- Thợ lắp ráp sản phẩm dệt may', '- Thợ lắp ráp bình giữ nhiệt', '- Thợ lắp ráp sản phẩm gỗ']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 860) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8311', 'Lái các phương tiện vận chuyển trên đường ray điều khiển hoặc hỗ trợ việc điều khiển các động cơ đầu máy để vận chuyển hành khách và hàng hóa.', array['- Lái xe hoặc hỗ trợ lái xe đầu máy hơi nước, điện hoặc động cơ điêzen;', '- Điều khiển tàu điện ngầm hoặc tàu chở khách trên cao;', '- Điều khiển đầu máy để đẩy toa xe dưới hoặc trên bề mặt của mỏ than và quặng;', '- Theo dõi các mối nguy hiểm, quan sát tín hiệu và đồng hồ đo;', '- Vận hành hệ thống liên lạc để liên lạc với các đoàn tàu và người điều khiển giao thông để đảm bảo vận hành an toàn và lên lịch trình cho các đoàn tàu;', '- Giám sát các lao động khác.']::text[], array['- Người lái đầu máy xe lửa', '- Người lái đường sắt đô thị', '- Người lái tàu hỏa']::text[], array['- Người lái xe điện - 8331', 'Ghi chú:', 'Người lái phương tiện vận hành trên đường sắt cố định tách biệt với tuyến đường công cộng được phân vào nhóm 8311 - lái các phương tiện vận chuyển trên đường ray.', 'Người lái phương tiện vận chuyển hành khách trên đường ray cố định được kết hợp với tuyến đường công cộng được phân vào nhóm 8331 - lái xe buýt và xe điện.']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 895) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8312', 'Nhân viên điều khiển tín hiệu, bẻ ghi và chuyển hướng tàu hỏa phụ trách và bảo vệ các đoàn tàu chở hàng trên suốt chuyến đi; kiểm soát sự di chuyển của giao thông đường sắt bằng tín hiệu vận hành; chuyển đổi đầu máy và tạo thành các đoàn tàu trong sân ga; chuẩn bị tàu để đẩy xe goòng than trong mỏ và kiểm soát sự chuyển động của chúng.', array['- Phụ trách và bảo vệ tàu chở hàng trên suốt chuyến đi;', '- Kiểm soát luồng đèn giao thông qua chỗ giao cắt của tuyến đường bằng việc điều khiển các hiệu lệnh và bẻ ghi từ panen điều khiển hoặc hộp hiệu lệnh;', '- Bẻ ghi và nối các toa xe lửa trong sân ga và đường ray để phù hợp với trình tự bốc dỡ và sắp đặt các toa lại với nhau;', '- Chuẩn bị các đoàn tàu để kéo bằng đầu máy hoặc dây cáp và chỉ dẫn sự chuyển động của chúng dọc theo đường kéo trong mỏ than hoặc quặng;', '- Kiểm tra hệ thống và thiết bị của tàu hỏa như hệ thống điều hòa không khí, sưởi ấm, phanh và mã lực hãm phanh trước khi tàu chạy.']::text[], array['- Người kiểm soát phanh (đường sắt)', '- Người bẻ ghi (đường sắt)', '- Người ra hiệu (đường sắt)']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 913) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8321', 'Lái xe máy điều khiển và chăm sóc xe máy hoặc xe ba bánh để vận chuyển nguyên vật liệu, hàng hóa hoặc hành khách.', array['- Điều khiển và giữ gìn xe máy hoặc xe ba bánh để vận chuyển nguyên vật liệu, hàng hóa và hành khách;', '- Tuân thủ các quy tắc và tín hiệu giao thông;', '- Làm sạch và rửa xe cũng như thực hiện các việc bảo dưỡng và sửa chữa nhỏ;', '- Ghi lại lịch trình quãng đường đi;', '- Phân phát thư tín.']::text[], array['- Người chở hàng bằng mô tô', '- Người lái xe kéo gắn động cơ', '- Người lái xe ba bánh', '- Người lái xe máy', '- Người lái xe máy công nghệ (grabbike…)']::text[], array['- Người lái xe đạp - 9331']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 928) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8322', 'Lái xe con, taxi và xe tải hạng nhẹ điều khiển và chăm sóc xe ô tô và xe tải để chuyển chở hành khách, thư tín và hàng hóa.', array['- Điều khiển và chăm sóc xe tải, xe con hoặc taxi để chở khách;', '- Điều khiển và chăm sóc xe con, xe tải hoặc xe tải nhỏ để phân phát thư tín hoặc hàng hóa;', '- Giúp đỡ hành khách mang hành lý;', '- Thu phí, thanh toán tiền phân phát hàng hóa hoặc tài liệu có giá trị bảo đảm;', '- Vận hành các thiết bị thông tin liên lạc để báo cáo vị trí và sẵn sàng theo sự chỉ dẫn của trung tâm điều hành;', '- Xác định các tuyến đường phù hợp nhất;', '- Hỗ trợ hành khách khuyết tật;', '- Vận hành thiết bị để tạo điều kiện thuận lợi cho hành khách khuyết tật được di chuyển dễ dàng.']::text[], array['- Người lái xe cứu thương', '- Người lái xe ô tô con', '- Người trông bãi đỗ xe', '- Người lái xe taxi', '- Người lái xe tải hạng nhẹ', '- Người lái xe ô tô công nghệ (grabcar…)']::text[], array['- Người lái xe kéo gắn động cơ - 8321', '- Người lái xe buýt - 8331', '- Người lái xe tải hạng nặng - 8332', '- Người lái xe đạp - 9331', '- Người lái xe xích lô - 9331', '- Người lái xe động vật kéo - 9332']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 944) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8331', 'Lái xe buýt và xe điện điều khiển và chăm sóc xe buýt hoặc xe điện để vận chuyển hành khách, thư tín hoặc hàng hóa.', array['Điều khiển và chăm sóc xe buýt, xe điện hoặc xe khách đường dài để chuyên chở hành khách, thư tín, hàng hóa nội tỉnh và liên tỉnh;', 'Điều khiển và chăm sóc xe điện chạy trên đường chuyên chở hành khách;', 'Mở và đóng cửa trước hoặc sau khi hành khách lên hoặc xuống xe;', 'Giúp đỡ hành khách mang hành lý;', 'Kiểm tra ánh sáng, sưởi ấm và hệ thống thông gió trên xe buýt và xe điện;', 'Quan sát giao thông để đảm bảo an toàn;', 'Thu phí hoặc kiểm tra vé.']::text[], array['- Người lái xe buýt', '- Người lái xe khách', '- Người lái xe điện']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 972) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8332', 'Lái xe tải hạng vừa và xe tải hạng nặng điều khiển và chăm sóc xe tải hạng vừa và hạng nặng để vận chuyển hàng hóa, chất lỏng và vật liệu nặng trên các quãng đường ngắn hoặc dài.', array['Điều khiển và chăm sóc xe tải hạng vừa, hạng nặng như xe tải có hoặc không có rơ moóc hoặc xe tải tự đổ để vận chuyển hàng hóa, chất lỏng hoặc vật liệu nặng trên các quãng đường ngắn hoặc dài;', 'Xác định các tuyến đường thích hợp nhất;', 'Đảm bảo hàng hóa được xếp gọn và che phủ an toàn để tránh mất mát và hư hỏng;', 'Hỗ trợ hoặc thực hiện việc xếp hoặc dỡ hàng, sử dụng các thiết bị nâng khác nhau;', 'Thực hiện việc bảo dưỡng nhỏ cho xe và sắp xếp bảo dưỡng, sửa chữa lớn;', 'Ước tính trọng lượng để tuân thủ giới hạn tải và đảm bảo trọng lượng an toàn.']::text[], array['- Người lái xe trộn bê tông', '- Người lái xe chở rác', '- Người lái xe tải hạng nặng', '- Người lái tàu đường bộ', '- Người lái xe tải vận chuyển các loại hóa chất']::text[], array['- Người lái xe tải hạng nhẹ - 8322']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 986) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8341', 'Thợ vận hành thiết bị nông nghiệp và lâm nghiệp điều khiển, vận hành và giám sát một hoặc nhiều loại máy móc, thiết bị di động chuyên dùng cho các hoạt động nông, lâm nghiệp.', array['- Điều khiển máy móc nông nghiệp đầu kéo hoặc tự hành để cày xới đất, gieo hạt, bón phân, canh tác và thu hoạch mùa màng;', '- Điều khiển máy móc lâm nghiệp đầu kéo hoặc tự hành để dọn đất, trồng, thu hoạch cây và gỗ hoặc thực hiện các hoạt động lâm nghiệp khác;', '- Chuẩn bị và định vị máy móc để vận hành;', '- Điều chỉnh tốc độ, độ cao, độ sâu của dụng cụ,', '- Vận hành phụ tùng để nâng, xoay, nhả, phân loại cây và gỗ; vận hành máy phụ trợ như máy băm, máy tách gỗ;', '- Đưa cây bị đốn vào máy xử lý tước cành và cắt thành khúc gỗ rồi chất trong kho dự trữ hoặc lên xe tải;', '- Bảo dưỡng máy móc và thực hiện sửa chữa nhỏ.']::text[], array['- Thợ vận hành máy gặt đập', '- Thợ vận hành nhà máy khai thác gỗ', '- Lái xe vận chuyển gỗ', '- Người lái máy kéo', '- Thợ vận hành máy đốn cây']::text[], array['- Thợ vận hành xe ủi - 8342']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1006) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8342', 'Thợ vận hành máy đào đất và thợ vận hành thiết bị có liên quan vận hành máy để đào, san bằng, làm cho mịn và nhỏ đất hoặc các vật liệu tương tự.', array['- Vận hành và giám sát máy đào, máy ủi, máy xúc có gầu để đào và di chuyển đất, đá, cát, sỏi hoặc các vật liệu tương tự;', '- Vận hành và giám sát máy đào mương rãnh cho cống rãnh, hệ thống thoát nước, dầu, khí ga hoặc các đường ống tương tự;', '- Vận hành và giám sát máy móc được trang bị lưỡi lõm bằng thép để di chuyển, phân phối và san bằng mặt đất, cát, tuyết và các vật liệu khác;', '- Vận hành và giám sát thiết bị để loại bỏ cát, sỏi và bùn từ đáy nước;', '- Vận hành và giám sát các máy móc để đóng cọc gỗ, bê tông hoặc thép xuống nền đất;', '- Vận hành và giám sát xe lu để làm cho đất chắc, mịn trong khi làm đường, vỉa hè và các công việc tương tự;', '- Vận hành và giám sát máy trải và làm mịn bê tông hoặc nhựa đường hoặc các chế phẩm bitum để xây dựng đường hoặc các bề mặt tương tự;', '- Giám sát các lao động khác.']::text[], array['- Thợ vận hành xe ủi', '- Thợ vận hành máy xúc', '- Thợ vận hành máy xúc kiểu gàu lật ra sau', '- Thợ vận hành máy đóng cọc', '- Thợ vận hành xe lu', '- Thợ vận hành máy san mặt đường', '- Thợ vận hành máy cào tuyết']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1024) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8343', 'Thợ vận hành cần trục và thợ vận hành các thiết bị có liên quan vận hành và giám sát cần cẩu cố định hoặc di động và các thiết bị cẩu khác.', array['Vận hành và giám sát cần cẩu cố định hoặc di động bằng cách nâng và hạ cần cẩu và cần cẩu để nâng, di chuyển, định vị hoặc đặt thiết bị và vật liệu;', 'Vận hành và giám sát thiết bị để nâng lên, hạ xuống công nhân và nguyên vật liệu trên các công trường xây dựng hoặc trong các mỏ;', 'Vận hành và giám sát các thang kéo để kéo hoặc mang người trượt tuyết tới một đường dốc và các thiết bị tương tự;', 'Vận hành và giám sát các máy được sử dụng để chuyên chở phà hoặc xà lan chở hàng hóa, hành khách và các phương tiện qua các đoạn nước ngắn trên sông;', 'Vận hành và giám sát máy để mở, đóng cầu cho giao thông đường bộ và đường thủy;', 'Vận hành và giám sát các thiết bị cần trục được trang bị bộ phận nạo vét để nạo vét đường thủy và các khu vực khác;', 'Vận hành cần trục được gắn trên thuyền hoặc xà lan để nâng, di chuyển, đặt các vật liệu và thiết bị;', 'Thực hiện các công việc có liên quan;', 'Giám sát các lao động khác.']::text[], array['- Thợ vận hành cáp treo', '- Thợ vận hành cần cẩu', '- Thợ vận hành máy cuộn dây kéo', '- Thợ vận hành máy tời', '- Thợ vận hành lồng quặng', '- Thợ vận hành các thang máy trượt tuyết']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1043) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8344', 'Thợ vận hành xe bốc dỡ điều khiển, vận hành và giám sát xe bốc dỡ hoặc các phương tiện tương tự để vận chuyển, nâng và chất hàng hóa lên tấm nâng.', array['- Điều khiển và giám sát xe bốc dỡ và các thiết bị tương tự để xếp, dỡ, vận chuyển, nâng hàng hóa và các tấm nâng hàng ở nhà ga, bến tàu, bến cảng, kho hàng, nhà máy và các cơ sở khác;', '- Bố trí các thiết bị nâng dưới, trên hoặc xung quanh tấm nâng đã được xếp và bảo vệ vật liệu hoặc sản phẩm an toàn cho việc vận chuyển đến khu vực được chỉ định;', '- Kiểm tra thiết bị để xác định hao mòn và thiệt hại;', '- Thực hiện bảo dưỡng định kỳ các thiết bị và phương tiện;', '- Lưu giữ hồ sơ công việc đã thực hiện và sự hỏng hóc của máy.']::text[], array['- Người lái xe nâng']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1062) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('8350', 'Thủy thủ trên tàu và những thợ có liên quan (trừ lao động trên tàu đánh bắt thủy sản) thực hiện các nhiệm vụ trên boong tàu và các nhiệm vụ tương tự trên các phương tiện tàu thuyền khác.', array['- Đứng quan sát trên biển và khi ra vào bến tàu, bến cảng hoặc vùng nước hẹp khác;', '- Lái tàu theo sự hướng dẫn;', '- Xử lý dây thừng, dây kim loại và vận hành các thiết bị neo đậu;', '- Bảo dưỡng và trong một vài trường hợp vận hành các thiết bị tàu thuyền, thiết bị chở hàng hóa, thiết bị cứu hộ và chữa cháy;', '- Thực hiện các công việc làm sạch, cạo, sơn boong tàu, thân tàu và các nhiệm vụ bảo dưỡng khác theo yêu cầu;', '- Sửa soạn, sắp xếp hàng hóa đóng gói lên tàu, trang bị thiết bị xử lý hàng hóa.']::text[], array['- Thuyền trưởng', '- Chèo phà bằng tay', '- Thủy thủ', '- Kéo lưới bằng tay']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1075) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9111', 'Người quét dọn và giúp việc gia đình quét dọn, hút bụi, lau rửa, đánh bóng sàn nhà, đồ nội thất, cửa sổ và đồ đạc khác; chăm sóc đồ vải gia dụng, mua sắm các đồ dùng gia đình; chuẩn bị thức ăn, dọn bàn ăn và thực hiện các nhiệm vụ khác trong nhà.', array['- Quét dọn, hút bụi, đánh bóng, lau rửa sàn nhà, đồ nội thất hoặc lau cửa sổ và đồ đạc khác;', '- Giặt, là và vá vải lanh và các vải dệt khác;', '- Rửa bát đĩa;', '- Giúp chuẩn bị, nấu ăn và phục vụ các bữa ăn, đồ uống;', '- Mua thực phẩm và các đồ dùng gia đình khác;', '- Lau chùi, tẩy uế, khử mùi nhà bếp, phòng tắm và nhà vệ sinh;', '- Làm sạch cửa sổ và các bề mặt kính khác.']::text[], array['- Người ở (trong gia đình)', '- Người quét dọn gia đình', '- Người giúp việc gia đình']::text[], array['- Quản gia - 5152', '- Người dọn dẹp khách sạn - 9112', '- Thợ giặt là bằng tay - 9121', '- Người quét dọn đường phố - 9613']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1098) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9112', 'Người quét dọn và giúp việc trong văn phòng, khách sạn và các cơ sở khác thực hiện các nhiệm vụ lau dọn khác nhau để giữ sạch sẽ, gọn gàng nội thất, đồ đạc của khách sạn, văn phòng và các cơ sở khác cũng như máy bay, tàu hỏa, xe buýt và các phương tiện tương tự.', array['- Quét hoặc hút bụi, rửa, đánh bóng sàn nhà, đồ nội thất và đồ đạc khác trong tòa nhà, xe khách, xe buýt, tàu điện, tàu hỏa và máy bay;', '- Dọn giường, vệ sinh phòng tắm, cung cấp khăn tắm, xà phòng và các đồ có liên quan;', '- Lau chùi phòng bếp và giúp đỡ các công việc bếp núc bao gồm cả việc rửa bát;', '- Nhặt rác, đổ rác ra khu đổ quy định.']::text[], array['- Người dọn dẹp máy bay', '- Người dọn dẹp khách sạn', '- Người dọn dẹp phòng vệ sinh', '- Người dọn dẹp văn phòng']::text[], array['- Quản gia - 5152', '- Người chăm sóc tòa nhà - 5153', '- Người quét dọn gia đình - 9111', '- Người rửa bát - 9402', '- Người phụ bếp - 9402', '- Người quét dọn đường phố - 9613', 'Ghi chú:', 'Người lao động thực hiện công việc vệ sinh và phụ giúp trong nhà bếp và chuẩn bị thực phẩm khác được phân vào nhóm 9402 - Người phụ bếp.']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1117) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9121', 'Thợ giặt là bằng tay giặt, là khô bằng tay vải lanh và các vải dệt khác.', array['- Giặt và là bằng tay vải lanh, quần áo, vải và các mặt hàng tương tự trong tiệm giặt là hoặc các cơ sở khác;', '- Làm sạch bằng tay với dung dịch hóa chất cho quần áo, vải, hàng da và các đồ tương tự trong các tiệm giặt khô hoặc các cơ sở khác;', '- Thay các khuy áo và thực hiện các việc sửa chữa nhỏ;', '- Đặt các đồ lên giá và treo các đồ để trả và nhận hàng.']::text[], array['- Thợ giặt khô (bằng tay)', '- Thợ giặt bằng tay', '- Thợ là bằng bàn là cầm tay', '- Thợ ủi']::text[], array['- Thợ vận hành máy giặt khô - 8157', '- Thợ vận hành máy giặt - 8157', '- Thợ vận hành máy là ủi - 8157']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1141) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9122', 'Thợ rửa xe cộ rửa, làm sạch, đánh bóng bên ngoài và nội thất của xe.', array['- Làm sạch, rửa, đánh bóng xe ô tô và các phương tiện khác bằng tay hoặc sử dụng các dụng cụ điện cầm tay;', '- Hút bụi bên trong xe, xì khô thảm và vải bọc ghế;', '- Sử dụng các chất tẩy rửa để loại bỏ vết bẩn ở trong và ngoài xe;', '- Rửa lốp xe, vòm bánh xe và bôi đen lốp xe;', '- Rửa và đánh bóng cửa sổ của xe;', '- Đổ và làm sạch khoang trong xe.']::text[], array['- Thợ chăm sóc xe ô tô con', '- Thợ rửa xe (bằng tay)']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1157) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9123', 'Thợ làm sạch cửa sổ lau rửa, đánh bóng cửa sổ và các phụ kiện thủy tinh khác.', array['- Lau rửa cửa sổ và các bề mặt kính khác bằng nước hoặc các dung dịch tẩy rửa, làm khô và đánh bóng chúng;', '- Sử dụng thang, xích đu, ghế, xe téc chở nước và các thiết bị khác để tiếp cận và làm sạch cửa sổ trong các tòa nhà cao tầng;', '- Lựa chọn dụng cụ vệ sinh hoặc đánh bóng thích hợp.']::text[], array['- Thợ lau cửa sổ']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1169) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9129', 'Thợ lau dọn khác làm sạch bề mặt, vật liệu và các đồ vật khác như thảm, tường, bể bơi, tháp làm lạnh bằng việc sử dụng các thiết bị và hóa chất tẩy rửa chuyên dụng.', array['- Làm sạch thảm, đồ nội thất bọc bằng việc sử dụng máy làm sạch và các phụ kiện của chúng;', '- Lựa chọn và sử dụng các chất tẩy để loại bỏ vết bẩn trên thảm;', '- Xử lý thảm với các hóa chất và các chất khử mùi không thấm nước; xử lý các sâu bọ bám trên thảm;', '- Làm sạch tường đá, bề mặt kim loại, các băng dải bằng chất tẩy rửa và dung môi nước áp lực cao;', '- Sử dụng hóa chất và phương pháp làm sạch áp suất lớn để loại bỏ vi sinh vật khỏi nước và hệ thống lọc nước;', '- Sử dụng máy hút bẩn và các thiết bị hút khác để loại bỏ chất bẩn tích tụ, cặn từ bể bơi, tháp làm lạnh, cống dẫn nước.']::text[], array['- Người giặt thảm', '- Thợ vệ sinh tháp làm lạnh', '- Thợ lau chùi tường đá', '- Người vệ sinh bể bơi', '- Người lau dọn máy phun nước']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1177) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9201', 'Lao động trồng trọt thực hiện nhiệm vụ đơn giản và thường xuyên tại các trang trại liên quan sản xuất cây trồng như hoa quả, hạt, ngũ cốc và rau củ.', array['- Đào và nạo vét để làm sạch mương hay cho mục đích khác;', '- Bốc xếp vật tư, sản phẩm và nguyên liệu khác;', '- Xếp loại, lựa chọn và chất rơm, cỏ khô và nguyên liệu khác;', '- Tưới nước, tỉa thưa, làm cỏ bằng tay hoặc sử dụng dụng cụ cầm tay;', '- Hái hoa quả, hạt, rau và cây trồng khác;', '- Trồng và thu hoạch cây mùa vụ như lúa bằng tay;', '- Phân loại, sắp xếp, bó, đóng gói sản phẩm vào thùng hàng;', '- Thực hiện sửa chữa nhỏ trên đồ đạc, tòa nhà, thiết bị và hàng rào.']::text[], array['- Người trồng mía', '- Người hái hoa quả', '- Lao động trồng lúa', '- Người hái rau']::text[], array['- Công nhân trang trại có kỹ năng (trồng trọt) - 6111', '- Lao động xây dựng (xây dựng tòa nhà) - 9313', '- Người thu gom củi - 9624', '- Người thu gom nước - 9624']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1197) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9202', 'Lao động chăn nuôi thực hiện nhiệm vụ đơn giản và thường xuyên tại trang trại về chăn nuôi gồm cả gia cầm và côn trùng.', array['- Đào và nạo vét để làm sạch mương hay cho mục đích khác;', '- Bốc xếp vật tư, sản phẩm và nguyên liệu khác;', '- Cho ăn, uống nước, tắm rửa cho vật nuôi và vệ sinh chuồng sạch sẽ;', '- Theo dõi vật nuôi và báo cáo tình trạng của chúng;', '- Hỗ trợ bảo đảm sức khỏe và phúc lợi của vật nuôi;', '- Hỗ trợ chăn gia súc, phân loại gia súc theo mục đích lấy sữa, xén lông, vận chuyển, lấy thịt;', '- Nhặt trứng và xếp vào lồng ấp;', '- Cào, ném, xếp, lưu trữ cỏ khô, rơm và các loại thức ăn chăn nuôi khác;', '- Phân loại, sắp xếp, bó, đóng gói sản phẩm vào thùng hàng;', '- Thực hiện các sửa chữa nhỏ trên đồ đạc, tòa nhà, thiết bị và hàng rào.']::text[], array['- Lao động chăn nuôi gia súc']::text[], array['- Nông dân chăn trâu, bò - 6121', '- Nông dân chăn cừu - 6121', '- Công nhân chăn nuôi có kỹ năng (gia súc) - 6121', '- Người thu gom củi - 9624', '- Người thu gom nước - 9624']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1218) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9203', 'Lao động trồng trọt và chăn nuôi hỗn hợp thực hiện nhiệm vụ đơn giản và thường xuyên tại nông trại cả về trồng trọt và chăn nuôi.', array['- Đào và nạo vét để làm sạch mương hay cho mục đích khác;', '- Bốc xếp vật tư, sản phẩm và nguyên liệu khác;', '- Xếp loại, lựa chọn và chất rơm, cỏ khô và nguyên liệu tương tự;', '- Tưới nước, tỉa thưa, làm cỏ bằng tay hoặc sử dụng dụng cụ cầm tay;', '- Hái hoa quả, hạt, rau, cây trồng khác và nhặt trứng;', '- Trồng và thu hoạch cây mùa vụ như lúa bằng tay;', '- Cho động vật ăn, tắm rửa và vệ sinh chuồng;', '- Theo dõi vật nuôi và báo cáo tình trạng của chúng;', '- Hỗ trợ bảo đảm thể trạng và phúc lợi súc vật;', '- Hỗ trợ chăn thả vật nuôi, phân loại gia súc theo mục đích lấy sữa, xén lông, vận chuyển, lấy thịt;', '- Phân loại, sắp xếp, bó, đóng gói sản phẩm vào thùng hàng;', '- Thực hiện các sửa chữa nhỏ trên đồ đạc, tòa nhà, thiết bị và hàng rào.']::text[], array['- Lao động nông trại']::text[], array['- Công nhân nông nghiệp có kỹ năng (trang trại hỗn hợp) - 6130', '- Người thu gom củi - 9624', '- Người thu gom nước - 9624']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1239) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9204', 'Lao động làm vườn thực hiện nhiệm vụ đơn giản và thường xuyên để chăm sóc, duy trì cây, bụi, hoa và các loại cây khác trong công viên hay vườn nhà; sản xuất cây con, củ, giống; trồng rau và hoa bằng kỹ thuật thâm canh.', array['- Xếp, dỡ, di chuyển vật tư, sản phẩm và nguyên liệu khác;', '- Chuẩn bị các khu vườn và mảnh đất bằng dụng cụ cầm tay hoặc máy móc đơn giản;', '- Hỗ trợ trồng và cấy ghép hoa, bụi, cây, cỏ;', '- Duy trì vườn thông qua việc tưới nước, nhổ cỏ dại, cắt cỏ;', '- Làm sạch vườn và nhặt rác;', '- Hỗ trợ nhân giống, trồng, ươm hạt, củ và giâm cành;', '- Chăm sóc cây bằng cách tưới nước, nhổ cỏ bằng tay;', '- Thu hoạch và đóng gói cây cảnh để bán và chuyên chở;', '- Thực hiện các sửa chữa nhỏ trên đồ đạc, tòa nhà, thiết bị và hàng rào.']::text[], array['- Lao động làm vườn', '- Thợ cắt cỏ', '- Lao động tại vườn ươm']::text[], array['- Người làm vườn - 6113', '- Người chăm sóc cảnh quan - 6113', '- Lao động trồng trọt - 9201']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1260) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9205', 'Lao động lâm nghiệp thực hiện nhiệm vụ đơn giản, thường xuyên để trồng trọt và chăm sóc rừng tự nhiên và rừng trồng; khai thác, đốn hạ và cưa cây.', array['- Đào hố trồng cây;', '- Chất và xếp gỗ;', '- Loại bỏ bụi rậm tại vùng đất rừng và tỉa thưa rừng trồng;', '- Duy trì cảnh báo cháy rừng;', '- Chặt bỏ cành chính và ngọn cây; tỉa cành và cưa thân cây thành khúc gỗ;', '- Vận hành và bảo dưỡng máy cưa bằng tay hoặc bằng máy để chặt cây, cành đã đốn thành các khúc gỗ;', '- Thu thập hạt giống và trồng cây con;', '- Thực hiện các sửa chữa nhỏ và bảo trì đường rừng, tòa nhà, thiết bị và cơ sở.']::text[], array['- Tiều phu', '- Lao công lâm nghiệp', '- Lao động trồng cây']::text[], array['- Lao động có kỹ năng trong lâm nghiệp - 6210']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1280) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9206', 'Lao động thủy sản thực hiện nhiệm vụ đơn giản và thường xuyên để nuôi trồng, đánh bắt, thu hoạch cá, hải sản trong lĩnh vực nuôi trồng và tiến hành khai thác thủy sản nội địa, ven biển và xa bờ.', array['- Làm sạch khu nuôi trồng cá và động vật thân mềm;', '- Thu thập rong biển, rêu biển, trai và các động vật thân mềm khác;', '- Chuẩn bị lưới, dây, dụng cụ đánh cá và các thiết bị trên boong tàu;', '- Vận hành ngư cụ để đánh bắt cá và sinh vật biển khác;', '- Làm sạch, phân loại, đóng gói cá, hải sản ướp lạnh và muối;', '- Làm sạch bề mặt boong tàu và khoang chứa cá;', '- Xử lý dây neo khi cập bến.']::text[], array['- Lao động nuôi trồng thủy sản', '- Lao động ngư nghiệp']::text[], array['- Nông dân nuôi cá - 6221', '- Đội trưởng khai thác cá trong nội địa - 6222', '- Ngư dân (vùng nước trong nội địa) - 6222', '- Ngư dân khai thác trong vùng biển Việt Nam - 6223']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1297) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9311', 'Lao động trong khai thác mỏ và khai thác đá thực hiện các nhiệm vụ thường xuyên trong hoạt động khai thác mỏ than, đá quặng.', array['- Hỗ trợ thợ khai thác than, khai thác đá trong việc bảo dưỡng máy móc, thiết bị và lắp đặt hầm mỏ;', '- Lắp ráp và tháo dỡ thiết bị khai khoáng;', '- Loại bỏ các giá đỡ đường hầm khỏi các công trình không sử dụng trong các mỏ và đá;', '- Loại bỏ các dự báo nguy hiểm từ công việc khai thác mỏ và đá;', '- Loại bỏ chất thải, vật liệu và thiết bị có thể sử dụng được ra khỏi khu làm việc sau khi các hoạt động khai thác đã hoàn thành; dọn sạch đất đá và khoáng sản tràn ra;', '- Làm sạch máy móc, thiết bị, dụng cụ, lối đi và đường vận chuyển;', '- Phân loại, xếp, dỡ, chất đống và lưu kho dụng cụ, vật liệu và nguyên liệu được thợ khai thác mỏ sử dụng.']::text[], array['- Lao động khai thác mỏ', '- Lao động khai thác đá']::text[], array['- Thợ vận hành máy khoan (khai thác) - 8111', '- Thợ mỏ - 8111', '- Thợ vận hành nhà máy khai thác - 8111', '- Thợ khai thác mỏ đá - 8111', '- Thợ khoan (giếng dầu hoặc khí ga) - 8113', '- Thợ điều hành nhà máy khoan - 8113']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1321) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9312', 'Lao động trong xây dựng công trình kỹ thuật (không phải nhà) thực hiện các công việc thường xuyên liên quan đến việc xây dựng và bảo trì đường bộ, đường sắt, đập nước và các công trình tương tự.', array['Đào, lấp các hố, mương, rãnh bằng các công cụ cầm tay;', 'Xúc, rải sỏi và các vật liệu liên quan;', 'Xén và cắt đá, bề mặt bê tông, bitum bằng búa kích;', 'Bốc dỡ vật liệu xây dựng, thiết bị đào và vận chuyển chúng xung quanh công trường bằng xe cút kít và xe nâng tay;', 'Làm sạch khu vực làm việc và loại bỏ phế thải;']::text[], array['- Lao động xây dựng (công trình dân dụng)', '- Lao động làm đất', '- Lao động bảo trì (đập nước)']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1341) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9313', 'Thợ phụ xây dựng tiến hành nhiệm vụ thường xuyên liên quan đến xây dựng và phá hủy công trình.', array['- Làm sạch gạch xây dựng đã qua sử dụng và thực hiện công việc đơn giản khác trên địa điểm phá dỡ công trình;', '- Trộn, đổ và rải vật liệu như bê tông, thạch cao và vữa;', '- Đào và lấp hố, mương bằng dụng cụ cầm tay;', '- Rải cát, đất, sỏi và vật liệu tương tự;', '- Bốc dỡ vật liệu xây dựng, vật liệu và dụng cụ đào rồi vận chuyển chúng xung quanh công trường xây dựng bằng xe cút kít, xe cuốc và xe nâng tay;', '- Dọn công trường và loại bỏ phế liệu.']::text[], array['- Hỗ trợ thợ nề', '- Lao động xây dựng (xây dựng công trình tòa nhà)', '- Lao động phá dỡ', '- Lao động chuyển thúng gạch']::text[], array['- Thợ xây nhà - 7111', '- Thợ nề - 7112', '- Thợ phá dỡ công trình - 7119']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1353) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9321', 'Lao động đóng gói thủ công cân, đóng gói và dán nhãn các vật liệu, sản phẩm bằng tay.', array['- Cân, bao gói, niêm phong, đóng kiện vật liệu, sản phẩm bằng tay;', '- Đóng chai, lon, hộp, túi và vật chứa khác đựng sản phẩm bằng tay;', '- Dán nhãn sản phẩm, bao bì và vật chứa khác bằng tay.']::text[], array['- Lao động dán nhãn (bằng tay)', '- Lao động đóng kiện (bằng tay)', '- Lao động đóng gói (bằng tay)']::text[], array['- Thợ vận hành máy dán nhãn - 8183', '- Thợ vận hành máy đóng kiện - 8183', '- Thợ vận hành máy đóng gói - 8183']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1374) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9329', 'Lao động công nghiệp khác chưa được phân vào đâu hỗ trợ vận hành, lắp ráp máy móc và thực hiện nhiều công việc thủ công, đơn giản, thường ngày trong quá trình sản xuất trừ đóng gói và dán nhãn thành phẩm.', array['- Chuyên chở hàng hóa, vật liệu, thiết bị, các vật dụng khác đến khu làm việc và loại bỏ các thành phẩm;', '- Chất và dỡ hàng trên xe tải và xe đẩy;', '- Thông tắc nghẽn máy móc; làm sạch máy móc, thiết bị, dụng cụ;', '- Tiến hành phân loại sản phẩm và các bộ phận của sản phẩm bằng thủ công.']::text[], array['- Lao động phân loại chai', '- Lao động phụ nhà máy', '- Lao động xử lý vật liệu', '- Lao động bốc xếp']::text[], array['- Thợ lắp ráp thiết bị điện - 8202', '- Thợ lắp ráp thiết bị điện tử - 8202', '- Thợ lắp ráp sản phẩm da - 8209', '- Thợ lắp ráp sản phẩm cao su - 8209', '- Lao động đóng gói thủ công - 9321']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1388) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9331', 'Lái xe bằng tay và đạp chân đẩy xe và các xe tương tự để vận chuyển hành khách và hàng hóa.', array['- Xếp dỡ hàng hóa hoặc hỗ trợ hành khách lên và xuống xe;', '- Điều khiển phương tiện di chuyển theo hướng mong muốn và tuân theo quy định của giao thông;', '- Kiểm tra các bộ phận của xe để xác định hao mòn và hư hỏng;', '- Bảo dưỡng xe, thực hiện các công việc sửa chữa nhỏ và lắp đặt các bộ phận thay thế;', '- Thu tiền vé hoặc phí.']::text[], array['- Người chuyển phát bằng xe đạp', '- Người đạp xích lô', '- Người lái xe đạp', '- Người lái xe kéo']::text[], array['- Vận động viên đua xe đạp - 3421', '- Người lái xe máy - 8321']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1409) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9332', 'Người điều khiển máy kéo và phương tiện do gia súc kéo chuyên chở người và hàng hóa ra cánh đồng.', array['Buộc gia súc vào xe cơ giới hoặc xe có động cơ;', 'Xếp dỡ hàng hóa hoặc hỗ trợ người lên hoặc xuống xe;', 'Điều khiển gia súc theo hướng mong muốn và tuân thủ các quy tắc giao thông;', 'Thu tiền vé hoặc phí;', 'Điều khiển gia súc để đẩy xe goòng trong mỏ than hoặc quặng;', 'Điều khiển gia súc tới nông trại hoặc máy móc khác;', 'Điều khiển voi làm việc;', 'Bảo dưỡng phương tiện hoặc máy móc, thực hiện công việc sửa chữa nhỏ và lắp đặt các bộ phận thay thế;', 'Chải lông và cho gia súc ăn.']::text[], array['- Người lái xe động vật kéo', '- Người lái tàu động vật kéo', '- Quản tượng']::text[], array['- Người đua ngựa - 3421']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1425) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9333', 'Người mang vác hàng thực hiện nhiệm vụ như đóng gói, mang vác, bốc xếp đồ đạc và các vật dụng gia đình hoặc xếp dỡ hàng hóa lên tàu, máy bay; chuyển và xếp hàng hóa trong các kho hàng khác nhau.', array['Đóng gói đồ đạc văn phòng hoặc gia đình, máy móc, thiết bị và hàng hóa liên quan để vận chuyển từ nơi này đến nơi khác;', 'Vận chuyển đến một nơi khác;', 'Mang hàng hóa đã được bốc dỡ hoặc bốc xếp từ xe tải, toa xe, tàu thuyền hoặc máy bay;', 'Bốc dỡ và bốc xếp ngũ cốc, than, cát, hành lý và các hàng hóa tương tự bằng việc đặt chúng lên băng tải, đường ống và các phương tiện vận chuyển khác;', 'Nối các ống giữa các đường ống lắp đặt trên bờ và các bồn chứa của sà lan, tàu chở dầu và các tàu khác để bốc dỡ dầu mỏ, khí hóa lỏng và chất lỏng khác;', 'Chuyển, xếp hàng hóa trong kho và trong các cơ sở tương tự;', 'Phân loại hàng hóa trước khi xếp và dỡ hàng;', 'Giám sát các lao động khác.']::text[], array['- Người xử lý hành lý', '- Người vận chuyển hàng hóa', '- Người khuân vác kho']::text[], array['- Người vận hành cần cẩu - 8343', '- Người lái xe nâng - 8344', '- Người khuân vác ở khách sạn - 9621', '- Người khuân vác hành lý - 9621']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1443) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9334', 'Người bày hàng lên giá bày hàng trên các kệ, giá, các khu vực trưng bày và giữ chúng sạch sẽ, ngăn nắp trong các siêu thị, trong các cửa hàng bán buôn và bán lẻ khác.', array['Xếp hàng hóa gọn gàng trong các thùng, trên các giá và xếp hàng hóa cồng kềnh trên sàn nhà;', 'Xếp kín hàng hóa lên các kệ và đảm bảo hàng hóa có hạn sử dụng sớm nhất ở phía trước kệ;', 'Loại bỏ hàng hóa quá hạn sử dụng;', 'Bảo dưỡng kệ hàng bằng việc di chuyển hàng trong kho đến một vị trí khác;', 'Ghi chép những hàng hóa đã được bán và lấy hàng hóa cần thiết từ kho hàng;', 'Lấy các sản phẩm cho khách hàng từ kệ hoặc trong kho chứa hàng;', 'Hướng dẫn cho khách hàng vị trí hàng hóa;', 'Nhận, mở và kiểm tra hàng hóa hư hỏng từ nhà sản xuất hoặc nhà phân phối.']::text[], array['- Người bày hàng ban đêm', '- Người xếp hàng trong kho', '- Người xử lý kho']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1463) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9401', 'Người chuẩn bị đồ ăn nhanh chuẩn bị một số ít nguyên liệu, nấu và pha chế các thức ăn, đồ uống đơn giản. Họ có thể nhận đơn đặt hàng của khách hàng và phục vụ tại quầy hoặc bàn.', array['- Chuẩn bị món ăn, đồ uống đơn giản hoặc chế biến sẵn như bánh mỳ kẹp, pizza, khoai tây chiên, salad và cà phê;', '- Rửa, thái, đong và trộn thực phẩm để nấu;', '- Sử dụng thiết bị nấu ăn như lò nướng, lò vi sóng, nồi chiên, vỉ nướng...;', '- Hâm nóng lại thức ăn đã chuẩn bị trước;', '- Làm sạch khu vực chuẩn bị thực phẩm, khu vực và dụng cụ nấu ăn;', '- Nhận và phục vụ món ăn, đồ uống tại các địa điểm ăn uống chuyên phục vụ nhanh và thức ăn mang theo;', '- Đặt hàng và giao các nguyên liệu làm đồ ăn nhanh;', '- Đảm bảo tiêu chuẩn vệ sinh, sức khỏe và an toàn tại khu vực làm việc;', '- Đảm bảo thực phẩm chế biến sẵn đáp ứng yêu cầu về lượng và chất.']::text[], array['- Đầu bếp món ăn nhanh', '- Thợ làm hamburger', '- Thợ làm pizza', '- Người phục vụ đồ ăn nhanh']::text[], array['- Đầu bếp trưởng - 3434', '- Đầu bếp - 5120', '- Nhân viên phục vụ đồ ăn uống - 5246', 'Ghi chú:', 'Các công việc kết hợp chuẩn bị các món ăn đơn giản với việc nhận đơn đặt hàng, phục vụ khách hàng, tính toán hoặc nhận thanh toán được phân vào nhóm 5246 - Nhân viên phục vụ đồ ăn uống trừ khi phục vụ khách hàng là một thành phần phụ của công việc.']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1486) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9402', 'Người phụ bếp dọn bàn, dọn dẹp khu vực bếp, rửa bát, chuẩn bị nguyên liệu và thực hiện các nhiệm vụ khác để hỗ trợ đầu bếp chuẩn bị hoặc phục vụ đồ ăn, thức uống.', array['- Làm sạch nhà bếp, khu vực chuẩn bị thực phẩm và khu vực phục vụ đồ ăn;', '- Hỗ trợ đầu bếp, bếp trưởng chuẩn bị thực phẩm bằng cách việc rửa, gọt, chặt, thái, đong và trộn nguyên liệu;', '- Tập hợp các món ăn để phục vụ;', '- Mở gói, kiểm tra, chuyển, cân và lưu trữ nguyên liệu trong tủ lạnh, tủ đựng và các khu vực lưu trữ khác;', '- Rửa bát đĩa, dụng cụ nấu ăn rồi cất chúng;', '- Chuẩn bị, nấu nướng, hâm nóng món ăn đơn giản.']::text[], array['- Người rửa bát bằng tay', '- Người phụ bếp', '- Người khuân vác phòng bếp', '- Người quản lý bếp ăn', '- Người phục vụ thức ăn']::text[], array['- Đầu bếp - 5120', '- Người chuẩn bị đồ ăn nhanh - 9401']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1509) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9510', 'Lao động trên đường phố và lao động có liên quan cung cấp nhiều dịch vụ khác nhau trên đường phố và những nơi công cộng với các công việc như đánh giày, rửa cửa kính ô tô, chạy việc vặt, phát tờ rơi, trông giữ tài sản và cung cấp các dịch vụ đường phố tại chỗ khác.', array['- Đảm bảo vật liệu cần thiết để thực hiện dịch vụ;', '- Tiếp cận khách hàng trên đường phố để cung cấp dịch vụ;', '- Làm sạch và đánh bóng giày;', '- Làm sạch và đánh bóng cửa kính ô tô;', '- Chạy việc vặt;', '- Hỗ trợ tài xế tìm bãi đỗ và đảm bảo xe không bị hư hỏng khi vắng mặt tài xế;', '- Phát tờ rơi và báo miễn phí;', '- Nhận thanh toán ngay.']::text[], array['- Người bảo vệ xe', '- Thợ rửa cửa kính ô tô', '- Người làm việc vặt', '- Người phát báo miễn phí', '- Người phát tờ rơi', '- Người đánh giày']::text[], array['- Nhân viên phục vụ ở các trạm dịch vụ - 5245', '- Người giao tờ rơi và báo - 9621']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1530) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9520', 'Người bán hàng rong trên đường phố (trừ đồ ăn) thường bán một số lượng hàng hóa nhất định (không bao gồm đồ ăn tiêu thụ ngay) trên đường phố và tại địa điểm công cộng như nhà ga, rạp hát, rạp chiếu phim.', array['- Mua hay nhận các mặt hàng để bán hoặc làm các mặt hàng đơn giản;', '- Xếp và dỡ giỏ, khay, xe đẩy, xe đạp, xe nâng tay hoặc các phương tiện khác để chuyên chở hàng hóa đến khu phố hay địa điểm công cộng như nhà ga, rạp phim;', '- Bày bán hàng hóa hay chào mời để thu hút khách;', '- Tiếp cận khách hàng tiềm năng trên đường phố hay đến tận nhà để chào bán sản phẩm;', '- Nhận thanh toán ngay.']::text[], array['- Người bán rong', '- Người bán báo', '- Người bán dạo']::text[], array['- Người bán hàng trong chợ - 5211', '- Người bán hàng trên phố - 5211', '- Người bán đồ ăn trên đường phố - 5212', '- Nhân viên bán hàng tận nhà - 5243', '- Người phát báo miễn phí - 9510', 'Ghi chú:', 'Những người bán thực phẩm tươi sống không dùng để tiêu thụ ngay (như trái cây, rau, thịt, sữa) được phân vào nhóm 5211 - Người bán hàng trong quầy hàng và tại chợ. Những người bán hàng rong trên đường và tại chợ với nhiều loại thức ăn chế biến sẵn và các mặt hàng thực phẩm để tiêu dùng ngay được phân vào nhóm 5246 - Nhân viên phục vụ đồ ăn uống. Những người bán thực phẩm và đồ uống trên đường phố và địa điểm công cộng từ xe đẩy, xe tải, khay hoặc giỏ được phân vào nhóm 5212 - Người bán đồ ăn trên đường phố. Những người bán hàng rong trên đường phố và địa điểm công cộng các mặt hàng phi thực phẩm (hoặc các mặt hàng thực phẩm không dễ hỏng được đóng gói sẵn như bánh kẹo) từ xe đẩy, xe tải, khay, giỏ được phân vào nhóm 9520 - Người bán hàng rong trên đường phố (trừ đồ ăn).']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1551) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9611', 'Người thu gom rác và tái chế thu gom, loại bỏ rác và các vật dụng để tái chế từ các tòa nhà, sân vườn, đường phố và những nơi khác.', array['Thu gom rác và các vật liệu có thể tái chế; đưa chúng vào trong các thùng, xe chở rác và tái chế;', 'Vận chuyển chúng trên các xe rác hay xe tái chế;', 'Nâng các thùng rác và đổ chúng vào xe tải hoặc các thùng chứa lớn hơn;', 'Dỡ rác và xe tải tái chế.']::text[], array['- Người hót rác', '- Người thu gom đồ tái chế', '- Người thu gom rác thải']::text[], array['- Người lái xe chở rác - 8332', '- Người nhặt rác - 9612']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1577) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9612', 'Người thu dọn, sắp xếp, phân loại rác xác định các đồ đã được loại bỏ thích hợp cho việc tái chế tại các bãi rác, xí nghiệp tái chế hoặc trong các tòa nhà, đường phố và những nơi công cộng khác.', array['- Thu thập đồ phế thải cho việc tái chế từ bãi rác, các hộ gia đình, trung tâm thương mại và công nghiệp hoặc từ những nơi công cộng như đường phố;', '- Phân loại bìa, giấy, thủy tinh, nhựa, nhôm hoặc các vật liệu tái chế khác;', '- Đặt các vật dụng và vật liệu có thể tái chế vào các thùng chứa được chỉ định để lưu trữ hoặc vận chuyển;', '- Nhận dạng và sắp xếp các đồ đạc, thiết bị, máy móc hoặc các bộ phận mà có thể được sửa chữa hoặc tái sử dụng;', '- Vận chuyển các mặt hàng có thể tái chế bằng tay hoặc sử dụng các phương tiện không có động cơ;', '- Bán vật liệu có thể tái chế hoặc tái sử dụng.']::text[], array['- Công nhân tái chế', '- Người buôn bán phế liệu', '- Người nhặt rác']::text[], array['- Người thu gom rác thải - 9611', '- Người quét dọn đường phố - 9613']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1591) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9613', 'Người quét dọn và lao động khác có liên quan quét dọn đường phố, công viên, sân bay, nhà ga và những nơi công cộng khác.', array['- Quét dọn đường phố, công viên, sân bay, nhà ga và những nơi công cộng tương tự;', '- Đập để loại bỏ bụi bẩn khỏi thảm bằng việc sử dụng que đập hoặc máy đập bụi;', '- Làm sạch rác, lá cây từ đường phố hoặc sân vườn.']::text[], array['- Người quét dọn công viên', '- Người quét dọn đường phố']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1607) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9621', 'Người đưa thư, người giao hàng và người khuân vác hành lý đi bộ mang và phân phát thư tín, bưu kiện và các vật dụng khác trong một cơ sở hay giữa các cơ sở, đến các hộ gia đình và nơi khác hoặc mang hành lý đặc biệt tại khách sạn, nhà ga và sân bay.', array['- Gửi thư, thông điệp, bưu phẩm và các vật phẩm khác trong nội bộ hoặc giữa các cơ sở hoặc nơi khác;', '- Giao hàng hóa khác nhau đến và đi từ các doanh nghiệp, cửa hàng, hộ gia đình và những nơi khác;', '- Mang và giao hành lý tại khách sạn, nhà ga, sân bay và địa điểm khác;', '- Tiếp nhận và đánh dấu hành lý bằng cách hoàn thành và đính kèm phiếu yêu cầu bồi thường;', '- Lên kế hoạch và chọn lộ trình hiệu quả nhất;', '- Phân loại các mặt hàng cần giao theo lộ trình giao hàng.']::text[], array['- Người khuân vác ở khách sạn', '- Người giao tờ rơi', '- Người khuân vác hành lý', '- Người đưa thư', '- Người giao báo']::text[], array['- Nhân viên vận chuyển thư - 4402', '- Nhân viên đưa thư - 4402']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1619) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9622', 'Người làm công việc lặt vặt dọn dẹp, quét sơn, bảo dưỡng tòa nhà, khuôn viên, các cơ sở vật chất khác và thực hiện các công việc sửa chữa đơn giản.', array['- Sửa chữa cửa sổ bị hỏng, các bức ngăn, cửa ra vào, hàng rào, vỉ nướng, bàn ăn ngoài trời, kệ, giá, tủ và các vật dụng khác;', '- Thay thế các đồ bị lỗi như bóng đèn;', '- Sửa chữa và sơn bề mặt bên trong và bên ngoài như tường, trần nhà và hàng rào;', '- Điều chỉnh cửa ra vào và cửa sổ; lắp tay vịn;', '- Thay thế các vòi nước hỏng;', '- Bốc dỡ than hoặc gỗ và đặt chúng vào các kho chứa của hộ gia đình hoặc các cơ sở riêng.']::text[], array['- Người sửa chữa vặt', '- Người làm công việc lặt vặt']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1637) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9623', 'Người đọc đồng hồ đo và người thu tiền từ máy bán hàng tự động cung cấp các máy bán hàng tự động và thu tiền từ máy bán hàng tự động hay từ đồng hồ tính cước phí đỗ xe và các hộp đựng tiền xu khác; đọc đồng hồ đo điện, ga, nước.', array['- Lấp đầy các khu vực lưu trữ của máy bán hàng tự động và thu gom tiền từ hộp đựng tiền của chúng;', '- Thu tiền từ máy thu tiền đậu xe và hộp đựng tiền tương tự;', '- Đọc đồng hồ đo điện, khí đốt, nước và ghi lại mức tiêu thụ;', '- Lưu giữ hồ sơ về hàng hóa được phân phối và số tiền thu được;', '- Tiến hành theo lộ trình lên sẵn để lập sổ ghi thông số đo của đồng hồ đo;', '- Xác minh các kết quả đọc trong trường hợp mức tiêu thụ có vẻ bất thường và ghi lại các lý do có thể gây ra biến động;', '- Kiểm tra đồng hồ để tìm các kết nối trái phép, các khuyết tật và hư hỏng như vòng đệm bị hỏng.']::text[], array['- Người đọc công tơ', '- Người thu tiền máy bán hàng tự động']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1649) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9624', 'Người thu gom nước và củi tiến hành gom nước và củi, đi bộ để vận chuyển chúng hoặc sử dụng xe kéo bằng tay hoặc động vật.', array['- Chặt và lấy củi từ rừng để bán tại chợ hoặc làm chất đốt tự tiêu dùng;', '- Vào rừng hoặc ra cánh đồng để nhặt những mẩu củi khô trên mặt đất và xếp chúng chất thành đống;', '- Chặt cành và thân cây mục nát bằng rìu hoặc cưa tay;', '- Buộc củi kiếm được thành bó nhỏ rồi mang hoặc vận chuyển chúng bằng xe đẩy đến chợ để bán hoặc cho các làng bản và hộ gia đình sử dụng;', '- Lấy nước từ giếng, sông, ao… để sử dụng trong gia đình;', '- Đựng nước vào các túi da, xô hay các vật chứa khác từ vòi nước, sông, ao, giếng rồi phân phối nước đến nơi làm việc, nhà của khách hàng hoặc hộ gia đình để uống, vệ sinh đường ống thoát nước hay lưu trữ trong bể chứa.']::text[], array['- Người thu gom củi', '- Người thu gom nước']::text[], '{}'::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1662) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
insert into public.occupation_descriptions (code, description, main_tasks, examples, exclusions, skill_note, source_file, source_paragraph) values ('9629', 'Lao động giản đơn khác chưa được phân vào đâu chẳng hạn như những người làm việc liên quan đến phát và thu vé vào cổng, gửi xe, cung cấp vật dụng cá nhân cho khách hàng và hỗ trợ khách tại các sự kiện giải trí.', array['- Bán vé vào cửa và thẻ ra vào cho khách tại các sự kiện giải trí hay thu vé, thẻ ra vào và phù hiệu;', '- Kiểm tra vé hay thẻ ra vào để xác minh tính xác thực bằng cách sử dụng tiêu chí như màu sắc hay ngày cấp;', '- Hướng dẫn khách lối ra hoặc cung cấp chỉ dẫn hay hỗ trợ trong trường hợp khẩn cấp;', '- Hướng dẫn khách đến nhà vệ sinh, khán đài hay chỗ gọi điện thoại;', '- Hướng dẫn lái xe đến chỗ đỗ xe;', '- Tuần tra khu vực đỗ xe đề phòng phá hoại hay trộm cắp tài sản, phương tiện;', '- Tính phí gửi xe và thu phí từ khách hàng;', '- Hướng dẫn các tiện nghi trong phòng thay đồ, không gian thay đồ hoặc tủ đựng quần áo cho khách ở các cơ sở thể thao, bơi lội, spa.']::text[], array['- Người phục vụ áo choàng', '- Người phục vụ hội chợ', '- Người trông xe', '- Người soát vé', '- Giám thị']::text[], array['- Người trông bãi đỗ xe - 8322']::text[], null, '2020_1151 + 1152_34-2020-QĐ-TTg.doc', 1674) on conflict (code) do update set description = excluded.description, main_tasks = excluded.main_tasks, examples = excluded.examples, exclusions = excluded.exclusions, skill_note = excluded.skill_note, source_file = excluded.source_file, source_paragraph = excluded.source_paragraph;
